const MAX_INBOUND_TEXT = 100_000;
const MAX_ERROR_TEXT = 2_000;
const DELIVERY_PROCESSING_STALE_MS = 60_000;
// Reactions can beat the transaction that persists a just-sent provider
// message link. Keep that narrow gap durable, but never retain an unbound
// reaction indefinitely or let it enter the ordinary inbound-message FIFO.
const REACTION_LINK_RETRY_DELAY_MS = 250;
const REACTION_LINK_MAX_DELAY_MS = 5_000;
const REACTION_LINK_MAX_ATTEMPTS = 20;
const REACTION_LINK_MAX_AGE_MS = 2 * 60_000;
// A Discord root mention is durably staged before the adapter creates its
// provider thread. Give the bounded provider retry loop ample time to finish;
// if the process disappears, the delivery worker verifies that thread over
// Discord's read-only API before it permits any Paperclip task mutation.
const DISCORD_ROOT_THREAD_CONFIRMATION_DELAY_MS = 5 * 60_000;
const DELIVERY_LEASE_TTL_MS = 90_000;
const DELIVERY_DRAIN_LIMIT = 100;
const SLACK_COMMAND_POST_STALE_MS = 60_000;
const SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS = 5 * 60_000;
const SLACK_COMMAND_ADMISSION_STALE_MS = 60_000;
const PROVIDER_EFFECT_STALE_MS = 60_000;
const SLACK_FILE_RECEIPT_MAX_AGE_MS = 24 * 60 * 60_000;
const SLACK_FILE_RECEIPT_MAX_ATTEMPTS = 12;
const SLACK_FILE_RECEIPT_STALE_MS = 60_000;
const ORPHAN_FOLLOW_UP_GRACE_MS = 5_000;
const ORPHAN_FOLLOW_UP_MAX_ATTEMPTS = 12;
const CREDENTIAL_MUTATION_LEASE_TTL_MS = 90_000;
const PUBLICATION_ENDPOINT_CONCURRENCY = 4;
const CREDENTIAL_MUTATION_LEASE_WAIT_MS = 10_000;
const CREDENTIAL_MUTATION_LEASE_POLL_MS = 25;
const DISCORD_GATEWAY_LEASE_KEY = "discord_gateway_runtime";
const DISCORD_GATEWAY_LEASE_TTL_MS = 15_000;
const DISCORD_GATEWAY_LEASE_WAIT_MS = 20_000;
const DISCORD_GATEWAY_LEASE_POLL_MS = 100;
const PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS = 25_000;
const GITHUB_WEBHOOK_RESPONSE_BUDGET_MS = 8_000;
const CONFIRMATION_WAKEUP_RETRY_BACKOFF_MS = 30_000;
// Providers can deliver adjacent callbacks on separate HTTP requests out of
// order. Hold the first callback briefly so a rapid burst can be sorted by the
// provider's own timestamp and sequence before any run is started.
const INGRESS_REORDER_WINDOW_MS: Partial<Record<ChatProvider, number>> = {
  // Both providers deliver adjacent comments as independent HTTP requests and
  // do not guarantee callback arrival order. A fixed, non-sliding window lets
  // the durable drain sort a short burst before the first agent wake starts.
  slack: 750,
  github: 750,
  discord: 750,
  // Bot Framework can dispatch adjacent activities over independent requests.
  // Keep Teams bursts inside the same provider-timestamp ordering boundary as
  // Slack and GitHub so a faster later reply cannot wake the agent first.
  "microsoft-teams": 750,
  // Telegram's webhook max_connections setting permits concurrent delivery.
  // Its message timestamp has only one-second resolution, so the drain also
  // uses message_id/update_id below to order callbacks within this fixed,
  // non-sliding window without serializing separate chats.
  telegram: 750,
};

type EndpointRow = typeof chatEndpoints.$inferSelect;
type ResourceRow = typeof chatEndpointResources.$inferSelect;
type DbTransaction = Parameters<Parameters<Db["transaction"]>[0]>[0];
type DbOrTransaction = Db | DbTransaction;
type SlackCallbackSurface = keyof ChatEndpointCallbackSurfaces;
type SlackCallbackObservation = { url: string; observedAt: string };
type InternalSetupState = ChatEndpointSetupState & {
  runtimeGeneration?: number;
  slackCallbackSurfaces?: Partial<
    Record<SlackCallbackSurface, SlackCallbackObservation>
  >;
};
type RuntimeContext = {
  credentialFingerprint: string;
  discordGatewayEventQueue?: Promise<void>;
  discordGatewaySequence?: number;
  discordGatewayOwned?: boolean;
  /** Cache identity only; durable command admission rechecks ownership. */
  discordCommandId?: string;
  endpointRuntime?: ChatSdkEndpointRuntime;
  generation: number;
  localEpoch: number;
  version: string;
};
type LifecycleRuntimeFence = Pick<
  RuntimeContext,
  "credentialFingerprint" | "generation"
>;
type InboundRuntimeContext = LifecycleRuntimeFence &
  Pick<RuntimeContext, "discordGatewayOwned" | "endpointRuntime">;
type VerifiedProviderIdentity = {
  providerAccountId?: string | null;
  providerAccountLabel?: string | null;
  botExternalId?: string | null;
  botUsername?: string | null;
  botLabel?: string | null;
};

const GITHUB_RECOVERY_STATE_KEY = "paperclip:github-webhook-recovery:v1";
const GITHUB_RECOVERY_INTERVAL_MS = 60_000;
const GITHUB_RECOVERY_WINDOW_MS = 60 * 60_000;
const GITHUB_RECOVERY_SCAN_LEASE_MS = 5 * 60_000;
type GitHubRecoveryWindow = LifecycleRuntimeFence & {
  appId: string;
  webhookUrl: string;
  floor: string;
  nextScanAt: string;
};
type GitHubRecoveryReceipt = GitHubRecoveryWindow & {
  original: GitHubAppWebhookDeliveryDetail;
};

function githubRecoveryWindow(value: unknown): GitHubRecoveryWindow | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const item = value as GitHubRecoveryWindow;
  return Number.isSafeInteger(item.generation) &&
    item.generation >= 0 &&
    typeof item.credentialFingerprint === "string" &&
    /^[a-f0-9]{64}$/.test(item.credentialFingerprint) &&
    typeof item.appId === "string" &&
    /^\d+$/.test(item.appId) &&
    typeof item.webhookUrl === "string" &&
    typeof item.floor === "string" &&
    Number.isFinite(Date.parse(item.floor)) &&
    typeof item.nextScanAt === "string" &&
    Number.isFinite(Date.parse(item.nextScanAt))
    ? item
    : null;
}

function runtimeGeneration(setup: ChatEndpointSetupState): number {
  const value = Number((setup as InternalSetupState).runtimeGeneration ?? 0);
  return Number.isSafeInteger(value) && value >= 0 ? value : 0;
}

function credentialFingerprint(refs: ToolCredentialSecretRef[]): string {
  const stable = refs
    .map((ref) => ({
      configPath: ref.configPath,
      secretId: ref.secretId,
      versionSelector: ref.versionSelector ?? "latest",
    }))
    .sort((left, right) =>
      `${left.configPath}:${left.secretId}:${left.versionSelector}`.localeCompare(
        `${right.configPath}:${right.secretId}:${right.versionSelector}`,
      ),
    );
  return createHash("sha256").update(JSON.stringify(stable)).digest("hex");
}

const ATTACHMENT_FAILURE_NOTICE_PREFIX = "attachment-failure-notice:";

function attachmentFailureNoticeFence(
  idempotencyKey: string,
): LifecycleRuntimeFence | null {
  const match =
    /^attachment-failure-notice:[0-9a-f-]{36}:(\d+):([0-9a-f]{64})$/i.exec(
      idempotencyKey,
    );
  if (!match) return null;
  const generation = Number(match[1]);
  if (!Number.isSafeInteger(generation) || generation < 0) return null;
  return { generation, credentialFingerprint: match[2]!.toLowerCase() };
}

function definiteAttachmentProviderRejection(error: unknown): boolean {
  const pending: Array<{ depth: number; value: unknown }> = [
    { depth: 0, value: error },
  ];
  const seen = new Set<object>();
  const statuses: number[] = [];
  const names: string[] = [];
  const codes: string[] = [];
  while (pending.length > 0) {
    const current = pending.shift();
    if (
      !current ||
      current.depth > 4 ||
      !current.value ||
      typeof current.value !== "object" ||
      seen.has(current.value)
    ) {
      continue;
    }
    seen.add(current.value);
    const record = current.value as {
      cause?: unknown;
      code?: unknown;
      details?: { code?: unknown; providerStatus?: unknown };
      innerHttpError?: { statusCode?: unknown };
      name?: unknown;
      original?: unknown;
      originalError?: unknown;
      response?: { status?: unknown };
      status?: unknown;
      statusCode?: unknown;
    };
    for (const status of [
      record.status,
      record.statusCode,
      record.response?.status,
      record.details?.providerStatus,
      record.innerHttpError?.statusCode,
    ]) {
      if (typeof status === "number" && Number.isInteger(status)) {
        statuses.push(status);
      }
    }
    if (typeof record.name === "string") names.push(record.name);
    for (const code of [record.code, record.details?.code]) {
      if (typeof code === "string") codes.push(code);
    }
    for (const nested of [
      record.cause,
      record.original,
      record.originalError,
    ]) {
      pending.push({ depth: current.depth + 1, value: nested });
    }
  }
  if (
    names.some((name) =>
      ["ValidationError", "NotImplementedError"].includes(name),
    ) ||
    codes.some((code) =>
      [
        "CHAT_ADAPTER_COMPATIBILITY_ERROR",
        "CHAT_PROVIDER_PRETRANSPORT_REJECTED",
        "NOT_IMPLEMENTED",
        "VALIDATION_ERROR",
      ].includes(code),
    )
  ) {
    return false;
  }
  // Slack's Web API can reject a file operation with `ok: false` in an HTTP
  // 200 response. The SDK's structured platform-error code is still a
  // definitive provider rejection; the main disposition classifier has
  // already excluded auth, destination, and rate-limit outcomes.
  if (codes.includes("slack_webapi_platform_error")) return true;
  return statuses.some(
    (status) =>
      status >= 400 &&
      status < 500 &&
      ![401, 403, 404, 410, 429].includes(status),
  );
}

function attachmentFailureKind(
  payload: SafeChatPublicationPayload,
):
  | { kind: "generated_response"; provider: "discord" | "telegram" }
  | { kind: "selected_file"; provider: null }
  | null {
  if (payload.transportPart?.mode === "discord_markdown_attachment") {
    return { kind: "generated_response", provider: "discord" };
  }
  if (payload.transportPart?.mode === "telegram_markdown_attachment") {
    return { kind: "generated_response", provider: "telegram" };
  }
  if (payload.attachmentIds?.length) {
    return { kind: "selected_file", provider: null };
  }
  return null;
}
type ConversationRow = typeof chatConversations.$inferSelect;
type DeliveryRow = typeof chatDeliveries.$inferSelect;
type LiveInboundMessage = {
  endpoint: EndpointRow;
  message: Message;
  receiptReactionSupported: boolean;
  runtimeContext?: InboundRuntimeContext;
  thread: Thread;
  trigger: ChatSdkMessageCallbackEvent["trigger"];
};
type ProviderEffectTarget = {
  post: Thread["post"];
  postEphemeral?: Thread["postEphemeral"];
};
type ProviderEffectPayload = {
  version: 1;
  effect: "thread_message" | "ephemeral_message" | "telegram_callback_notice";
  telegramCallback?: TelegramCallbackReceipt;
  telegramAuthorizationSha256?: string;
  authorizationMode?: "principal" | "safe_notice";
  threadId: string;
  userId?: string;
  text: string;
  fallbackText?: string;
  settleDelivery: boolean;
  completeConversationId?: string;
  resourceId?: string;
  runtimeGeneration: number;
  credentialFingerprint: string;
};

type ReceiptReactionPayload = {
  version: 1;
  operation: "add" | "remove";
  threadId: string;
  messageId: string;
  reaction: "eyes";
  runtimeGeneration: number;
  credentialFingerprint: string;
  githubReceipt?: GitHubReceiptIdentity;
};

type SlackFileUploadReceiptPayload = {
  version: 1;
  publicationId: string;
  publicationAttempt: number;
  threadId: string;
  fileIds: string[];
  botExternalId: string;
  runtimeGeneration: number;
  credentialFingerprint: string;
};

function slackFileUploadReceiptPayload(
  payload: Record<string, unknown>,
): SlackFileUploadReceiptPayload | null {
  if (
    payload.version !== 1 ||
    typeof payload.publicationId !== "string" ||
    !isUuidLike(payload.publicationId) ||
    typeof payload.publicationAttempt !== "number" ||
    !Number.isSafeInteger(payload.publicationAttempt) ||
    payload.publicationAttempt < 1 ||
    typeof payload.threadId !== "string" ||
    payload.threadId.length < 1 ||
    payload.threadId.length > 2_048 ||
    !payload.threadId.startsWith("slack:") ||
    typeof payload.botExternalId !== "string" ||
    payload.botExternalId.length < 1 ||
    payload.botExternalId.length > 255 ||
    typeof payload.runtimeGeneration !== "number" ||
    !Number.isSafeInteger(payload.runtimeGeneration) ||
    payload.runtimeGeneration < 0 ||
    typeof payload.credentialFingerprint !== "string" ||
    !/^[a-f0-9]{64}$/.test(payload.credentialFingerprint) ||
    !Array.isArray(payload.fileIds) ||
    payload.fileIds.length < 1 ||
    payload.fileIds.length > 20 ||
    payload.fileIds.some(
      (fileId) =>
        typeof fileId !== "string" || !/^F[A-Z0-9]{1,254}$/.test(fileId),
    ) ||
    new Set(payload.fileIds).size !== payload.fileIds.length
  ) {
    return null;
  }
  return payload as SlackFileUploadReceiptPayload;
}

function operatorConfirmedSlackFileReceipt(
  result: Record<string, unknown> | null,
  payload: SlackFileUploadReceiptPayload,
): boolean {
  return (
    result?.operatorConfirmedPublicationId === payload.publicationId &&
    result.operatorConfirmedAttempt === payload.publicationAttempt &&
    typeof result.operatorConfirmedAt === "string" &&
    Number.isFinite(Date.parse(result.operatorConfirmedAt))
  );
}

function sameSlackFileUploadReceipt(
  left: SlackFileUploadReceiptPayload,
  right: SlackFileUploadReceiptPayload,
): boolean {
  return (
    left.publicationId === right.publicationId &&
    left.publicationAttempt === right.publicationAttempt &&
    left.threadId === right.threadId &&
    left.botExternalId === right.botExternalId &&
    left.runtimeGeneration === right.runtimeGeneration &&
    left.credentialFingerprint === right.credentialFingerprint &&
    left.fileIds.length === right.fileIds.length &&
    left.fileIds.every((fileId, index) => fileId === right.fileIds[index])
  );
}

type GitHubWebhookIngressPayload = {
  version: 1;
  body: string;
  bodySha256: string;
  contentType: string;
  deliveryId: string;
  eventType: string;
  runtimeGeneration: number;
  credentialFingerprint: string;
};

type RedactedGitHubWebhookIngressPayload = Omit<
  GitHubWebhookIngressPayload,
  "body" | "contentType"
> & {
  redacted: true;
};

type TelegramMaintenancePayload = {
  version: 1;
  operation: "register_commands" | "remove_endpoint" | "stop_subscription";
  runtimeGeneration: number;
  credentialFingerprint: string;
  webhookUrlSha256?: string;
  botUserId?: string;
};

function telegramMaintenancePayload(
  payload: Record<string, unknown>,
): TelegramMaintenancePayload | null {
  if (
    payload.version !== 1 ||
    (payload.operation !== "register_commands" &&
      payload.operation !== "remove_endpoint" &&
      payload.operation !== "stop_subscription") ||
    typeof payload.runtimeGeneration !== "number" ||
    !Number.isSafeInteger(payload.runtimeGeneration) ||
    typeof payload.credentialFingerprint !== "string" ||
    (payload.operation === "stop_subscription" &&
      (typeof payload.webhookUrlSha256 !== "string" ||
        !/^[a-f0-9]{64}$/.test(payload.webhookUrlSha256) ||
        typeof payload.botUserId !== "string" ||
        !/^[1-9][0-9]{0,15}$/.test(payload.botUserId)))
  ) {
    return null;
  }
  return payload as TelegramMaintenancePayload;
}

function receiptReactionPayload(
  payload: Record<string, unknown>,
): ReceiptReactionPayload | null {
  const operation = payload.operation ?? "add";
  if (
    payload.version !== 1 ||
    (operation !== "add" && operation !== "remove") ||
    typeof payload.threadId !== "string" ||
    !payload.threadId ||
    typeof payload.messageId !== "string" ||
    !payload.messageId ||
    payload.reaction !== "eyes" ||
    typeof payload.runtimeGeneration !== "number" ||
    !Number.isSafeInteger(payload.runtimeGeneration) ||
    typeof payload.credentialFingerprint !== "string" ||
    (payload.githubReceipt !== undefined &&
      !parseGitHubReceiptIdentity(payload.githubReceipt))
  ) {
    return null;
  }
  return { ...payload, operation } as ReceiptReactionPayload;
}

function githubWebhookIngressPayload(
  payload: Record<string, unknown>,
): GitHubWebhookIngressPayload | null {
  if (
    payload.version !== 1 ||
    typeof payload.body !== "string" ||
    typeof payload.bodySha256 !== "string" ||
    !/^[a-f0-9]{64}$/.test(payload.bodySha256) ||
    typeof payload.contentType !== "string" ||
    typeof payload.deliveryId !== "string" ||
    !payload.deliveryId ||
    typeof payload.eventType !== "string" ||
    !payload.eventType ||
    typeof payload.runtimeGeneration !== "number" ||
    !Number.isSafeInteger(payload.runtimeGeneration) ||
    typeof payload.credentialFingerprint !== "string"
  ) {
    return null;
  }
  if (
    createHash("sha256").update(payload.body).digest("hex") !==
    payload.bodySha256
  ) {
    return null;
  }
  return payload as GitHubWebhookIngressPayload;
}

function redactedGitHubWebhookIngressPayload(
  payload: GitHubWebhookIngressPayload,
): RedactedGitHubWebhookIngressPayload {
  return {
    version: 1,
    bodySha256: payload.bodySha256,
    deliveryId: payload.deliveryId,
    eventType: payload.eventType,
    runtimeGeneration: payload.runtimeGeneration,
    credentialFingerprint: payload.credentialFingerprint,
    redacted: true,
  };
}

function isSlackReceiptReactionAlreadyApplied(error: unknown): boolean {
  const pending: Array<{ depth: number; value: unknown }> = [
    { depth: 0, value: error },
  ];
  const seen = new Set<object>();
  while (pending.length > 0) {
    const current = pending.shift();
    if (
      !current ||
      current.depth > 4 ||
      !current.value ||
      typeof current.value !== "object" ||
      seen.has(current.value)
    ) {
      continue;
    }
    seen.add(current.value);
    const record = current.value as {
      cause?: unknown;
      code?: unknown;
      data?: { error?: unknown };
      original?: unknown;
      originalError?: unknown;
    };
    if (
      record.code === "already_reacted" ||
      record.data?.error === "already_reacted"
    ) {
      return true;
    }
    for (const value of [record.cause, record.original, record.originalError]) {
      pending.push({ depth: current.depth + 1, value });
    }
  }
  return false;
}

function providerEffectPayload(
  payload: Record<string, unknown>,
): ProviderEffectPayload | null {
  if (
    payload.version !== 1 ||
    (payload.effect !== "thread_message" &&
      payload.effect !== "ephemeral_message" &&
      payload.effect !== "telegram_callback_notice") ||
    typeof payload.threadId !== "string" ||
    !payload.threadId ||
    typeof payload.text !== "string" ||
    !payload.text ||
    typeof payload.settleDelivery !== "boolean" ||
    typeof payload.runtimeGeneration !== "number" ||
    !Number.isSafeInteger(payload.runtimeGeneration) ||
    typeof payload.credentialFingerprint !== "string"
  ) {
    return null;
  }
  if (
    payload.effect === "ephemeral_message" &&
    (typeof payload.userId !== "string" || !payload.userId)
  ) {
    return null;
  }
  for (const key of [
    "authorizationMode",
    "userId",
    "fallbackText",
    "completeConversationId",
    "resourceId",
  ] as const) {
    const value = payload[key];
    if (value !== undefined && (typeof value !== "string" || !value)) {
      return null;
    }
  }
  if (
    payload.authorizationMode !== undefined &&
    payload.authorizationMode !== "principal" &&
    payload.authorizationMode !== "safe_notice"
  ) {
    return null;
  }
  if (payload.effect === "telegram_callback_notice") {
    const receipt = parseTelegramCallbackReceipt(payload.telegramCallback);
    if (
      !receipt ||
      payload.authorizationMode !== "safe_notice" ||
      payload.text !== TELEGRAM_PRIVATE_ACTION_UNAVAILABLE ||
      payload.threadId !== telegramCallbackThreadId(receipt) ||
      payload.userId !== receipt.receiverUserId ||
      payload.settleDelivery !== false ||
      payload.fallbackText !== undefined ||
      payload.completeConversationId !== undefined ||
      typeof payload.telegramAuthorizationSha256 !== "string" ||
      !/^[a-f0-9]{64}$/.test(payload.telegramAuthorizationSha256)
    )
      return null;
  } else if (
    payload.telegramCallback !== undefined ||
    payload.telegramAuthorizationSha256 !== undefined
  )
    return null;
  return payload as ProviderEffectPayload;
}

export interface ChatChannelServiceOptions {
  /**
   * Provider webhooks await only the durable ingress write, then finish task
   * processing outside the provider response budget. Tests may leave this off
   * when they need direct callback assertions.
   */
  deferWebhookProcessing?: boolean;
  /** Test override for GitHub's end-to-end webhook response budget. */
  githubWebhookResponseBudgetMs?: number;
  /** Testable boundary after reading a GitHub webhook and before authentication. */
  githubWebhookAuthenticationBarrier?: () => Promise<void>;
  /** Testable boundary before a durable GitHub receipt re-enters provider handling. */
  githubWebhookReplayBarrier?: () => Promise<void>;
  /** Test override for the credential-mutation lease renewal cadence. */
  credentialMutationLeaseRenewalIntervalMs?: number;
  /** Narrow fault-injection boundary for credential-lease ownership checks. */
  renewCredentialMutationLease?: (input: {
    companyId: string;
    endpointId: string;
    expiresAt: Date;
    leaseKey: string;
    token: string;
  }) => Promise<boolean>;
  fetch?: typeof globalThis.fetch;
  /** Test-only private upload transport; production retains guarded egress. */
  teamsFileUploadRequest?: TeamsFileTransferOptions["uploadRequest"];
  heartbeat: IssueAssignmentWakeupDeps & {
    cancelRun?: (
      runId: string,
      reason?: string,
      options?: {
        errorCode?: string;
        eventMessage?: string;
        eventPayload?: Record<string, unknown>;
      },
    ) => Promise<unknown>;
  };
  /** Production bridge for resuming a native run that owns the question. */
  resolveNativeQuestion?: QuestionResponseDeliveryServiceOptions["resolveNativeQuestion"];
  publicBaseUrl?: string | null;
  /** Optional verified ingress origin; never used for board or identity links. */
  webhookPublicBaseUrl?: string | null;
  runtime?: ChatSdkRuntime;
  /** Testable scheduler hook; production defaults to the next event-loop turn. */
  scheduleDeferredWork?: (task: () => void) => void;
  /** Test boundary after selecting due Slack status work and before claiming. */
  slackSessionSyncSelectionBarrier?: () => Promise<void>;
  /** Narrow fault-injection boundary for the one-time setup-secret audit. */
  setupSecretActivityLogger?: typeof logActivity;
  /** Testable barrier after fail-closed state and before secret-ref mutation. */
  setupSecretCredentialPersistBarrier?: () => Promise<void>;
  /** Testable boundary immediately before setup-secret's final lease check. */
  setupSecretFinalOwnershipBarrier?: () => Promise<void>;
  /** Testable boundary after setup qualification and before activation. */
  setupTestActivationBarrier?: () => Promise<void>;
  /** Testable boundary after identity preflight and before its database claim. */
  nativeBotIdentityClaimBarrier?: () => Promise<void>;
  /** Testable crash boundary after interaction commit and before chat settlement. */
  confirmationResolutionPersistBarrier?: () => Promise<void>;
  /** Testable boundary after a question callback claim and before resolution. */
  questionResolutionPersistBarrier?: () => Promise<void>;
  /** Testable boundary before the final question-form opener authorization fence. */
  questionFormOpenAuthorizationBarrier?: () => Promise<void>;
  /** Testable boundary immediately before the final inbound reach row lock. */
  reachAuthorizationBarrier?: () => Promise<void>;
  /** Testable boundary after receipt-reaction durability and before transport. */
  receiptReactionTransportBarrier?: () => Promise<void>;
  /** Testable boundary between the first reaction-link and streaming lookups. */
  reactionLinkPreflightBarrier?: () => Promise<void>;
  /** Testable boundary after replay locks its endpoint and before conversation. */
  reactionReplayEndpointLockBarrier?: () => Promise<void>;
  /** Testable boundary after replay locks its conversation. */
  reactionReplayConversationLockBarrier?: () => Promise<void>;
  /** Narrow fault-injection boundary before durable publication preparation. */
  publicationTransportPreparationBarrier?: (input: {
    publicationId: string;
  }) => Promise<void>;
  /** Test override for the conversation-delivery lease renewal cadence. */
  conversationLeaseRenewalIntervalMs?: number;
  /** Narrow fault-injection boundary for renewing a conversation lease. */
  renewConversationDeliveryLease?: (input: {
    endpointId: string;
    leaseKey: string;
    token: string;
    expiresAt: Date;
  }) => Promise<boolean>;
  /** Test override for Discord Gateway leader-lease expiry. */
  discordGatewayLeaseTtlMs?: number;
  /** Test override for Discord Gateway leader-lease renewal cadence. */
  discordGatewayLeaseRenewalIntervalMs?: number;
  /** Test override for lifecycle handoff while another replica is stopping. */
  discordGatewayLeaseWaitMs?: number;
  /** Narrow fault-injection boundary before renewing a Discord Gateway lease. */
  renewDiscordGatewayLease?: (input: {
    companyId: string;
    credentialFingerprint: string;
    endpointId: string;
    expiresAt: Date;
    generation: number;
    leaseKey: string;
    token: string;
  }) => Promise<boolean>;
  /** Testable barrier inside the serialized Discord Gateway event drain. */
  discordGatewayEventBarrier?: (
    event: DiscordGatewayCallbackEvent,
  ) => Promise<void>;
  /** Testable boundary after initial Gateway ownership and before admission. */
  discordGatewayMessageAdmissionBarrier?: () => Promise<void>;
  /** Testable barrier before the credential-leased Discord root creation. */
  discordRootThreadTransportBarrier?: () => Promise<void>;
  /** Testable boundary after a Slack task-admission worker claims its attempt. */
  slackTaskAdmissionClaimBarrier?: (input: {
    actionId: string;
    claimId: string;
  }) => Promise<void>;
  storage?: StorageService;
}

interface CredentialMutationLeaseGuard {
  assertOwned(database?: DbOrTransaction): Promise<void>;
}

interface CredentialMutationLeaseCompletion<T> {
  beforeFinalOwnershipCheck?: () => Promise<void>;
  recoverCommittedResultAfterLeaseLoss?: (
    result: T,
    error: Error,
  ) => Promise<boolean>;
}

type DiscordGatewayOwnership = {
  companyId: string;
  context: RuntimeContext;
  endpointId: string;
  expiresAt: Date;
  leaseKey: typeof DISCORD_GATEWAY_LEASE_KEY;
  renewTimer: ReturnType<typeof setInterval> | null;
  renewal: Promise<void> | null;
  stopPromise: Promise<void> | null;
  stopping: boolean;
  token: string;
};

function iso(value: Date | null | undefined): string | null {
  return value ? value.toISOString() : null;
}

function providerResourceType(
  provider: ChatProvider,
  surfaceKind: ChatSurfaceKind,
): string {
  if (surfaceKind === "direct_message") return "direct_message";
  if (provider === "github") return "repository";
  if (provider === "discord") return "channel";
  if (provider === "microsoft-teams")
    return surfaceKind === "linear_group" ? "group_chat" : "channel";
  // Telegram topics are task/thread boundaries inside one group resource. The
  // operator grants access to the chat once rather than having to rediscover
  // and enable every topic independently.
  if (provider === "telegram") return "chat";
  return "channel";
}

type ChatSurfaceKind = "direct_message" | "linear_group" | "native_thread";


function sameTeamsThreadIdentity(left: string, right: string): boolean {
  const leftConversationId = teamsConversationId(left);
  const rightConversationId = teamsConversationId(right);
  return (
    leftConversationId !== null &&
    rightConversationId !== null &&
    leftConversationId === rightConversationId
  );
}


function durableExternalThreadIdentity(threadId: string): string {
  return canonicalTeamsThreadId(threadId) ?? threadId;
}


function microsoftTeamsServiceUrl(raw: unknown): string | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const value = (raw as { serviceUrl?: unknown }).serviceUrl;
  return typeof value === "string" && value ? value : null;
}

function baseTeamsConversationId(value: string): string {
  return value.replace(/;messageid=[^;]+/i, "");
}

function teamsThreadRootMessageId(threadId: string): string | null {
  const conversationId = teamsConversationId(threadId);
  if (!conversationId) return null;
  return /;messageid=([^;]+)/i.exec(conversationId)?.[1] ?? null;
}

function canonicalProviderResourceId(
  provider: ChatProvider,
  thread: Pick<Thread, "channelId" | "id">,
): string {
  if (provider === "slack") return thread.channelId.replace(/^slack:/, "");
  if (provider === "github")
    return thread.channelId.replace(/^github:/, "").toLowerCase();
  if (provider === "discord") {
    const parts = thread.channelId.split(":");
    return parts[2] ?? thread.channelId;
  }
  if (provider === "microsoft-teams") {
    const conversationId =
      teamsConversationId(thread.channelId) ?? teamsConversationId(thread.id);
    return conversationId
      ? baseTeamsConversationId(conversationId)
      : baseTeamsConversationId(thread.channelId);
  }
  if (provider === "telegram")
    return thread.channelId.replace(/^telegram:/, "");
  return thread.channelId;
}

function slackResourceLabelIsFallback(
  providerResourceId: string,
  label: string,
): boolean {
  const candidate = label.trim();
  return (
    candidate === providerResourceId ||
    candidate === `slack:${providerResourceId}`
  );
}

function telegramResourceLabelIsFallback(
  providerResourceId: string,
  label: string,
): boolean {
  const candidate = label.trim();
  return (
    candidate === providerResourceId ||
    candidate === `telegram:${providerResourceId}`
  );
}

function providerResourceLabelFromThread(
  provider: ChatProvider,
  thread: Pick<Thread, "channelId" | "id" | "channel">,
): { label: string; fallback: boolean } {
  const providerResourceId = canonicalProviderResourceId(provider, thread);
  const candidate = thread.channel.name?.trim();
  if (!candidate) return { label: providerResourceId, fallback: true };
  if (
    (provider === "slack" &&
      slackResourceLabelIsFallback(providerResourceId, candidate)) ||
    (provider === "telegram" &&
      telegramResourceLabelIsFallback(providerResourceId, candidate))
  ) {
    return { label: providerResourceId, fallback: true };
  }
  return { label: candidate, fallback: false };
}

/**
 * Native channel threads keep one issue forever. Linear surfaces instead
 * advance through Paperclip task generations because their provider id is
 * reused after a task completes or the user explicitly starts a new task.
 */
function chatSurfaceKind(
  provider: ChatProvider,
  thread: Thread,
): ChatSurfaceKind {
  if (thread.isDM) return "direct_message";
  if (provider === "telegram") {
    return /^telegram:[^:]+:[^:]+$/.test(thread.id)
      ? "native_thread"
      : "linear_group";
  }
  if (provider === "microsoft-teams") {
    const conversationId = teamsConversationId(thread.id);
    return conversationId?.includes(";messageid=")
      ? "native_thread"
      : "linear_group";
  }
  return "native_thread";
}

/**
 * Teams group chats are admitted as a class: installation at the provider and
 * the endpoint's group-chat toggle are the two gates the operator can
 * actually control. Teams channels, and every other non-DM destination,
 * retain the explicit per-resource enablement gate shown in Settings.
 */
function nonDirectDestinationAllowed(
  endpoint: EndpointRow,
  resource: ResourceRow | null | undefined,
): boolean {
  if (!resource || resource.availability !== "available") return false;
  if (
    endpoint.provider === "microsoft-teams" &&
    resource.type === "group_chat"
  ) {
    return endpoint.allowGroupChats;
  }
  return resource.enabled;
}

function linearControlCommand(text: string): "new" | "close" | "status" | null {
  const match = /^\/(new|close|status)(?:@[\w.-]+)?\s*$/i.exec(text.trim());
  return (
    (match?.[1]?.toLowerCase() as "new" | "close" | "status" | undefined) ??
    null
  );
}

function telegramGuidanceCommand(
  text: string,
): "start" | "task" | "unknown" | null {
  const match = /^\/([a-z][\w-]*)(?:@[\w.-]+)?(?:\s|$)/i.exec(text.trim());
  const command = match?.[1]?.toLowerCase();
  if (
    !command ||
    command === "new" ||
    command === "close" ||
    command === "status"
  )
    return null;
  if (command === "start") return "start";
  if (command === "task") return "task";
  return "unknown";
}

function stableExternalPrincipalId(
  provider: ChatProvider,
  author: Author,
  raw?: unknown,
): string {
  if (provider !== "microsoft-teams" || !raw || typeof raw !== "object")
    return author.userId;
  const from = (raw as { from?: unknown }).from;
  if (!from || typeof from !== "object") return author.userId;
  const aadObjectId = (from as { aadObjectId?: unknown }).aadObjectId;
  return normalizeMicrosoftTeamsExternalPrincipalId(aadObjectId, author.userId);
}

function safeTitle(text: string, fallback: string): string {
  const line = text
    .replace(/<@[A-Z0-9]+>/gi, "")
    .replace(/@[\w.-]+(?:\[bot\])?/gi, "")
    .trim()
    .split(/\r?\n/)[0];
  return (line || fallback).slice(0, 160);
}

function hasMeaningfulSlackMentionRequest(text: string): boolean {
  const withoutMentions = text
    .replace(/<@[^>|\s]+(?:\|[^>]+)?>/gi, " ")
    .replace(/(^|\s)@[A-Z0-9._-]+(?=\s|$)/gi, " ");
  return withoutMentions.replace(/[\s\p{P}\p{S}\p{Cf}]/gu, "").length > 0;
}

type SlackSlashTaskRecoveryPayload = {
  channelId: string;
  command: string;
  syntheticMessageId: string;
  taskText: string;
};

type SlackSessionStopTarget =
  { id: string; kind: "run" } | { id: string; kind: "wakeup" };

type SlackSessionStopPayload = {
  version: 1;
  assignedAgentId: string;
  eventTimestamp: string;
  issueId: string | null;
  occurredAt: string;
  sessionGeneration: number | null;
  target: SlackSessionStopTarget | null;
  threadId: string;
  userId: string;
};

function slackSessionStopPayload(
  value: Record<string, unknown>,
): SlackSessionStopPayload | null {
  const target = value.target;
  const parsedTarget =
    target === null
      ? null
      : target &&
          typeof target === "object" &&
          !Array.isArray(target) &&
          ((target as { kind?: unknown }).kind === "run" ||
            (target as { kind?: unknown }).kind === "wakeup") &&
          typeof (target as { id?: unknown }).id === "string" &&
          isUuidLike((target as { id: string }).id)
        ? (target as SlackSessionStopTarget)
        : undefined;
  if (
    value.version !== 1 ||
    typeof value.assignedAgentId !== "string" ||
    !isUuidLike(value.assignedAgentId) ||
    typeof value.eventTimestamp !== "string" ||
    !value.eventTimestamp ||
    (value.issueId !== null &&
      (typeof value.issueId !== "string" || !isUuidLike(value.issueId))) ||
    typeof value.occurredAt !== "string" ||
    !Number.isFinite(new Date(value.occurredAt).getTime()) ||
    (value.sessionGeneration !== null &&
      (typeof value.sessionGeneration !== "number" ||
        !Number.isSafeInteger(value.sessionGeneration) ||
        value.sessionGeneration < 1)) ||
    (parsedTarget !== null &&
      (value.issueId === null || value.sessionGeneration === null)) ||
    parsedTarget === undefined ||
    typeof value.threadId !== "string" ||
    !value.threadId.startsWith("slack:") ||
    typeof value.userId !== "string" ||
    !value.userId
  ) {
    return null;
  }
  return {
    version: 1,
    assignedAgentId: value.assignedAgentId,
    eventTimestamp: value.eventTimestamp,
    issueId: value.issueId,
    occurredAt: value.occurredAt,
    sessionGeneration: value.sessionGeneration,
    target: parsedTarget,
    threadId: value.threadId,
    userId: value.userId,
  };
}

function slackSlashTaskRecoveryPayload(
  payload: Record<string, unknown>,
): SlackSlashTaskRecoveryPayload | null {
  const channelId = payload.channelId;
  const command = payload.command;
  const syntheticMessageId = payload.syntheticMessageId;
  const taskText = payload.taskText;
  if (
    typeof channelId !== "string" ||
    !channelId.trim() ||
    typeof command !== "string" ||
    !command.trim() ||
    typeof syntheticMessageId !== "string" ||
    !syntheticMessageId.trim() ||
    typeof taskText !== "string" ||
    !taskText.trim()
  ) {
    return null;
  }
  return { channelId, command, syntheticMessageId, taskText };
}

function slackTaskStarterThreadId(
  channelId: string,
  providerMessageId: string,
): string {
  return `slack:${channelId.replace(/^slack:/, "")}:${providerMessageId}`;
}

function slackThreadChannelId(threadId: string): string | null {
  if (!threadId.startsWith("slack:")) return null;
  const channelAndThread = threadId.slice("slack:".length);
  const separator = channelAndThread.indexOf(":");
  const channelId =
    separator === -1 ? channelAndThread : channelAndThread.slice(0, separator);
  return channelId || null;
}

function actionThreadMatchesConversation(
  provider: ChatProvider,
  actionThreadId: string,
  conversationThreadId: string,
): boolean {
  if (provider === "microsoft-teams") {
    return sameTeamsThreadIdentity(actionThreadId, conversationThreadId);
  }
  if (provider !== "slack") return actionThreadId === conversationThreadId;
  const actionChannelId = slackThreadChannelId(actionThreadId);
  return (
    actionChannelId !== null &&
    actionChannelId === slackThreadChannelId(conversationThreadId)
  );
}

function slackTaskStartActivityStatus(action: {
  status: string;
  updatedAt: Date;
}): string {
  const age = Date.now() - action.updatedAt.getTime();
  if (action.status === "validating" && age >= SLACK_COMMAND_POST_STALE_MS) {
    return "queued";
  }
  if (
    (action.status === "received" && age >= SLACK_COMMAND_POST_STALE_MS) ||
    (action.status === "resolving" &&
      age >= SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS)
  ) {
    return "delivery_unknown";
  }
  return action.status;
}

function confirmedSlackTaskStartResult(
  result: Record<string, unknown> | null,
): {
  authorizedUserId?: string | null;
  providerMessageId: string;
  threadId: string;
} | null {
  if (
    !result ||
    typeof result.providerMessageId !== "string" ||
    !result.providerMessageId ||
    typeof result.threadId !== "string" ||
    !result.threadId
  ) {
    return null;
  }
  const hasAuthorizedUserId = Object.prototype.hasOwnProperty.call(
    result,
    "authorizedUserId",
  );
  if (
    hasAuthorizedUserId &&
    result.authorizedUserId !== null &&
    (typeof result.authorizedUserId !== "string" || !result.authorizedUserId)
  ) {
    return null;
  }
  return {
    ...(hasAuthorizedUserId
      ? { authorizedUserId: result.authorizedUserId as string | null }
      : {}),
    providerMessageId: result.providerMessageId,
    threadId: result.threadId,
  };
}

function sanitizeFilename(value: string | undefined): string | null {
  if (!value) return null;
  const leaf = value.replaceAll("\\", "/").split("/").pop()?.trim();
  return leaf ? leaf.replace(/[\u0000-\u001f\u007f]/g, "").slice(0, 255) : null;
}

function redactError(error: unknown): string {
  const text = error instanceof Error ? error.message : String(error);
  // Telegram authenticates Bot API calls with a token embedded in the URL
  // path. Generic key/value redaction cannot recognize that shape, so scrub
  // both literal and URL-encoded forms before an error reaches logs, health
  // state, or an HTTP response.
  const withoutTelegramBotTokens = text
    .replace(/(\/bot)\d{5,}(?::|%3A)[A-Za-z0-9_-]{20,}/gi, "$1***REDACTED***")
    .replace(/\b\d{5,}:[A-Za-z0-9_-]{20,}\b/g, "***REDACTED***");
  return redactSensitiveText(withoutTelegramBotTokens).slice(0, MAX_ERROR_TEXT);
}

async function attemptProviderPublication<T>(
  send: () => Promise<T>,
): Promise<T> {
  return await send();
}

async function editOrPostProviderPublication<T>(
  edit: () => Promise<T>,
  post: () => Promise<T>,
): Promise<T> {
  try {
    return await edit();
  } catch (error) {
    // A definite 404 proves the old progress comment no longer exists. It is
    // therefore safe to create a replacement without risking a duplicate.
    // Ambiguous transport failures must still enter delivery_unknown.
    if (classifyChatPublicationError(error, 1).kind !== "resource_unavailable")
      throw error;
    return await post();
  }
}

function safeCardForPublication(
  payload: SafeChatPublicationPayload,
  provider: ChatProvider,
) {
  if (!payload.card) return null;
  const children = [];
  if (payload.card.body) children.push(CardText(payload.card.body));
  const actions = (payload.card.actions ?? []).map((action) =>
    action.type === "callback"
      ? Button({
          id: action.actionId,
          label: action.label,
          style: action.style ?? "default",
          // Telegram encodes both id and value into callback_data, whose hard
          // limit is 64 bytes. Its opaque action id resolves through the
          // durable token ledger, so repeating the interaction UUID is both
          // unnecessary and too large. Other adapters retain the value as a
          // defense-in-depth binding supported by their larger envelopes.
          value: provider === "telegram" ? undefined : payload.interactionId,
          actionType: isChatQuestionFormOpenActionId(action.actionId)
            ? "modal"
            : undefined,
        })
      : LinkButton({ label: action.label, url: action.url }),
  );
  if (actions.length) children.push(Actions(actions));
  return Card({ title: payload.card.title, children });
}

function base64UrlJson(value: unknown): string {
  return Buffer.from(JSON.stringify(value)).toString("base64url");
}

function githubAppJwt(
  appId: string,
  privateKey: string,
  now = new Date(),
): string {
  const epoch = Math.floor(now.getTime() / 1000);
  const unsigned = `${base64UrlJson({ alg: "RS256", typ: "JWT" })}.${base64UrlJson({ iat: epoch - 60, exp: epoch + 540, iss: appId })}`;
  const signer = createSign("RSA-SHA256");
  signer.update(unsigned);
  signer.end();
  return `${unsigned}.${signer.sign(createPrivateKey(privateKey)).toString("base64url")}`;
}

function absoluteBaseUrl(value: string | null | undefined): string | null {
  if (!value) return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" ||
      url.hostname === "localhost" ||
      url.hostname === "127.0.0.1"
      ? url.origin
      : null;
  } catch {
    return null;
  }
}

const TELEGRAM_WEBHOOK_PORTS = new Set(["", "80", "88", "443", "8443"]);

function isSupportedTelegramWebhookBaseUrl(value: string | null): boolean {
  if (!value) return false;
  try {
    const url = new URL(value);
    return url.protocol === "https:" && TELEGRAM_WEBHOOK_PORTS.has(url.port);
  } catch {
    return false;
  }
}

type GitHubLifecycleEvent = {
  actor?: LifecycleActor;
  isBotMessage?: true;
  eventKind: "message_updated" | "message_deleted";
  messageId: string;
  providerEventId?: string;
  providerMessageSequence: number | null;
  providerSentAt: string | null;
  revision: string;
  text: string;
  threadId: string;
};

type TelegramLifecycleEvent = {
  actor: LifecycleActor;
  eventKind: "message_updated";
  messageId: string;
  providerEventId?: string;
  providerMessageSequence: number;
  providerSentAt: string;
  providerUpdateId: number | null;
  revision: string;
  text: string;
  threadId: string;
};

type LifecycleActor = {
  displayName: string;
  externalId: string;
  handle: string;
};

type MicrosoftTeamsLifecycleEvent = {
  actor?: LifecycleActor;
  eventKind: "message_updated" | "message_deleted" | "message_restored";
  messageId: string;
  providerSentAt: string | null;
  raw?: unknown;
  revision: string;
  text: string;
  threadId: string;
};

function lifecycleActorFromAuthor(
  provider: ChatProvider,
  author: Author,
  raw?: unknown,
): LifecycleActor {
  return {
    externalId: stableExternalPrincipalId(provider, author, raw),
    displayName: author.fullName,
    handle: author.userName,
  };
}

function slackLifecycleFilesDigest(raw: unknown): string {
  const files =
    raw && typeof raw === "object" && !Array.isArray(raw)
      ? (raw as Record<string, unknown>).files
      : undefined;
  // Match the pinned Slack adapter's content-change projection. Transport
  // locators/unfurls are not content identity and must never enter durable keys.
  const projection = Array.isArray(files)
    ? files.map((file) => {
        const row =
          file && typeof file === "object" && !Array.isArray(file)
            ? (file as Record<string, unknown>)
            : {};
        return [
          ...["id", "name", "mimetype"].map((key) =>
            typeof row[key] === "string" ? row[key] : null,
          ),
          ...["size", "original_w", "original_h"].map((key) =>
            typeof row[key] === "number" && Number.isFinite(row[key])
              ? row[key]
              : null,
          ),
        ];
      })
    : [];
  return createHash("sha256").update(JSON.stringify(projection)).digest("hex");
}

function discordLifecycleFilesDigest(raw: unknown): string {
  const attachments =
    raw && typeof raw === "object" && !Array.isArray(raw)
      ? (raw as Record<string, unknown>).attachments
      : undefined;
  // Match the pinned Gateway adapter's flattened, ordered file projection.
  // Rotating CDN URLs are transport authority, never source revision identity.
  const projection = Array.isArray(attachments)
    ? attachments.map((attachment) => {
        const row =
          attachment &&
          typeof attachment === "object" &&
          !Array.isArray(attachment)
            ? (attachment as Record<string, unknown>)
            : {};
        return [
          ...["id", "filename", "content_type"].map((key) =>
            typeof row[key] === "string" ? row[key] : null,
          ),
          typeof row.size === "number" && Number.isFinite(row.size)
            ? row.size
            : null,
        ];
      })
    : [];
  return createHash("sha256").update(JSON.stringify(projection)).digest("hex");
}

function telegramLifecycleActor(message: {
  from?: unknown;
  sender_chat?: unknown;
}): LifecycleActor | null {
  const candidate =
    message.from &&
    typeof message.from === "object" &&
    !Array.isArray(message.from)
      ? (message.from as Record<string, unknown>)
      : message.sender_chat &&
          typeof message.sender_chat === "object" &&
          !Array.isArray(message.sender_chat)
        ? (message.sender_chat as Record<string, unknown>)
        : null;
  if (!candidate) return null;
  const id = candidate.id;
  if (typeof id !== "string" && typeof id !== "number") return null;
  const handle =
    typeof candidate.username === "string" ? candidate.username : "";
  const displayName =
    [candidate.first_name, candidate.last_name]
      .filter(
        (value): value is string => typeof value === "string" && Boolean(value),
      )
      .join(" ") ||
    (typeof candidate.title === "string" ? candidate.title : "") ||
    handle ||
    String(id);
  return { externalId: String(id), displayName, handle };
}

function microsoftTeamsLifecycleEventFromPayload(
  payload: unknown,
  endpointRuntime: ChatSdkEndpointRuntime,
): MicrosoftTeamsLifecycleEvent | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    return null;
  const activity = payload as {
    channelData?: { eventType?: unknown };
    timestamp?: unknown;
    type?: unknown;
  };
  const eventType = activity.channelData?.eventType;
  const isEdit =
    activity.type === "messageUpdate" && eventType === "editMessage";
  const isRestore =
    activity.type === "messageUpdate" && eventType === "undeleteMessage";
  const isDelete =
    activity.type === "messageDelete" && eventType === "softDeleteMessage";
  if (!isEdit && !isRestore && !isDelete) return null;
  const message = endpointRuntime.parseMicrosoftTeamsMessage(payload);
  if (!message?.id || !message.threadId) return null;
  const body = message.text.slice(0, MAX_INBOUND_TEXT);
  const providerSentAt =
    typeof activity.timestamp === "string" &&
    Number.isFinite(Date.parse(activity.timestamp))
      ? new Date(activity.timestamp).toISOString()
      : null;
  const bodyHash = createHash("sha256").update(body).digest("hex");
  const revision = providerSentAt ? `${providerSentAt}:${bodyHash}` : bodyHash;
  return {
    ...(!isDelete
      ? {
          actor: lifecycleActorFromAuthor(
            "microsoft-teams",
            message.author,
            message.raw,
          ),
        }
      : {}),
    eventKind: isDelete
      ? "message_deleted"
      : isRestore
        ? "message_restored"
        : "message_updated",
    messageId: message.id,
    providerSentAt,
    raw: message.raw,
    revision,
    text: isDelete
      ? "An external message in this conversation was deleted."
      : isRestore
        ? `An external message was restored:\n\n${body}`
        : `An external message was edited:\n\n${body}`,
    threadId: message.threadId,
  };
}

function telegramLifecycleEventFromPayload(
  payload: unknown,
): TelegramLifecycleEvent | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    return null;
  const update = payload as {
    edited_message?: unknown;
    update_id?: unknown;
  };
  const edited = update.edited_message;
  if (!edited || typeof edited !== "object" || Array.isArray(edited))
    return null;
  const message = edited as {
    caption?: unknown;
    chat?: { id?: unknown };
    edit_date?: unknown;
    from?: unknown;
    message_id?: unknown;
    message_thread_id?: unknown;
    sender_chat?: unknown;
    text?: unknown;
    rich_message?: unknown;
  };
  const chatId = message.chat?.id;
  const messageId = message.message_id;
  const editDate = message.edit_date;
  if (
    (typeof chatId !== "string" && typeof chatId !== "number") ||
    typeof messageId !== "number" ||
    !Number.isSafeInteger(messageId) ||
    messageId < 0 ||
    typeof editDate !== "number" ||
    !Number.isSafeInteger(editDate) ||
    editDate <= 0
  )
    return null;
  const topicId = message.message_thread_id;
  if (topicId !== undefined && typeof topicId !== "number") return null;
  const rich = normalizeTelegramRichMessage(message);
  const body =
    rich?.text ??
    (typeof message.text === "string"
      ? message.text
      : typeof message.caption === "string"
        ? message.caption
        : "");
  const chat = String(chatId);
  const providerUpdateId =
    typeof update.update_id === "number" &&
    Number.isSafeInteger(update.update_id) &&
    update.update_id >= 0
      ? update.update_id
      : null;
  const bodyHash = createHash("sha256").update(body).digest("hex");
  const actor = telegramLifecycleActor(message);
  if (!actor) return null;
  return {
    actor,
    eventKind: "message_updated",
    messageId: `${chat}:${messageId}`,
    ...(providerUpdateId === null
      ? {}
      : { providerEventId: `telegram:update:${providerUpdateId}` }),
    providerMessageSequence: messageId,
    providerSentAt: new Date(editDate * 1_000).toISOString(),
    providerUpdateId,
    // Bot API timestamps have one-second resolution. The update id is the
    // authoritative identity when present; retaining a content hash keeps the
    // fallback path from collapsing two distinct edits in that same second.
    revision: `${editDate}:${bodyHash}${rich ? `:${rich.mediaDigest}` : ""}`,
    text: `An external message was edited:\n\n${body.slice(0, MAX_INBOUND_TEXT)}`,
    threadId:
      topicId === undefined
        ? `telegram:${chat}`
        : `telegram:${chat}:${topicId}`,
  };
}

function isTelegramEditedMessageRaw(raw: unknown): boolean {
  return (
    !!raw &&
    typeof raw === "object" &&
    !Array.isArray(raw) &&
    typeof (raw as { edit_date?: unknown }).edit_date === "number"
  );
}

function isTelegramMigrationRaw(raw: unknown): boolean {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return false;
  const value = raw as {
    migrate_from_chat_id?: unknown;
    migrate_to_chat_id?: unknown;
  };
  return (
    value.migrate_from_chat_id !== undefined ||
    value.migrate_to_chat_id !== undefined
  );
}

function telegramMessageSequence(raw: unknown): number | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const value = (raw as { message_id?: unknown }).message_id;
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0
    ? value
    : null;
}

function telegramMessageId(raw: unknown): string | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const value = raw as {
    chat?: { id?: unknown };
    message_id?: unknown;
  };
  const messageId = value.message_id;
  const chatId = value.chat?.id;
  if (
    typeof messageId !== "number" ||
    !Number.isSafeInteger(messageId) ||
    messageId <= 0
  )
    return null;
  const normalizedChatId =
    typeof chatId === "number" && Number.isSafeInteger(chatId)
      ? String(chatId)
      : typeof chatId === "string" && /^-?\d+$/.test(chatId)
        ? chatId
        : null;
  return normalizedChatId ? `${normalizedChatId}:${messageId}` : null;
}

function telegramZeroMessageId(value: unknown): boolean {
  // The pinned adapter qualifies native message IDs with the numeric chat ID.
  // Keep legacy synthetic/non-numeric IDs compatible; zero is specifically
  // the provider's non-ordinary message identity, never an admitted source.
  return typeof value === "string" && /^(?:-?\d+:)?0$/.test(value);
}

function telegramDeliveryHasZeroMessageId(
  delivery: DeliveryRow,
  provider: ChatProvider,
): boolean {
  if (provider !== "telegram") return false;
  const normalized = delivery.normalizedEvent as {
    message?: {
      providerMessageId?: unknown;
      providerMessageSequence?: unknown;
    };
    conversation?: { externalThreadId?: unknown };
  };
  if (
    telegramZeroMessageId(normalized.message?.providerMessageId) ||
    normalized.message?.providerMessageSequence === 0
  )
    return true;
  const threadId = normalized.conversation?.externalThreadId;
  // Check the independently retained event key only inside its exact thread
  // namespace, not arbitrary IDs ending in ':0' from synthetic commands.
  return (
    typeof threadId === "string" &&
    delivery.providerEventId.startsWith(`${threadId}:`) &&
    telegramZeroMessageId(delivery.providerEventId.slice(threadId.length + 1))
  );
}

function telegramMessageSentAt(raw: unknown): Date | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const value = (raw as { date?: unknown }).date;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0)
    return null;
  const sentAt = new Date(value * 1_000);
  return Number.isFinite(sentAt.getTime()) ? sentAt : null;
}

function slackMessageSentAt(raw: unknown, messageId: string): Date | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const ts = (raw as { ts?: unknown }).ts;
  if (
    ts !== messageId ||
    typeof ts !== "string" ||
    !/^[1-9][0-9]{0,12}\.[0-9]{6}$/.test(ts)
  )
    return null;
  const date = new Date(Number(ts) * 1_000);
  return Number.isFinite(date.getTime()) ? date : null;
}

function teamsActivitySentAt(raw: unknown): Date | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const value = (raw as { timestamp?: unknown }).timestamp;
  // The SDK may supply a Date, but its missing-timestamp display fallback is
  // only on Message.metadata. Never use that fallback as provider chronology.
  if (value instanceof Date)
    return Number.isFinite(value.getTime()) ? new Date(value.getTime()) : null;
  if (
    typeof value !== "string" ||
    value.length > 64 ||
    !/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,7})?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/.test(
      value,
    )
  )
    return null;
  // Date.parse otherwise normalizes nonexistent dates such as February 30.
  const day = value.slice(0, 10);
  const calendar = new Date(`${day}T00:00:00.000Z`);
  if (
    !Number.isFinite(calendar.getTime()) ||
    calendar.toISOString().slice(0, 10) !== day
  )
    return null;
  const sentAt = new Date(value);
  return Number.isFinite(sentAt.getTime()) ? sentAt : null;
}

async function githubLifecycleEventFromRequest(
  request: Request,
): Promise<GitHubLifecycleEvent | null> {
  const eventType = request.headers.get("x-github-event");
  const deliveryId = request.headers.get("x-github-delivery")?.trim() || null;
  if (
    eventType !== "issue_comment" &&
    eventType !== "pull_request_review_comment"
  )
    return null;
  const payload = (await request.json()) as {
    action?: unknown;
    comment?: {
      id?: unknown;
      in_reply_to_id?: unknown;
      body?: unknown;
      updated_at?: unknown;
      user?: { type?: unknown };
    };
    issue?: { number?: unknown; pull_request?: unknown };
    pull_request?: { number?: unknown };
    repository?: { name?: unknown; owner?: { login?: unknown } };
    sender?: { id?: unknown; login?: unknown; type?: unknown };
  };
  if (payload.action !== "edited" && payload.action !== "deleted") return null;
  const owner = payload.repository?.owner?.login;
  const repo = payload.repository?.name;
  const messageId = payload.comment?.id;
  if (
    typeof owner !== "string" ||
    typeof repo !== "string" ||
    (typeof messageId !== "string" && typeof messageId !== "number")
  )
    return null;
  let threadId: string;
  if (eventType === "issue_comment") {
    const number = payload.issue?.number;
    if (typeof number !== "number") return null;
    threadId = payload.issue?.pull_request
      ? `github:${owner}/${repo}:${number}`
      : `github:${owner}/${repo}:issue:${number}`;
  } else {
    const number = payload.pull_request?.number;
    const rootCommentId =
      payload.comment?.in_reply_to_id ?? payload.comment?.id;
    if (
      typeof number !== "number" ||
      (typeof rootCommentId !== "string" && typeof rootCommentId !== "number")
    )
      return null;
    threadId = `github:${owner}/${repo}:${number}:rc:${rootCommentId}`;
  }
  const eventKind =
    payload.action === "edited" ? "message_updated" : "message_deleted";
  const body =
    typeof payload.comment?.body === "string"
      ? payload.comment.body.slice(0, MAX_INBOUND_TEXT)
      : "";
  const providerRevision =
    typeof payload.comment?.updated_at === "string"
      ? payload.comment.updated_at
      : payload.action;
  const parsedProviderSentAt = new Date(providerRevision);
  const providerSentAt = Number.isFinite(parsedProviderSentAt.getTime())
    ? parsedProviderSentAt.toISOString()
    : null;
  const numericMessageId =
    typeof messageId === "number"
      ? messageId
      : typeof messageId === "string" && /^\d+$/.test(messageId)
        ? Number(messageId)
        : null;
  const providerMessageSequence =
    numericMessageId !== null &&
    Number.isSafeInteger(numericMessageId) &&
    numericMessageId >= 0
      ? numericMessageId
      : null;
  const senderId = payload.sender?.id;
  const senderLogin = payload.sender?.login;
  const actor =
    (typeof senderId === "string" || typeof senderId === "number") &&
    typeof senderLogin === "string" &&
    senderLogin.length > 0
      ? {
          externalId: String(senderId),
          displayName: senderLogin,
          handle: senderLogin,
        }
      : undefined;
  return {
    ...(actor ? { actor } : {}),
    ...(payload.comment?.user?.type === "Bot" || payload.sender?.type === "Bot"
      ? { isBotMessage: true as const }
      : {}),
    eventKind,
    messageId: String(messageId),
    ...(deliveryId ? { providerEventId: `github:delivery:${deliveryId}` } : {}),
    providerMessageSequence,
    providerSentAt,
    // GitHub's updated_at value can have coarser resolution than a quick
    // sequence of edits. Include the normalized body so distinct edits at the
    // same timestamp remain durable while an exact webhook redelivery still
    // deduplicates.
    revision:
      eventKind === "message_updated"
        ? `${providerRevision}:${createHash("sha256").update(body).digest("hex")}`
        : providerRevision,
    text:
      eventKind === "message_updated"
        ? `An external message was edited:\n\n${body}`
        : "An external message in this conversation was deleted.",
    threadId,
  };
}

function githubRepositoryInventoryItemFromPayload(
  payload: unknown,
): ChatProviderResourceInventoryItem | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    return null;
  const repository = (payload as { repository?: unknown }).repository;
  if (
    !repository ||
    typeof repository !== "object" ||
    Array.isArray(repository)
  )
    return null;
  const value = repository as {
    id?: unknown;
    full_name?: unknown;
    html_url?: unknown;
    name?: unknown;
    owner?: { id?: unknown; login?: unknown };
    private?: unknown;
  };
  const repositoryId =
    typeof value.id === "number" && Number.isSafeInteger(value.id)
      ? String(value.id)
      : typeof value.id === "string" && /^\d+$/.test(value.id)
        ? value.id
        : null;
  const owner =
    typeof value.owner?.login === "string" ? value.owner.login.trim() : "";
  const name = typeof value.name === "string" ? value.name.trim() : "";
  const fullName =
    typeof value.full_name === "string" && value.full_name.includes("/")
      ? value.full_name.trim()
      : owner && name
        ? `${owner}/${name}`
        : "";
  if (!repositoryId || !fullName) return null;
  const ownerId =
    typeof value.owner?.id === "number" && Number.isSafeInteger(value.owner.id)
      ? String(value.owner.id)
      : typeof value.owner?.id === "string" && /^\d+$/.test(value.owner.id)
        ? value.owner.id
        : undefined;
  return {
    providerResourceId: fullName.toLowerCase(),
    parentProviderResourceId: ownerId,
    type: "repository",
    label: fullName,
    providerUrl:
      typeof value.html_url === "string" && value.html_url.length > 0
        ? value.html_url
        : `https://github.com/${fullName}`,
    metadata: {
      providerRepositoryId: repositoryId,
      fullName,
      ...(owner ? { owner } : {}),
      private: value.private === true,
      source: "provider_webhook",
    },
  };
}

function providerSetupState(
  endpoint: Pick<
    EndpointRow,
    | "provider"
    | "providerAccountId"
    | "publicId"
    | "status"
    | "setup"
    | "botUsername"
  >,
  publicBaseUrl: string | null,
  assignedAgentName?: string | null,
) {
  const path = `/api/chat-webhooks/${endpoint.publicId}/${endpoint.provider}`;
  const webhookUrl = publicBaseUrl ? `${publicBaseUrl}${path}` : null;
  const step = endpoint.status === "active" ? "complete" : endpoint.setup.step;
  switch (endpoint.provider) {
    case "slack": {
      const observations = (endpoint.setup as InternalSetupState)
        .slackCallbackSurfaces;
      const currentUrl = webhookUrl ? canonicalCallbackUrl(webhookUrl) : null;
      const surfaceState = (
        surface: SlackCallbackSurface,
      ): ChatEndpointCallbackSurfaces[SlackCallbackSurface] => {
        const observation = observations?.[surface];
        if (!observation) return { status: "unverified" };
        return {
          status:
            currentUrl !== null &&
            canonicalCallbackUrl(observation.url) === currentUrl
              ? "current"
              : "stale",
          observedAt: observation.observedAt,
        };
      };
      const callbackSurfaces: ChatEndpointCallbackSurfaces = {
        events: surfaceState("events"),
        interactivity: surfaceState("interactivity"),
        slashCommands: surfaceState("slashCommands"),
      };
      return {
        step,
        authorizationUrl: "https://api.slack.com/apps?new_app=1",
        providerUrl: "https://app.slack.com/",
        webhookUrl,
        webhookVerifiedAt: endpoint.setup.webhookVerifiedAt ?? null,
        callbackSurfaces,
        callbacksNeedUpdate: Object.values(callbackSurfaces).some(
          (surface) => surface.status === "stale",
        ),
        // Slack registers the slash command in the provider configuration.
        // Keep that identity immutable when the assigned agent is renamed;
        // deriving it remains only a compatibility path for older rows.
        command:
          typeof endpoint.setup.command === "string"
            ? endpoint.setup.command
            : assignedAgentName
              ? slackCommandForAgent(assignedAgentName, endpoint.publicId)
              : null,
      } as const;
    }
    case "github":
      return {
        step,
        authorizationUrl: "https://github.com/settings/apps/new",
        providerUrl: "https://github.com/settings/installations",
        webhookUrl,
        webhookVerifiedAt: endpoint.setup.webhookVerifiedAt ?? null,
      } as const;
    case "discord":
      return {
        step,
        authorizationUrl: "https://discord.com/developers/applications",
        providerUrl: endpoint.providerAccountId
          ? `https://discord.com/channels/${encodeURIComponent(endpoint.providerAccountId)}`
          : "https://discord.com/channels/@me",
        webhookUrl,
      } as const;
    case "microsoft-teams":
      return {
        step,
        authorizationUrl: "https://dev.teams.microsoft.com/apps",
        providerUrl: "https://teams.microsoft.com/",
        messagingEndpoint: webhookUrl,
      } as const;
    case "telegram":
      return {
        step,
        providerUrl: endpoint.botUsername
          ? `https://t.me/${encodeURIComponent(endpoint.botUsername)}`
          : "https://t.me/BotFather",
        webhookUrl,
      } as const;
  }
}

function slackCommandForAgent(agentName: string, publicId: string): string {
  const slug = agentName
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 20);
  const suffix = publicId
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "")
    .slice(0, 6);
  return `/${slug || "paperclip"}-${suffix || "agent"}`;
}

export function createChatSdkStatePersistence(db: Db): ChatSdkStatePersistence {
  return {
    async read(scope: ChatSdkStateScope, key: string) {
      return db
        .select({
          value: chatSdkState.value,
          version: chatSdkState.version,
          expiresAt: chatSdkState.expiresAt,
        })
        .from(chatSdkState)
        .where(
          and(
            eq(chatSdkState.companyId, scope.companyId),
            eq(chatSdkState.endpointId, scope.endpointId),
            eq(chatSdkState.stateKey, key),
          ),
        )
        .then((rows) => rows[0] ?? null);
    },
    async compareAndSet(input: ChatSdkStateCompareAndSetInput) {
      if (input.expectedVersion === null) {
        const inserted = await db
          .insert(chatSdkState)
          .values({
            companyId: input.companyId,
            endpointId: input.endpointId,
            stateKey: input.key,
            version: 1,
            value: input.value,
            expiresAt: input.expiresAt,
          })
          .onConflictDoNothing()
          .returning({ id: chatSdkState.id });
        return inserted.length === 1;
      }
      const updated = await db
        .update(chatSdkState)
        .set({
          version: input.expectedVersion + 1,
          value: input.value,
          expiresAt: input.expiresAt,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatSdkState.companyId, input.companyId),
            eq(chatSdkState.endpointId, input.endpointId),
            eq(chatSdkState.stateKey, input.key),
            eq(chatSdkState.version, input.expectedVersion),
          ),
        )
        .returning({ id: chatSdkState.id });
      return updated.length === 1;
    },
    async deleteIfVersion(input: ChatSdkStateDeleteInput) {
      const deleted = await db
        .delete(chatSdkState)
        .where(
          and(
            eq(chatSdkState.companyId, input.companyId),
            eq(chatSdkState.endpointId, input.endpointId),
            eq(chatSdkState.stateKey, input.key),
            eq(chatSdkState.version, input.expectedVersion),
          ),
        )
        .returning({ id: chatSdkState.id });
      return deleted.length === 1;
    },
  };
}

const OUTBOUND_ATTACHMENT_STORAGE_TIMEOUT_MS = 10_000;

class OutboundAttachmentHydrationError extends Error {
  readonly code = "CHAT_ATTACHMENT_HYDRATION_FAILED";

  constructor(message: string, cause?: unknown) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = "OutboundAttachmentHydrationError";
  }
}

class OutboundAttachmentValidationError extends Error {
  readonly code = "CHAT_ATTACHMENT_VALIDATION_FAILED";

  constructor(message: string) {
    super(message);
    this.name = "OutboundAttachmentValidationError";
  }
}

function isOutboundAttachmentHydrationError(
  error: unknown,
): error is OutboundAttachmentHydrationError {
  return error instanceof OutboundAttachmentHydrationError;
}

function isOutboundAttachmentValidationError(
  error: unknown,
): error is OutboundAttachmentValidationError {
  return error instanceof OutboundAttachmentValidationError;
}

/**
 * Read one already-authorized attachment before any provider transport starts.
 * The database digest, rather than mutable object-store metadata, is the
 * integrity boundary. Both acquisition and streaming are bounded so a stuck
 * storage backend cannot hold the publication lane indefinitely.
 */
export async function hydrateOutboundAttachment(input: {
  storage: StorageService;
  companyId: string;
  objectKey: string;
  byteSize: number;
  sha256: string;
  filename: string;
  mimeType: string;
  timeoutMs?: number;
}): Promise<FileUpload> {
  const timeoutMs =
    typeof input.timeoutMs === "number" &&
    Number.isFinite(input.timeoutMs) &&
    input.timeoutMs > 0
      ? input.timeoutMs
      : OUTBOUND_ATTACHMENT_STORAGE_TIMEOUT_MS;
  if (
    !Number.isSafeInteger(input.byteSize) ||
    input.byteSize <= 0 ||
    input.byteSize > MAX_ATTACHMENT_BYTES ||
    !/^[0-9a-f]{64}$/iu.test(input.sha256)
  ) {
    throw new OutboundAttachmentHydrationError(
      "Chat publication attachment metadata is invalid",
    );
  }
  const acquisitionTimeoutError = new OutboundAttachmentHydrationError(
    "Chat publication attachment storage read timed out",
  );
  let acquisitionTimedOut = false;
  let rejectAcquisition!: (error: Error) => void;
  const acquisitionTimeout = new Promise<never>((_resolve, reject) => {
    rejectAcquisition = reject;
  });
  const acquisitionTimer = setTimeout(() => {
    acquisitionTimedOut = true;
    rejectAcquisition(acquisitionTimeoutError);
  }, timeoutMs);
  acquisitionTimer.unref?.();
  const objectPromise = Promise.resolve()
    .then(() => input.storage.getObject(input.companyId, input.objectKey))
    .then((object) => {
      if (acquisitionTimedOut) object.stream.destroy();
      return object;
    })
    .catch((error) => {
      throw isOutboundAttachmentHydrationError(error)
        ? error
        : new OutboundAttachmentHydrationError(
            "Chat publication attachment storage read failed",
            error,
          );
    });
  let object: Awaited<ReturnType<StorageService["getObject"]>>;
  try {
    object = await Promise.race([objectPromise, acquisitionTimeout]);
  } finally {
    clearTimeout(acquisitionTimer);
  }

  if (
    object.contentLength !== undefined &&
    object.contentLength !== input.byteSize
  ) {
    object.stream.destroy();
    throw new OutboundAttachmentHydrationError(
      "Chat publication attachment size changed after registration",
    );
  }

  const streamTimeoutError = new OutboundAttachmentHydrationError(
    "Chat publication attachment storage read timed out",
  );
  const streamTimer = setTimeout(() => {
    object.stream.destroy(streamTimeoutError);
  }, timeoutMs);
  streamTimer.unref?.();
  const chunks: Buffer[] = [];
  const digest = createHash("sha256");
  let bytes = 0;
  try {
    for await (const chunk of object.stream) {
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      bytes += buffer.length;
      if (bytes > input.byteSize || bytes > MAX_ATTACHMENT_BYTES) {
        object.stream.destroy();
        throw new OutboundAttachmentHydrationError(
          "Chat publication attachment exceeded its streaming byte limit",
        );
      }
      digest.update(buffer);
      chunks.push(buffer);
    }
  } catch (error) {
    throw isOutboundAttachmentHydrationError(error)
      ? error
      : new OutboundAttachmentHydrationError(
          "Chat publication attachment storage read failed",
          error,
        );
  } finally {
    clearTimeout(streamTimer);
  }

  const actualDigest = digest.digest("hex");
  if (bytes !== input.byteSize || actualDigest !== input.sha256.toLowerCase()) {
    if (!object.stream.destroyed) object.stream.destroy();
    throw new OutboundAttachmentHydrationError(
      "Chat publication attachment integrity changed after registration",
    );
  }

  return {
    data: Buffer.concat(chunks, bytes),
    filename: input.filename,
    mimeType: input.mimeType,
  };
}

export function chatChannelService(db: Db, options: ChatChannelServiceOptions) {
  const runtime = options.runtime ?? createChatSdkRuntime();
  const runtimeVersions = new Map<string, string>();
  const runtimeLocalEpochs = new Map<string, number>();
  // One bounded publication lane per endpoint; credential/reconnect fencing
  // still serializes a bot's sends while unrelated bots can make progress.
  const publicationEndpointTasks = new Map<string, Promise<void>>();
  // Scheduling-only cooldown for rejected/contended staged work. Do not alter
  // an unverified transfer or its publication merely because a worker saw it.
  const teamsFileRetryAfter = new Map<string, number>();
  let telegramSubscriptionScanAfter: string | null = null;
  const runtimeContexts = new WeakMap<object, RuntimeContext>();
  const runtimeInitializations = new Map<
    string,
    {
      discordGatewayOwned: boolean;
      promise: Promise<ChatSdkEndpointRuntime>;
      version: string;
    }
  >();
  const persistence = createChatSdkStatePersistence(db);
  const fetchImpl = options.fetch ?? globalThis.fetch;
  const publicBaseUrl = absoluteBaseUrl(options.publicBaseUrl);
  const webhookPublicBaseUrl =
    parseChatWebhookPublicBaseUrl(options.webhookPublicBaseUrl) ??
    publicBaseUrl;
  const issuesSvc = issueService(db);
  const secrets = secretService(db);
  const questionResponses = questionResponseDeliveryService(db, {
    heartbeat:
      options.heartbeat as QuestionResponseDeliveryServiceOptions["heartbeat"],
    resolveNativeQuestion: options.resolveNativeQuestion,
  });
  const backgroundMessageTasks = new Set<Promise<void>>();
  const scheduledConversationDrains = new Map<string, number>();
  const liveInboundMessages = new Map<string, LiveInboundMessage>();
  const discordGatewayOwnerships = new Map<string, DiscordGatewayOwnership>();
  const discordGatewayStopTasks = new Set<Promise<void>>();
  let shuttingDown = false;

  function discordGatewayNotOwnedError() {
    return conflict(
      "Another Paperclip server owns this Discord Gateway connection; retry shortly",
      { code: "chat_discord_gateway_not_owned" },
    );
  }

  function isDiscordGatewayNotOwnedError(error: unknown): boolean {
    return Boolean(
      error &&
      typeof error === "object" &&
      "details" in error &&
      error.details &&
      typeof error.details === "object" &&
      "code" in error.details &&
      error.details.code === "chat_discord_gateway_not_owned",
    );
  }

  async function releaseDiscordGatewayLeaseRow(
    ownership: DiscordGatewayOwnership,
  ): Promise<void> {
    await db
      .delete(chatEndpointLeases)
      .where(
        and(
          eq(chatEndpointLeases.companyId, ownership.companyId),
          eq(chatEndpointLeases.endpointId, ownership.endpointId),
          eq(chatEndpointLeases.leaseKey, ownership.leaseKey),
          eq(chatEndpointLeases.token, ownership.token),
        ),
      )
      .catch((error) => {
        logger.warn(
          {
            endpointId: ownership.endpointId,
            error: redactError(error),
          },
          "could not release Discord Gateway ownership lease",
        );
      });
  }

  async function stopDiscordGatewayOwnership(
    ownership: DiscordGatewayOwnership,
    removeRuntime = true,
  ): Promise<void> {
    if (ownership.stopPromise) return ownership.stopPromise;
    ownership.stopping = true;
    if (ownership.renewTimer) {
      clearInterval(ownership.renewTimer);
      ownership.renewTimer = null;
    }
    if (discordGatewayOwnerships.get(ownership.endpointId) === ownership) {
      discordGatewayOwnerships.delete(ownership.endpointId);
    }
    ownership.stopPromise = (async () => {
      if (
        removeRuntime &&
        ownership.context.endpointRuntime &&
        runtime.get(ownership.endpointId) === ownership.context.endpointRuntime
      ) {
        runtimeVersions.delete(ownership.endpointId);
        await runtime.removeEndpoint(ownership.endpointId).catch((error) => {
          logger.warn(
            {
              endpointId: ownership.endpointId,
              error: redactError(error),
            },
            "could not stop Discord Gateway after ownership loss",
          );
        });
      }
      // The listener is stopped before the lease is released. A standby can
      // therefore acquire immediately without overlapping Gateway sessions.
      await releaseDiscordGatewayLeaseRow(ownership);
    })();
    discordGatewayStopTasks.add(ownership.stopPromise);
    void ownership.stopPromise.finally(() => {
      if (ownership.stopPromise) {
        discordGatewayStopTasks.delete(ownership.stopPromise);
      }
    });
    return ownership.stopPromise;
  }

  async function renewDiscordGatewayOwnership(
    ownership: DiscordGatewayOwnership,
  ): Promise<boolean> {
    if (
      shuttingDown ||
      ownership.stopping ||
      discordGatewayOwnerships.get(ownership.endpointId) !== ownership ||
      ownership.context.discordGatewayOwned !== true ||
      ownership.context.endpointRuntime === undefined ||
      runtime.get(ownership.endpointId) !== ownership.context.endpointRuntime
    ) {
      return false;
    }
    const proposedExpiresAt = new Date(
      Date.now() +
        (options.discordGatewayLeaseTtlMs ?? DISCORD_GATEWAY_LEASE_TTL_MS),
    );
    if (
      options.renewDiscordGatewayLease &&
      !(await options.renewDiscordGatewayLease({
        companyId: ownership.companyId,
        credentialFingerprint: ownership.context.credentialFingerprint,
        endpointId: ownership.endpointId,
        expiresAt: proposedExpiresAt,
        generation: ownership.context.generation,
        leaseKey: ownership.leaseKey,
        token: ownership.token,
      }))
    ) {
      return false;
    }
    return db.transaction(async (tx) => {
      const now = new Date();
      const current = await runtimeCallbackEndpoint(
        tx,
        ownership.endpointId,
        {
          credentialFingerprint: ownership.context.credentialFingerprint,
          generation: ownership.context.generation,
        },
        ["verifying", "active", "attention"],
      );
      if (!current || current.provider !== "discord") return false;
      const expiresAt = new Date(
        now.getTime() +
          (options.discordGatewayLeaseTtlMs ?? DISCORD_GATEWAY_LEASE_TTL_MS),
      );
      const renewed = await tx
        .update(chatEndpointLeases)
        .set({ expiresAt, updatedAt: now })
        .where(
          and(
            eq(chatEndpointLeases.companyId, ownership.companyId),
            eq(chatEndpointLeases.endpointId, ownership.endpointId),
            eq(chatEndpointLeases.leaseKey, ownership.leaseKey),
            eq(chatEndpointLeases.token, ownership.token),
          ),
        )
        .returning({ id: chatEndpointLeases.id });
      if (!renewed.length) return false;
      ownership.expiresAt = expiresAt;
      return true;
    });
  }

  async function renewDiscordGatewayOwnershipForMessageAdmission(
    tx: DbTransaction,
    endpointId: string,
    context: InboundRuntimeContext,
  ): Promise<
    | {
        kind: "owned";
        expiresAt: Date;
        ownership: DiscordGatewayOwnership;
      }
    | { kind: "lost"; ownership: DiscordGatewayOwnership | null }
  > {
    const ownership = discordGatewayOwnerships.get(endpointId);
    if (
      !ownership ||
      ownership.stopping ||
      ownership.context !== context ||
      context.discordGatewayOwned !== true ||
      context.endpointRuntime === undefined ||
      runtime.get(endpointId) !== context.endpointRuntime
    ) {
      return {
        kind: "lost",
        ownership: ownership?.context === context ? ownership : null,
      };
    }
    const now = new Date();
    const expiresAt = new Date(
      now.getTime() +
        (options.discordGatewayLeaseTtlMs ?? DISCORD_GATEWAY_LEASE_TTL_MS),
    );
    const renewed = await tx
      .update(chatEndpointLeases)
      .set({ expiresAt, updatedAt: now })
      .where(
        and(
          eq(chatEndpointLeases.companyId, ownership.companyId),
          eq(chatEndpointLeases.endpointId, ownership.endpointId),
          eq(chatEndpointLeases.leaseKey, ownership.leaseKey),
          eq(chatEndpointLeases.token, ownership.token),
        ),
      )
      .returning({ id: chatEndpointLeases.id });
    return renewed.length
      ? { kind: "owned", expiresAt, ownership }
      : { kind: "lost", ownership };
  }

  function refreshDiscordGatewayOwnership(
    ownership: DiscordGatewayOwnership,
  ): Promise<void> {
    if (ownership.renewal) return ownership.renewal;
    ownership.renewal = renewDiscordGatewayOwnership(ownership)
      .then((owned) => {
        if (owned) return;
        logger.warn(
          { endpointId: ownership.endpointId },
          "lost Discord Gateway ownership; stopping the local listener",
        );
        // A Gateway lifecycle callback can be the caller that discovers the
        // lost token. Fence it synchronously, but do not make that callback
        // await the Gateway task whose adapter notification may be waiting on
        // the callback itself. The tracked stop task is joined at shutdown.
        void stopDiscordGatewayOwnership(ownership);
      })
      .catch((error) => {
        logger.warn(
          {
            endpointId: ownership.endpointId,
            error: redactError(error),
          },
          "Discord Gateway ownership renewal failed; stopping the local listener",
        );
        void stopDiscordGatewayOwnership(ownership);
      })
      .finally(() => {
        ownership.renewal = null;
      });
    return ownership.renewal;
  }

  async function ensureDiscordGatewayRuntimeIsCurrent(
    endpointId: string,
    context: RuntimeContext,
  ): Promise<boolean> {
    const ownership = discordGatewayOwnerships.get(endpointId);
    if (
      !ownership ||
      ownership.stopping ||
      ownership.context !== context ||
      context.discordGatewayOwned !== true ||
      context.endpointRuntime === undefined ||
      runtime.get(endpointId) !== context.endpointRuntime
    ) {
      return false;
    }
    if (ownership.expiresAt.getTime() <= Date.now()) {
      // A host can resume after the local TTL while its durable token is still
      // authoritative. Reclaim that exact token before accepting buffered
      // callbacks. A standby takeover changes the token, so the CAS fails and
      // the old listener remains fenced.
      await refreshDiscordGatewayOwnership(ownership);
    }
    return discordGatewayRuntimeIsCurrent(endpointId, context);
  }

  function startDiscordGatewayLeaseRenewal(
    ownership: DiscordGatewayOwnership,
  ): void {
    ownership.renewTimer = setInterval(
      () => {
        if (ownership.renewal || ownership.stopping) return;
        void refreshDiscordGatewayOwnership(ownership);
      },
      options.discordGatewayLeaseRenewalIntervalMs ??
        (options.discordGatewayLeaseTtlMs ?? DISCORD_GATEWAY_LEASE_TTL_MS) / 3,
    );
    ownership.renewTimer.unref?.();
  }

  async function acquireDiscordGatewayOwnership(
    endpoint: EndpointRow,
    context: RuntimeContext,
    waitForOwnership: boolean,
  ): Promise<DiscordGatewayOwnership | null> {
    const local = discordGatewayOwnerships.get(endpoint.id);
    if (
      local &&
      !local.stopping &&
      local.context.version === context.version &&
      local.expiresAt.getTime() > Date.now()
    ) {
      return local;
    }
    if (local) await stopDiscordGatewayOwnership(local);

    const token = randomUUID();
    const deadline =
      Date.now() +
      (waitForOwnership
        ? (options.discordGatewayLeaseWaitMs ?? DISCORD_GATEWAY_LEASE_WAIT_MS)
        : 0);
    for (;;) {
      if (shuttingDown) return null;
      const now = new Date();
      const expiresAt = new Date(
        now.getTime() +
          (options.discordGatewayLeaseTtlMs ?? DISCORD_GATEWAY_LEASE_TTL_MS),
      );
      const inserted = await db
        .insert(chatEndpointLeases)
        .values({
          companyId: endpoint.companyId,
          endpointId: endpoint.id,
          leaseKey: DISCORD_GATEWAY_LEASE_KEY,
          token,
          expiresAt,
        })
        .onConflictDoNothing()
        .returning({ id: chatEndpointLeases.id });
      const reclaimed = inserted.length
        ? inserted
        : await db
            .update(chatEndpointLeases)
            .set({ token, expiresAt, updatedAt: now })
            .where(
              and(
                eq(chatEndpointLeases.companyId, endpoint.companyId),
                eq(chatEndpointLeases.endpointId, endpoint.id),
                eq(chatEndpointLeases.leaseKey, DISCORD_GATEWAY_LEASE_KEY),
                lte(chatEndpointLeases.expiresAt, now),
              ),
            )
            .returning({ id: chatEndpointLeases.id });
      if (reclaimed.length) {
        const ownership: DiscordGatewayOwnership = {
          companyId: endpoint.companyId,
          context,
          endpointId: endpoint.id,
          expiresAt,
          leaseKey: DISCORD_GATEWAY_LEASE_KEY,
          renewal: null,
          renewTimer: null,
          stopPromise: null,
          stopping: false,
          token,
        };
        discordGatewayOwnerships.set(endpoint.id, ownership);
        startDiscordGatewayLeaseRenewal(ownership);
        return ownership;
      }
      if (Date.now() >= deadline) return null;
      await new Promise((resolve) =>
        setTimeout(resolve, DISCORD_GATEWAY_LEASE_POLL_MS),
      );
    }
  }

  function localRuntimeEpoch(endpointId: string): number {
    return runtimeLocalEpochs.get(endpointId) ?? 0;
  }

  function runtimeContextForRecord(
    record: NonNullable<Awaited<ReturnType<typeof endpointRecord>>>,
  ): RuntimeContext {
    const generation = runtimeGeneration(record.endpoint.setup);
    const refsFingerprint = credentialFingerprint(record.credentialSecretRefs);
    const localEpoch = localRuntimeEpoch(record.endpoint.id);
    return {
      credentialFingerprint: refsFingerprint,
      generation,
      localEpoch,
      version: `${generation}:${refsFingerprint}:${localEpoch}`,
    };
  }

  async function invalidateRuntime(endpointId: string): Promise<boolean> {
    runtimeLocalEpochs.set(endpointId, localRuntimeEpoch(endpointId) + 1);
    runtimeVersions.delete(endpointId);
    const discordOwnership = discordGatewayOwnerships.get(endpointId);
    if (discordOwnership) {
      const hadRuntime = runtime.get(endpointId) !== null;
      await stopDiscordGatewayOwnership(discordOwnership);
      return hadRuntime;
    }
    return await runtime.removeEndpoint(endpointId);
  }

  function scheduleMessageProcessing(task: () => Promise<void>) {
    if (shuttingDown) return;
    const schedule = options.scheduleDeferredWork ?? setImmediate;
    schedule(() => {
      if (shuttingDown) return;
      const pending = task().catch((error) => {
        logger.error(
          { error: redactError(error) },
          "deferred external chat message processing failed",
        );
      });
      backgroundMessageTasks.add(pending);
      void pending.finally(() => backgroundMessageTasks.delete(pending));
    });
  }

  function retryableGitHubWebhookResponse(): Response {
    return new Response(
      "Paperclip could not durably accept the event in time",
      {
        status: 503,
        headers: {
          "content-type": "text/plain; charset=utf-8",
          "retry-after": "1",
        },
      },
    );
  }

  async function addReceiptReaction(input: {
    deliveryId: string;
    endpoint: EndpointRow;
    message: Message;
    runtimeContext?: LifecycleRuntimeFence;
    thread: Thread;
  }): Promise<void> {
    const record = await endpointRecord(input.endpoint.id);
    if (!record) return;
    // A live SDK object remains bound to the credentials that authenticated
    // its callback. Preserve that original fence rather than sampling the
    // endpoint again after a rotation and accidentally blessing an obsolete
    // adapter with the new generation.
    const context = input.runtimeContext ?? runtimeContextForRecord(record);
    const [inserted] = await db
      .insert(chatActions)
      .values({
        companyId: input.endpoint.companyId,
        endpointId: input.endpoint.id,
        deliveryId: input.deliveryId,
        kind: "receipt_reaction",
        providerActionId: `receipt_reaction:${input.deliveryId}`,
        payload: {
          version: 1,
          operation: "add",
          threadId: input.thread.id,
          messageId: input.message.id,
          reaction: "eyes",
          runtimeGeneration: context.generation,
          credentialFingerprint: context.credentialFingerprint,
        } satisfies ReceiptReactionPayload,
        status: "received",
      })
      .onConflictDoNothing()
      .returning({ id: chatActions.id });
    const actionId =
      inserted?.id ??
      (await db
        .select({ id: chatActions.id })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, input.endpoint.id),
            eq(
              chatActions.providerActionId,
              `receipt_reaction:${input.deliveryId}`,
            ),
          ),
        )
        .then((rows) => rows[0]?.id ?? null));
    if (!actionId) return;
    await options.receiptReactionTransportBarrier?.();
    await processReceiptReaction(actionId);
  }

  function conversationDrainKey(endpointId: string, threadId: string) {
    return `${endpointId}:${createHash("sha256").update(durableExternalThreadIdentity(threadId)).digest("hex")}`;
  }

  function scheduleConversationDrain(
    endpointId: string,
    threadId: string,
    drainAt = Date.now(),
  ) {
    if (shuttingDown) return;
    const key = conversationDrainKey(endpointId, threadId);
    const scheduledAt = scheduledConversationDrains.get(key);
    if (scheduledAt !== undefined) return;
    scheduledConversationDrains.set(key, drainAt);
    scheduleMessageProcessing(async () => {
      try {
        while (!shuttingDown) {
          const target = scheduledConversationDrains.get(key);
          if (target === undefined) return;
          const remaining = target - Date.now();
          if (remaining > 0) {
            await new Promise((resolve) => setTimeout(resolve, remaining));
            continue;
          }
          const shouldContinue = await drainConversationDeliveries(
            endpointId,
            threadId,
          );
          if (shouldContinue) {
            scheduledConversationDrains.set(key, Date.now());
            continue;
          }
          return;
        }
      } finally {
        scheduledConversationDrains.delete(key);
      }
    });
  }

  async function endpointRecord(endpointId: string) {
    return db
      .select({
        endpoint: chatEndpoints,
        assignedAgentName: agents.name,
        connectionName: toolConnections.name,
        applicationId: toolConnections.applicationId,
        credentialSecretRefs: toolConnections.credentialSecretRefs,
      })
      .from(chatEndpoints)
      .innerJoin(
        agents,
        and(
          eq(agents.id, chatEndpoints.assignedAgentId),
          eq(agents.companyId, chatEndpoints.companyId),
        ),
      )
      .innerJoin(
        toolConnections,
        and(
          eq(toolConnections.id, chatEndpoints.connectionId),
          eq(toolConnections.companyId, chatEndpoints.companyId),
        ),
      )
      .where(eq(chatEndpoints.id, endpointId))
      .then((rows) => rows[0] ?? null);
  }

  async function processReceiptReaction(actionId: string): Promise<void> {
    const initialAction = await db
      .select({ endpointId: chatActions.endpointId })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "receipt_reaction"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!initialAction) return;
    const initialEndpoint = await endpointRecord(initialAction.endpointId);
    if (!initialEndpoint) return;
    // Receipt reactions are GitHub repository mutations too. Serialize their
    // final runtime-fence check and provider call with reconnect, secret
    // rotation, pause, and removal so credentials cannot become obsolete
    // between authorization and transport.
    await withCredentialMutationLease(initialEndpoint.endpoint, (lease) =>
      processReceiptReactionWithCredentialLease(actionId, lease),
    );
  }

  async function processReceiptReactionWithCredentialLease(
    actionId: string,
    credentialLease: CredentialMutationLeaseGuard,
  ): Promise<void> {
    let action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "receipt_reaction"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!action || ["processed", "cancelled"].includes(action.status)) return;
    const payload = receiptReactionPayload(action.payload);
    if (!payload) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            code: "receipt_reaction_payload_invalid",
            retryable: false,
          },
          updatedAt: new Date(),
        })
        .where(eq(chatActions.id, action.id));
      return;
    }
    if (payload.operation === "add" && action.deliveryId) {
      const terminalRemoval = await db
        .select({ id: chatActions.id })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, action.endpointId),
            eq(
              chatActions.providerActionId,
              `receipt_reaction_remove:${action.deliveryId}`,
            ),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (terminalRemoval) {
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await tx
            .update(chatActions)
            .set({
              status: "cancelled",
              result: {
                ...(typeof action!.result?.attempts === "number"
                  ? { attempts: action!.result.attempts }
                  : {}),
                code: "receipt_reaction_superseded_by_terminal_publication",
              },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action!.id),
                eq(chatActions.status, action!.status),
              ),
            );
          await credentialLease.assertOwned(tx);
        });
        return;
      }
    }
    if (action.status === "processing") {
      if (action.updatedAt > new Date(Date.now() - PROVIDER_EFFECT_STALE_MS))
        return;
      // Adding or removing the same reaction is idempotent. A worker
      // interruption can be retried safely without an ambiguous
      // duplicate-message boundary.
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            ...(action.result ?? {}),
            retryable: true,
            retryAt: new Date().toISOString(),
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
            eq(chatActions.updatedAt, action.updatedAt),
          ),
        );
      action = await db
        .select()
        .from(chatActions)
        .where(eq(chatActions.id, action.id))
        .then((rows) => rows[0] ?? null);
      if (!action) return;
    }
    if (action.status === "failed") {
      if (action.result?.retryable !== true) return;
      const retryAt =
        typeof action.result.retryAt === "string"
          ? new Date(action.result.retryAt)
          : null;
      if (retryAt && retryAt > new Date()) return;
    } else if (action.status !== "received") {
      return;
    }
    const attempt =
      (typeof action.result?.attempts === "number" ? action.result.attempts : 0) +
      1;
    const retainedGitHubReceipt = parseGitHubReceiptIdentity(
      action.result?.githubReceipt,
    );
    const [claimed] = await db.transaction(async (tx) => {
      await credentialLease.assertOwned(tx);
      const rows = await tx
        .update(chatActions)
        .set({
          status: "processing",
          result: {
            attempts: attempt,
            ...(retainedGitHubReceipt
              ? { githubReceipt: retainedGitHubReceipt }
              : {}),
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action!.id),
            eq(chatActions.status, action!.status),
          ),
        )
        .returning();
      await credentialLease.assertOwned(tx);
      return rows;
    });
    if (!claimed) return;

    let reactionProvider: ChatProvider | null = null;
    let githubReceipt: GitHubReceiptIdentity | null = retainedGitHubReceipt;
    try {
      const record = await endpointRecord(action.endpointId);
      if (
        !record ||
        !["verifying", "active"].includes(record.endpoint.status) ||
        runtimeGeneration(record.endpoint.setup) !== payload.runtimeGeneration ||
        credentialFingerprint(record.credentialSecretRefs) !==
          payload.credentialFingerprint
      ) {
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await tx
            .update(chatActions)
            .set({
              status: "cancelled",
              result: {
                attempts: attempt,
                code: "receipt_reaction_runtime_superseded",
              },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action!.id),
                eq(chatActions.status, "processing"),
                sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
              ),
            );
          await credentialLease.assertOwned(tx);
        });
        return;
      }
      reactionProvider = record.endpoint.provider;
      // Resolve the adapter only after acquiring the credential lease and
      // proving the action's durable generation/fingerprint is still current.
      // Never reuse the live callback's adapter: it may hold an installation
      // token minted by a superseded private key.
      const endpointRuntime = await runtimeFor(record.endpoint);
      const adapter = endpointRuntime.thread(payload.threadId).adapter;
      await credentialLease.assertOwned();
      if (record.endpoint.provider === "slack") {
        await endpointRuntime.applySlackReceiptReaction(payload, fetchImpl);
      } else if (record.endpoint.provider === "github") {
        const assertCurrent = async () => {
          await credentialLease.assertOwned();
          const [current] = await db
            .select({ endpoint: chatEndpoints, connection: toolConnections })
            .from(chatEndpoints)
            .innerJoin(
              toolConnections,
              and(
                eq(toolConnections.id, chatEndpoints.connectionId),
                eq(toolConnections.companyId, chatEndpoints.companyId),
              ),
            )
            .where(
              and(
                eq(chatEndpoints.id, action!.endpointId),
                eq(chatEndpoints.companyId, action!.companyId),
              ),
            )
            .limit(1);
          if (
            !current ||
            !["active", "verifying"].includes(current.endpoint.status) ||
            !current.connection.enabled ||
            current.connection.status !== "active" ||
            runtimeGeneration(current.endpoint.setup) !==
              payload.runtimeGeneration ||
            credentialFingerprint(current.connection.credentialSecretRefs) !==
              payload.credentialFingerprint ||
            runtime.get(action!.endpointId) !== endpointRuntime
          )
            throw new Error("GitHub receipt authority is no longer current");
        };
        const applied = await endpointRuntime.applyGitHubReceiptReaction(
          { ...payload, ...(githubReceipt ? { githubReceipt } : {}) },
          assertCurrent,
          fetchImpl,
        );
        githubReceipt = parseGitHubReceiptIdentity(applied);
        if (
          !githubReceipt ||
          (payload.operation === "add" && !githubReceipt.reactionId)
        )
          throw new Error("GitHub receipt identity was not confirmed");
      } else if (payload.operation === "remove") {
        await adapter.removeReaction(
          payload.threadId,
          payload.messageId,
          payload.reaction,
        );
      } else {
        await adapter.addReaction(
          payload.threadId,
          payload.messageId,
          payload.reaction,
        );
      }
      // The provider may already have accepted the idempotent reaction. Fence
      // the local success receipt so a reclaimed lease cannot report success
      // for an obsolete runtime.
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const processed = await tx
          .update(chatActions)
          .set({
            status: "processed",
            result: {
              attempts: attempt,
              ...(githubReceipt ? { githubReceipt } : {}),
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, action.id),
              eq(chatActions.status, "processing"),
              sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
            ),
          )
          .returning({ id: chatActions.id });
        if (!processed.length) {
          throw new Error(
            "Receipt-reaction ownership changed before success settlement",
          );
        }
        if (action.deliveryId) {
          await tx
            .update(chatDeliveries)
            .set({ redactedError: null, updatedAt: new Date() })
            .where(
              and(
                eq(chatDeliveries.id, action.deliveryId),
                eq(chatDeliveries.state, "processed"),
                like(chatDeliveries.redactedError, "Receipt reaction %"),
              ),
            );
        }
        await credentialLease.assertOwned(tx);
      });
    } catch (error) {
      if (
        payload.operation === "add" &&
        reactionProvider === "slack" &&
        isSlackReceiptReactionAlreadyApplied(error)
      ) {
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const processed = await tx
            .update(chatActions)
            .set({
              status: "processed",
              result: {
                attempts: attempt,
                code: "receipt_reaction_already_applied",
              },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action!.id),
                eq(chatActions.status, "processing"),
                sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
              ),
            )
            .returning({ id: chatActions.id });
          if (!processed.length) {
            throw new Error(
              "Receipt-reaction ownership changed before idempotent settlement",
            );
          }
          if (action.deliveryId) {
            await tx
              .update(chatDeliveries)
              .set({ redactedError: null, updatedAt: new Date() })
              .where(
                and(
                  eq(chatDeliveries.id, action.deliveryId),
                  eq(chatDeliveries.state, "processed"),
                  like(chatDeliveries.redactedError, "Receipt reaction %"),
                ),
              );
          }
          await credentialLease.assertOwned(tx);
        });
        return;
      }
      const disposition = classifyChatPublicationError(error, attempt);
      const retryable =
        disposition.kind === "retry" ||
        (disposition.kind === "delivery_unknown" && attempt < 3);
      const retryAfterMs =
        disposition.kind === "retry"
          ? disposition.retryAfterMs
          : 100 * 2 ** Math.max(0, attempt - 1);
      const operationLabel =
        payload.operation === "remove" ? " reaction removal" : " reaction";
      const diagnostic =
        `Receipt${operationLabel} ${retryable ? "deferred" : "failed"} after ${attempt} attempt${attempt === 1 ? "" : "s"} (${disposition.kind}): ${redactError(error)}`.slice(
          0,
          MAX_ERROR_TEXT,
        );
      const retryAt = retryable
        ? new Date(Date.now() + retryAfterMs).toISOString()
        : null;
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const [failed] = await tx
          .update(chatActions)
          .set({
            status: "failed",
            result: {
              attempts: attempt,
              ...(githubReceipt ? { githubReceipt } : {}),
              code:
                payload.operation === "remove"
                  ? `receipt_reaction_removal_${disposition.kind}`
                  : `receipt_reaction_${disposition.kind}`,
              redactedError: diagnostic,
              retryable,
              retryAt,
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, action.id),
              eq(chatActions.status, "processing"),
              sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
            ),
          )
          .returning({ id: chatActions.id });
        if (failed && action.deliveryId) {
          await tx
            .update(chatDeliveries)
            .set({ redactedError: diagnostic, updatedAt: new Date() })
            .where(
              and(
                eq(chatDeliveries.id, action.deliveryId),
                eq(chatDeliveries.state, "processed"),
              ),
            );
        }
        await credentialLease.assertOwned(tx);
      });
      logger.warn(
        {
          endpointId: action.endpointId,
          deliveryId: action.deliveryId,
          attempts: attempt,
          disposition: disposition.kind,
          operation: payload.operation,
          retryAt,
        },
        "external chat receipt reaction deferred",
      );
    }
  }

  async function processPendingReceiptReactions(
    limit = 25,
    onlyActionId?: string,
  ) {
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    const actions = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "receipt_reaction"),
          ...(onlyActionId ? [eq(chatActions.id, onlyActionId)] : []),
          or(
            eq(chatActions.status, "received"),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, staleBefore),
            ),
            and(
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'true'`,
              sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.createdAt))
      .limit(limit);
    for (const action of actions) await processReceiptReaction(action.id);
    return actions.length;
  }

  async function stageTelegramMaintenance(
    endpoint: EndpointRow,
    operation: TelegramMaintenancePayload["operation"],
  ) {
    const record = await endpointRecord(endpoint.id);
    if (!record) throw notFound("Chat endpoint not found");
    const context = runtimeContextForRecord(record);
    const subscriptionScope =
      operation === "stop_subscription"
        ? telegramStopSubscriptionScope(record.endpoint, context)
        : null;
    if (operation === "stop_subscription" && !subscriptionScope) return null;
    const operationGeneration = subscriptionScope
      ? `${context.generation}:${context.credentialFingerprint}:${subscriptionScope.botUserId}:${subscriptionScope.webhookUrlSha256}`
      : operation === "register_commands"
        ? `${context.generation}:${record.endpoint.setup.testStartedAt ?? record.endpoint.updatedAt.toISOString()}`
        : String(context.generation);
    const providerActionId = `telegram_maintenance:${operation}:${operationGeneration}`;
    const [inserted] = await db
      .insert(chatActions)
      .values({
        companyId: endpoint.companyId,
        endpointId: endpoint.id,
        kind: "telegram_maintenance",
        providerActionId,
        payload: {
          version: 1,
          operation,
          runtimeGeneration: context.generation,
          credentialFingerprint: context.credentialFingerprint,
          ...(subscriptionScope
            ? {
                webhookUrlSha256: subscriptionScope.webhookUrlSha256,
                botUserId: subscriptionScope.botUserId,
              }
            : {}),
        } satisfies TelegramMaintenancePayload,
        status: "received",
      })
      .onConflictDoNothing()
      .returning();
    return (
      inserted ??
      (await db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, endpoint.id),
            eq(chatActions.providerActionId, providerActionId),
          ),
        )
        .then((rows) => rows[0] ?? null))
    );
  }

  async function telegramMaintenanceRequest(
    botToken: string,
    method: "deleteWebhook" | "deleteMyCommands" | "setMyCommands",
    body: Record<string, unknown>,
  ): Promise<void> {
    const response = await fetchImpl(
      `https://api.telegram.org/bot${encodeURIComponent(botToken)}/${method}`,
      {
        method: "POST",
        signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS),
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
      },
    );
    const result = (await response.json()) as {
      ok?: boolean;
      description?: string;
      parameters?: { retry_after?: number };
    };
    if (response.ok && result.ok) return;
    throw Object.assign(
      new Error(
        `Telegram ${method} failed: ${result.description ?? response.status}`,
      ),
      response.status === 429
        ? {
            adapter: "telegram",
            code: "RATE_LIMITED",
            name: "AdapterRateLimitError",
            retryAfter: result.parameters?.retry_after,
            response: { status: response.status, headers: response.headers },
          }
        : {
            adapter: "telegram",
            status: response.status,
            response: { status: response.status, headers: response.headers },
          },
    );
  }

  async function processTelegramMaintenance(
    actionId: string,
    force = false,
    credentialLease?: CredentialMutationLeaseGuard,
  ): Promise<"processed" | "pending" | "failed"> {
    if (!credentialLease) {
      const initialAction = await db
        .select({ endpointId: chatActions.endpointId })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.id, actionId),
            eq(chatActions.kind, "telegram_maintenance"),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (!initialAction) return "failed";
      const initialEndpoint = await endpointRecord(initialAction.endpointId);
      if (!initialEndpoint) return "failed";
      // Recovery sweeps run independently from endpoint configuration. Hold
      // the same durable credential lease as reconnect, pause, and removal so
      // a stale bot token cannot mutate Telegram after its final runtime fence
      // but before transport.
      return withCredentialMutationLease(initialEndpoint.endpoint, (lease) =>
        processTelegramMaintenance(actionId, force, lease),
      );
    }
    let action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "telegram_maintenance"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!action) return "failed";
    if (action.status === "processed") return "processed";
    const payload = telegramMaintenancePayload(action.payload);
    if (!payload) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            code: "telegram_maintenance_payload_invalid",
            retryable: false,
          },
          updatedAt: new Date(),
        })
        .where(eq(chatActions.id, action.id));
      return "failed";
    }
    if (action.status === "processing") {
      if (action.updatedAt > new Date(Date.now() - PROVIDER_EFFECT_STALE_MS))
        return "pending";
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            ...(action.result ?? {}),
            retryable: true,
            retryAt: new Date().toISOString(),
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
            eq(chatActions.updatedAt, action.updatedAt),
          ),
        );
      action = await db
        .select()
        .from(chatActions)
        .where(eq(chatActions.id, action.id))
        .then((rows) => rows[0] ?? null);
      if (!action) return "failed";
    }
    if (action.status === "failed") {
      if (action.result?.retryable !== true && !force) return "failed";
      const retryAt =
        typeof action.result?.retryAt === "string"
          ? new Date(action.result.retryAt)
          : null;
      if (!force && retryAt && retryAt > new Date()) return "pending";
    } else if (action.status !== "received") {
      return "failed";
    }
    const attempt =
      (typeof action.result?.attempts === "number"
        ? action.result.attempts
        : 0) + 1;
    let providerConfirmed = action.result?.providerConfirmed === true;
    const [claimed] = await db.transaction(async (tx) => {
      await credentialLease.assertOwned(tx);
      const rows = await tx
        .update(chatActions)
        .set({
          status: "processing",
          result: { attempts: attempt, providerConfirmed },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action!.id),
            eq(chatActions.status, action!.status),
          ),
        )
        .returning();
      await credentialLease.assertOwned(tx);
      return rows;
    });
    if (!claimed) return "pending";

    try {
      const record = await endpointRecord(action.endpointId);
      if (!record || record.endpoint.provider !== "telegram") {
        throw Object.assign(new Error("Telegram endpoint is unavailable"), {
          code: "CHAT_PROVIDER_PRETRANSPORT_REJECTED",
        });
      }
      if (
        payload.operation === "remove_endpoint" &&
        record.credentialSecretRefs.length === 0
      ) {
        // Recovery may observe the narrow crash window after provider cleanup
        // and credential clearing but before the action receipt was committed.
        // Empty refs prove removal cleanup crossed its final local boundary;
        // settle the idempotent action instead of misclassifying it as a
        // credential rotation.
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await tx
            .update(chatActions)
            .set({
              status: "processed",
              result: { attempts: attempt, providerConfirmed: true },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action!.id),
                eq(chatActions.status, "processing"),
                sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
              ),
            );
          await credentialLease.assertOwned(tx);
        });
        return "processed";
      }
      if (
        credentialFingerprint(record.credentialSecretRefs) !==
          payload.credentialFingerprint ||
        (payload.operation !== "remove_endpoint" &&
          runtimeGeneration(record.endpoint.setup) !==
            payload.runtimeGeneration)
      ) {
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await tx
            .update(chatActions)
            .set({
              status: "cancelled",
              result: {
                attempts: attempt,
                code: "telegram_maintenance_credentials_superseded",
              },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action!.id),
                eq(chatActions.status, "processing"),
                sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
              ),
            );
          await credentialLease.assertOwned(tx);
        });
        return "failed";
      }
      if (!providerConfirmed || payload.operation === "stop_subscription") {
        const credentials = await resolveCredentials(record.endpoint);
        if (!credentials.botToken) {
          throw Object.assign(new Error("Telegram bot token is unavailable"), {
            code: "CHAT_PROVIDER_PRETRANSPORT_REJECTED",
          });
        }
        if (payload.operation === "stop_subscription") {
          await repairTelegramStopSubscription(
            record.endpoint,
            payload,
            credentialLease,
          );
          providerConfirmed = true;
        } else if (payload.operation === "register_commands") {
          await credentialLease.assertOwned();
          await telegramMaintenanceRequest(
            credentials.botToken,
            "setMyCommands",
            { commands: TELEGRAM_COMMANDS },
          );
          providerConfirmed = true;
        } else {
          await credentialLease.assertOwned();
          await telegramMaintenanceRequest(
            credentials.botToken,
            "deleteWebhook",
            { drop_pending_updates: false },
          );
          await credentialLease.assertOwned();
          await telegramMaintenanceRequest(
            credentials.botToken,
            "deleteMyCommands",
            {},
          );
          providerConfirmed = true;
        }
        await credentialLease.assertOwned();
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const confirmed = await tx
            .update(chatActions)
            .set({
              result: { attempts: attempt, providerConfirmed: true },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action.id),
                eq(chatActions.status, "processing"),
                sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
              ),
            )
            .returning({ id: chatActions.id });
          if (!confirmed.length) {
            throw new Error(
              "Telegram maintenance ownership changed before provider confirmation",
            );
          }
          await credentialLease.assertOwned(tx);
        });
      }
      if (payload.operation === "remove_endpoint") {
        await credentialLease.assertOwned();
        await clearCredentials(record.endpoint, credentialLease);
      }
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const processed = await tx
          .update(chatActions)
          .set({
            status: "processed",
            result: { attempts: attempt, providerConfirmed: true },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, action.id),
              eq(chatActions.status, "processing"),
              sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
            ),
          )
          .returning({ id: chatActions.id });
        if (!processed.length) {
          throw new Error(
            "Telegram maintenance ownership changed before success settlement",
          );
        }
        await credentialLease.assertOwned(tx);
      });
      await logActivity(db, {
        companyId: record.endpoint.companyId,
        actorType: "system",
        actorId: "chat-maintenance",
        action: `chat_endpoint.telegram_${payload.operation}_completed`,
        entityType: "tool_connection",
        entityId: record.endpoint.connectionId,
        details: { endpointId: record.endpoint.id, attempt },
      });
      return "processed";
    } catch (error) {
      const disposition = classifyChatPublicationError(error, attempt);
      // Webhook/menu mutations are idempotent provider operations. A lost
      // response is safe to retry, and an explicit provider Retry-After must
      // remain durable rather than occupying an in-memory timer.
      const retryable =
        disposition.kind === "retry" || disposition.kind === "delivery_unknown";
      const retryAfterMs =
        disposition.kind === "retry"
          ? disposition.retryAfterMs
          : Math.min(60_000, 1_000 * 2 ** Math.max(0, attempt - 1));
      const retryAt = retryable
        ? new Date(Date.now() + retryAfterMs).toISOString()
        : null;
      const diagnostic = redactError(error);
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            attempts: attempt,
            code: `telegram_maintenance_${disposition.kind}`,
            providerConfirmed:
              providerConfirmed || action.result?.providerConfirmed === true,
            redactedError: diagnostic,
            retryable,
            retryAt,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
            sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
          ),
        );
      await logActivity(db, {
        companyId: action.companyId,
        actorType: "system",
        actorId: "chat-maintenance",
        action: `chat_endpoint.telegram_${payload.operation}_deferred`,
        entityType: "tool_connection",
        entityId:
          (await endpointRecord(action.endpointId))?.endpoint.connectionId ??
          action.endpointId,
        details: {
          endpointId: action.endpointId,
          attempt,
          disposition: disposition.kind,
          retryAt,
        },
      }).catch((auditError) => {
        logger.error(
          { endpointId: action!.endpointId, error: redactError(auditError) },
          "could not persist Telegram maintenance deferral audit",
        );
      });
      logger.warn(
        {
          endpointId: action.endpointId,
          operation: payload.operation,
          retryAt,
        },
        "Telegram maintenance was deferred",
      );
      return retryable ? "pending" : "failed";
    }
  }

  async function processPendingTelegramMaintenance(limit = 25) {
    // Keyset scanning bounds each sweep without starving endpoints behind a
    // page whose subscriptions were already confirmed. No provider I/O here.
    const candidates = await db
      .select({ endpoint: chatEndpoints })
      .from(chatEndpoints)
      .innerJoin(
        toolConnections,
        and(
          eq(toolConnections.id, chatEndpoints.connectionId),
          eq(toolConnections.companyId, chatEndpoints.companyId),
        ),
      )
      .where(
        and(
          eq(chatEndpoints.provider, "telegram"),
          eq(chatEndpoints.status, "active"),
          eq(toolConnections.status, "active"),
          eq(toolConnections.enabled, true),
          telegramSubscriptionScanAfter
            ? gt(chatEndpoints.id, telegramSubscriptionScanAfter)
            : undefined,
        ),
      )
      .orderBy(asc(chatEndpoints.id))
      .limit(Math.max(1, Math.min(limit, 100)));
    telegramSubscriptionScanAfter =
      candidates.length >= Math.max(1, Math.min(limit, 100))
        ? candidates.at(-1)!.endpoint.id
        : null;
    for (const { endpoint } of candidates) {
      try {
        const record = await endpointRecord(endpoint.id);
        if (
          record &&
          !(await hasTelegramStopSubscription(
            record.endpoint,
            runtimeContextForRecord(record),
          ))
        )
          await stageTelegramMaintenance(record.endpoint, "stop_subscription");
      } catch {
        logger.warn(
          { endpointId: endpoint.id },
          "Telegram subscription maintenance could not be staged",
        );
      }
    }
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    const actions = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "telegram_maintenance"),
          sql`(${chatActions.payload}->>'operation' <> 'stop_subscription' or exists (
            select 1 from ${chatEndpoints} inner join ${toolConnections}
              on ${toolConnections.id} = ${chatEndpoints.connectionId} and ${toolConnections.companyId} = ${chatEndpoints.companyId}
            where ${chatEndpoints.id} = ${chatActions.endpointId} and ${chatEndpoints.companyId} = ${chatActions.companyId}
              and ${chatEndpoints.provider} = 'telegram' and ${chatEndpoints.status} = 'active'
              and ${toolConnections.status} = 'active' and ${toolConnections.enabled} = true
          ))`,
          or(
            eq(chatActions.status, "received"),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, staleBefore),
            ),
            and(
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'true'`,
              sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.createdAt))
      .limit(limit);
    for (const action of actions) await processTelegramMaintenance(action.id);
    return actions.length;
  }

  async function stageProviderEffect(
    database: DbOrTransaction,
    input: {
      endpoint: EndpointRow;
      deliveryId?: string | null;
      conversationId?: string | null;
      principalId?: string | null;
      providerActionId: string;
      payload: Omit<
        ProviderEffectPayload,
        "runtimeGeneration" | "credentialFingerprint"
      >;
      runtimeContext: LifecycleRuntimeFence;
    },
  ) {
    const [inserted] = await database
      .insert(chatActions)
      .values({
        companyId: input.endpoint.companyId,
        endpointId: input.endpoint.id,
        deliveryId: input.deliveryId ?? null,
        conversationId: input.conversationId ?? null,
        principalId: input.principalId ?? null,
        kind: "provider_effect",
        providerActionId: input.providerActionId,
        payload: {
          ...input.payload,
          runtimeGeneration: input.runtimeContext.generation,
          credentialFingerprint: input.runtimeContext.credentialFingerprint,
        },
        status: "received",
      })
      .onConflictDoNothing()
      .returning();
    if (inserted) return inserted;
    return database
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.endpointId, input.endpoint.id),
          eq(chatActions.providerActionId, input.providerActionId),
          eq(chatActions.kind, "provider_effect"),
        ),
      )
      .then((rows) => rows[0] ?? null);
  }

  async function stageAuthorizedTaskControlPublication(
    tx: DbOrTransaction,
    input: {
      companyId: string;
      conversationId: string;
      endpointId: string;
      idempotencyKey: string;
      issueId: string;
      payload: SafeChatPublicationPayload;
      principalId: string;
    },
  ) {
    const [inserted] = await tx
      .insert(chatPublications)
      .values({
        companyId: input.companyId,
        endpointId: input.endpointId,
        conversationId: input.conversationId,
        issueId: input.issueId,
        idempotencyKey: input.idempotencyKey,
        payload: input.payload,
        state: "pending",
      })
      .onConflictDoNothing()
      .returning({ id: chatPublications.id });
    const publication =
      inserted ??
      (await tx
        .select({ id: chatPublications.id })
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, input.companyId),
            eq(chatPublications.idempotencyKey, input.idempotencyKey),
          ),
        )
        .then((rows) => rows[0] ?? null));
    if (!publication) {
      throw new Error("Task-control publication was not persisted");
    }
    await tx
      .insert(chatActions)
      .values({
        companyId: input.companyId,
        endpointId: input.endpointId,
        conversationId: input.conversationId,
        principalId: input.principalId,
        kind: "task_control_authorization",
        providerActionId: `task-control-authorization:${publication.id}`,
        payload: { publicationId: publication.id },
        status: "issued",
      })
      .onConflictDoNothing();
    return publication;
  }

  function providerEffectDisposition(
    error: unknown,
    attempt: number,
    providerEffectCompleted: boolean,
  ) {
    if (!providerEffectCompleted)
      return classifyChatPublicationError(error, attempt);
    return {
      kind: "delivery_unknown" as const,
      reason:
        "Provider effect completed, but Paperclip could not confirm its durable result",
    };
  }

  async function finalizeProviderEffectFailure(input: {
    action: typeof chatActions.$inferSelect;
    endpoint: EndpointRow;
    payload: ProviderEffectPayload;
    disposition: ReturnType<typeof providerEffectDisposition>;
    attempt: number;
  }): Promise<boolean> {
    const failure = redactSensitiveText(input.disposition.reason).slice(
      0,
      MAX_ERROR_TEXT,
    );
    const retryable = input.disposition.kind === "retry";
    const retryAt =
      input.disposition.kind === "retry"
        ? new Date(Date.now() + input.disposition.retryAfterMs)
        : null;
    let invalidateCurrentRuntime = false;
    const finalized = await db.transaction(async (tx) => {
      // Admission locks the endpoint before its delivery. Keep that order
      // when failure settlement also needs to change endpoint/resource health.
      const currentEndpoint =
        input.disposition.kind === "endpoint_attention" ||
        input.disposition.kind === "resource_unavailable"
          ? await runtimeCallbackEndpoint(
              tx,
              input.endpoint.id,
              {
                generation: input.payload.runtimeGeneration,
                credentialFingerprint: input.payload.credentialFingerprint,
              },
              ["verifying", "active"],
            )
          : null;
      const [ownedAction] = await tx
        .update(chatActions)
        .set({
          status:
            input.disposition.kind === "delivery_unknown"
              ? "delivery_unknown"
              : "failed",
          result: {
            code: `provider_effect_${input.disposition.kind}`,
            attempts: input.attempt,
            redactedError: failure,
            retryable,
            retryAt: retryAt?.toISOString() ?? null,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, input.action.id),
            eq(chatActions.status, "processing"),
            sql`(${chatActions.result}->>'attempts')::int = ${input.attempt}`,
          ),
        )
        .returning({ id: chatActions.id });
      if (!ownedAction) return false;
      if (input.payload.settleDelivery && input.action.deliveryId) {
        await tx
          .update(chatDeliveries)
          .set({
            state: retryable ? "retry" : "failed",
            nextAttemptAt: retryAt,
            redactedError:
              input.disposition.kind === "delivery_unknown"
                ? `Provider response is unconfirmed: ${failure}`.slice(
                    0,
                    MAX_ERROR_TEXT,
                  )
                : failure,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatDeliveries.id, input.action.deliveryId),
              eq(chatDeliveries.state, "processing"),
            ),
          );
      }
      if (input.disposition.kind === "endpoint_attention" && currentEndpoint) {
        await tx
          .update(chatEndpoints)
          .set({
            status: "attention",
            healthMessage: "Provider credentials or permissions need attention",
            lastError: failure,
            updatedAt: new Date(),
          })
          .where(eq(chatEndpoints.id, currentEndpoint.id));
        await tx
          .update(toolConnections)
          .set({
            status: "disabled",
            enabled: false,
            healthStatus: "degraded",
            healthMessage: "Provider credentials or permissions need attention",
            lastError: failure,
            healthCheckedAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(toolConnections.id, currentEndpoint.connectionId));
        invalidateCurrentRuntime = true;
      } else if (
        input.disposition.kind === "resource_unavailable" &&
        input.payload.resourceId &&
        currentEndpoint
      ) {
        await tx
          .update(chatEndpointResources)
          .set({ availability: "unavailable", updatedAt: new Date() })
          .where(
            and(
              eq(chatEndpointResources.id, input.payload.resourceId),
              eq(chatEndpointResources.endpointId, currentEndpoint.id),
            ),
          );
      }
      return true;
    });
    if (finalized && invalidateCurrentRuntime) {
      await invalidateRuntime(input.endpoint.id).catch(() => undefined);
    }
    return finalized;
  }

  async function quarantineStaleProviderEffect(
    action: typeof chatActions.$inferSelect,
  ) {
    const payload = providerEffectPayload(action.payload);
    const failure =
      "Provider delivery could not be confirmed after the worker stopped. The effect will not be replayed automatically.";
    await db.transaction(async (tx) => {
      const [quarantined] = await tx
        .update(chatActions)
        .set({
          status: "delivery_unknown",
          result: {
            code: "provider_effect_delivery_unknown",
            redactedError: failure,
            retryable: false,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
            eq(chatActions.updatedAt, action.updatedAt),
            sql`(${chatActions.result}->>'attempts')::int = ${
              typeof action.result?.attempts === "number"
                ? action.result.attempts
                : -1
            }`,
            lte(
              chatActions.updatedAt,
              new Date(Date.now() - PROVIDER_EFFECT_STALE_MS),
            ),
          ),
        )
        .returning({ id: chatActions.id });
      if (quarantined && payload?.settleDelivery && action.deliveryId) {
        await tx
          .update(chatDeliveries)
          .set({
            state: "failed",
            nextAttemptAt: null,
            redactedError: failure,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatDeliveries.id, action.deliveryId),
              eq(chatDeliveries.state, "processing"),
            ),
          );
      }
    });
  }

  function providerEffectThreadResourceId(
    provider: ChatProvider,
    threadId: string,
  ): string | null {
    if (provider === "slack") {
      return (
        slackThreadChannelId(threadId) ??
        (!threadId.includes(":") ? threadId : null)
      );
    }
    if (provider === "telegram") {
      return /^telegram:([^:]+)/.exec(threadId)?.[1] ?? null;
    }
    if (provider === "github") {
      return /^github:([^:]+)/.exec(threadId)?.[1]?.toLowerCase() ?? null;
    }
    if (provider === "discord") {
      return /^discord:[^:]+:([^:]+)/.exec(threadId)?.[1] ?? null;
    }
    const conversationId = teamsConversationId(threadId);
    return conversationId ? baseTeamsConversationId(conversationId) : null;
  }

  // This is permission to return one fixed, neutral callback denial, not
  // permission to execute the denied action or publish to the conversation.
  // Retain the initial identity-policy snapshot so queued notices cannot cross
  // a subsequent actor/link/reach change. No provider I/O occurs under locks.
  async function lockTelegramCallbackNoticeAuthority(
    tx: DbTransaction,
    endpoint: EndpointRow,
    receipt: TelegramCallbackReceipt,
    principalId: string | null,
  ): Promise<string | null> {
    if (
      endpoint.provider !== "telegram" ||
      endpoint.status !== "active" ||
      endpoint.companyId !== receipt.companyId ||
      endpoint.id !== receipt.endpointId ||
      endpoint.botExternalId !== receipt.botUserId ||
      !endpoint.providerAccountId ||
      !principalId ||
      Date.now() < receipt.receivedAtMs ||
      Date.now() >= receipt.deadlineAtMs
    )
      return null;
    const resource =
      receipt.chatType === "private"
        ? null
        : await tx
            .select()
            .from(chatEndpointResources)
            .where(
              and(
                eq(chatEndpointResources.companyId, endpoint.companyId),
                eq(chatEndpointResources.endpointId, endpoint.id),
                eq(chatEndpointResources.providerResourceId, receipt.chatId),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null);
    if (
      receipt.chatType === "private"
        ? !endpoint.allowDirectMessages
        : !resource || !nonDirectDestinationAllowed(endpoint, resource)
    )
      return null;
    const principal = await tx
      .select()
      .from(chatExternalPrincipals)
      .where(
        and(
          eq(chatExternalPrincipals.companyId, endpoint.companyId),
          eq(chatExternalPrincipals.provider, endpoint.provider),
          eq(
            chatExternalPrincipals.providerAccountId,
            endpoint.providerAccountId,
          ),
          eq(chatExternalPrincipals.id, principalId),
          eq(chatExternalPrincipals.externalId, receipt.receiverUserId),
        ),
      )
      .for("update")
      .then((rows) => rows[0] ?? null);
    if (!principal || principal.kind !== "user" || principal.isBot) return null;
    const authorization = await lockCurrentPrincipalAuthorization(
      tx,
      endpoint,
      principal.id,
    );
    const link = await tx
      .select({
        status: chatIdentityLinks.status,
        userId: chatIdentityLinks.paperclipUserId,
      })
      .from(chatIdentityLinks)
      .where(
        and(
          eq(chatIdentityLinks.companyId, endpoint.companyId),
          eq(chatIdentityLinks.endpointId, endpoint.id),
          eq(chatIdentityLinks.principalId, principal.id),
        ),
      )
      .then((rows) => rows[0] ?? null);
    return createHash("sha256")
      .update(
        JSON.stringify([
          endpoint.companyId,
          endpoint.id,
          receipt.botUserId,
          resource?.id ?? null,
          principal.id,
          principal.externalId,
          link,
          authorization,
          endpoint.allowUnlinkedPeople,
          endpoint.sponsorUserId,
        ]),
      )
      .digest("hex");
  }

  async function lockCurrentProviderEffectAuthorization(
    tx: DbTransaction,
    action: typeof chatActions.$inferSelect,
    endpoint: EndpointRow,
    payload: ProviderEffectPayload,
  ): Promise<boolean> {
    if (payload.effect === "telegram_callback_notice") {
      const receipt = parseTelegramCallbackReceipt(payload.telegramCallback);
      if (!receipt || !action.deliveryId) return false;
      const delivery = await tx
        .select()
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.id, action.deliveryId),
            eq(chatDeliveries.companyId, action.companyId),
            eq(chatDeliveries.endpointId, action.endpointId),
            eq(chatDeliveries.state, "filtered"),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const retained =
        delivery &&
        parseTelegramCallbackReceipt(delivery.normalizedEvent.telegramCallback);
      if (
        !delivery ||
        delivery.principalId !== action.principalId ||
        retained?.sourceSha256 !== receipt.sourceSha256 ||
        delivery.normalizedEvent.telegramAuthorizationSha256 !==
          payload.telegramAuthorizationSha256
      )
        return false;
      return (
        (await lockTelegramCallbackNoticeAuthority(
          tx,
          endpoint,
          receipt,
          action.principalId,
        )) === payload.telegramAuthorizationSha256
      );
    }
    const conversation = action.conversationId
      ? await tx
          .select()
          .from(chatConversations)
          .where(
            and(
              eq(chatConversations.companyId, endpoint.companyId),
              eq(chatConversations.endpointId, endpoint.id),
              eq(chatConversations.id, action.conversationId),
              inArray(chatConversations.state, ["active", "waiting"]),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null)
      : null;
    if (action.conversationId && !conversation) return false;
    const inferredResourceId = providerEffectThreadResourceId(
      endpoint.provider,
      payload.threadId,
    );
    const resource = await tx
      .select()
      .from(chatEndpointResources)
      .where(
        and(
          eq(chatEndpointResources.companyId, endpoint.companyId),
          eq(chatEndpointResources.endpointId, endpoint.id),
          payload.resourceId || conversation?.resourceId
            ? eq(
                chatEndpointResources.id,
                payload.resourceId ?? conversation!.resourceId!,
              )
            : inferredResourceId
              ? eq(chatEndpointResources.providerResourceId, inferredResourceId)
              : sql`false`,
        ),
      )
      .for("update")
      .then((rows) => rows[0] ?? null);
    const slackChannelId =
      endpoint.provider === "slack"
        ? slackThreadChannelId(payload.threadId)
        : null;
    const isDirectMessage =
      conversation?.isDirectMessage === true ||
      resource?.type === "direct_message" ||
      Boolean(slackChannelId && /^D[A-Z0-9]+$/i.test(slackChannelId));
    const destinationAllowed = isDirectMessage
      ? endpoint.allowDirectMessages
      : nonDirectDestinationAllowed(endpoint, resource);
    if (payload.authorizationMode === "safe_notice") return true;
    if (!destinationAllowed) return false;
    if (!action.principalId) return false;
    return (
      await lockCurrentPrincipalAuthorization(tx, endpoint, action.principalId)
    ).allowed;
  }

  async function cancelUnauthorizedProviderEffect(
    tx: DbTransaction,
    action: typeof chatActions.$inferSelect,
    attempt: number,
  ): Promise<boolean> {
    const [cancelled] = await tx
      .update(chatActions)
      .set({
        status: "cancelled",
        result: {
          attempts: attempt,
          code: "provider_effect_no_longer_authorized",
        },
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(chatActions.id, action.id),
          eq(chatActions.status, "processing"),
          sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
        ),
      )
      .returning({ id: chatActions.id });
    if (!cancelled) return false;
    if (action.deliveryId) {
      await tx
        .update(chatDeliveries)
        .set({
          state: "filtered",
          processedAt: new Date(),
          nextAttemptAt: null,
          redactedError:
            "Provider reply was suppressed because current chat authorization changed",
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, action.deliveryId),
            eq(chatDeliveries.state, "processing"),
          ),
        );
    }
    return true;
  }

  async function processProviderEffect(
    actionId: string,
    liveTarget?: ProviderEffectTarget,
  ): Promise<"processed" | "pending" | "failed" | "delivery_unknown"> {
    const initial = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "provider_effect"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!initial) return "failed";
    const initialEndpoint = await endpointRecord(initial.endpointId);
    if (!initialEndpoint) return "failed";

    const processClaimedEffect = async () => {
      let action = await db
        .select()
        .from(chatActions)
        .where(eq(chatActions.id, actionId))
        .then((rows) => rows[0] ?? null);
      if (!action) return "failed";
      const payload = providerEffectPayload(action.payload);
      if (!payload) {
        await db
          .update(chatActions)
          .set({
            status: "failed",
            result: { code: "provider_effect_payload_invalid" },
            updatedAt: new Date(),
          })
          .where(eq(chatActions.id, action.id));
        return "failed";
      }
      if (action.status === "processed") return "processed";
      if (action.status === "delivery_unknown") return "delivery_unknown";
      if (action.status === "processing") {
        if (action.updatedAt > new Date(Date.now() - PROVIDER_EFFECT_STALE_MS))
          return "pending";
        await quarantineStaleProviderEffect(action);
        return "delivery_unknown";
      }
      if (action.status === "failed") {
        if (action.result?.retryable !== true) return "failed";
        const retryAt =
          typeof action.result.retryAt === "string"
            ? new Date(action.result.retryAt)
            : null;
        if (retryAt && retryAt > new Date()) return "pending";
      } else if (action.status !== "received") {
        return "failed";
      }

      const attempt =
        (typeof action.result?.attempts === "number"
          ? action.result.attempts
          : 0) + 1;
      const record = await endpointRecord(action.endpointId);
      let providerEffectCompleted = false;
      try {
        if (!record) {
          throw Object.assign(
            new Error("Chat endpoint is unavailable for this provider effect"),
            { code: "CHAT_PROVIDER_PRETRANSPORT_REJECTED" },
          );
        }
        return await withCredentialMutationLease(
          record.endpoint,
          async (credentialLease) => {
            const claim = await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              const currentAction = await tx
                .select()
                .from(chatActions)
                .where(
                  and(
                    eq(chatActions.id, action!.id),
                    eq(chatActions.kind, "provider_effect"),
                    eq(chatActions.status, action!.status),
                  ),
                )
                .for("update")
                .then((rows) => rows[0] ?? null);
              if (!currentAction) return null;
              const currentEndpoint = await runtimeCallbackEndpoint(
                tx,
                currentAction.endpointId,
                {
                  generation: payload.runtimeGeneration,
                  credentialFingerprint: payload.credentialFingerprint,
                },
                ["verifying", "active"],
              );
              const authorized = currentEndpoint
                ? await lockCurrentProviderEffectAuthorization(
                    tx,
                    currentAction,
                    currentEndpoint,
                    payload,
                  )
                : false;
              const [transportClaim] = await tx
                .update(chatActions)
                .set({
                  status: "processing",
                  result: { attempts: attempt },
                  updatedAt: new Date(),
                })
                .where(
                  and(
                    eq(chatActions.id, currentAction.id),
                    eq(chatActions.status, currentAction.status),
                  ),
                )
                .returning();
              if (!transportClaim) return null;
              if (!currentEndpoint || !authorized) {
                const cancelled = await cancelUnauthorizedProviderEffect(
                  tx,
                  transportClaim,
                  attempt,
                );
                if (!cancelled) {
                  throw new Error(
                    "Provider effect ownership changed before authorization cancellation",
                  );
                }
                return { outcome: "cancelled" as const };
              }
              await credentialLease.assertOwned(tx);
              return {
                action: transportClaim,
                endpoint: currentEndpoint,
                outcome: "claimed" as const,
              };
            });
            if (!claim) return "pending";
            if (claim.outcome === "cancelled") return "failed";
            action = claim.action;

            // `processing` is the durable, single-owner transport claim and
            // authorization linearization point. Its transaction has committed
            // before provider I/O begins. The renewable credential lease keeps
            // runtime identity stable without holding database row locks.
            let sent: { id: string; threadId: string } | null = null;
            if (payload.effect === "telegram_callback_notice") {
              sent = await (
                await runtimeFor(claim.endpoint)
              ).sendTelegramCallbackNotice(
                payload.telegramCallback!,
                payload.text,
              );
            } else {
              const target =
                liveTarget ??
                (await runtimeFor(claim.endpoint)).thread(payload.threadId);
              if (payload.effect === "ephemeral_message") {
                if (!target.postEphemeral) {
                  if (!payload.fallbackText) {
                    throw Object.assign(
                      new Error("Provider does not support ephemeral messages"),
                      { code: "CHAT_PROVIDER_PRETRANSPORT_REJECTED" },
                    );
                  }
                  sent = await target.post(payload.fallbackText);
                } else {
                  try {
                    sent = await target.postEphemeral(
                      payload.userId!,
                      payload.text,
                      { fallbackToDM: false },
                    );
                  } catch (error) {
                    if (
                      !payload.fallbackText ||
                      classifyChatPublicationError(error, attempt).kind !==
                        "failed"
                    ) {
                      throw error;
                    }
                  }
                  if (!sent && payload.fallbackText) {
                    sent = await target.post(payload.fallbackText);
                  }
                }
              } else {
                sent = await target.post(payload.text);
              }
            }
            if (!sent) {
              throw Object.assign(
                new Error("Provider did not accept the message"),
                { code: "CHAT_PROVIDER_PRETRANSPORT_REJECTED" },
              );
            }
            providerEffectCompleted = true;
            await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              // A duplicate webhook holds the endpoint while waiting for the
              // delivery's unique-index entry. Lock this endpoint first too,
              // before settling the action/conversation/delivery, so neither
              // transaction can wait on a row already held by the other.
              const currentEndpoint = await runtimeCallbackEndpoint(
                tx,
                claim.endpoint.id,
                {
                  generation: payload.runtimeGeneration,
                  credentialFingerprint: payload.credentialFingerprint,
                },
                ["verifying", "active"],
              );
              const [completed] = await tx
                .update(chatActions)
                .set({
                  status: "processed",
                  result: {
                    attempts: attempt,
                    providerMessageId: sent.id,
                    threadId: sent.threadId,
                    ...(payload.effect === "telegram_callback_notice"
                      ? {
                          code:
                            payload.telegramCallback?.chatType === "private"
                              ? "telegram_private_api_accepted"
                              : "telegram_ephemeral_api_accepted",
                        }
                      : {}),
                  },
                  updatedAt: new Date(),
                })
                .where(
                  and(
                    eq(chatActions.id, action!.id),
                    eq(chatActions.status, "processing"),
                    sql`(${chatActions.result}->>'attempts')::int = ${attempt}`,
                  ),
                )
                .returning({ id: chatActions.id });
              if (!completed) {
                throw new Error(
                  "Provider effect ownership changed before commit",
                );
              }
              if (payload.completeConversationId) {
                await tx
                  .update(chatConversations)
                  .set({ state: "completed", updatedAt: new Date() })
                  .where(
                    and(
                      eq(chatConversations.id, payload.completeConversationId),
                      eq(chatConversations.endpointId, claim.endpoint.id),
                      inArray(chatConversations.state, ["active", "waiting"]),
                    ),
                  );
              }
              if (payload.settleDelivery && action!.deliveryId) {
                const [settled] = await tx
                  .update(chatDeliveries)
                  .set({
                    state: "processed",
                    processedAt: new Date(),
                    nextAttemptAt: null,
                    redactedError: null,
                    updatedAt: new Date(),
                  })
                  .where(
                    and(
                      eq(chatDeliveries.id, action!.deliveryId),
                      eq(chatDeliveries.state, "processing"),
                    ),
                  )
                  .returning({ id: chatDeliveries.id });
                if (!settled) {
                  throw new Error(
                    "Provider effect delivery ownership changed before commit",
                  );
                }
              }
              if (currentEndpoint) {
                await tx
                  .update(chatEndpoints)
                  .set({ lastEventAt: new Date(), updatedAt: new Date() })
                  .where(eq(chatEndpoints.id, currentEndpoint.id));
              }
              await credentialLease.assertOwned(tx);
            });
            return "processed";
          },
        );
      } catch (error) {
        const disposition = providerEffectDisposition(
          error,
          attempt,
          providerEffectCompleted,
        );
        try {
          await finalizeProviderEffectFailure({
            action,
            endpoint: record?.endpoint ?? initialEndpoint.endpoint,
            payload,
            disposition,
            attempt,
          });
        } catch (finalizationError) {
          if (disposition.kind === "delivery_unknown") {
            throw Object.assign(
              new Error(
                "Provider effect is ambiguous and its durable quarantine failed",
                { cause: finalizationError },
              ),
              { code: "CHAT_PROVIDER_EFFECT_AMBIGUOUS" },
            );
          }
          throw finalizationError;
        }
        throw error;
      }
    };
    return processClaimedEffect();
  }

  function scheduleProviderEffect(
    actionId: string,
    liveTarget?: ProviderEffectTarget,
  ) {
    scheduleMessageProcessing(async () => {
      await processProviderEffect(actionId, liveTarget);
    });
  }

  async function processPendingProviderEffects(limit = 25) {
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    const actions = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "provider_effect"),
          or(
            eq(chatActions.status, "received"),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, staleBefore),
            ),
            and(
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'true'`,
              sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.createdAt))
      .limit(limit);
    for (const action of actions) {
      if (action.status === "processing" && action.updatedAt <= staleBefore) {
        await quarantineStaleProviderEffect(action);
        continue;
      }
      try {
        await processProviderEffect(action.id);
      } catch (error) {
        logger.warn(
          {
            endpointId: action.endpointId,
            actionId: action.id,
            error: redactError(error),
          },
          "chat provider effect reconciliation failed",
        );
      }
    }
    return actions.length;
  }

  async function runtimeCallbackEndpoint(
    tx: DbTransaction,
    endpointId: string,
    context: LifecycleRuntimeFence,
    allowedStatuses: EndpointRow["status"][],
  ): Promise<EndpointRow | null> {
    const endpoint = await tx
      .select()
      .from(chatEndpoints)
      .where(eq(chatEndpoints.id, endpointId))
      // Serialize endpoint mutations without taking the stronger row lock
      // that conflicts with the Chat SDK state table's endpoint foreign-key
      // check. FOR UPDATE can self-deadlock an SDK-state write performed by a
      // provider callback on another pooled connection.
      .for("no key update")
      .then((rows) => rows[0] ?? null);
    if (
      !endpoint ||
      !allowedStatuses.includes(endpoint.status) ||
      runtimeGeneration(endpoint.setup) !== context.generation
    )
      return null;
    const refs = await tx
      .select({ refs: toolConnections.credentialSecretRefs })
      .from(toolConnections)
      .where(
        and(
          eq(toolConnections.companyId, endpoint.companyId),
          eq(toolConnections.id, endpoint.connectionId),
        ),
      )
      .then((rows) => rows[0]?.refs ?? []);
    if (credentialFingerprint(refs) !== context.credentialFingerprint) {
      return null;
    }
    const runtimeContext = context as RuntimeContext;
    if (
      endpoint.provider === "discord" &&
      runtimeContext.discordGatewayOwned === true &&
      runtimeContext.endpointRuntime !== undefined &&
      !discordGatewayRuntimeIsCurrent(endpointId, runtimeContext)
    ) {
      return null;
    }
    return endpoint;
  }

  async function runtimeCallbackRecord(
    endpointId: string,
    context: RuntimeContext,
    allowedStatuses: EndpointRow["status"][],
  ) {
    const record = await endpointRecord(endpointId);
    if (
      record?.endpoint.provider === "discord" &&
      !(await ensureDiscordGatewayRuntimeIsCurrent(endpointId, context))
    ) {
      return null;
    }
    return record &&
      allowedStatuses.includes(record.endpoint.status) &&
      runtimeGeneration(record.endpoint.setup) === context.generation &&
      credentialFingerprint(record.credentialSecretRefs) ===
        context.credentialFingerprint &&
      runtime.get(endpointId) === context.endpointRuntime &&
      (record.endpoint.provider !== "discord" ||
        discordGatewayRuntimeIsCurrent(endpointId, context))
      ? record
      : null;
  }

  async function recordCurrentMicrosoftTeamsRoute(
    endpoint: EndpointRow,
    context: InboundRuntimeContext | undefined,
    threadId: string,
    raw: unknown,
    recordAcceptedActivity = true,
  ): Promise<void> {
    if (endpoint.provider !== "microsoft-teams" || !context?.endpointRuntime) {
      return;
    }
    const serviceUrl = microsoftTeamsServiceUrl(raw);
    if (!serviceUrl) return;
    await db.transaction(async (tx) => {
      const current = await runtimeCallbackEndpoint(tx, endpoint.id, context, [
        "verifying",
        "active",
      ]);
      if (!current || runtime.get(endpoint.id) !== context.endpointRuntime) {
        return;
      }
      await context.endpointRuntime.recordMicrosoftTeamsRoute(
        threadId,
        serviceUrl,
        recordAcceptedActivity ? raw : undefined,
      );
    });
  }

  function discordGatewayRuntimeIsCurrent(
    endpointId: string,
    context: RuntimeContext,
  ): boolean {
    const ownership = discordGatewayOwnerships.get(endpointId);
    return (
      ownership !== undefined &&
      !ownership.stopping &&
      ownership.context === context &&
      ownership.expiresAt.getTime() > Date.now() &&
      context.discordGatewayOwned === true &&
      context.endpointRuntime !== undefined &&
      runtime.get(endpointId) === context.endpointRuntime
    );
  }

  function discordGatewayFailureDetail(
    event: DiscordGatewayCallbackEvent["event"],
  ): string {
    if (event.type === "guild_removed") {
      return "Discord bot was removed from the configured server";
    }
    if (event.type === "guild_unavailable") {
      return "Discord server is temporarily unavailable; reconnecting";
    }
    if (event.type === "disconnected") {
      return `Discord Gateway disconnected${event.code === undefined ? "" : ` (code ${event.code})`}; reconnecting`;
    }
    if (event.type === "failure") {
      const code = event.error.code ?? event.error.status;
      return `Discord Gateway failed${code === undefined ? "" : ` (${String(code).slice(0, 64)})`}; ${event.fatal ? "credentials or privileged intents need attention" : "reconnecting"}`;
    }
    return "Discord Gateway connection needs attention";
  }

  function handleDiscordGatewayEvent(
    callback: DiscordGatewayCallbackEvent,
    context: RuntimeContext,
  ): Promise<void> {
    const pending = (context.discordGatewayEventQueue ?? Promise.resolve())
      .catch(() => undefined)
      .then(() => processDiscordGatewayEvent(callback, context));
    context.discordGatewayEventQueue = pending;
    return pending;
  }

  async function processDiscordGatewayEvent(
    callback: DiscordGatewayCallbackEvent,
    context: RuntimeContext,
  ): Promise<void> {
    if (
      !(await ensureDiscordGatewayRuntimeIsCurrent(
        callback.endpointId,
        context,
      ))
    )
      return;
    if (callback.sequence <= (context.discordGatewaySequence ?? 0)) return;
    context.discordGatewaySequence = callback.sequence;
    await options.discordGatewayEventBarrier?.(callback);
    const record = await runtimeCallbackRecord(callback.endpointId, context, [
      "verifying",
      "active",
      "attention",
    ]);
    if (!record || record.endpoint.provider !== "discord") return;
    const event = callback.event;
    if (event.type === "channel_removed") {
      await applyProviderLifecycleEffect(
        record.endpoint,
        {
          kind: "resource",
          provider: "discord",
          providerEventId: `gateway:channel_removed:${event.channelId}`,
          providerResourceId: event.channelId,
          resourceType: "channel",
          label: event.label?.trim() || event.channelId,
          availability: "removed",
          metadata: { source: "discord_gateway" },
        },
        context,
      );
      return;
    }

    await db.transaction(async (tx) => {
      const current = await runtimeCallbackEndpoint(
        tx,
        callback.endpointId,
        context,
        ["verifying", "active", "attention"],
      );
      if (
        !current ||
        current.provider !== "discord" ||
        !discordGatewayRuntimeIsCurrent(callback.endpointId, context)
      ) {
        return;
      }
      const now = new Date();
      if (event.type === "connecting") {
        await tx
          .update(chatEndpoints)
          .set({
            healthMessage: "Discord Gateway connecting",
            lastError: null,
            lastEventAt: now,
            updatedAt: now,
          })
          .where(eq(chatEndpoints.id, current.id));
        await tx
          .update(toolConnections)
          .set({
            healthStatus: "unchecked",
            healthMessage: "Discord Gateway connecting",
            lastError: null,
            healthCheckedAt: now,
            updatedAt: now,
          })
          .where(eq(toolConnections.id, current.connectionId));
        return;
      }
      if (event.type === "ready" || event.type === "guild_available") {
        const gatewayOwnedAttention =
          current.status === "attention" &&
          current.healthMessage?.startsWith("Discord ") === true;
        if (current.status === "attention" && !gatewayOwnedAttention) return;
        const status =
          current.setup.step === "complete" ? "active" : "verifying";
        await tx
          .update(chatEndpoints)
          .set({
            status,
            healthMessage:
              status === "active"
                ? "Connected"
                : "Waiting for a test conversation",
            lastError: null,
            lastEventAt: now,
            updatedAt: now,
          })
          .where(eq(chatEndpoints.id, current.id));
        await tx
          .update(toolConnections)
          .set({
            status: "active",
            enabled: true,
            healthStatus: "healthy",
            healthMessage: "Connected",
            lastError: null,
            healthCheckedAt: now,
            updatedAt: now,
          })
          .where(eq(toolConnections.id, current.connectionId));
        return;
      }

      const detail = discordGatewayFailureDetail(event);
      const transientGuildOutage = event.type === "guild_unavailable";
      const terminal =
        event.type === "guild_removed" ||
        ((event.type === "failure" || event.type === "disconnected") &&
          event.fatal);
      await tx
        .update(chatEndpoints)
        .set({
          status: transientGuildOutage
            ? current.status
            : event.type === "guild_removed"
              ? "revoked"
              : "attention",
          healthMessage: detail,
          lastError: detail,
          lastEventAt: now,
          ...(terminal
            ? {
                setup: {
                  ...current.setup,
                  runtimeGeneration: runtimeGeneration(current.setup) + 1,
                } as InternalSetupState,
              }
            : {}),
          updatedAt: now,
        })
        .where(eq(chatEndpoints.id, current.id));
      await tx
        .update(toolConnections)
        .set({
          status: terminal ? "disabled" : "active",
          enabled: !terminal,
          healthStatus: event.type === "guild_removed" ? "failed" : "degraded",
          healthMessage: detail,
          lastError: detail,
          healthCheckedAt: now,
          updatedAt: now,
        })
        .where(eq(toolConnections.id, current.connectionId));
      if (event.type === "guild_removed") {
        await tx
          .update(chatEndpointResources)
          .set({ availability: "unavailable", updatedAt: now })
          .where(
            and(
              eq(chatEndpointResources.companyId, current.companyId),
              eq(chatEndpointResources.endpointId, current.id),
            ),
          );
        await tx
          .update(chatConversations)
          .set({ state: "unavailable", updatedAt: now })
          .where(
            and(
              eq(chatConversations.companyId, current.companyId),
              eq(chatConversations.endpointId, current.id),
              inArray(chatConversations.state, ["active", "waiting"]),
            ),
          );
      }
    });
  }

  function serializeEndpoint(
    row: Awaited<ReturnType<typeof endpointRecord>>,
  ): ChatEndpoint {
    if (!row) throw notFound("Chat endpoint not found");
    const endpoint = row.endpoint;
    return {
      id: endpoint.id,
      companyId: endpoint.companyId,
      connectionId: endpoint.connectionId,
      provider: endpoint.provider,
      publicId: endpoint.publicId,
      status: endpoint.status,
      deploymentMode: endpoint.deploymentMode,
      assignedAgentId: endpoint.assignedAgentId,
      assignedAgentName: row.assignedAgentName,
      sponsorUserId: endpoint.sponsorUserId,
      providerAccountId: endpoint.providerAccountId,
      providerAccountLabel: endpoint.providerAccountLabel,
      botExternalId: endpoint.botExternalId,
      botUsername: endpoint.botUsername,
      botLabel: endpoint.botDisplayName ?? row.assignedAgentName,
      botAvatarUrl: endpoint.botAvatarUrl,
      allowDirectMessages: endpoint.allowDirectMessages,
      allowGroupChats: endpoint.allowGroupChats,
      allowUnlinkedPeople: endpoint.allowUnlinkedPeople,
      replyMode: "subscribed",
      capabilities: endpoint.capabilities,
      setup: {
        ...providerSetupState(
          endpoint,
          webhookPublicBaseUrl,
          row.assignedAgentName,
        ),
        ...(endpoint.provider === "github"
          ? {
              webhookSecretConfigured: row.credentialSecretRefs.some(
                (ref) => ref.configPath === "credentials.webhookSecret",
              ),
            }
          : {}),
      },
      healthMessage: endpoint.healthMessage,
      lastError: endpoint.lastError,
      lastActivityAt: iso(endpoint.lastEventAt),
      lastPublicationAt: iso(endpoint.lastPublicationAt),
      activatedAt: iso(endpoint.activatedAt),
      createdAt: endpoint.createdAt.toISOString(),
      updatedAt: endpoint.updatedAt.toISOString(),
    };
  }

  async function list(companyId: string) {
    const rows = await db
      .select({
        endpoint: chatEndpoints,
        assignedAgentName: agents.name,
        connectionName: toolConnections.name,
        applicationId: toolConnections.applicationId,
        credentialSecretRefs: toolConnections.credentialSecretRefs,
      })
      .from(chatEndpoints)
      .innerJoin(
        agents,
        and(
          eq(agents.id, chatEndpoints.assignedAgentId),
          eq(agents.companyId, chatEndpoints.companyId),
        ),
      )
      .innerJoin(
        toolConnections,
        and(
          eq(toolConnections.id, chatEndpoints.connectionId),
          eq(toolConnections.companyId, chatEndpoints.companyId),
        ),
      )
      .where(
        and(
          eq(chatEndpoints.companyId, companyId),
          ne(chatEndpoints.status, "archived"),
        ),
      )
      .orderBy(desc(chatEndpoints.updatedAt));
    return rows.map((row) => serializeEndpoint(row));
  }

  async function get(endpointId: string) {
    return serializeEndpoint(await endpointRecord(endpointId));
  }

  async function create(
    companyId: string,
    input: CreateChatEndpointInput,
    actorUserId?: string | null,
  ) {
    const agent = await db
      .select({ id: agents.id, name: agents.name, status: agents.status })
      .from(agents)
      .where(
        and(
          eq(agents.companyId, companyId),
          eq(agents.id, input.assignedAgentId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!agent)
      throw unprocessable("The selected agent does not belong to this company");
    if (!isAgentStatusInvokable(agent.status)) {
      throw unprocessable(
        "The selected agent must be active before it can be connected to chat",
        {
          code: "chat_agent_not_invokable",
        },
      );
    }

    const endpointId = randomUUID();
    const publicId = randomBytes(32).toString("base64url");
    const applicationId = input.applicationId ?? randomUUID();
    const connectionId = randomUUID();
    const suffix = endpointId.slice(0, 8);
    const name = (
      input.name?.trim() || `${PROVIDER_LABELS[input.provider]} — ${agent.name}`
    ).slice(0, 145);
    await db.transaction(async (tx) => {
      if (input.applicationId) {
        const application = await tx
          .select({
            id: toolApplications.id,
            applicationKey: toolApplications.applicationKey,
            metadata: toolApplications.metadata,
            status: toolApplications.status,
          })
          .from(toolApplications)
          .where(
            and(
              eq(toolApplications.companyId, companyId),
              eq(toolApplications.id, input.applicationId),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (!application) throw notFound("App not found");
        const sourceTemplateKey =
          typeof application.metadata.sourceTemplateKey === "string"
            ? application.metadata.sourceTemplateKey
            : null;
        if (
          application.status === "archived" ||
          (application.applicationKey !== input.provider &&
            sourceTemplateKey !== input.provider)
        ) {
          throw unprocessable(
            `The selected App is not the ${PROVIDER_LABELS[input.provider]} connector`,
          );
        }
      } else {
        await tx.insert(toolApplications).values({
          id: applicationId,
          companyId,
          applicationKey: `chat:${input.provider}:${endpointId}`,
          name: `${name} ${suffix}`,
          description: `People talk to ${agent.name} through ${PROVIDER_LABELS[input.provider]}.`,
          type: "chat",
          status: "draft",
          metadata: { sourceTemplateKey: input.provider, purpose: "channel" },
          ownerUserId: actorUserId ?? null,
        });
      }
      await tx.insert(toolConnections).values({
        id: connectionId,
        companyId,
        applicationId,
        name,
        uid: `chat-${input.provider}-${endpointId}`,
        connectionKind: "managed",
        connectionPurpose: "channel",
        ownership: "customer",
        transport: "chat_sdk",
        authKind: "api_key",
        credentialPolicy: "shared",
        status: "draft",
        enabled: false,
        config: { provider: input.provider },
        transportConfig: {},
        createdByUserId: actorUserId ?? null,
      });
      await tx.insert(chatEndpoints).values({
        id: endpointId,
        companyId,
        connectionId,
        provider: input.provider,
        publicId,
        assignedAgentId: agent.id,
        sponsorUserId: actorUserId ?? null,
        // Group chat is a broad Teams reach grant rather than a discovered
        // destination toggle. Keep it closed until the operator explicitly
        // enables that surface, even when this process is running against a
        // database created before the column default was hardened.
        allowGroupChats: input.provider !== "microsoft-teams",
        capabilities: CAPABILITIES[input.provider],
        setup: {
          step: "provider_setup",
          ...(input.provider === "slack"
            ? { command: slackCommandForAgent(agent.name, publicId) }
            : {}),
        },
      });
    });
    await logActivity(db, {
      companyId,
      actorType: "user",
      actorId: actorUserId ?? "board",
      action: "chat_endpoint.created",
      entityType: "tool_connection",
      entityId: connectionId,
      details: {
        endpointId,
        provider: input.provider,
        assignedAgentId: agent.id,
      },
    });
    return get(endpointId);
  }

  async function update(
    endpointId: string,
    input: UpdateChatEndpointInput,
    actorUserId?: string | null,
  ) {
    const initial = await endpointRecord(endpointId);
    if (!initial) throw notFound("Chat endpoint not found");
    await withCredentialMutationLease(
      initial.endpoint,
      async (credentialLease) => {
        // Reach changes share the provider-transport lane with publications.
        // Once a disable returns, no send that sampled the previous grant can
        // still begin or finish behind it.
        const existing = await endpointRecord(endpointId);
        if (!existing) throw notFound("Chat endpoint not found");
        const values: Partial<typeof chatEndpoints.$inferInsert> = {
          updatedAt: new Date(),
        };
        if (input.allowDirectMessages !== undefined)
          values.allowDirectMessages = input.allowDirectMessages;
        if (input.allowGroupChats !== undefined)
          values.allowGroupChats = input.allowGroupChats;
        if (input.allowUnlinkedPeople !== undefined)
          values.allowUnlinkedPeople = input.allowUnlinkedPeople;
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await tx
            .update(chatEndpoints)
            .set(values)
            .where(eq(chatEndpoints.id, endpointId));
          await logActivity(tx as unknown as Db, {
            companyId: existing.endpoint.companyId,
            actorType: "user",
            actorId: actorUserId ?? "board",
            action: "chat_endpoint.updated",
            entityType: "tool_connection",
            entityId: existing.endpoint.connectionId,
            details: { endpointId, fields: Object.keys(input) },
          });
          await credentialLease.assertOwned(tx);
        });
      },
    );
    return get(endpointId);
  }

  async function normalizedCredentials(
    endpoint: EndpointRow,
    supplied: Record<string, string> | undefined,
  ) {
    const values = await resolveCredentials(endpoint).catch(
      () => ({}) as Record<string, string>,
    );
    for (const [key, rawValue] of Object.entries(supplied ?? {})) {
      if (typeof rawValue === "string" && rawValue.trim())
        values[key] = key === "privateKey" ? rawValue : rawValue.trim();
    }
    if (endpoint.provider === "telegram" && !values.webhookSecret) {
      values.webhookSecret = randomBytes(32).toString("hex");
    }
    const required =
      endpoint.provider === "github"
        ? ["appId", "privateKey", "webhookSecret"]
        : REQUIRED_CREDENTIALS[endpoint.provider];
    const missing = required.filter((key) => !values[key]);
    if (missing.length > 0) {
      throw unprocessable(
        `Missing required ${PROVIDER_LABELS[endpoint.provider]} credentials: ${missing.join(", ")}`,
      );
    }
    return endpoint.provider === "microsoft-teams"
      ? normalizeMicrosoftTeamsCredentialIds(values)
      : values;
  }

  async function verifyCredentials(
    provider: ChatProvider,
    credentials: Record<string, string>,
  ): Promise<VerifiedProviderIdentity> {
    if (provider === "slack") {
      const response = await fetchImpl("https://slack.com/api/auth.test", {
        method: "POST",
        signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS),
        headers: {
          authorization: `Bearer ${credentials.botToken}`,
          "content-type": "application/x-www-form-urlencoded",
        },
        body: "",
      });
      const result = (await response.json()) as {
        ok?: boolean;
        error?: string;
        team_id?: string;
        team?: string;
        user_id?: string;
        user?: string;
      };
      if (!response.ok || !result.ok)
        throw unprocessable(
          `Slack rejected the bot token: ${result.error ?? response.status}`,
        );
      const grantedScopes = new Set(
        (response.headers.get("x-oauth-scopes") ?? "")
          .split(",")
          .map((scope) => scope.trim())
          .filter(Boolean),
      );
      const missingScopes = REQUIRED_SLACK_BOT_SCOPES.filter(
        (scope) => !grantedScopes.has(scope),
      );
      if (missingScopes.length > 0) {
        throw unprocessable(
          `Slack app is missing required bot scopes: ${missingScopes.join(", ")}`,
          {
            code: "chat_provider_permissions_missing",
            provider: "slack",
            missingScopes,
          },
        );
      }
      return {
        providerAccountId: result.team_id,
        providerAccountLabel: result.team,
        botExternalId: result.user_id,
        botUsername: result.user,
        botLabel: result.user,
      };
    }
    if (provider === "discord") {
      const identity = await verifyDiscordBot({
        applicationId: credentials.applicationId,
        botToken: credentials.botToken,
        fetch: fetchImpl,
        guildId: credentials.guildId,
      }).catch((error) => {
        throw unprocessable(redactError(error), {
          code: "chat_provider_permissions_missing",
          provider: "discord",
        });
      });
      return identity;
    }
    if (provider === "telegram") {
      const response = await fetchImpl(
        `https://api.telegram.org/bot${encodeURIComponent(credentials.botToken)}/getMe`,
        { signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS) },
      );
      const result = (await response.json()) as {
        ok?: boolean;
        description?: string;
        result?: { id?: number; username?: string; first_name?: string };
      };
      if (!response.ok || !result.ok)
        throw unprocessable(
          `Telegram rejected the bot token: ${result.description ?? response.status}`,
        );
      return {
        providerAccountId: String(result.result?.id ?? ""),
        botExternalId: String(result.result?.id ?? ""),
        botUsername: result.result?.username,
        botLabel: result.result?.first_name,
      };
    }
    if (provider === "github") {
      const token = githubAppJwt(credentials.appId, credentials.privateKey);
      const response = await fetchImpl("https://api.github.com/app", {
        signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS),
        headers: {
          accept: "application/vnd.github+json",
          authorization: `Bearer ${token}`,
          "x-github-api-version": "2022-11-28",
        },
      });
      const result = (await response.json()) as {
        id?: number;
        login?: string;
        slug?: string;
        name?: string;
        message?: string;
        owner?: { login?: string };
        permissions?: Record<string, string>;
        events?: string[];
      };
      if (!response.ok)
        throw unprocessable(
          `GitHub rejected the app credentials: ${result.message ?? response.status}`,
        );
      const missingPermissions = Object.entries(REQUIRED_GITHUB_PERMISSIONS)
        .filter(
          ([permission, access]) => result.permissions?.[permission] !== access,
        )
        .map(([permission]) => permission);
      const excessivePermissions = Object.keys(result.permissions ?? {}).filter(
        (permission) => !(permission in REQUIRED_GITHUB_PERMISSIONS),
      );
      const configuredEvents = new Set(result.events ?? []);
      const missingEvents = REQUIRED_GITHUB_EVENTS.filter(
        (event) => !configuredEvents.has(event),
      );
      const allowedEvents = new Set<string>([
        ...REQUIRED_GITHUB_EVENTS,
        ...UNAVOIDABLE_GITHUB_EVENTS,
      ]);
      const excessiveEvents = [...configuredEvents].filter(
        (event) => !allowedEvents.has(event),
      );
      if (
        missingPermissions.length > 0 ||
        excessivePermissions.length > 0 ||
        missingEvents.length > 0 ||
        excessiveEvents.length > 0
      ) {
        throw unprocessable(
          [
            missingPermissions.length > 0
              ? `GitHub App needs the documented minimum access for: ${missingPermissions.join(", ")}`
              : null,
            excessivePermissions.length > 0
              ? `GitHub App has broader permissions than Paperclip needs: ${excessivePermissions.join(", ")}`
              : null,
            missingEvents.length > 0
              ? `GitHub App must subscribe to: ${missingEvents.join(", ")}`
              : null,
            excessiveEvents.length > 0
              ? `GitHub App subscribes to broader events than Paperclip needs: ${excessiveEvents.join(", ")}`
              : null,
          ]
            .filter(Boolean)
            .join(". "),
          {
            code: "chat_provider_permissions_missing",
            provider: "github",
            missingPermissions,
            excessivePermissions,
            missingEvents,
            excessiveEvents,
          },
        );
      }
      return {
        providerAccountId: result.owner?.login,
        providerAccountLabel: result.owner?.login ?? result.name,
        // The App registration id is the stable, immutable endpoint identity.
        // The adapter discovers the separate bot-user id while initializing.
        botExternalId:
          typeof result.id === "number" && Number.isFinite(result.id)
            ? String(result.id)
            : undefined,
        botUsername: result.slug ? `${result.slug}[bot]` : undefined,
        botLabel: result.name ?? result.slug,
      };
    }
    const teamsCredentials = normalizeMicrosoftTeamsCredentialIds(credentials);
    const body = new URLSearchParams({
      client_id: teamsCredentials.clientId,
      client_secret: teamsCredentials.clientSecret,
      grant_type: "client_credentials",
      scope: "https://api.botframework.com/.default",
    });
    const response = await fetchImpl(
      `https://login.microsoftonline.com/${encodeURIComponent(teamsCredentials.tenantId)}/oauth2/v2.0/token`,
      {
        method: "POST",
        signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS),
        headers: { "content-type": "application/x-www-form-urlencoded" },
        body,
      },
    );
    const result = (await response.json()) as {
      access_token?: string;
      error_description?: string;
    };
    if (!response.ok || !result.access_token)
      throw unprocessable(
        `Microsoft rejected the app credentials: ${result.error_description ?? response.status}`,
      );
    return {
      providerAccountId: teamsCredentials.tenantId,
      providerAccountLabel: teamsCredentials.tenantId,
      botExternalId: teamsCredentials.clientId,
    };
  }

  function nativeBotIdentityKey(
    provider: ChatProvider,
    identity: VerifiedProviderIdentity,
  ): string | null {
    const account = identity.providerAccountId?.trim().toLowerCase();
    const bot = identity.botExternalId?.trim().toLowerCase();
    if (provider === "github" || provider === "discord") {
      if (bot) return `${provider}:app:${bot}`;
      return null;
    }
    if (!account || !bot) return null;
    return `${provider}:${account}:${bot}`;
  }

  function providerUsesGlobalApplicationIdentity(
    provider: ChatProvider,
  ): boolean {
    return (
      provider === "github" ||
      provider === "discord" ||
      provider === "microsoft-teams"
    );
  }

  function nativeBotIdentityMatches(
    provider: ChatProvider,
    current: VerifiedProviderIdentity,
    incoming: VerifiedProviderIdentity,
  ): boolean {
    const currentKey = nativeBotIdentityKey(provider, current);
    return (
      currentKey !== null &&
      currentKey === nativeBotIdentityKey(provider, incoming)
    );
  }

  function legacyGitHubLabelsMatchVerifiedCredentials(
    current: VerifiedProviderIdentity,
    verified: VerifiedProviderIdentity,
  ): boolean {
    return (
      !current.botExternalId &&
      Boolean(verified.botExternalId) &&
      current.providerAccountId?.trim().toLowerCase() ===
        verified.providerAccountId?.trim().toLowerCase() &&
      current.botUsername?.trim().toLowerCase() ===
        verified.botUsername?.trim().toLowerCase()
    );
  }

  async function assertNativeBotIdentityAvailable(
    endpoint: EndpointRow,
    identity: VerifiedProviderIdentity,
  ): Promise<void> {
    const key = nativeBotIdentityKey(endpoint.provider, identity);
    if (!key) {
      throw unprocessable(
        `${PROVIDER_LABELS[endpoint.provider]} did not return a stable native bot identity`,
      );
    }
    const candidates = await db
      .select({
        id: chatEndpoints.id,
        companyId: chatEndpoints.companyId,
        assignedAgentId: chatEndpoints.assignedAgentId,
        providerAccountId: chatEndpoints.providerAccountId,
        botExternalId: chatEndpoints.botExternalId,
        botUsername: chatEndpoints.botUsername,
      })
      .from(chatEndpoints)
      .where(
        and(
          providerUsesGlobalApplicationIdentity(endpoint.provider)
            ? undefined
            : eq(chatEndpoints.companyId, endpoint.companyId),
          eq(chatEndpoints.provider, endpoint.provider),
          ne(chatEndpoints.id, endpoint.id),
          inArray(chatEndpoints.status, [
            "verifying",
            "active",
            "paused",
            "attention",
          ]),
        ),
      );
    const conflictEndpoint = candidates.find((candidate) => {
      if (!providerUsesGlobalApplicationIdentity(endpoint.provider)) {
        return nativeBotIdentityKey(endpoint.provider, candidate) === key;
      }
      const candidateAppId = candidate.botExternalId?.trim().toLowerCase();
      const incomingAppId = identity.botExternalId?.trim().toLowerCase();
      if (candidateAppId && incomingAppId)
        return candidateAppId === incomingAppId;
      return (
        candidate.providerAccountId?.trim().toLowerCase() ===
          identity.providerAccountId?.trim().toLowerCase() &&
        candidate.botUsername?.trim().toLowerCase() ===
          identity.botUsername?.trim().toLowerCase()
      );
    });
    if (conflictEndpoint) {
      throw conflict(
        `This ${PROVIDER_LABELS[endpoint.provider]} bot already represents another Paperclip agent connection`,
        conflictEndpoint.companyId === endpoint.companyId
          ? {
              code: "chat_bot_identity_in_use",
              endpointId: conflictEndpoint.id,
              assignedAgentId: conflictEndpoint.assignedAgentId,
            }
          : { code: "chat_bot_identity_in_use" },
      );
    }
  }

  function isNativeBotIdentityUniqueViolation(error: unknown): boolean {
    return (
      isUniqueViolation(error, "chat_endpoints_live_bot_external_uq") ||
      isUniqueViolation(error, "chat_endpoints_live_discord_bot_external_uq") ||
      isUniqueViolation(
        error,
        "chat_endpoints_live_global_app_bot_external_uq",
      ) ||
      isUniqueViolation(error, "chat_endpoints_live_bot_username_uq")
    );
  }

  function nativeBotIdentityConflict(provider: ChatProvider) {
    return conflict(
      `This ${PROVIDER_LABELS[provider]} bot already represents another Paperclip agent connection`,
      { code: "chat_bot_identity_in_use" },
    );
  }

  async function persistCredentials(
    endpoint: EndpointRow,
    credentials: Record<string, string>,
    credentialLease: CredentialMutationLeaseGuard,
    actorUserId?: string | null,
  ) {
    await credentialLease.assertOwned();
    const previousRefs = await db
      .select({ refs: toolConnections.credentialSecretRefs })
      .from(toolConnections)
      .where(
        and(
          eq(toolConnections.companyId, endpoint.companyId),
          eq(toolConnections.id, endpoint.connectionId),
        ),
      )
      .then((rows) => rows[0]?.refs ?? []);
    const refs: ToolCredentialSecretRef[] = [];
    try {
      for (const [key, value] of Object.entries(credentials)) {
        await credentialLease.assertOwned();
        const suffix = randomUUID();
        const secret = await secrets.create(
          endpoint.companyId,
          {
            name: `chat.${endpoint.provider}.${endpoint.id.slice(0, 8)}.${key}.${suffix.slice(0, 8)}`,
            key: `CHAT_${endpoint.provider.replaceAll("-", "_")}_${endpoint.id.replaceAll("-", "_")}_${key}_${suffix}`.toUpperCase(),
            provider: "local_encrypted",
            managedMode: "paperclip_managed",
            value,
            description: `${PROVIDER_LABELS[endpoint.provider]} channel credential for endpoint ${endpoint.id}`,
          },
          { userId: actorUserId ?? undefined },
        );
        refs.push({
          secretId: secret.id,
          versionSelector: "latest",
          configPath: `credentials.${key}`,
          required: true,
          label: key,
          projectionClass: "unclassified",
        });
        await credentialLease.assertOwned();
      }
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const current = await tx
          .select({ refs: toolConnections.credentialSecretRefs })
          .from(toolConnections)
          .where(
            and(
              eq(toolConnections.companyId, endpoint.companyId),
              eq(toolConnections.id, endpoint.connectionId),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current) throw notFound("Chat connection not found");
        if (
          credentialFingerprint(current.refs) !==
          credentialFingerprint(previousRefs)
        ) {
          throw conflict("Chat credentials changed during rotation", {
            code: "chat_endpoint_credentials_changed",
          });
        }
        await tx
          .delete(companySecretBindings)
          .where(
            and(
              eq(companySecretBindings.companyId, endpoint.companyId),
              eq(companySecretBindings.targetType, "tool_connection"),
              eq(companySecretBindings.targetId, endpoint.connectionId),
            ),
          );
        if (refs.length > 0) {
          await tx.insert(companySecretBindings).values(
            refs.map((ref) => ({
              companyId: endpoint.companyId,
              secretId: ref.secretId,
              targetType: "tool_connection",
              targetId: endpoint.connectionId,
              configPath: ref.configPath,
              versionSelector: String(ref.versionSelector ?? "latest"),
              required: ref.required,
              label: ref.label ?? null,
              projectionClass: ref.projectionClass ?? "unclassified",
              projectionAllowlistKey: ref.projectionAllowlistKey ?? null,
            })),
          );
        }
        await tx
          .update(toolConnections)
          .set({ credentialSecretRefs: refs, updatedAt: new Date() })
          .where(eq(toolConnections.id, endpoint.connectionId));
        await credentialLease.assertOwned(tx);
      });
    } catch (error) {
      // A lost database acknowledgement can be ambiguous even when the
      // transaction committed. Delete only secrets proven unbound after the
      // failure; when that proof cannot be read, leak safely for later cleanup
      // instead of deleting a possibly-authoritative credential.
      const boundSecretIds =
        refs.length === 0
          ? new Set<string>()
          : await db
              .select({ secretId: companySecretBindings.secretId })
              .from(companySecretBindings)
              .where(
                and(
                  eq(companySecretBindings.companyId, endpoint.companyId),
                  inArray(
                    companySecretBindings.secretId,
                    refs.map((ref) => ref.secretId),
                  ),
                ),
              )
              .then((rows) => new Set(rows.map((row) => row.secretId)))
              .catch(() => null);
      if (boundSecretIds) {
        await Promise.allSettled(
          refs
            .filter((ref) => !boundSecretIds.has(ref.secretId))
            .map((ref) => secrets.remove(ref.secretId)),
        );
      }
      throw error;
    }
    const currentIds = new Set(refs.map((ref) => ref.secretId));
    const retired = previousRefs.filter((ref) => !currentIds.has(ref.secretId));
    const results = await Promise.allSettled(
      retired.map((ref) => secrets.remove(ref.secretId)),
    );
    if (results.some((result) => result.status === "rejected")) {
      logger.warn(
        { endpointId: endpoint.id },
        "chat credential rotation left an unbound retired secret for later cleanup",
      );
    }
    return refs;
  }

  async function clearCredentials(
    endpoint: EndpointRow,
    credentialLease: CredentialMutationLeaseGuard,
  ) {
    let refs: ToolCredentialSecretRef[] = [];
    await db.transaction(async (tx) => {
      await credentialLease.assertOwned(tx);
      const current = await tx
        .select({ refs: toolConnections.credentialSecretRefs })
        .from(toolConnections)
        .where(
          and(
            eq(toolConnections.companyId, endpoint.companyId),
            eq(toolConnections.id, endpoint.connectionId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!current) throw notFound("Chat connection not found");
      refs = current.refs;
      await tx
        .delete(companySecretBindings)
        .where(
          and(
            eq(companySecretBindings.companyId, endpoint.companyId),
            eq(companySecretBindings.targetType, "tool_connection"),
            eq(companySecretBindings.targetId, endpoint.connectionId),
          ),
        );
      await tx
        .update(toolConnections)
        .set({ credentialSecretRefs: [], updatedAt: new Date() })
        .where(eq(toolConnections.id, endpoint.connectionId));
      await credentialLease.assertOwned(tx);
    });
    const results = await Promise.allSettled(
      refs.map((ref) => secrets.remove(ref.secretId)),
    );
    if (results.some((result) => result.status === "rejected")) {
      logger.warn(
        { endpointId: endpoint.id },
        "chat endpoint removal left an unbound retired secret for later cleanup",
      );
    }
  }

  async function resolveCredentialRefs(
    endpoint: EndpointRow,
    refs: ToolCredentialSecretRef[],
  ): Promise<Record<string, string>> {
    const values: Record<string, string> = {};
    for (const ref of refs) {
      const key = ref.configPath.replace(/^credentials\./, "");
      values[key] = await secrets.resolveSecretValue(
        endpoint.companyId,
        ref.secretId,
        ref.versionSelector ?? "latest",
        {
          consumerType: "tool_connection",
          consumerId: endpoint.connectionId,
          configPath: ref.configPath,
          actorType: "system",
          actorId: null,
        },
      );
    }
    return values;
  }

  async function resolveCredentials(
    endpoint: EndpointRow,
  ): Promise<Record<string, string>> {
    const connection = await db
      .select({ refs: toolConnections.credentialSecretRefs })
      .from(toolConnections)
      .where(
        and(
          eq(toolConnections.companyId, endpoint.companyId),
          eq(toolConnections.id, endpoint.connectionId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!connection) throw notFound("Chat connection not found");
    return resolveCredentialRefs(endpoint, connection.refs);
  }

  async function acquireCredentialMutationLease(endpoint: EndpointRow) {
    const token = randomUUID();
    const leaseKey = "credentials";
    const deadline = Date.now() + CREDENTIAL_MUTATION_LEASE_WAIT_MS;
    while (true) {
      const now = new Date();
      const expiresAt = new Date(
        now.getTime() + CREDENTIAL_MUTATION_LEASE_TTL_MS,
      );
      const inserted = await db
        .insert(chatEndpointLeases)
        .values({
          companyId: endpoint.companyId,
          endpointId: endpoint.id,
          leaseKey,
          token,
          expiresAt,
        })
        .onConflictDoNothing()
        .returning({ id: chatEndpointLeases.id });
      if (inserted.length > 0) return { leaseKey, token };
      const reclaimed = await db
        .update(chatEndpointLeases)
        .set({ token, expiresAt, updatedAt: now })
        .where(
          and(
            eq(chatEndpointLeases.companyId, endpoint.companyId),
            eq(chatEndpointLeases.endpointId, endpoint.id),
            eq(chatEndpointLeases.leaseKey, leaseKey),
            lte(chatEndpointLeases.expiresAt, now),
          ),
        )
        .returning({ id: chatEndpointLeases.id });
      if (reclaimed.length > 0) return { leaseKey, token };
      if (Date.now() >= deadline) {
        throw conflict(
          "Another credential update is still in progress; try again",
          {
            code: "chat_endpoint_credentials_busy",
          },
        );
      }
      await new Promise((resolve) =>
        setTimeout(resolve, CREDENTIAL_MUTATION_LEASE_POLL_MS),
      );
    }
  }

  async function withCredentialMutationLease<T>(
    endpoint: EndpointRow,
    mutation: (lease: CredentialMutationLeaseGuard) => Promise<T>,
    completion?: CredentialMutationLeaseCompletion<T>,
  ): Promise<T> {
    const lease = await acquireCredentialMutationLease(endpoint);
    let leaseLoss: Error | null = null;
    const lostLeaseError = (cause?: unknown) =>
      Object.assign(
        new Error(
          "Chat credential mutation lease ownership was lost before the operation completed",
          cause === undefined ? undefined : { cause },
        ),
        { code: "CHAT_CREDENTIAL_LEASE_LOST" },
      );
    const assertOwned: CredentialMutationLeaseGuard["assertOwned"] = async (
      database = db,
    ) => {
      if (leaseLoss) throw leaseLoss;
      const now = new Date();
      const expiresAt = new Date(
        now.getTime() + CREDENTIAL_MUTATION_LEASE_TTL_MS,
      );
      try {
        const owned = options.renewCredentialMutationLease
          ? await options.renewCredentialMutationLease({
              companyId: endpoint.companyId,
              endpointId: endpoint.id,
              expiresAt,
              leaseKey: lease.leaseKey,
              token: lease.token,
            })
          : (
              await database
                .update(chatEndpointLeases)
                .set({ expiresAt, updatedAt: now })
                .where(
                  and(
                    eq(chatEndpointLeases.companyId, endpoint.companyId),
                    eq(chatEndpointLeases.endpointId, endpoint.id),
                    eq(chatEndpointLeases.leaseKey, lease.leaseKey),
                    eq(chatEndpointLeases.token, lease.token),
                  ),
                )
                .returning({ id: chatEndpointLeases.id })
            ).length > 0;
        if (!owned) {
          leaseLoss = lostLeaseError();
          throw leaseLoss;
        }
      } catch (error) {
        if (leaseLoss) throw leaseLoss;
        leaseLoss = lostLeaseError(error);
        throw leaseLoss;
      }
    };
    const guard: CredentialMutationLeaseGuard = { assertOwned };
    let renewal: Promise<void> | null = null;
    const renewTimer = setInterval(
      () => {
        if (renewal) return;
        renewal = assertOwned()
          .catch((error) => {
            logger.warn(
              { endpointId: endpoint.id, error: redactError(error) },
              "lost chat credential mutation lease ownership",
            );
          })
          .finally(() => {
            renewal = null;
          });
      },
      options.credentialMutationLeaseRenewalIntervalMs ??
        CREDENTIAL_MUTATION_LEASE_TTL_MS / 3,
    );
    renewTimer.unref?.();
    try {
      const result = await mutation(guard);
      await completion?.beforeFinalOwnershipCheck?.();
      try {
        await assertOwned();
      } catch (error) {
        const recovered = completion?.recoverCommittedResultAfterLeaseLoss
          ? await completion
              .recoverCommittedResultAfterLeaseLoss(result, error as Error)
              .catch((recoveryError) => {
                logger.warn(
                  {
                    endpointId: endpoint.id,
                    error: redactError(recoveryError),
                  },
                  "could not verify a committed chat credential mutation after lease loss",
                );
                return false;
              })
          : false;
        if (!recovered) throw error;
      }
      return result;
    } finally {
      clearInterval(renewTimer);
      await renewal;
      await db
        .delete(chatEndpointLeases)
        .where(
          and(
            eq(chatEndpointLeases.companyId, endpoint.companyId),
            eq(chatEndpointLeases.endpointId, endpoint.id),
            eq(chatEndpointLeases.leaseKey, lease.leaseKey),
            eq(chatEndpointLeases.token, lease.token),
          ),
        )
        .catch((error) => {
          logger.warn(
            { endpointId: endpoint.id, error: redactError(error) },
            "could not release chat credential mutation lease",
          );
        });
    }
  }

  async function generateSetupSecret(
    endpointId: string,
    actorUserId?: string | null,
  ) {
    const initial = await endpointRecord(endpointId);
    if (!initial) throw notFound("Chat endpoint not found");
    if (initial.endpoint.provider !== "github") {
      throw unprocessable(
        "Setup secret generation is only available for GitHub",
      );
    }
    let committedWebhookSecretRef: ToolCredentialSecretRef | null = null;
    return withCredentialMutationLease(
      initial.endpoint,
      async (credentialLease) => {
        // A competing request may have completed while this request waited for
        // the durable lease. Reload both endpoint state and credential refs only
        // after ownership so each successful rotation starts from its immediate
        // predecessor instead of replacing the credential set from a stale read.
        const record = await endpointRecord(endpointId);
        if (!record) throw notFound("Chat endpoint not found");
        const endpoint = record.endpoint;
        if (
          ![
            "draft",
            "verifying",
            "active",
            "attention",
            "revoked",
            "paused",
          ].includes(endpoint.status)
        ) {
          throw conflict(
            "The GitHub webhook secret cannot be rotated in this connection state",
            {
              code: "chat_endpoint_setup_secret_unavailable",
            },
          );
        }
        const webhookSecret = randomBytes(32).toString("hex");
        // Rotation must fail closed if any existing credential cannot be resolved.
        // Falling back to an empty object here would replace the full credential
        // set with only the new webhook secret and strand an otherwise-live App.
        const existing = await resolveCredentials(endpoint);
        const replacedExistingSecret = record.credentialSecretRefs.some(
          (ref) => ref.configPath === "credentials.webhookSecret",
        );
        const rotatingConfiguredApp =
          Boolean(endpoint.providerAccountId || endpoint.botExternalId) ||
          record.credentialSecretRefs.some((ref) =>
            ["credentials.appId", "credentials.privateKey"].includes(
              ref.configPath,
            ),
          );
        const rotationId = randomUUID();
        const auditDetails = {
          endpointId: endpoint.id,
          provider: endpoint.provider,
          rotationId,
          rotated: rotatingConfiguredApp,
          replacedPrevious: replacedExistingSecret,
        };
        const writeSetupSecretActivity =
          options.setupSecretActivityLogger ?? logActivity;
        // This durable intent is the audit boundary. If it cannot be written,
        // fail before changing state or refs so retry is safe. Endpoint/tool
        // state moves fail-closed before ref replacement. Once refs change, only
        // best-effort work remains and the plaintext must still be returned.
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await writeSetupSecretActivity(tx as unknown as Db, {
            companyId: endpoint.companyId,
            actorType: "user",
            actorId: actorUserId ?? "board",
            action: "chat_endpoint.setup_secret_rotation_started",
            entityType: "tool_connection",
            entityId: endpoint.connectionId,
            details: auditDetails,
          });
          await credentialLease.assertOwned(tx);
        });
        try {
          if (rotatingConfiguredApp) {
            const updatedAt = new Date();
            await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              const current = await tx
                .select({ setup: chatEndpoints.setup })
                .from(chatEndpoints)
                .where(eq(chatEndpoints.id, endpoint.id))
                .for("update")
                .then((rows) => rows[0] ?? null);
              if (!current) throw notFound("Chat endpoint not found");
              await tx
                .update(chatEndpoints)
                .set({
                  status: "attention",
                  healthMessage:
                    "Update the GitHub webhook secret, then reconnect this App",
                  lastError: null,
                  setup: {
                    ...current.setup,
                    step: "provider_setup",
                    webhookVerifiedAt: null,
                    runtimeGeneration: runtimeGeneration(current.setup) + 1,
                  } as InternalSetupState,
                  updatedAt,
                })
                .where(eq(chatEndpoints.id, endpoint.id));
              await tx
                .update(toolConnections)
                .set({
                  status: "disabled",
                  enabled: false,
                  healthStatus: "degraded",
                  healthMessage:
                    "GitHub webhook secret rotation needs reconnect",
                  lastError: null,
                  healthCheckedAt: updatedAt,
                  updatedAt,
                })
                .where(eq(toolConnections.id, endpoint.connectionId));
              await credentialLease.assertOwned(tx);
            });
            await invalidateRuntime(endpoint.id).catch(() => undefined);
          } else {
            // Replacing a secret while the operator is still creating the GitHub
            // App is not a live credential rotation. Keep first-time setup in its
            // draft state, clear any ping for the superseded value, and also heal
            // endpoints affected by the earlier pre-connect rotation trap.
            const updatedAt = new Date();
            await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              const current = await tx
                .select({ setup: chatEndpoints.setup })
                .from(chatEndpoints)
                .where(eq(chatEndpoints.id, endpoint.id))
                .for("update")
                .then((rows) => rows[0] ?? null);
              if (!current) throw notFound("Chat endpoint not found");
              await tx
                .update(chatEndpoints)
                .set({
                  status: "draft",
                  healthMessage: null,
                  lastError: null,
                  setup: {
                    ...current.setup,
                    step: "provider_setup",
                    webhookVerifiedAt: null,
                  },
                  updatedAt,
                })
                .where(eq(chatEndpoints.id, endpoint.id));
              await tx
                .update(toolConnections)
                .set({
                  status: "draft",
                  enabled: false,
                  healthStatus: "unchecked",
                  healthMessage: null,
                  lastError: null,
                  healthCheckedAt: null,
                  updatedAt,
                })
                .where(eq(toolConnections.id, endpoint.connectionId));
              await credentialLease.assertOwned(tx);
            });
          }
          await options.setupSecretCredentialPersistBarrier?.();
          // Make credential refs the final required mutation. Once this returns,
          // only the best-effort completion audit remains, so the request cannot
          // fail after making the newly generated secret authoritative.
          const persistedRefs = await persistCredentials(
            endpoint,
            { ...existing, webhookSecret },
            credentialLease,
            actorUserId,
          );
          committedWebhookSecretRef =
            persistedRefs.find(
              (ref) => ref.configPath === "credentials.webhookSecret",
            ) ?? null;
          if (!committedWebhookSecretRef) {
            throw new Error(
              "GitHub webhook secret was not present after credential persistence",
            );
          }
        } catch (error) {
          await writeSetupSecretActivity(db, {
            companyId: endpoint.companyId,
            actorType: "user",
            actorId: actorUserId ?? "board",
            action: "chat_endpoint.setup_secret_rotation_failed",
            entityType: "tool_connection",
            entityId: endpoint.connectionId,
            details: auditDetails,
          }).catch((auditError) => {
            logger.warn(
              {
                endpointId: endpoint.id,
                error: redactError(auditError),
                rotationId,
              },
              "could not audit failed GitHub setup-secret rotation",
            );
          });
          throw error;
        }
        await db
          .transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            await writeSetupSecretActivity(tx as unknown as Db, {
              companyId: endpoint.companyId,
              actorType: "user",
              actorId: actorUserId ?? "board",
              action: "chat_endpoint.setup_secret_generated",
              entityType: "tool_connection",
              entityId: endpoint.connectionId,
              details: auditDetails,
            });
            await credentialLease.assertOwned(tx);
          })
          .catch((error) => {
            logger.warn(
              {
                endpointId: endpoint.id,
                error: redactError(error),
                rotationId,
              },
              "GitHub setup secret rotated but completion audit failed",
            );
          });
        return { webhookSecret };
      },
      {
        beforeFinalOwnershipCheck: options.setupSecretFinalOwnershipBarrier,
        recoverCommittedResultAfterLeaseLoss: async () => {
          const committedRef = committedWebhookSecretRef;
          if (!committedRef) return false;
          const authoritative = await db
            .select({ refs: toolConnections.credentialSecretRefs })
            .from(toolConnections)
            .innerJoin(
              companySecretBindings,
              and(
                eq(companySecretBindings.companyId, initial.endpoint.companyId),
                eq(companySecretBindings.targetType, "tool_connection"),
                eq(
                  companySecretBindings.targetId,
                  initial.endpoint.connectionId,
                ),
                eq(companySecretBindings.configPath, committedRef.configPath),
                eq(companySecretBindings.secretId, committedRef.secretId),
                eq(
                  companySecretBindings.versionSelector,
                  String(committedRef.versionSelector ?? "latest"),
                ),
              ),
            )
            .where(
              and(
                eq(toolConnections.companyId, initial.endpoint.companyId),
                eq(toolConnections.id, initial.endpoint.connectionId),
              ),
            )
            .then((rows) => rows[0] ?? null);
          return (
            authoritative?.refs.some(
              (ref) =>
                credentialFingerprint([ref]) ===
                credentialFingerprint([committedRef]),
            ) === true
          );
        },
      },
    );
  }

  function githubRepositoryStableId(
    item: ChatProviderResourceInventoryItem,
  ): string | null {
    const value = item.metadata?.providerRepositoryId;
    return typeof value === "string" && /^\d+$/.test(value) ? value : null;
  }

  async function upsertProviderResourceRow(
    tx: DbTransaction,
    endpoint: EndpointRow,
    item: ChatProviderResourceInventoryItem,
  ) {
    const stableGitHubId =
      endpoint.provider === "github" ? githubRepositoryStableId(item) : null;
    if (stableGitHubId) {
      await tx.execute(
        sql`select pg_advisory_xact_lock(hashtextextended(${`chat-github-repository:${endpoint.id}:${stableGitHubId}`}, 0))`,
      );
      const stableResource = await tx
        .select()
        .from(chatEndpointResources)
        .where(
          and(
            eq(chatEndpointResources.companyId, endpoint.companyId),
            eq(chatEndpointResources.endpointId, endpoint.id),
            eq(chatEndpointResources.type, "repository"),
            sql`${chatEndpointResources.metadata}->>'providerRepositoryId' = ${stableGitHubId}`,
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (
        stableResource &&
        stableResource.providerResourceId !== item.providerResourceId
      ) {
        const coordinateResource = await tx
          .select()
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.companyId, endpoint.companyId),
              eq(chatEndpointResources.endpointId, endpoint.id),
              eq(chatEndpointResources.type, "repository"),
              eq(
                chatEndpointResources.providerResourceId,
                item.providerResourceId,
              ),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (coordinateResource && coordinateResource.id !== stableResource.id) {
          const coordinateConversation = await tx
            .select({ id: chatConversations.id })
            .from(chatConversations)
            .where(
              and(
                eq(chatConversations.endpointId, endpoint.id),
                eq(chatConversations.resourceId, coordinateResource.id),
              ),
            )
            .limit(1)
            .then((rows) => rows[0] ?? null);
          if (coordinateConversation) {
            throw conflict(
              "GitHub repository identity is already bound to two coordinates",
              { code: "chat_github_repository_identity_conflict" },
            );
          }
          await tx
            .delete(chatEndpointResources)
            .where(eq(chatEndpointResources.id, coordinateResource.id));
        }

        const oldRepository = stableResource.providerResourceId;
        const oldThreadPrefix = `github:${oldRepository}`;
        const newThreadPrefix = `github:${item.providerResourceId}`;
        const oldProviderUrl = `https://github.com/${oldRepository}`;
        const newProviderUrl = `https://github.com/${item.providerResourceId}`;
        await tx
          .update(chatEndpointResources)
          .set({
            providerResourceId: item.providerResourceId,
            parentProviderResourceId: item.parentProviderResourceId ?? null,
            label: item.label,
            providerUrl: item.providerUrl ?? null,
            availability: "available",
            enabled:
              stableResource.enabled || coordinateResource?.enabled === true,
            metadata: item.metadata ?? {},
            updatedAt: new Date(),
          })
          .where(eq(chatEndpointResources.id, stableResource.id));
        await tx
          .update(chatConversations)
          .set({
            externalConversationId: sql<string>`case
              when lower(${chatConversations.externalConversationId}) = ${oldRepository} then ${item.providerResourceId}
              when lower(${chatConversations.externalConversationId}) = ${oldThreadPrefix} then ${newThreadPrefix}
              else ${chatConversations.externalConversationId}
            end`,
            externalThreadId: sql<string>`case
              when lower(${chatConversations.externalThreadId}) = ${oldThreadPrefix} then ${newThreadPrefix}
              when lower(${chatConversations.externalThreadId}) like ${`${oldThreadPrefix}:%`}
                then ${newThreadPrefix} || substring(
                  ${chatConversations.externalThreadId}
                  from char_length(${oldThreadPrefix}) + 1
                )
              else ${chatConversations.externalThreadId}
            end`,
            externalLabel: item.label,
            providerUrl: sql<string | null>`case
              when lower(${chatConversations.providerUrl}) like ${`${oldProviderUrl}/%`}
                then ${newProviderUrl} || substring(
                  ${chatConversations.providerUrl}
                  from char_length(${oldProviderUrl}) + 1
                )
              else ${chatConversations.providerUrl}
            end`,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatConversations.companyId, endpoint.companyId),
              eq(chatConversations.endpointId, endpoint.id),
              eq(chatConversations.resourceId, stableResource.id),
            ),
          );
        return { id: stableResource.id };
      }
    }

    const [resource] = await tx
      .insert(chatEndpointResources)
      .values({
        companyId: endpoint.companyId,
        endpointId: endpoint.id,
        type: item.type,
        providerResourceId: item.providerResourceId,
        parentProviderResourceId: item.parentProviderResourceId ?? null,
        label: item.label,
        providerUrl: item.providerUrl ?? null,
        availability: "available",
        enabled: false,
        metadata: item.metadata ?? {},
      })
      .onConflictDoUpdate({
        target: [
          chatEndpointResources.endpointId,
          chatEndpointResources.type,
          chatEndpointResources.providerResourceId,
        ],
        set: {
          parentProviderResourceId: item.parentProviderResourceId ?? null,
          label: item.label,
          providerUrl: item.providerUrl ?? null,
          availability: "available",
          metadata: item.metadata ?? {},
          updatedAt: new Date(),
        },
      })
      .returning({ id: chatEndpointResources.id });
    return resource ?? null;
  }

  async function reconcileGitHubWebhookRepository(
    endpoint: EndpointRow,
    payload: unknown,
    credentialLease: CredentialMutationLeaseGuard,
  ) {
    const item = githubRepositoryInventoryItemFromPayload(payload);
    if (!item) return;
    await db.transaction(async (tx) => {
      await credentialLease.assertOwned(tx);
      const resource = await upsertProviderResourceRow(tx, endpoint, item);
      if (!resource) return;
      // A correctly signed repository callback is current provider proof. Keep
      // Paperclip's enabled choice, and reopen only conversations previously
      // quarantined for provider availability loss.
      await tx
        .update(chatConversations)
        .set({ state: "active", updatedAt: new Date() })
        .where(
          and(
            eq(chatConversations.companyId, endpoint.companyId),
            eq(chatConversations.endpointId, endpoint.id),
            eq(chatConversations.resourceId, resource.id),
            eq(chatConversations.state, "unavailable"),
          ),
        );
      await credentialLease.assertOwned(tx);
    });
  }

  async function reconcileProviderResourceRows(
    endpoint: EndpointRow,
    inventory: ChatProviderInventoryResult,
    credentialLease: CredentialMutationLeaseGuard,
  ) {
    const resourceType =
      endpoint.provider === "github" ? "repository" : "channel";
    const discovered = new Set(
      inventory.resources.map((resource) => resource.providerResourceId),
    );
    const absentAvailability =
      endpoint.provider === "github" ? "removed" : "unavailable";
    await db.transaction(async (tx) => {
      await credentialLease.assertOwned(tx);
      for (const item of inventory.resources) {
        const resource = await upsertProviderResourceRow(tx, endpoint, item);
        if (resource) {
          // Resource recovery reopens only bindings that Paperclip marked
          // unavailable. Completed historical tasks stay completed.
          await tx
            .update(chatConversations)
            .set({ state: "active", updatedAt: new Date() })
            .where(
              and(
                eq(chatConversations.companyId, endpoint.companyId),
                eq(chatConversations.endpointId, endpoint.id),
                eq(chatConversations.resourceId, resource.id),
                eq(chatConversations.state, "unavailable"),
              ),
            );
        }
      }

      const existing = await tx
        .select({
          id: chatEndpointResources.id,
          providerResourceId: chatEndpointResources.providerResourceId,
        })
        .from(chatEndpointResources)
        .where(
          and(
            eq(chatEndpointResources.companyId, endpoint.companyId),
            eq(chatEndpointResources.endpointId, endpoint.id),
            eq(chatEndpointResources.type, resourceType),
          ),
        );
      for (const resource of existing) {
        if (discovered.has(resource.providerResourceId)) continue;
        await tx
          .update(chatEndpointResources)
          .set({ availability: absentAvailability, updatedAt: new Date() })
          .where(eq(chatEndpointResources.id, resource.id));
        await tx
          .update(chatConversations)
          .set({ state: "unavailable", updatedAt: new Date() })
          .where(
            and(
              eq(chatConversations.companyId, endpoint.companyId),
              eq(chatConversations.endpointId, endpoint.id),
              eq(chatConversations.resourceId, resource.id),
              inArray(chatConversations.state, ["active", "waiting"]),
            ),
          );
      }
      await credentialLease.assertOwned(tx);
    });
  }

  async function hydrateSlackResourceLabel(
    endpointId: string,
    providerResourceId: string,
  ): Promise<void> {
    const record = await endpointRecord(endpointId);
    if (
      !record ||
      record.endpoint.provider !== "slack" ||
      record.endpoint.status === "archived" ||
      record.endpoint.status === "revoked"
    ) {
      return;
    }
    const credentials = await resolveCredentials(record.endpoint);
    const resource = await getSlackBotChannel({
      botToken: credentials.botToken,
      channelId: providerResourceId,
      fetch: fetchImpl,
    });
    if (
      !resource ||
      slackResourceLabelIsFallback(providerResourceId, resource.label)
    )
      return;
    await db
      .update(chatEndpointResources)
      .set({ label: resource.label, updatedAt: new Date() })
      .where(
        and(
          eq(chatEndpointResources.companyId, record.endpoint.companyId),
          eq(chatEndpointResources.endpointId, endpointId),
          eq(chatEndpointResources.type, "channel"),
          eq(chatEndpointResources.providerResourceId, providerResourceId),
          eq(chatEndpointResources.availability, "available"),
        ),
      );
  }

  async function prepareProviderInventory(
    endpoint: EndpointRow,
    credentials: Record<string, string>,
  ): Promise<{
    credentials: Record<string, string>;
    inventory: ChatProviderInventoryResult | null;
  }> {
    try {
      if (endpoint.provider === "slack") {
        return {
          credentials,
          inventory: await listSlackBotChannels({
            botToken: credentials.botToken,
            fetch: fetchImpl,
          }),
        };
      }
      if (endpoint.provider === "github") {
        const appJwt = githubAppJwt(credentials.appId, credentials.privateKey);
        const installation = await discoverDedicatedGitHubAppInstallation({
          appJwt,
          fetch: fetchImpl,
        });
        const preparedCredentials = {
          ...credentials,
          installationId: installation.installationId,
        };
        const inventory = await listGitHubInstallationRepositories({
          appJwt,
          installationId: installation.installationId,
          fetch: fetchImpl,
        });
        return {
          credentials: preparedCredentials,
          inventory: {
            ...inventory,
            resources: inventory.resources.map((resource) => {
              const fullName =
                typeof resource.metadata?.fullName === "string"
                  ? resource.metadata.fullName
                  : resource.label.includes("/")
                    ? resource.label
                    : null;
              return fullName
                ? {
                    ...resource,
                    providerResourceId: fullName.toLowerCase(),
                    metadata: {
                      ...resource.metadata,
                      providerRepositoryId: resource.providerResourceId,
                      fullName,
                    },
                  }
                : resource;
            }),
          },
        };
      }
      if (endpoint.provider === "discord") {
        return {
          credentials,
          inventory: await listDiscordBotChannels({
            botUserId: credentials.applicationId,
            botToken: credentials.botToken,
            fetch: fetchImpl,
            guildId: credentials.guildId,
          }),
        };
      }
      return { credentials, inventory: null };
    } catch (error) {
      throw unprocessable(redactError(error), {
        code: "chat_provider_inventory_failed",
      });
    }
  }

  function runtimeConfig(
    endpoint: EndpointRow,
    userName: string,
    credentials: Record<string, string>,
  ): ResolvedChatSdkProviderConfig {
    if (endpoint.provider === "slack")
      return {
        provider: "slack",
        userName,
        credentials: {
          botToken: credentials.botToken,
          signingSecret: credentials.signingSecret,
          botUserId: endpoint.botExternalId ?? undefined,
        },
      };
    if (endpoint.provider === "telegram")
      return {
        provider: "telegram",
        userName,
        maxDownloadBytes: MAX_ATTACHMENT_BYTES,
        credentials: {
          botToken: credentials.botToken,
          secretToken: credentials.webhookSecret,
        },
      };
    if (endpoint.provider === "discord")
      return {
        provider: "discord",
        userName,
        credentials: {
          applicationId: credentials.applicationId,
          botToken: credentials.botToken,
          guildId: credentials.guildId,
        },
      };
    if (endpoint.provider === "microsoft-teams")
      return {
        provider: "microsoft-teams",
        userName,
        credentials: {
          appId: credentials.clientId,
          appPassword: credentials.clientSecret,
          appTenantId: credentials.tenantId,
          appType: "SingleTenant",
        },
      };
    return {
      provider: "github",
      userName,
      credentials: {
        appId: credentials.appId,
        privateKey: credentials.privateKey,
        installationId: credentials.installationId
          ? Number(credentials.installationId)
          : undefined,
        webhookSecret: credentials.webhookSecret,
      },
    };
  }

  async function reconcileDiscordCommands(
    endpointId: string,
    existingLease?: CredentialMutationLeaseGuard,
    force = false,
  ): Promise<void> {
    const initial = await endpointRecord(endpointId);
    if (!initial || initial.endpoint.provider !== "discord") return;
    const reconcile = async (lease: CredentialMutationLeaseGuard) => {
      const record = await endpointRecord(endpointId);
      if (
        !record ||
        record.endpoint.provider !== "discord" ||
        !["verifying", "active", "attention"].includes(
          record.endpoint.status,
        ) ||
        !record.endpoint.botExternalId ||
        !record.endpoint.providerAccountId
      )
        return;
      const scope = {
        companyId: record.endpoint.companyId,
        endpointId,
        applicationId: record.endpoint.botExternalId,
        guildId: record.endpoint.providerAccountId,
      };
      const fence = runtimeContextForRecord(record);
      const authorize = async (tx: DbTransaction) => {
        const endpoint = await tx
          .select()
          .from(chatEndpoints)
          .where(
            and(
              eq(chatEndpoints.companyId, scope.companyId),
              eq(chatEndpoints.id, scope.endpointId),
            ),
          )
          .for("no key update")
          .then((rows) => rows[0]);
        if (
          !endpoint ||
          endpoint.provider !== "discord" ||
          !["verifying", "active", "attention"].includes(endpoint.status) ||
          endpoint.botExternalId !== scope.applicationId ||
          endpoint.providerAccountId !== scope.guildId ||
          runtimeGeneration(endpoint.setup) !== fence.generation
        )
          throw conflict("Discord command registration authority changed");
        const connection = await tx
          .select()
          .from(toolConnections)
          .where(
            and(
              eq(toolConnections.companyId, scope.companyId),
              eq(toolConnections.id, endpoint.connectionId),
            ),
          )
          .for("no key update")
          .then((rows) => rows[0]);
        if (
          !connection?.enabled ||
          connection.status !== "active" ||
          credentialFingerprint(connection.credentialSecretRefs) !==
            fence.credentialFingerprint
        )
          throw conflict("Discord command registration authority changed");
        await lease.assertOwned(tx);
      };
      const setCapability = async (tx: DbTransaction, registered: boolean) => {
        const current = await tx
          .select()
          .from(chatEndpoints)
          .where(
            and(
              eq(chatEndpoints.companyId, scope.companyId),
              eq(chatEndpoints.id, endpointId),
            ),
          )
          .then((rows) => rows[0]);
        if (!current) throw notFound("Chat endpoint not found");
        if (
          current.capabilities.slashCommands === registered &&
          current.capabilities.ephemeralMessages === registered
        )
          return;
        await tx
          .update(chatEndpoints)
          .set({
            capabilities: {
              ...current.capabilities,
              slashCommands: registered,
              ephemeralMessages: registered,
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatEndpoints.companyId, scope.companyId),
              eq(chatEndpoints.id, endpointId),
            ),
          );
        await logActivity(tx as unknown as Db, {
          companyId: scope.companyId,
          actorType: "system",
          actorId: "system",
          action: registered
            ? "chat_endpoint.commands_registered"
            : "chat_endpoint.commands_unavailable",
          entityType: "tool_connection",
          entityId: current.connectionId,
          details: { endpointId, provider: "discord" },
        });
      };
      await lease.assertOwned();
      const credentials = await resolveCredentialRefs(
        record.endpoint,
        record.credentialSecretRefs,
      );
      if (
        credentials.applicationId !== scope.applicationId ||
        credentials.guildId !== scope.guildId
      )
        throw conflict("Discord command registration identity changed");
      const result = await reconcileStoredDiscordCommandRegistration(db, {
        scope,
        runtimeFence: {
          generation: fence.generation,
          credentialFingerprint: fence.credentialFingerprint,
        },
        botToken: credentials.botToken,
        fetch: fetchImpl,
        authorize,
        force,
        onState: async (tx, state) =>
          setCapability(tx, state.phase === "registered"),
      });
      if (result.kind === "deferred") return;
      await db.transaction(async (tx) => {
        await authorize(tx);
        const registered =
          result.kind === "registered"
            ? await readRegisteredDiscordCommandRegistration(tx, scope)
            : null;
        await setCapability(tx, registered !== null);
        await lease.assertOwned(tx);
      });
    };
    try {
      if (existingLease) await reconcile(existingLease);
      else await withCredentialMutationLease(initial.endpoint, reconcile);
    } catch {
      // Commands are additive. Do not fail an otherwise working mention/thread
      // connection or expose provider errors/tokens when registration is busy.
      logger.warn(
        { endpointId },
        "Discord command registration remains unconfirmed",
      );
    }
  }

  async function runtimeFor(
    endpoint: EndpointRow,
    optionsForRuntime: {
      requireDiscordOwnership?: boolean;
      waitForDiscordOwnership?: boolean;
    } = {},
  ): Promise<ChatSdkEndpointRuntime> {
    for (;;) {
      const record = await endpointRecord(endpoint.id);
      if (!record) throw notFound("Chat endpoint not found");
      if (
        record.endpoint.status === "archived" ||
        record.endpoint.status === "paused" ||
        record.endpoint.status === "draft"
      ) {
        throw conflict("Chat endpoint runtime is not available in this state", {
          code: "chat_endpoint_runtime_unavailable",
        });
      }
      const context = runtimeContextForRecord(record);
      const current = runtime.get(endpoint.id);
      const currentDiscordOwnership = discordGatewayOwnerships.get(endpoint.id);
      const currentOwnsDiscordGateway =
        currentDiscordOwnership !== undefined &&
        !currentDiscordOwnership.stopping &&
        currentDiscordOwnership.context.version === context.version &&
        currentDiscordOwnership.context.endpointRuntime === current &&
        currentDiscordOwnership.expiresAt.getTime() > Date.now();
      if (
        current &&
        runtimeVersions.get(endpoint.id) === context.version &&
        (record.endpoint.provider !== "discord" ||
          optionsForRuntime.requireDiscordOwnership !== true ||
          currentOwnsDiscordGateway)
      )
        return current;

      const pending = runtimeInitializations.get(endpoint.id);
      if (pending) {
        try {
          const instance = await pending.promise;
          if (
            pending.version === context.version &&
            (optionsForRuntime.requireDiscordOwnership !== true ||
              pending.discordGatewayOwned)
          ) {
            return instance;
          }
          if (
            pending.version === context.version &&
            optionsForRuntime.requireDiscordOwnership === true
          ) {
            await new Promise((resolve) =>
              setTimeout(resolve, DISCORD_GATEWAY_LEASE_POLL_MS),
            );
            continue;
          }
        } catch (error) {
          if (pending.version === context.version) {
            if (
              optionsForRuntime.waitForDiscordOwnership === true &&
              isDiscordGatewayNotOwnedError(error)
            ) {
              await new Promise((resolve) =>
                setTimeout(resolve, DISCORD_GATEWAY_LEASE_POLL_MS),
              );
              continue;
            }
            throw error;
          }
        }
        continue;
      }

      const initialization: {
        discordGatewayOwned: boolean;
        promise: Promise<ChatSdkEndpointRuntime>;
        version: string;
      } = {
        discordGatewayOwned: false,
        promise: undefined as unknown as Promise<ChatSdkEndpointRuntime>,
        version: context.version,
      };
      const promise = (async () => {
        const discordOwnership =
          record.endpoint.provider === "discord"
            ? await acquireDiscordGatewayOwnership(
                record.endpoint,
                context,
                optionsForRuntime.waitForDiscordOwnership === true,
              )
            : null;
        if (
          record.endpoint.provider === "discord" &&
          !discordOwnership &&
          optionsForRuntime.requireDiscordOwnership === true
        ) {
          throw discordGatewayNotOwnedError();
        }
        initialization.discordGatewayOwned = discordOwnership !== null;
        context.discordGatewayOwned = discordOwnership !== null;
        let instance: ChatSdkEndpointRuntime | null = null;
        try {
          const stale = runtime.get(endpoint.id);
          if (stale) {
            runtimeVersions.delete(endpoint.id);
            await runtime.removeEndpoint(endpoint.id);
          }
          recordChatWebhookStage("runtime_initializing", record.endpoint.id);
          const credentials = await resolveCredentials(record.endpoint);
          const discordCommands =
            record.endpoint.provider === "discord" &&
            record.endpoint.botExternalId &&
            record.endpoint.providerAccountId
              ? await readRegisteredDiscordCommandRegistration(db, {
                  companyId: record.endpoint.companyId,
                  endpointId: record.endpoint.id,
                  applicationId: record.endpoint.botExternalId,
                  guildId: record.endpoint.providerAccountId,
                })
              : null;
          context.discordCommandId =
            discordCommands && record.endpoint.capabilities.slashCommands
              ? discordCommands.receipt.commandId
              : undefined;
          instance = await runtime.replaceEndpoint({
            companyId: record.endpoint.companyId,
            endpointId: record.endpoint.id,
            providerConfig: runtimeConfig(
              record.endpoint,
              record.endpoint.botUsername ?? record.assignedAgentName,
              credentials,
            ),
            persistence,
            concurrency: record.endpoint.concurrencyPolicy,
            enableDiscordGateway: discordOwnership !== null,
            callbacks: {
              onMessage: (event) => handleSdkMessage(event, context),
              onDiscordRootMentionAdmission:
                record.endpoint.provider === "discord"
                  ? (event) =>
                      admitDiscordRootMention(record.endpoint, event, context)
                  : undefined,
              onDiscordGatewayEvent:
                record.endpoint.provider === "discord"
                  ? (event) => handleDiscordGatewayEvent(event, context)
                  : undefined,
              onAction:
                record.endpoint.capabilities.actions === true
                  ? (event) => handleAction(event, context)
                  : undefined,
              onModalSubmit:
                record.endpoint.capabilities.modals === true ||
                record.endpoint.provider === "discord"
                  ? (event) => handleModalSubmit(event, context)
                  : undefined,
              onMessageDeleted: (event) => handleMessageDeleted(event, context),
              onMessageUpdated: (event) => handleMessageUpdated(event, context),
              onTeamsFileConsent:
                record.endpoint.provider === "microsoft-teams"
                  ? (event) => handleTeamsFileConsent(event, context)
                  : undefined,
              onTelegramGenerationStopped:
                record.endpoint.provider === "telegram"
                  ? (event) => handleTelegramGenerationStopped(event, context)
                  : undefined,
              onReaction:
                record.endpoint.capabilities.reactions === true
                  ? (event) => handleReaction(event, context)
                  : undefined,
              // Dynamic options remain unregistered. Native question buttons and
              // forms resolve only through issued durable rows. Reactions are an
              // auditable social signal, never an approval or task instruction.
              // Telegram exposes bot commands through Chat SDK's slash-command
              // callback even though it does not support arbitrary registered slash
              // commands. Paperclip still needs that callback for /new, /close, and
              // /status session controls.
              // Discord must always install the guarded private-response path:
              // an unavailable registration still needs a terminal denial for a
              // cached provider command, not the SDK's unhandled deferred reply.
              onSlashCommand:
                record.endpoint.provider === "discord" ||
                record.endpoint.capabilities.slashCommands ||
                record.endpoint.provider === "telegram"
                  ? (event) => handleSlashCommand(event, context)
                  : undefined,
            },
          });
          context.endpointRuntime = instance;
          runtimeContexts.set(instance as object, context);
          await instance.initialize();
          const latest = await endpointRecord(endpoint.id);
          const stillRegistered = runtime.get(endpoint.id) === instance;
          const stillCurrent =
            latest !== null &&
            latest.endpoint.status === record.endpoint.status &&
            runtimeContextForRecord(latest).version === context.version;
          if (!stillRegistered || !stillCurrent) {
            if (stillRegistered) {
              await runtime.removeEndpoint(endpoint.id);
              runtimeVersions.delete(endpoint.id);
            }
            throw conflict(
              "Chat endpoint runtime changed while it was initializing",
              {
                code: "chat_endpoint_runtime_superseded",
              },
            );
          }
          if (
            discordOwnership &&
            (discordGatewayOwnerships.get(endpoint.id) !== discordOwnership ||
              discordOwnership.stopping ||
              discordOwnership.expiresAt.getTime() <= Date.now())
          ) {
            throw discordGatewayNotOwnedError();
          }
          runtimeVersions.set(endpoint.id, context.version);
          return instance;
        } catch (error) {
          if (instance && runtime.get(endpoint.id) === instance) {
            await runtime.removeEndpoint(endpoint.id).catch(() => undefined);
            runtimeVersions.delete(endpoint.id);
          } else if (!runtime.get(endpoint.id)) {
            runtimeVersions.delete(endpoint.id);
          }
          if (discordOwnership) {
            await stopDiscordGatewayOwnership(discordOwnership, false);
          }
          throw error;
        }
      })();
      initialization.promise = promise;
      runtimeInitializations.set(endpoint.id, initialization);
      try {
        return await promise;
      } finally {
        if (runtimeInitializations.get(endpoint.id) === initialization) {
          runtimeInitializations.delete(endpoint.id);
        }
      }
    }
  }

  async function reconcileProviderRuntimes() {
    if (shuttingDown) {
      return { eligible: 0, local: 0, ownedElsewhere: 0, failed: 0 };
    }
    const eligibleRows = await db
      .select({ endpointId: chatEndpoints.id })
      .from(chatEndpoints)
      .innerJoin(
        toolConnections,
        and(
          eq(toolConnections.id, chatEndpoints.connectionId),
          eq(toolConnections.companyId, chatEndpoints.companyId),
        ),
      )
      .where(
        and(
          eq(chatEndpoints.provider, "discord"),
          inArray(chatEndpoints.status, ["verifying", "active", "attention"]),
          eq(toolConnections.status, "active"),
          eq(toolConnections.enabled, true),
        ),
      );
    const eligibleIds = new Set(eligibleRows.map((row) => row.endpointId));
    await Promise.all(
      [...discordGatewayOwnerships.values()]
        .filter((ownership) => !eligibleIds.has(ownership.endpointId))
        .map((ownership) => stopDiscordGatewayOwnership(ownership)),
    );

    let local = 0;
    let ownedElsewhere = 0;
    let failed = 0;
    for (const row of eligibleRows) {
      const record = await endpointRecord(row.endpointId);
      if (!record) continue;
      try {
        let instance = await runtimeFor(record.endpoint, {
          requireDiscordOwnership: true,
        });
        await reconcileDiscordCommands(row.endpointId);
        const afterCommands = await endpointRecord(row.endpointId);
        const desiredCommands =
          afterCommands?.endpoint.capabilities.slashCommands &&
          afterCommands.endpoint.botExternalId &&
          afterCommands.endpoint.providerAccountId
            ? await readRegisteredDiscordCommandRegistration(db, {
                companyId: afterCommands.endpoint.companyId,
                endpointId: row.endpointId,
                applicationId: afterCommands.endpoint.botExternalId,
                guildId: afterCommands.endpoint.providerAccountId,
              })
            : null;
        // A missing command handler needs a new runtime only on upgrade.
        // Loss of registration is denied by the existing callback's current
        // durable checks; optional REST maintenance must not tear down a
        // healthy Gateway used for ordinary mentions and thread messages.
        if (
          afterCommands &&
          desiredCommands &&
          runtimeContexts.get(instance as object)?.discordCommandId !==
            desiredCommands.receipt.commandId
        ) {
          await invalidateRuntime(row.endpointId);
          instance = await runtimeFor(afterCommands.endpoint, {
            requireDiscordOwnership: true,
          });
        }
        const context = runtimeContexts.get(instance as object);
        if (
          CAPABILITIES.discord.modals &&
          context &&
          runtime.get(row.endpointId) === instance
        ) {
          // Existing connected endpoints acquire the new implementation
          // capability only after the pinned runtime initialized successfully.
          // No reconnect, policy/reach change, credential rotation, or runtime
          // generation change is needed: its Discord handler is registered
          // even while the persisted capability remains disabled.
          await db.transaction(async (tx) => {
            const current = await runtimeCallbackEndpoint(
              tx,
              row.endpointId,
              context,
              ["verifying", "active", "attention"],
            );
            if (
              !current ||
              current.provider !== "discord" ||
              current.capabilities.modals === true ||
              runtime.get(row.endpointId) !== instance
            )
              return;
            const connection = await tx
              .select({
                enabled: toolConnections.enabled,
                status: toolConnections.status,
                refs: toolConnections.credentialSecretRefs,
              })
              .from(toolConnections)
              .where(
                and(
                  eq(toolConnections.companyId, current.companyId),
                  eq(toolConnections.id, current.connectionId),
                ),
              )
              .for("no key update")
              .then((rows) => rows[0]);
            if (
              !connection?.enabled ||
              connection.status !== "active" ||
              credentialFingerprint(connection.refs) !==
                context.credentialFingerprint ||
              runtime.get(row.endpointId) !== instance ||
              !discordGatewayRuntimeIsCurrent(row.endpointId, context)
            )
              return;
            await tx
              .update(chatEndpoints)
              .set({ capabilities: { ...current.capabilities, modals: true } })
              .where(
                and(
                  eq(chatEndpoints.companyId, current.companyId),
                  eq(chatEndpoints.id, current.id),
                ),
              );
          });
        }
        local += 1;
      } catch (error) {
        if (isDiscordGatewayNotOwnedError(error)) {
          ownedElsewhere += 1;
          continue;
        }
        failed += 1;
        logger.warn(
          { endpointId: row.endpointId, error: redactError(error) },
          "could not reconcile Discord Gateway runtime",
        );
      }
    }
    return {
      eligible: eligibleRows.length,
      local,
      ownedElsewhere,
      failed,
    };
  }

  async function configure(
    endpointId: string,
    input: ConfigureChatEndpointInput,
    actorUserId?: string | null,
  ) {
    const record = await endpointRecord(endpointId);
    if (!record) throw notFound("Chat endpoint not found");
    const suppliedCredentialKeys = Object.keys(input.credentials ?? {});
    if (suppliedCredentialKeys.length > 0) {
      const credentialAction =
        input.action === "configure" || input.action === "reconnect";
      const allowedKeys = new Set(
        credentialAction
          ? SUPPLIED_CREDENTIAL_KEYS[record.endpoint.provider]
          : [],
      );
      const unsupportedKeys = suppliedCredentialKeys.filter(
        (key) => !allowedKeys.has(key),
      );
      if (unsupportedKeys.length > 0) {
        throw unprocessable(
          `Unsupported ${PROVIDER_LABELS[record.endpoint.provider]} credential fields for ${input.action}: ${unsupportedKeys.join(", ")}`,
          {
            code: "chat_endpoint_credentials_invalid",
            provider: record.endpoint.provider,
            action: input.action,
            unsupportedKeys,
          },
        );
      }
    }
    return withCredentialMutationLease(record.endpoint, (credentialLease) =>
      configureWithCredentialLease(
        endpointId,
        input,
        credentialLease,
        actorUserId,
      ),
    );
  }

  async function configureWithCredentialLease(
    endpointId: string,
    input: ConfigureChatEndpointInput,
    credentialLease: CredentialMutationLeaseGuard,
    actorUserId?: string | null,
  ) {
    const record = await endpointRecord(endpointId);
    if (!record) throw notFound("Chat endpoint not found");
    const endpoint = record.endpoint;
    if (input.action === "pause") {
      if (endpoint.status !== "active") {
        throw conflict("Only an active chat connection can be paused", {
          code: "chat_endpoint_not_active",
        });
      }
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const pausedAt = new Date();
        const current = await tx
          .select({ setup: chatEndpoints.setup, status: chatEndpoints.status })
          .from(chatEndpoints)
          .where(eq(chatEndpoints.id, endpoint.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current || current.status !== "active") {
          throw conflict("Only an active chat connection can be paused", {
            code: "chat_endpoint_not_active",
          });
        }
        await tx
          .update(chatEndpoints)
          .set({
            status: "paused",
            setup: {
              ...current.setup,
              runtimeGeneration: runtimeGeneration(current.setup) + 1,
            } as InternalSetupState,
            updatedAt: pausedAt,
          })
          .where(eq(chatEndpoints.id, endpoint.id));
        await tx
          .update(toolConnections)
          .set({ status: "disabled", enabled: false, updatedAt: new Date() })
          .where(eq(toolConnections.id, endpoint.connectionId));
        await tx
          .update(chatDeliveries)
          .set({
            state: "filtered",
            nextAttemptAt: null,
            redactedError: "Connection was paused before processing",
            processedAt: pausedAt,
            updatedAt: pausedAt,
          })
          .where(
            and(
              eq(chatDeliveries.endpointId, endpoint.id),
              inArray(chatDeliveries.state, ["received", "retry"]),
            ),
          );
        await credentialLease.assertOwned(tx);
      });
      await invalidateRuntime(endpoint.id);
      await logActivity(db, {
        companyId: endpoint.companyId,
        actorType: "user",
        actorId: actorUserId ?? "board",
        action: "chat_endpoint.paused",
        entityType: "tool_connection",
        entityId: endpoint.connectionId,
        details: { endpointId: endpoint.id },
      });
      return get(endpoint.id);
    }
    if (input.action === "resume") {
      if (endpoint.status !== "paused" || endpoint.setup.step !== "complete") {
        throw conflict(
          "Only a previously active chat connection can be resumed",
          {
            code: "chat_endpoint_not_resumable",
          },
        );
      }
      let credentials = await resolveCredentials(endpoint).catch(() => {
        throw conflict("Reconnect the provider credentials before resuming", {
          code: "chat_endpoint_credentials_missing",
        });
      });
      const identity = await verifyCredentials(endpoint.provider, credentials);
      const upgradingLegacyGitHubIdentity =
        endpoint.provider === "github" &&
        !endpoint.botExternalId &&
        legacyGitHubLabelsMatchVerifiedCredentials(endpoint, identity);
      if (
        !upgradingLegacyGitHubIdentity &&
        !nativeBotIdentityMatches(endpoint.provider, endpoint, identity)
      ) {
        throw conflict(
          "The provider credentials now identify a different bot; reconnect this connection instead",
          {
            code: "chat_bot_identity_changed",
          },
        );
      }
      await assertNativeBotIdentityAvailable(endpoint, identity);
      const prepared = await prepareProviderInventory(endpoint, credentials);
      if (
        endpoint.provider === "github" &&
        prepared.credentials.installationId !== credentials.installationId
      ) {
        await persistCredentials(
          endpoint,
          prepared.credentials,
          credentialLease,
          actorUserId,
        );
      }
      credentials = prepared.credentials;
      if (prepared.inventory)
        await reconcileProviderResourceRows(
          endpoint,
          prepared.inventory,
          credentialLease,
        );
      let activatedEndpoint!: EndpointRow;
      try {
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const resumedAt = new Date();
          const current = await tx
            .select()
            .from(chatEndpoints)
            .where(eq(chatEndpoints.id, endpoint.id))
            .for("update")
            .then((rows) => rows[0] ?? null);
          if (!current || current.status !== "paused") {
            throw conflict(
              "Only a previously active chat connection can be resumed",
              {
                code: "chat_endpoint_not_resumable",
              },
            );
          }
          // Fail closed for any legacy or racing delivery that remained open
          // while this endpoint was paused. Resume must never execute traffic
          // that Paperclip acknowledged during the inactive interval.
          await tx
            .update(chatDeliveries)
            .set({
              state: "filtered",
              nextAttemptAt: null,
              redactedError: "Connection was paused when this event arrived",
              processedAt: resumedAt,
              updatedAt: resumedAt,
            })
            .where(
              and(
                eq(chatDeliveries.endpointId, endpoint.id),
                inArray(chatDeliveries.state, ["received", "retry"]),
              ),
            );
          [activatedEndpoint] = await tx
            .update(chatEndpoints)
            .set({
              status: "active",
              ...(upgradingLegacyGitHubIdentity
                ? { botExternalId: identity.botExternalId }
                : {}),
              healthMessage: "Connected",
              lastError: null,
              setup: {
                ...current.setup,
                runtimeGeneration: runtimeGeneration(current.setup) + 1,
              } as InternalSetupState,
              updatedAt: resumedAt,
            })
            .where(eq(chatEndpoints.id, endpoint.id))
            .returning();
          await tx
            .update(toolConnections)
            .set({
              status: "active",
              enabled: true,
              healthStatus: "healthy",
              healthMessage: "Connected",
              lastError: null,
              healthCheckedAt: new Date(),
              updatedAt: new Date(),
            })
            .where(eq(toolConnections.id, endpoint.connectionId));
          await credentialLease.assertOwned(tx);
        });
        await invalidateRuntime(endpoint.id);
        if (activatedEndpoint.provider === "discord")
          await reconcileDiscordCommands(endpoint.id, credentialLease, true);
        await runtimeFor(activatedEndpoint, {
          requireDiscordOwnership: activatedEndpoint.provider === "discord",
          waitForDiscordOwnership: activatedEndpoint.provider === "discord",
        });
      } catch (error) {
        await invalidateRuntime(endpoint.id).catch(() => undefined);
        if (activatedEndpoint) {
          const failure = redactError(error);
          const failedAt = new Date();
          await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            await tx
              .update(chatEndpoints)
              .set({
                status: "attention",
                healthMessage: "Provider resume needs attention",
                lastError: failure,
                updatedAt: failedAt,
              })
              .where(
                and(
                  eq(chatEndpoints.id, endpoint.id),
                  eq(chatEndpoints.status, "active"),
                  sql`coalesce((${chatEndpoints.setup}->>'runtimeGeneration')::integer, 0) = ${runtimeGeneration(activatedEndpoint.setup)}`,
                ),
              );
            await tx
              .update(toolConnections)
              .set({
                status: "disabled",
                enabled: false,
                healthStatus: "degraded",
                healthMessage: "Provider resume failed",
                lastError: failure,
                healthCheckedAt: failedAt,
                updatedAt: failedAt,
              })
              .where(eq(toolConnections.id, endpoint.connectionId));
            await tx
              .update(chatDeliveries)
              .set({
                state: "filtered",
                nextAttemptAt: null,
                redactedError: "Connection activation failed",
                processedAt: failedAt,
                updatedAt: failedAt,
              })
              .where(
                and(
                  eq(chatDeliveries.endpointId, endpoint.id),
                  inArray(chatDeliveries.state, ["received", "retry"]),
                ),
              );
            await credentialLease.assertOwned(tx);
          });
        }
        throw error;
      }
      await logActivity(db, {
        companyId: endpoint.companyId,
        actorType: "user",
        actorId: actorUserId ?? "board",
        action: "chat_endpoint.resumed",
        entityType: "tool_connection",
        entityId: endpoint.connectionId,
        details: { endpointId: endpoint.id },
      });
      return get(endpoint.id);
    }
    if (input.action === "remove") {
      if (endpoint.status === "archived") {
        // Archival is the durable ingress fence and intentionally commits
        // before secret-store cleanup. If that cleanup failed, a repeated
        // remove is the recovery operation; once refs are empty, retain the
        // normal already-removed conflict contract.
        if (record.credentialSecretRefs.length > 0) {
          await invalidateRuntime(endpoint.id).catch(() => undefined);
          if (endpoint.provider === "telegram") {
            await credentialLease.assertOwned();
            const action = await stageTelegramMaintenance(
              endpoint,
              "remove_endpoint",
            );
            if (action)
              await processTelegramMaintenance(
                action.id,
                true,
                credentialLease,
              );
          } else {
            await clearCredentials(endpoint, credentialLease);
          }
          return get(endpoint.id);
        }
        throw conflict("This chat connection has already been removed", {
          code: "chat_endpoint_already_removed",
        });
      }
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const current = await tx
          .select({ setup: chatEndpoints.setup, status: chatEndpoints.status })
          .from(chatEndpoints)
          .where(eq(chatEndpoints.id, endpoint.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current || current.status === "archived") {
          throw conflict("This chat connection has already been removed", {
            code: "chat_endpoint_already_removed",
          });
        }
        await tx
          .update(chatEndpoints)
          .set({
            status: "archived",
            setup: {
              ...current.setup,
              runtimeGeneration: runtimeGeneration(current.setup) + 1,
            } as InternalSetupState,
            archivedAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(chatEndpoints.id, endpoint.id));
        await tx
          .update(chatConversations)
          .set({ state: "endpoint_removed", updatedAt: new Date() })
          .where(eq(chatConversations.endpointId, endpoint.id));
        await tx
          .update(toolConnections)
          .set({ status: "archived", enabled: false, updatedAt: new Date() })
          .where(eq(toolConnections.id, endpoint.connectionId));
        const otherConnection = await tx
          .select({ id: toolConnections.id })
          .from(toolConnections)
          .where(
            and(
              eq(toolConnections.companyId, endpoint.companyId),
              eq(toolConnections.applicationId, record.applicationId),
              ne(toolConnections.id, endpoint.connectionId),
              ne(toolConnections.status, "archived"),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null);
        if (!otherConnection) {
          await tx
            .update(toolApplications)
            .set({
              status: "archived",
              archivedAt: new Date(),
              updatedAt: new Date(),
            })
            .where(eq(toolApplications.id, record.applicationId));
        }
        await credentialLease.assertOwned(tx);
      });
      await invalidateRuntime(endpoint.id).catch(() => undefined);
      if (endpoint.provider === "telegram") {
        await credentialLease.assertOwned();
        const action = await stageTelegramMaintenance(
          endpoint,
          "remove_endpoint",
        );
        if (action) {
          await processTelegramMaintenance(action.id, true, credentialLease);
        }
      } else {
        await clearCredentials(endpoint, credentialLease);
      }
      return get(endpoint.id);
    }
    if (
      input.action !== "configure" &&
      input.action !== "reconnect" &&
      input.action !== "verify"
    ) {
      throw unprocessable("Unsupported chat endpoint setup action");
    }
    if (!webhookPublicBaseUrl && endpoint.provider !== "discord") {
      throw unprocessable(
        `A public HTTPS Paperclip URL is required before connecting ${PROVIDER_LABELS[endpoint.provider]}`,
      );
    }
    if (
      endpoint.provider === "telegram" &&
      (input.action === "configure" || input.action === "reconnect") &&
      !isSupportedTelegramWebhookBaseUrl(webhookPublicBaseUrl)
    ) {
      throw unprocessable(
        "Telegram webhooks require PAPERCLIP_CHAT_WEBHOOK_PUBLIC_URL to use HTTPS on port 443, 80, 88, or 8443",
        {
          code: "chat_telegram_webhook_url_unsupported",
          provider: "telegram",
          supportedPorts: [443, 80, 88, 8443],
        },
      );
    }
    if (input.action === "verify") {
      if (
        endpoint.provider !== "slack" ||
        endpoint.status !== "verifying" ||
        endpoint.setup.step !== "provider_setup"
      ) {
        throw conflict(
          "Provider verification is not available at this setup step",
          {
            code: "chat_endpoint_invalid_setup_step",
          },
        );
      }
      if (!endpoint.setup.webhookVerifiedAt) {
        throw conflict("Slack has not verified the Paperclip Request URL yet", {
          code: "chat_webhook_not_verified",
        });
      }
    } else if (
      input.action === "configure" &&
      !["draft", "attention", "revoked"].includes(endpoint.status)
    ) {
      throw conflict(
        "This connection is already configured; use its reconnect flow if credentials need repair",
        {
          code: "chat_endpoint_already_configured",
        },
      );
    } else if (
      input.action === "reconnect" &&
      !["verifying", "active", "attention", "revoked", "paused"].includes(
        endpoint.status,
      )
    ) {
      throw conflict(
        "This chat connection does not currently need reconnecting",
        {
          code: "chat_endpoint_not_reconnectable",
        },
      );
    }
    if (
      endpoint.provider === "github" &&
      (input.action === "configure" || input.action === "reconnect") &&
      !endpoint.setup.webhookVerifiedAt
    ) {
      throw conflict(
        "GitHub has not delivered a signed webhook ping for this secret yet",
        {
          code: "chat_webhook_not_verified",
        },
      );
    }

    let verifiedCurrentIdentity: VerifiedProviderIdentity = endpoint;
    if (
      input.action === "reconnect" &&
      endpoint.provider === "github" &&
      !endpoint.botExternalId
    ) {
      const storedCredentials = await resolveCredentials(endpoint).catch(() => {
        throw conflict(
          "Reconnect the existing GitHub App credentials before changing them",
          {
            code: "chat_bot_identity_unverifiable",
          },
        );
      });
      const storedIdentity = await verifyCredentials(
        "github",
        storedCredentials,
      );
      if (
        !legacyGitHubLabelsMatchVerifiedCredentials(endpoint, storedIdentity)
      ) {
        throw conflict(
          "The stored credentials no longer verify the GitHub App that owns this connection",
          {
            code: "chat_bot_identity_unverifiable",
          },
        );
      }
      verifiedCurrentIdentity = storedIdentity;
    }

    let credentials =
      input.credentials && Object.keys(input.credentials).length > 0
        ? await normalizedCredentials(endpoint, input.credentials)
        : await resolveCredentials(endpoint).catch(() => {
            throw unprocessable(
              `${PROVIDER_LABELS[endpoint.provider]} credentials are required`,
            );
          });
    const identity = await verifyCredentials(endpoint.provider, credentials);
    // Once setup has claimed a provider bot identity, every credential repair
    // must prove that same identity before secrets can be replaced. A process
    // interruption can leave the endpoint in `attention` after the claim but
    // before credential persistence; a repeated first-setup request must not
    // turn that recovery state into an identity-swap escape hatch.
    if (input.action === "reconnect" || Boolean(endpoint.botExternalId)) {
      if (
        !nativeBotIdentityMatches(
          endpoint.provider,
          verifiedCurrentIdentity,
          identity,
        )
      ) {
        throw conflict(
          "The provider credentials identify a different bot; create a new connection for that bot instead",
          { code: "chat_bot_identity_changed" },
        );
      }
    }
    await assertNativeBotIdentityAvailable(endpoint, identity);
    const prepared = await prepareProviderInventory(endpoint, credentials);
    const credentialsChangedByDiscovery =
      endpoint.provider === "github" &&
      prepared.credentials.installationId !== credentials.installationId;
    credentials = prepared.credentials;
    await options.nativeBotIdentityClaimBarrier?.();
    // Claim a fresh provider identity before any newly supplied secrets are
    // persisted. The provider-global unique indexes are the multi-process
    // arbitration boundary when two setup requests both pass the optimistic
    // preflight. A process that stops after this small claim leaves a
    // fail-closed attention endpoint that the same operator can reconnect;
    // it never leaves credentials bound to the losing endpoint.
    if (!endpoint.botExternalId) {
      try {
        const claimed = await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const rows = await tx
            .update(chatEndpoints)
            .set({
              status: "attention",
              providerAccountId: identity.providerAccountId ?? null,
              providerAccountLabel: identity.providerAccountLabel ?? null,
              botExternalId: identity.botExternalId ?? null,
              botUsername: identity.botUsername ?? null,
              botDisplayName:
                identity.botLabel ??
                endpoint.botDisplayName ??
                record.assignedAgentName,
              healthMessage: "Provider setup must be completed",
              lastError: null,
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatEndpoints.id, endpoint.id),
                eq(chatEndpoints.status, endpoint.status),
                isNull(chatEndpoints.botExternalId),
              ),
            )
            .returning({ id: chatEndpoints.id });
          await credentialLease.assertOwned(tx);
          return rows;
        });
        if (claimed.length !== 1) {
          throw conflict("This chat connection changed during setup", {
            code: "chat_endpoint_setup_changed",
          });
        }
      } catch (error) {
        if (isNativeBotIdentityUniqueViolation(error)) {
          throw nativeBotIdentityConflict(endpoint.provider);
        }
        throw error;
      }
    }
    if (
      (input.credentials && Object.keys(input.credentials).length > 0) ||
      credentialsChangedByDiscovery
    )
      await persistCredentials(
        endpoint,
        credentials,
        credentialLease,
        actorUserId,
      );
    if (prepared.inventory)
      await reconcileProviderResourceRows(
        endpoint,
        prepared.inventory,
        credentialLease,
      );
    const updatedAt = new Date();
    const waitingForSlackConfiguration =
      endpoint.provider === "slack" &&
      (input.action === "configure" || input.action === "reconnect");
    try {
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        const current = await tx
          .select({ setup: chatEndpoints.setup })
          .from(chatEndpoints)
          .where(eq(chatEndpoints.id, endpoint.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current) throw notFound("Chat endpoint not found");
        await tx
          .update(chatEndpoints)
          .set({
            status: "verifying",
            providerAccountId: identity.providerAccountId ?? null,
            providerAccountLabel: identity.providerAccountLabel ?? null,
            botExternalId: identity.botExternalId ?? null,
            botUsername: identity.botUsername ?? null,
            botDisplayName:
              identity.botLabel ??
              endpoint.botDisplayName ??
              record.assignedAgentName,
            healthMessage: waitingForSlackConfiguration
              ? "Finish provider webhook configuration"
              : "Waiting for a test conversation",
            lastError: null,
            lastEventAt: null,
            setup: {
              ...current.setup,
              step: waitingForSlackConfiguration ? "provider_setup" : "test",
              testStartedAt: waitingForSlackConfiguration
                ? null
                : updatedAt.toISOString(),
              webhookVerifiedAt: waitingForSlackConfiguration
                ? null
                : (current.setup.webhookVerifiedAt ?? null),
              runtimeGeneration: runtimeGeneration(current.setup) + 1,
            } as InternalSetupState,
            updatedAt,
          })
          .where(eq(chatEndpoints.id, endpoint.id));
        await tx
          .update(toolConnections)
          .set({
            status: "active",
            enabled: true,
            healthStatus: "healthy",
            healthMessage: "Provider credentials verified",
            healthCheckedAt: updatedAt,
            updatedAt,
          })
          .where(eq(toolConnections.id, endpoint.connectionId));
        await tx
          .update(toolApplications)
          .set({ status: "active", archivedAt: null, updatedAt })
          .where(eq(toolApplications.id, record.applicationId));
        await credentialLease.assertOwned(tx);
      });
    } catch (error) {
      if (isNativeBotIdentityUniqueViolation(error)) {
        throw nativeBotIdentityConflict(endpoint.provider);
      }
      throw error;
    }
    try {
      const next = await endpointRecord(endpoint.id);
      if (!next) throw notFound("Chat endpoint not found");
      await invalidateRuntime(endpoint.id);
      if (endpoint.provider === "github" && input.action === "reconnect") {
        // The immutable App and its installation were verified above. Repair
        // only its callback using the stored secret; never reinstall it or
        // change repository access. Keep historical signed-ping evidence, but
        // require the fresh test round trip established above before activation.
        const auditWebhookSync = async (action: string) => {
          await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            await logActivity(tx as unknown as Db, {
              companyId: endpoint.companyId,
              actorType: "user",
              actorId: actorUserId ?? "board",
              action,
              entityType: "tool_connection",
              entityId: endpoint.connectionId,
              details: { endpointId: endpoint.id, provider: "github" },
            });
            await credentialLease.assertOwned(tx);
          });
        };
        await auditWebhookSync("chat_endpoint.webhook_sync_started");
        await credentialLease.assertOwned();
        await resyncGitHubAppWebhook({
          fetch: fetchImpl,
          appToken: githubAppJwt(credentials.appId, credentials.privateKey),
          webhookUrl: `${webhookPublicBaseUrl}/api/chat-webhooks/${endpoint.publicId}/github`,
          webhookSecret: credentials.webhookSecret,
        });
        await auditWebhookSync("chat_endpoint.webhook_synced");
      }
      if (next.endpoint.provider === "discord")
        await reconcileDiscordCommands(endpoint.id, credentialLease, true);
      await runtimeFor(next.endpoint, {
        requireDiscordOwnership: next.endpoint.provider === "discord",
        waitForDiscordOwnership: next.endpoint.provider === "discord",
      });

      if (endpoint.provider === "telegram" && webhookPublicBaseUrl) {
        const webhookUrl = `${webhookPublicBaseUrl}/api/chat-webhooks/${endpoint.publicId}/telegram`;
        const infoResponse = await fetchImpl(
          `https://api.telegram.org/bot${encodeURIComponent(credentials.botToken)}/getWebhookInfo`,
          { signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS) },
        );
        const infoResult = (await infoResponse.json()) as {
          ok?: boolean;
          description?: string;
          result?: { url?: string };
        };
        if (!infoResponse.ok || !infoResult.ok) {
          throw unprocessable(
            `Telegram could not inspect the existing webhook: ${infoResult.description ?? infoResponse.status}`,
          );
        }
        await credentialLease.assertOwned();
        const response = await fetchImpl(
          `https://api.telegram.org/bot${encodeURIComponent(credentials.botToken)}/setWebhook`,
          {
            method: "POST",
            signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS),
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
              url: webhookUrl,
              secret_token: credentials.webhookSecret,
              allowed_updates: [
                "message",
                "edited_message",
                "callback_query",
                "stopped_message_generation",
                "message_reaction",
                "my_chat_member",
              ],
              // A first-time connection may inherit stale updates from a bot
              // that was used before Paperclip owned it. Reconnect is
              // different: Telegram may be holding legitimate updates while
              // the old callback URL is unavailable. Preserve that backlog
              // even when an operator is rotating the public origin.
              drop_pending_updates: input.action === "configure",
            }),
          },
        );
        const result = (await response.json()) as {
          ok?: boolean;
          description?: string;
          result?: unknown;
        };
        if (!response.ok || !result.ok)
          throw unprocessable(
            `Telegram could not register the webhook: ${result.description ?? response.status}`,
          );
        await credentialLease.assertOwned();
        if (result.ok === true && result.result === true) {
          // Telegram's successful boolean receipt acknowledges the exact URL,
          // secret and allowed_updates request above. GET alone cannot prove
          // secret_token, which Telegram deliberately does not return.
          await recordTelegramStopSubscription(
            next.endpoint,
            runtimeContextForRecord(next),
            credentialLease,
          );
        }
        // Command discovery is optional for ingress, but its provider mutation
        // is still a durable, auditable action. A transient or rate-limited
        // failure is retried by the maintenance worker without blocking the
        // otherwise-valid webhook connection.
        const commandAction = await stageTelegramMaintenance(
          endpoint,
          "register_commands",
        );
        if (commandAction)
          await processTelegramMaintenance(
            commandAction.id,
            false,
            credentialLease,
          );
      }
    } catch (error) {
      const failure = redactError(error);
      await invalidateRuntime(endpoint.id).catch(() => undefined);
      await db.transaction(async (tx) => {
        await credentialLease.assertOwned(tx);
        await tx
          .update(chatEndpoints)
          .set({
            status: "attention",
            healthMessage: "Provider setup needs attention",
            lastError: failure,
            updatedAt: new Date(),
          })
          .where(eq(chatEndpoints.id, endpoint.id));
        await tx
          .update(toolConnections)
          .set({
            healthStatus: "degraded",
            healthMessage: "Provider setup failed",
            lastError: failure,
            healthCheckedAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(toolConnections.id, endpoint.connectionId));
        await credentialLease.assertOwned(tx);
      });
      throw unprocessable(failure, { code: "chat_provider_setup_failed" });
    }

    await db.transaction(async (tx) => {
      await credentialLease.assertOwned(tx);
      await logActivity(tx as unknown as Db, {
        companyId: endpoint.companyId,
        actorType: "user",
        actorId: actorUserId ?? "board",
        action:
          input.action === "reconnect"
            ? "chat_endpoint.reconnected"
            : "chat_endpoint.credentials_verified",
        entityType: "tool_connection",
        entityId: endpoint.connectionId,
        details: { endpointId: endpoint.id, provider: endpoint.provider },
      });
      await credentialLease.assertOwned(tx);
    });
    return get(endpoint.id);
  }

  async function test(endpointId: string) {
    const initial = await endpointRecord(endpointId);
    if (!initial) throw notFound("Chat endpoint not found");
    return withCredentialMutationLease(
      initial.endpoint,
      async (credentialLease) => {
        // Reload only after owning the same lane as reconnect, pause, removal,
        // and credential rotation. Qualification and activation must describe
        // one exact provider runtime, never a setup snapshot that a concurrent
        // reconnect has already superseded.
        const record = await endpointRecord(endpointId);
        if (!record) throw notFound("Chat endpoint not found");
        const endpoint = record.endpoint;
        if (endpoint.status !== "verifying" || endpoint.setup.step !== "test") {
          throw conflict("This connection is not waiting for a setup test", {
            code: "chat_endpoint_not_testing",
          });
        }
        const testStartedAtValue = endpoint.setup.testStartedAt;
        const testStartedAt = testStartedAtValue
          ? new Date(testStartedAtValue)
          : null;
        if (
          !endpoint.lastEventAt ||
          !testStartedAtValue ||
          !testStartedAt ||
          Number.isNaN(testStartedAt.getTime()) ||
          endpoint.lastEventAt < testStartedAt
        ) {
          throw conflict(
            "Send the test message in the provider before completing setup",
            {
              code: "chat_test_message_missing",
            },
          );
        }
        const requiredTrigger =
          endpoint.provider === "telegram"
            ? "direct_message"
            : "subscribed_message";
        const qualifyingDelivery = await db
          .select({
            id: chatDeliveries.id,
            conversationId: chatDeliveries.conversationId,
            processedAt: chatDeliveries.processedAt,
          })
          .from(chatDeliveries)
          .where(
            and(
              eq(chatDeliveries.companyId, endpoint.companyId),
              eq(chatDeliveries.endpointId, endpoint.id),
              eq(chatDeliveries.state, "processed"),
              gte(chatDeliveries.processedAt, testStartedAt),
              sql`${chatDeliveries.normalizedEvent}->>'trigger' = ${requiredTrigger}`,
            ),
          )
          .orderBy(desc(chatDeliveries.processedAt))
          .limit(1)
          .then((rows) => rows[0] ?? null);
        if (
          !qualifyingDelivery?.conversationId ||
          !qualifyingDelivery.processedAt
        ) {
          throw conflict(
            endpoint.provider === "telegram"
              ? "Send the test direct message before completing setup"
              : "Reply once without mentioning the agent before completing setup",
            { code: "chat_test_follow_up_missing" },
          );
        }
        const finalPublication = await db
          .select({
            commentId: chatPublications.commentId,
            payload: chatPublications.payload,
          })
          .from(chatPublications)
          .innerJoin(
            issueComments,
            and(
              eq(issueComments.id, chatPublications.commentId),
              eq(issueComments.companyId, chatPublications.companyId),
              eq(issueComments.issueId, chatPublications.issueId),
              eq(issueComments.authorType, "agent"),
              eq(issueComments.authorAgentId, endpoint.assignedAgentId),
            ),
          )
          .innerJoin(
            chatMessageLinks,
            and(
              eq(chatMessageLinks.companyId, chatPublications.companyId),
              eq(chatMessageLinks.endpointId, chatPublications.endpointId),
              eq(
                chatMessageLinks.conversationId,
                chatPublications.conversationId,
              ),
              eq(chatMessageLinks.deliveryId, qualifyingDelivery.id),
              eq(chatMessageLinks.direction, "inbound"),
              isNotNull(chatMessageLinks.commentId),
            ),
          )
          .innerJoin(
            heartbeatRuns,
            and(
              eq(heartbeatRuns.id, issueComments.createdByRunId),
              eq(heartbeatRuns.companyId, chatPublications.companyId),
              eq(heartbeatRuns.agentId, endpoint.assignedAgentId),
              eq(heartbeatRuns.status, "succeeded"),
              eq(
                sql<string>`${heartbeatRuns.contextSnapshot} ->> 'issueId'`,
                sql<string>`${chatPublications.issueId}::text`,
              ),
              or(
                sql`${chatMessageLinks.commentId}::text = ${heartbeatRuns.contextSnapshot} ->> 'wakeCommentId'`,
                sql`${chatMessageLinks.commentId}::text = ${heartbeatRuns.contextSnapshot} ->> 'commentId'`,
                sql`coalesce(${heartbeatRuns.contextSnapshot} -> 'wakeCommentIds', '[]'::jsonb) ? ${chatMessageLinks.commentId}::text`,
              ),
            ),
          )
          .where(
            and(
              eq(chatPublications.companyId, endpoint.companyId),
              eq(chatPublications.endpointId, endpoint.id),
              eq(
                chatPublications.conversationId,
                qualifyingDelivery.conversationId,
              ),
              eq(chatPublications.state, "published"),
              gte(chatPublications.publishedAt, qualifyingDelivery.processedAt),
            ),
          )
          .orderBy(desc(chatPublications.publishedAt))
          .then((rows) =>
            rows.find(
              (row) =>
                row.payload.interactionId === undefined &&
                row.payload.progressState === undefined &&
                row.commentId !== null,
            ),
          );
        if (!finalPublication) {
          throw conflict(
            "Wait for the Paperclip agent to reply to the setup turn before completing setup",
            {
              code: "chat_test_round_trip_incomplete",
            },
          );
        }
        await options.setupTestActivationBarrier?.();
        const expectedGeneration = runtimeGeneration(endpoint.setup);
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const [activated] = await tx
            .update(chatEndpoints)
            .set({
              status: "active",
              setup: {
                ...endpoint.setup,
                step: "complete",
                testStartedAt: null,
              },
              healthMessage: "Connected",
              activatedAt: endpoint.activatedAt ?? new Date(),
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatEndpoints.id, endpointId),
                eq(chatEndpoints.status, "verifying"),
                sql`${chatEndpoints.setup}->>'step' = 'test'`,
                sql`coalesce((${chatEndpoints.setup}->>'runtimeGeneration')::integer, 0) = ${expectedGeneration}`,
                sql`${chatEndpoints.setup}->>'testStartedAt' = ${testStartedAtValue}`,
              ),
            )
            .returning({ id: chatEndpoints.id });
          if (!activated) {
            throw conflict("This setup test was superseded by a reconnect", {
              code: "chat_endpoint_test_superseded",
            });
          }
          await tx
            .update(toolConnections)
            .set({
              status: "active",
              enabled: true,
              healthStatus: "healthy",
              healthMessage: "Connected",
              lastError: null,
              healthCheckedAt: new Date(),
              updatedAt: new Date(),
            })
            .where(eq(toolConnections.id, endpoint.connectionId));
          await credentialLease.assertOwned(tx);
        });
        return get(endpointId);
      },
    );
  }

  async function ensurePrincipal(
    endpoint: EndpointRow,
    author: Author,
    raw?: unknown,
  ) {
    const providerAccountId = endpoint.providerAccountId ?? "unknown";
    const externalId = stableExternalPrincipalId(
      endpoint.provider,
      author,
      raw,
    );
    const [principal] = await db
      .insert(chatExternalPrincipals)
      .values({
        companyId: endpoint.companyId,
        provider: endpoint.provider,
        providerAccountId,
        externalId,
        kind:
          author.isBot === true ? "bot" : author.isSystem ? "system" : "user",
        displayName: author.fullName,
        handle: author.userName,
        isBot: author.isBot === true || author.isMe,
        lastSeenAt: new Date(),
      })
      .onConflictDoUpdate({
        target: [
          chatExternalPrincipals.companyId,
          chatExternalPrincipals.provider,
          chatExternalPrincipals.providerAccountId,
          chatExternalPrincipals.externalId,
        ],
        set: {
          displayName: author.fullName,
          handle: author.userName,
          isBot: author.isBot === true || author.isMe,
          lastSeenAt: new Date(),
          updatedAt: new Date(),
        },
      })
      .returning();
    const link = await db
      .select({
        userId: chatIdentityLinks.paperclipUserId,
        status: chatIdentityLinks.status,
      })
      .from(chatIdentityLinks)
      .where(
        and(
          eq(chatIdentityLinks.endpointId, endpoint.id),
          eq(chatIdentityLinks.principalId, principal.id),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (link?.status === "linked" && link.userId) {
      const membership = await db
        .select({
          status: companyMemberships.status,
          membershipRole: companyMemberships.membershipRole,
        })
        .from(companyMemberships)
        .where(
          and(
            eq(companyMemberships.companyId, endpoint.companyId),
            eq(companyMemberships.principalType, "user"),
            eq(companyMemberships.principalId, link.userId),
          ),
        )
        .then((rows) => rows[0] ?? null);
      // External chat performs the same task mutations as the board. A linked
      // viewer therefore remains read-only instead of gaining write authority
      // merely by using a provider account.
      if (
        membership?.status !== "active" ||
        membership.membershipRole === "viewer"
      ) {
        return { principal, userId: null, linkedDenied: true };
      }
      return { principal, userId: link.userId, linkedDenied: false };
    }
    return { principal, userId: null, linkedDenied: false };
  }

  async function sponsorAllowsGuest(endpoint: EndpointRow): Promise<boolean> {
    // A null sponsor is the local board/operator context used by self-hosted
    // instances. Cloud endpoints retain the creating user and must revalidate
    // that user's current company authority on every sponsored guest turn.
    if (!endpoint.sponsorUserId) return true;
    const membership = await db
      .select({
        status: companyMemberships.status,
        membershipRole: companyMemberships.membershipRole,
      })
      .from(companyMemberships)
      .where(
        and(
          eq(companyMemberships.companyId, endpoint.companyId),
          eq(companyMemberships.principalType, "user"),
          eq(companyMemberships.principalId, endpoint.sponsorUserId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    return (
      membership?.status === "active" && membership.membershipRole !== "viewer"
    );
  }

  async function lockCurrentPrincipalAuthorization(
    tx: DbOrTransaction,
    endpoint: EndpointRow,
    principalId: string,
  ): Promise<{
    allowed: boolean;
    linkedDenied: boolean;
    userId: string | null;
  }> {
    // Link confirmation already uses this transaction-scoped identity key.
    // Taking it at the final task mutation boundary prevents a newly confirmed
    // identity from racing the authorization snapshot. Row locks below also
    // serialize revocation and membership changes that do not use this key.
    await tx.execute(
      sql`select pg_advisory_xact_lock(hashtextextended(${`chat-identity:${endpoint.companyId}:${principalId}`}, 0))`,
    );
    const link = await tx
      .select({
        status: chatIdentityLinks.status,
        userId: chatIdentityLinks.paperclipUserId,
      })
      .from(chatIdentityLinks)
      .where(
        and(
          eq(chatIdentityLinks.companyId, endpoint.companyId),
          eq(chatIdentityLinks.endpointId, endpoint.id),
          eq(chatIdentityLinks.principalId, principalId),
        ),
      )
      .for("update")
      .then((rows) => rows[0] ?? null);
    if (link?.status === "linked") {
      if (!link.userId) {
        return { allowed: false, linkedDenied: true, userId: null };
      }
      const membership = await tx
        .select({
          status: companyMemberships.status,
          membershipRole: companyMemberships.membershipRole,
        })
        .from(companyMemberships)
        .where(
          and(
            eq(companyMemberships.companyId, endpoint.companyId),
            eq(companyMemberships.principalType, "user"),
            eq(companyMemberships.principalId, link.userId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const allowed =
        membership?.status === "active" &&
        membership.membershipRole !== "viewer";
      return {
        allowed,
        linkedDenied: !allowed,
        userId: allowed ? link.userId : null,
      };
    }
    if (!endpoint.allowUnlinkedPeople) {
      return { allowed: false, linkedDenied: false, userId: null };
    }
    if (!endpoint.sponsorUserId) {
      return { allowed: true, linkedDenied: false, userId: null };
    }
    const sponsorMembership = await tx
      .select({
        status: companyMemberships.status,
        membershipRole: companyMemberships.membershipRole,
      })
      .from(companyMemberships)
      .where(
        and(
          eq(companyMemberships.companyId, endpoint.companyId),
          eq(companyMemberships.principalType, "user"),
          eq(companyMemberships.principalId, endpoint.sponsorUserId),
        ),
      )
      .for("update")
      .then((rows) => rows[0] ?? null);
    return {
      allowed:
        sponsorMembership?.status === "active" &&
        sponsorMembership.membershipRole !== "viewer",
      linkedDenied: false,
      userId: null,
    };
  }

  async function requireCurrentExternalActionAuthorization(
    tx: DbTransaction,
    input: {
      conversationId: string;
      endpointId: string;
      expectedUserId: string;
      principalId: string;
      runtimeContext: LifecycleRuntimeFence;
    },
  ): Promise<void> {
    const endpoint = await runtimeCallbackEndpoint(
      tx,
      input.endpointId,
      input.runtimeContext,
      ["active"],
    );
    if (!endpoint) {
      throw forbidden("This chat action is no longer authorized", {
        code: "chat_action_authorization_changed",
      });
    }
    const conversation = await tx
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, endpoint.companyId),
          eq(chatConversations.endpointId, endpoint.id),
          eq(chatConversations.id, input.conversationId),
          inArray(chatConversations.state, ["active", "waiting"]),
        ),
      )
      .for("update")
      .then((rows) => rows[0] ?? null);
    if (!conversation) {
      throw forbidden("This chat action is no longer authorized", {
        code: "chat_action_authorization_changed",
      });
    }
    const resource = conversation.resourceId
      ? await tx
          .select()
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.companyId, endpoint.companyId),
              eq(chatEndpointResources.endpointId, endpoint.id),
              eq(chatEndpointResources.id, conversation.resourceId),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null)
      : null;
    const destinationAllowed = conversation.isDirectMessage
      ? endpoint.allowDirectMessages
      : nonDirectDestinationAllowed(endpoint, resource);
    const authorization = await lockCurrentPrincipalAuthorization(
      tx,
      endpoint,
      input.principalId,
    );
    // Governed actions never fall back to sponsored-guest authority. If the
    // provider identity was relinked while this callback waited, reject this
    // stale actor snapshot and let a fresh callback use the new identity.
    if (
      !destinationAllowed ||
      !authorization.allowed ||
      authorization.userId !== input.expectedUserId
    ) {
      throw forbidden("This chat action is no longer authorized", {
        code: "chat_action_authorization_changed",
      });
    }
  }

  function isExternalActionAuthorizationChange(error: unknown): boolean {
    if (!error || typeof error !== "object") return false;
    const value = error as { details?: unknown };
    return (
      Boolean(value.details) &&
      typeof value.details === "object" &&
      (value.details as { code?: unknown }).code ===
        "chat_action_authorization_changed"
    );
  }

  async function ensureResource(
    endpoint: EndpointRow,
    thread: Thread,
    enabledBySetupActivation: boolean,
    database: DbOrTransaction = db,
  ) {
    const type = providerResourceType(
      endpoint.provider,
      chatSurfaceKind(endpoint.provider, thread),
    );
    const providerResourceId = canonicalProviderResourceId(
      endpoint.provider,
      thread,
    );
    const resourceLabel = providerResourceLabelFromThread(
      endpoint.provider,
      thread,
    );
    const [resource] = await database
      .insert(chatEndpointResources)
      .values({
        companyId: endpoint.companyId,
        endpointId: endpoint.id,
        type,
        providerResourceId,
        label: resourceLabel.label,
        availability: "available",
        enabled: thread.isDM || enabledBySetupActivation,
      })
      .onConflictDoUpdate({
        target: [
          chatEndpointResources.endpointId,
          chatEndpointResources.type,
          chatEndpointResources.providerResourceId,
        ],
        set: {
          // Provider inventory and membership lifecycle own availability.
          // A delayed message must not resurrect a destination after the bot
          // was removed or an installation lost access.
          // Slack callbacks are not guaranteed to carry a channel name. Keep
          // an inventory- or conversations.info-derived label instead of
          // downgrading it to C… / slack:C… when a delayed message arrives.
          ...(resourceLabel.fallback
            ? {}
            : {
                label: sql<string>`case
                  when ${chatEndpointResources.availability} = 'available' then ${resourceLabel.label}
                  else ${chatEndpointResources.label}
                end`,
              }),
          updatedAt: new Date(),
        },
      })
      .returning();
    return resource;
  }

  async function ingestAttachments(input: {
    endpoint: EndpointRow;
    endpointRuntime: ChatSdkEndpointRuntime;
    deliveryId: string;
    issueId: string;
    issueCommentId: string;
    attachments: Attachment[];
    attachmentLimitOmissions?: number;
    unavailableReferenceCount?: number;
    actorUserId: string | null;
  }): Promise<{
    storedIds: string[];
    omissionReasons: Record<string, number>;
  }> {
    const omissionReasons: Record<string, number> = {};
    const omit = (reason: string, count = 1) => {
      omissionReasons[reason] = (omissionReasons[reason] ?? 0) + count;
    };
    const boundedAttachments = input.attachments.slice(0, 20);
    if (
      input.endpoint.provider === "microsoft-teams" &&
      input.unavailableReferenceCount
    ) {
      // A channel/group reference is not a download capability. Still tell
      // the exact current-turn consumer that those bytes are unavailable,
      // including when there are no ingestible attachments at all.
      omit("download_unavailable", input.unavailableReferenceCount);
    }
    if (
      input.endpoint.provider === "github" &&
      input.attachmentLimitOmissions
    ) {
      omit("attachment_limit", input.attachmentLimitOmissions);
    }
    if (input.attachments.length > boundedAttachments.length) {
      omit(
        "attachment_limit",
        input.attachments.length - boundedAttachments.length,
      );
    }
    if (!options.storage) {
      if (boundedAttachments.length)
        omit("storage_unavailable", boundedAttachments.length);
      return { storedIds: [], omissionReasons };
    }
    const existingByFingerprint = new Map<string, string[]>();
    const existingAttachments = await db
      .select({
        id: issueAttachments.id,
        byteSize: assets.byteSize,
        contentType: assets.contentType,
        originalFilename: assets.originalFilename,
        sha256: assets.sha256,
      })
      .from(issueAttachments)
      .innerJoin(
        assets,
        and(
          eq(assets.companyId, issueAttachments.companyId),
          eq(assets.id, issueAttachments.assetId),
        ),
      )
      .where(
        and(
          eq(issueAttachments.companyId, input.endpoint.companyId),
          eq(issueAttachments.issueId, input.issueId),
          eq(issueAttachments.issueCommentId, input.issueCommentId),
        ),
      );
    for (const existing of existingAttachments) {
      const fingerprint = JSON.stringify([
        existing.sha256,
        existing.byteSize,
        existing.contentType,
        existing.originalFilename,
      ]);
      const ids = existingByFingerprint.get(fingerprint) ?? [];
      ids.push(existing.id);
      existingByFingerprint.set(fingerprint, ids);
    }
    const storedIds: string[] = [];
    const withCurrentAttachmentAuthorization = async <T>(
      work: (tx: DbTransaction) => Promise<T>,
      enforceUnchangedSource = false,
      telegramMedia?: Attachment,
    ): Promise<T> => {
      for (let attempt = 0; ; attempt++) {
        try {
          return await db.transaction(async (tx) => {
            const action = await tx
              .select()
              .from(chatActions)
              .where(
                and(
                  eq(chatActions.companyId, input.endpoint.companyId),
                  eq(chatActions.endpointId, input.endpoint.id),
                  eq(chatActions.deliveryId, input.deliveryId),
                  eq(chatActions.kind, "inbound_wakeup"),
                ),
              )
              .limit(1)
              .then((rows) => rows[0]);
            if (
              !action ||
              !["preparing", "issued", "processing", "processed"].includes(
                action.status,
              ) ||
              action.payload.issueId !== input.issueId ||
              action.payload.commentId !== input.issueCommentId
            )
              throw forbidden(
                "The attachment's current chat admission is unavailable",
                { code: "chat_action_authorization_changed" },
              );
            const current = await authorizeInboundWakeup(tx, action);
            // Delivery settlement/replay can update these receipts without
            // taking the issue lock. Lock in delivery -> action order only
            // after policy authorization; NOWAIT breaks cross-worker lock
            // inversions and the outer loop retries the whole transaction.
            const lockedDelivery = await tx
              .select()
              .from(chatDeliveries)
              .where(
                and(
                  eq(chatDeliveries.companyId, input.endpoint.companyId),
                  eq(chatDeliveries.id, input.deliveryId),
                ),
              )
              .for("update", { noWait: true })
              .limit(1)
              .then((rows) => rows[0]);
            const lockedAction = await tx
              .select()
              .from(chatActions)
              .where(
                and(
                  eq(chatActions.companyId, input.endpoint.companyId),
                  eq(chatActions.id, action.id),
                ),
              )
              .for("update", { noWait: true })
              .limit(1)
              .then((rows) => rows[0]);
            const scopeKeys = [
              "version",
              "issueId",
              "commentId",
              "agentId",
              "sessionGeneration",
              "requestedByActorType",
              "requestedByActorId",
            ] as const;
            if (
              current.delivery.state !== "processing" ||
              !lockedDelivery ||
              !lockedAction ||
              lockedDelivery.state !== "processing" ||
              lockedDelivery.endpointId !== action.endpointId ||
              lockedDelivery.conversationId !== action.conversationId ||
              lockedDelivery.principalId !== action.principalId ||
              lockedDelivery.attempts !== current.delivery.attempts ||
              JSON.stringify(lifecycleRuntimeFence(lockedDelivery)) !==
                JSON.stringify(lifecycleRuntimeFence(current.delivery)) ||
              lockedAction.endpointId !== action.endpointId ||
              lockedAction.deliveryId !== action.deliveryId ||
              lockedAction.conversationId !== action.conversationId ||
              lockedAction.principalId !== action.principalId ||
              lockedAction.kind !== "inbound_wakeup" ||
              !["preparing", "issued", "processing", "processed"].includes(
                lockedAction.status,
              ) ||
              scopeKeys.some(
                (key) => lockedAction.payload[key] !== action.payload[key],
              )
            )
              throw forbidden(
                "The attachment's current chat admission is unavailable",
                { code: "chat_action_authorization_changed" },
              );
            if (enforceUnchangedSource) {
              if (telegramMedia) {
                const normalized = lockedDelivery.normalizedEvent as {
                  principal?: { externalId?: string };
                  message?: {
                    providerMessageId?: string;
                    attachments?: Array<{ recovery?: unknown }>;
                  };
                };
                const fence = lifecycleRuntimeFence(lockedDelivery);
                const descriptor =
                  input.endpointRuntime.attachmentRecoveryDescriptor(
                    telegramMedia,
                    {
                      threadId: current.conversation.externalThreadId,
                      messageId: normalized.message?.providerMessageId ?? "",
                      principalExternalId: normalized.principal?.externalId,
                      runtimeGeneration: fence?.generation,
                      credentialFingerprint: fence?.credentialFingerprint,
                    },
                  );
                if (
                  descriptor?.locator.kind !== "telegram_media" ||
                  !normalized.message?.attachments?.some((item) => {
                    const retained = item.recovery as {
                      version?: unknown;
                      provider?: unknown;
                      locator?: Record<string, unknown>;
                      attachment?: Record<string, unknown>;
                    } | null;
                    return (
                      retained?.version === 1 &&
                      retained.provider === "telegram" &&
                      Object.entries(descriptor.locator).every(
                        ([key, value]) => retained.locator?.[key] === value,
                      ) &&
                      Object.entries(descriptor.attachment).every(
                        ([key, value]) => retained.attachment?.[key] === value,
                      )
                    );
                  })
                )
                  throw forbidden(
                    "The media's admitted source is unavailable",
                    { code: "chat_action_authorization_changed" },
                  );
              }
              const [source] = await tx
                .select({ id: issueComments.id })
                .from(issueComments)
                .where(
                  and(
                    eq(issueComments.companyId, input.endpoint.companyId),
                    eq(issueComments.issueId, input.issueId),
                    eq(issueComments.id, input.issueCommentId),
                    isNull(issueComments.deletedAt),
                    sql`${issueComments.updatedAt} = ${issueComments.createdAt}`,
                  ),
                )
                .for("share", { noWait: true });
              // Lifecycle admission precedes its conversation drain. Pending
              // source changes already invalidate this image download, even
              // when the append-only original comment is still untouched.
              const [lifecycle] = await tx
                .select({ id: chatDeliveries.id })
                .from(chatDeliveries)
                .where(
                  and(
                    eq(chatDeliveries.companyId, input.endpoint.companyId),
                    eq(chatDeliveries.endpointId, input.endpoint.id),
                    or(
                      isNull(chatDeliveries.conversationId),
                      eq(
                        chatDeliveries.conversationId,
                        current.conversation.id,
                      ),
                    ),
                    ne(chatDeliveries.state, "filtered"),
                    inArray(chatDeliveries.eventKind, [
                      "message_updated",
                      "message_deleted",
                      "message_restored",
                    ]),
                    sql`${chatDeliveries.normalizedEvent}->'runtimeContext' = ${JSON.stringify(lifecycleRuntimeFence(lockedDelivery))}::jsonb`,
                    sql`${chatDeliveries.normalizedEvent}->'message'->>'targetProviderEventId' = ${lockedDelivery.providerEventId}`,
                  ),
                )
                .limit(1);
              if (!source || lifecycle)
                throw forbidden(
                  "The image's admitted source changed before attachment registration",
                  {
                    code: "chat_action_authorization_changed",
                  },
                );
            }
            return await work(tx);
          });
        } catch (error) {
          if (!isExternalChatWaitAuthorizationContention(error) || attempt >= 4)
            throw error;
          // Retry the complete short transaction; no network/storage work or
          // backoff occurs while governance rows are locked.
          await new Promise((resolve) =>
            setTimeout(resolve, 20 * (attempt + 1)),
          );
        }
      }
    };
    // One shared deadline bounds the sequential batch; an expired batch never
    // starts another GitHub request. Other providers retain their own policy.
    const githubBatchSignal =
      input.endpoint.provider === "github"
        ? AbortSignal.timeout(GITHUB_ATTACHMENT_BATCH_TIMEOUT_MS)
        : undefined;
    // This new image-only lane shares one budget across token acquisition and
    // downloads. DB/storage commit semantics remain explicit and unchanged.
    const teamsInlineBatchSignal =
      input.endpoint.provider === "microsoft-teams"
        ? AbortSignal.timeout(10_000)
        : undefined;
    for (let attachment of boundedAttachments) {
      const teamsInlineImage =
        input.endpoint.provider === "microsoft-teams" &&
        input.endpointRuntime.attachmentRecoveryDescriptor(attachment)?.locator
          .kind === "teams_inline_image";
      const telegramMedia =
        input.endpoint.provider === "telegram" &&
        hasTelegramMediaProvenance(attachment);
      const sourceBoundMedia = teamsInlineImage || telegramMedia;
      const requireCurrentAttachmentAuthorization =
        input.endpoint.provider === "github" || sourceBoundMedia;
      try {
        if (teamsInlineImage && teamsInlineBatchSignal?.aborted) {
          omit("download_unavailable");
          continue;
        }
        // GitHub's anonymized upload URLs carry no trustworthy MIME metadata.
        // Resolve public bytes only here, after durable comment admission, and
        // then apply the same storage/type policy as every native attachment.
        if (input.endpoint.provider === "github") {
          await withCurrentAttachmentAuthorization(async () => {});
          attachment = await prepareGitHubPublicAttachment(
            attachment,
            githubBatchSignal,
            async (request, signal) => {
              await withCurrentAttachmentAuthorization(async () => {});
              return (
                (await input.endpointRuntime.resolveGitHubAttachmentComment?.(
                  request,
                  signal,
                )) ?? null
              );
            },
          );
        }
        if (
          requireCurrentAttachmentAuthorization &&
          input.endpoint.provider !== "github"
        )
          await withCurrentAttachmentAuthorization(
            async () => {},
            sourceBoundMedia,
            telegramMedia ? attachment : undefined,
          );
        if (
          attachment.size !== undefined &&
          attachment.size > MAX_ATTACHMENT_BYTES
        ) {
          omit("declared_too_large");
          continue;
        }
        if (!attachment.fetchData) {
          omit("download_unavailable");
          continue;
        }
        const originalFilename = sanitizeFilename(attachment.name);
        let contentType = normalizeUploadAttachmentContentType({
          contentType: normalizeContentType(
            attachment.mimeType ?? "application/octet-stream",
          ),
          originalFilename,
          isAllowedContentType,
        });
        // Reject a provider-declared type before allocating the downloaded
        // payload. The actual byte length is checked again after the adapter's
        // bounded fetch contract resolves.
        // A filename may infer an Office MIME for ordinary documents, but it
        // must not bypass byte identification for native media without MIME.
        const identifyTelegram =
          telegramMedia &&
          telegramMediaNeedsIdentification(attachment) &&
          normalizeContentType(
            attachment.mimeType ?? "application/octet-stream",
          ) === "application/octet-stream";
        if (!isAllowedContentType(contentType) && !identifyTelegram) {
          omit("unsupported_type");
          continue;
        }
        const fetched = teamsInlineImage
          ? await input.endpointRuntime.fetchTeamsInlineImage(
              attachment,
              teamsInlineBatchSignal!,
            )
          : await attachment.fetchData();
        const body = Buffer.isBuffer(fetched) ? fetched : Buffer.from(fetched);
        if (body.length === 0) {
          omit("empty_download");
          continue;
        }
        if (body.length > MAX_ATTACHMENT_BYTES) {
          omit("downloaded_too_large");
          continue;
        }
        if (identifyTelegram) {
          contentType =
            identifyTelegramMedia(attachment, body) ??
            "application/octet-stream";
          if (!isAllowedContentType(contentType)) {
            omit("unsupported_type");
            continue;
          }
        }
        const fingerprint = JSON.stringify([
          createHash("sha256").update(body).digest("hex"),
          body.length,
          contentType,
          originalFilename,
        ]);
        const existingIds = existingByFingerprint.get(fingerprint);
        const existingId = existingIds?.shift();
        if (requireCurrentAttachmentAuthorization) {
          // Revoke during either API resolution or the anonymous byte download
          // must prevent storage and attachment registration for that input.
          await withCurrentAttachmentAuthorization(
            async () => {},
            sourceBoundMedia,
            telegramMedia ? attachment : undefined,
          );
        }
        if (existingId) {
          storedIds.push(existingId);
          continue;
        }
        const stored = await options.storage.putFile({
          companyId: input.endpoint.companyId,
          namespace: `issues/${input.issueId}`,
          originalFilename,
          contentType,
          body,
        });
        const registration = {
          issueId: input.issueId,
          issueCommentId: input.issueCommentId,
          provider: stored.provider,
          objectKey: stored.objectKey,
          contentType: stored.contentType,
          byteSize: stored.byteSize,
          sha256: stored.sha256,
          originalFilename: stored.originalFilename,
          createdByUserId: input.actorUserId,
        };
        let row;
        try {
          row = requireCurrentAttachmentAuthorization
            ? await withCurrentAttachmentAuthorization(
                (tx) =>
                  issueService(tx as unknown as Db).createAttachment(
                    registration,
                  ),
                sourceBoundMedia,
                telegramMedia ? attachment : undefined,
              )
            : await issuesSvc.createAttachment(registration);
        } catch (error) {
          // An explicit authorization denial happens before registration. Do
          // not delete on ambiguous database errors which may have committed.
          if (
            requireCurrentAttachmentAuthorization &&
            isExternalActionAuthorizationChange(error)
          )
            await options.storage
              .deleteObject(input.endpoint.companyId, stored.objectKey)
              .catch(() => undefined);
          throw error;
        }
        storedIds.push(row.id);
      } catch (error) {
        if (isExternalActionAuthorizationChange(error)) throw error;
        // Use the closed current-input omission vocabulary consumed by native
        // prompts; provider-specific diagnostics remain redacted log codes.
        omit(
          error instanceof GitHubAttachmentUnavailableError
            ? "download_unavailable"
            : "processing_failed",
        );
        // A malformed or unavailable provider attachment must not strand the
        // durable text delivery. The rejected file is intentionally omitted;
        // the delivery remains auditable through its normalized attachment
        // metadata without persisting provider credentials or download URLs.
        logger.warn(
          {
            endpointId: input.endpoint.id,
            issueId: input.issueId,
            ...(error instanceof GitHubAttachmentUnavailableError
              ? {
                  deliveryId: input.deliveryId,
                  attachmentDiagnosticCode: error.code,
                }
              : {}),
            attachmentName: sanitizeFilename(attachment.name),
            error: redactError(error),
          },
          "external chat attachment was rejected",
        );
      }
    }
    return { storedIds, omissionReasons };
  }

  function attachmentOmissionDetail(result: {
    omissionReasons: Record<string, number>;
  }): string | null {
    const entries = Object.entries(result.omissionReasons).filter(
      ([, count]) => count > 0,
    );
    const omitted = entries.reduce((total, [, count]) => total + count, 0);
    if (!omitted) return null;
    const reasons = entries
      .map(([reason, count]) => `${reason.replaceAll("_", " ")}: ${count}`)
      .join(", ");
    return `${omitted} external attachment${omitted === 1 ? " was" : "s were"} omitted (${reasons})`;
  }

  async function settleTelegramAttachmentOnlyFailure(input: {
    activeDelivery: DeliveryRow;
    attachmentResult: {
      storedIds: string[];
      omissionReasons: Record<string, number>;
    };
    commentId: string;
    conversationId: string;
    endpoint: EndpointRow;
    message: Message;
    principalId: string | null;
    resourceId: string | null;
    runtimeContext?: InboundRuntimeContext;
    thread: Thread;
  }): Promise<boolean> {
    if (
      input.endpoint.provider !== "telegram" ||
      input.message.text.trim().length > 0 ||
      input.message.attachments.length === 0 ||
      input.attachmentResult.storedIds.length > 0
    ) {
      return false;
    }
    const diagnostic =
      attachmentOmissionDetail(input.attachmentResult) ??
      "The Telegram attachment could not be imported";
    const visibleFailure = `Paperclip could not safely import the attached Telegram file. Please resend it as a supported file under ${formatAttachmentSize(MAX_ATTACHMENT_BYTES)} or include text describing the request.`;
    const effectContext =
      input.runtimeContext ??
      runtimeContextForRecord(
        (await endpointRecord(input.endpoint.id)) ??
          (() => {
            throw new Error("Chat endpoint is unavailable");
          })(),
      );
    const effect = await db.transaction(async (tx) => {
      // Replace the optimistic attachment placeholder with an explicit safe
      // Paperclip-visible failure. The message link stays authoritative for
      // exact provider redelivery, while no agent wakeup is enqueued for an
      // empty turn that contains no usable bytes.
      await tx
        .update(issueComments)
        .set({ body: visibleFailure, updatedAt: new Date() })
        .where(
          and(
            eq(issueComments.id, input.commentId),
            eq(issueComments.companyId, input.endpoint.companyId),
          ),
        );
      await tx
        .update(chatActions)
        .set({
          status: "failed",
          result: { code: "inbound_wakeup_attachment_unavailable" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.deliveryId, input.activeDelivery.id),
            eq(chatActions.kind, "inbound_wakeup"),
            eq(chatActions.status, "preparing"),
          ),
        );
      const staged = await stageProviderEffect(tx, {
        endpoint: input.endpoint,
        deliveryId: input.activeDelivery.id,
        conversationId: input.conversationId,
        principalId: input.principalId,
        providerActionId: `provider_effect:attachment-ingest-failure:${input.activeDelivery.id}`,
        payload: {
          version: 1,
          authorizationMode: "safe_notice",
          effect: "thread_message",
          threadId: input.thread.id,
          text: visibleFailure,
          settleDelivery: false,
          ...(input.resourceId ? { resourceId: input.resourceId } : {}),
        },
        runtimeContext: effectContext,
      });
      await tx
        .update(chatDeliveries)
        .set({
          conversationId: input.conversationId,
          state: "processed",
          processedAt: new Date(),
          nextAttemptAt: null,
          redactedError: diagnostic,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, input.activeDelivery.id),
            eq(chatDeliveries.state, "processing"),
          ),
        );
      return staged;
    });
    if (!effect) throw new Error("Attachment failure notice was not persisted");
    // Posting the safe notice is its own durable outbox operation. A provider
    // outage must not turn the already-settled, deliberately unwoken inbound
    // delivery back into a replayable attachment message.
    scheduleProviderEffect(effect.id, input.thread);
    return true;
  }

  async function admitDiscordRootMention(
    configuredEndpoint: EndpointRow,
    event: DiscordRootMentionAdmissionEvent,
    context: RuntimeContext,
  ): Promise<boolean> {
    if (
      !(await ensureDiscordGatewayRuntimeIsCurrent(
        configuredEndpoint.id,
        context,
      ))
    ) {
      return false;
    }
    return withCredentialMutationLease(
      configuredEndpoint,
      async (credentialLease) => {
        const threadId = `discord:${event.guildId}:${event.channelId}:${event.messageId}`;
        const providerEventId = `${threadId}:${event.messageId}`;
        const allowed = await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const endpoint = await runtimeCallbackEndpoint(
            tx,
            configuredEndpoint.id,
            context,
            ["verifying", "active"],
          );
          const existing = await tx
            .select({ state: chatDeliveries.state })
            .from(chatDeliveries)
            .where(
              and(
                eq(chatDeliveries.endpointId, configuredEndpoint.id),
                eq(chatDeliveries.providerEventId, providerEventId),
              ),
            )
            .then((rows) => rows[0] ?? null);
          if (
            existing &&
            ["processed", "filtered", "failed"].includes(existing.state)
          )
            return false;

          let reason: string | null = null;
          if (!endpoint || endpoint.providerAccountId !== event.guildId) {
            reason = "Connection is not active";
          }
          const resource = endpoint
            ? await tx
                .select()
                .from(chatEndpointResources)
                .where(
                  and(
                    eq(chatEndpointResources.endpointId, endpoint.id),
                    eq(chatEndpointResources.type, "channel"),
                    eq(
                      chatEndpointResources.providerResourceId,
                      event.channelId,
                    ),
                  ),
                )
                .for("update")
                .then((rows) => rows[0] ?? null)
            : null;
          const enabledCount =
            endpoint?.status === "verifying"
              ? await tx
                  .select({ count: sql<number>`count(*)::int` })
                  .from(chatEndpointResources)
                  .where(
                    and(
                      eq(chatEndpointResources.endpointId, endpoint.id),
                      eq(chatEndpointResources.type, "channel"),
                      eq(chatEndpointResources.enabled, true),
                      eq(chatEndpointResources.availability, "available"),
                    ),
                  )
                  .then((rows) => rows[0]?.count ?? 0)
              : 0;
          const setupDestination =
            endpoint?.status === "verifying" &&
            enabledCount === 0 &&
            resource?.availability === "available";
          if (
            !reason &&
            !(
              endpoint?.allowGroupChats &&
              resource?.availability === "available" &&
              (resource.enabled || setupDestination)
            )
          ) {
            reason = "Destination is not enabled in Paperclip";
          }

          if (!reason && endpoint) {
            const principal = await tx
              .select({ id: chatExternalPrincipals.id })
              .from(chatExternalPrincipals)
              .where(
                and(
                  eq(chatExternalPrincipals.companyId, endpoint.companyId),
                  eq(chatExternalPrincipals.provider, "discord"),
                  eq(chatExternalPrincipals.providerAccountId, event.guildId),
                  eq(chatExternalPrincipals.externalId, event.userId),
                ),
              )
              .then((rows) => rows[0] ?? null);
            let allowed: boolean;
            let linkedDenied = false;
            if (principal) {
              const authorization = await lockCurrentPrincipalAuthorization(
                tx,
                endpoint,
                principal.id,
              );
              allowed = authorization.allowed;
              linkedDenied = authorization.linkedDenied;
            } else if (!endpoint.allowUnlinkedPeople) {
              allowed = false;
            } else if (!endpoint.sponsorUserId) {
              allowed = true;
            } else {
              const sponsor = await tx
                .select({
                  status: companyMemberships.status,
                  membershipRole: companyMemberships.membershipRole,
                })
                .from(companyMemberships)
                .where(
                  and(
                    eq(companyMemberships.companyId, endpoint.companyId),
                    eq(companyMemberships.principalType, "user"),
                    eq(companyMemberships.principalId, endpoint.sponsorUserId),
                  ),
                )
                .for("update")
                .then((rows) => rows[0] ?? null);
              allowed =
                sponsor?.status === "active" &&
                sponsor.membershipRole !== "viewer";
            }
            if (!allowed) {
              reason = linkedDenied
                ? "Linked Paperclip account is not currently permitted"
                : endpoint.allowUnlinkedPeople
                  ? "Endpoint sponsor can no longer authorize external guests"
                  : "External identity must be linked to a Paperclip account";
            }
          }
          if (!reason) {
            await credentialLease.assertOwned(tx);
            return true;
          }

          const filteredAt = new Date();
          const normalizedEvent = {
            providerEventId,
            kind: "mention",
            trigger: "mention",
            resource: {
              type: "channel",
              providerResourceId: event.channelId,
            },
            conversation: { externalThreadId: threadId },
            message: { providerMessageId: event.messageId },
            filtering: { contentRetained: false, providerThreadCreated: false },
          };
          await tx
            .insert(chatDeliveries)
            .values({
              companyId: configuredEndpoint.companyId,
              endpointId: configuredEndpoint.id,
              providerEventId,
              deduplicationKey: createHash("sha256")
                .update(providerEventId)
                .digest("hex"),
              eventKind: "mention",
              normalizedEvent,
              state: "filtered",
              redactedError: reason,
              processedAt: filteredAt,
            })
            .onConflictDoUpdate({
              target: [
                chatDeliveries.endpointId,
                chatDeliveries.providerEventId,
              ],
              set: {
                normalizedEvent,
                principalId: null,
                state: "filtered",
                nextAttemptAt: null,
                redactedError: reason,
                processedAt: filteredAt,
                updatedAt: filteredAt,
              },
            });
          await tx
            .update(chatEndpoints)
            .set({ lastEventAt: filteredAt, updatedAt: filteredAt })
            .where(eq(chatEndpoints.id, configuredEndpoint.id));
          await credentialLease.assertOwned(tx);
          return false;
        });
        if (!allowed || !event.message || !context.endpointRuntime) {
          return false;
        }
        const thread = context.endpointRuntime.thread(event.threadId);
        await processMessage(
          configuredEndpoint,
          thread,
          event.message,
          "mention",
          true,
          null,
          context,
          undefined,
          null,
          true,
          undefined,
          true,
        );
        const staged = await db
          .select({ state: chatDeliveries.state })
          .from(chatDeliveries)
          .where(
            and(
              eq(chatDeliveries.endpointId, configuredEndpoint.id),
              eq(chatDeliveries.providerEventId, providerEventId),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (
          !staged ||
          !["received", "retry", "processing"].includes(staged.state)
        ) {
          return false;
        }

        await options.discordRootThreadTransportBarrier?.();
        await credentialLease.assertOwned();
        if (
          !(await ensureDiscordGatewayRuntimeIsCurrent(
            configuredEndpoint.id,
            context,
          ))
        ) {
          return false;
        }
        try {
          await context.endpointRuntime.ensureDiscordRootThread({
            channelId: event.channelId,
            content: event.message.text,
            messageId: event.messageId,
          });
        } catch (error) {
          // The durable provisional receipt owns recovery. Do not let a
          // transient REST failure escape the Gateway event handler or ask the
          // adapter to create the same thread outside Paperclip's lifecycle
          // fence.
          logger.warn(
            {
              endpointId: configuredEndpoint.id,
              error: redactError(error),
              providerEventId,
            },
            "Discord root thread creation will be retried from the durable receipt",
          );
          return false;
        }
        const promoted = await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const current = await runtimeCallbackEndpoint(
            tx,
            configuredEndpoint.id,
            context,
            ["verifying", "active"],
          );
          if (!current) return false;
          const [row] = await tx
            .update(chatDeliveries)
            .set({
              state: "received",
              normalizedEvent: sql`${chatDeliveries.normalizedEvent} - 'providerThreadPending'`,
              nextAttemptAt: null,
              redactedError: null,
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatDeliveries.endpointId, configuredEndpoint.id),
                eq(chatDeliveries.providerEventId, providerEventId),
                eq(chatDeliveries.state, "retry"),
                sql`${chatDeliveries.normalizedEvent}->>'providerThreadPending' = 'true'`,
              ),
            )
            .returning({ id: chatDeliveries.id });
          await credentialLease.assertOwned(tx);
          return Boolean(row);
        });
        if (promoted)
          scheduleConversationDrain(configuredEndpoint.id, threadId);
        // Paperclip created the provider thread inside its credential/reach
        // lease. Returning false prevents the adapter from creating it again;
        // the durable drain owns the remaining task mutation.
        return false;
      },
    );
  }

  async function stageInboundWakeup(
    tx: DbOrTransaction,
    input: {
      endpoint: EndpointRow;
      deliveryId: string;
      conversation: typeof chatConversations.$inferSelect;
      commentId: string;
      principalId: string;
      actorUserId: string | null;
    },
  ) {
    await tx
      .insert(chatActions)
      .values({
        companyId: input.endpoint.companyId,
        endpointId: input.endpoint.id,
        deliveryId: input.deliveryId,
        conversationId: input.conversation.id,
        principalId: input.principalId,
        kind: "inbound_wakeup",
        providerActionId: `inbound_wakeup:${input.deliveryId}`,
        status: "preparing",
        payload: {
          version: 1,
          issueId: input.conversation.issueId,
          agentId: input.endpoint.assignedAgentId,
          commentId: input.commentId,
          sessionGeneration: input.conversation.sessionGeneration,
          requestedByActorType: input.actorUserId ? "user" : "system",
          requestedByActorId: input.actorUserId ?? input.principalId,
        },
      })
      .onConflictDoNothing();
  }

  async function authorizeInboundWakeup(
    tx: DbOrTransaction,
    action: typeof chatActions.$inferSelect,
    notice?: { nonblocking: true; terminal: boolean },
  ) {
    const payload = action.payload;
    const deny = () =>
      forbidden(
        "This accepted chat message is no longer authorized to start work",
        { code: "chat_action_authorization_changed" },
      );
    if (
      payload.version !== 1 ||
      typeof payload.issueId !== "string" ||
      typeof payload.agentId !== "string" ||
      typeof payload.commentId !== "string" ||
      !action.conversationId ||
      !action.principalId ||
      !action.deliveryId ||
      !["user", "system"].includes(String(payload.requestedByActorType)) ||
      typeof payload.requestedByActorId !== "string"
    )
      throw deny();
    const issue = await tx
      .select()
      .from(issues)
      .where(
        and(
          eq(issues.companyId, action.companyId),
          eq(issues.id, payload.issueId),
        ),
      )
      .for("update", notice ? { noWait: true } : undefined)
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (
      !issue ||
      issue.assigneeAgentId !== payload.agentId ||
      (!notice?.terminal &&
        ["backlog", "done", "cancelled"].includes(issue.status))
    )
      throw deny();
    // The scheduler already owns the issue lock. Do not wait in the opposite
    // order behind an ingress transaction which owns the endpoint first.
    const endpoint = await tx
      .select()
      .from(chatEndpoints)
      .where(
        and(
          eq(chatEndpoints.companyId, action.companyId),
          eq(chatEndpoints.id, action.endpointId),
        ),
      )
      .for("no key update", { noWait: true })
      .limit(1)
      .then((rows) => rows[0] ?? null);
    const delivery = await tx
      .select()
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.companyId, action.companyId),
          eq(chatDeliveries.id, action.deliveryId),
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    const fence = delivery ? lifecycleRuntimeFence(delivery) : null;
    if (
      !endpoint ||
      endpoint.assignedAgentId !== payload.agentId ||
      !delivery ||
      telegramDeliveryHasZeroMessageId(delivery, endpoint.provider) ||
      delivery.endpointId !== endpoint.id ||
      delivery.conversationId !== action.conversationId ||
      delivery.principalId !== action.principalId ||
      !fence ||
      !(await runtimeCallbackEndpoint(tx as DbTransaction, endpoint.id, fence, [
        "verifying",
        "active",
      ]))
    )
      throw deny();
    const conversation = await tx
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, action.companyId),
          eq(chatConversations.id, action.conversationId),
        ),
      )
      .for("update")
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (
      !conversation ||
      conversation.endpointId !== endpoint.id ||
      conversation.issueId !== issue.id ||
      conversation.sessionGeneration !== payload.sessionGeneration ||
      !["active", "waiting"].includes(conversation.state)
    )
      throw deny();
    const resource = conversation.resourceId
      ? await tx
          .select()
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.endpointId, endpoint.id),
              eq(chatEndpointResources.id, conversation.resourceId),
            ),
          )
          .for("update")
          .limit(1)
          .then((rows) => rows[0] ?? null)
      : null;
    const authorization = await lockCurrentPrincipalAuthorization(
      tx,
      endpoint,
      action.principalId,
    );
    const expectedUserId =
      payload.requestedByActorType === "user"
        ? payload.requestedByActorId
        : null;
    if (
      !(conversation.isDirectMessage
        ? endpoint.allowDirectMessages
        : nonDirectDestinationAllowed(endpoint, resource)) ||
      !authorization.allowed ||
      authorization.userId !== expectedUserId ||
      (payload.requestedByActorType === "system" &&
        payload.requestedByActorId !== action.principalId)
    )
      throw deny();
    const source = await tx
      .select({
        authorUserId: issueComments.authorUserId,
        deletedAt: issueComments.deletedAt,
      })
      .from(chatMessageLinks)
      .innerJoin(
        issueComments,
        and(
          eq(issueComments.id, chatMessageLinks.commentId),
          eq(issueComments.companyId, action.companyId),
          eq(issueComments.issueId, issue.id),
        ),
      )
      .where(
        and(
          eq(chatMessageLinks.companyId, action.companyId),
          eq(chatMessageLinks.endpointId, endpoint.id),
          eq(chatMessageLinks.conversationId, conversation.id),
          eq(chatMessageLinks.deliveryId, delivery.id),
          eq(chatMessageLinks.commentId, payload.commentId),
          eq(chatMessageLinks.direction, "inbound"),
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (
      !source ||
      (source.deletedAt && !notice?.terminal) ||
      source.authorUserId !== expectedUserId
    )
      throw deny();
    return { issue, delivery, endpoint, conversation };
  }

  function inboundWakeScope(action: typeof chatActions.$inferSelect) {
    return JSON.stringify([
      action.companyId,
      action.endpointId,
      action.conversationId,
      action.deliveryId,
      action.principalId,
      action.kind,
      ...[
        "version",
        "issueId",
        "agentId",
        "commentId",
        "sessionGeneration",
        "requestedByActorType",
        "requestedByActorId",
      ].map((key) => action.payload[key]),
    ]);
  }

  const failedChatRetryDenied = () =>
    conflict(
      "The exact failed chat request can no longer be retried safely. Check its current connection, access, and recovery state.",
      { code: "chat_failed_run_retry_not_authorized" },
    );
  class FailedChatRetryPublicationReadError extends Error {
    constructor() {
      super("Chat retry publication authorization is temporarily unavailable");
    }
  }

  function retryCommentIds(context: Record<string, unknown>): string[] {
    const ids =
      context.wakeCommentIds ??
      (context.wakeCommentId ? [context.wakeCommentId] : []);
    if (
      !Array.isArray(ids) ||
      ids.length === 0 ||
      ids.length > 50 ||
      ids.some((id) => typeof id !== "string" || !isUuidLike(id)) ||
      new Set(ids).size !== ids.length ||
      (context.wakeCommentId !== undefined &&
        context.wakeCommentId !== ids.at(-1))
    )
      throw failedChatRetryDenied();
    return ids as string[];
  }

  type FailedChatRetrySource = {
    failedRunId: string;
    sourceWakeupRequestId: string;
    issueId: string;
    agentId: string;
    taskKey: string;
    provider: ChatProvider;
    commentIds: string[];
    sources: Array<Record<string, unknown>>;
    endpointId: string;
    conversationId: string;
    principalId: string;
    sessionGeneration: number;
    requestedByActorType: "user" | "system";
    requestedByActorId: string;
    retryAncestors: Array<{
      actionId: string;
      failedRunId: string;
      sourceScopeSha256: string;
    }>;
    sourceScopeSha256: string;
  };
  function hashFailedRetrySource(
    scope: Omit<FailedChatRetrySource, "sourceScopeSha256">,
  ): FailedChatRetrySource {
    return {
      ...scope,
      sourceScopeSha256: createHash("sha256")
        .update(JSON.stringify(scope))
        .digest("hex"),
    };
  }

  function assertFailedRetryReceipt(
    ...args: Parameters<typeof assertDurableChatWakeupReceipt>
  ) {
    try {
      assertDurableChatWakeupReceipt(...args);
    } catch {
      throw failedChatRetryDenied();
    }
  }

  /** The reviewed-chat ownership check runs before runtime/profile resolution
   * or provider startup. Recognize only that exact persisted failure together
   * with its sole system diagnostic and absence of execution evidence. A
   * generic setup error (or a prior-session display hint) is not this proof. */
  async function isPreProviderReviewedChatFailure(
    tx: DbOrTransaction,
    run: typeof heartbeatRuns.$inferSelect,
  ): Promise<boolean> {
    const diagnostic = "reviewed_chat_execution_binding_not_authorized";
    if (
      run.runtimeMode !== "legacy" ||
      run.errorCode !== "setup_failed" ||
      run.error !== diagnostic ||
      [
        run.runtimeModeResolverVersion,
        run.runtimeModeReason,
        run.runtimeModeResolvedAt,
        run.runnerProfileJson,
        run.runnerInstanceId,
        run.nativeSessionId,
        run.nativeIssueId,
        run.nativePhase,
        run.driverKind,
        run.driverVersion,
        run.completionContractId,
        run.completionContractSha256,
        run.sessionIdAfter,
        run.externalRunId,
        run.processPid,
        run.processGroupId,
        run.processStartedAt,
        run.logStore,
        run.logRef,
        run.logBytes,
        run.logSha256,
        run.stdoutExcerpt,
        run.stderrExcerpt,
        run.lastOutputAt,
        run.lastOutputStream,
        run.lastOutputBytes,
        run.usageJson,
        run.exitCode,
        run.signal,
      ].some((value) => value !== null) ||
      run.lastOutputSeq !== 0 ||
      run.logCompressed
    )
      return false;
    const events = await tx
      .select()
      .from(heartbeatRunEvents)
      .where(
        and(
          eq(heartbeatRunEvents.companyId, run.companyId),
          eq(heartbeatRunEvents.runId, run.id),
        ),
      )
      .limit(2)
      .for("share", { noWait: true });
    const event = events[0];
    if (
      events.length !== 1 ||
      !event ||
      event.agentId !== run.agentId ||
      event.seq !== 1 ||
      event.eventType !== "error" ||
      event.stream !== "system" ||
      event.level !== "error" ||
      event.message !== diagnostic ||
      event.payload !== null ||
      event.sourceInstanceId !== null ||
      event.sourceEventId !== null ||
      event.sourceSeq !== null ||
      event.sourcePayloadSha256 !== null ||
      event.protocolSchemaVersion !== null
    )
      return false;
    const evidence = await tx.execute(sql`select 1 where
      exists (select 1 from native_run_finalizations where company_id = ${run.companyId}::uuid and run_id = ${run.id}::uuid)
      or exists (select 1 from native_run_results where company_id = ${run.companyId}::uuid and run_id = ${run.id}::uuid)
      or exists (select 1 from environment_leases where company_id = ${run.companyId}::uuid and heartbeat_run_id = ${run.id}::uuid)`);
    return evidence.length === 0;
  }

  async function failedNativeRetryCoordinator(
    tx: DbOrTransaction,
    run: typeof heartbeatRuns.$inferSelect,
    issueId: string,
  ) {
    const [coordinator] = await tx
      .select()
      .from(nativeRunFinalizations)
      .where(
        and(
          eq(nativeRunFinalizations.runId, run.id),
          eq(nativeRunFinalizations.companyId, run.companyId),
          eq(nativeRunFinalizations.issueId, issueId),
        ),
      )
      .for("share", { noWait: true });
    // A queued request can fail before its first provider event because the
    // predecessor's exact retained checkpoint has not yet been suspended.
    // A later authenticated cleanup receipt can authorize retrying that
    // request; never pretend it exhausted provider execution attempts.
    if (
      coordinator &&
      run.nativeIssueId === issueId &&
      run.status === "failed" &&
      run.errorCode === "adapter_failed" &&
      run.error === "runner_state_identity_mismatch" &&
      run.nativePhase === "observed" &&
      coordinator.phase === "observed" &&
      coordinator.attempt === 0 &&
      !coordinator.leaseOwner &&
      !coordinator.leaseExpiresAt &&
      !coordinator.nextAttemptAt &&
      !coordinator.resultId &&
      !coordinator.assessmentId &&
      !coordinator.decisionId &&
      run.nativeSessionId &&
      run.processPid &&
      run.processGroupId === run.processPid
    ) {
      const [event] = await tx
        .select({ id: heartbeatRunEvents.id })
        .from(heartbeatRunEvents)
        .where(
          and(
            eq(heartbeatRunEvents.companyId, run.companyId),
            eq(heartbeatRunEvents.runId, run.id),
            or(
              isNotNull(heartbeatRunEvents.sourceInstanceId),
              sql`${heartbeatRunEvents.payload}->'prpEvent' is not null`,
            ),
          ),
        )
        .limit(1);
      const [result] = await tx
        .select({ id: nativeRunResults.id })
        .from(nativeRunResults)
        .where(
          and(
            eq(nativeRunResults.companyId, run.companyId),
            eq(nativeRunResults.runId, run.id),
          ),
        )
        .limit(1);
      const checkpoint = run.runnerProfileJson?.sessionCheckpoint as
        Record<string, unknown> | undefined;
      const binding = checkpoint?.identity as
        Record<string, unknown> | undefined;
      if (
        !event &&
        !result &&
        binding?.companyId === run.companyId &&
        binding?.issueId === issueId &&
        binding?.agentId === run.agentId &&
        binding?.runId === run.id &&
        binding?.sessionId === run.nativeSessionId &&
        typeof checkpoint?.sessionId === "string" &&
        checkpoint.sessionId.trim().length > 0 &&
        (checkpoint.providerSessionId == null ||
          (typeof checkpoint.providerSessionId === "string" &&
            checkpoint.providerSessionId.trim().length > 0))
      ) {
        const predecessors = await tx
          .select()
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.companyId, run.companyId),
              eq(heartbeatRuns.agentId, run.agentId),
              eq(heartbeatRuns.nativeIssueId, issueId),
              eq(heartbeatRuns.nativeSessionId, run.nativeSessionId),
              eq(heartbeatRuns.processPid, run.processPid),
              eq(heartbeatRuns.processGroupId, run.processGroupId),
              eq(heartbeatRuns.runtimeMode, "native"),
              eq(heartbeatRuns.status, "succeeded"),
              ne(heartbeatRuns.id, run.id),
              // Warm runs can share a PID and session. Only a durable maintenance
              // owner is a candidate; the physical check below must still prove
              // that this exact run owns the canonical suspended checkpoint.
              sql`exists (select 1 from native_run_finalizations retired
            where retired.company_id = ${heartbeatRuns.companyId}
              and retired.run_id = ${heartbeatRuns.id}
              and retired.phase = 'committed'
              and exists (select 1 from jsonb_array_elements(retired.recovery_history) receipt
                where receipt->>'kind' = 'native_cleanup_maintenance'
                  and receipt->>'phase' = 'settled' and receipt->>'version' = '1'))`,
            ),
          )
          .for("share", { noWait: true })
          .limit(2);
        if (predecessors.length === 1) {
          const predecessor = predecessors[0]!;
          const [retired] = await tx
            .select()
            .from(nativeRunFinalizations)
            .where(
              and(
                eq(nativeRunFinalizations.companyId, run.companyId),
                eq(nativeRunFinalizations.issueId, issueId),
                eq(nativeRunFinalizations.runId, predecessor.id),
              ),
            )
            .for("share", { noWait: true });
          const receipt = retired?.recoveryHistory.findLast(
            (entry) => entry.kind === "native_cleanup_maintenance",
          );
          const leases = await tx
            .select()
            .from(environmentLeases)
            .where(
              and(
                eq(environmentLeases.companyId, run.companyId),
                eq(environmentLeases.heartbeatRunId, run.id),
              ),
            )
            .for("share", { noWait: true });
          if (
            retired?.phase === "committed" &&
            retired.resultId &&
            retired.assessmentId &&
            retired.decisionId &&
            !retired.leaseOwner &&
            !retired.leaseExpiresAt &&
            !retired.nextAttemptAt &&
            receipt?.version === 1 &&
            receipt.phase === "settled" &&
            typeof receipt.requestId === "string" &&
            receipt.requestId.length > 0 &&
            receipt.nativeSessionId === run.nativeSessionId &&
            receipt.runnerInstanceId === predecessor.runnerInstanceId &&
            // The cleanup receipt identifies the provider thread. The
            // checkpoint's providerSessionId is the separate backend account.
            receipt.providerSessionId === checkpoint.sessionId &&
            typeof receipt.settledFingerprint === "string" &&
            /^[a-f0-9]{64}$/.test(receipt.settledFingerprint) &&
            typeof receipt.sourceFingerprint === "string" &&
            /^[a-f0-9]{64}$/.test(receipt.sourceFingerprint) &&
            leases.every(
              (lease) =>
                lease.provider === "local" &&
                lease.providerLeaseId === null &&
                lease.issueId === issueId &&
                ["failed", "released", "expired"].includes(lease.status) &&
                (lease.cleanupStatus === null ||
                  lease.cleanupStatus === "success") &&
                lease.releasedAt !== null,
            )
          ) {
            return {
              coordinator,
              leases,
              retiredOwner: {
                predecessor,
                receipt,
                providerSessionId: checkpoint.sessionId,
                providerBackendSessionId: checkpoint.providerSessionId ?? null,
              },
            };
          }
        }
      }
    }
    const detail = coordinator?.failureDetail;
    const ordinary = [
      "provider_process_exited",
      "provider_stdout_closed",
      "provider_process_output_closed",
      "provider_process_status_failed",
      "provider_initialize_timeout",
      "provider_initialize_protocol_error",
      "provider_request_timeout",
      "provider_request_protocol_error",
      "provider_transport_failed",
      "native_runner_process_exited",
    ];
    if (
      !coordinator ||
      run.nativeIssueId !== issueId ||
      run.nativePhase !== "terminal_failure" ||
      coordinator.phase !== "terminal_failure" ||
      coordinator.recoveryState !== "blocked" ||
      coordinator.failureCode !== "native_session_retry_exhausted" ||
      coordinator.attempt < 3 ||
      coordinator.leaseOwner ||
      coordinator.leaseExpiresAt ||
      coordinator.nextAttemptAt ||
      coordinator.resultId ||
      coordinator.assessmentId ||
      coordinator.decisionId ||
      !detail ||
      !ordinary.includes(String(detail.originalFailureCode)) ||
      !["bootstrap_retry", "exact_checkpoint_resume"].includes(
        String(detail.recoveryMode),
      ) ||
      ![
        "adapter_failed",
        "native_session_retry_exhausted",
        String(detail.originalFailureCode),
      ].includes(run.errorCode ?? "") ||
      (detail.recoveryMode === "bootstrap_retry" &&
        (detail.providerSessionEstablished !== false ||
          detail.providerEventsExist !== false ||
          detail.checkpointExists !== false)) ||
      (detail.recoveryMode === "exact_checkpoint_resume" &&
        (detail.providerSessionEstablished !== true ||
          detail.checkpointExists !== true))
    )
      throw failedChatRetryDenied();
    const evidence = await nativeProviderRecoveryEvidence({
      db: tx as Db,
      runId: run.id,
      sourceFailureCode: detail.originalFailureCode as Parameters<
        typeof nativeProviderRecoveryEvidence
      >[0]["sourceFailureCode"],
    });
    if (
      evidence.recoveryMode !== detail.recoveryMode ||
      evidence.providerSessionEstablished !==
        detail.providerSessionEstablished ||
      evidence.providerEventsExist !== detail.providerEventsExist ||
      evidence.checkpointExists !== detail.checkpointExists
    )
      throw failedChatRetryDenied();
    const leases = await tx
      .select()
      .from(environmentLeases)
      .where(
        and(
          eq(environmentLeases.companyId, run.companyId),
          eq(environmentLeases.heartbeatRunId, run.id),
        ),
      )
      .for("share", { noWait: true });
    if (
      leases.some(
        (lease) =>
          !["released", "expired", "failed"].includes(lease.status) ||
          lease.cleanupStatus !== "success" ||
          !lease.releasedAt,
      )
    )
      throw failedChatRetryDenied();
    return { coordinator, leases, retiredOwner: null };
  }

  async function assertFailedNativeRetryState(
    tx: DbOrTransaction,
    source: Pick<FailedChatRetrySource, "failedRunId" | "issueId" | "agentId">,
    companyId: string,
  ) {
    const [run] = await tx
      .select()
      .from(heartbeatRuns)
      .where(
        and(
          eq(heartbeatRuns.id, source.failedRunId),
          eq(heartbeatRuns.companyId, companyId),
          eq(heartbeatRuns.agentId, source.agentId),
        ),
      )
      .for("share", { noWait: true });
    if (!run) throw failedChatRetryDenied();
    if (run.runtimeMode !== "native") return;
    const { coordinator, leases, retiredOwner } =
      await failedNativeRetryCoordinator(tx, run, source.issueId);
    if (retiredOwner) {
      if (
        !nativePreProviderRetryAfterCleanupStateIsSafe({
          failedExecution: run.runnerProfileJson?.nativeExecutionInput,
          retiredExecution:
            retiredOwner.predecessor.runnerProfileJson?.nativeExecutionInput,
          companyId,
          issueId: source.issueId,
          agentId: source.agentId,
          failedRunId: run.id,
          retiredRunId: retiredOwner.predecessor.id,
          nativeSessionId: run.nativeSessionId!,
          runnerInstanceId: retiredOwner.predecessor.runnerInstanceId!,
          providerSessionId: retiredOwner.providerSessionId,
          providerBackendSessionId: retiredOwner.providerBackendSessionId,
          processPid: run.processPid!,
          processGroupId: run.processGroupId!,
          receipt: retiredOwner.receipt,
        })
      )
        throw failedChatRetryDenied();
      return;
    }
    const checkpoint = run.runnerProfileJson?.sessionCheckpoint as
      Record<string, unknown> | undefined;
    if (
      !run.nativeSessionId ||
      !run.runnerInstanceId ||
      (checkpoint?.providerSessionId != null &&
        (typeof checkpoint.providerSessionId !== "string" ||
          checkpoint.providerSessionId.trim().length === 0)) ||
      !nativeFailedRunRetryStateIsSafe({
        execution: run.runnerProfileJson?.nativeExecutionInput,
        companyId,
        issueId: source.issueId,
        agentId: source.agentId,
        runId: run.id,
        nativeSessionId: run.nativeSessionId,
        runnerInstanceId: run.runnerInstanceId,
        processPid: run.processPid,
        processGroupId: run.processGroupId,
        providerSessionId:
          typeof checkpoint?.sessionId === "string"
            ? checkpoint.sessionId
            : null,
        providerBackendSessionId:
          typeof checkpoint?.providerSessionId === "string"
            ? checkpoint.providerSessionId
            : null,
        recoveryMode: coordinator.failureDetail!.recoveryMode as
          "bootstrap_retry" | "exact_checkpoint_resume",
        allowVerifiedBackup: leases.length > 0,
      })
    )
      throw failedChatRetryDenied();
  }

  /** Resolve only a complete, originally admitted direct-chat batch. A retry
   * never turns caller JSON, task-description text, or a provider redelivery
   * into new input authority. Answer continuations require their own proof. */
  async function failedChatRetrySource(
    tx: DbOrTransaction,
    input: {
      companyId: string;
      issueId: string;
      agentId: string;
      failedRunId: string;
      retryActionId?: string;
      runId?: string;
      publication?: boolean;
      /** Internal selector for already committed output, never retry admission. */
      committedResponse?: {
        resultId: string;
        canonicalSha256?: string;
        decisionId?: string;
        /** Internal source-proof continuation for one locked Teams transfer.
         * Never permission to repeat its card/PUT or retry a model run. */
        continuingTeamsFileTransfer?: {
          transferId: string;
          publicationId: string;
          version: number;
          phase: "consent_unknown" | "file_info_unknown";
        };
      };
    },
    visited = new Set<string>(),
  ): Promise<FailedChatRetrySource> {
    if (visited.has(input.failedRunId) || visited.size >= 16)
      throw failedChatRetryDenied();
    const ancestors = new Set([...visited, input.failedRunId]);
    const [issue] = await tx
      .select()
      .from(issues)
      .where(
        and(
          eq(issues.id, input.issueId),
          eq(issues.companyId, input.companyId),
        ),
      )
      .for(
        "update",
        input.publication || input.retryActionId ? { noWait: true } : undefined,
      );
    const [actor] = await tx
      .select({ status: agents.status })
      .from(agents)
      .where(
        and(
          eq(agents.id, input.agentId),
          eq(agents.companyId, input.companyId),
        ),
      )
      .for("share", { noWait: true });
    const [failedRun] = await tx
      .select()
      .from(heartbeatRuns)
      .where(
        and(
          eq(heartbeatRuns.id, input.failedRunId),
          eq(heartbeatRuns.companyId, input.companyId),
          eq(heartbeatRuns.agentId, input.agentId),
        ),
      )
      .for("share", { noWait: true });
    if (
      !issue ||
      issue.assigneeAgentId !== input.agentId ||
      !actor ||
      !isAgentStatusInvokable(actor.status) ||
      !failedRun ||
      !failedRun.wakeupRequestId ||
      (!input.committedResponse &&
        (!["failed", "timed_out"].includes(failedRun.status) ||
          !failedRun.finishedAt)) ||
      (!input.committedResponse &&
        failedRun.runtimeMode !== "native" &&
        !(
          [
            "adapter_failed",
            "adapter_exit_code",
            "process_exit",
            "timeout",
          ].includes(failedRun.errorCode ?? "") ||
          (await isPreProviderReviewedChatFailure(tx, failedRun))
        )) ||
      (!input.publication &&
        ["backlog", "done", "cancelled"].includes(issue.status))
    )
      throw failedChatRetryDenied();
    if (failedRun.runtimeMode === "native" && !input.committedResponse)
      await failedNativeRetryCoordinator(tx, failedRun, issue.id);
    const context = failedRun.contextSnapshot ?? {};
    const provider = CHAT_PROVIDERS.find(
      (value) => context.source === `chat:${value}`,
    );
    if (
      !provider ||
      context.issueId !== issue.id ||
      context.interactionId ||
      (context.taskKey !== issue.identifier && context.taskKey !== issue.id)
    )
      throw failedChatRetryDenied();
    const commentIds = retryCommentIds(context);
    const [accepted] = await tx
      .select()
      .from(nativeRunResults)
      .where(
        and(
          eq(nativeRunResults.companyId, input.companyId),
          eq(nativeRunResults.runId, failedRun.id),
          eq(nativeRunResults.schemaStatus, "accepted"),
          input.committedResponse
            ? eq(nativeRunResults.id, input.committedResponse.resultId)
            : undefined,
        ),
      )
      .limit(1)
      .for("share", { noWait: true });
    if (input.committedResponse) {
      const [coordinator] = await tx
        .select()
        .from(nativeRunFinalizations)
        .where(
          and(
            eq(nativeRunFinalizations.companyId, input.companyId),
            eq(nativeRunFinalizations.issueId, issue.id),
            eq(nativeRunFinalizations.runId, failedRun.id),
          ),
        )
        .for("share", { noWait: true });
      const result = accepted?.resultJson.result as
        Record<string, unknown> | undefined;
      const terminal = accepted?.resultJson.terminal as
        Record<string, unknown> | undefined;
      const continuation = result?.continuation as
        Record<string, unknown> | undefined;
      if (
        failedRun.runtimeMode !== "native" ||
        failedRun.nativeIssueId !== issue.id ||
        !accepted ||
        accepted.id !== input.committedResponse.resultId ||
        accepted.issueId !== issue.id ||
        accepted.completionContractId !== failedRun.completionContractId ||
        coordinator?.phase !== "committed" ||
        coordinator.resultId !== accepted.id ||
        !coordinator.decisionId ||
        !coordinator.assessmentId ||
        (input.committedResponse.canonicalSha256 !== undefined &&
          input.committedResponse.canonicalSha256 !==
            accepted.canonicalSha256) ||
        (input.committedResponse.decisionId !== undefined &&
          input.committedResponse.decisionId !== coordinator.decisionId) ||
        result?.schema !== "paperclip.run_result.v1" ||
        result.reportedWorkDisposition !== "yielded" ||
        !Array.isArray(result.attentionRequests) ||
        result.attentionRequests.length !== 0 ||
        continuation?.kind !== "response_wake" ||
        terminal?.schema !== "paperclip.prp.terminal.v1" ||
        terminal.turnTerminalState !== "completed" ||
        terminal.runTerminalState !== "succeeded" ||
        terminal.reportedWorkDisposition !== "yielded"
      )
        throw failedChatRetryDenied();
    }
    let continuingUnknownPublicationId: string | undefined;
    const continuingTransfer =
      input.committedResponse?.continuingTeamsFileTransfer;
    if (continuingTransfer !== undefined) {
      if (
        input.publication !== true ||
        input.retryActionId !== undefined ||
        input.runId !== undefined ||
        provider !== "microsoft-teams" ||
        !continuingTransfer ||
        !isUuidLike(continuingTransfer.transferId) ||
        !isUuidLike(continuingTransfer.publicationId) ||
        !Number.isSafeInteger(continuingTransfer.version) ||
        continuingTransfer.version < 1 ||
        !["consent_unknown", "file_info_unknown"].includes(
          continuingTransfer.phase,
        )
      )
        throw failedChatRetryDenied();
      // The caller supplies a selector only. Independently prove the exact
      // unknown publication is this native run's own selected file, not a
      // sibling effect or another actor/generation. All ordinary source and
      // committed-result authorization below still runs unchanged.
      const [continuing] = await tx
        .select({
          publicationId: chatPublications.id,
          attemptId: chatTeamsFileTransfers.attemptId,
          attemptExpiresAt: chatTeamsFileTransfers.attemptExpiresAt,
        })
        .from(chatTeamsFileTransfers)
        .innerJoin(
          chatPublications,
          and(
            eq(chatPublications.id, chatTeamsFileTransfers.publicationId),
            eq(chatPublications.companyId, chatTeamsFileTransfers.companyId),
            eq(chatPublications.endpointId, chatTeamsFileTransfers.endpointId),
            eq(
              chatPublications.conversationId,
              chatTeamsFileTransfers.conversationId,
            ),
            eq(chatPublications.issueId, chatTeamsFileTransfers.issueId),
            eq(chatPublications.commentId, chatTeamsFileTransfers.commentId),
            eq(chatPublications.state, "delivery_unknown"),
            sql`${chatPublications.payload}->'attachmentIds' = jsonb_build_array(${chatTeamsFileTransfers.attachmentId}::text)`,
          ),
        )
        .innerJoin(
          chatEndpoints,
          and(
            eq(chatEndpoints.id, chatTeamsFileTransfers.endpointId),
            eq(chatEndpoints.companyId, input.companyId),
            eq(chatEndpoints.provider, "microsoft-teams"),
          ),
        )
        .innerJoin(
          chatConversations,
          and(
            eq(chatConversations.id, chatTeamsFileTransfers.conversationId),
            eq(chatConversations.companyId, input.companyId),
            eq(chatConversations.endpointId, chatTeamsFileTransfers.endpointId),
            eq(chatConversations.issueId, issue.id),
            eq(
              chatConversations.sessionGeneration,
              chatTeamsFileTransfers.conversationGeneration,
            ),
          ),
        )
        .innerJoin(
          issueComments,
          and(
            eq(issueComments.id, chatTeamsFileTransfers.commentId),
            eq(issueComments.companyId, input.companyId),
            eq(issueComments.issueId, issue.id),
            eq(issueComments.createdByRunId, failedRun.id),
            eq(issueComments.authorAgentId, input.agentId),
            isNull(issueComments.deletedAt),
          ),
        )
        .innerJoin(
          issueAttachments,
          and(
            eq(issueAttachments.id, chatTeamsFileTransfers.attachmentId),
            eq(issueAttachments.companyId, input.companyId),
            eq(issueAttachments.issueId, issue.id),
            eq(issueAttachments.issueCommentId, issueComments.id),
            eq(issueAttachments.originatingRunId, failedRun.id),
          ),
        )
        .innerJoin(
          assets,
          and(
            eq(assets.id, issueAttachments.assetId),
            eq(assets.companyId, input.companyId),
            eq(assets.sha256, chatTeamsFileTransfers.sha256),
            eq(assets.byteSize, chatTeamsFileTransfers.byteSize),
          ),
        )
        .where(
          and(
            eq(chatTeamsFileTransfers.companyId, input.companyId),
            eq(chatTeamsFileTransfers.issueId, issue.id),
            eq(chatTeamsFileTransfers.id, continuingTransfer.transferId),
            eq(
              chatTeamsFileTransfers.publicationId,
              continuingTransfer.publicationId,
            ),
            eq(chatTeamsFileTransfers.version, continuingTransfer.version),
            eq(chatTeamsFileTransfers.phase, continuingTransfer.phase),
          ),
        )
        .for("share", { noWait: true });
      if (
        !continuing ||
        (continuing.attemptId &&
          (!continuing.attemptExpiresAt ||
            continuing.attemptExpiresAt > new Date()))
      )
        throw failedChatRetryDenied();
      continuingUnknownPublicationId = continuing.publicationId;
    }
    const [question] = await tx
      .select({ id: issueThreadInteractions.id })
      .from(issueThreadInteractions)
      .where(
        and(
          eq(issueThreadInteractions.companyId, input.companyId),
          eq(issueThreadInteractions.issueId, issue.id),
          eq(issueThreadInteractions.sourceRunId, failedRun.id),
        ),
      )
      .limit(1);
    const [answerDelivery] = await tx
      .select({ id: issueQuestionResponseDeliveries.id })
      .from(issueQuestionResponseDeliveries)
      .where(
        and(
          eq(issueQuestionResponseDeliveries.companyId, input.companyId),
          eq(issueQuestionResponseDeliveries.targetRunId, failedRun.id),
        ),
      )
      .limit(1);
    const [resultPublication] = await tx
      .select({ id: chatPublications.id })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, input.companyId),
          eq(chatPublications.issueId, issue.id),
          input.committedResponse
            ? eq(chatPublications.state, "delivery_unknown")
            : undefined,
          continuingUnknownPublicationId
            ? ne(chatPublications.id, continuingUnknownPublicationId)
            : undefined,
          or(
            and(
              like(chatPublications.idempotencyKey, `run:${failedRun.id}:%`),
              eq(chatPublications.state, "delivery_unknown"),
            ),
            sql`exists (select 1 from issue_comments result_comment where result_comment.id = ${chatPublications.commentId}
          and result_comment.company_id = ${input.companyId}::uuid and result_comment.created_by_run_id = ${failedRun.id}::uuid
          )`,
          ),
        ),
      )
      .limit(1);
    if (
      (!input.committedResponse && accepted) ||
      resultPublication ||
      question ||
      answerDelivery
    )
      throw failedChatRetryDenied();
    if (context.chatFailedRunRetry) {
      const hint = context.chatFailedRunRetry as Record<string, unknown>;
      const [priorIntent] = await tx
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.id, failedRun.wakeupRequestId),
            eq(chatActions.companyId, input.companyId),
          ),
        )
        .for("share", { noWait: true });
      const [priorReceipt] = await tx
        .select()
        .from(agentWakeupRequests)
        .where(
          and(
            eq(agentWakeupRequests.id, failedRun.wakeupRequestId),
            eq(agentWakeupRequests.companyId, input.companyId),
          ),
        )
        .for("share", { noWait: true });
      if (
        !priorIntent ||
        priorIntent.kind !== "failed_run_retry" ||
        priorIntent.status !== "processed" ||
        !priorReceipt ||
        priorReceipt.runId !== failedRun.id ||
        !["failed", "completed"].includes(priorReceipt.status) ||
        typeof priorIntent.payload.failedRunId !== "string" ||
        !isUuidLike(priorIntent.payload.failedRunId) ||
        hint.version !== 1 ||
        hint.actionId !== priorIntent.id ||
        hint.failedRunId !== priorIntent.payload.failedRunId ||
        failedRun.retryOfRunId !== priorIntent.payload.failedRunId ||
        context.retryOfRunId !== failedRun.retryOfRunId
      )
        throw failedChatRetryDenied();
      const parent = await failedChatRetrySource(
        tx,
        {
          ...input,
          failedRunId: priorIntent.payload.failedRunId,
          committedResponse: undefined,
        },
        ancestors,
      );
      if (
        priorIntent.payload.sourceScopeSha256 !== parent.sourceScopeSha256 ||
        priorIntent.endpointId !== parent.endpointId ||
        priorIntent.conversationId !== parent.conversationId ||
        priorIntent.principalId !== parent.principalId ||
        context.taskKey !== parent.taskKey ||
        provider !== parent.provider ||
        JSON.stringify(commentIds) !== JSON.stringify(parent.commentIds)
      )
        throw failedChatRetryDenied();
      assertFailedRetryReceipt(
        createDurableChatWakeupRequest({
          id: priorIntent.id,
          companyId: input.companyId,
          agentId: input.agentId,
          issueId: input.issueId,
          commentId: parent.commentIds.at(-1)!,
          requestedByActorType: parent.requestedByActorType,
          requestedByActorId: parent.requestedByActorId,
          requestedAt: priorIntent.createdAt,
          authorize: async () => {},
        }),
        priorReceipt,
      );
      const { sourceScopeSha256, ...parentScope } = parent;
      return hashFailedRetrySource({
        ...parentScope,
        failedRunId: failedRun.id,
        retryAncestors: [
          ...parent.retryAncestors,
          {
            actionId: priorIntent.id,
            failedRunId: parent.failedRunId,
            sourceScopeSha256,
          },
        ],
      });
    }
    // Include every receipt that fed this run, including a deferred owner's
    // coalesced children. A mutable latest-comment hint cannot drop a sibling.
    const admittedBatch =
      await tx.execute(sql`select source.id, source.payload->>'commentId' as comment_id
      from agent_wakeup_requests receipt join chat_actions source on source.id = receipt.id
      where receipt.company_id = ${input.companyId}::uuid and receipt.agent_id = ${input.agentId}::uuid
        and (receipt.run_id = ${failedRun.id}::uuid or receipt.id = ${failedRun.wakeupRequestId}::uuid
          or receipt.payload->>'coalescedIntoWakeupRequestId' = ${failedRun.wakeupRequestId})
        and source.company_id = ${input.companyId}::uuid and source.kind = 'inbound_wakeup' limit 51`);
    if (
      admittedBatch.length !== commentIds.length ||
      admittedBatch.some(
        (entry) => !commentIds.includes(String(entry.comment_id)),
      )
    )
      throw failedChatRetryDenied();
    const sources = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, input.companyId),
          eq(chatActions.kind, "inbound_wakeup"),
          sql`${chatActions.payload}->>'issueId' = ${issue.id}`,
          inArray(
            sql<string>`${chatActions.payload}->>'commentId'`,
            commentIds,
          ),
        ),
      );
    if (sources.length !== commentIds.length) throw failedChatRetryDenied();
    const ordered = commentIds.map((id) =>
      sources.find((action) => action.payload.commentId === id)!,
    );
    const first = ordered[0]!;
    if (
      !first ||
      !first.principalId ||
      !first.conversationId ||
      sources.some(
        (action) =>
          action.endpointId !== first.endpointId ||
          action.conversationId !== first.conversationId ||
          action.principalId !== first.principalId ||
          action.payload.requestedByActorType !==
            first.payload.requestedByActorType ||
          action.payload.requestedByActorId !==
            first.payload.requestedByActorId,
      )
    )
      throw failedChatRetryDenied();
    const identity = await tx.execute(
      sql`select pg_try_advisory_xact_lock(hashtextextended(${`chat-identity:${input.companyId}:${first.principalId}`}, 0)) as locked`,
    );
    if (!identity[0]?.locked)
      throw new NativeChatReviewPresentationContentionError();
    const canonicalSources: Array<Record<string, unknown>> = [];
    let destination: Awaited<ReturnType<typeof authorizeInboundWakeup>> | null =
      null;
    for (const action of ordered) {
      destination = await authorizeInboundWakeup(tx, action, {
        nonblocking: true,
        terminal: input.publication === true,
      }).catch((error) => {
        if (isExternalActionAuthorizationChange(error))
          throw failedChatRetryDenied();
        throw error;
      });
      const [delivery] = await tx
        .select()
        .from(chatDeliveries)
        .where(eq(chatDeliveries.id, action.deliveryId!))
        .for("update", { noWait: true });
      const [current] = await tx
        .select()
        .from(chatActions)
        .where(eq(chatActions.id, action.id))
        .for("update", { noWait: true });
      const [comment] = await tx
        .select()
        .from(issueComments)
        .where(
          and(
            eq(issueComments.id, String(action.payload.commentId)),
            eq(issueComments.companyId, input.companyId),
            eq(issueComments.issueId, issue.id),
          ),
        )
        .for("share", { noWait: true });
      if (
        !current ||
        current.status !== "processed" ||
        inboundWakeScope(current) !== inboundWakeScope(action) ||
        !delivery ||
        delivery.state !== "processed" ||
        !comment ||
        comment.deletedAt ||
        comment.updatedAt.getTime() !== comment.createdAt.getTime() ||
        comment.updatedAt >
          (input.committedResponse
            ? accepted!.createdAt
            : failedRun.finishedAt!) ||
        destination.endpoint.provider !== provider ||
        JSON.stringify(lifecycleRuntimeFence(delivery)) !==
          JSON.stringify(lifecycleRuntimeFence(destination.delivery))
      )
        throw failedChatRetryDenied();
      const [lifecycle] = await tx
        .select({ id: chatDeliveries.id })
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.companyId, input.companyId),
            eq(chatDeliveries.endpointId, first.endpointId),
            or(
              isNull(chatDeliveries.conversationId),
              eq(chatDeliveries.conversationId, first.conversationId),
            ),
            ne(chatDeliveries.state, "filtered"),
            sql`${chatDeliveries.normalizedEvent}->'runtimeContext' = ${JSON.stringify(lifecycleRuntimeFence(delivery))}::jsonb`,
            inArray(chatDeliveries.eventKind, [
              "message_updated",
              "message_deleted",
              "message_restored",
            ]),
            sql`${chatDeliveries.normalizedEvent}->'message'->>'targetProviderEventId' = ${delivery.providerEventId}`,
          ),
        )
        .limit(1);
      if (lifecycle) throw failedChatRetryDenied();
      const [receipt] = await tx
        .select()
        .from(agentWakeupRequests)
        .where(eq(agentWakeupRequests.id, action.id))
        .for("share", { noWait: true });
      if (!receipt) throw failedChatRetryDenied();
      assertFailedRetryReceipt(
        createDurableChatWakeupRequest({
          id: action.id,
          companyId: input.companyId,
          agentId: input.agentId,
          issueId: issue.id,
          commentId: comment.id,
          requestedByActorType: action.payload.requestedByActorType as
            "user" | "system",
          requestedByActorId: String(action.payload.requestedByActorId),
          requestedAt: action.createdAt,
          authorize: async () => {},
        }),
        receipt,
      );
      let owner = receipt;
      const seen = new Set<string>();
      for (
        let depth = 0;
        owner.payload?.coalescedIntoWakeupRequestId !== undefined;
        depth++
      ) {
        const ownerId = owner.payload.coalescedIntoWakeupRequestId;
        // The scheduler writes a direct child -> canonical owner edge. Nested
        // chains/cycles are not silently interpreted as additional authority.
        if (
          depth >= 1 ||
          owner.status !== "coalesced" ||
          typeof ownerId !== "string" ||
          !isUuidLike(ownerId) ||
          seen.has(ownerId)
        )
          throw failedChatRetryDenied();
        seen.add(ownerId);
        const [next] = await tx
          .select()
          .from(agentWakeupRequests)
          .where(
            and(
              eq(agentWakeupRequests.id, ownerId),
              eq(agentWakeupRequests.companyId, input.companyId),
            ),
          )
          .for("share", { noWait: true });
        if (!next) throw failedChatRetryDenied();
        owner = next;
      }
      if (
        owner.id !== failedRun.wakeupRequestId ||
        owner.runId !== failedRun.id ||
        owner.agentId !== input.agentId ||
        owner.requestedByActorType !== receipt.requestedByActorType ||
        owner.requestedByActorId !== receipt.requestedByActorId ||
        ["skipped", "cancelled"].includes(receipt.status)
      )
        throw failedChatRetryDenied();
      canonicalSources.push({
        actionId: action.id,
        deliveryId: delivery.id,
        commentId: comment.id,
        principalId: action.principalId,
        scope: inboundWakeScope(action),
        fence: lifecycleRuntimeFence(delivery),
        bodySha256: createHash("sha256").update(comment.body).digest("hex"),
        omissionReasons: action.payload.attachmentOmissionReasons ?? {},
        receiptId: receipt.id,
        ownerId: owner.id,
      });
    }
    if (!destination) throw failedChatRetryDenied();
    const newestSource = ordered.reduce(
      (latest, action) =>
        action.createdAt > latest ? action.createdAt : latest,
      first.createdAt,
    );
    const [newer] = await tx
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, input.companyId),
          eq(chatActions.conversationId, first.conversationId),
          eq(chatActions.kind, "inbound_wakeup"),
          notInArray(
            chatActions.id,
            ordered.map((action) => action.id),
          ),
          gte(chatActions.createdAt, newestSource),
          sql`exists (select 1 from agent_wakeup_requests newer_admission where newer_admission.id = ${chatActions.id}
        and newer_admission.company_id = ${input.companyId}::uuid and newer_admission.status <> 'skipped')`,
        ),
      )
      .limit(1);
    if (newer && !input.publication) throw failedChatRetryDenied();
    const scope = {
      failedRunId: failedRun.id,
      sourceWakeupRequestId: failedRun.wakeupRequestId,
      issueId: issue.id,
      agentId: input.agentId,
      taskKey: context.taskKey as string,
      provider,
      commentIds,
      sources: canonicalSources,
      endpointId: first.endpointId,
      conversationId: first.conversationId,
      principalId: first.principalId,
      sessionGeneration: destination.conversation.sessionGeneration,
      requestedByActorType: first.payload.requestedByActorType as
        "user" | "system",
      requestedByActorId: String(first.payload.requestedByActorId),
      retryAncestors: [],
    };
    return hashFailedRetrySource(scope);
  }

  const unregisterCommittedResponseAuthority =
    registerCommittedChatResponseAuthority(db, async (tx, input) => {
      try {
        await failedChatRetrySource(tx, {
          ...input,
          failedRunId: input.runId,
          publication: true,
          committedResponse: { resultId: input.resultId },
        });
      } catch (error) {
        if (
          error instanceof HttpError &&
          (error.details as { code?: string } | undefined)?.code ===
            "chat_failed_run_retry_not_authorized"
        ) {
          throw new CommittedChatResponseAuthorizationError();
        }
        throw error;
      }
    });

  async function prepareFailedChatRunRetry(
    tx: DbOrTransaction,
    input: {
      companyId: string;
      issueId: string;
      agentId: string;
      failedRunId: string;
      initiatedByUserId: string;
    },
  ): Promise<{ actionId: string; issueId: string }> {
    const source = await failedChatRetrySource(tx, input);
    const providerActionId = `failed-run-retry:${source.failedRunId}`;
    const [existing] = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.endpointId, source.endpointId),
          eq(chatActions.providerActionId, providerActionId),
        ),
      )
      .for("update", { noWait: true });
    if (existing) {
      if (
        existing.kind !== "failed_run_retry" ||
        existing.companyId !== input.companyId ||
        existing.payload.sourceScopeSha256 !== source.sourceScopeSha256
      )
        throw failedChatRetryDenied();
      return { actionId: existing.id, issueId: input.issueId };
    }
    await assertFailedNativeRetryState(tx, source, input.companyId);
    const [busy] = await tx
      .select({ id: heartbeatRuns.id })
      .from(heartbeatRuns)
      .where(
        and(
          eq(heartbeatRuns.companyId, input.companyId),
          inArray(heartbeatRuns.status, [
            "queued",
            "running",
            "scheduled_retry",
          ]),
          sql`coalesce(${heartbeatRuns.contextSnapshot}->>'issueId', ${heartbeatRuns.contextSnapshot}->>'taskId') = ${input.issueId}`,
        ),
      )
      .limit(1);
    if (busy || !input.initiatedByUserId) throw failedChatRetryDenied();
    const now = new Date();
    const [intent] = await tx
      .insert(chatActions)
      .values({
        companyId: input.companyId,
        endpointId: source.endpointId,
        conversationId: source.conversationId,
        principalId: source.principalId,
        kind: "failed_run_retry",
        providerActionId,
        payload: {
          version: 1,
          ...source,
          initiatedByUserId: input.initiatedByUserId,
        },
        status: "issued",
        result: { code: "failed_chat_retry_queued", attemptCount: 0 },
        createdAt: now,
        updatedAt: now,
      })
      .returning();
    await logActivity(tx as Db, {
      companyId: input.companyId,
      actorType: "user",
      actorId: input.initiatedByUserId,
      action: "chat.failed_run_retry_requested",
      entityType: "heartbeat_run",
      entityId: input.failedRunId,
      details: {
        retryActionId: intent.id,
        issueId: input.issueId,
        commentCount: source.commentIds.length,
      },
    });
    return { actionId: intent.id, issueId: input.issueId };
  }

  async function authorizeFailedChatRunRetry(
    tx: DbOrTransaction,
    input: {
      companyId: string;
      issueId: string;
      agentId: string;
      retryActionId: string;
      runId?: string;
      publication?: boolean;
    },
  ) {
    const [snapshot] = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, input.retryActionId),
          eq(chatActions.companyId, input.companyId),
        ),
      );
    if (
      !snapshot ||
      snapshot.kind !== "failed_run_retry" ||
      typeof snapshot.payload.failedRunId !== "string" ||
      snapshot.payload.issueId !== input.issueId ||
      snapshot.payload.agentId !== input.agentId
    )
      throw failedChatRetryDenied();
    const source = await failedChatRetrySource(tx, {
      ...input,
      failedRunId: snapshot.payload.failedRunId,
    });
    const [intent] = await tx
      .select()
      .from(chatActions)
      .where(eq(chatActions.id, snapshot.id))
      .for("update", { noWait: true });
    if (
      !intent ||
      !(
        input.publication
          ? ["issued", "processing", "processed", "failed", "cancelled"]
          : ["issued", "processing", "processed"]
      ).includes(intent.status) ||
      intent.payload.version !== 1 ||
      intent.endpointId !== source.endpointId ||
      intent.conversationId !== source.conversationId ||
      intent.principalId !== source.principalId ||
      intent.payload.sourceScopeSha256 !== source.sourceScopeSha256 ||
      JSON.stringify(intent.payload) !== JSON.stringify(snapshot.payload)
    )
      throw failedChatRetryDenied();
    const [receipt] = await tx
      .select()
      .from(agentWakeupRequests)
      .where(eq(agentWakeupRequests.id, intent.id))
      .for("share", { noWait: true });
    if (receipt) {
      assertFailedRetryReceipt(
        createDurableChatWakeupRequest({
          id: intent.id,
          companyId: input.companyId,
          agentId: input.agentId,
          issueId: input.issueId,
          commentId: source.commentIds.at(-1)!,
          requestedByActorType: source.requestedByActorType,
          requestedByActorId: source.requestedByActorId,
          requestedAt: intent.createdAt,
          authorize: async () => {},
        }),
        receipt,
      );
      if (
        (!input.publication &&
          ["skipped", "cancelled"].includes(receipt.status)) ||
        (input.runId && receipt.runId !== input.runId)
      )
        throw failedChatRetryDenied();
    } else if (input.runId) throw failedChatRetryDenied();
    if (input.runId) {
      const [run] = await tx
        .select()
        .from(heartbeatRuns)
        .where(
          and(
            eq(heartbeatRuns.id, input.runId),
            eq(heartbeatRuns.companyId, input.companyId),
            eq(heartbeatRuns.agentId, input.agentId),
          ),
        )
        .for("share", { noWait: true });
      if (
        !run ||
        run.wakeupRequestId !== intent.id ||
        run.retryOfRunId !== source.failedRunId
      )
        throw failedChatRetryDenied();
    }
    return { ...source, intent };
  }

  const unregisterFailedRetryAuthority = registerFailedChatRunRetryAuthority(
    db,
    async (tx, input) => {
      const source = await authorizeFailedChatRunRetry(tx, {
        ...input,
        retryActionId: input.wakeupRequestId,
      });
      await assertFailedNativeRetryState(tx, source, input.companyId);
      const context = input.contextSnapshot;
      const hint = context.chatFailedRunRetry as
        Record<string, unknown> | undefined;
      if (
        context.issueId !== source.issueId ||
        context.source !== `chat:${source.provider}` ||
        context.taskKey !== source.taskKey ||
        context.retryOfRunId !== source.failedRunId ||
        JSON.stringify(retryCommentIds(context)) !==
          JSON.stringify(source.commentIds) ||
        hint?.version !== 1 ||
        hint.actionId !== source.intent.id ||
        hint.failedRunId !== source.failedRunId ||
        !Array.isArray(context.externalAttachmentOmissions) ||
        JSON.stringify(
          context.externalAttachmentOmissions.map((entry) =>
            entry && typeof entry === "object"
              ? [entry.commentId, entry.reasons]
              : null,
          ),
        ) !==
          JSON.stringify(
            source.sources.map((entry) => [
              entry.commentId,
              entry.omissionReasons,
            ]),
          )
      )
        throw failedChatRetryDenied();
    },
  );

  async function failedChatRetryReceipt(
    action: typeof chatActions.$inferSelect,
  ) {
    const [receipt] = await db
      .select()
      .from(agentWakeupRequests)
      .where(
        and(
          eq(agentWakeupRequests.id, action.id),
          eq(agentWakeupRequests.companyId, action.companyId),
        ),
      );
    const [run] = receipt?.runId
      ? await db
          .select()
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.id, receipt.runId),
              eq(heartbeatRuns.companyId, action.companyId),
            ),
          )
      : [];
    const status = ["succeeded", "failed", "cancelled"].includes(
      run?.status ?? "",
    )
      ? (run!.status as "succeeded" | "failed" | "cancelled")
      : run?.status === "timed_out"
        ? "failed"
        : run?.status === "running"
          ? "running"
          : receipt?.status === "deferred_issue_execution"
            ? "deferred"
            : ["failed", "cancelled"].includes(action.status)
              ? (action.status as "failed" | "cancelled")
              : ["skipped", "failed", "cancelled"].includes(
                    receipt?.status ?? "",
                  )
                ? "failed"
                : "queued";
    return {
      actionId: action.id,
      issueId: String(action.payload.issueId),
      runId: run?.id ?? null,
      status,
    };
  }

  async function claimFailedChatRunRetry(actionId: string) {
    const [candidate] = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "failed_run_retry"),
        ),
      );
    if (!candidate) throw notFound("Chat retry request not found");
    const now = new Date();
    if (
      shuttingDown ||
      !["issued", "processing"].includes(candidate.status) ||
      (candidate.status === "processing" &&
        candidate.updatedAt.getTime() >
          now.getTime() - DELIVERY_PROCESSING_STALE_MS) ||
      (typeof candidate.result?.retryAt === "string" &&
        Date.parse(candidate.result.retryAt) > now.getTime())
    )
      return failedChatRetryReceipt(candidate);
    const [claimed] = await db
      .update(chatActions)
      .set({ status: "processing", updatedAt: now })
      .where(
        and(
          eq(chatActions.id, candidate.id),
          eq(chatActions.status, candidate.status),
          eq(chatActions.updatedAt, candidate.updatedAt),
        ),
      )
      .returning();
    if (!claimed) return failedChatRetryReceipt(candidate);
    const attemptCount = Number(candidate.result?.attemptCount ?? 0) + 1;
    const settle = async (status: string, result: Record<string, unknown>) => {
      const [current] = await db
        .update(chatActions)
        .set({ status, result, updatedAt: new Date() })
        .where(
          and(
            eq(chatActions.id, claimed.id),
            eq(chatActions.status, "processing"),
            eq(chatActions.updatedAt, now),
          ),
        )
        .returning();
      return failedChatRetryReceipt(current ?? claimed);
    };
    try {
      const scope = {
        companyId: claimed.companyId,
        issueId: String(claimed.payload.issueId),
        agentId: String(claimed.payload.agentId),
        retryActionId: claimed.id,
      };
      const source = await db.transaction((tx) =>
        authorizeFailedChatRunRetry(tx, scope),
      );
      const existing = await db
        .select({ id: agentWakeupRequests.id })
        .from(agentWakeupRequests)
        .where(eq(agentWakeupRequests.id, claimed.id));
      if (!existing.length) {
        const context = {
          issueId: source.issueId,
          taskKey: source.taskKey,
          source: `chat:${source.provider}`,
          wakeCommentId: source.commentIds.at(-1)!,
          wakeCommentIds: source.commentIds,
          retryOfRunId: source.failedRunId,
          chatFailedRunRetry: {
            version: 1,
            actionId: claimed.id,
            failedRunId: source.failedRunId,
          },
          externalAttachmentOmissions: source.sources.map((entry) => ({
            commentId: entry.commentId,
            reasons: entry.omissionReasons,
          })),
        };
        await options.heartbeat.wakeup(source.agentId, {
          source: "on_demand",
          triggerDetail: "manual",
          reason: "retry_failed_run",
          payload: context,
          contextSnapshot: context,
          allowRunCoalescing: false,
          requestedByActorType: source.requestedByActorType,
          requestedByActorId: source.requestedByActorId,
          durableChatRequest: createDurableChatWakeupRequest({
            id: claimed.id,
            companyId: claimed.companyId,
            agentId: source.agentId,
            issueId: source.issueId,
            commentId: source.commentIds.at(-1)!,
            requestedByActorType: source.requestedByActorType,
            requestedByActorId: source.requestedByActorId,
            requestedAt: claimed.createdAt,
            failedRunRetry: { failedRunId: source.failedRunId },
            authorize: async (tx) => {
              const current = await authorizeFailedChatRunRetry(tx, scope);
              await assertFailedNativeRetryState(
                tx,
                current,
                claimed.companyId,
              );
            },
          }),
        });
      }
      const [receipt] = await db
        .select()
        .from(agentWakeupRequests)
        .where(eq(agentWakeupRequests.id, claimed.id));
      if (!receipt) throw new Error("chat_retry_receipt_not_committed");
      return settle(
        ["skipped", "failed", "cancelled"].includes(receipt.status)
          ? "failed"
          : "processed",
        { code: "failed_chat_retry_durable", attemptCount },
      );
    } catch (error) {
      const [receipt] = await db
        .select()
        .from(agentWakeupRequests)
        .where(eq(agentWakeupRequests.id, claimed.id));
      if (receipt)
        return settle("processed", {
          code: "failed_chat_retry_durable",
          attemptCount,
        });
      const denied =
        error &&
        typeof error === "object" &&
        "details" in error &&
        error.details &&
        typeof error.details === "object" &&
        "code" in error.details &&
        [
          "chat_failed_run_retry_not_authorized",
          "chat_action_authorization_changed",
        ].includes(String(error.details.code));
      const retryable = !denied && attemptCount < 8;
      return settle(retryable ? "issued" : "failed", {
        code: retryable
          ? "failed_chat_retry_contended"
          : "failed_chat_retry_not_authorized",
        attemptCount,
        ...(retryable
          ? {
              retryAt: new Date(
                Date.now() + Math.min(5_000, attemptCount * 250),
              ).toISOString(),
            }
          : {}),
      });
    }
  }

  const failedRetryTasks = new Map<
    string,
    ReturnType<typeof claimFailedChatRunRetry>
  >();
  function processFailedChatRunRetry(actionId: string) {
    const existing = failedRetryTasks.get(actionId);
    if (existing) return existing;
    const task = claimFailedChatRunRetry(actionId);
    failedRetryTasks.set(actionId, task);
    void task.then(
      () => failedRetryTasks.delete(actionId),
      () => failedRetryTasks.delete(actionId),
    );
    return task;
  }

  async function processFailedChatRunRetries(limit = 20) {
    if (shuttingDown) return 0;
    const now = new Date();
    const candidates = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "failed_run_retry"),
          or(
            eq(chatActions.status, "issued"),
            and(
              eq(chatActions.status, "processing"),
              lte(
                chatActions.updatedAt,
                new Date(now.getTime() - DELIVERY_PROCESSING_STALE_MS),
              ),
            ),
          ),
          sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
        ),
      )
      .orderBy(asc(chatActions.createdAt), asc(chatActions.id))
      .limit(Math.max(1, Math.min(50, limit)));
    for (const candidate of candidates)
      await processFailedChatRunRetry(candidate.id);
    return candidates.length;
  }

  let failedRetryNoticeCursor: { createdAt: Date; id: string } | null = null;
  async function enqueueFailedChatRetryPublications(
    limit: number,
  ): Promise<number> {
    const cursor = failedRetryNoticeCursor;
    const batchSize = Math.max(1, Math.min(50, limit));
    const candidates = await db
      .select({ action: chatActions, receipt: agentWakeupRequests })
      .from(chatActions)
      .innerJoin(
        agentWakeupRequests,
        and(
          eq(agentWakeupRequests.id, chatActions.id),
          eq(agentWakeupRequests.companyId, chatActions.companyId),
        ),
      )
      .where(
        and(
          eq(chatActions.kind, "failed_run_retry"),
          isNull(agentWakeupRequests.runId),
          cursor
            ? sql`(${chatActions.createdAt}, ${chatActions.id}) > (${cursor.createdAt.toISOString()}::timestamptz, ${cursor.id}::uuid)`
            : undefined,
          inArray(agentWakeupRequests.status, [
            "deferred_issue_execution",
            "cancelled",
            "failed",
            "skipped",
          ]),
          sql`not exists (select 1 from chat_publications retry_notice where retry_notice.company_id = ${chatActions.companyId}
          and retry_notice.idempotency_key = 'wake:' || ${chatActions.id}::text || ':' ||
          case when ${agentWakeupRequests.status} = 'deferred_issue_execution' then 'queued' else 'not_started' end || ':' ||
          ${chatActions.endpointId}::text || ':' || ${chatActions.conversationId}::text)`,
        ),
      )
      .orderBy(asc(chatActions.createdAt), asc(chatActions.id))
      .limit(batchSize);
    const last = candidates.at(-1)?.action;
    failedRetryNoticeCursor =
      candidates.length >= batchSize && last
        ? { createdAt: last.createdAt, id: last.id }
        : null;
    let inserted = 0;
    for (const { action, receipt } of candidates) {
      try {
        inserted += await db.transaction(async (tx) => {
          const source = await authorizeFailedChatRunRetry(tx, {
            companyId: action.companyId,
            issueId: String(action.payload.issueId),
            agentId: String(action.payload.agentId),
            retryActionId: action.id,
            publication: true,
          });
          const [current] = await tx
            .select()
            .from(agentWakeupRequests)
            .where(eq(agentWakeupRequests.id, receipt.id))
            .for("update", { noWait: true });
          if (!current || current.runId || current.status !== receipt.status)
            return 0;
          const state =
            current.status === "deferred_issue_execution"
              ? "queued"
              : "not_started";
          return (
            await tx
              .insert(chatPublications)
              .values({
                companyId: action.companyId,
                endpointId: source.endpointId,
                conversationId: source.conversationId,
                issueId: source.issueId,
                commentId: source.commentIds.at(-1)!,
                idempotencyKey: inboundWakePublicationKey(
                  action.id,
                  state,
                  source.endpointId,
                  source.conversationId,
                ),
                payload: projectSafeChatPublication({
                  classification: "external",
                  source: "safe_milestone",
                  text:
                    state === "queued"
                      ? "Your retry is queued."
                      : "This retry was not started. Open the task in Paperclip for details.",
                  progressState: state === "queued" ? "queued" : "failed",
                }),
                state: "pending",
              })
              .onConflictDoNothing()
              .returning({ id: chatPublications.id })
          ).length;
        });
      } catch (error) {
        if (
          isExternalChatWaitAuthorizationContention(error) ||
          error instanceof NativeChatReviewPresentationContentionError ||
          isExternalActionAuthorizationChange(error) ||
          (error &&
            typeof error === "object" &&
            "status" in error &&
            error.status === 409)
        )
          continue;
        throw error;
      }
    }
    return inserted;
  }

  async function authorizeRetainedChatSourcePublication(
    tx: DbOrTransaction,
    publication: typeof chatPublications.$inferSelect,
  ): Promise<boolean> {
    const notice = parseInboundWakePublicationKey(publication.idempotencyKey);
    let runId = runIdFromMilestonePublication(publication);
    if (!runId && publication.commentId && !notice) {
      const [comment] = await tx
        .select({ runId: issueComments.createdByRunId })
        .from(issueComments)
        .where(
          and(
            eq(issueComments.id, publication.commentId),
            eq(issueComments.companyId, publication.companyId),
          ),
        );
      runId = comment?.runId ?? null;
    }
    if (!runId && publication.payload.interactionId && !notice) {
      const [interaction] = await tx
        .select({ runId: issueThreadInteractions.sourceRunId })
        .from(issueThreadInteractions)
        .where(
          and(
            eq(
              issueThreadInteractions.id,
              String(publication.payload.interactionId),
            ),
            eq(issueThreadInteractions.companyId, publication.companyId),
          ),
        );
      runId = interaction?.runId ?? null;
    }
    const [run] = runId
      ? await tx
          .select()
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.id, runId),
              eq(heartbeatRuns.companyId, publication.companyId),
            ),
          )
      : [];
    try {
      const committed = run?.resultJson?.nativeCommittedChatResponse;
      if (committed !== undefined) {
        if (
          !run ||
          !committed ||
          typeof committed !== "object" ||
          Array.isArray(committed)
        )
          return false;
        const marker = committed as Record<string, unknown>;
        if (
          marker.schema !== "paperclip.native_committed_chat_response.v1" ||
          typeof marker.resultId !== "string" ||
          !isUuidLike(marker.resultId) ||
          typeof marker.canonicalSha256 !== "string" ||
          typeof marker.decisionId !== "string" ||
          !isUuidLike(marker.decisionId)
        )
          return false;
        const source = await failedChatRetrySource(tx, {
          companyId: publication.companyId,
          issueId: publication.issueId,
          agentId: run.agentId,
          failedRunId: run.id,
          publication: true,
          committedResponse: {
            resultId: marker.resultId,
            canonicalSha256: marker.canonicalSha256,
            decisionId: marker.decisionId,
          },
        });
        if (
          source.endpointId !== publication.endpointId ||
          source.conversationId !== publication.conversationId
        )
          return false;
      }
      const actionId = notice?.wakeId ?? run?.wakeupRequestId;
      if (!actionId) return true;
      const [action] = await tx
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.id, actionId),
            eq(chatActions.companyId, publication.companyId),
          ),
        );
      if (action?.kind !== "failed_run_retry")
        return !run?.contextSnapshot?.chatFailedRunRetry;
      const source = await authorizeFailedChatRunRetry(tx, {
        companyId: publication.companyId,
        issueId: publication.issueId,
        agentId: String(action.payload.agentId),
        retryActionId: action.id,
        ...(run ? { runId: run.id } : {}),
        publication: true,
      });
      if (
        source.endpointId !== publication.endpointId ||
        source.conversationId !== publication.conversationId
      )
        return false;
      if (notice) {
        const [receipt] = await tx
          .select()
          .from(agentWakeupRequests)
          .where(eq(agentWakeupRequests.id, action.id))
          .for("share", { noWait: true });
        return (
          publication.commentId === source.commentIds.at(-1) &&
          !receipt?.runId &&
          (notice.state === "queued"
            ? receipt?.status === "deferred_issue_execution"
            : notice.state === "not_started" &&
              ["cancelled", "failed", "skipped"].includes(
                receipt?.status ?? "",
              ))
        );
      }
      return (
        !!run &&
        JSON.stringify(retryCommentIds(run.contextSnapshot ?? {})) ===
          JSON.stringify(source.commentIds) &&
        run.contextSnapshot?.source === `chat:${source.provider}`
      );
    } catch (error) {
      if (
        isExternalChatWaitAuthorizationContention(error) ||
        error instanceof NativeChatReviewPresentationContentionError
      )
        throw new NativeChatReviewPresentationContentionError();
      if (
        isExternalActionAuthorizationChange(error) ||
        (error &&
          typeof error === "object" &&
          "details" in error &&
          error.details &&
          typeof error.details === "object" &&
          "code" in error.details &&
          error.details.code === "chat_failed_run_retry_not_authorized")
      )
        return false;
      throw error;
    }
  }

  async function currentInboundWakeNotice(
    tx: DbOrTransaction,
    action: typeof chatActions.$inferSelect,
    terminal: boolean,
  ) {
    const identityLock = await tx.execute(
      sql`select pg_try_advisory_xact_lock(hashtextextended(${`chat-identity:${action.companyId}:${action.principalId}`}, 0)) as locked`,
    );
    if (!identityLock[0]?.locked)
      throw new NativeChatReviewPresentationContentionError();
    const authorized = await authorizeInboundWakeup(tx, action, {
      nonblocking: true,
      terminal,
    });
    // The policy locks above serialize destination/identity changes. Re-read
    // both receipts under NOWAIT locks: cancellation can update them without
    // taking the policy locks, and must win if it committed first.
    const [delivery] = await tx
      .select()
      .from(chatDeliveries)
      .where(eq(chatDeliveries.id, action.deliveryId!))
      .for("update", { noWait: true });
    const [currentAction] = await tx
      .select()
      .from(chatActions)
      .where(eq(chatActions.id, action.id))
      .for("update", { noWait: true });
    if (
      !currentAction ||
      inboundWakeScope(currentAction) !== inboundWakeScope(action) ||
      !["processed", "failed"].includes(currentAction.status) ||
      !delivery ||
      delivery.state !== "processed" ||
      delivery.companyId !== action.companyId ||
      delivery.endpointId !== action.endpointId ||
      delivery.conversationId !== action.conversationId ||
      delivery.principalId !== action.principalId
    )
      return null;
    const [comment] = await tx
      .select()
      .from(issueComments)
      .where(
        and(
          eq(issueComments.id, String(action.payload.commentId)),
          eq(issueComments.companyId, action.companyId),
          eq(issueComments.issueId, authorized.issue.id),
        ),
      )
      .for("share", { noWait: true });
    if (
      !comment ||
      (comment.deletedAt && !terminal) ||
      comment.authorUserId !==
        (action.payload.requestedByActorType === "user"
          ? action.payload.requestedByActorId
          : null)
    )
      return null;
    const [receipt] = await tx
      .select()
      .from(agentWakeupRequests)
      .where(eq(agentWakeupRequests.id, action.id))
      .for("update", { noWait: true });
    const ownerId =
      receipt?.payload?.coalescedIntoWakeupRequestId ?? receipt?.id;
    if (typeof ownerId !== "string" || !isUuidLike(ownerId)) return null;
    const owner =
      ownerId === receipt?.id
        ? receipt
        : await tx
            .select()
            .from(agentWakeupRequests)
            .where(eq(agentWakeupRequests.id, ownerId))
            .for("update", { noWait: true })
            .then((rows) => rows[0]);
    const resolved = resolveInboundWakeReceipt(
      currentAction,
      receipt ?? null,
      owner ?? null,
      terminal && comment.deletedAt !== null,
    );
    return resolved ? { ...resolved, ...authorized } : null;
  }

  let inboundWakeNoticeCursor: { createdAt: Date; id: string } | null = null;

  async function inboundQueueNoticeStillVisible(
    tx: DbOrTransaction,
    publication: typeof chatPublications.$inferSelect,
  ) {
    if (publication.state !== "published" || !publication.providerMessageId)
      return false;
    const [link] = await tx
      .select({ id: chatMessageLinks.id })
      .from(chatMessageLinks)
      .where(
        and(
          eq(chatMessageLinks.companyId, publication.companyId),
          eq(chatMessageLinks.endpointId, publication.endpointId),
          eq(chatMessageLinks.conversationId, publication.conversationId),
          eq(chatMessageLinks.publicationId, publication.id),
          eq(chatMessageLinks.providerMessageId, publication.providerMessageId),
          eq(chatMessageLinks.direction, "outbound"),
          isNull(chatMessageLinks.commentId),
        ),
      )
      .for("update", { noWait: true });
    return Boolean(link);
  }

  async function enqueueInboundWakeupPublications(limit = 50): Promise<number> {
    if (shuttingDown) return 0;
    const retryInserted = await enqueueFailedChatRetryPublications(limit);
    const owner = alias(agentWakeupRequests, "chat_notice_owner");
    const cursor = inboundWakeNoticeCursor;
    const sourceRemoved = sql`exists (select 1 from issue_comments removed_comment
      where removed_comment.company_id = ${chatActions.companyId}
        and removed_comment.issue_id::text = ${chatActions.payload}->>'issueId'
        and removed_comment.id::text = ${chatActions.payload}->>'commentId'
        and removed_comment.deleted_at is not null)`;
    const hasVisibleQueue = sql`exists (select 1 from chat_publications queued_notice
      join chat_message_links visible_queue on visible_queue.publication_id = queued_notice.id
        and visible_queue.company_id = queued_notice.company_id
        and visible_queue.endpoint_id = queued_notice.endpoint_id
        and visible_queue.conversation_id = queued_notice.conversation_id
        and visible_queue.provider_message_id = queued_notice.provider_message_id
        and visible_queue.direction = 'outbound' and visible_queue.comment_id is null
      where queued_notice.company_id = ${chatActions.companyId}
        and queued_notice.comment_id::text = ${chatActions.payload}->>'commentId'
        and queued_notice.state = 'published'
        and queued_notice.idempotency_key = 'wake:' || ${owner.id}::text || ':queued:' ||
          ${chatActions.endpointId}::text || ':' || ${chatActions.conversationId}::text)`;
    // A bounded keyset sweep, not an in-memory work queue. Advancing even past
    // revoked candidates prevents an inaccessible old message starving others.
    const candidates = await db
      .select({ action: chatActions })
      .from(chatActions)
      .innerJoin(
        agentWakeupRequests,
        eq(agentWakeupRequests.id, chatActions.id),
      )
      .innerJoin(
        owner,
        sql`${owner.id}::text = coalesce(${agentWakeupRequests.payload}->>'coalescedIntoWakeupRequestId', ${agentWakeupRequests.id}::text)`,
      )
      .where(
        and(
          eq(chatActions.kind, "inbound_wakeup"),
          inArray(chatActions.status, ["processed", "failed"]),
          eq(owner.companyId, chatActions.companyId),
          or(
            and(
              isNull(owner.runId),
              inArray(owner.status, [
                "deferred_issue_execution",
                "cancelled",
                "failed",
                "skipped",
              ]),
            ),
            and(sourceRemoved, hasVisibleQueue),
          ),
          sql`(( ${owner.status} = 'deferred_issue_execution'
          and ${agentWakeupRequests.status} not in ('cancelled','failed','skipped') and not (${sourceRemoved}))
          or ${hasVisibleQueue})`,
          cursor
            ? sql`(${chatActions.createdAt}, ${chatActions.id}) > (${cursor.createdAt.toISOString()}::timestamptz, ${cursor.id}::uuid)`
            : undefined,
          sql`not exists (select 1 from chat_publications notice
          where notice.company_id = ${chatActions.companyId}
            and notice.idempotency_key = 'wake:' || ${owner.id}::text || ':' ||
              (case when ${sourceRemoved} then 'removed' when ${owner.status} = 'deferred_issue_execution'
                and ${agentWakeupRequests.status} not in ('cancelled','failed','skipped')
                then 'queued' else 'not_started' end) || ':' ||
              ${chatActions.endpointId}::text || ':' || ${chatActions.conversationId}::text)`,
        ),
      )
      .orderBy(asc(chatActions.createdAt), asc(chatActions.id))
      .limit(Math.max(1, Math.min(limit, 200)));
    const last = candidates.at(-1)?.action;
    inboundWakeNoticeCursor =
      candidates.length >= Math.max(1, Math.min(limit, 200)) && last
        ? { createdAt: last.createdAt, id: last.id }
        : null;
    let inserted = retryInserted;
    for (const { action } of candidates) {
      try {
        inserted += await db.transaction(async (tx) => {
          const [receipt] = await tx
            .select()
            .from(agentWakeupRequests)
            .where(eq(agentWakeupRequests.id, action.id));
          const ownerId =
            receipt?.payload?.coalescedIntoWakeupRequestId ?? receipt?.id;
          if (
            typeof ownerId !== "string" ||
            !isUuidLike(ownerId) ||
            !action.conversationId
          )
            return 0;
          const queuedKey = inboundWakePublicationKey(
            ownerId,
            "queued",
            action.endpointId,
            action.conversationId,
          );
          const [prior] = await tx
            .select()
            .from(chatPublications)
            .where(
              and(
                eq(chatPublications.companyId, action.companyId),
                eq(chatPublications.idempotencyKey, queuedKey),
              ),
            );
          // Only the exact original notice may be retired; never post a failure
          // notice for input which never received a provider queue acknowledgement.
          if (
            prior &&
            (prior.state !== "published" ||
              prior.commentId !== action.payload.commentId)
          )
            return 0;
          const context = await currentInboundWakeNotice(
            tx,
            action,
            Boolean(prior),
          );
          if (
            !context ||
            context.ownerId !== ownerId ||
            context.state === "promoted" ||
            (context.state !== "queued" && !prior) ||
            (context.state === "queued" && prior)
          )
            return 0;
          if (prior && !(await inboundQueueNoticeStillVisible(tx, prior)))
            return 0;
          const rows = await tx
            .insert(chatPublications)
            .values({
              companyId: action.companyId,
              endpointId: action.endpointId,
              conversationId: action.conversationId,
              issueId: context.issue.id,
              commentId: String(action.payload.commentId),
              idempotencyKey: inboundWakePublicationKey(
                ownerId,
                context.state,
                action.endpointId,
                action.conversationId,
              ),
              payload: projectSafeChatPublication({
                classification: "external",
                source: "safe_milestone",
                text: inboundWakePublicationText(context.state),
                progressState: context.state === "queued" ? "queued" : "failed",
              }),
            })
            .onConflictDoNothing()
            .returning({ id: chatPublications.id });
          return rows.length;
        });
      } catch (error) {
        if (
          !isExternalActionAuthorizationChange(error) &&
          !isExternalChatWaitAuthorizationContention(error) &&
          !(error instanceof NativeChatReviewPresentationContentionError)
        )
          throw error;
      }
    }
    return inserted;
  }

  async function authorizeInboundWakePublication(
    tx: DbOrTransaction,
    publication: typeof chatPublications.$inferSelect,
  ) {
    const key = parseInboundWakePublicationKey(publication.idempotencyKey);
    if (key) {
      const [retry] = await tx
        .select({ kind: chatActions.kind })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.id, key.wakeId),
            eq(chatActions.companyId, publication.companyId),
          ),
        );
      if (retry?.kind === "failed_run_retry")
        return authorizeRetainedChatSourcePublication(tx, publication);
    }
    if (
      !key ||
      key.endpointId !== publication.endpointId ||
      key.conversationId !== publication.conversationId ||
      !publication.commentId
    )
      return false;
    const actions = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, publication.companyId),
          eq(chatActions.endpointId, publication.endpointId),
          eq(chatActions.conversationId, publication.conversationId),
          eq(chatActions.kind, "inbound_wakeup"),
          sql`${chatActions.payload}->>'issueId' = ${publication.issueId}`,
          sql`${chatActions.payload}->>'commentId' = ${publication.commentId}`,
        ),
      )
      .limit(2);
    if (actions.length !== 1) return false;
    if (key.state !== "queued") {
      const [prior] = await tx
        .select()
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, publication.companyId),
            eq(chatPublications.commentId, publication.commentId),
            eq(chatPublications.state, "published"),
            eq(
              chatPublications.idempotencyKey,
              inboundWakePublicationKey(
                key.wakeId,
                "queued",
                key.endpointId,
                key.conversationId,
              ),
            ),
          ),
        );
      if (!prior || !(await inboundQueueNoticeStillVisible(tx, prior)))
        return false;
    }
    try {
      const context = await currentInboundWakeNotice(
        tx,
        actions[0]!,
        key.state !== "queued",
      );
      return context?.ownerId === key.wakeId && context.state === key.state;
    } catch (error) {
      if (isExternalActionAuthorizationChange(error)) return false;
      if (isExternalChatWaitAuthorizationContention(error))
        throw new NativeChatReviewPresentationContentionError();
      throw error;
    }
  }

  async function acceptInboundWakeup(
    deliveryId: string,
    attachmentResult: Awaited<ReturnType<typeof ingestAttachments>>,
  ) {
    await db.transaction(async (tx) => {
      const action = await tx
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.deliveryId, deliveryId),
            eq(chatActions.kind, "inbound_wakeup"),
          ),
        )
        .limit(1)
        .then((rows) => rows[0] ?? null);
      if (!action) throw new Error("chat_inbound_wakeup_intent_missing");
      const { delivery } = await authorizeInboundWakeup(tx, action);
      if (delivery.state === "processed") return;
      if (delivery.state !== "processing")
        throw new Error("chat_inbound_wakeup_delivery_claim_lost");
      if (action.status !== "preparing") {
        const existingReceipt = await tx
          .select()
          .from(agentWakeupRequests)
          .where(eq(agentWakeupRequests.id, action.id))
          .limit(1)
          .then((rows) => rows[0] ?? null);
        if (!existingReceipt)
          throw new Error("chat_inbound_wakeup_action_claim_lost");
        assertDurableChatWakeupReceipt(
          createDurableChatWakeupRequest({
            id: action.id,
            companyId: action.companyId,
            agentId: String(action.payload.agentId),
            issueId: String(action.payload.issueId),
            commentId: String(action.payload.commentId),
            requestedByActorType: action.payload.requestedByActorType as
              "user" | "system",
            requestedByActorId: String(action.payload.requestedByActorId),
            requestedAt: action.createdAt,
            authorize: async () => {},
          }),
          existingReceipt,
        );
      }
      const accepted = await tx
        .update(chatDeliveries)
        .set({
          state: "processed",
          processedAt: new Date(),
          redactedError: attachmentOmissionDetail(attachmentResult),
          nextAttemptAt: null,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, deliveryId),
            eq(chatDeliveries.state, "processing"),
            eq(chatDeliveries.updatedAt, delivery.updatedAt),
          ),
        )
        .returning({ id: chatDeliveries.id });
      if (accepted.length !== 1)
        throw new Error("chat_inbound_wakeup_delivery_claim_lost");
      // An operator can repair a failed delivery ledger after its wake was
      // already committed. Keep the immutable receipt and never admit twice.
      if (action.status !== "preparing") return;
      const issued = await tx
        .update(chatActions)
        .set({
          status: "issued",
          payload: {
            ...action.payload,
            attachmentOmissionReasons: attachmentResult.omissionReasons,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "preparing"),
          ),
        )
        .returning({ id: chatActions.id });
      if (issued.length !== 1)
        throw new Error("chat_inbound_wakeup_action_claim_lost");
    });
  }

  async function settleRejectedInboundWakeups(onlyDeliveryId?: string) {
    await db
      .update(chatActions)
      .set({
        status: "failed",
        result: { code: "inbound_wakeup_delivery_rejected" },
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(chatActions.kind, "inbound_wakeup"),
          eq(chatActions.status, "preparing"),
          onlyDeliveryId
            ? eq(chatActions.deliveryId, onlyDeliveryId)
            : undefined,
          sql`exists (select 1 from ${chatDeliveries}
            where ${chatDeliveries.id} = ${chatActions.deliveryId}
              and ${chatDeliveries.companyId} = ${chatActions.companyId}
              and ${chatDeliveries.endpointId} = ${chatActions.endpointId}
              and ${chatDeliveries.state} in ('filtered', 'failed'))`,
        ),
      );
  }

  async function processInboundWakeup(deliveryId: string): Promise<boolean> {
    const now = new Date();
    const candidate = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.deliveryId, deliveryId),
          eq(chatActions.kind, "inbound_wakeup"),
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (
      !candidate ||
      !["preparing", "issued", "processing"].includes(candidate.status)
    )
      return true;
    if (
      candidate.status === "preparing" ||
      (candidate.status === "processing" &&
        candidate.updatedAt.getTime() >
          now.getTime() - DELIVERY_PROCESSING_STALE_MS) ||
      (typeof candidate.result?.retryAt === "string" &&
        Date.parse(candidate.result.retryAt) > now.getTime())
    )
      return false;
    const claimed = await db
      .update(chatActions)
      .set({ status: "processing", updatedAt: now })
      .where(
        and(
          eq(chatActions.id, candidate.id),
          eq(chatActions.status, candidate.status),
          eq(chatActions.updatedAt, candidate.updatedAt),
        ),
      )
      .returning()
      .then((rows) => rows[0] ?? null);
    if (!claimed) return false;
    const attemptCount = Number(candidate.result?.attemptCount ?? 0) + 1;
    const receiptDeclined = (row: typeof agentWakeupRequests.$inferSelect) =>
      ["skipped", "cancelled", "failed"].includes(row.status);
    const settle = (status: string, result: Record<string, unknown>) =>
      db.transaction(async (tx) => {
        const changed = await tx
          .update(chatActions)
          .set({ status, result, updatedAt: new Date() })
          .where(
            and(
              eq(chatActions.id, claimed.id),
              eq(chatActions.status, "processing"),
              eq(chatActions.updatedAt, now),
            ),
          )
          .returning({ id: chatActions.id });
        if (changed.length && status === "failed") {
          await tx
            .update(chatDeliveries)
            .set({
              redactedError:
                result.code === "inbound_wakeup_authorization_changed"
                  ? "Input saved. Work was not scheduled because current chat access no longer permits it."
                  : "Input saved. Its work request was skipped, cancelled, or failed; no automatic replay was performed.",
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatDeliveries.id, deliveryId),
                eq(chatDeliveries.companyId, claimed.companyId),
                eq(chatDeliveries.state, "processed"),
              ),
            );
        }
      });
    let request: ReturnType<typeof createDurableChatWakeupRequest> | null =
      null;
    const receipt = async () => {
      const row = await db
        .select()
        .from(agentWakeupRequests)
        .where(eq(agentWakeupRequests.id, claimed.id))
        .limit(1)
        .then((rows) => rows[0] ?? null);
      if (row && request) assertDurableChatWakeupReceipt(request, row);
      return row;
    };
    try {
      if (
        claimed.payload.version !== 1 ||
        typeof claimed.payload.agentId !== "string" ||
        typeof claimed.payload.issueId !== "string" ||
        typeof claimed.payload.commentId !== "string" ||
        typeof claimed.payload.requestedByActorId !== "string" ||
        !["user", "system"].includes(
          String(claimed.payload.requestedByActorType),
        )
      ) {
        throw forbidden("Invalid durable inbound chat source", {
          code: "chat_action_authorization_changed",
        });
      }
      request = createDurableChatWakeupRequest({
        id: claimed.id,
        companyId: claimed.companyId,
        agentId: claimed.payload.agentId,
        issueId: claimed.payload.issueId,
        commentId: claimed.payload.commentId,
        requestedByActorType: claimed.payload.requestedByActorType as
          "user" | "system",
        requestedByActorId: String(claimed.payload.requestedByActorId),
        requestedAt: claimed.createdAt,
        authorize: async (tx) => {
          const current = await authorizeInboundWakeup(tx, claimed);
          if (current.delivery.state !== "processed")
            throw new Error("chat_inbound_wakeup_acceptance_not_committed");
        },
      });
      const priorReceipt = await receipt();
      if (priorReceipt) {
        await settle(receiptDeclined(priorReceipt) ? "failed" : "processed", {
          code: receiptDeclined(priorReceipt)
            ? `inbound_wakeup_${priorReceipt.status}`
            : "inbound_wakeup_already_durable",
          wakeupRequestId: priorReceipt.id,
          runId: priorReceipt.runId,
          receiptStatus: priorReceipt.status,
          attemptCount,
        });
        return true;
      }
      const context = await db.transaction((tx) =>
        authorizeInboundWakeup(tx, claimed),
      );
      if (context.delivery.state !== "processed")
        throw new Error("chat_inbound_wakeup_acceptance_not_committed");
      await queueIssueAssignmentWakeup({
        heartbeat: options.heartbeat,
        issue: context.issue,
        reason: "External chat message received",
        mutation: "chat_message_received",
        contextSource: `chat:${context.endpoint.provider}`,
        requestedByActorType: request.requestedByActorType,
        requestedByActorId: request.requestedByActorId,
        taskKey: context.issue.identifier,
        wakeCommentId: request.commentId,
        attachmentOmissionReasons: claimed.payload.attachmentOmissionReasons as
          Record<string, number> | undefined,
        durableChatRequest: request,
        rethrowOnError: true,
      });
      const durable = await receipt();
      if (!durable) throw new Error("chat_inbound_wakeup_receipt_missing");
      await settle(receiptDeclined(durable) ? "failed" : "processed", {
        code: receiptDeclined(durable)
          ? `inbound_wakeup_${durable.status}`
          : "inbound_wakeup_durable",
        wakeupRequestId: durable.id,
        runId: durable.runId,
        receiptStatus: durable.status,
        ...(durable.status === "skipped" ? { reason: durable.reason } : {}),
        attemptCount,
      });
      return true;
    } catch (error) {
      const conflictingReceipt =
        error instanceof Error &&
        error.message === "chat_inbound_wakeup_receipt_conflict";
      const durable = request && !conflictingReceipt ? await receipt() : null;
      if (durable) {
        await settle(receiptDeclined(durable) ? "failed" : "processed", {
          code: receiptDeclined(durable)
            ? `inbound_wakeup_${durable.status}`
            : "inbound_wakeup_already_durable",
          wakeupRequestId: durable.id,
          runId: durable.runId,
          receiptStatus: durable.status,
          attemptCount,
        });
        return true;
      }
      const denied =
        conflictingReceipt || isExternalActionAuthorizationChange(error);
      await settle(denied ? "failed" : "issued", {
        code: conflictingReceipt
          ? "inbound_wakeup_receipt_conflict"
          : denied
            ? "inbound_wakeup_authorization_changed"
            : "inbound_wakeup_retry",
        attemptCount,
        ...(!denied
          ? {
              retryAt: new Date(
                Date.now() +
                  Math.min(30_000, 1000 * 2 ** Math.min(attemptCount, 5)),
              ).toISOString(),
            }
          : {}),
      });
      if (!denied)
        logger.warn(
          { deliveryId, error: redactError(error) },
          "accepted inbound chat wakeup will retry",
        );
      return denied;
    }
  }


  async function processMessage(
    endpoint: EndpointRow,
    thread: Thread,
    message: Message,
    trigger: ChatSdkMessageCallbackEvent["trigger"],
    ingressOnly = false,
    recoveredProviderUrl: string | null = null,
    runtimeContext?: InboundRuntimeContext,
    providerUpdateId?: number,
    admittedDeliveryId: string | null = null,
    receiptReactionSupported = true,
    // Kept as a positional compatibility slot for already-normalized durable
    // deliveries. Authorization snapshots are intentionally ignored: task
    // mutation always rechecks current reach, identity link, and membership.
    _preauthorizedUserId?: string | null,
    deferDrainUntilFollowup = false,
    suppressSetupDestinationActivation = false,
    slackSlashControl = false,
  ) {
    if (
      endpoint.provider === "telegram" &&
      (telegramZeroMessageId(message.id) ||
        (message.raw !== null &&
          typeof message.raw === "object" &&
          (message.raw as { message_id?: unknown }).message_id === 0))
    )
      return;
    // The Telegram adapter currently emits edited_message through the normal
    // message callback with the original message id. Paperclip records that
    // verified payload through its supplemental message_updated lifecycle
    // ledger instead; letting it reach normal dedupe would falsely report the
    // edit as a duplicate provider delivery.
    if (
      endpoint.provider === "telegram" &&
      (isTelegramEditedMessageRaw(message.raw) ||
        isTelegramMigrationRaw(message.raw))
    )
      return;
    if (
      message.author.isMe ||
      message.author.isBot === true ||
      message.author.isSystem
    )
      return;
    // One provider message can match both a mention handler and the catch-all
    // new-message handler. The trigger is policy metadata, not provider event
    // identity, so it must not defeat durable deduplication.
    const providerEventId = `${durableExternalThreadIdentity(thread.id)}:${message.id}`;
    const surfaceKind = chatSurfaceKind(endpoint.provider, thread);
    const addressed =
      trigger === "mention" ||
      trigger === "direct_message" ||
      message.isMention === true;
    const eventKind: ChatEventKind =
      trigger === "direct_message"
        ? "direct_message"
        : trigger === "mention"
          ? "mention"
          : "message";
    // A callback remains tied to the runtime that authenticated and parsed it.
    // In particular, do not resolve the registry again here: pause or rotation
    // may already have removed that instance, and recreating a runtime before
    // the durable admission fence would either throw or bind old payload data
    // to new credentials.
    const endpointRuntime =
      runtimeContext?.endpointRuntime ?? (await runtimeFor(endpoint));
    // Non-personal generic files still require a separate Graph grant. Only
    // exact inline image resources from the authenticated original activity
    // receive a scope-bound, URL-free recovery locator. Reconstructed input
    // can retain that proof, but cannot mint one from legacy fetch metadata.
    const teamsNonPersonal =
      endpoint.provider === "microsoft-teams" && !thread.isDM;
    const attachmentSource = {
      threadId: thread.id,
      messageId: message.id,
      runtimeGeneration: runtimeContext?.generation,
      credentialFingerprint: runtimeContext?.credentialFingerprint,
      principalExternalId: stableExternalPrincipalId(
        endpoint.provider,
        message.author,
        message.raw,
      ),
      isDirectMessage: thread.isDM,
      ...(runtimeContext?.endpointRuntime && !admittedDeliveryId
        ? { message }
        : {}),
    };
    const inlineRecovery = new Map<
      Attachment,
      ReturnType<ChatSdkEndpointRuntime["attachmentRecoveryDescriptor"]>
    >();
    const nativeInboundAttachments = teamsNonPersonal
      ? message.attachments.slice(0, 20).flatMap((attachment) => {
          const descriptor = endpointRuntime.attachmentRecoveryDescriptor(
            attachment,
            attachmentSource,
          );
          if (descriptor?.locator.kind !== "teams_inline_image") return [];
          const restored = endpointRuntime.rehydrateAttachment(
            descriptor,
            attachmentSource,
          );
          if (!restored) return [];
          inlineRecovery.set(attachment, descriptor);
          return [restored];
        })
      : message.attachments;
    const unavailableTeamsReferences = teamsNonPersonal
      ? Math.min(message.attachments.length, 20) -
        nativeInboundAttachments.length
      : 0;
    const providerSentAt =
      endpoint.provider === "microsoft-teams"
        ? teamsActivitySentAt(message.raw)
        : endpoint.provider === "telegram"
          ? telegramMessageSentAt(message.raw)
          : endpoint.provider === "slack"
            ? slackMessageSentAt(message.raw, message.id)
          : message.metadata.dateSent instanceof Date &&
              Number.isFinite(message.metadata.dateSent.getTime())
            ? message.metadata.dateSent
            : null;
    const providerSentAtSource = providerSentAt
      ? endpoint.provider === "microsoft-teams"
        ? "teams_activity_timestamp"
        : endpoint.provider === "telegram"
          ? "telegram_message_date"
          : endpoint.provider === "slack"
            ? "slack_message_ts"
          : null
      : null;
    const providerUrl =
      chatProviderConversationUrl({
        provider: endpoint.provider,
        providerAccountId: endpoint.providerAccountId,
        botUsername: endpoint.botUsername,
        threadId: thread.id,
        providerMessageId: message.id,
        raw: message.raw,
      }) ?? recoveredProviderUrl;
    // Preserve only the closed personal-recipient proof from the runtime that
    // authenticated this original activity. A reconstructed delivery's AAD-only
    // author and SDK route caches cannot recreate its Bot Framework recipient.
    const teamsPersonalRecipient =
      endpoint.provider === "microsoft-teams" &&
      runtimeContext?.endpointRuntime &&
      !admittedDeliveryId &&
      endpoint.providerAccountId &&
      endpoint.botExternalId
        ? deriveTeamsPersonalRecipient(message, {
            companyId: endpoint.companyId,
            endpointId: endpoint.id,
            runtimeGeneration: runtimeContext.generation,
            credentialFingerprint: runtimeContext.credentialFingerprint,
            tenantId: endpoint.providerAccountId,
            botAppId: endpoint.botExternalId,
            providerEventId,
            threadId: thread.id,
            isDirectMessage: thread.isDM,
          })
        : null;
    const normalized = {
      providerEventId,
      kind: eventKind,
      trigger,
      ...(teamsPersonalRecipient ? { teamsPersonalRecipient } : {}),
      ...(slackSlashControl ? { admission: { origin: "slack_slash_control" } } : suppressSetupDestinationActivation
        ? // A slash-command root is provider-confirmed only after an enabled
          // destination authorized its transport. Persist that closed origin so
          // crash recovery can never reinterpret it as first-time setup traffic
          // and undo a later operator reach revocation.
          { admission: { origin: "provider_confirmed_action" } }
        : {}),
      ...(runtimeContext
        ? {
            runtimeContext: {
              credentialFingerprint: runtimeContext.credentialFingerprint,
              generation: runtimeContext.generation,
            },
          }
        : {}),
      acknowledgement: {
        // Some provider callbacks represent an auditable user command without
        // a provider message that can receive a reaction. Persist the
        // distinction so a crash/retry cannot mistake the synthetic ledger id
        // for a native message id.
        receiptReactionSupported,
      },
      principal: {
        externalId: stableExternalPrincipalId(
          endpoint.provider,
          message.author,
          message.raw,
        ),
        displayName: message.author.fullName,
        handle: message.author.userName,
      },
      resource: {
        type: providerResourceType(endpoint.provider, surfaceKind),
        providerResourceId: canonicalProviderResourceId(
          endpoint.provider,
          thread,
        ),
        label: thread.channel.name ?? thread.channelId,
      },
      conversation: {
        externalConversationId: thread.channelId,
        externalThreadId: thread.id,
        label: thread.channel.name ?? thread.channelId,
        isDirectMessage: thread.isDM,
        providerUrl,
      },
      message: {
        providerMessageId: message.id,
        providerMessageSequence:
          endpoint.provider === "telegram"
            ? telegramMessageSequence(message.raw)
            : null,
        providerUpdateId:
          endpoint.provider === "telegram" ? (providerUpdateId ?? null) : null,
        text: message.text.slice(0, MAX_INBOUND_TEXT),
        mentionedBot: message.isMention === true,
        providerSentAt: providerSentAt?.toISOString() ?? null,
        ...(providerSentAtSource ? { providerSentAtSource } : {}),
        ...(endpoint.provider === "github" &&
        githubAttachmentLimitOmissions(message)
          ? {
              attachmentLimitOmissions: githubAttachmentLimitOmissions(message),
            }
          : {}),
        attachments: message.attachments.slice(0, 20).map((attachment) => ({
          name: sanitizeFilename(attachment.name),
          mimeType: normalizeContentType(attachment.mimeType),
          size: attachment.size ?? null,
          recovery: teamsNonPersonal
            ? (inlineRecovery.get(attachment) ?? null)
            : nativeInboundAttachments.includes(attachment)
              ? endpointRuntime.attachmentRecoveryDescriptor(
                  attachment,
                  endpoint.provider === "telegram"
                    ? attachmentSource
                    : undefined,
                )
              : null,
        })),
      },
    };
    // Teams RSC can deliver messages from every installed channel, and a
    // Telegram bot can receive addressed traffic from a provider-available
    // group that the operator has not enabled in Paperclip. Until the reach
    // gate admits that destination, retain only identifiers required for
    // deduplication and operator-visible filtering—not user text, attachment
    // metadata, or an external principal profile.
    const redactedDestinationNormalized = {
      providerEventId,
      kind: eventKind,
      trigger,
      ...(runtimeContext
        ? {
            runtimeContext: {
              credentialFingerprint: runtimeContext.credentialFingerprint,
              generation: runtimeContext.generation,
            },
          }
        : {}),
      resource: {
        type: providerResourceType(endpoint.provider, surfaceKind),
        providerResourceId: canonicalProviderResourceId(
          endpoint.provider,
          thread,
        ),
      },
      conversation: { externalThreadId: thread.id },
      message: {
        providerMessageId: message.id,
        providerSentAt: providerSentAt?.toISOString() ?? null,
      },
      filtering: { contentRetained: false },
    };
    const reorderWindow = INGRESS_REORDER_WINDOW_MS[endpoint.provider];
    const scheduledAt =
      ingressOnly && reorderWindow
        ? (scheduledConversationDrains.get(
            conversationDrainKey(endpoint.id, thread.id),
          ) ?? Date.now() + reorderWindow)
        : null;
    const discordGatewayAdmissionState: {
      lost?: DiscordGatewayOwnership;
      renewed?: {
        expiresAt: Date;
        ownership: DiscordGatewayOwnership;
      };
    } = {};
    const admission = await db.transaction(async (tx) => {
      const currentEndpoint = await tx
        .select({
          status: chatEndpoints.status,
          setup: chatEndpoints.setup,
          allowDirectMessages: chatEndpoints.allowDirectMessages,
          allowGroupChats: chatEndpoints.allowGroupChats,
        })
        .from(chatEndpoints)
        .where(eq(chatEndpoints.id, endpoint.id))
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!currentEndpoint) return null;
      // An SDK callback can finish parsing after a pause/resume cycle. Each
      // runtime captures the durable endpoint generation at registration;
      // resume advances it under the same row lock used by admission. This
      // rejects stale callbacks without relying on provider/server clock sync.
      const currentRuntimeGeneration = runtimeGeneration(currentEndpoint.setup);
      const currentCredentialFingerprint = runtimeContext
        ? await tx
            .select({ refs: toolConnections.credentialSecretRefs })
            .from(toolConnections)
            .where(
              and(
                eq(toolConnections.companyId, endpoint.companyId),
                eq(toolConnections.id, endpoint.connectionId),
              ),
            )
            .then((rows) => credentialFingerprint(rows[0]?.refs ?? []))
        : null;
      const staleActivation =
        runtimeContext !== undefined &&
        (runtimeContext.generation !== currentRuntimeGeneration ||
          runtimeContext.credentialFingerprint !==
            currentCredentialFingerprint);
      const endpointAccepting =
        ["verifying", "active"].includes(currentEndpoint.status) &&
        !staleActivation;
      if (
        endpointAccepting &&
        endpoint.provider === "discord" &&
        runtimeContext &&
        !admittedDeliveryId
      ) {
        // The first process-local ownership check can precede a host pause.
        // Reclaim the same durable token while the endpoint admission row is
        // locked so a standby takeover cannot be followed by an obsolete
        // callback write. This renews only the exact token that authenticated
        // the callback; generation and credential checks above remain intact.
        const gatewayOwnership =
          await renewDiscordGatewayOwnershipForMessageAdmission(
            tx,
            endpoint.id,
            runtimeContext,
          );
        if (gatewayOwnership.kind === "lost") {
          if (gatewayOwnership.ownership) {
            discordGatewayAdmissionState.lost = gatewayOwnership.ownership;
          }
          return null;
        }
        discordGatewayAdmissionState.renewed = gatewayOwnership;
      }
      let provisionalTeamsSetupReply = false;
      let destinationAccepting = true;
      if (endpointAccepting && thread.isDM) {
        destinationAccepting = currentEndpoint.allowDirectMessages;
      }
      if (
        endpointAccepting &&
        endpoint.provider === "microsoft-teams" &&
        !thread.isDM
      ) {
        let resource = await ensureResource(endpoint, thread, false, tx);
        const enabledChannelCount = await tx
          .select({ count: sql<number>`count(*)::int` })
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.endpointId, endpoint.id),
              eq(chatEndpointResources.enabled, true),
              eq(chatEndpointResources.availability, "available"),
              eq(chatEndpointResources.type, "channel"),
            ),
          )
          .then((rows) => rows[0]?.count ?? 0);
        const canActivateFirstSetupChannel =
          currentEndpoint.status === "verifying" &&
          resource.type === "channel" &&
          resource.availability === "available" &&
          enabledChannelCount === 0 &&
          addressed;
        if (canActivateFirstSetupChannel && !resource.enabled) {
          resource = await tx
            .update(chatEndpointResources)
            .set({ enabled: true, updatedAt: new Date() })
            .where(eq(chatEndpointResources.id, resource.id))
            .returning()
            .then((rows) => rows[0] ?? resource);
        }
        const teamsRootMessageId = teamsThreadRootMessageId(thread.id);
        provisionalTeamsSetupReply =
          currentEndpoint.status === "verifying" &&
          resource.type === "channel" &&
          resource.availability === "available" &&
          enabledChannelCount === 0 &&
          !addressed &&
          Boolean(teamsRootMessageId) &&
          teamsRootMessageId !== message.id;
        destinationAccepting =
          nonDirectDestinationAllowed(
            { ...endpoint, allowGroupChats: currentEndpoint.allowGroupChats },
            resource,
          ) || provisionalTeamsSetupReply;
      }
      if (
        endpointAccepting &&
        endpoint.provider === "telegram" &&
        !thread.isDM
      ) {
        let resource = await ensureResource(endpoint, thread, false, tx);
        const enabledResourceCount = await tx
          .select({ count: sql<number>`count(*)::int` })
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.endpointId, endpoint.id),
              eq(chatEndpointResources.enabled, true),
              eq(chatEndpointResources.availability, "available"),
              ne(chatEndpointResources.type, "direct_message"),
              ne(chatEndpointResources.type, "group_chat"),
            ),
          )
          .then((rows) => rows[0]?.count ?? 0);
        const canActivateFirstSetupGroup =
          currentEndpoint.status === "verifying" &&
          resource.availability === "available" &&
          enabledResourceCount === 0 &&
          addressed;
        if (canActivateFirstSetupGroup && !resource.enabled) {
          resource = await tx
            .update(chatEndpointResources)
            .set({ enabled: true, updatedAt: new Date() })
            .where(eq(chatEndpointResources.id, resource.id))
            .returning()
            .then((rows) => rows[0] ?? resource);
        }
        // Telegram's privacy-mode contract is explicit: in a group or forum
        // topic, every admitted turn must address the bot. A direct reply to a
        // bot message is normalized as a mention by the pinned adapter, while
        // unrelated subscribed traffic remains unaddressed and is filtered.
        destinationAccepting =
          addressed &&
          nonDirectDestinationAllowed(
            { ...endpoint, allowGroupChats: currentEndpoint.allowGroupChats },
            resource,
          );
      }
      const accepting = endpointAccepting && destinationAccepting;
      const redactDestinationDelivery =
        (!accepting && thread.isDM) ||
        (!thread.isDM &&
          (endpoint.provider === "microsoft-teams" ||
            endpoint.provider === "telegram") &&
          (!accepting || provisionalTeamsSetupReply));
      const ignoredAt = accepting ? null : new Date();
      const inactiveReason = !endpointAccepting
        ? staleActivation
          ? "Connection activation changed before admission"
          : "Connection is not active"
        : endpoint.provider === "telegram" && !thread.isDM && !addressed
          ? "Message did not address the agent"
          : "Destination is not enabled in Paperclip";
      let candidate = admittedDeliveryId
        ? await tx
            .select()
            .from(chatDeliveries)
            .where(
              and(
                eq(chatDeliveries.id, admittedDeliveryId),
                eq(chatDeliveries.endpointId, endpoint.id),
                eq(chatDeliveries.providerEventId, providerEventId),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;
      if (!admittedDeliveryId) {
        const [delivery] = await tx
          .insert(chatDeliveries)
          .values({
            companyId: endpoint.companyId,
            endpointId: endpoint.id,
            providerEventId,
            deduplicationKey: createHash("sha256")
              .update(providerEventId)
              .digest("hex"),
            eventKind,
            normalizedEvent: redactDestinationDelivery
              ? redactedDestinationNormalized
              : deferDrainUntilFollowup && accepting
                ? {
                    ...normalized,
                    providerThreadPending: true,
                  }
                : normalized,
            state: accepting
              ? deferDrainUntilFollowup
                ? "retry"
                : "received"
              : "filtered",
            nextAttemptAt:
              accepting && deferDrainUntilFollowup
                ? new Date(
                    Date.now() + DISCORD_ROOT_THREAD_CONFIRMATION_DELAY_MS,
                  )
                : accepting && scheduledAt
                  ? new Date(scheduledAt)
                  : null,
            redactedError:
              accepting && deferDrainUntilFollowup
                ? "Waiting for Discord thread creation confirmation"
                : accepting
                  ? null
                  : inactiveReason,
            processedAt: ignoredAt,
          })
          .onConflictDoNothing()
          .returning();
        candidate = delivery ?? null;
      }
      if (!candidate && !admittedDeliveryId) {
        const existingDelivery = await tx
          .select()
          .from(chatDeliveries)
          .where(
            and(
              eq(chatDeliveries.endpointId, endpoint.id),
              eq(chatDeliveries.providerEventId, providerEventId),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (existingDelivery) {
          const hydrateTeamsDelivery =
            endpoint.provider === "microsoft-teams" &&
            !thread.isDM &&
            accepting &&
            !provisionalTeamsSetupReply &&
            ["received", "retry", "processing"].includes(
              existingDelivery.state,
            ) &&
            deliveryContentWasRedacted(existingDelivery.normalizedEvent);
          [candidate] = await tx
            .update(chatDeliveries)
            .set({
              // Increment under PostgreSQL's row lock so simultaneous handler
              // fanout and provider retries cannot lose duplicate telemetry.
              normalizedEvent: redactDestinationDelivery
                ? sql`${JSON.stringify(redactedDestinationNormalized)}::jsonb
                    || jsonb_build_object(
                      'deduplication',
                      jsonb_build_object(
                        'duplicateCount',
                        coalesce((${chatDeliveries.normalizedEvent}#>>'{deduplication,duplicateCount}')::integer, 0) + 1,
                        'lastDuplicateAt',
                        ${new Date().toISOString()}::text
                      )
                    )`
                : hydrateTeamsDelivery
                  ? sql`${JSON.stringify(normalized)}::jsonb
                    || jsonb_build_object(
                      'deduplication',
                      coalesce(${chatDeliveries.normalizedEvent}->'deduplication', '{}'::jsonb)
                        || jsonb_build_object(
                          'duplicateCount',
                          coalesce((${chatDeliveries.normalizedEvent}#>>'{deduplication,duplicateCount}')::integer, 0) + 1,
                          'lastDuplicateAt',
                          ${new Date().toISOString()}::text
                        )
                    )`
                  : sql`coalesce(${chatDeliveries.normalizedEvent}, '{}'::jsonb)
                    || jsonb_build_object(
                      'deduplication',
                      coalesce(${chatDeliveries.normalizedEvent}->'deduplication', '{}'::jsonb)
                        || jsonb_build_object(
                          'duplicateCount',
                          coalesce((${chatDeliveries.normalizedEvent}#>>'{deduplication,duplicateCount}')::integer, 0) + 1,
                          'lastDuplicateAt',
                          ${new Date().toISOString()}::text
                        )
                    )`,
              ...(!accepting &&
              ["received", "retry"].includes(existingDelivery.state)
                ? {
                    state: "filtered" as const,
                    nextAttemptAt: null,
                    redactedError: inactiveReason,
                    processedAt: ignoredAt,
                  }
                : {}),
              updatedAt: new Date(),
            })
            .where(eq(chatDeliveries.id, existingDelivery.id))
            .returning();
        }
      }
      if (
        candidate &&
        admittedDeliveryId &&
        accepting &&
        !provisionalTeamsSetupReply &&
        endpoint.provider === "microsoft-teams" &&
        !thread.isDM &&
        ["received", "retry", "processing"].includes(candidate.state) &&
        deliveryContentWasRedacted(candidate.normalizedEvent)
      ) {
        [candidate] = await tx
          .update(chatDeliveries)
          .set({ normalizedEvent: normalized, updatedAt: new Date() })
          .where(eq(chatDeliveries.id, candidate.id))
          .returning();
      }
      if (
        candidate &&
        admittedDeliveryId &&
        !accepting &&
        ["received", "retry", "processing"].includes(candidate.state)
      ) {
        [candidate] = await tx
          .update(chatDeliveries)
          .set({
            state: "filtered",
            ...(redactDestinationDelivery
              ? {
                  normalizedEvent: redactedDestinationNormalized,
                  principalId: null,
                }
              : {}),
            nextAttemptAt: null,
            redactedError: inactiveReason,
            processedAt: ignoredAt,
            updatedAt: new Date(),
          })
          .where(eq(chatDeliveries.id, candidate.id))
          .returning();
      }
      if (!accepting && ignoredAt) {
        await tx
          .update(chatEndpoints)
          .set({ lastEventAt: ignoredAt, updatedAt: ignoredAt })
          .where(eq(chatEndpoints.id, endpoint.id));
      }
      return {
        accepting,
        candidate: candidate ?? null,
        provisionalTeamsSetupReply,
      };
    });
    // The database token is authoritative. Publish its new expiry to the
    // process-local fast path only after the admission transaction commits.
    // Conversely, synchronously fence an obsolete local owner after a failed
    // token CAS, then stop it without awaiting the callback it may be serving.
    const renewedDiscordOwnership = discordGatewayAdmissionState.renewed;
    if (
      renewedDiscordOwnership &&
      discordGatewayOwnerships.get(endpoint.id) ===
        renewedDiscordOwnership.ownership &&
      !renewedDiscordOwnership.ownership.stopping
    ) {
      renewedDiscordOwnership.ownership.expiresAt =
        renewedDiscordOwnership.expiresAt;
    }
    const lostDiscordOwnership = discordGatewayAdmissionState.lost;
    if (
      lostDiscordOwnership &&
      discordGatewayOwnerships.get(endpoint.id) === lostDiscordOwnership
    ) {
      lostDiscordOwnership.stopping = true;
      void stopDiscordGatewayOwnership(lostDiscordOwnership);
    }
    if (!admittedDeliveryId && admission?.candidate) {
      recordChatWebhookReceipt(
        endpoint.id,
        admission.candidate.id,
        "message_delivery",
        providerSentAt,
      );
    }
    if (admission?.accepting) {
      // Persist the latest authenticated Teams reply route under a fresh
      // runtime/credential fence. The helper holds the endpoint's NO KEY
      // UPDATE lock through the SDK-state write, so reconnect, pause, and
      // credential rotation cannot overtake it while the state table's
      // foreign-key check remains deadlock-free. A failed write escapes so
      // Teams retries the already-idempotent delivery.
      await recordCurrentMicrosoftTeamsRoute(
        endpoint,
        runtimeContext,
        thread.id,
        message.raw,
      );
    }
    let candidate = admission?.candidate ?? null;
    if (!admission || !candidate) return;
    if (!admission.accepting) {
      liveInboundMessages.delete(candidate.id);
      return;
    }
    if (["processed", "filtered", "failed"].includes(candidate.state)) return;
    if (
      !deferDrainUntilFollowup &&
      endpoint.provider === "discord" &&
      discordRootThreadPending(candidate)
    ) {
      // The adapter invokes the ordinary message callback only after Discord
      // has returned the created thread. Promote the pre-admission receipt
      // atomically so the normal ordered drain can begin immediately.
      const [promoted] = await db
        .update(chatDeliveries)
        .set({
          state: "received",
          normalizedEvent: sql`${chatDeliveries.normalizedEvent} - 'providerThreadPending'`,
          nextAttemptAt: scheduledAt ? new Date(scheduledAt) : null,
          redactedError: null,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, candidate.id),
            eq(chatDeliveries.state, "retry"),
            sql`${chatDeliveries.normalizedEvent}->>'providerThreadPending' = 'true'`,
          ),
        )
        .returning();
      if (promoted) candidate = promoted;
    }
    const now = new Date();
    if (
      !deferDrainUntilFollowup &&
      candidate.state === "retry" &&
      candidate.nextAttemptAt &&
      candidate.nextAttemptAt > now
    )
      return;
    const staleBefore = new Date(now.getTime() - DELIVERY_PROCESSING_STALE_MS);
    if (candidate.state === "processing" && candidate.updatedAt > staleBefore)
      return;
    if (ingressOnly) {
      // The verified provider request owns only the durable ingress write.
      // Task mutation, attachment download, wakeup, and provider-visible
      // acknowledgement continue under a durable conversation lease after the
      // HTTP response. Keeping the original SDK objects process-locally lets
      // the first attempt retain attachment download handles; another process
      // can still reconstruct the delivery solely from the durable ledger.
      liveInboundMessages.set(candidate.id, {
        endpoint,
        thread,
        message,
        trigger,
        receiptReactionSupported,
        runtimeContext,
      });
      if (!deferDrainUntilFollowup) {
        scheduleConversationDrain(
          endpoint.id,
          thread.id,
          scheduledAt ?? Date.now(),
        );
      }
      return;
    }
    const claimConditions = [
      eq(chatDeliveries.id, candidate.id),
      eq(chatDeliveries.state, candidate.state),
    ];
    if (candidate.state === "processing")
      claimConditions.push(lte(chatDeliveries.updatedAt, staleBefore));
    const claimed = await db
      .update(chatDeliveries)
      .set({
        state: "processing",
        attempts: candidate.attempts + 1,
        nextAttemptAt: null,
        redactedError: null,
        updatedAt: now,
      })
      .where(and(...claimConditions))
      .returning();
    const activeDelivery = claimed[0];
    if (!activeDelivery) return;

    try {
      if (admission.provisionalTeamsSetupReply) {
        const resolutionAt = new Date();
        const waitForSetupRoot =
          activeDelivery.attempts <= ORPHAN_FOLLOW_UP_MAX_ATTEMPTS;
        await db
          .update(chatDeliveries)
          .set(
            waitForSetupRoot
              ? {
                  state: "retry",
                  nextAttemptAt: new Date(
                    resolutionAt.getTime() + ORPHAN_FOLLOW_UP_GRACE_MS,
                  ),
                  redactedError: "Waiting briefly for an earlier root mention",
                  updatedAt: resolutionAt,
                }
              : {
                  state: "filtered",
                  normalizedEvent: redactedDestinationNormalized,
                  principalId: null,
                  nextAttemptAt: null,
                  processedAt: resolutionAt,
                  redactedError: "Destination is not enabled in Paperclip",
                  updatedAt: resolutionAt,
                },
          )
          .where(eq(chatDeliveries.id, activeDelivery.id));
        return;
      }
      // A committed inbound message link proves that a prior attempt completed
      // its task mutation even if it crashed before returning to the provider.
      const existingMessageLink = await db
        .select({
          id: chatMessageLinks.id,
          conversationId: chatMessageLinks.conversationId,
          commentId: chatMessageLinks.commentId,
        })
        .from(chatMessageLinks)
        .where(
          and(
            eq(chatMessageLinks.endpointId, endpoint.id),
            eq(chatMessageLinks.deliveryId, activeDelivery.id),
            eq(chatMessageLinks.direction, "inbound"),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (existingMessageLink) {
        const inboundCommentId = existingMessageLink.commentId;
        if (!inboundCommentId) {
          throw new Error("Inbound message link is missing its task comment");
        }
        const rebound = await db
          .select({
            conversation: chatConversations,
            issueId: chatConversations.issueId,
            resourceId: chatConversations.resourceId,
            assigneeAgentId: issues.assigneeAgentId,
            issueStatus: issues.status,
            issueIdentifier: issues.identifier,
            authorUserId: issueComments.authorUserId,
          })
          .from(chatConversations)
          .innerJoin(
            issues,
            and(
              eq(issues.companyId, chatConversations.companyId),
              eq(issues.id, chatConversations.issueId),
            ),
          )
          .leftJoin(issueComments, eq(issueComments.id, inboundCommentId))
          .where(
            and(
              eq(chatConversations.id, existingMessageLink.conversationId),
              eq(chatConversations.endpointId, endpoint.id),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (!rebound) throw notFound("Bound task not found");
        if (!activeDelivery.principalId)
          throw new Error("chat_inbound_wakeup_principal_missing");
        await stageInboundWakeup(db, {
          endpoint,
          deliveryId: activeDelivery.id,
          conversation: rebound.conversation,
          commentId: inboundCommentId,
          principalId: activeDelivery.principalId,
          actorUserId: rebound.authorUserId,
        });
        // Attachment storage follows the atomic task/comment/link mutation.
        // If a later wakeup or provider subscription failed, retry from the
        // committed delivery link and fill in only files that are still
        // missing from this exact inbound comment.
        const attachmentResult = await ingestAttachments({
          endpoint,
          endpointRuntime,
          deliveryId: activeDelivery.id,
          issueId: rebound.issueId,
          issueCommentId: inboundCommentId,
          attachments: nativeInboundAttachments,
          attachmentLimitOmissions: githubAttachmentLimitOmissions(message),
          unavailableReferenceCount: unavailableTeamsReferences,
          actorUserId: rebound.authorUserId,
        });
        if (
          await settleTelegramAttachmentOnlyFailure({
            activeDelivery,
            attachmentResult,
            commentId: inboundCommentId,
            conversationId: existingMessageLink.conversationId,
            endpoint,
            message,
            principalId: activeDelivery.principalId,
            resourceId: rebound.resourceId,
            runtimeContext,
            thread,
          })
        ) {
          return;
        }
        // Subscription is part of the durable acceptance boundary. If it
        // fails, keep the delivery retryable; the committed message link makes
        // the retry resume here without duplicating the task or comment.
        if (addressed && !thread.isDM) await thread.subscribe();
        await acceptInboundWakeup(activeDelivery.id, attachmentResult);
        if (!(await processInboundWakeup(activeDelivery.id))) return;
        const acceptedWake = await db
          .select({ status: chatActions.status })
          .from(chatActions)
          .where(
            and(
              eq(chatActions.deliveryId, activeDelivery.id),
              eq(chatActions.kind, "inbound_wakeup"),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null);
        if (acceptedWake?.status !== "processed") return;
        // Recover the visible receipt as well as the durable wake. The
        // receipt action is idempotent and resolves the current runtime fence.
        await Promise.allSettled([
          receiptReactionSupported
            ? addReceiptReaction({
                deliveryId: activeDelivery.id,
                endpoint,
                message,
                runtimeContext,
                thread,
              })
            : Promise.resolve(),
          endpoint.provider === "slack"
            ? Promise.resolve()
            : thread.startTyping("Working…"),
        ]);
        return;
      }

      const principalResolution = await ensurePrincipal(
        endpoint,
        message.author,
        message.raw,
      );
      const mayEnableSetupDestination =
        !thread.isDM &&
        endpoint.status === "verifying" &&
        addressed &&
        !suppressSetupDestinationActivation &&
        !(
          endpoint.provider === "microsoft-teams" &&
          surfaceKind === "linear_group"
        );
      const resourceAdmission = mayEnableSetupDestination
        ? await db.transaction(async (tx) => {
            const currentEndpoint = await tx
              .select({ status: chatEndpoints.status })
              .from(chatEndpoints)
              .where(eq(chatEndpoints.id, endpoint.id))
              .for("update")
              .then((rows) => rows[0] ?? null);
            if (!currentEndpoint) throw notFound("Chat endpoint not found");
            const enabledResourceCount = await tx
              .select({ count: sql<number>`count(*)::int` })
              .from(chatEndpointResources)
              .where(
                and(
                  eq(chatEndpointResources.endpointId, endpoint.id),
                  eq(chatEndpointResources.enabled, true),
                  eq(chatEndpointResources.availability, "available"),
                  ne(chatEndpointResources.type, "direct_message"),
                  ne(chatEndpointResources.type, "group_chat"),
                ),
              )
              .then((rows) => rows[0]?.count ?? 0);
            const enableSetupDestination =
              currentEndpoint.status === "verifying" &&
              enabledResourceCount === 0;
            let resource = await ensureResource(
              endpoint,
              thread,
              enableSetupDestination,
              tx,
            );
            if (enableSetupDestination && !resource.enabled) {
              resource = await tx
                .update(chatEndpointResources)
                .set({ enabled: true, updatedAt: new Date() })
                .where(eq(chatEndpointResources.id, resource.id))
                .returning()
                .then((rows) => rows[0] ?? resource);
            }
            return { enabledResourceCount, resource };
          })
        : {
            enabledResourceCount: await db
              .select({ count: sql<number>`count(*)::int` })
              .from(chatEndpointResources)
              .where(
                and(
                  eq(chatEndpointResources.endpointId, endpoint.id),
                  eq(chatEndpointResources.enabled, true),
                  eq(chatEndpointResources.availability, "available"),
                  ne(chatEndpointResources.type, "direct_message"),
                  ne(chatEndpointResources.type, "group_chat"),
                ),
              )
              .then((rows) => rows[0]?.count ?? 0),
            resource: await ensureResource(endpoint, thread, false),
          };
      const { enabledResourceCount, resource } = resourceAdmission;
      await db
        .update(chatDeliveries)
        .set({
          principalId: principalResolution.principal.id,
          updatedAt: new Date(),
        })
        .where(eq(chatDeliveries.id, activeDelivery.id));

      const latestConversation =
        endpoint.provider === "microsoft-teams"
          ? await conversationForThread(endpoint.id, thread.id)
          : await db
              .select()
              .from(chatConversations)
              .where(
                and(
                  eq(chatConversations.endpointId, endpoint.id),
                  eq(
                    chatConversations.externalConversationId,
                    thread.channelId,
                  ),
                  eq(chatConversations.externalThreadId, thread.id),
                ),
              )
              .orderBy(desc(chatConversations.sessionGeneration))
              .then((rows) => rows[0] ?? null);
      const isLinear = surfaceKind !== "native_thread";
      let existingConversation: ConversationRow | null = latestConversation;
      let existingIssue: typeof issues.$inferSelect | null =
        existingConversation
          ? await db
              .select()
              .from(issues)
              .where(
                and(
                  eq(issues.companyId, endpoint.companyId),
                  eq(issues.id, existingConversation.issueId),
                ),
              )
              .then((rows) => rows[0] ?? null)
          : null;
      if (
        isLinear &&
        existingConversation &&
        (existingConversation.state === "completed" ||
          existingIssue?.status === "done" ||
          existingIssue?.status === "cancelled")
      ) {
        if (existingConversation.state !== "completed") {
          await db
            .update(chatConversations)
            .set({ state: "completed", updatedAt: new Date() })
            .where(eq(chatConversations.id, existingConversation.id));
        }
        existingConversation = null;
        existingIssue = null;
      }
      // Telegram exposes its small command vocabulary in forum topics too.
      // A forum topic is a native provider thread and therefore stays bound to
      // one immutable Paperclip task, but the command must still be consumed
      // as control-plane input instead of becoming a task comment/wakeup.
      const controlCommand =
        isLinear || endpoint.provider === "telegram"
          ? linearControlCommand(message.text)
          : null;
      const guidanceCommand =
        endpoint.provider === "telegram"
          ? telegramGuidanceCommand(message.text)
          : null;
      const endpointAllowed =
        endpoint.status === "verifying" || endpoint.status === "active";
      const destinationAllowed = thread.isDM
        ? endpoint.allowDirectMessages
        : nonDirectDestinationAllowed(endpoint, resource);
      const guestSponsorAllowed =
        principalResolution.userId === null &&
        !principalResolution.linkedDenied &&
        endpoint.allowUnlinkedPeople
          ? await sponsorAllowsGuest(endpoint)
          : false;
      const principalAllowed =
        !principalResolution.linkedDenied &&
        (principalResolution.userId !== null || guestSponsorAllowed);
      const activationAllowed = addressed || existingConversation !== null;
      const allowed =
        endpointAllowed &&
        destinationAllowed &&
        principalAllowed &&
        activationAllowed;
      const slackRootMessageId =
        endpoint.provider === "slack"
          ? /^slack:[^:]+:(.+)$/.exec(thread.id)?.[1]
          : null;
      const teamsRootMessageId =
        endpoint.provider === "microsoft-teams"
          ? teamsThreadRootMessageId(thread.id)
          : null;
      const isPlausibleOrphanFollowUp =
        endpoint.provider === "github" ||
        endpoint.provider === "discord" ||
        (endpoint.provider === "slack" &&
          Boolean(slackRootMessageId) &&
          slackRootMessageId !== message.id) ||
        (endpoint.provider === "microsoft-teams" &&
          Boolean(teamsRootMessageId) &&
          teamsRootMessageId !== message.id);
      const setupDestinationCanBeEnabledByEarlierMention =
        (endpoint.provider === "github" ||
          endpoint.provider === "discord" ||
          (endpoint.provider === "microsoft-teams" &&
            resource?.type === "channel")) &&
        !thread.isDM &&
        endpoint.status === "verifying" &&
        enabledResourceCount === 0 &&
        resource.availability === "available";
      if (
        !allowed &&
        isPlausibleOrphanFollowUp &&
        !addressed &&
        existingConversation === null &&
        activeDelivery.attempts <= ORPHAN_FOLLOW_UP_MAX_ATTEMPTS &&
        endpointAllowed &&
        principalAllowed &&
        (destinationAllowed || setupDestinationCanBeEnabledByEarlierMention)
      ) {
        // GitHub, Slack, and Teams can deliver a thread reply before the older
        // root callback that creates its Paperclip task. Keep this exact
        // delivery for a bounded minute, without admitting or waking it, so
        // the durable thread drain can sort again if a delayed root arrives.
        // A standalone unaddressed message is filtered after the bounded
        // retention window.
        await db
          .update(chatDeliveries)
          .set({
            state: "retry",
            nextAttemptAt: new Date(Date.now() + ORPHAN_FOLLOW_UP_GRACE_MS),
            redactedError: "Waiting briefly for an earlier root mention",
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatDeliveries.id, activeDelivery.id),
              eq(chatDeliveries.state, "processing"),
            ),
          );
        return;
      }
      if (!allowed) {
        const filteredReason = !endpointAllowed
          ? "Connection is not active"
          : !destinationAllowed
            ? "Destination is not enabled in Paperclip"
            : principalResolution.linkedDenied
              ? "Linked Paperclip account is not currently permitted"
              : !principalAllowed
                ? endpoint.allowUnlinkedPeople
                  ? "Endpoint sponsor can no longer authorize external guests"
                  : "External identity must be linked to a Paperclip account"
                : "Message did not address the agent or an active task thread";
        await db
          .update(chatDeliveries)
          .set({
            state: "filtered",
            normalizedEvent: redactedDestinationNormalized,
            principalId: null,
            nextAttemptAt: null,
            redactedError: filteredReason,
            processedAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(chatDeliveries.id, activeDelivery.id));
        return;
      }

      const filterPreControlSource = async (database: DbOrTransaction) => {
        if (controlCommand === "status" || (controlCommand === "new" && endpoint.provider === "telegram" && surfaceKind === "native_thread") || guidanceCommand || (await readChatControlChronology(database, endpoint, thread, activeDelivery)) !== "before_or_unproven") return false;
        const filteredAt = new Date();
        await database.update(chatDeliveries).set({
          state: "filtered",
          nextAttemptAt: null,
          processedAt: filteredAt,
          updatedAt: filteredAt,
          redactedError: "Message predates or cannot be ordered after a completed chat close/new. Send a new request to start work.",
        }).where(and(eq(chatDeliveries.id, activeDelivery.id), eq(chatDeliveries.companyId, endpoint.companyId), eq(chatDeliveries.state, "processing")));
        return true;
      };
      if (await filterPreControlSource(db)) return;

      const emptySlackMention =
        endpoint.provider === "slack" &&
        (trigger === "mention" || message.isMention === true) &&
        message.attachments.length === 0 &&
        !hasMeaningfulSlackMentionRequest(message.text);
      if (emptySlackMention) {
        const effectContext =
          runtimeContext ??
          runtimeContextForRecord(
            (await endpointRecord(endpoint.id)) ??
              (() => {
                throw new Error("Chat endpoint is unavailable");
              })(),
          );
        const effect = await db.transaction((tx) =>
          stageProviderEffect(tx, {
            endpoint,
            deliveryId: activeDelivery.id,
            principalId: principalResolution.principal.id,
            providerActionId: `provider_effect:delivery:${activeDelivery.id}`,
            payload: {
              version: 1,
              effect: "thread_message",
              threadId: thread.id,
              text: "Please include a request after mentioning me.",
              settleDelivery: true,
              resourceId: resource.id,
            },
            runtimeContext: effectContext,
          }),
        );
        if (!effect) throw new Error("Provider effect was not persisted");
        if ((await processProviderEffect(effect.id, thread)) !== "processed")
          return;
        if (receiptReactionSupported) {
          await addReceiptReaction({
            deliveryId: activeDelivery.id,
            endpoint,
            message,
            runtimeContext,
            thread,
          });
        }
        return;
      }

      if (guidanceCommand) {
        const assignedAgentName =
          guidanceCommand === "start"
            ? await db
                .select({ name: agents.name })
                .from(agents)
                .where(
                  and(
                    eq(agents.companyId, endpoint.companyId),
                    eq(agents.id, endpoint.assignedAgentId),
                  ),
                )
                .then((rows) => rows[0]?.name ?? "this agent")
            : null;
        const responseText =
          guidanceCommand === "start"
            ? `Send a direct message to start work with ${assignedAgentName}. In a group, use /task@${endpoint.botUsername ?? "your_bot"} followed by your request. Use /status, /new, or /close to manage the active task in this chat.`
            : guidanceCommand === "task"
              ? `Please include a request after /task@${endpoint.botUsername ?? "your_bot"}.`
              : `Available commands: /task@${endpoint.botUsername ?? "your_bot"} followed by your request, /status, /new, and /close.`;
        const publicationBinding =
          existingConversation && existingIssue
            ? { conversation: existingConversation, issue: existingIssue }
            : null;
        let effect: typeof chatActions.$inferSelect | null = null;
        if (publicationBinding) {
          await db.transaction(async (tx) => {
            await tx
              .update(chatEndpoints)
              .set({ lastEventAt: new Date(), updatedAt: new Date() })
              .where(eq(chatEndpoints.id, endpoint.id));
            await tx
              .update(chatDeliveries)
              .set({
                conversationId: publicationBinding.conversation.id,
                state: "processed",
                processedAt: new Date(),
                redactedError: null,
                updatedAt: new Date(),
              })
              .where(eq(chatDeliveries.id, activeDelivery.id));
            await stageAuthorizedTaskControlPublication(tx, {
              companyId: endpoint.companyId,
              endpointId: endpoint.id,
              conversationId: publicationBinding.conversation.id,
              issueId: publicationBinding.issue.id,
              idempotencyKey: `control:guidance:${activeDelivery.id}`,
              payload: projectSafeChatPublication({
                classification: "external",
                source: "task_control",
                text: responseText,
              }),
              principalId: principalResolution.principal.id,
            });
          });
        } else {
          const effectContext =
            runtimeContext ??
            runtimeContextForRecord(
              (await endpointRecord(endpoint.id)) ??
                (() => {
                  throw new Error("Chat endpoint is unavailable");
                })(),
            );
          effect = await db.transaction((tx) =>
            stageProviderEffect(tx, {
              endpoint,
              deliveryId: activeDelivery.id,
              principalId: principalResolution.principal.id,
              providerActionId: `provider_effect:delivery:${activeDelivery.id}`,
              payload: {
                version: 1,
                effect: "thread_message",
                threadId: thread.id,
                text: responseText,
                settleDelivery: true,
                resourceId: resource.id,
              },
              runtimeContext: effectContext,
            }),
          );
          if (!effect) throw new Error("Provider effect was not persisted");
          if ((await processProviderEffect(effect.id, thread)) !== "processed")
            return;
        }
        // Telegram's command reply is the acknowledgement. A control-only
        // request starts no run that could later retire a processing receipt.
        await Promise.allSettled([
          receiptReactionSupported && endpoint.provider !== "telegram"
            ? addReceiptReaction({
                deliveryId: activeDelivery.id,
                endpoint,
                message,
                runtimeContext,
                thread,
              })
            : Promise.resolve(),
          addressed && !thread.isDM ? thread.subscribe() : Promise.resolve(),
        ]);
        return;
      }

      if (controlCommand) {
        const isTelegramForumTopic =
          endpoint.provider === "telegram" && surfaceKind === "native_thread";
        const taskLabel = existingIssue
          ? `${existingIssue.identifier}: ${existingIssue.title}`
          : "No task is active in this conversation.";
        const responseText =
          controlCommand === "status"
            ? existingIssue
              ? `${taskLabel} — ${existingIssue.status}`
              : taskLabel
            : controlCommand === "new"
              ? isTelegramForumTopic
                ? existingIssue
                  ? `${taskLabel} stays bound to this forum topic. Open a new Telegram forum topic to start a new Paperclip task.`
                  : "Open a new Telegram forum topic to start a new Paperclip task."
                : "Send your request to start a new Paperclip task."
              : existingConversation
                ? isTelegramForumTopic
                  ? "This chat conversation is closed. A later message here will continue the same Paperclip task."
                  : "This chat conversation is closed. Send another message to start a new task."
                : "No task is active. Send a message to start one.";
        const publicationBinding =
          existingConversation && existingIssue
            ? { conversation: existingConversation, issue: existingIssue }
            : null;
        if (publicationBinding) {
          const publicationControl =
            controlCommand === "new" && isTelegramForumTopic
              ? "new_guidance"
              : controlCommand;
          const staged = await db.transaction(async (tx) => {
            await tx
              .update(chatEndpoints)
              .set({ lastEventAt: new Date(), updatedAt: new Date() })
              .where(eq(chatEndpoints.id, endpoint.id));
            if (await filterPreControlSource(tx)) return false;
            await tx
              .update(chatDeliveries)
              .set({
                conversationId: publicationBinding.conversation.id,
                state: "processed",
                processedAt: new Date(),
                updatedAt: new Date(),
              })
              .where(eq(chatDeliveries.id, activeDelivery.id));
            await stageAuthorizedTaskControlPublication(tx, {
              companyId: endpoint.companyId,
              endpointId: endpoint.id,
              conversationId: publicationBinding.conversation.id,
              issueId: publicationBinding.issue.id,
              idempotencyKey: `control:${publicationControl}:${activeDelivery.id}`,
              payload: projectSafeChatPublication({
                classification: "external",
                source: "task_control",
                text: responseText,
              }),
              principalId: principalResolution.principal.id,
            });
            return true;
          });
          if (!staged) return;
        } else {
          const effectContext =
            runtimeContext ??
            runtimeContextForRecord(
              (await endpointRecord(endpoint.id)) ??
                (() => {
                  throw new Error("Chat endpoint is unavailable");
                })(),
            );
          const effect = await db.transaction(async (tx) => {
            return stageProviderEffect(tx, {
              endpoint,
              deliveryId: activeDelivery.id,
              principalId: principalResolution.principal.id,
              providerActionId: `provider_effect:delivery:${activeDelivery.id}`,
              payload: {
                version: 1,
                effect: "thread_message",
                threadId: thread.id,
                text: responseText,
                settleDelivery: true,
                resourceId: resource.id,
              },
              runtimeContext: effectContext,
            });
          });
          if (!effect) throw new Error("Provider effect was not persisted");
          if ((await processProviderEffect(effect.id, thread)) !== "processed")
            return;
        }
        // This command stages a reply, not new agent work to acknowledge.
        await Promise.allSettled([
          receiptReactionSupported && endpoint.provider !== "telegram"
            ? addReceiptReaction({
                deliveryId: activeDelivery.id,
                endpoint,
                message,
                runtimeContext,
                thread,
              })
            : Promise.resolve(),
          addressed && !thread.isDM ? thread.subscribe() : Promise.resolve(),
        ]);
        return;
      }

      const persistTaskMutation = async (
        taskTx: DbOrTransaction,
        taskEndpoint: EndpointRow,
        taskUserId: string | null,
      ) => {
        let conversation = existingConversation;
        if (!conversation) {
          const sessionGeneration = isLinear
            ? (latestConversation?.sessionGeneration ?? 0) + 1
            : 1;
          const issue = await issuesSvc.create(
            endpoint.companyId,
            {
              title: safeTitle(
                message.text,
                `${PROVIDER_LABELS[endpoint.provider]} conversation`,
              ),
              description: `Started from ${PROVIDER_LABELS[endpoint.provider]}: ${resource.label}`,
              status: "todo",
              priority: "medium",
              assigneeAgentId: endpoint.assignedAgentId,
              createdByUserId: taskUserId ?? endpoint.sponsorUserId,
              responsibleUserId: taskUserId ?? endpoint.sponsorUserId,
              originKind: "chat_channel",
              originId: `${endpoint.id}:${thread.id}:${sessionGeneration}`,
              idempotencyKey: `chat:${endpoint.id}:${thread.id}:${sessionGeneration}`,
            },
            taskTx,
          );
          if (!taskUserId) {
            const reviewPreset = {
              id: LOW_TRUST_REVIEW_PRESET,
              version: LOW_TRUST_REVIEW_PRESET_VERSION,
              rawOutputDisposition: LOW_TRUST_REVIEW_RAW_OUTPUT_DISPOSITION,
            } as const;
            await taskTx
              .update(issues)
              .set({
                sourceTrust: {
                  preset: LOW_TRUST_REVIEW_PRESET,
                  disposition: "quarantined",
                  sourceIssueId: issue.id,
                },
                executionPolicy: {
                  mode: "normal",
                  commentRequired: true,
                  stages: [],
                  reviewPreset,
                  authorizationPolicy: {
                    trustPreset: LOW_TRUST_REVIEW_PRESET,
                    reviewPreset,
                    trustBoundary: {
                      mode: LOW_TRUST_REVIEW_PRESET,
                      companyId: endpoint.companyId,
                      rootIssueId: issue.id,
                      issueIds: [issue.id],
                      allowedAgentIds: [endpoint.assignedAgentId],
                      allowedToolClasses: [
                        "git.read",
                        "github.pr.read",
                        "tests.local",
                      ],
                    },
                  },
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(issues.id, issue.id),
                  eq(issues.companyId, endpoint.companyId),
                ),
              );
          }
          await taskTx
            .insert(chatConversations)
            .values({
              companyId: endpoint.companyId,
              endpointId: endpoint.id,
              resourceId: resource.id,
              issueId: issue.id,
              externalConversationId: thread.channelId,
              externalThreadId: thread.id,
              sessionGeneration,
              externalLabel: resource.label,
              providerUrl,
              isDirectMessage: thread.isDM,
              state: "active",
              lastActivityAt: new Date(),
            })
            .onConflictDoNothing();
          conversation = await taskTx
            .select()
            .from(chatConversations)
            .where(
              and(
                eq(chatConversations.endpointId, endpoint.id),
                eq(chatConversations.externalConversationId, thread.channelId),
                eq(chatConversations.externalThreadId, thread.id),
                eq(chatConversations.sessionGeneration, sessionGeneration),
              ),
            )
            .then((rows) => rows[0] ?? null);
        }
        if (!conversation)
          throw conflict(
            "Could not bind external conversation to a Paperclip task",
          );

        const issue =
          existingIssue?.id === conversation.issueId
            ? existingIssue
            : await taskTx
                .select()
                .from(issues)
                .where(eq(issues.id, conversation.issueId))
                .then((rows) => rows[0] ?? null);
        if (!issue) throw notFound("Bound task not found");
        if (issue.status === "done" || issue.status === "cancelled") {
          await issuesSvc.update(
            issue.id,
            {
              status: "todo",
              actorUserId: taskUserId ?? taskEndpoint.sponsorUserId,
            },
            taskTx,
          );
        }
        const body =
          message.text.trim() ||
          (message.attachments.length > 0
            ? taskEndpoint.provider === "microsoft-teams" &&
              !thread.isDM &&
              nativeInboundAttachments.length === 0
              ? `Shared ${message.attachments.length} Microsoft Teams file reference${message.attachments.length === 1 ? "" : "s"}.${providerUrl ? ` Open in Microsoft Teams: ${providerUrl}` : ""}`
              : `Shared ${message.attachments.length} file${message.attachments.length === 1 ? "" : "s"}.`
            : "Sent an empty message.");
        let comment!: Awaited<ReturnType<typeof issuesSvc.addComment>>;
        await taskTx
          .update(chatEndpoints)
          .set({
            status: taskEndpoint.status,
            setup: taskEndpoint.setup,
            healthMessage:
              taskEndpoint.status === "verifying"
                ? "Test conversation received"
                : "Connected",
            lastEventAt: new Date(),
            activatedAt:
              taskEndpoint.status === "active"
                ? taskEndpoint.activatedAt
                : null,
            updatedAt: new Date(),
          })
          .where(eq(chatEndpoints.id, taskEndpoint.id));
        comment = await issuesSvc.addComment(
          conversation!.issueId,
          body.slice(0, MAX_INBOUND_TEXT),
          taskUserId ? { userId: taskUserId } : {},
          {
            authorType: taskUserId ? "user" : "system",
            metadata: {
              version: 1,
              sections: [
                {
                  title: `${PROVIDER_LABELS[endpoint.provider]} sender`,
                  rows: [
                    {
                      type: "key_value",
                      label: "Name",
                      value: message.author.fullName || message.author.userName,
                    },
                    {
                      type: "key_value",
                      label: "Provider ID",
                      value: stableExternalPrincipalId(
                        endpoint.provider,
                        message.author,
                        message.raw,
                      ),
                    },
                    {
                      type: "key_value",
                      label: "Authority",
                      value: taskUserId
                        ? "Linked Paperclip user"
                        : "Sponsored external guest (restricted)",
                    },
                  ],
                },
              ],
            },
            sourceTrust: taskUserId
              ? null
              : {
                  preset: LOW_TRUST_REVIEW_PRESET,
                  disposition: "quarantined",
                  sourceIssueId: conversation!.issueId,
                },
          },
          taskTx,
        );
        await taskTx
          .update(chatDeliveries)
          .set({
            conversationId: conversation!.id,
            updatedAt: new Date(),
          })
          .where(eq(chatDeliveries.id, activeDelivery.id));
        await taskTx
          .insert(chatMessageLinks)
          .values({
            companyId: endpoint.companyId,
            endpointId: endpoint.id,
            conversationId: conversation!.id,
            deliveryId: activeDelivery.id,
            commentId: comment.id,
            providerMessageId: message.id,
            direction: "inbound",
          })
          .onConflictDoNothing();
        await taskTx
          .update(chatConversations)
          .set({
            state: "active",
            lastActivityAt: new Date(),
            ...(providerUrl ? { providerUrl } : {}),
            updatedAt: new Date(),
          })
          .where(eq(chatConversations.id, conversation!.id));
        await taskTx
          .update(toolConnections)
          .set({
            status: "active",
            enabled: true,
            healthStatus: "healthy",
            healthMessage: "Connected",
            lastHealthAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(toolConnections.id, taskEndpoint.connectionId));
        await stageInboundWakeup(taskTx, {
          endpoint: taskEndpoint,
          deliveryId: activeDelivery.id,
          conversation,
          commentId: comment.id,
          principalId: principalResolution.principal.id,
          actorUserId: taskUserId,
        });
        return { actorUserId: taskUserId, comment, conversation, issue };
      };
      const taskMutation = await db.transaction(async (tx) => {
        // Admission and durable task mutation are separate so the provider
        // webhook can return inside its response budget. Take the endpoint and
        // destination locks again at the authoritative mutation boundary for
        // every provider: either a reach revocation commits first and this
        // event is redacted, or this task/comment commits first and the
        // revocation waits. There is no stale-snapshot middle.
        await options.reachAuthorizationBarrier?.();
        const currentEndpoint = await tx
          .select()
          .from(chatEndpoints)
          .where(eq(chatEndpoints.id, endpoint.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!currentEndpoint) throw notFound("Chat endpoint not found");
        const currentResource = thread.isDM
          ? resource
          : await tx
              .select()
              .from(chatEndpointResources)
              .where(
                and(
                  eq(chatEndpointResources.id, resource.id),
                  eq(chatEndpointResources.endpointId, endpoint.id),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null);
        const currentPrincipalAuthorization =
          await lockCurrentPrincipalAuthorization(
            tx,
            currentEndpoint,
            principalResolution.principal.id,
          );
        const endpointStillAllowed =
          currentEndpoint.status === "verifying" ||
          currentEndpoint.status === "active";
        const destinationStillAllowed = thread.isDM
          ? currentEndpoint.allowDirectMessages
          : nonDirectDestinationAllowed(currentEndpoint, currentResource);
        if (
          !endpointStillAllowed ||
          !destinationStillAllowed ||
          !currentPrincipalAuthorization.allowed
        ) {
          const filteredAt = new Date();
          await tx
            .update(chatDeliveries)
            .set({
              state: "filtered",
              normalizedEvent: redactedDestinationNormalized,
              principalId: null,
              nextAttemptAt: null,
              processedAt: filteredAt,
              redactedError: endpointStillAllowed
                ? destinationStillAllowed
                  ? currentPrincipalAuthorization.linkedDenied
                    ? "Linked Paperclip account is not currently permitted"
                    : currentEndpoint.allowUnlinkedPeople
                      ? "Endpoint sponsor can no longer authorize external guests"
                      : "External identity must be linked to a Paperclip account"
                  : "Destination is not enabled in Paperclip"
                : "Connection is not active",
              updatedAt: filteredAt,
            })
            .where(
              and(
                eq(chatDeliveries.id, activeDelivery.id),
                eq(chatDeliveries.state, "processing"),
              ),
            );
          // A principal first observed only by this now-revoked event must not
          // survive as a side-channel. Preserve established or linked
          // identities referenced by any other durable record.
          await tx
            .delete(chatExternalPrincipals)
            .where(
              and(
                eq(chatExternalPrincipals.id, principalResolution.principal.id),
                notExists(
                  tx
                    .select({ id: chatDeliveries.id })
                    .from(chatDeliveries)
                    .where(
                      eq(
                        chatDeliveries.principalId,
                        principalResolution.principal.id,
                      ),
                    ),
                ),
                notExists(
                  tx
                    .select({ id: chatIdentityLinks.id })
                    .from(chatIdentityLinks)
                    .where(
                      eq(
                        chatIdentityLinks.principalId,
                        principalResolution.principal.id,
                      ),
                    ),
                ),
                notExists(
                  tx
                    .select({ id: chatActions.id })
                    .from(chatActions)
                    .where(
                      eq(
                        chatActions.principalId,
                        principalResolution.principal.id,
                      ),
                    ),
                ),
              ),
            );
          return null;
        }
        // Close completion takes this endpoint lock in its receipt transaction.
        // Recheck after the lock: an old input held between precheck and task
        // mutation must not create work after that control commits.
        if (await filterPreControlSource(tx)) return null;
        return persistTaskMutation(
          tx,
          currentEndpoint,
          currentPrincipalAuthorization.userId,
        );
      });
      if (!taskMutation) return;
      const { actorUserId, comment, conversation, issue } = taskMutation;
      const attachmentResult = await ingestAttachments({
        endpoint,
        endpointRuntime,
        deliveryId: activeDelivery.id,
        issueId: conversation.issueId,
        issueCommentId: comment.id,
        attachments: nativeInboundAttachments,
        attachmentLimitOmissions: githubAttachmentLimitOmissions(message),
        unavailableReferenceCount: unavailableTeamsReferences,
        actorUserId,
      });
      if (
        await settleTelegramAttachmentOnlyFailure({
          activeDelivery,
          attachmentResult,
          commentId: comment.id,
          conversationId: conversation.id,
          endpoint,
          message,
          principalId: principalResolution.principal.id,
          resourceId: resource.id,
          runtimeContext,
          thread,
        })
      ) {
        return;
      }
      // Do not discard a subscription failure after marking the delivery
      // processed. A retry reuses the committed message link above and tries
      // this idempotent subscription again before completing the delivery.
      if (addressed && !thread.isDM) await thread.subscribe();
      await acceptInboundWakeup(activeDelivery.id, attachmentResult);
      if (!(await processInboundWakeup(activeDelivery.id))) return;
      const acceptedWake = await db
        .select({ status: chatActions.status })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.deliveryId, activeDelivery.id),
            eq(chatActions.kind, "inbound_wakeup"),
          ),
        )
        .limit(1)
        .then((rows) => rows[0] ?? null);
      if (acceptedWake?.status !== "processed") return;
      // Provider-visible acknowledgement begins only after the task, external
      // comment, durable wakeup request, delivery state, and message link commit.
      await Promise.allSettled([
        receiptReactionSupported
          ? addReceiptReaction({
              deliveryId: activeDelivery.id,
              endpoint,
              message,
              runtimeContext,
              thread,
            })
          : Promise.resolve(),
        // Slack implements this through assistant.threads.setStatus, which
        // requires assistant:write. The least-privilege Paperclip manifest
        // deliberately does not request that scope; the coalesced lifecycle
        // reply below is the visible working state instead.
        endpoint.provider === "slack"
          ? Promise.resolve()
          : thread.startTyping("Working…"),
      ]);
    } catch (error) {
      const providerEffectAmbiguous =
        error !== null &&
        typeof error === "object" &&
        "code" in error &&
        error.code === "CHAT_PROVIDER_EFFECT_AMBIGUOUS";
      const terminal =
        providerEffectAmbiguous ||
        isExternalActionAuthorizationChange(error) ||
        activeDelivery.attempts >= 5;
      await db
        .update(chatDeliveries)
        .set({
          state: terminal ? "failed" : "retry",
          nextAttemptAt: terminal
            ? null
            : new Date(
                Date.now() +
                  Math.min(60_000, 1000 * 2 ** activeDelivery.attempts),
              ),
          redactedError: redactError(error),
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, activeDelivery.id),
            eq(chatDeliveries.state, "processing"),
          ),
        );
      if (terminal) await settleRejectedInboundWakeups(activeDelivery.id);
      throw error;
    }
  }

  function deliveryContentWasRedacted(normalizedEvent: unknown): boolean {
    if (
      !normalizedEvent ||
      typeof normalizedEvent !== "object" ||
      Array.isArray(normalizedEvent)
    )
      return false;
    const filtering = (normalizedEvent as { filtering?: unknown }).filtering;
    return (
      Boolean(filtering) &&
      typeof filtering === "object" &&
      !Array.isArray(filtering) &&
      (filtering as { contentRetained?: unknown }).contentRetained === false
    );
  }

  function setupDestinationActivationSuppressed(
    normalizedEvent: unknown,
  ): boolean {
    if (
      !normalizedEvent ||
      typeof normalizedEvent !== "object" ||
      Array.isArray(normalizedEvent)
    )
      return false;
    const normalized = normalizedEvent as {
      admission?: { origin?: unknown };
      admissionAuthorization?: { version?: unknown };
    };
    return (
      normalized.admission?.origin === "provider_confirmed_action" ||
      normalized.admissionAuthorization?.version === 1
    );
  }

  function discordRootThreadPending(
    delivery: Pick<DeliveryRow, "normalizedEvent">,
  ): boolean {
    return (
      Boolean(delivery.normalizedEvent) &&
      typeof delivery.normalizedEvent === "object" &&
      !Array.isArray(delivery.normalizedEvent) &&
      (delivery.normalizedEvent as { providerThreadPending?: unknown })
        .providerThreadPending === true
    );
  }

  async function reconcileDiscordRootThread(
    endpoint: EndpointRow,
    delivery: DeliveryRow,
    threadId: string,
  ): Promise<boolean> {
    try {
      const normalized = delivery.normalizedEvent as {
        message?: { providerMessageId?: unknown; text?: unknown };
        resource?: { providerResourceId?: unknown };
      };
      const discordThreadParts = threadId.split(":");
      const channelId =
        discordThreadParts[0] === "discord" && discordThreadParts.length >= 4
          ? discordThreadParts[2]
          : normalized.resource?.providerResourceId;
      const messageId = normalized.message?.providerMessageId;
      if (typeof channelId !== "string" || typeof messageId !== "string") {
        throw new DiscordAdapterCompatibilityError(
          "the provisional root receipt is missing its channel or message id",
        );
      }
      const runtimeFence = lifecycleRuntimeFence(delivery);
      if (!runtimeFence) {
        throw new DiscordAdapterCompatibilityError(
          "the provisional root receipt is missing its runtime fence",
        );
      }
      return await withCredentialMutationLease(
        endpoint,
        async (credentialLease) => {
          const currentEndpoint = await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            const current = await runtimeCallbackEndpoint(
              tx,
              endpoint.id,
              runtimeFence,
              ["verifying", "active"],
            );
            await credentialLease.assertOwned(tx);
            return current;
          });
          if (!currentEndpoint) {
            throw conflict(
              "Discord root thread credentials or connection state changed before recovery",
              { code: "chat_endpoint_runtime_superseded" },
            );
          }
          const endpointRuntime = await runtimeFor(currentEndpoint);
          await credentialLease.assertOwned();
          await endpointRuntime.ensureDiscordRootThread({
            channelId,
            messageId,
            content:
              typeof normalized.message?.text === "string"
                ? normalized.message.text
                : "Paperclip task",
          });
          return await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            const current = await runtimeCallbackEndpoint(
              tx,
              endpoint.id,
              runtimeFence,
              ["verifying", "active"],
            );
            if (!current) return false;
            const [promoted] = await tx
              .update(chatDeliveries)
              .set({
                state: "received",
                normalizedEvent: sql`${chatDeliveries.normalizedEvent} - 'providerThreadPending'`,
                nextAttemptAt: null,
                redactedError: null,
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatDeliveries.id, delivery.id),
                  eq(chatDeliveries.state, "retry"),
                  sql`${chatDeliveries.normalizedEvent}->>'providerThreadPending' = 'true'`,
                ),
              )
              .returning({ id: chatDeliveries.id });
            await credentialLease.assertOwned(tx);
            return Boolean(promoted);
          });
        },
      );
    } catch (error) {
      const disposition = classifyChatPublicationError(
        error,
        delivery.attempts + 1,
      );
      const terminal =
        disposition.kind === "resource_unavailable" ||
        disposition.kind === "failed";
      const retryAfterMs =
        disposition.kind === "retry"
          ? disposition.retryAfterMs
          : DISCORD_ROOT_THREAD_CONFIRMATION_DELAY_MS;
      const now = new Date();
      await db.transaction(async (tx) => {
        if (disposition.kind === "resource_unavailable") {
          const fence = lifecycleRuntimeFence(delivery);
          const normalized = delivery.normalizedEvent as {
            resource?: { providerResourceId?: unknown };
          };
          const providerResourceId = normalized.resource?.providerResourceId;
          const current = fence
            ? await runtimeCallbackEndpoint(tx, endpoint.id, fence, [
                "verifying",
                "active",
                "attention",
              ])
            : null;
          const resource =
            current && typeof providerResourceId === "string"
              ? await tx
                  .select({ id: chatEndpointResources.id })
                  .from(chatEndpointResources)
                  .where(
                    and(
                      eq(chatEndpointResources.companyId, current.companyId),
                      eq(chatEndpointResources.endpointId, current.id),
                      eq(
                        chatEndpointResources.providerResourceId,
                        providerResourceId,
                      ),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
          if (resource) {
            await tx
              .update(chatEndpointResources)
              .set({ availability: "unavailable", updatedAt: now })
              .where(eq(chatEndpointResources.id, resource.id));
            await tx
              .update(chatConversations)
              .set({ state: "unavailable", updatedAt: now })
              .where(
                and(
                  eq(chatConversations.companyId, current!.companyId),
                  eq(chatConversations.endpointId, current!.id),
                  eq(chatConversations.resourceId, resource.id),
                  inArray(chatConversations.state, ["active", "waiting"]),
                ),
              );
          }
        }
        await tx
          .update(chatDeliveries)
          .set({
            state: terminal ? "filtered" : "retry",
            attempts: delivery.attempts + 1,
            nextAttemptAt: terminal
              ? null
              : new Date(now.getTime() + retryAfterMs),
            processedAt: terminal ? now : null,
            redactedError: terminal
              ? "Discord thread creation was not confirmed"
              : redactError(error),
            updatedAt: now,
          })
          .where(
            and(
              eq(chatDeliveries.id, delivery.id),
              eq(chatDeliveries.state, "retry"),
              sql`${chatDeliveries.normalizedEvent}->>'providerThreadPending' = 'true'`,
            ),
          );
      });
      return false;
    }
  }

  function normalizedDeliveryThreadId(delivery: DeliveryRow): string | null {
    const normalized = delivery.normalizedEvent as {
      conversation?: { externalThreadId?: unknown };
    };
    return typeof normalized.conversation?.externalThreadId === "string"
      ? normalized.conversation.externalThreadId
      : null;
  }

  function normalizedLifecycleTargetEventId(
    delivery: DeliveryRow,
  ): string | null {
    if (
      delivery.eventKind !== "message_updated" &&
      delivery.eventKind !== "message_deleted" &&
      delivery.eventKind !== "message_restored"
    )
      return null;
    const normalized = delivery.normalizedEvent as {
      message?: { targetProviderEventId?: unknown };
    };
    return typeof normalized.message?.targetProviderEventId === "string"
      ? normalized.message.targetProviderEventId
      : null;
  }

  function normalizedLifecycleEffect(
    delivery: DeliveryRow,
  ): ChatProviderLifecycleEffect | null {
    const normalized = delivery.normalizedEvent as { lifecycle?: unknown };
    const value = normalized.lifecycle;
    if (!value || typeof value !== "object" || Array.isArray(value))
      return null;
    const effect = value as Record<string, unknown>;
    if (
      (effect.provider !== "slack" &&
        effect.provider !== "github" &&
        effect.provider !== "discord" &&
        effect.provider !== "microsoft-teams" &&
        effect.provider !== "telegram") ||
      typeof effect.providerEventId !== "string"
    )
      return null;
    if (
      effect.kind === "endpoint" &&
      (effect.availability === "available" ||
        effect.availability === "attention" ||
        effect.availability === "revoked") &&
      typeof effect.reason === "string"
    )
      return effect as ChatProviderLifecycleEffect;
    if (
      effect.kind === "resource" &&
      (effect.availability === "available" ||
        effect.availability === "unavailable" ||
        effect.availability === "removed") &&
      typeof effect.providerResourceId === "string" &&
      (effect.previousProviderResourceId === undefined ||
        typeof effect.previousProviderResourceId === "string") &&
      typeof effect.resourceType === "string" &&
      typeof effect.label === "string"
    )
      return effect as ChatProviderLifecycleEffect;
    return null;
  }

  function deliveryReady(delivery: DeliveryRow, now: Date): boolean {
    // Accepted input may still own the conversation head through its wake
    // outbox. The action dispatcher checks its own retry/claim deadline.
    if (delivery.state === "processed") return true;
    if (delivery.state === "received")
      return !delivery.nextAttemptAt || delivery.nextAttemptAt <= now;
    if (delivery.state === "retry") {
      return !delivery.nextAttemptAt || delivery.nextAttemptAt <= now;
    }
    return (
      delivery.state === "processing" &&
      delivery.updatedAt <=
        new Date(now.getTime() - DELIVERY_PROCESSING_STALE_MS)
    );
  }

  async function earliestOpenConversationDelivery(
    endpointId: string,
    threadId: string,
  ): Promise<DeliveryRow | null> {
    const externalThreadId = sql<string>`${chatDeliveries.normalizedEvent}->'conversation'->>'externalThreadId'`;
    const candidate = await db
      .select()
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.endpointId, endpointId),
          or(
            inArray(chatDeliveries.state, ["received", "retry", "processing"]),
            and(
              eq(chatDeliveries.state, "processed"),
              pendingInboundWakeupCondition(),
            ),
          ),
          notInArray(chatDeliveries.eventKind, [
            "reaction_added",
            "reaction_removed",
          ]),
          externalThreadIdentityCondition(externalThreadId, threadId),
        ),
      )
      .orderBy(
        asc(
          sql`coalesce(nullif(${chatDeliveries.normalizedEvent}->'message'->>'providerSentAt', '')::timestamptz, ${chatDeliveries.receivedAt})`,
        ),
        // GitHub timestamps and Telegram message dates have one-second
        // resolution. GitHub's numeric comment id and Telegram's message_id
        // are monotonic within one conversation, so use them before receipt
        // order. The Telegram update_id is a final provider-native tie-breaker
        // for unusual payloads that lack a usable message_id.
        asc(sql`coalesce(
          case
            when ${chatDeliveries.normalizedEvent}->'message'->>'providerMessageSequence' ~ '^[0-9]+$'
            then (${chatDeliveries.normalizedEvent}->'message'->>'providerMessageSequence')::numeric
            else null
          end,
          case
            when ${chatDeliveries.normalizedEvent}->'message'->>'providerMessageId' ~ '^[0-9]+$'
            then (${chatDeliveries.normalizedEvent}->'message'->>'providerMessageId')::numeric
            else null
          end
        )`),
        asc(sql`case
          when ${chatDeliveries.normalizedEvent}->'message'->>'providerUpdateId' ~ '^[0-9]+$'
          then (${chatDeliveries.normalizedEvent}->'message'->>'providerUpdateId')::numeric
          else null
        end`),
        // GitHub exposes no sortable webhook sequence. When an edit and delete
        // share its whole-second updated_at value, preserve the only valid
        // lifecycle state transition: update before delete. Provider-native
        // update ids (Telegram) remain the stronger preceding key.
        asc(sql`case ${chatDeliveries.eventKind}
          when 'message_updated' then 1
          when 'message_deleted' then 2
          when 'message_restored' then 3
          else 0
        end`),
        asc(chatDeliveries.receivedAt),
        asc(chatDeliveries.id),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (!candidate) return null;

    // A lifecycle callback can reach Paperclip before its create callback. If
    // the root becomes durable while the lifecycle row is waiting, always
    // return that exact dependency first even when a coarse or malformed
    // provider timestamp would otherwise put the edit/delete at the head.
    const targetProviderEventId = normalizedLifecycleTargetEventId(candidate);
    if (!targetProviderEventId) return candidate;
    return db
      .select()
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.endpointId, endpointId),
          eq(chatDeliveries.providerEventId, targetProviderEventId),
          inArray(chatDeliveries.state, ["received", "retry", "processing"]),
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? candidate);
  }

  function pendingInboundWakeupCondition(readyOnly = false): SQL {
    return sql`exists (
      select 1 from ${chatActions}
      where ${chatActions.deliveryId} = ${chatDeliveries.id}
        and ${chatActions.endpointId} = ${chatDeliveries.endpointId}
        and ${chatActions.companyId} = ${chatDeliveries.companyId}
        and ${chatActions.kind} = 'inbound_wakeup'
        and ${chatActions.status} in ('issued', 'processing')
        ${
          readyOnly
            ? sql`and (
          (${chatActions.status} = 'issued' and (${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= now()))
          or (${chatActions.status} = 'processing' and ${chatActions.updatedAt} <= ${new Date(Date.now() - DELIVERY_PROCESSING_STALE_MS).toISOString()}::timestamptz)
        )`
            : sql``
        }
    )`;
  }

  async function acquireConversationDeliveryLease(input: {
    companyId: string;
    endpointId: string;
    threadId: string;
  }): Promise<{ leaseKey: string; token: string } | null> {
    const now = new Date();
    const token = randomUUID();
    const leaseKey = `inbound:${createHash("sha256").update(durableExternalThreadIdentity(input.threadId)).digest("hex")}`;
    const expiresAt = new Date(now.getTime() + DELIVERY_LEASE_TTL_MS);
    const inserted = await db
      .insert(chatEndpointLeases)
      .values({
        companyId: input.companyId,
        endpointId: input.endpointId,
        leaseKey,
        token,
        expiresAt,
      })
      .onConflictDoNothing()
      .returning({ id: chatEndpointLeases.id });
    if (inserted.length > 0) return { leaseKey, token };
    const reclaimed = await db
      .update(chatEndpointLeases)
      .set({ token, expiresAt, updatedAt: now })
      .where(
        and(
          eq(chatEndpointLeases.companyId, input.companyId),
          eq(chatEndpointLeases.endpointId, input.endpointId),
          eq(chatEndpointLeases.leaseKey, leaseKey),
          lte(chatEndpointLeases.expiresAt, now),
        ),
      )
      .returning({ id: chatEndpointLeases.id });
    return reclaimed.length > 0 ? { leaseKey, token } : null;
  }

  async function releaseConversationDeliveryLease(input: {
    endpointId: string;
    leaseKey: string;
    token: string;
  }): Promise<void> {
    await db
      .delete(chatEndpointLeases)
      .where(
        and(
          eq(chatEndpointLeases.endpointId, input.endpointId),
          eq(chatEndpointLeases.leaseKey, input.leaseKey),
          eq(chatEndpointLeases.token, input.token),
        ),
      );
  }

  function messageFromDelivery(
    delivery: DeliveryRow,
    thread: Thread,
    endpointRuntime: ChatSdkEndpointRuntime,
  ): {
    message: Message;
    receiptReactionSupported: boolean;
    suppressSetupDestinationActivation: boolean;
    trigger: ChatSdkMessageCallbackEvent["trigger"];
    providerUrl: string | null;
  } | null {
    if (telegramDeliveryHasZeroMessageId(delivery, endpointRuntime.provider))
      return null;
    const normalized = delivery.normalizedEvent as {
      acknowledgement?: { receiptReactionSupported?: unknown };
      kind?: unknown;
      trigger?: unknown;
      principal?: {
        externalId?: unknown;
        displayName?: unknown;
        handle?: unknown;
      };
      message?: {
        providerMessageId?: unknown;
        text?: unknown;
        mentionedBot?: unknown;
        attachments?: Array<{
          name?: unknown;
          mimeType?: unknown;
          size?: unknown;
          recovery?: unknown;
        }>;
        attachmentLimitOmissions?: unknown;
      };
      conversation?: { providerUrl?: unknown };
    };
    const providerMessageId = normalized.message?.providerMessageId;
    const externalId = normalized.principal?.externalId;
    if (typeof providerMessageId !== "string" || typeof externalId !== "string")
      return null;
    const isTeams = endpointRuntime.provider === "microsoft-teams";
    const referenceOnlyTeamsAttachments = isTeams && !thread.isDM;
    const originFence = lifecycleRuntimeFence(delivery);
    const storedAttachments = normalized.message?.attachments ?? [];
    const attachments = (
      isTeams ? storedAttachments.slice(0, 20) : storedAttachments
    )
      .map((attachment) => {
        if (!attachment || typeof attachment !== "object") return null;
        const rehydrated =
          attachment.recovery &&
          (!referenceOnlyTeamsAttachments ||
            (typeof attachment.recovery === "object" &&
              attachment.recovery !== null &&
              "locator" in attachment.recovery &&
              typeof attachment.recovery.locator === "object" &&
              attachment.recovery.locator !== null &&
              "kind" in attachment.recovery.locator &&
              attachment.recovery.locator.kind === "teams_inline_image"))
            ? endpointRuntime.rehydrateAttachment(attachment.recovery, {
                threadId: thread.id,
                messageId: providerMessageId,
                runtimeGeneration: originFence?.generation,
                credentialFingerprint: originFence?.credentialFingerprint,
                principalExternalId: externalId,
                isDirectMessage: thread.isDM,
              })
            : null;
        if (rehydrated) return rehydrated;
        if (
          isTeams ||
          (endpointRuntime.provider === "telegram" &&
            typeof attachment.recovery === "object" &&
            attachment.recovery !== null &&
            "locator" in attachment.recovery &&
            typeof attachment.recovery.locator === "object" &&
            attachment.recovery.locator !== null &&
            "kind" in attachment.recovery.locator &&
            attachment.recovery.locator.kind === "telegram_media")
        ) {
          // Non-personal references and personal files whose safe download
          // capability did not survive restart still belong to this input.
          // Keep bounded metadata so ingestion records an explicit omission;
          // never persist bearer URLs or fabricate a download capability.
          // Even a legacy URL locator cannot enable non-personal downloads.
          // A Telegram media locator which fails its exact source proof also
          // remains an unavailable input, never an empty attachment-free turn.
          return {
            type: "file",
            name:
              sanitizeFilename(
                typeof attachment.name === "string"
                  ? attachment.name
                  : undefined,
              ) ?? undefined,
            mimeType: normalizeContentType(
              typeof attachment.mimeType === "string"
                ? attachment.mimeType
                : undefined,
            ).slice(0, 255),
            size:
              typeof attachment.size === "number" &&
              Number.isSafeInteger(attachment.size) &&
              attachment.size >= 0
                ? attachment.size
                : undefined,
          } as Attachment;
        }
        return null;
      })
      .filter((attachment): attachment is Attachment => Boolean(attachment));
    const message = {
      id: providerMessageId,
      threadId: thread.id,
      text:
        typeof normalized.message?.text === "string"
          ? normalized.message.text
          : "",
      formatted: { type: "root", children: [] },
      raw: {},
      author: {
        userId: externalId,
        userName:
          typeof normalized.principal?.handle === "string"
            ? normalized.principal.handle
            : externalId,
        fullName:
          typeof normalized.principal?.displayName === "string"
            ? normalized.principal.displayName
            : externalId,
        isBot: false,
        isMe: false,
        isSystem: false,
      },
      metadata: { dateSent: delivery.receivedAt, edited: false },
      attachments,
      links: [],
      isMention: normalized.message?.mentionedBot === true,
    } as unknown as Message;
    if (endpointRuntime.provider === "github") {
      restoreGitHubAttachmentLimitOmissions(
        message,
        normalized.message?.attachmentLimitOmissions,
      );
    }
    const normalizedTrigger = normalized.trigger;
    const trigger: ChatSdkMessageCallbackEvent["trigger"] =
      normalizedTrigger === "direct_message" ||
      normalizedTrigger === "mention" ||
      normalizedTrigger === "subscribed_message" ||
      normalizedTrigger === "unaddressed_message"
        ? normalizedTrigger
        : normalized.kind === "direct_message"
          ? "direct_message"
          : normalized.kind === "mention"
            ? "mention"
            : "subscribed_message";
    return {
      message,
      // Legacy deliveries all originated from native provider messages and
      // therefore retain the historical default.
      receiptReactionSupported:
        normalized.acknowledgement?.receiptReactionSupported !== false,
      suppressSetupDestinationActivation: setupDestinationActivationSuppressed(
        delivery.normalizedEvent,
      ),
      trigger,
      providerUrl:
        typeof normalized.conversation?.providerUrl === "string"
          ? normalized.conversation.providerUrl
          : null,
    };
  }

  /**
   * Drain one external conversation in durable receipt order. The database
   * lease is endpoint + thread scoped, so separate server processes can work
   * on different conversations concurrently but can never mutate the same
   * Paperclip task from two inbound turns at once.
   */
  async function drainConversationDeliveries(
    endpointId: string,
    threadId: string,
  ): Promise<boolean> {
    const endpoint = await db
      .select()
      .from(chatEndpoints)
      .where(eq(chatEndpoints.id, endpointId))
      .then((rows) => rows[0] ?? null);
    if (!endpoint) return false;
    if (endpoint.status === "paused" || endpoint.status === "attention")
      return false;

    const lease = await acquireConversationDeliveryLease({
      companyId: endpoint.companyId,
      endpointId,
      threadId,
    });
    if (!lease) return false;

    let leaseOwned = true;
    let renewal: Promise<void> | null = null;
    const renewTimer = setInterval(
      () => {
        if (!leaseOwned || renewal) return;
        const expiresAt = new Date(Date.now() + DELIVERY_LEASE_TTL_MS);
        renewal = Promise.resolve()
          .then(async () => {
            const renewed = options.renewConversationDeliveryLease
              ? await options.renewConversationDeliveryLease({
                  endpointId,
                  leaseKey: lease.leaseKey,
                  token: lease.token,
                  expiresAt,
                })
              : await db
                  .update(chatEndpointLeases)
                  .set({ expiresAt, updatedAt: new Date() })
                  .where(
                    and(
                      eq(chatEndpointLeases.endpointId, endpointId),
                      eq(chatEndpointLeases.leaseKey, lease.leaseKey),
                      eq(chatEndpointLeases.token, lease.token),
                    ),
                  )
                  .returning({ id: chatEndpointLeases.id })
                  .then((rows) => rows.length > 0);
            if (!renewed) leaseOwned = false;
          })
          .catch((error) => {
            // A failed renewal has unknown durability. Stop this local drain at
            // the next delivery boundary so another worker can never overlap
            // later turns after the original lease expires or is reclaimed.
            leaseOwned = false;
            logger.warn(
              { endpointId, error: redactError(error) },
              "could not renew external chat conversation lease",
            );
          })
          .finally(() => {
            renewal = null;
          });
      },
      options.conversationLeaseRenewalIntervalMs ?? DELIVERY_LEASE_TTL_MS / 3,
    );
    renewTimer.unref?.();

    try {
      for (
        let processed = 0;
        processed < DELIVERY_DRAIN_LIMIT;
        processed += 1
      ) {
        if (!leaseOwned) break;
        const delivery = await earliestOpenConversationDelivery(
          endpointId,
          threadId,
        );
        if (!delivery || !deliveryReady(delivery, new Date())) break;
        if (delivery.state === "processed") {
          if (!(await processInboundWakeup(delivery.id))) break;
          continue;
        }
        if (telegramDeliveryHasZeroMessageId(delivery, endpoint.provider)) {
          const filtered = await db
            .transaction(async (tx) => {
              // Do not round-trip a PostgreSQL microsecond timestamp through
              // JS Date for a CAS. Lock the exact receipt, then revalidate the
              // current source and claim before changing it. A competing live
              // claim is a retry boundary, not permission to settle its work.
              const [current] = await tx
                .select()
                .from(chatDeliveries)
                .where(
                  and(
                    eq(chatDeliveries.id, delivery.id),
                    eq(chatDeliveries.companyId, endpoint.companyId),
                    eq(chatDeliveries.endpointId, endpoint.id),
                  ),
                )
                .for("update", { noWait: true });
              const filteredAt = new Date();
              if (
                !current ||
                current.state !== delivery.state ||
                current.eventKind !== delivery.eventKind ||
                !["received", "retry", "processing"].includes(current.state) ||
                normalizedDeliveryThreadId(current) !== threadId ||
                !deliveryReady(current, filteredAt) ||
                !telegramDeliveryHasZeroMessageId(current, endpoint.provider)
              )
                return false;
              const changed = await tx
                .update(chatDeliveries)
                .set({
                  state: "filtered",
                  nextAttemptAt: null,
                  processedAt: filteredAt,
                  updatedAt: filteredAt,
                  redactedError:
                    "Telegram message ID zero cannot authorize ordinary work",
                })
                .where(eq(chatDeliveries.id, current.id))
                .returning({ id: chatDeliveries.id });
              return changed.length === 1;
            })
            .catch((error: unknown) => {
              if (isExternalChatWaitAuthorizationContention(error))
                return false;
              throw error;
            });
          if (!filtered) break;
          // Retain original evidence/comments; filtering adds no user content
          // and cannot hydrate attachments, invoke commands, or send feedback.
          await settleRejectedInboundWakeups(delivery.id);
          liveInboundMessages.delete(delivery.id);
          continue;
        }
        if (endpoint.status === "archived" || endpoint.status === "revoked") {
          await db
            .update(chatDeliveries)
            .set({
              state: "filtered",
              redactedError: "Connection was removed before processing",
              processedAt: new Date(),
              updatedAt: new Date(),
            })
            .where(eq(chatDeliveries.id, delivery.id));
          liveInboundMessages.delete(delivery.id);
          continue;
        }

        if (
          endpoint.provider === "discord" &&
          discordRootThreadPending(delivery)
        ) {
          // This is the only recovery path for the narrow crash window after
          // pre-admission but before Chat's ordinary callback. A successful
          // read proves the root thread exists; an explicit 404/410 proves it
          // does not. Ambiguous transport and auth failures remain retryable.
          if (await reconcileDiscordRootThread(endpoint, delivery, threadId)) {
            continue;
          }
          break;
        }

        const live = liveInboundMessages.get(delivery.id);
        try {
          if (
            delivery.eventKind === "message_updated" ||
            delivery.eventKind === "message_deleted" ||
            delivery.eventKind === "message_restored"
          ) {
            await processLifecycleDelivery(endpoint, delivery);
          } else if (live) {
            await processMessage(
              endpoint,
              live.thread,
              live.message,
              live.trigger,
              false,
              null,
              live.runtimeContext,
              undefined,
              delivery.id,
              live.receiptReactionSupported,
              undefined,
              false,
              setupDestinationActivationSuppressed(delivery.normalizedEvent),
            );
          } else {
            if (deliveryContentWasRedacted(delivery.normalizedEvent)) {
              const filteredAt = new Date();
              await db
                .update(chatDeliveries)
                .set({
                  state: "filtered",
                  principalId: null,
                  nextAttemptAt: null,
                  processedAt: filteredAt,
                  redactedError:
                    "Provisional Teams setup reply could not be hydrated from a current provider event",
                  updatedAt: filteredAt,
                })
                .where(
                  and(
                    eq(chatDeliveries.id, delivery.id),
                    inArray(chatDeliveries.state, [
                      "received",
                      "retry",
                      "processing",
                    ]),
                  ),
                );
              continue;
            }
            const endpointRuntime = await runtimeFor(endpoint);
            const deliveryRuntimeFence = lifecycleRuntimeFence(delivery);
            const currentRuntimeContext = runtimeContexts.get(
              endpointRuntime as object,
            );
            const thread = endpointRuntime.thread(threadId);
            const reconstructed = messageFromDelivery(
              delivery,
              thread,
              endpointRuntime,
            );
            if (!reconstructed) {
              await db
                .update(chatDeliveries)
                .set({
                  state: "failed",
                  redactedError: "Normalized delivery is incomplete",
                  updatedAt: new Date(),
                })
                .where(eq(chatDeliveries.id, delivery.id));
              continue;
            }
            await processMessage(
              endpoint,
              thread,
              reconstructed.message,
              reconstructed.trigger,
              false,
              reconstructed.providerUrl,
              deliveryRuntimeFence
                ? {
                    ...deliveryRuntimeFence,
                    endpointRuntime,
                  }
                : currentRuntimeContext,
              undefined,
              delivery.id,
              reconstructed.receiptReactionSupported,
              undefined,
              false,
              reconstructed.suppressSetupDestinationActivation,
            );
          }
        } catch (error) {
          logger.warn(
            {
              endpointId,
              deliveryId: delivery.id,
              error: redactError(error),
            },
            "external chat delivery will retry in receipt order",
          );
        }

        const state = await db
          .select({ state: chatDeliveries.state })
          .from(chatDeliveries)
          .where(eq(chatDeliveries.id, delivery.id))
          .then((rows) => rows[0]?.state ?? null);
        if (
          state === "processed" ||
          state === "filtered" ||
          state === "failed"
        ) {
          if (state !== "processed")
            await settleRejectedInboundWakeups(delivery.id);
          liveInboundMessages.delete(delivery.id);
          continue;
        }
        // A retry delay or another still-live processing claim is a strict
        // head-of-line barrier; later replies may not overtake it.
        break;
      }
    } finally {
      clearInterval(renewTimer);
      await renewal;
      await releaseConversationDeliveryLease({ endpointId, ...lease });
    }

    const next = await earliestOpenConversationDelivery(endpointId, threadId);
    if (next?.state === "processed") {
      const [ready] = await db
        .select({ id: chatDeliveries.id })
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.id, next.id),
            pendingInboundWakeupCondition(true),
          ),
        )
        .limit(1);
      return Boolean(ready);
    }
    return Boolean(next && deliveryReady(next, new Date()));
  }

  async function handleSdkMessage(
    event: ChatSdkMessageCallbackEvent,
    runtimeContext?: RuntimeContext,
    messageOptions: { receiptReactionSupported?: boolean; slackSlashControl?: boolean } = {},
  ) {
    if (
      event.provider === "discord" &&
      (!runtimeContext ||
        !(await ensureDiscordGatewayRuntimeIsCurrent(
          event.endpointId,
          runtimeContext,
        )))
    ) {
      return;
    }
    if (event.provider === "discord") {
      await options.discordGatewayMessageAdmissionBarrier?.();
    }
    const record = await endpointRecord(event.endpointId);
    if (!record) throw notFound("Chat endpoint not found");
    const messages = [...(event.context?.skipped ?? []), event.message];
    for (const message of messages)
      await processMessage(
        record.endpoint,
        event.thread,
        message,
        message === event.message ? event.trigger : "subscribed_message",
        options.deferWebhookProcessing === true,
        null,
        runtimeContext,
        event.providerUpdateId,
        null,
        messageOptions.receiptReactionSupported !== false,
        undefined,
        false,
        false,
        messageOptions.slackSlashControl === true,
      );
  }

  async function conversationForThread(endpointId: string, threadId: string) {
    const exact = await db
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.endpointId, endpointId),
          eq(chatConversations.externalThreadId, threadId),
        ),
      )
      .orderBy(desc(chatConversations.sessionGeneration))
      .then((rows) => rows[0] ?? null);
    if (exact || !threadId.startsWith("teams:")) return exact;

    // Before Paperclip made Teams route state independent, the adapter
    // embedded the mutable Bot Connector serviceUrl in every thread id. Read
    // those rows by the immutable conversation id so a regional route change
    // continues the same task. New rows use the canonical route-free id.
    if (!teamsConversationId(threadId)) return null;
    return db
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.endpointId, endpointId),
          externalThreadIdentityCondition(
            sql<string>`${chatConversations.externalThreadId}`,
            threadId,
          ),
        ),
      )
      .orderBy(desc(chatConversations.sessionGeneration))
      .then(
        (rows) =>
          rows.find((row) =>
            sameTeamsThreadIdentity(row.externalThreadId, threadId),
          ) ?? null,
      );
  }

  async function recordLifecycleDelivery(
    input: {
      actor?: LifecycleActor;
      isBotMessage?: true;
      endpointId: string;
      threadId: string;
      messageId: string;
      eventKind: "message_updated" | "message_deleted" | "message_restored";
      text: string;
      providerEventId?: string;
      providerMessageSequence?: number | null;
      providerSentAt?: string | null;
      providerUpdateId?: number | null;
      raw?: unknown;
      revision?: string | null;
    },
    runtimeContext?: RuntimeContext,
  ) {
    const durableThreadId = durableExternalThreadIdentity(input.threadId);
    const providerEventId =
      input.providerEventId ??
      `${input.eventKind}:${durableThreadId}:${input.messageId}:${input.revision ?? "once"}`;
    const targetProviderEventId = `${durableThreadId}:${input.messageId}`;
    const admission = await db.transaction(async (tx) => {
      const endpoint = await tx
        .select()
        .from(chatEndpoints)
        .where(eq(chatEndpoints.id, input.endpointId))
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!endpoint) throw notFound("Chat endpoint not found");
      if (
        runtimeContext &&
        !(await runtimeCallbackEndpoint(tx, endpoint.id, runtimeContext, [
          "verifying",
          "active",
        ]))
      )
        return null;
      // A provider has already authenticated this callback. During setup the
      // message can belong to the test conversation, so retain its correction.
      // Paused or unhealthy connections acknowledge late callbacks without
      // mutating the bound task or causing provider retry storms.
      if (endpoint.status !== "verifying" && endpoint.status !== "active")
        return null;
      const reorderWindow = INGRESS_REORDER_WINDOW_MS[endpoint.provider];
      const scheduledAt =
        options.deferWebhookProcessing === true && reorderWindow
          ? (scheduledConversationDrains.get(
              conversationDrainKey(input.endpointId, input.threadId),
            ) ?? Date.now() + reorderWindow)
          : null;
      const [delivery] = await tx
        .insert(chatDeliveries)
        .values({
          companyId: endpoint.companyId,
          endpointId: input.endpointId,
          providerEventId,
          deduplicationKey: createHash("sha256")
            .update(providerEventId)
            .digest("hex"),
          eventKind: input.eventKind,
          normalizedEvent: {
            providerEventId,
            kind: input.eventKind,
            ...(runtimeContext
              ? {
                  runtimeContext: {
                    credentialFingerprint: runtimeContext.credentialFingerprint,
                    generation: runtimeContext.generation,
                  },
                }
              : {}),
            ...(input.actor ? { principal: input.actor } : {}),
            conversation: { externalThreadId: input.threadId },
            message: {
              providerMessageId: input.messageId,
              targetProviderEventId,
              ...(endpoint.provider === "github" && input.isBotMessage === true
                ? { isBotMessage: true }
                : {}),
              providerMessageSequence: input.providerMessageSequence ?? null,
              providerSentAt: input.providerSentAt ?? null,
              providerUpdateId: input.providerUpdateId ?? null,
              text: input.text,
            },
          },
          state: "received",
          nextAttemptAt: scheduledAt ? new Date(scheduledAt) : null,
        })
        .onConflictDoNothing()
        .returning();
      if (delivery) return { delivery, endpoint, scheduledAt };
      const existing = await tx
        .select()
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.endpointId, input.endpointId),
            eq(chatDeliveries.providerEventId, providerEventId),
          ),
        )
        .then((rows) => rows[0] ?? null);
      return existing ? { delivery: existing, endpoint, scheduledAt } : null;
    });
    if (admission) {
      // Lifecycle callbacks can carry a new regional Bot Connector route. Keep
      // that provider-authenticated route current even when processing is
      // deferred, but deliberately omit the raw activity here. Lifecycle
      // callbacks never populate the adapter's user cache; the admitted root
      // message already established the principal metadata they must match.
      await recordCurrentMicrosoftTeamsRoute(
        admission.endpoint,
        runtimeContext,
        input.threadId,
        input.raw,
        false,
      );
    }
    if (
      !admission ||
      admission.delivery.state === "processed" ||
      admission.delivery.state === "filtered" ||
      admission.delivery.state === "failed"
    )
      return;
    if (options.deferWebhookProcessing === true) {
      scheduleConversationDrain(
        input.endpointId,
        input.threadId,
        admission.scheduledAt ?? Date.now(),
      );
      return;
    }
    await drainConversationDeliveries(input.endpointId, input.threadId);
  }

  function lifecycleMessageFromDelivery(delivery: DeliveryRow): {
    actor: LifecycleActor | null;
    isBotMessage: boolean;
    messageId: string;
    providerSentAt: string | null;
    targetProviderEventId: string;
    text: string;
    threadId: string;
  } | null {
    if (
      delivery.eventKind !== "message_updated" &&
      delivery.eventKind !== "message_deleted" &&
      delivery.eventKind !== "message_restored"
    )
      return null;
    const normalized = delivery.normalizedEvent as {
      principal?: {
        displayName?: unknown;
        externalId?: unknown;
        handle?: unknown;
      };
      message?: {
        isBotMessage?: unknown;
        providerMessageId?: unknown;
        providerSentAt?: unknown;
        targetProviderEventId?: unknown;
        text?: unknown;
      };
    };
    const messageId = normalized.message?.providerMessageId;
    const targetProviderEventId = normalized.message?.targetProviderEventId;
    const providerSentAt = normalized.message?.providerSentAt;
    const text = normalized.message?.text;
    const threadId = normalizedDeliveryThreadId(delivery);
    const externalId = normalized.principal?.externalId;
    const actor =
      typeof externalId === "string" && externalId
        ? {
            externalId,
            displayName:
              typeof normalized.principal?.displayName === "string"
                ? normalized.principal.displayName
                : externalId,
            handle:
              typeof normalized.principal?.handle === "string"
                ? normalized.principal.handle
                : externalId,
          }
        : null;
    return typeof messageId === "string" &&
      typeof targetProviderEventId === "string" &&
      typeof text === "string" &&
      threadId !== null
      ? {
          actor,
          isBotMessage: normalized.message?.isBotMessage === true,
          messageId,
          providerSentAt:
            typeof providerSentAt === "string" ? providerSentAt : null,
          targetProviderEventId,
          text,
          threadId,
        }
      : null;
  }

  async function processLifecycleDelivery(
    endpoint: EndpointRow,
    candidate: DeliveryRow,
  ): Promise<void> {
    const lifecycle = lifecycleMessageFromDelivery(candidate);
    if (!lifecycle) {
      await db
        .update(chatDeliveries)
        .set({
          state: "failed",
          redactedError: "Normalized lifecycle delivery is incomplete",
          updatedAt: new Date(),
        })
        .where(eq(chatDeliveries.id, candidate.id));
      return;
    }

    const now = new Date();
    const staleBefore = new Date(now.getTime() - DELIVERY_PROCESSING_STALE_MS);
    const claimConditions = [
      eq(chatDeliveries.id, candidate.id),
      eq(chatDeliveries.state, candidate.state),
    ];
    if (candidate.state === "processing")
      claimConditions.push(lte(chatDeliveries.updatedAt, staleBefore));
    const [activeDelivery] = await db
      .update(chatDeliveries)
      .set({
        state: "processing",
        attempts: candidate.attempts + 1,
        nextAttemptAt: null,
        redactedError: null,
        updatedAt: now,
      })
      .where(and(...claimConditions))
      .returning();
    if (!activeDelivery) return;

    try {
      await db.transaction(async (tx) => {
        const admittedRuntimeContext = lifecycleRuntimeFence(activeDelivery);
        const currentEndpoint = admittedRuntimeContext
          ? await runtimeCallbackEndpoint(
              tx,
              endpoint.id,
              admittedRuntimeContext,
              ["verifying", "active"],
            )
          : null;
        if (!admittedRuntimeContext || !currentEndpoint) {
          const filteredAt = new Date();
          await tx
            .update(chatDeliveries)
            .set({
              state: "filtered",
              nextAttemptAt: null,
              processedAt: filteredAt,
              redactedError:
                "Message lifecycle callback belonged to a superseded runtime",
              updatedAt: filteredAt,
            })
            .where(
              and(
                eq(chatDeliveries.id, activeDelivery.id),
                eq(chatDeliveries.state, "processing"),
              ),
            );
          return;
        }
        let githubBotSourceEdit = false;
        if (
          currentEndpoint.provider === "github" &&
          activeDelivery.eventKind === "message_updated"
        ) {
          // Bot callbacks can arrive before the outbound publication commits
          // its message link. The Boolean comes only from GitHub's verified
          // sender/comment-author type, never from comment text. Legacy rows
          // lack it, so also recognize exact already-published outbound links.
          const linkedMessages = await tx
            .select({ direction: chatMessageLinks.direction })
            .from(chatMessageLinks)
            .innerJoin(
              chatConversations,
              and(
                eq(chatConversations.id, chatMessageLinks.conversationId),
                eq(chatConversations.companyId, chatMessageLinks.companyId),
                eq(chatConversations.endpointId, chatMessageLinks.endpointId),
              ),
            )
            .where(
              and(
                eq(chatMessageLinks.companyId, currentEndpoint.companyId),
                eq(chatMessageLinks.endpointId, currentEndpoint.id),
                eq(chatMessageLinks.providerMessageId, lifecycle.messageId),
                eq(chatConversations.externalThreadId, lifecycle.threadId),
              ),
            );
          const outbound = linkedMessages.some(
            (row) => row.direction === "outbound",
          );
          // A bot editor can change an already-admitted human source. That
          // authenticated change revokes the old source, but never admits the
          // bot's new content. Unknown/self/outbound updates remain suppressed.
          githubBotSourceEdit =
            lifecycle.isBotMessage &&
            !outbound &&
            linkedMessages.some((row) => row.direction === "inbound");
          if (outbound || (lifecycle.isBotMessage && !githubBotSourceEdit)) {
            const filteredAt = new Date();
            await tx
              .update(chatDeliveries)
              .set({
                state: "filtered",
                principalId: null,
                nextAttemptAt: null,
                processedAt: filteredAt,
                updatedAt: filteredAt,
                redactedError:
                  "Provider bot or outbound message updates do not create inbound work",
                normalizedEvent: {
                  providerEventId:
                    activeDelivery.normalizedEvent.providerEventId ??
                    activeDelivery.providerEventId,
                  kind: activeDelivery.eventKind,
                  conversation: { externalThreadId: lifecycle.threadId },
                  message: {
                    providerMessageId: lifecycle.messageId,
                    targetProviderEventId: lifecycle.targetProviderEventId,
                  },
                  filtering: { contentRetained: false },
                },
              })
              .where(
                and(
                  eq(chatDeliveries.id, activeDelivery.id),
                  eq(chatDeliveries.state, "processing"),
                ),
              );
            return;
          }
        }
        if (
          activeDelivery.eventKind === "message_updated" ||
          activeDelivery.eventKind === "message_deleted" ||
          activeDelivery.eventKind === "message_restored"
        ) {
          const latestDeleteTransition = await tx
            .select({
              eventKind: chatDeliveries.eventKind,
              providerSentAt: sql<
                string | null
              >`nullif(${chatDeliveries.normalizedEvent}->'message'->>'providerSentAt', '')`,
            })
            .from(chatDeliveries)
            .where(
              and(
                eq(chatDeliveries.companyId, activeDelivery.companyId),
                eq(chatDeliveries.endpointId, endpoint.id),
                inArray(chatDeliveries.eventKind, [
                  "message_deleted",
                  "message_restored",
                ]),
                eq(chatDeliveries.state, "processed"),
                externalThreadIdentityCondition(
                  sql<string>`${chatDeliveries.normalizedEvent}->'conversation'->>'externalThreadId'`,
                  lifecycle.threadId,
                ),
                sql`${chatDeliveries.normalizedEvent}->'message'->>'targetProviderEventId' = ${lifecycle.targetProviderEventId}`,
              ),
            )
            .orderBy(
              desc(
                sql`coalesce(nullif(${chatDeliveries.normalizedEvent}->'message'->>'providerSentAt', '')::timestamptz, ${chatDeliveries.processedAt})`,
              ),
              desc(sql`case ${chatDeliveries.eventKind}
                when 'message_restored' then 2
                when 'message_deleted' then 1
                else 0
              end`),
              desc(chatDeliveries.processedAt),
              desc(chatDeliveries.id),
            )
            .limit(1)
            .then((rows) => rows[0] ?? null);
          const latestTransitionAt = latestDeleteTransition?.providerSentAt
            ? Date.parse(latestDeleteTransition.providerSentAt)
            : Number.NaN;
          const incomingTransitionAt = lifecycle.providerSentAt
            ? Date.parse(lifecycle.providerSentAt)
            : Number.NaN;
          const incomingTransitionIsStale =
            latestDeleteTransition !== null &&
            Number.isFinite(latestTransitionAt) &&
            Number.isFinite(incomingTransitionAt) &&
            (incomingTransitionAt < latestTransitionAt ||
              (incomingTransitionAt === latestTransitionAt &&
                activeDelivery.eventKind === "message_deleted" &&
                latestDeleteTransition.eventKind === "message_restored"));
          const editTargetsDeletedMessage =
            activeDelivery.eventKind === "message_updated" &&
            latestDeleteTransition?.eventKind === "message_deleted";
          const editPredatesRestore =
            activeDelivery.eventKind === "message_updated" &&
            latestDeleteTransition?.eventKind === "message_restored" &&
            Number.isFinite(latestTransitionAt) &&
            Number.isFinite(incomingTransitionAt) &&
            incomingTransitionAt < latestTransitionAt;
          if (
            incomingTransitionIsStale ||
            editTargetsDeletedMessage ||
            editPredatesRestore
          ) {
            const filteredAt = new Date();
            await tx
              .update(chatDeliveries)
              .set({
                state: "filtered",
                normalizedEvent: {
                  providerEventId:
                    activeDelivery.normalizedEvent.providerEventId ??
                    activeDelivery.providerEventId,
                  kind: activeDelivery.eventKind,
                  conversation: { externalThreadId: lifecycle.threadId },
                  message: {
                    providerMessageId: lifecycle.messageId,
                    targetProviderEventId: lifecycle.targetProviderEventId,
                  },
                  filtering: { contentRetained: false },
                },
                principalId: null,
                nextAttemptAt: null,
                processedAt: filteredAt,
                redactedError: editTargetsDeletedMessage
                  ? "Message edit arrived after the provider message was deleted"
                  : "Message lifecycle callback was older than the current provider state",
                updatedAt: filteredAt,
              })
              .where(
                and(
                  eq(chatDeliveries.id, activeDelivery.id),
                  eq(chatDeliveries.state, "processing"),
                ),
              );
            return;
          }
        }
        const originalDelivery = await tx
          .select({ state: chatDeliveries.state })
          .from(chatDeliveries)
          .where(
            and(
              eq(chatDeliveries.endpointId, endpoint.id),
              eq(
                chatDeliveries.providerEventId,
                lifecycle.targetProviderEventId,
              ),
            ),
          )
          .then((rows) => rows[0] ?? null);
        const linkedTargets = await tx
          .select({
            conversationId: chatConversations.id,
            externalThreadId: chatConversations.externalThreadId,
            issueId: chatConversations.issueId,
          })
          .from(chatMessageLinks)
          .innerJoin(
            chatConversations,
            and(
              eq(chatConversations.companyId, chatMessageLinks.companyId),
              eq(chatConversations.id, chatMessageLinks.conversationId),
            ),
          )
          .where(
            and(
              eq(chatMessageLinks.endpointId, endpoint.id),
              eq(chatMessageLinks.providerMessageId, lifecycle.messageId),
              eq(chatMessageLinks.direction, "inbound"),
            ),
          )
          .orderBy(desc(chatConversations.sessionGeneration))
          .then((rows) => rows);
        const linkedTarget =
          linkedTargets.find((candidate) =>
            currentEndpoint.provider === "microsoft-teams"
              ? sameTeamsThreadIdentity(
                  candidate.externalThreadId,
                  lifecycle.threadId,
                )
              : candidate.externalThreadId === lifecycle.threadId,
          ) ?? null;

        if (!linkedTarget) {
          const originalIsOpen =
            originalDelivery !== null &&
            ["received", "processing", "retry"].includes(
              originalDelivery.state,
            );
          const waitForRoot =
            originalIsOpen ||
            activeDelivery.attempts <= ORPHAN_FOLLOW_UP_MAX_ATTEMPTS;
          const resolutionAt = new Date();
          await tx
            .update(chatDeliveries)
            .set(
              waitForRoot
                ? {
                    state: "retry",
                    nextAttemptAt: new Date(
                      resolutionAt.getTime() + ORPHAN_FOLLOW_UP_GRACE_MS,
                    ),
                    redactedError: originalIsOpen
                      ? "Waiting for the original message to finish processing"
                      : "Waiting briefly for the original message",
                    updatedAt: resolutionAt,
                  }
                : {
                    state: "filtered",
                    nextAttemptAt: null,
                    redactedError:
                      "Original message was not admitted to this conversation",
                    processedAt: resolutionAt,
                    updatedAt: resolutionAt,
                  },
            )
            .where(
              and(
                eq(chatDeliveries.id, activeDelivery.id),
                eq(chatDeliveries.state, "processing"),
              ),
            );
          return;
        }

        const currentConversation = await tx
          .select()
          .from(chatConversations)
          .where(
            and(
              eq(chatConversations.companyId, currentEndpoint.companyId),
              eq(chatConversations.endpointId, currentEndpoint.id),
              eq(chatConversations.id, linkedTarget.conversationId),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        const currentResource =
          currentConversation?.resourceId &&
          !currentConversation.isDirectMessage
            ? await tx
                .select()
                .from(chatEndpointResources)
                .where(
                  and(
                    eq(
                      chatEndpointResources.companyId,
                      currentEndpoint.companyId,
                    ),
                    eq(chatEndpointResources.endpointId, currentEndpoint.id),
                    eq(
                      chatEndpointResources.id,
                      currentConversation.resourceId,
                    ),
                  ),
                )
                .for("update")
                .then((rows) => rows[0] ?? null)
            : null;
        const retainSourceInvalidation = async (
          principalId: string | null,
          reason: string,
        ): Promise<boolean> => {
          if (
            !currentConversation ||
            activeDelivery.eventKind !== "message_updated"
          )
            return false;
          const invalidatedAt = new Date();
          // Provider authentication proves the exact source changed. The
          // editor's current Paperclip rights govern admitting new content,
          // not whether a later regrant can resurrect the stale old source.
          await tx
            .update(chatDeliveries)
            .set({
              state: "processed",
              conversationId: currentConversation.id,
              principalId,
              normalizedEvent: {
                providerEventId:
                  activeDelivery.normalizedEvent.providerEventId ??
                  activeDelivery.providerEventId,
                kind: activeDelivery.eventKind,
                runtimeContext: {
                  generation: admittedRuntimeContext.generation,
                  credentialFingerprint:
                    admittedRuntimeContext.credentialFingerprint,
                },
                conversation: { externalThreadId: lifecycle.threadId },
                message: {
                  providerMessageId: lifecycle.messageId,
                  targetProviderEventId: lifecycle.targetProviderEventId,
                  providerSentAt: lifecycle.providerSentAt,
                },
                filtering: { contentRetained: false },
              },
              nextAttemptAt: null,
              processedAt: invalidatedAt,
              redactedError: reason,
              updatedAt: invalidatedAt,
            })
            .where(
              and(
                eq(chatDeliveries.id, activeDelivery.id),
                eq(chatDeliveries.state, "processing"),
              ),
            );
          return true;
        };
        if (
          githubBotSourceEdit &&
          (await retainSourceInvalidation(
            null,
            "Provider bot edit invalidated an existing source without admitting bot content",
          ))
        )
          return;

        let lifecyclePrincipalId: string | null = null;
        const requiresLifecycleActorAuthorization =
          (activeDelivery.eventKind === "message_updated" ||
            activeDelivery.eventKind === "message_restored") &&
          (lifecycle.actor !== null ||
            currentEndpoint.provider === "github" ||
            currentEndpoint.provider === "telegram" ||
            currentEndpoint.provider === "microsoft-teams");
        if (requiresLifecycleActorAuthorization) {
          const lifecyclePrincipal = lifecycle.actor
            ? await tx
                .select({
                  id: chatExternalPrincipals.id,
                  isBot: chatExternalPrincipals.isBot,
                  kind: chatExternalPrincipals.kind,
                })
                .from(chatExternalPrincipals)
                .where(
                  and(
                    eq(
                      chatExternalPrincipals.companyId,
                      currentEndpoint.companyId,
                    ),
                    eq(
                      chatExternalPrincipals.provider,
                      currentEndpoint.provider,
                    ),
                    eq(
                      chatExternalPrincipals.providerAccountId,
                      currentEndpoint.providerAccountId ?? "unknown",
                    ),
                    eq(
                      chatExternalPrincipals.externalId,
                      lifecycle.actor.externalId,
                    ),
                  ),
                )
                .for("update")
                .then((rows) => rows[0] ?? null)
            : null;
          const authorization =
            lifecyclePrincipal &&
            lifecyclePrincipal.kind === "user" &&
            !lifecyclePrincipal.isBot
              ? await lockCurrentPrincipalAuthorization(
                  tx,
                  currentEndpoint,
                  lifecyclePrincipal.id,
                )
              : null;
          const authorizedPrincipalId = authorization?.allowed
            ? (lifecyclePrincipal?.id ?? null)
            : null;
          if (!authorizedPrincipalId) {
            if (
              await retainSourceInvalidation(
                lifecyclePrincipal?.id ?? null,
                "Provider edit invalidation retained without admitting content from an unauthorized actor",
              )
            )
              return;
            const filteredAt = new Date();
            await tx
              .update(chatDeliveries)
              .set({
                principalId: lifecyclePrincipal?.id ?? null,
                state: "filtered",
                normalizedEvent: {
                  providerEventId:
                    activeDelivery.normalizedEvent.providerEventId ??
                    activeDelivery.providerEventId,
                  kind: activeDelivery.eventKind,
                  conversation: { externalThreadId: lifecycle.threadId },
                  message: {
                    providerMessageId: lifecycle.messageId,
                    targetProviderEventId: lifecycle.targetProviderEventId,
                  },
                  filtering: { contentRetained: false },
                },
                nextAttemptAt: null,
                processedAt: filteredAt,
                redactedError:
                  "External message actor is no longer authorized for lifecycle events",
                updatedAt: filteredAt,
              })
              .where(
                and(
                  eq(chatDeliveries.id, activeDelivery.id),
                  eq(chatDeliveries.state, "processing"),
                ),
              );
            return;
          }
          lifecyclePrincipalId = authorizedPrincipalId;
        }

        const destinationAllowed =
          currentConversation !== null &&
          ["active", "waiting"].includes(currentConversation.state) &&
          (currentConversation.isDirectMessage
            ? currentEndpoint.allowDirectMessages
            : nonDirectDestinationAllowed(currentEndpoint, currentResource));
        if (!destinationAllowed) {
          const filteredAt = new Date();
          // A verified deletion or authorized edit still revokes the exactly
          // linked source while reach is disabled. Re-enabling access must not
          // revive stale files. Keep only the invalidation, never the new
          // content: no task comment, attachment import or wake is allowed.
          const retainInvalidation =
            currentConversation !== null &&
            (activeDelivery.eventKind === "message_deleted" ||
              (activeDelivery.eventKind === "message_updated" &&
                lifecyclePrincipalId !== null));
          await tx
            .update(chatDeliveries)
            .set({
              state: retainInvalidation ? "processed" : "filtered",
              ...(retainInvalidation
                ? {
                    conversationId: currentConversation.id,
                    principalId: lifecyclePrincipalId,
                  }
                : {}),
              normalizedEvent: {
                providerEventId:
                  activeDelivery.normalizedEvent.providerEventId ??
                  activeDelivery.providerEventId,
                kind: activeDelivery.eventKind,
                ...(retainInvalidation
                  ? {
                      runtimeContext: {
                        generation: admittedRuntimeContext.generation,
                        credentialFingerprint:
                          admittedRuntimeContext.credentialFingerprint,
                      },
                    }
                  : {}),
                conversation: { externalThreadId: lifecycle.threadId },
                message: {
                  providerMessageId: lifecycle.messageId,
                  targetProviderEventId: lifecycle.targetProviderEventId,
                  ...(retainInvalidation
                    ? { providerSentAt: lifecycle.providerSentAt }
                    : {}),
                },
                filtering: { contentRetained: false },
              },
              nextAttemptAt: null,
              processedAt: filteredAt,
              redactedError: retainInvalidation
                ? activeDelivery.eventKind === "message_deleted"
                  ? "Provider deletion retained without task content while destination access is disabled"
                  : "Provider edit invalidation retained without task content while destination access is disabled"
                : "Destination is no longer enabled for message lifecycle events",
              updatedAt: filteredAt,
            })
            .where(
              and(
                eq(chatDeliveries.id, activeDelivery.id),
                eq(chatDeliveries.state, "processing"),
              ),
            );
          return;
        }

        await issuesSvc.addComment(
          linkedTarget.issueId,
          lifecycle.text,
          {},
          { authorType: "system" },
          tx,
        );
        await tx
          .update(chatDeliveries)
          .set({
            conversationId: linkedTarget.conversationId,
            principalId: lifecyclePrincipalId,
            state: "processed",
            processedAt: new Date(),
            redactedError: null,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatDeliveries.id, activeDelivery.id),
              eq(chatDeliveries.state, "processing"),
            ),
          );
      });
    } catch (error) {
      const terminal = activeDelivery.attempts >= 5;
      await db
        .update(chatDeliveries)
        .set({
          state: terminal ? "failed" : "retry",
          nextAttemptAt: terminal
            ? null
            : new Date(
                Date.now() +
                  Math.min(60_000, 1000 * 2 ** activeDelivery.attempts),
              ),
          redactedError: redactError(error),
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, activeDelivery.id),
            eq(chatDeliveries.state, "processing"),
          ),
        );
      throw error;
    }
  }

  async function handleMessageUpdated(
    event: ChatSdkMessageUpdatedCallbackEvent,
    runtimeContext: RuntimeContext,
  ) {
    if (
      event.provider === "discord" &&
      !(await ensureDiscordGatewayRuntimeIsCurrent(
        event.endpointId,
        runtimeContext,
      ))
    ) {
      return;
    }
    const text = `An external message was edited:\n\n${event.message.text.slice(0, MAX_INBOUND_TEXT)}`;
    const telegramRich =
      event.provider === "telegram"
        ? normalizeTelegramRichMessage(event.message.raw)
        : null;
    await recordLifecycleDelivery(
      {
        actor: lifecycleActorFromAuthor(
          event.provider,
          event.message.author,
          event.message.raw,
        ),
        endpointId: event.endpointId,
        threadId: event.thread.id,
        messageId: event.message.id,
        eventKind: "message_updated",
        text,
        providerMessageSequence:
          event.provider === "telegram"
            ? telegramMessageSequence(event.message.raw)
            : null,
        providerSentAt:
          (
            event.message.metadata.editedAt ?? event.message.metadata.dateSent
          )?.toISOString() ?? null,
        raw: event.message.raw,
        revision: `${event.message.metadata.editedAt?.toISOString() ?? "unknown"}:${createHash("sha256").update(event.message.text).digest("hex")}${event.provider === "slack" ? `:${slackLifecycleFilesDigest(event.message.raw)}` : event.provider === "discord" ? `:${discordLifecycleFilesDigest(event.message.raw)}` : telegramRich ? `:${telegramRich.mediaDigest}` : ""}`,
      },
      runtimeContext,
    );
  }

  async function handleMessageDeleted(
    event: ChatSdkCallbackEvent<MessageDeletedEvent>,
    runtimeContext: RuntimeContext,
  ) {
    if (
      event.provider === "discord" &&
      !(await ensureDiscordGatewayRuntimeIsCurrent(
        event.endpointId,
        runtimeContext,
      ))
    ) {
      return;
    }
    await recordLifecycleDelivery(
      {
        endpointId: event.endpointId,
        threadId: event.event.threadId,
        messageId: event.event.messageId,
        eventKind: "message_deleted",
        text: "An external message in this conversation was deleted.",
        providerSentAt: event.event.deletedAt?.toISOString() ?? null,
        raw: event.event.raw,
        revision: event.event.deletedAt?.toISOString() ?? null,
      },
      runtimeContext,
    );
  }

  function reactionConversationThreadCondition(
    provider: ChatProvider,
    threadId: string,
  ): SQL | undefined {
    const exact = externalThreadIdentityCondition(
      sql<string>`${chatConversations.externalThreadId}`,
      threadId,
    );
    const slackDmChannel =
      provider === "slack" ? slackThreadChannelId(threadId) : null;
    return slackDmChannel && /^D[A-Z0-9-]*$/i.test(slackDmChannel)
      ? or(
          exact,
          and(
            eq(chatConversations.isDirectMessage, true),
            eq(chatConversations.externalThreadId, `slack:${slackDmChannel}:`),
          ),
        )
      : exact;
  }

  async function reactionConversationForMessage(
    database: DbOrTransaction,
    endpoint: EndpointRow,
    threadId: string,
    providerMessageId: string,
    direction?: "outbound",
  ): Promise<ConversationRow | null> {
    return database
      .select({ conversation: chatConversations })
      .from(chatMessageLinks)
      .innerJoin(
        chatConversations,
        and(
          eq(chatConversations.companyId, chatMessageLinks.companyId),
          eq(chatConversations.endpointId, chatMessageLinks.endpointId),
          eq(chatConversations.id, chatMessageLinks.conversationId),
        ),
      )
      .where(
        and(
          eq(chatMessageLinks.companyId, endpoint.companyId),
          eq(chatMessageLinks.endpointId, endpoint.id),
          eq(chatMessageLinks.providerMessageId, providerMessageId),
          direction ? eq(chatMessageLinks.direction, direction) : undefined,
          reactionConversationThreadCondition(endpoint.provider, threadId),
        ),
      )
      .orderBy(desc(chatConversations.sessionGeneration))
      .limit(1)
      .then((rows) => rows[0]?.conversation ?? null);
  }

  async function lockReactionConversationForMessage(
    tx: DbTransaction,
    endpoint: EndpointRow,
    threadId: string,
    providerMessageId: string,
    direction?: "outbound",
  ): Promise<ConversationRow | null> {
    const candidate = await reactionConversationForMessage(
      tx,
      endpoint,
      threadId,
      providerMessageId,
      direction,
    );
    if (!candidate) return null;
    const current = await tx
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, endpoint.companyId),
          eq(chatConversations.endpointId, endpoint.id),
          eq(chatConversations.id, candidate.id),
        ),
      )
      // Publication settlement inserts the outbound message link before it
      // updates the endpoint. NO KEY UPDATE serializes state changes while
      // remaining compatible with that link's conversation FK KEY SHARE.
      .for("no key update")
      .then((rows) => rows[0] ?? null);
    if (
      !current ||
      !(current.isDirectMessage
        ? ["active", "waiting", "completed"].includes(current.state)
        : ["active", "waiting"].includes(current.state))
    ) {
      return null;
    }
    const linkStillExists = await tx
      .select({ id: chatMessageLinks.id })
      .from(chatMessageLinks)
      .where(
        and(
          eq(chatMessageLinks.companyId, endpoint.companyId),
          eq(chatMessageLinks.endpointId, endpoint.id),
          eq(chatMessageLinks.conversationId, current.id),
          eq(chatMessageLinks.providerMessageId, providerMessageId),
          direction ? eq(chatMessageLinks.direction, direction) : undefined,
        ),
      )
      .limit(1)
      .then((rows) => rows.length > 0);
    return linkStillExists ? current : null;
  }

  async function streamingReactionConversation(
    database: DbOrTransaction,
    endpoint: EndpointRow,
    threadId: string,
  ): Promise<ConversationRow | null> {
    const candidates = await database
      .selectDistinct({
        conversation: chatConversations,
        sessionGeneration: chatConversations.sessionGeneration,
      })
      .from(chatConversations)
      .innerJoin(
        chatPublications,
        and(
          eq(chatPublications.companyId, chatConversations.companyId),
          eq(chatPublications.endpointId, chatConversations.endpointId),
          eq(chatPublications.conversationId, chatConversations.id),
        ),
      )
      .where(
        and(
          eq(chatConversations.companyId, endpoint.companyId),
          eq(chatConversations.endpointId, endpoint.id),
          or(
            inArray(chatConversations.state, ["active", "waiting"]),
            and(
              eq(chatConversations.isDirectMessage, true),
              eq(chatConversations.state, "completed"),
            ),
          ),
          reactionConversationThreadCondition(endpoint.provider, threadId),
          eq(chatPublications.state, "streaming"),
        ),
      )
      .orderBy(desc(chatConversations.sessionGeneration))
      .limit(2);
    if (candidates.length !== 1) return null;
    return candidates[0]!.conversation;
  }

  async function lockStreamingReactionConversation(
    tx: DbTransaction,
    endpoint: EndpointRow,
    threadId: string,
  ): Promise<ConversationRow | null> {
    const candidate = await streamingReactionConversation(
      tx,
      endpoint,
      threadId,
    );
    if (!candidate) return null;
    const current = await tx
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, endpoint.companyId),
          eq(chatConversations.endpointId, endpoint.id),
          eq(chatConversations.id, candidate.id),
          or(
            inArray(chatConversations.state, ["active", "waiting"]),
            and(
              eq(chatConversations.isDirectMessage, true),
              eq(chatConversations.state, "completed"),
            ),
          ),
        ),
      )
      // Keep the same lock strength/order as the exact-link path above so an
      // in-flight message-link insert cannot deadlock reaction admission.
      .for("no key update")
      .then((rows) => rows[0] ?? null);
    if (!current) return null;
    const stillStreaming = await tx
      .select({ id: chatPublications.id })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, endpoint.companyId),
          eq(chatPublications.endpointId, endpoint.id),
          eq(chatPublications.conversationId, current.id),
          eq(chatPublications.state, "streaming"),
        ),
      )
      .limit(1)
      .then((rows) => rows.length > 0);
    return stillStreaming ? current : null;
  }

  async function authorizeReactionConversation(
    tx: DbTransaction,
    endpoint: EndpointRow,
    conversation: ConversationRow,
    principalId: string,
  ): Promise<boolean> {
    const resource =
      conversation.resourceId && !conversation.isDirectMessage
        ? await tx
            .select()
            .from(chatEndpointResources)
            .where(
              and(
                eq(chatEndpointResources.companyId, endpoint.companyId),
                eq(chatEndpointResources.endpointId, endpoint.id),
                eq(chatEndpointResources.id, conversation.resourceId),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;
    const destinationAllowed = conversation.isDirectMessage
      ? endpoint.allowDirectMessages
      : nonDirectDestinationAllowed(endpoint, resource);
    if (!destinationAllowed) return false;
    return (await lockCurrentPrincipalAuthorization(tx, endpoint, principalId))
      .allowed;
  }

  async function handleReaction(
    event: ChatSdkCallbackEvent<ReactionEvent>,
    runtimeContext: RuntimeContext,
  ) {
    const record = await runtimeCallbackRecord(
      event.endpointId,
      runtimeContext,
      ["active"],
    );
    if (
      !record ||
      record.endpoint.status !== "active" ||
      record.endpoint.provider !== event.provider ||
      record.endpoint.capabilities.reactions !== true ||
      event.event.user.isMe ||
      event.event.user.isBot === true ||
      event.event.user.isSystem
    ) {
      return;
    }
    // A DM can have a newer task generation while this reaction still belongs
    // to an older linked message. Resolve its exact lineage before choosing a
    // generation; never attach it to the latest task merely sharing the chat.
    // A just-sent provider message can be visible before its publication/link
    // transaction commits. Only that exact thread's streaming publication is
    // enough evidence to stage an otherwise-unbound reaction for replay.
    let conversation = await reactionConversationForMessage(
      db,
      record.endpoint,
      event.event.threadId,
      event.event.messageId,
    );
    await options.reactionLinkPreflightBarrier?.();
    const plausibleStreamingConversation = conversation
      ? null
      : await streamingReactionConversation(
          db,
          record.endpoint,
          event.event.threadId,
        );
    if (!conversation && !plausibleStreamingConversation) {
      // Settlement can commit between the first exact-link lookup and the
      // streaming-publication lookup. Recheck the durable link before treating
      // the callback as an arbitrary unknown message.
      conversation = await reactionConversationForMessage(
        db,
        record.endpoint,
        event.event.threadId,
        event.event.messageId,
      );
      if (!conversation) return;
    }

    const principal = await ensurePrincipal(
      record.endpoint,
      event.event.user,
      event.event.raw,
    );
    let rawFingerprint: string;
    try {
      rawFingerprint = createHash("sha256")
        .update(JSON.stringify(event.event.raw ?? null))
        .digest("hex")
        .slice(0, 24);
    } catch {
      rawFingerprint = "unavailable";
    }
    const eventKind: ChatEventKind = event.event.added
      ? "reaction_added"
      : "reaction_removed";
    const providerEventId = [
      eventKind,
      durableExternalThreadIdentity(event.event.threadId),
      event.event.messageId,
      stableExternalPrincipalId(
        record.endpoint.provider,
        event.event.user,
        event.event.raw,
      ),
      event.event.rawEmoji,
      rawFingerprint,
    ].join(":");
    const normalizedEvent = {
      providerEventId,
      kind: eventKind,
      conversation: { externalThreadId: event.event.threadId },
      message: { providerMessageId: event.event.messageId },
      reaction: {
        emoji: event.event.emoji.name,
        rawEmoji: event.event.rawEmoji,
        added: event.event.added,
      },
      runtimeContext: {
        generation: runtimeContext.generation,
        credentialFingerprint: runtimeContext.credentialFingerprint,
      },
    };
    const admitted = await db.transaction(async (tx) => {
      const currentEndpoint = await runtimeCallbackEndpoint(
        tx,
        event.endpointId,
        runtimeContext,
        ["active"],
      );
      if (!currentEndpoint) return false;
      const linkedConversation = await lockReactionConversationForMessage(
        tx,
        currentEndpoint,
        event.event.threadId,
        event.event.messageId,
      );
      const currentConversation =
        linkedConversation ??
        (await lockStreamingReactionConversation(
          tx,
          currentEndpoint,
          event.event.threadId,
        ));
      if (
        !currentConversation ||
        !(await authorizeReactionConversation(
          tx,
          currentEndpoint,
          currentConversation,
          principal.principal.id,
        ))
      ) {
        return false;
      }
      const now = new Date();
      if (linkedConversation) {
        const expiryCutoff = new Date(now.getTime() - REACTION_LINK_MAX_AGE_MS);
        const hasOutboundLink = await tx
          .select({ id: chatMessageLinks.id })
          .from(chatMessageLinks)
          .where(
            and(
              eq(chatMessageLinks.companyId, currentEndpoint.companyId),
              eq(chatMessageLinks.endpointId, currentEndpoint.id),
              eq(chatMessageLinks.conversationId, linkedConversation.id),
              eq(chatMessageLinks.providerMessageId, event.event.messageId),
              eq(chatMessageLinks.direction, "outbound"),
            ),
          )
          .limit(1)
          .then((rows) => rows.length > 0);
        const reconciled = hasOutboundLink
          ? await tx
              .update(chatDeliveries)
              .set({
                conversationId: linkedConversation.id,
                state: "processed",
                attempts: sql`${chatDeliveries.attempts} + 1`,
                nextAttemptAt: null,
                processedAt: now,
                redactedError: null,
                updatedAt: now,
              })
              .where(
                and(
                  eq(chatDeliveries.endpointId, currentEndpoint.id),
                  eq(chatDeliveries.providerEventId, providerEventId),
                  inArray(chatDeliveries.state, ["received", "retry"]),
                  gt(chatDeliveries.receivedAt, expiryCutoff),
                  lt(chatDeliveries.attempts, REACTION_LINK_MAX_ATTEMPTS),
                  sql`${chatDeliveries.normalizedEvent}->'runtimeContext'->>'generation' = ${String(runtimeContext.generation)}`,
                  sql`${chatDeliveries.normalizedEvent}->'runtimeContext'->>'credentialFingerprint' = ${runtimeContext.credentialFingerprint}`,
                ),
              )
              .returning({ id: chatDeliveries.id })
          : [];
        if (reconciled.length > 0) return true;
        const expired = await tx
          .update(chatDeliveries)
          .set({
            state: "filtered",
            nextAttemptAt: null,
            processedAt: now,
            redactedError:
              "Reaction target did not become linked before replay expiry",
            updatedAt: now,
          })
          .where(
            and(
              eq(chatDeliveries.endpointId, currentEndpoint.id),
              eq(chatDeliveries.providerEventId, providerEventId),
              inArray(chatDeliveries.state, ["received", "retry"]),
              or(
                lte(chatDeliveries.receivedAt, expiryCutoff),
                gte(chatDeliveries.attempts, REACTION_LINK_MAX_ATTEMPTS),
              ),
              sql`${chatDeliveries.normalizedEvent}->'runtimeContext'->>'generation' = ${String(runtimeContext.generation)}`,
              sql`${chatDeliveries.normalizedEvent}->'runtimeContext'->>'credentialFingerprint' = ${runtimeContext.credentialFingerprint}`,
            ),
          )
          .returning({ id: chatDeliveries.id });
        if (expired.length > 0) return false;
      }
      const inserted = await tx
        .insert(chatDeliveries)
        .values({
          companyId: currentEndpoint.companyId,
          endpointId: currentEndpoint.id,
          conversationId: linkedConversation?.id ?? null,
          principalId: principal.principal.id,
          providerEventId,
          deduplicationKey: createHash("sha256")
            .update(providerEventId)
            .digest("hex"),
          eventKind,
          normalizedEvent,
          state: linkedConversation ? "processed" : "received",
          attempts: linkedConversation ? 1 : 0,
          nextAttemptAt: linkedConversation
            ? null
            : new Date(now.getTime() + REACTION_LINK_RETRY_DELAY_MS),
          processedAt: linkedConversation ? now : null,
        })
        .onConflictDoNothing()
        .returning({ id: chatDeliveries.id });
      if (inserted.length > 0) return true;
      return tx
        .select({ id: chatDeliveries.id })
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.endpointId, currentEndpoint.id),
            eq(chatDeliveries.providerEventId, providerEventId),
            inArray(chatDeliveries.state, ["received", "retry", "processed"]),
          ),
        )
        .limit(1)
        .then((rows) => rows.length > 0);
    });
    if (admitted) {
      await recordCurrentMicrosoftTeamsRoute(
        record.endpoint,
        runtimeContext,
        event.event.threadId,
        event.event.raw,
      );
    }
  }

  async function denyExternalAction(
    endpoint: EndpointRow,
    event: ChatSdkCallbackEvent<ActionEvent>,
    runtimeContext: LifecycleRuntimeFence,
    safelyKnown: {
      conversationId?: string | null;
      principalId?: string | null;
    } = {},
  ): Promise<void> {
    const telegramCallback =
      endpoint.provider === "telegram" && endpoint.botExternalId
        ? readTelegramCallbackProvenance(event.telegramCallback, {
            companyId: endpoint.companyId,
            endpointId: endpoint.id,
            botUserId: endpoint.botExternalId,
            threadId: event.event.threadId,
            messageId: event.event.messageId,
            userId: event.event.user.userId,
          })
        : null;
    const fingerprint = createHash("sha256")
      .update(
        JSON.stringify(
          telegramCallback
            ? [
                endpoint.id,
                "telegram_callback_denial",
                telegramCallback.botUserId,
                telegramCallback.callbackId,
              ]
            : [
                endpoint.id,
                event.provider,
                event.event.threadId,
                event.event.messageId,
                event.event.user.userId,
                event.event.actionId,
                event.event.triggerId ?? null,
              ],
        ),
      )
      .digest("hex");
    const providerEventId = `action-denied:${fingerprint}`;
    const processedAt = new Date();
    const actionThread = event.event.thread;
    const effectPayload =
      actionThread &&
      typeof actionThread.postEphemeral === "function" &&
      CAPABILITIES[endpoint.provider].ephemeralMessages
        ? ({
            version: 1,
            effect: "ephemeral_message",
            authorizationMode: "safe_notice",
            threadId: event.event.threadId,
            userId: event.event.user.userId,
            text: "This action is no longer available. Open the linked Paperclip task or ask an operator to link this account.",
            fallbackText: "This Paperclip action is no longer available.",
            settleDelivery: false,
          } as const)
        : null;
    let effect: typeof chatActions.$inferSelect | null = null;
    try {
      effect = await db.transaction(async (tx) => {
        const currentEndpoint = telegramCallback
          ? await runtimeCallbackEndpoint(tx, endpoint.id, runtimeContext, [
              "active",
            ])
          : null;
        const telegramAuthorizationSha256 =
          currentEndpoint && telegramCallback
            ? await lockTelegramCallbackNoticeAuthority(
                tx,
                currentEndpoint,
                telegramCallback,
                safelyKnown.principalId ?? null,
              )
            : null;
        const [inserted] = await tx
          .insert(chatDeliveries)
          .values({
            companyId: endpoint.companyId,
            endpointId: endpoint.id,
            conversationId: safelyKnown.conversationId ?? null,
            principalId: safelyKnown.principalId ?? null,
            providerEventId,
            deduplicationKey: fingerprint,
            eventKind: "action",
            normalizedEvent: {
              providerEventId,
              kind: "action",
              authorization: { outcome: "denied" },
              ...(telegramCallback
                ? { telegramCallback, telegramAuthorizationSha256 }
                : {}),
            },
            state: "filtered",
            attempts: 1,
            redactedError: "External action denied by Paperclip authorization",
            processedAt,
            updatedAt: processedAt,
          })
          .onConflictDoNothing()
          .returning();
        const notice: Omit<
          ProviderEffectPayload,
          "runtimeGeneration" | "credentialFingerprint"
        > | null =
          telegramCallback && telegramAuthorizationSha256
            ? {
                version: 1,
                effect: "telegram_callback_notice",
                authorizationMode: "safe_notice",
                telegramCallback,
                telegramAuthorizationSha256,
                threadId: telegramCallbackThreadId(telegramCallback),
                userId: telegramCallback.receiverUserId,
                text: TELEGRAM_PRIVATE_ACTION_UNAVAILABLE,
                settleDelivery: false,
              }
            : effectPayload;
        if (!inserted || !notice) return null;
        return stageProviderEffect(tx, {
          endpoint,
          deliveryId: inserted.id,
          conversationId: safelyKnown.conversationId ?? null,
          principalId: safelyKnown.principalId ?? null,
          providerActionId: `provider_effect:${providerEventId}`,
          payload: notice,
          runtimeContext,
        });
      });
    } catch (error) {
      logger.warn(
        {
          endpointId: endpoint.id,
          provider: endpoint.provider,
          error: redactError(error),
        },
        "could not record denied external chat action",
      );
      // Provider retries are useful only while the authoritative denial could
      // not be recorded. Once the filtered delivery exists, a policy denial
      // is a successfully handled webhook and must not be surfaced as a
      // callback failure (which the Chat SDK correctly converts to a 503).
      throw error;
    }
    if (effect && actionThread) {
      // The callback is acknowledged after the authoritative denial and its
      // provider effect are durable. Slow provider I/O runs out of band; a
      // redelivery finds the same action and cannot enqueue another notice.
      scheduleProviderEffect(effect.id, actionThread);
    }
  }

  async function recordModalOpenFailure(
    endpoint: EndpointRow,
    event: ChatSdkCallbackEvent<ActionEvent>,
    runtimeContext: LifecycleRuntimeFence,
    safelyKnown: {
      attemptActionId?: string | null;
      conversationId?: string | null;
      principalId?: string | null;
      resource?: ResourceRow | null;
    },
    error: unknown,
  ): Promise<void> {
    const disposition = classifyChatPublicationError(error, 1);
    const fingerprint = createHash("sha256")
      .update(
        JSON.stringify([
          endpoint.id,
          event.provider,
          "modal_open",
          event.event.triggerId ?? null,
          event.event.threadId,
          event.event.messageId,
          event.event.user.userId,
          event.event.actionId,
        ]),
      )
      .digest("hex");
    const providerEventId = `modal-open-failed:${fingerprint}`;
    const failure = redactError(error);
    const processedAt = new Date();
    const actionThread = event.event.thread;
    const effectPayload =
      actionThread &&
      typeof actionThread.postEphemeral === "function" &&
      CAPABILITIES[endpoint.provider].ephemeralMessages
        ? ({
            version: 1,
            effect: "ephemeral_message",
            authorizationMode: "safe_notice",
            threadId: event.event.threadId,
            userId: event.event.user.userId,
            text: "Paperclip could not open this form. Try the action again or open the linked Paperclip task.",
            fallbackText: "Paperclip could not open this form.",
            settleDelivery: false,
          } as const)
        : null;
    let effect: typeof chatActions.$inferSelect | null = null;
    let invalidateEndpointRuntime = false;
    try {
      effect = await db.transaction(async (tx) => {
        const [inserted] = await tx
          .insert(chatDeliveries)
          .values({
            companyId: endpoint.companyId,
            endpointId: endpoint.id,
            conversationId: safelyKnown.conversationId ?? null,
            principalId: safelyKnown.principalId ?? null,
            providerEventId,
            deduplicationKey: fingerprint,
            eventKind: "action",
            normalizedEvent: {
              providerEventId,
              kind: "action",
              modal: {
                phase: "open",
                outcome: "failed",
                disposition: disposition.kind,
              },
            },
            // Modal callbacks are acknowledged after this audit row commits.
            // They must never enter the replayable inbound-delivery queue.
            state: "filtered",
            attempts: 1,
            redactedError: `Provider modal open failed: ${failure}`.slice(
              0,
              MAX_ERROR_TEXT,
            ),
            processedAt,
            updatedAt: processedAt,
          })
          .onConflictDoNothing()
          .returning();
        if (!inserted) return null;

        if (safelyKnown.attemptActionId) {
          await tx
            .update(chatActions)
            .set({
              status: "failed",
              result: {
                code: `question_form_open_${disposition.kind}`,
                retryable: false,
              },
              updatedAt: processedAt,
            })
            .where(
              and(
                eq(chatActions.id, safelyKnown.attemptActionId),
                eq(chatActions.status, "processing"),
              ),
            );
        }

        if (disposition.kind === "endpoint_attention") {
          const currentEndpoint = await runtimeCallbackEndpoint(
            tx,
            endpoint.id,
            runtimeContext,
            ["active"],
          );
          if (currentEndpoint) {
            await tx
              .update(chatEndpoints)
              .set({
                status: "attention",
                healthMessage:
                  "Provider credentials or permissions need attention",
                lastError: failure,
                updatedAt: processedAt,
              })
              .where(eq(chatEndpoints.id, endpoint.id));
            await tx
              .update(toolConnections)
              .set({
                status: "disabled",
                enabled: false,
                healthStatus: "degraded",
                healthMessage:
                  "Provider credentials or permissions need attention",
                lastError: failure,
                healthCheckedAt: processedAt,
                updatedAt: processedAt,
              })
              .where(eq(toolConnections.id, endpoint.connectionId));
            invalidateEndpointRuntime = true;
          }
        } else if (
          disposition.kind === "resource_unavailable" &&
          safelyKnown.resource
        ) {
          await tx
            .update(chatEndpointResources)
            .set({ availability: "unavailable", updatedAt: processedAt })
            .where(
              and(
                eq(chatEndpointResources.companyId, endpoint.companyId),
                eq(chatEndpointResources.endpointId, endpoint.id),
                eq(chatEndpointResources.id, safelyKnown.resource.id),
              ),
            );
        }

        if (!effectPayload) return null;
        return stageProviderEffect(tx, {
          endpoint,
          deliveryId: inserted.id,
          conversationId: safelyKnown.conversationId ?? null,
          principalId: safelyKnown.principalId ?? null,
          providerActionId: `provider_effect:${providerEventId}`,
          payload: effectPayload,
          runtimeContext,
        });
      });
    } catch (auditError) {
      logger.warn(
        {
          endpointId: endpoint.id,
          provider: endpoint.provider,
          error: redactError(auditError),
        },
        "could not record external chat modal-open failure",
      );
      throw auditError;
    }
    if (effect && actionThread) scheduleProviderEffect(effect.id, actionThread);
    if (invalidateEndpointRuntime) {
      await invalidateRuntime(endpoint.id).catch(() => undefined);
    }
  }

  async function recordModalSubmitDenial(
    endpoint: EndpointRow,
    event: ChatSdkCallbackEvent<ModalSubmitEvent>,
    input: {
      code: string;
      conversationId?: string | null;
      principalId?: string | null;
    },
    database: DbOrTransaction = db,
  ): Promise<void> {
    const fingerprint = createHash("sha256")
      .update(
        JSON.stringify([
          endpoint.id,
          event.provider,
          "modal_submit",
          event.event.callbackId,
          event.event.viewId,
          event.event.user.userId,
          input.code,
        ]),
      )
      .digest("hex");
    const providerEventId = `modal-submit-denied:${fingerprint}`;
    const processedAt = new Date();
    try {
      await database
        .insert(chatDeliveries)
        .values({
          companyId: endpoint.companyId,
          endpointId: endpoint.id,
          conversationId: input.conversationId ?? null,
          principalId: input.principalId ?? null,
          providerEventId,
          deduplicationKey: fingerprint,
          eventKind: "action",
          normalizedEvent: {
            providerEventId,
            kind: "action",
            authorization: { outcome: "denied" },
            modal: {
              phase: "submit",
              outcome: "denied",
              code: input.code,
            },
          },
          state: "filtered",
          attempts: 1,
          redactedError: "External chat modal submission denied by Paperclip",
          processedAt,
          updatedAt: processedAt,
        })
        .onConflictDoNothing();
    } catch (error) {
      logger.warn(
        {
          endpointId: endpoint.id,
          provider: endpoint.provider,
          error: redactError(error),
        },
        "could not record denied external chat modal submission",
      );
      throw error;
    }
  }

  async function settleTerminalConfirmationAction(
    actionId: string,
  ): Promise<boolean> {
    const action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "confirmation_response"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (action?.status === "processed") return true;
    if (!action || action.status !== "processing" || !action.conversationId)
      return false;
    const token = action.payload;
    if (
      token.version !== 1 ||
      typeof token.publicationId !== "string" ||
      typeof token.interactionId !== "string" ||
      (token.decision !== "accept" && token.decision !== "reject")
    ) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: { code: "confirmation_action_payload_invalid" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        );
      return false;
    }
    const [conversation, publication, endpoint] = await Promise.all([
      db
        .select()
        .from(chatConversations)
        .where(
          and(
            eq(chatConversations.companyId, action.companyId),
            eq(chatConversations.endpointId, action.endpointId),
            eq(chatConversations.id, action.conversationId),
          ),
        )
        .then((rows) => rows[0] ?? null),
      db
        .select()
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, action.companyId),
            eq(chatPublications.endpointId, action.endpointId),
            eq(chatPublications.id, token.publicationId as string),
          ),
        )
        .then((rows) => rows[0] ?? null),
      db
        .select()
        .from(chatEndpoints)
        .where(
          and(
            eq(chatEndpoints.companyId, action.companyId),
            eq(chatEndpoints.id, action.endpointId),
          ),
        )
        .then((rows) => rows[0] ?? null),
    ]);
    if (
      !conversation ||
      !publication ||
      !endpoint ||
      endpoint.provider !== "telegram" ||
      publication.conversationId !== conversation.id ||
      publication.payload.interactionId !== token.interactionId
    ) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: { code: "confirmation_action_binding_invalid" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        );
      return false;
    }
    const interaction = (
      await issueThreadInteractionService(db).listForIssue(conversation.issueId)
    ).find((candidate) => candidate.id === token.interactionId);
    if (
      !interaction ||
      interaction.kind !== "request_confirmation" ||
      !nativeTelegramConfirmation(interaction)
    ) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: { code: "confirmation_interaction_invalid" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        );
      return false;
    }
    if (
      interaction.status !== "accepted" &&
      interaction.status !== "rejected"
    ) {
      if (interaction.status === "pending") return false;
      const [retired] = await db
        .update(chatActions)
        .set({
          status: "expired",
          result: {
            code: "confirmation_interaction_resolved_elsewhere",
            interactionId: interaction.id,
            interactionStatus: interaction.status,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        )
        .returning({ id: chatActions.id });
      if (retired) return true;
      const winner = await db
        .select({ status: chatActions.status })
        .from(chatActions)
        .where(eq(chatActions.id, action.id))
        .then((rows) => rows[0] ?? null);
      return winner?.status === "expired" || winner?.status === "processed";
    }
    const decisionMatches =
      (token.decision === "accept" && interaction.status === "accepted") ||
      (token.decision === "reject" && interaction.status === "rejected");
    if (!decisionMatches) {
      await db
        .update(chatActions)
        .set({
          status: "expired",
          result: { code: "interaction_resolved_by_sibling_action" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        );
      return false;
    }
    const issue = await db
      .select({
        id: issues.id,
        companyId: issues.companyId,
        assigneeAgentId: issues.assigneeAgentId,
        status: issues.status,
      })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, action.companyId),
          eq(issues.id, conversation.issueId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!issue || !interaction.resolvedByUserId) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: { code: "confirmation_resolution_context_missing" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        );
      return false;
    }
    const resolvedByUserId = interaction.resolvedByUserId;
    const shouldWake =
      Boolean(issue.assigneeAgentId) &&
      issue.status !== "done" &&
      issue.status !== "cancelled" &&
      (interaction.continuationPolicy === "wake_assignee" ||
        (interaction.continuationPolicy === "wake_assignee_on_accept" &&
          interaction.status === "accepted"));
    const resolutionLabel =
      interaction.status === "accepted" ? "Accepted" : "Rejected";
    const resolvedByThisProviderAction =
      action.result?.code === "confirmation_resolution_committed_by_provider";
    return db.transaction(async (tx) => {
      const [completed] = await tx
        .update(chatActions)
        .set({
          status: "processed",
          result: {
            code: resolvedByThisProviderAction
              ? "confirmation_resolution_committed_by_provider"
              : "confirmation_resolution_reconciled",
            interactionId: interaction.id,
            interactionStatus: interaction.status,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
          ),
        )
        .returning({ id: chatActions.id });
      if (!completed) {
        // A publication sweep may reconcile the durable action while the
        // original provider callback is still in flight. Treat that CAS loss
        // as success once the winner has processed the same action so the
        // provider does not receive a spurious 5xx and redeliver it.
        const winner = await tx
          .select({ status: chatActions.status })
          .from(chatActions)
          .where(eq(chatActions.id, action.id))
          .then((rows) => rows[0] ?? null);
        return winner?.status === "processed";
      }
      await tx
        .update(chatActions)
        .set({
          status: "expired",
          result: { code: "interaction_resolved_by_sibling_action" },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.companyId, issue.companyId),
            eq(chatActions.endpointId, action.endpointId),
            eq(chatActions.conversationId, conversation.id),
            eq(chatActions.kind, "confirmation_response"),
            inArray(chatActions.status, ["issued", "processing"]),
            ne(chatActions.id, action.id),
            eq(
              sql<string>`${chatActions.payload}->>'interactionId'`,
              interaction.id,
            ),
          ),
        );
      await tx
        .insert(chatPublications)
        .values({
          companyId: issue.companyId,
          endpointId: action.endpointId,
          conversationId: conversation.id,
          issueId: issue.id,
          idempotencyKey: `interaction-resolution:${interaction.id}:${action.endpointId}`,
          payload: projectSafeChatPublication({
            classification: "external",
            source: "issue_interaction",
            text: `${resolutionLabel}: ${interaction.payload.prompt}`,
            interaction: {
              id: interaction.id,
              card: {
                kind: "confirmation",
                title: interaction.payload.prompt,
                body: resolutionLabel,
                actions: [],
              },
            },
          }),
          state: "pending",
        })
        .onConflictDoNothing();
      if (shouldWake && issue.assigneeAgentId) {
        await tx
          .insert(chatActions)
          .values({
            companyId: issue.companyId,
            endpointId: action.endpointId,
            conversationId: conversation.id,
            principalId: action.principalId,
            kind: "interaction_wakeup",
            providerActionId: `interaction_wakeup:${interaction.id}`,
            payload: {
              version: 1,
              interactionId: interaction.id,
              interactionKind: interaction.kind,
              interactionStatus: interaction.status,
              issueId: issue.id,
              agentId: issue.assigneeAgentId,
              sourceCommentId: interaction.sourceCommentId ?? null,
              sourceRunId: interaction.sourceRunId ?? null,
              requestedByUserId: resolvedByUserId,
              requestedByActorType: "user",
              requestedByActorId: resolvedByUserId,
            },
            status: "issued",
          })
          .onConflictDoNothing();
      }
      // A provider callback can lose the pending -> terminal interaction race
      // to the Paperclip UI. In that case this transaction only retires the
      // now-redundant provider action and must not fabricate a second external
      // resolution event attributed to the board winner.
      if (resolvedByThisProviderAction) {
        await logActivity(tx as unknown as Db, {
          companyId: issue.companyId,
          actorType: "user",
          actorId: resolvedByUserId,
          action:
            interaction.status === "accepted"
              ? "issue.thread_interaction_accepted"
              : "issue.thread_interaction_rejected",
          entityType: "issue",
          entityId: issue.id,
          details: {
            source: "external_chat",
            endpointId: action.endpointId,
            provider: endpoint.provider,
            conversationId: conversation.id,
            publicationId: publication.id,
            providerMessageId: publication.providerMessageId,
            interactionId: interaction.id,
            interactionKind: interaction.kind,
            interactionStatus: interaction.status,
            resolutionActorKind: "user",
            requestedResolverPolicy: interaction.requestedResolverPolicy,
            effectiveResolverPolicy: interaction.effectiveResolverPolicy,
          },
        });
      }
      return true;
    });
  }

  async function reconcileTerminalConfirmationActions(
    limit = 100,
  ): Promise<number> {
    const candidates = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "confirmation_response"),
          eq(chatActions.status, "processing"),
        ),
      )
      .orderBy(asc(chatActions.updatedAt), asc(chatActions.id))
      .limit(limit);
    let settled = 0;
    for (const candidate of candidates) {
      if (await settleTerminalConfirmationAction(candidate.id)) settled += 1;
    }
    return settled;
  }

  async function processPendingInteractionWakeups(
    limit = 100,
  ): Promise<number> {
    const staleBefore = new Date(Date.now() - 30_000);
    const retryBefore = new Date(
      Date.now() - CONFIRMATION_WAKEUP_RETRY_BACKOFF_MS,
    );
    const candidates = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "interaction_wakeup"),
          or(
            and(
              eq(chatActions.status, "issued"),
              or(
                isNull(chatActions.result),
                lte(chatActions.updatedAt, retryBefore),
              ),
            ),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, staleBefore),
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.updatedAt), asc(chatActions.id))
      .limit(limit);
    let processed = 0;
    for (const candidate of candidates) {
      const [claimed] = await db
        .update(chatActions)
        .set({ status: "processing", updatedAt: new Date() })
        .where(
          and(
            eq(chatActions.id, candidate.id),
            or(
              and(
                eq(chatActions.status, "issued"),
                or(
                  isNull(chatActions.result),
                  lte(chatActions.updatedAt, retryBefore),
                ),
              ),
              and(
                eq(chatActions.status, "processing"),
                lte(chatActions.updatedAt, staleBefore),
              ),
            ),
          ),
        )
        .returning();
      if (!claimed) continue;
      const payload = claimed.payload;
      const requestedByActorType =
        payload.requestedByActorType === "user" ||
        payload.requestedByActorType === "agent" ||
        payload.requestedByActorType === "system"
          ? payload.requestedByActorType
          : typeof payload.requestedByUserId === "string"
            ? "user"
            : null;
      const requestedByActorId =
        typeof payload.requestedByActorId === "string"
          ? payload.requestedByActorId
          : typeof payload.requestedByUserId === "string"
            ? payload.requestedByUserId
            : null;
      if (
        payload.version !== 1 ||
        typeof payload.interactionId !== "string" ||
        typeof payload.interactionKind !== "string" ||
        !["accepted", "rejected", "answered", "cancelled", "failed"].includes(
          String(payload.interactionStatus),
        ) ||
        typeof payload.issueId !== "string" ||
        typeof payload.agentId !== "string" ||
        !requestedByActorType ||
        !requestedByActorId
      ) {
        await db
          .update(chatActions)
          .set({
            status: "failed",
            result: { code: "interaction_wakeup_payload_invalid" },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, claimed.id),
              eq(chatActions.status, "processing"),
            ),
          );
        continue;
      }
      const currentIssue = await db
        .select({
          assigneeAgentId: issues.assigneeAgentId,
          status: issues.status,
        })
        .from(issues)
        .where(
          and(
            eq(issues.companyId, claimed.companyId),
            eq(issues.id, payload.issueId),
          ),
        )
        .then((rows) => rows[0] ?? null);
      const currentInteraction = currentIssue
        ? (
            await issueThreadInteractionService(db).listForIssue(
              payload.issueId,
            )
          ).find((interaction) => interaction.id === payload.interactionId)
        : null;
      if (
        !currentIssue ||
        !currentInteraction ||
        currentInteraction.companyId !== claimed.companyId ||
        currentInteraction.kind !== payload.interactionKind ||
        currentInteraction.status !== payload.interactionStatus ||
        currentIssue.assigneeAgentId !== payload.agentId ||
        currentIssue.status === "done" ||
        currentIssue.status === "cancelled"
      ) {
        await db
          .update(chatActions)
          .set({
            status: "processed",
            result: { code: "interaction_wakeup_no_longer_applicable" },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, claimed.id),
              eq(chatActions.status, "processing"),
            ),
          );
        processed += 1;
        continue;
      }
      const idempotencyKey = `interaction:${payload.interactionId}:${payload.interactionStatus}`;
      try {
        const sourceCommentId = currentInteraction.sourceCommentId ?? null;
        const sourceRunId = currentInteraction.sourceRunId ?? null;
        // A resolved interaction is still part of the originating external
        // turn. Preserve one verified inbound comment edge on the continuation
        // run so queued/working/failure milestones return to this exact
        // endpoint and conversation instead of disappearing as an internal
        // automation run.
        const chatOrigin = claimed.conversationId
          ? await db
              .select({
                commentId: chatMessageLinks.commentId,
                provider: chatEndpoints.provider,
              })
              .from(chatEndpoints)
              .innerJoin(
                chatMessageLinks,
                and(
                  eq(chatMessageLinks.companyId, chatEndpoints.companyId),
                  eq(chatMessageLinks.endpointId, chatEndpoints.id),
                ),
              )
              .where(
                and(
                  eq(chatEndpoints.companyId, claimed.companyId),
                  eq(chatEndpoints.id, claimed.endpointId),
                  eq(chatMessageLinks.conversationId, claimed.conversationId),
                  eq(chatMessageLinks.direction, "inbound"),
                  isNotNull(chatMessageLinks.commentId),
                ),
              )
              .orderBy(
                desc(chatMessageLinks.createdAt),
                desc(chatMessageLinks.id),
              )
              .limit(1)
              .then((rows) => rows[0] ?? null)
          : null;
        const wakeCommentId = sourceCommentId ?? chatOrigin?.commentId ?? null;
        const existing = await db
          .select({
            agentId: agentWakeupRequests.agentId,
            id: agentWakeupRequests.id,
          })
          .from(agentWakeupRequests)
          .where(
            and(
              eq(agentWakeupRequests.companyId, claimed.companyId),
              eq(agentWakeupRequests.idempotencyKey, idempotencyKey),
              notInArray(agentWakeupRequests.status, [
                "skipped",
                "failed",
                "cancelled",
              ]),
            ),
          )
          .limit(1)
          .then((rows) => rows[0] ?? null);
        const queuedRun = !existing
          ? await options.heartbeat.wakeup(payload.agentId, {
              source: "automation",
              triggerDetail: "system",
              reason: "issue_commented",
              payload: {
                issueId: payload.issueId,
                interactionId: payload.interactionId,
                interactionKind: payload.interactionKind,
                interactionStatus: payload.interactionStatus,
                sourceCommentId,
                sourceRunId,
                ...(wakeCommentId
                  ? {
                      wakeCommentId,
                      wakeCommentIds: [wakeCommentId],
                    }
                  : {}),
                ...(payload.planReviewInteraction &&
                typeof payload.planReviewInteraction === "object"
                  ? { planReviewInteraction: payload.planReviewInteraction }
                  : {}),
                mutation: "interaction",
              },
              idempotencyKey,
              allowRunCoalescing: false,
              requestedByActorType,
              requestedByActorId,
              contextSnapshot: {
                issueId: payload.issueId,
                taskId: payload.issueId,
                interactionId: payload.interactionId,
                interactionKind: payload.interactionKind,
                interactionStatus: payload.interactionStatus,
                sourceCommentId,
                sourceRunId,
                ...(payload.planReviewInteraction &&
                typeof payload.planReviewInteraction === "object"
                  ? { planReviewInteraction: payload.planReviewInteraction }
                  : {}),
                wakeReason: "issue_commented",
                source: chatOrigin
                  ? `chat:${chatOrigin.provider}`
                  : "external_chat.interaction.resolve",
                ...(wakeCommentId
                  ? {
                      wakeCommentId,
                      wakeCommentIds: [wakeCommentId],
                    }
                  : {}),
                ...(payload.forceFreshSession === true
                  ? { forceFreshSession: true }
                  : {}),
                ...(typeof payload.workspaceRefreshReason === "string"
                  ? {
                      workspaceRefreshReason: payload.workspaceRefreshReason,
                    }
                  : {}),
              },
            })
          : null;
        const durable =
          existing ??
          (await db
            .select({
              agentId: agentWakeupRequests.agentId,
              id: agentWakeupRequests.id,
            })
            .from(agentWakeupRequests)
            .where(
              and(
                eq(agentWakeupRequests.companyId, claimed.companyId),
                eq(agentWakeupRequests.idempotencyKey, idempotencyKey),
                notInArray(agentWakeupRequests.status, [
                  "skipped",
                  "failed",
                  "cancelled",
                ]),
              ),
            )
            .limit(1)
            .then((rows) => rows[0] ?? null));
        if (!queuedRun && !durable) {
          await db
            .update(chatActions)
            .set({
              status: "issued",
              result: { code: "interaction_wakeup_deferred" },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, claimed.id),
                eq(chatActions.status, "processing"),
              ),
            );
          continue;
        }
        await db
          .update(chatActions)
          .set({
            status: "processed",
            result: {
              code: durable
                ? durable.agentId === payload.agentId
                  ? "interaction_wakeup_already_durable"
                  : "interaction_wakeup_coalesced_after_reassignment"
                : "interaction_wakeup_queued",
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, claimed.id),
              eq(chatActions.status, "processing"),
            ),
          );
        processed += 1;
      } catch (error) {
        const durable = isUniqueViolation(error)
          ? await db
              .select({
                agentId: agentWakeupRequests.agentId,
                id: agentWakeupRequests.id,
              })
              .from(agentWakeupRequests)
              .where(
                and(
                  eq(agentWakeupRequests.companyId, claimed.companyId),
                  eq(agentWakeupRequests.idempotencyKey, idempotencyKey),
                  notInArray(agentWakeupRequests.status, [
                    "skipped",
                    "failed",
                    "cancelled",
                  ]),
                ),
              )
              .limit(1)
              .then((rows) => rows[0] ?? null)
          : null;
        const previousResult =
          claimed.result && typeof claimed.result === "object"
            ? (claimed.result as Record<string, unknown>)
            : {};
        const previousAttempts =
          typeof previousResult.attemptCount === "number" &&
          Number.isInteger(previousResult.attemptCount) &&
          previousResult.attemptCount >= 0
            ? previousResult.attemptCount
            : 0;
        const attemptCount = previousAttempts + 1;
        await db
          .update(chatActions)
          .set({
            status: durable ? "processed" : "issued",
            result: {
              code: durable
                ? durable.agentId === payload.agentId
                  ? "interaction_wakeup_already_durable"
                  : "interaction_wakeup_coalesced_after_reassignment"
                : "interaction_wakeup_failed",
              ...(!durable ? { attemptCount } : {}),
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, claimed.id),
              eq(chatActions.status, "processing"),
            ),
          );
        if (!durable) {
          logger.warn(
            {
              endpointId: claimed.endpointId,
              interactionId: payload.interactionId,
              attemptCount,
              error: redactError(error),
            },
            "failed to queue external interaction continuation wake",
          );
        }
      }
    }
    return processed;
  }

  async function handleAction(
    event: ChatSdkCallbackEvent<ActionEvent>,
    runtimeContext: RuntimeContext,
  ) {
    const record = await runtimeCallbackRecord(
      event.endpointId,
      runtimeContext,
      ["active"],
    );
    if (!record) {
      throw forbidden("This chat action is not a current Paperclip question");
    }
    const deny = async (safelyKnown?: {
      conversationId?: string | null;
      principalId?: string | null;
    }) => {
      await denyExternalAction(
        record.endpoint,
        event,
        runtimeContext,
        safelyKnown,
      );
      if (
        event.provider === "discord" &&
        event.transport === "discord_gateway"
      ) {
        // Discord renders deferUpdate as a successful click. After the denial
        // audit is durable, surface a transport-only sentinel so the Gateway
        // adapter can withhold that misleading acknowledgement. The runtime,
        // not raw JSON or discord.js methods, supplies the ingress context.
        throw Object.assign(
          new Error("Discord Gateway action was not admitted by Paperclip"),
          { code: "chat_discord_gateway_action_rejected" },
        );
      }
    };
    if (
      record.endpoint.status !== "active" ||
      record.endpoint.provider !== event.provider ||
      record.endpoint.capabilities.actions !== true
    ) {
      return deny();
    }
    const principal = await ensurePrincipal(
      record.endpoint,
      event.event.user,
      event.event.raw,
    );
    // Executable external actions are deliberately stricter than ordinary
    // sponsored-guest messages. They require a current endpoint-scoped link to
    // an active non-viewer Paperclip member, and never run as a guest sponsor.
    if (
      principal.linkedDenied ||
      !principal.userId ||
      principal.principal.kind !== "user" ||
      principal.principal.isBot
    ) {
      return deny({ principalId: principal.principal.id });
    }
    const isCorrection = isDiscordQuestionFormCorrectionId(
      event.event.actionId,
    );
    const correction =
      isCorrection &&
      event.provider === "discord" &&
      event.transport === "discord_gateway"
        ? await loadDiscordQuestionFormCorrection(
            persistence,
            {
              companyId: record.endpoint.companyId,
              endpointId: record.endpoint.id,
            },
            event.event.actionId,
            {
              principalId: principal.principal.id,
              userId: principal.userId,
              externalUserId: event.event.user.userId,
            },
            event.event.threadId,
          )
        : null;
    if (
      isCorrection &&
      (!correction ||
        discordQuestionFormThreadId(event.event.raw) !== event.event.threadId)
    )
      return deny({ principalId: principal.principal.id });
    // The private correction handle selects the original publication, never
    // the new ephemeral error message. It does not bypass any current source,
    // destination, actor, open-token, or pending-interaction check below.
    const sourceActionId = correction?.openActionId ?? event.event.actionId;
    const sourceMessageId =
      correction?.providerMessageId ?? event.event.messageId;
    const actionBinding = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, record.endpoint.companyId),
          eq(chatActions.endpointId, record.endpoint.id),
          inArray(chatActions.kind, [
            "question_answer",
            "question_form_open",
            "confirmation_response",
          ]),
          eq(chatActions.providerActionId, sourceActionId),
        ),
      )
      .then((rows) => (rows.length === 1 ? rows[0]! : null));
    const originalPublicationId = actionBinding?.payload.publicationId;
    const actionInteractionId = actionBinding?.payload.interactionId;
    if (
      correction &&
      (actionBinding?.kind !== "question_form_open" ||
        actionBinding.conversationId !== correction.conversationId ||
        originalPublicationId !== correction.publicationId ||
        actionInteractionId !== correction.interactionId ||
        actionBinding.payload.formActionId !== correction.submitActionId)
    )
      return deny({ principalId: principal.principal.id });
    if (
      !actionBinding?.conversationId ||
      typeof originalPublicationId !== "string" ||
      typeof actionInteractionId !== "string"
    ) {
      return deny({ principalId: principal.principal.id });
    }
    // The opaque provider action is the immutable link to the original
    // publication. Resolve the conversation from that token, then verify the
    // provider's thread independently; never trust a callback message id to
    // select a Paperclip task.
    const conversation = await db
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, record.endpoint.companyId),
          eq(chatConversations.endpointId, record.endpoint.id),
          eq(chatConversations.id, actionBinding.conversationId),
          inArray(chatConversations.state, ["active", "waiting"]),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (
      !conversation ||
      !actionThreadMatchesConversation(
        event.provider,
        event.event.threadId,
        conversation.externalThreadId,
      )
    ) {
      return deny({ principalId: principal.principal.id });
    }
    const safelyKnown = {
      conversationId: conversation.id,
      principalId: principal.principal.id,
    };
    const resource = conversation.resourceId
      ? await db
          .select()
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.companyId, record.endpoint.companyId),
              eq(chatEndpointResources.endpointId, record.endpoint.id),
              eq(chatEndpointResources.id, conversation.resourceId),
            ),
          )
          .then((rows) => rows[0] ?? null)
      : null;
    const resourceAllowed = conversation.isDirectMessage
      ? record.endpoint.allowDirectMessages
      : nonDirectDestinationAllowed(record.endpoint, resource);
    if (!resourceAllowed) return deny(safelyKnown);

    let originalPublication = await db
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, record.endpoint.companyId),
          eq(chatPublications.endpointId, record.endpoint.id),
          eq(chatPublications.conversationId, conversation.id),
          eq(chatPublications.issueId, conversation.issueId),
          eq(chatPublications.id, originalPublicationId),
          inArray(chatPublications.state, ["published", "delivery_unknown"]),
          or(
            isNull(chatPublications.providerMessageId),
            eq(chatPublications.providerMessageId, sourceMessageId),
          ),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!originalPublication) return deny(safelyKnown);
    if (
      correction &&
      (originalPublication.state !== "published" ||
        originalPublication.providerMessageId !== correction.providerMessageId)
    )
      return deny(safelyKnown);
    if (!originalPublication.providerMessageId) {
      const reconciledPublication = await db.transaction(async (tx) => {
        const current = await tx
          .select()
          .from(chatPublications)
          .where(eq(chatPublications.id, originalPublicationId))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (
          !current ||
          current.companyId !== record.endpoint.companyId ||
          current.endpointId !== record.endpoint.id ||
          current.conversationId !== conversation.id ||
          current.issueId !== conversation.issueId ||
          !["published", "delivery_unknown"].includes(current.state) ||
          (current.providerMessageId !== null &&
            current.providerMessageId !== event.event.messageId)
        ) {
          return null;
        }
        const occupied = await tx
          .select({ publicationId: chatMessageLinks.publicationId })
          .from(chatMessageLinks)
          .where(
            and(
              eq(chatMessageLinks.endpointId, record.endpoint.id),
              eq(chatMessageLinks.conversationId, conversation.id),
              eq(chatMessageLinks.providerMessageId, event.event.messageId),
              eq(chatMessageLinks.direction, "outbound"),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (occupied && occupied.publicationId !== current.id) return null;
        const reconciledAt = new Date();
        const [reconciled] = await tx
          .update(chatPublications)
          .set({
            state: "published",
            providerMessageId: event.event.messageId,
            publishedAt: current.publishedAt ?? reconciledAt,
            nextAttemptAt: null,
            redactedError: null,
            updatedAt: reconciledAt,
          })
          .where(
            and(
              eq(chatPublications.id, current.id),
              inArray(chatPublications.state, [
                "published",
                "delivery_unknown",
              ]),
              isNull(chatPublications.providerMessageId),
            ),
          )
          .returning();
        if (!reconciled) return null;
        await tx
          .insert(chatMessageLinks)
          .values({
            companyId: current.companyId,
            endpointId: current.endpointId,
            conversationId: current.conversationId,
            publicationId: current.id,
            commentId: current.commentId,
            providerMessageId: event.event.messageId,
            direction: "outbound",
          })
          .onConflictDoNothing();
        const linked = await tx
          .select({ publicationId: chatMessageLinks.publicationId })
          .from(chatMessageLinks)
          .where(
            and(
              eq(chatMessageLinks.endpointId, record.endpoint.id),
              eq(chatMessageLinks.conversationId, conversation.id),
              eq(chatMessageLinks.providerMessageId, event.event.messageId),
              eq(chatMessageLinks.direction, "outbound"),
            ),
          )
          .then((rows) => rows[0] ?? null);
        return linked?.publicationId === reconciled.id ? reconciled : null;
      });
      if (!reconciledPublication) return deny(safelyKnown);
      originalPublication = reconciledPublication;
    }
    const messageBinding = await db
      .select({
        link: chatMessageLinks,
        linkedPublication: chatPublications,
      })
      .from(chatMessageLinks)
      .innerJoin(
        chatPublications,
        and(
          eq(chatPublications.companyId, chatMessageLinks.companyId),
          eq(chatPublications.endpointId, chatMessageLinks.endpointId),
          eq(chatPublications.conversationId, chatMessageLinks.conversationId),
          eq(chatPublications.id, chatMessageLinks.publicationId),
        ),
      )
      .where(
        and(
          eq(chatMessageLinks.companyId, record.endpoint.companyId),
          eq(chatMessageLinks.endpointId, record.endpoint.id),
          eq(chatMessageLinks.conversationId, conversation.id),
          eq(chatMessageLinks.providerMessageId, sourceMessageId),
          eq(chatMessageLinks.direction, "outbound"),
          eq(chatPublications.issueId, conversation.issueId),
          eq(chatPublications.state, "published"),
          eq(chatPublications.providerMessageId, sourceMessageId),
        ),
      )
      .then((rows) => (rows.length === 1 ? rows[0]! : null));
    if (!messageBinding) return deny(safelyKnown);
    const linkedPayload = messageBinding.linkedPublication
      .payload as SafeChatPublicationPayload;
    const linkStillAuthoritative =
      messageBinding.link.publicationId === originalPublicationId ||
      (messageBinding.linkedPublication.idempotencyKey ===
        `interaction-resolution:${actionInteractionId}:${record.endpoint.id}` &&
        linkedPayload.interactionId === actionInteractionId);
    if (!originalPublication || !linkStillAuthoritative) {
      return deny(safelyKnown);
    }
    const issued = {
      publication: originalPublication,
      link: messageBinding.link,
      conversation,
    };

    const payload = issued.publication.payload as SafeChatPublicationPayload;
    if (event.provider === "telegram") {
      const raw = event.event.raw;
      const callbackData =
        raw && typeof raw === "object" && "data" in raw
          ? (raw as { data?: unknown }).data
          : null;
      if (
        typeof callbackData !== "string" ||
        Buffer.byteLength(callbackData, "utf8") >
          TELEGRAM_CALLBACK_DATA_LIMIT_BYTES ||
        callbackData !== telegramChatSdkCallbackData(event.event.actionId) ||
        event.event.value !== undefined
      ) {
        return deny(safelyKnown);
      }
    }
    if (
      !payload.interactionId ||
      (!correction &&
        event.provider !== "telegram" &&
        event.event.value !== payload.interactionId) ||
      !payload.card?.actions?.some(
        (action) =>
          action.type === "callback" && action.actionId === sourceActionId,
      )
    ) {
      return deny(safelyKnown);
    }

    const interaction = (
      await issueThreadInteractionService(db).listForIssue(conversation.issueId)
    ).find((candidate) => candidate.id === payload.interactionId);
    if (
      !interaction ||
      interaction.companyId !== record.endpoint.companyId ||
      interaction.issueId !== conversation.issueId
    ) {
      return deny(safelyKnown);
    }
    if (interaction.status !== "pending") {
      if (correction) return deny(safelyKnown);
      const completedAction = await db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.companyId, record.endpoint.companyId),
            eq(chatActions.endpointId, record.endpoint.id),
            eq(chatActions.conversationId, conversation.id),
            eq(chatActions.providerActionId, event.event.actionId),
            eq(chatActions.principalId, principal.principal.id),
            eq(chatActions.status, "processed"),
          ),
        )
        .then((rows) => rows[0] ?? null);
      const completedPayload = completedAction?.payload;
      const completedResult = completedAction?.result;
      const completedResultMatches =
        completedResult?.interactionId === interaction.id &&
        completedResult?.interactionStatus === interaction.status &&
        (interaction.kind !== "request_confirmation" ||
          completedResult.code ===
            "confirmation_resolution_committed_by_provider");
      if (
        completedAction &&
        completedResultMatches &&
        completedPayload?.publicationId === issued.publication.id &&
        completedPayload?.interactionId === interaction.id &&
        completedPayload?.messageId === event.event.messageId &&
        completedPayload?.actionId === event.event.actionId
      ) {
        await recordCurrentMicrosoftTeamsRoute(
          record.endpoint,
          runtimeContext,
          event.event.threadId,
          event.event.raw,
        );
        return;
      }
      return deny(safelyKnown);
    }
    if (interaction.kind === "request_confirmation") {
      if (
        event.provider !== "telegram" ||
        !nativeTelegramConfirmation(interaction)
      ) {
        return deny(safelyKnown);
      }
      const action = await db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.companyId, record.endpoint.companyId),
            eq(chatActions.endpointId, record.endpoint.id),
            eq(chatActions.conversationId, conversation.id),
            eq(chatActions.kind, "confirmation_response"),
            eq(chatActions.providerActionId, event.event.actionId),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (!action || action.status !== "issued") return deny(safelyKnown);
      const tokenPayload = action.payload;
      const tokenExpiresAt =
        typeof tokenPayload.expiresAt === "string"
          ? Date.parse(tokenPayload.expiresAt)
          : Number.NaN;
      if (!Number.isFinite(tokenExpiresAt) || tokenExpiresAt <= Date.now()) {
        await db
          .update(chatActions)
          .set({
            status: "expired",
            result: { code: "confirmation_action_token_expired" },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, action.id),
              eq(chatActions.status, "issued"),
            ),
          );
        return deny(safelyKnown);
      }
      if (
        tokenPayload.version !== 1 ||
        tokenPayload.publicationId !== issued.publication.id ||
        tokenPayload.interactionId !== interaction.id ||
        (tokenPayload.decision !== "accept" &&
          tokenPayload.decision !== "reject")
      ) {
        return deny(safelyKnown);
      }

      const issue = await db
        .select({
          id: issues.id,
          companyId: issues.companyId,
          projectId: issues.projectId,
          goalId: issues.goalId,
          status: issues.status,
          assigneeAgentId: issues.assigneeAgentId,
        })
        .from(issues)
        .where(
          and(
            eq(issues.companyId, record.endpoint.companyId),
            eq(issues.id, conversation.issueId),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (!issue) {
        return deny(safelyKnown);
      }

      const decision = tokenPayload.decision;
      try {
        if (decision === "accept") {
          await issueThreadInteractionService(db).acceptInteraction(
            issue,
            interaction.id,
            {},
            { userId: principal.userId },
            {
              beforeResolveInTransaction: async (tx) => {
                await requireCurrentExternalActionAuthorization(tx, {
                  conversationId: conversation.id,
                  endpointId: record.endpoint.id,
                  expectedUserId: principal.userId!,
                  principalId: principal.principal.id,
                  runtimeContext,
                });
              },
              afterResolveInTransaction: async (tx, resolved) => {
                const [owned] = await tx
                  .update(chatActions)
                  .set({
                    principalId: principal.principal.id,
                    status: "processing",
                    payload: {
                      ...tokenPayload,
                      messageId: event.event.messageId,
                      actionId: event.event.actionId,
                      value: null,
                    },
                    result: {
                      code: "confirmation_resolution_committed_by_provider",
                      interactionId: resolved.id,
                      interactionStatus: resolved.status,
                    },
                    updatedAt: new Date(),
                  })
                  .where(
                    and(
                      eq(chatActions.id, action.id),
                      eq(chatActions.status, "issued"),
                    ),
                  )
                  .returning({ id: chatActions.id });
                if (!owned) {
                  throw new Error(
                    "External confirmation action ownership changed before interaction commit",
                  );
                }
              },
            },
          );
        } else {
          await issueThreadInteractionService(db).rejectInteraction(
            issue,
            interaction.id,
            {},
            { userId: principal.userId },
            {
              beforeResolveInTransaction: async (tx) => {
                await requireCurrentExternalActionAuthorization(tx, {
                  conversationId: conversation.id,
                  endpointId: record.endpoint.id,
                  expectedUserId: principal.userId!,
                  principalId: principal.principal.id,
                  runtimeContext,
                });
              },
              afterResolveInTransaction: async (tx, resolved) => {
                const [owned] = await tx
                  .update(chatActions)
                  .set({
                    principalId: principal.principal.id,
                    status: "processing",
                    payload: {
                      ...tokenPayload,
                      messageId: event.event.messageId,
                      actionId: event.event.actionId,
                      value: null,
                    },
                    result: {
                      code: "confirmation_resolution_committed_by_provider",
                      interactionId: resolved.id,
                      interactionStatus: resolved.status,
                    },
                    updatedAt: new Date(),
                  })
                  .where(
                    and(
                      eq(chatActions.id, action.id),
                      eq(chatActions.status, "issued"),
                    ),
                  )
                  .returning({ id: chatActions.id });
                if (!owned) {
                  throw new Error(
                    "External confirmation action ownership changed before interaction commit",
                  );
                }
              },
            },
          );
        }
      } catch (error) {
        if (isExternalActionAuthorizationChange(error)) {
          return deny(safelyKnown);
        }
        const currentStatus = await db
          .select({ status: issueThreadInteractions.status })
          .from(issueThreadInteractions)
          .where(eq(issueThreadInteractions.id, interaction.id))
          .then((rows) => rows[0]?.status ?? null);
        if (currentStatus !== null && currentStatus !== "pending") {
          await settleTerminalConfirmationAction(action.id);
          const completedAction = await db
            .select({ status: chatActions.status, result: chatActions.result })
            .from(chatActions)
            .where(eq(chatActions.id, action.id))
            .then((rows) => rows[0] ?? null);
          if (
            completedAction?.status === "processed" &&
            completedAction.result?.code ===
              "confirmation_resolution_committed_by_provider"
          ) {
            return;
          }
          return deny(safelyKnown);
        }
        throw error;
      }

      await options.confirmationResolutionPersistBarrier?.();
      if (!(await settleTerminalConfirmationAction(action.id))) {
        throw new Error(
          "External confirmation action ownership changed before settlement",
        );
      }

      scheduleMessageProcessing(async () => {
        await processPendingPublications();
      });
      return;
    }
    if (interaction.kind !== "ask_user_questions") {
      return deny(safelyKnown);
    }
    if (isChatQuestionFormOpenActionId(sourceActionId)) {
      if (
        event.provider !== "slack" &&
        event.provider !== "microsoft-teams" &&
        !(
          event.provider === "discord" &&
          event.transport === "discord_gateway" &&
          record.endpoint.capabilities.modals === true
        )
      ) {
        return deny(safelyKnown);
      }
      await options.questionFormOpenAuthorizationBarrier?.();
      let providerAttempted = false;
      let attemptActionId: string | null = null;
      try {
        const attemptProviderActionId = event.event.triggerId
          ? `question_form_open_attempt:${createHash("sha256")
              .update(
                JSON.stringify([
                  record.endpoint.id,
                  event.provider,
                  event.event.triggerId,
                ]),
              )
              .digest("hex")}`
          : null;
        const preflight = await db.transaction(async (tx) => {
          await requireCurrentExternalActionAuthorization(tx, {
            conversationId: conversation.id,
            endpointId: record.endpoint.id,
            expectedUserId: principal.userId!,
            principalId: principal.principal.id,
            runtimeContext,
          });
          const resolved = await resolveChatQuestionFormOpen(tx, {
            companyId: record.endpoint.companyId,
            endpointId: record.endpoint.id,
            conversationId: conversation.id,
            interaction,
            openActionId: sourceActionId,
          });
          if (!resolved || resolved.publicationId !== issued.publication.id) {
            return { kind: "denied" as const };
          }
          if (!attemptProviderActionId) {
            return {
              kind: "ready" as const,
              attemptActionId: null,
              resolved,
            };
          }
          const [attempt] = await tx
            .insert(chatActions)
            .values({
              companyId: record.endpoint.companyId,
              endpointId: record.endpoint.id,
              conversationId: conversation.id,
              principalId: principal.principal.id,
              kind: "question_form_open_attempt",
              providerActionId: attemptProviderActionId,
              payload: { version: 1 },
              status: "processing",
            })
            .onConflictDoNothing()
            .returning({ id: chatActions.id });
          return attempt
            ? {
                kind: "ready" as const,
                attemptActionId: attempt.id,
                resolved,
              }
            : { kind: "duplicate" as const };
        });
        if (preflight.kind === "denied") return deny(safelyKnown);
        if (preflight.kind === "duplicate") {
          if (event.provider === "discord") {
            // A prior attempt may have consumed Discord's single response.
            // A fresh handler has no showModal closure state for that attempt;
            // do not turn its processing/failed receipt into a success ACK.
            throw Object.assign(
              new Error("Discord modal response was already attempted"),
              { code: "chat_discord_gateway_modal_response_indeterminate" },
            );
          }
          await recordCurrentMicrosoftTeamsRoute(
            record.endpoint,
            runtimeContext,
            event.event.threadId,
            event.event.raw,
          );
          return;
        }
        attemptActionId = preflight.attemptActionId;

        await recordCurrentMicrosoftTeamsRoute(
          record.endpoint,
          runtimeContext,
          event.event.threadId,
          event.event.raw,
        );

        // A provider modal open can take seconds and can outlive Slack's
        // trigger. The final Paperclip authorization snapshot above commits
        // before transport starts so provider latency never holds endpoint,
        // destination, identity-link, or membership row locks.
        const modal = correction
          ? discordQuestionFormCorrectionModal(
              preflight.resolved.modal,
              correction,
            )
          : preflight.resolved.modal;
        if (!modal) return deny(safelyKnown);
        providerAttempted = true;
        const opened = await event.event.openModal(modal);
        if (!opened) {
          await recordModalOpenFailure(
            record.endpoint,
            event,
            runtimeContext,
            { ...safelyKnown, attemptActionId, resource },
            new Error("Provider did not confirm the modal open"),
          );
          if (event.provider === "discord") return deny(safelyKnown);
          return;
        }
        if (attemptActionId) {
          const [settledAttempt] = await db
            .update(chatActions)
            .set({
              status: "processed",
              result: { code: "question_form_opened" },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, attemptActionId),
                eq(chatActions.status, "processing"),
              ),
            )
            .returning({ id: chatActions.id });
          if (!settledAttempt) {
            throw new Error(
              "Question-form modal ownership changed after provider acceptance",
            );
          }
        }
      } catch (error) {
        if (isExternalActionAuthorizationChange(error)) {
          return deny(safelyKnown);
        }
        if (!providerAttempted) throw error;
        await recordModalOpenFailure(
          record.endpoint,
          event,
          runtimeContext,
          { ...safelyKnown, attemptActionId, resource },
          error,
        );
        if (event.provider === "discord") return deny(safelyKnown);
        // The provider attempt is now a durable, non-replayable Activity row.
        // Acknowledge the callback so Chat SDK does not turn a definite denial
        // or an ambiguous modal open into a duplicate retry loop.
        return;
      }
      return;
    }

    const action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, record.endpoint.companyId),
          eq(chatActions.endpointId, record.endpoint.id),
          eq(chatActions.conversationId, conversation.id),
          eq(chatActions.kind, "question_answer"),
          eq(chatActions.providerActionId, event.event.actionId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!action || action.status !== "issued") return deny(safelyKnown);
    const tokenPayload = action.payload;
    const tokenExpiresAt =
      typeof tokenPayload.expiresAt === "string"
        ? Date.parse(tokenPayload.expiresAt)
        : Number.NaN;
    if (!Number.isFinite(tokenExpiresAt) || tokenExpiresAt <= Date.now()) {
      await db
        .update(chatActions)
        .set({
          status: "expired",
          result: { code: "question_action_token_expired" },
          updatedAt: new Date(),
        })
        .where(
          and(eq(chatActions.id, action.id), eq(chatActions.status, "issued")),
        );
      return deny(safelyKnown);
    }
    if (
      tokenPayload.version !== 1 ||
      tokenPayload.publicationId !== issued.publication.id ||
      tokenPayload.interactionId !== payload.interactionId ||
      typeof tokenPayload.questionId !== "string" ||
      typeof tokenPayload.optionId !== "string"
    ) {
      return deny(safelyKnown);
    }

    const question = nativeChatQuestion(interaction);
    const option = question?.options.find(
      (candidate) => candidate.id === tokenPayload.optionId,
    );
    if (!question || question.id !== tokenPayload.questionId || !option)
      return deny(safelyKnown);

    await options.questionResolutionPersistBarrier?.();

    const issue = await db
      .select({
        id: issues.id,
        companyId: issues.companyId,
        status: issues.status,
      })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, record.endpoint.companyId),
          eq(issues.id, conversation.issueId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!issue) return deny(safelyKnown);
    try {
      const answered = await issueThreadInteractionService(db).answerQuestions(
        issue,
        interaction.id,
        {
          answers: [{ questionId: question.id, optionIds: [option.id] }],
        },
        { userId: principal.userId },
        {
          beforeResolveInTransaction: async (tx) => {
            await requireCurrentExternalActionAuthorization(tx, {
              conversationId: conversation.id,
              endpointId: record.endpoint.id,
              expectedUserId: principal.userId!,
              principalId: principal.principal.id,
              runtimeContext,
            });
          },
          afterResolveInTransaction: async (tx, resolved) => {
            const [completed] = await tx
              .update(chatActions)
              .set({
                principalId: principal.principal.id,
                status: "processed",
                payload: {
                  ...tokenPayload,
                  messageId: event.event.messageId,
                  actionId: event.event.actionId,
                  value: event.event.value ?? null,
                },
                result: {
                  interactionId: resolved.id,
                  interactionStatus: resolved.status,
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "issued"),
                ),
              )
              .returning({ id: chatActions.id });
            if (!completed) {
              throw new Error(
                "External question action ownership changed before commit",
              );
            }
            await tx
              .update(chatActions)
              .set({
                status: "expired",
                result: { code: "interaction_resolved_by_sibling_action" },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.companyId, issue.companyId),
                  eq(chatActions.endpointId, record.endpoint.id),
                  eq(chatActions.conversationId, conversation.id),
                  eq(chatActions.kind, "question_answer"),
                  eq(chatActions.status, "issued"),
                  ne(chatActions.id, action.id),
                  eq(
                    sql<string>`${chatActions.payload}->>'interactionId'`,
                    resolved.id,
                  ),
                ),
              );
            await logActivity(tx as unknown as Db, {
              companyId: issue.companyId,
              actorType: "user",
              actorId: principal.userId!,
              action: "issue.thread_interaction_answered",
              entityType: "issue",
              entityId: issue.id,
              details: {
                source: "external_chat",
                endpointId: record.endpoint.id,
                provider: record.endpoint.provider,
                conversationId: conversation.id,
                publicationId: issued.publication.id,
                providerMessageId: event.event.messageId,
                interactionId: resolved.id,
                interactionKind: resolved.kind,
                interactionStatus: resolved.status,
                resolutionActorKind: "user",
                answeredQuestionCount: 1,
              },
            });
            await tx
              .insert(chatPublications)
              .values({
                companyId: issue.companyId,
                endpointId: record.endpoint.id,
                conversationId: conversation.id,
                issueId: issue.id,
                idempotencyKey: `interaction-resolution:${resolved.id}:${record.endpoint.id}`,
                payload: projectSafeChatPublication({
                  classification: "external",
                  source: "issue_interaction",
                  text: `Answered: ${option.label}.`,
                  interaction: {
                    id: resolved.id,
                    card: {
                      kind: "question",
                      title: question.prompt,
                      body: `Answered: ${option.label}.`,
                      actions: [],
                    },
                  },
                }),
                state: "pending",
              })
              .onConflictDoNothing();
          },
        },
      );
      scheduleMessageProcessing(async () => {
        await processPendingPublications();
      });
      // The interaction, provider token, and response-delivery receipt are
      // already durable. A provider callback must not wait for agent startup;
      // drain the outbox after acknowledging the provider callback.
      scheduleMessageProcessing(async () => {
        await questionResponses.deliver(answered.id);
      });
    } catch (error) {
      if (isExternalActionAuthorizationChange(error)) {
        return deny(safelyKnown);
      }
      // `answerQuestions` commits the interaction and this action in one
      // transaction, then performs a best-effort issue timestamp touch. If
      // that post-commit touch fails, the provider callback is nevertheless
      // durably complete. Do not corrupt the processed token to `failed` or
      // return a retryable webhook response that turns Telegram's redelivery
      // into a misleading stale-action notice.
      try {
        const raceResult = await db.transaction(async (tx) => {
          const currentAction = await tx
            .select({ status: chatActions.status })
            .from(chatActions)
            .where(eq(chatActions.id, action.id))
            .then((rows) => rows[0] ?? null);
          const currentInteraction = (
            await issueThreadInteractionService(
              tx as unknown as Db,
            ).listForIssue(issue.id)
          ).find((candidate) => candidate.id === interaction.id);
          if (currentInteraction && currentInteraction.status !== "pending") {
            await tx
              .update(chatActions)
              .set({
                status: "expired",
                result: { code: "interaction_resolved_elsewhere" },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  inArray(chatActions.status, ["issued", "processing"]),
                ),
              );
            await enqueueTerminalIssueInteractionChatPublications(
              tx,
              currentInteraction,
            );
            return { actionStatus: currentAction?.status, settledRace: true };
          }
          return { actionStatus: currentAction?.status, settledRace: false };
        });
        if (raceResult.actionStatus === "processed") {
          logger.warn(
            {
              endpointId: record.endpoint.id,
              interactionId: interaction.id,
              error: redactError(error),
            },
            "external chat question resolved but post-commit follow-up failed",
          );
          return;
        }
        if (raceResult.settledRace) {
          scheduleMessageProcessing(async () => {
            await processPendingPublications();
          });
          return;
        }
      } catch (recoveryError) {
        logger.warn(
          {
            endpointId: record.endpoint.id,
            interactionId: interaction.id,
            error: redactError(recoveryError),
          },
          "could not reconcile an external chat question after resolution failed",
        );
      }
      throw error;
    }
    await recordCurrentMicrosoftTeamsRoute(
      record.endpoint,
      runtimeContext,
      event.event.threadId,
      event.event.raw,
    );
  }

  async function handleModalSubmit(
    event: ChatSdkCallbackEvent<ModalSubmitEvent>,
    runtimeContext: RuntimeContext,
  ): Promise<ModalResponse> {
    const denialError = () =>
      forbidden("This chat form is not a current Paperclip question");
    const record = await runtimeCallbackRecord(
      event.endpointId,
      runtimeContext,
      ["active"],
    );
    if (
      !record ||
      record.endpoint.status !== "active" ||
      record.endpoint.provider !== event.provider ||
      record.endpoint.capabilities.modals !== true ||
      (event.provider !== "slack" &&
        event.provider !== "microsoft-teams" &&
        !(
          event.provider === "discord" && event.transport === "discord_gateway"
        ))
    ) {
      const staleRecord =
        record ??
        (await endpointRecord(event.endpointId).then((candidate) =>
          candidate?.endpoint.provider === event.provider ? candidate : null,
        ));
      if (staleRecord) {
        await recordModalSubmitDenial(staleRecord.endpoint, event, {
          code: "chat_modal_runtime_not_current",
        });
      }
      return event.provider === "discord"
        ? discordQuestionFormDenialResponse()
        : chatQuestionFormDenialResponse();
    }
    const deny = async (
      code: string,
      safelyKnown: {
        conversationId?: string | null;
        principalId?: string | null;
      } = {},
      payload?: Parameters<typeof chatQuestionFormDenialResponse>[0],
    ): Promise<ModalResponse> => {
      await recordModalSubmitDenial(record.endpoint, event, {
        code,
        ...safelyKnown,
      });
      return event.provider === "discord"
        ? discordQuestionFormDenialResponse()
        : chatQuestionFormDenialResponse(payload);
    };
    const loaded = await loadChatQuestionFormSubmissionToken(db, {
      callbackId: event.event.callbackId,
      companyId: record.endpoint.companyId,
      endpointId: record.endpoint.id,
      includeProcessed: true,
    });
    if (!loaded) return deny("chat_modal_token_not_current");
    const conversation = await db
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, record.endpoint.companyId),
          eq(chatConversations.endpointId, record.endpoint.id),
          eq(chatConversations.id, loaded.conversationId),
          inArray(chatConversations.state, ["active", "waiting"]),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (
      !conversation ||
      (event.provider === "discord" &&
        discordQuestionFormThreadId(event.event.raw) !==
          conversation.externalThreadId) ||
      (event.event.relatedThread &&
        (event.provider === "microsoft-teams"
          ? !sameTeamsThreadIdentity(
              event.event.relatedThread.id,
              conversation.externalThreadId,
            )
          : event.event.relatedThread.id !== conversation.externalThreadId))
    ) {
      return deny(
        "chat_modal_conversation_not_current",
        {
          conversationId: conversation?.id ?? null,
        },
        loaded.payload,
      );
    }
    const principal = await ensurePrincipal(
      record.endpoint,
      event.event.user,
      event.event.raw,
    );
    if (
      principal.linkedDenied ||
      !principal.userId ||
      principal.principal.kind !== "user" ||
      principal.principal.isBot
    ) {
      return deny(
        "chat_modal_principal_not_authorized",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    const resource = conversation.resourceId
      ? await db
          .select()
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.companyId, record.endpoint.companyId),
              eq(chatEndpointResources.endpointId, record.endpoint.id),
              eq(chatEndpointResources.id, conversation.resourceId),
            ),
          )
          .then((rows) => rows[0] ?? null)
      : null;
    const resourceAllowed = conversation.isDirectMessage
      ? record.endpoint.allowDirectMessages
      : nonDirectDestinationAllowed(record.endpoint, resource);
    if (!resourceAllowed) {
      return deny(
        "chat_modal_destination_not_authorized",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }

    const originalPublication = await db
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, record.endpoint.companyId),
          eq(chatPublications.endpointId, record.endpoint.id),
          eq(chatPublications.conversationId, conversation.id),
          eq(chatPublications.issueId, conversation.issueId),
          eq(chatPublications.id, loaded.publicationId),
          eq(chatPublications.state, "published"),
          event.provider !== "discord" && event.event.relatedMessage
            ? eq(
                chatPublications.providerMessageId,
                event.event.relatedMessage.id,
              )
            : undefined,
        ),
      )
      .then((rows) => rows[0] ?? null);
    const providerMessageId =
      (event.provider === "discord"
        ? undefined
        : event.event.relatedMessage?.id) ??
      originalPublication?.providerMessageId ??
      null;
    if (!originalPublication || !providerMessageId) {
      return deny(
        "chat_modal_publication_not_current",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    const currentMessageBinding = await db
      .select({
        link: chatMessageLinks,
        publication: chatPublications,
      })
      .from(chatMessageLinks)
      .innerJoin(
        chatPublications,
        and(
          eq(chatPublications.companyId, chatMessageLinks.companyId),
          eq(chatPublications.endpointId, chatMessageLinks.endpointId),
          eq(chatPublications.conversationId, chatMessageLinks.conversationId),
          eq(chatPublications.id, chatMessageLinks.publicationId),
        ),
      )
      .where(
        and(
          eq(chatMessageLinks.companyId, record.endpoint.companyId),
          eq(chatMessageLinks.endpointId, record.endpoint.id),
          eq(chatMessageLinks.conversationId, conversation.id),
          eq(chatMessageLinks.providerMessageId, providerMessageId),
          eq(chatMessageLinks.direction, "outbound"),
          eq(chatPublications.issueId, conversation.issueId),
          eq(chatPublications.state, "published"),
          eq(chatPublications.providerMessageId, providerMessageId),
        ),
      )
      .then((rows) => (rows.length === 1 ? rows[0]! : null));
    const linkedPayload = currentMessageBinding?.publication.payload as
      SafeChatPublicationPayload | undefined;
    const linkStillAuthoritative =
      currentMessageBinding?.link.publicationId === originalPublication.id ||
      (currentMessageBinding?.publication.idempotencyKey ===
        `interaction-resolution:${loaded.interactionId}:${record.endpoint.id}` &&
        linkedPayload?.interactionId === loaded.interactionId);
    if (!currentMessageBinding || !linkStillAuthoritative) {
      return deny(
        "chat_modal_message_binding_not_current",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    const issued = {
      publication: originalPublication,
      link: currentMessageBinding.link,
    };
    const payload = issued.publication.payload as SafeChatPublicationPayload;
    if (payload.interactionId !== loaded.interactionId) {
      return deny(
        "chat_modal_interaction_binding_not_current",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    const interaction = (
      await issueThreadInteractionService(db).listForIssue(conversation.issueId)
    ).find((candidate) => candidate.id === loaded.interactionId);
    const discordReplayAnswersMatch = (
      resolved: typeof interaction,
    ): boolean => {
      if (event.provider !== "discord") return true;
      if (
        resolved?.kind !== "ask_user_questions" ||
        resolved.status !== "answered"
      )
        return false;
      // Parse only for comparison after current token/source/actor checks.
      // This local pending projection cannot reopen or resolve an interaction.
      const submitted = validateChatQuestionFormSubmission({
        callbackId: event.event.callbackId,
        privateMetadata: event.event.privateMetadata,
        interaction: { ...resolved, status: "pending" },
        payload: loaded.payload,
        values: event.event.values,
      });
      return (
        submitted.ok &&
        JSON.stringify(submitted.answers) ===
          JSON.stringify(resolved.result?.answers)
      );
    };
    const isExactProcessedReplay = (
      current: Awaited<ReturnType<typeof loadChatQuestionFormSubmissionToken>>,
    ) =>
      interaction?.companyId === record.endpoint.companyId &&
      interaction.issueId === conversation.issueId &&
      interaction.kind === "ask_user_questions" &&
      interaction.status === "answered" &&
      interaction.resolvedByUserId === principal.userId &&
      current?.status === "processed" &&
      current.actionRowId === loaded.actionRowId &&
      current.conversationId === conversation.id &&
      current.publicationId === originalPublication.id &&
      current.interactionId === loaded.interactionId &&
      current.principalId === principal.principal.id &&
      current.result?.code === "question_form_answered" &&
      current.result?.interactionId === loaded.interactionId &&
      discordReplayAnswersMatch(interaction);
    const acceptedResponse = async (): Promise<ModalResponse> => {
      if (event.provider === "discord") {
        try {
          await deleteDiscordQuestionFormCorrection(
            persistence,
            {
              companyId: record.endpoint.companyId,
              endpointId: record.endpoint.id,
            },
            {
              principalId: principal.principal.id,
              userId: principal.userId!,
              externalUserId: event.event.user.userId,
            },
            loaded.payload.formActionId,
          );
        } catch {
          // The answer receipt is already committed. Cleanup is retryable on
          // exact replay/expiry access and cannot relabel an accepted answer.
          logger.warn(
            {
              endpointId: record.endpoint.id,
              code: "discord_question_correction_cleanup_failed",
            },
            "Discord correction draft cleanup will be retried",
          );
        }
      }
      return { action: "clear" };
    };
    if (loaded.status === "processed") {
      if (!isExactProcessedReplay(loaded)) {
        return deny(
          "chat_modal_replay_not_authorized",
          {
            conversationId: conversation.id,
            principalId: principal.principal.id,
          },
          loaded.payload,
        );
      }
      if (event.event.relatedThread) {
        await recordCurrentMicrosoftTeamsRoute(
          record.endpoint,
          runtimeContext,
          event.event.relatedThread.id,
          event.event.raw,
        );
      }
      return acceptedResponse();
    }
    if (
      !interaction ||
      interaction.companyId !== record.endpoint.companyId ||
      interaction.issueId !== conversation.issueId ||
      interaction.kind !== "ask_user_questions" ||
      interaction.status !== "pending"
    ) {
      // Another callback can commit the same token between the initial token
      // read and this interaction read. Only its exact processed receipt may
      // acknowledge the stale snapshot; an answer by another token or actor
      // does not authorize this form. Recheck current policy under its locks.
      let processedReplay = false;
      if (
        interaction?.companyId === record.endpoint.companyId &&
        interaction.issueId === conversation.issueId &&
        interaction.kind === "ask_user_questions" &&
        interaction.status === "answered"
      ) {
        try {
          processedReplay = await db.transaction(async (tx) => {
            await requireCurrentExternalActionAuthorization(tx, {
              conversationId: conversation.id,
              endpointId: record.endpoint.id,
              expectedUserId: principal.userId!,
              principalId: principal.principal.id,
              runtimeContext,
            });
            return isExactProcessedReplay(
              await loadChatQuestionFormSubmissionToken(tx, {
                callbackId: event.event.callbackId,
                companyId: record.endpoint.companyId,
                endpointId: record.endpoint.id,
                includeProcessed: true,
              }),
            );
          });
        } catch (error) {
          if (!isExternalActionAuthorizationChange(error)) throw error;
        }
      }
      if (processedReplay) {
        if (event.event.relatedThread) {
          await recordCurrentMicrosoftTeamsRoute(
            record.endpoint,
            runtimeContext,
            event.event.relatedThread.id,
            event.event.raw,
          );
        }
        return acceptedResponse();
      }
      return deny(
        "chat_modal_interaction_not_pending",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    const validation = validateChatQuestionFormSubmission({
      callbackId: event.event.callbackId,
      privateMetadata: event.event.privateMetadata,
      interaction,
      payload: loaded.payload,
      values: event.event.values,
    });
    if (!validation.ok) {
      if (validation.code === "invalid_form") {
        if (event.provider === "discord") {
          const openAction = payload.card?.actions?.find(
            (action) =>
              action.type === "callback" &&
              isChatQuestionFormOpenActionId(action.actionId),
          );
          const openActionId =
            openAction?.type === "callback" ? openAction.actionId : null;
          if (!openActionId) return deny("chat_modal_open_token_not_current");
          try {
            return await db.transaction(async (tx) => {
              await requireCurrentExternalActionAuthorization(tx, {
                conversationId: conversation.id,
                endpointId: record.endpoint.id,
                expectedUserId: principal.userId!,
                principalId: principal.principal.id,
                runtimeContext,
              });
              const pending = await tx
                .select({ id: issueThreadInteractions.id })
                .from(issueThreadInteractions)
                .where(
                  and(
                    eq(
                      issueThreadInteractions.companyId,
                      record.endpoint.companyId,
                    ),
                    eq(issueThreadInteractions.issueId, conversation.issueId),
                    eq(issueThreadInteractions.id, interaction.id),
                    eq(issueThreadInteractions.status, "pending"),
                  ),
                )
                .for("update")
                .then((rows) => rows[0]);
              const resolved = pending
                ? await resolveChatQuestionFormOpen(tx, {
                    companyId: record.endpoint.companyId,
                    endpointId: record.endpoint.id,
                    conversationId: conversation.id,
                    interaction,
                    openActionId,
                  })
                : null;
              if (
                !resolved ||
                resolved.submitActionId !== loaded.payload.formActionId ||
                resolved.publicationId !== originalPublication.id
              )
                throw denialError();
              return retainDiscordQuestionFormCorrection(
                createChatSdkStatePersistence(tx as unknown as Db),
                {
                  companyId: record.endpoint.companyId,
                  endpointId: record.endpoint.id,
                },
                {
                  principalId: principal.principal.id,
                  userId: principal.userId!,
                  externalUserId: event.event.user.userId,
                  conversationId: conversation.id,
                  publicationId: originalPublication.id,
                  providerMessageId,
                  threadId: conversation.externalThreadId,
                  interactionId: interaction.id,
                  openActionId,
                  submitActionId: resolved.submitActionId,
                  parentExpiresAt: loaded.payload.expiresAt,
                  modal: resolved.modal,
                  values: event.event.values,
                  fieldErrors: validation.fieldErrors,
                },
              );
            });
          } catch (error) {
            if (
              isExternalActionAuthorizationChange(error) ||
              (error &&
                typeof error === "object" &&
                "status" in error &&
                error.status === 403)
            )
              return deny("chat_modal_correction_not_authorized");
            throw error;
          }
        }
        return chatQuestionFormValidationResponse({
          provider: event.provider,
          callbackId: event.event.callbackId,
          privateMetadata: event.event.privateMetadata,
          interaction,
          payload: loaded.payload,
          values: event.event.values,
        });
      }
      return deny(
        `chat_modal_${validation.code}`,
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    const issue = await db
      .select({
        id: issues.id,
        companyId: issues.companyId,
        status: issues.status,
      })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, record.endpoint.companyId),
          eq(issues.id, conversation.issueId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!issue) {
      return deny(
        "chat_modal_issue_not_current",
        {
          conversationId: conversation.id,
          principalId: principal.principal.id,
        },
        loaded.payload,
      );
    }
    await options.questionResolutionPersistBarrier?.();
    let answered: Awaited<
      ReturnType<
        ReturnType<typeof issueThreadInteractionService>["answerQuestions"]
      >
    >;
    try {
      answered = await issueThreadInteractionService(db).answerQuestions(
        issue,
        interaction.id,
        { answers: validation.answers },
        { userId: principal.userId },
        {
          beforeResolveInTransaction: async (tx) => {
            await requireCurrentExternalActionAuthorization(tx, {
              conversationId: conversation.id,
              endpointId: event.endpointId,
              expectedUserId: principal.userId!,
              principalId: principal.principal.id,
              runtimeContext,
            });
          },
          afterResolveInTransaction: async (tx, resolved) => {
            const claimed = await claimChatQuestionFormSubmission(tx, {
              actionRowId: loaded.actionRowId,
              principalId: principal.principal.id,
            });
            if (!claimed) throw denialError();
            const completed = await completeChatQuestionFormSubmission(tx, {
              actionRowId: loaded.actionRowId,
              interactionId: resolved.id,
            });
            if (!completed) throw denialError();
            await tx
              .update(chatActions)
              .set({
                status: "expired",
                result: { code: "question_form_submitted" },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.companyId, issue.companyId),
                  eq(chatActions.endpointId, record.endpoint.id),
                  eq(chatActions.conversationId, conversation.id),
                  eq(chatActions.kind, "question_form_open"),
                  eq(chatActions.status, "issued"),
                  eq(
                    sql<string>`${chatActions.payload}->>'interactionId'`,
                    resolved.id,
                  ),
                ),
              );
            await logActivity(tx as unknown as Db, {
              companyId: issue.companyId,
              actorType: "user",
              actorId: principal.userId!,
              action: "issue.thread_interaction_answered",
              entityType: "issue",
              entityId: issue.id,
              details: {
                source: "external_chat_modal",
                endpointId: record.endpoint.id,
                provider: record.endpoint.provider,
                conversationId: conversation.id,
                publicationId: issued.publication.id,
                interactionId: resolved.id,
                interactionKind: resolved.kind,
                interactionStatus: resolved.status,
                resolutionActorKind: "user",
                answeredQuestionCount: validation.answers.length,
              },
            });
          },
        },
      );
    } catch (error) {
      if (isExternalActionAuthorizationChange(error)) {
        await db.transaction(async (tx) => {
          await tx
            .update(chatActions)
            .set({
              status: "expired",
              result: { code: "chat_action_authorization_changed" },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, loaded.actionRowId),
                eq(chatActions.status, "issued"),
              ),
            );
          await recordModalSubmitDenial(
            record.endpoint,
            event,
            {
              code: "chat_action_authorization_changed",
              conversationId: conversation.id,
              principalId: principal.principal.id,
            },
            tx,
          );
        });
        return event.provider === "discord"
          ? discordQuestionFormDenialResponse()
          : chatQuestionFormDenialResponse(loaded.payload);
      }
      const settledRace = await db.transaction(async (tx) => {
        const currentInteraction = (
          await issueThreadInteractionService(tx as unknown as Db).listForIssue(
            issue.id,
          )
        ).find((candidate) => candidate.id === interaction.id);
        if (!currentInteraction || currentInteraction.status === "pending") {
          return false;
        }
        await enqueueTerminalIssueInteractionChatPublications(
          tx,
          currentInteraction,
        );
        return true;
      });
      if (!settledRace) {
        const status =
          error && typeof error === "object"
            ? (error as { status?: unknown }).status
            : null;
        if (status === 403) {
          return deny(
            "chat_modal_resolution_not_authorized",
            {
              conversationId: conversation.id,
              principalId: principal.principal.id,
            },
            loaded.payload,
          );
        }
        throw error;
      }
      scheduleMessageProcessing(async () => {
        await processPendingPublications();
      });
      if (event.provider === "discord") {
        const current = await loadChatQuestionFormSubmissionToken(db, {
          callbackId: event.event.callbackId,
          companyId: record.endpoint.companyId,
          endpointId: record.endpoint.id,
          includeProcessed: true,
        });
        const resolved = (
          await issueThreadInteractionService(db).listForIssue(
            conversation.issueId,
          )
        ).find((candidate) => candidate.id === interaction.id);
        if (
          current?.status !== "processed" ||
          current.actionRowId !== loaded.actionRowId ||
          current.principalId !== principal.principal.id ||
          current.result?.code !== "question_form_answered" ||
          current.result.interactionId !== interaction.id ||
          resolved?.status !== "answered" ||
          resolved.resolvedByUserId !== principal.userId ||
          !discordReplayAnswersMatch(resolved)
        )
          return deny("chat_modal_resolution_committed_elsewhere");
      }
      return acceptedResponse();
    }
    if (event.event.relatedThread) {
      await recordCurrentMicrosoftTeamsRoute(
        record.endpoint,
        runtimeContext,
        event.event.relatedThread.id,
        event.event.raw,
      );
    }
    scheduleMessageProcessing(async () => {
      await questionResponses.deliver(answered.id);
    });
    return acceptedResponse();
  }

  async function latestSlackDmControlThreadId(
    endpointId: string,
    rawChannelId: string,
  ): Promise<string | null> {
    const conversationIds = [rawChannelId, `slack:${rawChannelId}`];
    return db
      .select({ externalThreadId: chatConversations.externalThreadId })
      .from(chatConversations)
      .innerJoin(
        issues,
        and(
          eq(issues.companyId, chatConversations.companyId),
          eq(issues.id, chatConversations.issueId),
        ),
      )
      .where(
        and(
          eq(chatConversations.endpointId, endpointId),
          inArray(chatConversations.externalConversationId, conversationIds),
          eq(chatConversations.isDirectMessage, true),
          inArray(chatConversations.state, ["active", "waiting"]),
          notInArray(issues.status, ["done", "cancelled"]),
        ),
      )
      .orderBy(
        desc(chatConversations.lastActivityAt),
        desc(chatConversations.createdAt),
      )
      .limit(1)
      .then((rows) => rows[0]?.externalThreadId ?? null);
  }

  async function finalizeSlackTaskStartFailure(input: {
    actionId: string;
    actionStatus: "received" | "validating" | "resolving";
    attempt?: number;
    connectionId: string;
    credentialLease: CredentialMutationLeaseGuard;
    endpoint: EndpointRow;
    error: unknown;
    providerAttempted?: boolean;
    resource: ResourceRow | null;
    runtimeFence: LifecycleRuntimeFence;
  }): Promise<boolean> {
    const attempt = input.attempt ?? 1;
    const classified = classifyChatPublicationError(input.error, attempt);
    // Runtime construction, lease acquisition, and authorization validation
    // happen before the transport fence. Even a socket-shaped error in that
    // phase is known not to have sent a Slack message and remains safely
    // retryable instead of entering the ambiguous-delivery quarantine.
    const classifiedDisposition =
      input.providerAttempted === false &&
      classified.kind === "delivery_unknown"
        ? {
            kind: "retry" as const,
            retryAfterMs: Math.min(60_000, 2 ** Math.max(0, attempt) * 1000),
            reason: classified.reason,
          }
        : classified;
    await input.credentialLease.assertOwned();
    const currentRecord = await endpointRecord(input.endpoint.id);
    const runtimeFenceCurrent =
      currentRecord !== null &&
      runtimeGeneration(currentRecord.endpoint.setup) ===
        input.runtimeFence.generation &&
      credentialFingerprint(currentRecord.credentialSecretRefs) ===
        input.runtimeFence.credentialFingerprint;
    // A provider rejection from credentials that were superseded while this
    // worker lost its lease cannot quarantine the successor endpoint or its
    // resources. Preserve genuinely ambiguous provider acceptance, but make a
    // definite old-runtime rejection safely retryable so the normal worker can
    // re-authorize it against the current endpoint before any new Slack call.
    const disposition =
      !runtimeFenceCurrent && classifiedDisposition.kind !== "delivery_unknown"
        ? {
            kind: "retry" as const,
            retryAfterMs: 1_000,
            reason: "Slack runtime changed before failure settlement",
          }
        : classifiedDisposition;
    const failure = redactSensitiveText(disposition.reason).slice(
      0,
      MAX_ERROR_TEXT,
    );
    const finalized = await db.transaction(async (tx) => {
      await input.credentialLease.assertOwned(tx);
      const [ownedAction] = await tx
        .update(chatActions)
        .set({
          status:
            disposition.kind === "delivery_unknown"
              ? "delivery_unknown"
              : disposition.kind === "retry"
                ? "queued"
                : "failed",
          result: {
            code: runtimeFenceCurrent
              ? `slash_task_${disposition.kind}`
              : disposition.kind === "delivery_unknown"
                ? "slash_task_delivery_unknown"
                : "slash_task_runtime_superseded",
            redactedError: failure,
            retryable: disposition.kind === "retry",
            attemptCount: attempt,
            ...(disposition.kind === "retry"
              ? {
                  retryAt: new Date(
                    Date.now() + disposition.retryAfterMs,
                  ).toISOString(),
                }
              : {}),
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, input.actionId),
            eq(chatActions.status, input.actionStatus),
            sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
          ),
        )
        .returning({ id: chatActions.id });
      if (!ownedAction) return false;
      if (runtimeFenceCurrent && disposition.kind === "endpoint_attention") {
        await tx
          .update(chatEndpoints)
          .set({
            status: "attention",
            healthMessage: "Provider credentials or permissions need attention",
            lastError: failure,
            updatedAt: new Date(),
          })
          .where(eq(chatEndpoints.id, input.endpoint.id));
        await tx
          .update(toolConnections)
          .set({
            status: "disabled",
            enabled: false,
            healthStatus: "degraded",
            healthMessage: "Provider credentials or permissions need attention",
            lastError: failure,
            healthCheckedAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(toolConnections.id, input.connectionId));
      } else if (
        runtimeFenceCurrent &&
        disposition.kind === "resource_unavailable" &&
        input.resource
      ) {
        await tx
          .update(chatEndpointResources)
          .set({ availability: "unavailable", updatedAt: new Date() })
          .where(eq(chatEndpointResources.id, input.resource.id));
      }
      await input.credentialLease.assertOwned(tx);
      return true;
    });
    if (
      finalized &&
      runtimeFenceCurrent &&
      disposition.kind === "endpoint_attention"
    ) {
      // Runtime removal mutates process-local provider state after the durable
      // transaction. Prove this worker still owns the credential fence at the
      // last await boundary so a reclaimer cannot have installed a successor
      // runtime that this obsolete failure would then remove.
      await input.credentialLease.assertOwned();
      await invalidateRuntime(input.endpoint.id).catch(() => undefined);
    }
    return finalized;
  }

  async function admitConfirmedSlackTaskStart(
    actionId: string,
    ingressOnly = true,
  ): Promise<boolean> {
    const admissionClaimId = randomUUID();
    const staleAdmission = new Date(
      Date.now() - SLACK_COMMAND_ADMISSION_STALE_MS,
    );
    const [action] = await db
      .update(chatActions)
      .set({
        status: "admitting",
        result: sql`coalesce(${chatActions.result}, '{}'::jsonb)
          || jsonb_build_object('admissionClaimId', ${admissionClaimId}::text)`,
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "slash_task_start"),
          or(
            eq(chatActions.status, "provider_confirmed"),
            and(
              eq(chatActions.status, "admitting"),
              lte(chatActions.updatedAt, staleAdmission),
            ),
          ),
        ),
      )
      .returning();
    if (!action) return false;
    await options.slackTaskAdmissionClaimBarrier?.({
      actionId: action.id,
      claimId: admissionClaimId,
    });

    const recovery = slackSlashTaskRecoveryPayload(action.payload);
    const confirmed = confirmedSlackTaskStartResult(action.result);
    const ownsAdmission = () =>
      and(
        eq(chatActions.id, action.id),
        eq(chatActions.status, "admitting"),
        sql`${chatActions.result}->>'admissionClaimId' = ${admissionClaimId}`,
      );
    const failAdmission = async (code: string, detail: string) => {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            ...(confirmed ?? {}),
            code,
            redactedError: redactSensitiveText(detail).slice(0, MAX_ERROR_TEXT),
          },
          updatedAt: new Date(),
        })
        .where(ownsAdmission());
    };
    if (!recovery || !confirmed || !action.principalId) {
      await failAdmission(
        "slash_task_admission_context_missing",
        "Confirmed Slack task start lacks durable admission context",
      );
      return true;
    }

    const record = await endpointRecord(action.endpointId);
    if (!record || record.endpoint.provider !== "slack") {
      await failAdmission(
        "slash_task_endpoint_missing",
        "Slack endpoint is no longer available",
      );
      return true;
    }
    if (!["verifying", "active"].includes(record.endpoint.status)) {
      if (record.endpoint.status === "archived") {
        await failAdmission(
          "slash_task_endpoint_archived",
          "Slack endpoint was archived before task admission completed",
        );
      } else {
        // The provider-visible send is already confirmed. Wait for an
        // operator to repair/resume the endpoint, then continue Paperclip-only
        // admission without sending another Slack message.
        await db
          .update(chatActions)
          .set({
            status: "provider_confirmed",
            result: confirmed,
            updatedAt: new Date(),
          })
          .where(ownsAdmission());
      }
      return true;
    }
    const principal = await db
      .select()
      .from(chatExternalPrincipals)
      .where(
        and(
          eq(chatExternalPrincipals.id, action.principalId),
          eq(chatExternalPrincipals.companyId, record.endpoint.companyId),
          eq(chatExternalPrincipals.provider, "slack"),
          eq(
            chatExternalPrincipals.providerAccountId,
            record.endpoint.providerAccountId ?? "unknown",
          ),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!principal || principal.isBot || principal.kind !== "user") {
      await failAdmission(
        "slash_task_principal_missing",
        "Original Slack account is no longer available",
      );
      return true;
    }

    const author = {
      userId: principal.externalId,
      userName: principal.handle ?? principal.externalId,
      fullName:
        principal.displayName ?? principal.handle ?? principal.externalId,
      isBot: false,
      isMe: false,
      isSystem: false,
    } satisfies Author;
    try {
      const endpointRuntime = await runtimeFor(record.endpoint);
      const thread = endpointRuntime.thread(confirmed.threadId);
      await processMessage(
        record.endpoint,
        thread,
        {
          id: recovery.syntheticMessageId,
          threadId: thread.id,
          text: recovery.taskText,
          formatted: { type: "root", children: [] },
          raw: { recoveredFromActionId: action.id },
          author,
          metadata: { dateSent: action.createdAt, edited: false },
          attachments: [],
          links: [],
          isMention: true,
        } as unknown as Message,
        "mention",
        ingressOnly,
        null,
        { ...runtimeContextForRecord(record), endpointRuntime },
        undefined,
        null,
        false,
        undefined,
        false,
        true,
      );
      await db
        .update(chatActions)
        .set({ status: "processed", result: confirmed, updatedAt: new Date() })
        .where(ownsAdmission());
      return true;
    } catch (error) {
      // The provider post is already confirmed, so this retry is strictly a
      // Paperclip admission retry. Preserve the root tuple and let the durable
      // reconciler resume without ever posting to Slack again.
      await db
        .update(chatActions)
        .set({
          status: "provider_confirmed",
          result: {
            ...confirmed,
            code: "slash_task_admission_retry",
            redactedError: redactError(error),
          },
          updatedAt: new Date(),
        })
        .where(ownsAdmission());
      throw error;
    }
  }

  async function processSlackTaskStart(
    actionId: string,
    ingressOnly = true,
  ): Promise<boolean> {
    let action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "slash_task_start"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!action) return false;

    if (
      action.status === "provider_confirmed" ||
      action.status === "admitting"
    ) {
      return await admitConfirmedSlackTaskStart(action.id, ingressOnly);
    }
    if (action.status === "resolving") {
      if (
        action.updatedAt.getTime() <=
        Date.now() - SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS
      ) {
        const staleRecord = await endpointRecord(action.endpointId);
        if (!staleRecord) return false;
        await withCredentialMutationLease(
          staleRecord.endpoint,
          async (credentialLease) => {
            await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              await tx
                .update(chatActions)
                .set({
                  status: "delivery_unknown",
                  result: {
                    ...(action.result ?? {}),
                    code: "slash_task_delivery_unknown",
                  },
                  updatedAt: new Date(),
                })
                .where(
                  and(
                    eq(chatActions.id, action.id),
                    eq(chatActions.status, "resolving"),
                    eq(chatActions.updatedAt, action.updatedAt),
                    lte(
                      chatActions.updatedAt,
                      new Date(
                        Date.now() - SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS,
                      ),
                    ),
                  ),
                );
              await credentialLease.assertOwned(tx);
            });
          },
        );
      }
      return false;
    }
    if (action.status === "validating") {
      if (
        action.updatedAt.getTime() <=
        Date.now() - SLACK_COMMAND_POST_STALE_MS
      ) {
        const staleRecord = await endpointRecord(action.endpointId);
        if (!staleRecord) return false;
        await withCredentialMutationLease(
          staleRecord.endpoint,
          async (credentialLease) => {
            await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              await tx
                .update(chatActions)
                .set({ status: "queued", updatedAt: new Date() })
                .where(
                  and(
                    eq(chatActions.id, action.id),
                    eq(chatActions.status, "validating"),
                    eq(chatActions.updatedAt, action.updatedAt),
                    lte(
                      chatActions.updatedAt,
                      new Date(Date.now() - SLACK_COMMAND_POST_STALE_MS),
                    ),
                  ),
                );
              await credentialLease.assertOwned(tx);
            });
          },
        );
      }
      return false;
    }
    if (action.status !== "queued") return false;
    const retryAt =
      typeof action.result?.retryAt === "string"
        ? new Date(action.result.retryAt)
        : null;
    if (
      retryAt &&
      !Number.isNaN(retryAt.getTime()) &&
      retryAt.getTime() > Date.now()
    ) {
      return false;
    }
    const attempt =
      (typeof action.result?.attemptCount === "number" &&
      Number.isSafeInteger(action.result.attemptCount)
        ? Math.max(0, action.result.attemptCount)
        : 0) + 1;

    const [claimed] = await db
      .update(chatActions)
      .set({
        status: "validating",
        result: { attemptCount: attempt },
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(chatActions.id, action.id),
          eq(chatActions.kind, "slash_task_start"),
          eq(chatActions.status, action.status),
        ),
      )
      .returning();
    if (!claimed) return false;
    action = claimed;

    const recovery = slackSlashTaskRecoveryPayload(action.payload);
    const initialRecord = await endpointRecord(action.endpointId);
    if (
      !recovery ||
      !initialRecord ||
      initialRecord.endpoint.provider !== "slack"
    ) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            code: "slash_task_provider_context_missing",
            retryable: false,
            attemptCount: attempt,
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "validating"),
            sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
          ),
        );
      return true;
    }
    let providerPostStarted = false;
    let transportClaimed = false;
    let failureResource: ResourceRow | null = null;
    let failureRuntimeFence = runtimeContextForRecord(initialRecord);
    let failureSettledUnderLease = false;
    let confirmedActionId: string | null = null;
    try {
      const processed = await withCredentialMutationLease(
        initialRecord.endpoint,
        async (credentialLease) => {
          const record = await endpointRecord(action.endpointId);
          if (!record || record.endpoint.provider !== "slack") {
            await db
              .update(chatActions)
              .set({
                status: "failed",
                result: {
                  code: "slash_task_provider_context_missing",
                  retryable: false,
                  attemptCount: attempt,
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "validating"),
                  sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
                ),
              );
            return true;
          }
          failureRuntimeFence = runtimeContextForRecord(record);
          if (!["verifying", "active"].includes(record.endpoint.status)) {
            const terminallyArchived = record.endpoint.status === "archived";
            await db
              .update(chatActions)
              .set({
                status: terminallyArchived ? "cancelled" : "queued",
                result: {
                  code: terminallyArchived
                    ? "slash_task_endpoint_archived"
                    : "slash_task_endpoint_waiting",
                  attemptCount: attempt - 1,
                  ...(terminallyArchived
                    ? {}
                    : {
                        retryAt: new Date(Date.now() + 5_000).toISOString(),
                      }),
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "validating"),
                  sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
                ),
              );
            return false;
          }

          const principal = action.principalId
            ? await db
                .select()
                .from(chatExternalPrincipals)
                .where(
                  and(
                    eq(chatExternalPrincipals.id, action.principalId),
                    eq(
                      chatExternalPrincipals.companyId,
                      record.endpoint.companyId,
                    ),
                    eq(chatExternalPrincipals.provider, "slack"),
                    eq(
                      chatExternalPrincipals.providerAccountId,
                      record.endpoint.providerAccountId ?? "unknown",
                    ),
                  ),
                )
                .then((rows) => rows[0] ?? null)
            : null;
          let principalAllowed = false;
          if (principal && !principal.isBot && principal.kind === "user") {
            const link = await db
              .select({
                paperclipUserId: chatIdentityLinks.paperclipUserId,
                status: chatIdentityLinks.status,
              })
              .from(chatIdentityLinks)
              .where(
                and(
                  eq(chatIdentityLinks.endpointId, record.endpoint.id),
                  eq(chatIdentityLinks.principalId, principal.id),
                ),
              )
              .then((rows) => rows[0] ?? null);
            if (link?.status === "linked" && link.paperclipUserId) {
              principalAllowed = await db
                .select({ id: companyMemberships.id })
                .from(companyMemberships)
                .where(
                  and(
                    eq(companyMemberships.companyId, record.endpoint.companyId),
                    eq(companyMemberships.principalType, "user"),
                    eq(companyMemberships.principalId, link.paperclipUserId),
                    eq(companyMemberships.status, "active"),
                    ne(companyMemberships.membershipRole, "viewer"),
                  ),
                )
                .then((rows) => rows.length > 0);
            } else if (record.endpoint.allowUnlinkedPeople) {
              principalAllowed = await sponsorAllowsGuest(record.endpoint);
            }
          }

          const rawChannelId = recovery.channelId.replace(/^slack:/, "");
          const isDirectMessage = /^D[A-Z0-9]+$/i.test(rawChannelId);
          const resource = await db
            .select()
            .from(chatEndpointResources)
            .where(
              and(
                eq(chatEndpointResources.endpointId, record.endpoint.id),
                eq(chatEndpointResources.providerResourceId, rawChannelId),
              ),
            )
            .then((rows) => rows[0] ?? null);
          failureResource = resource;
          const destinationAllowed = isDirectMessage
            ? record.endpoint.allowDirectMessages
            : nonDirectDestinationAllowed(record.endpoint, resource);
          if (!principalAllowed || !destinationAllowed) {
            await db
              .update(chatActions)
              .set({
                status: "cancelled",
                result: {
                  code: "slash_task_no_longer_authorized",
                  attemptCount: attempt,
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "validating"),
                  sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
                ),
              );
            return true;
          }

          const endpointRuntime = await runtimeFor(record.endpoint);
          const baseThread = endpointRuntime.thread(`slack:${rawChannelId}:`);
          const authorizationSnapshot = await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            const currentEndpoint = await runtimeCallbackEndpoint(
              tx,
              record.endpoint.id,
              runtimeContextForRecord(record),
              ["verifying", "active"],
            );
            const currentResource = currentEndpoint
              ? await tx
                  .select()
                  .from(chatEndpointResources)
                  .where(
                    and(
                      eq(
                        chatEndpointResources.companyId,
                        currentEndpoint.companyId,
                      ),
                      eq(chatEndpointResources.endpointId, currentEndpoint.id),
                      eq(
                        chatEndpointResources.providerResourceId,
                        rawChannelId,
                      ),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
            const currentAuthorization =
              currentEndpoint && action!.principalId
                ? await lockCurrentPrincipalAuthorization(
                    tx,
                    currentEndpoint,
                    action!.principalId,
                  )
                : null;
            const currentDestinationAllowed = currentEndpoint
              ? isDirectMessage
                ? currentEndpoint.allowDirectMessages
                : nonDirectDestinationAllowed(currentEndpoint, currentResource)
              : false;
            if (
              !currentEndpoint ||
              !currentAuthorization?.allowed ||
              !currentDestinationAllowed
            ) {
              await tx
                .update(chatActions)
                .set({
                  status: "cancelled",
                  result: {
                    code: "slash_task_no_longer_authorized",
                    attemptCount: attempt,
                  },
                  updatedAt: new Date(),
                })
                .where(
                  and(
                    eq(chatActions.id, action!.id),
                    eq(chatActions.status, "validating"),
                    sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
                  ),
                );
              return null;
            }

            failureResource = currentResource;
            const [transportClaim] = await tx
              .update(chatActions)
              .set({
                status: "resolving",
                result: {
                  attemptCount: attempt,
                  authorizedUserId: currentAuthorization.userId,
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action!.id),
                  eq(chatActions.status, "validating"),
                  sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
                ),
              )
              .returning({ id: chatActions.id });
            return transportClaim
              ? { authorizedUserId: currentAuthorization.userId }
              : null;
          });
          if (!authorizationSnapshot) return false;

          // `resolving` is the durable, single-owner transport claim. The
          // authorization snapshot above commits and releases every row lock
          // before Slack I/O starts. A crash after Slack accepts the post is
          // quarantined as delivery_unknown and is never replayed implicitly.
          transportClaimed = true;
          providerPostStarted = true;
          let starter: Awaited<ReturnType<typeof baseThread.post>>;
          try {
            starter = await baseThread.post("Starting a task…");
          } catch (error) {
            try {
              await finalizeSlackTaskStartFailure({
                actionId: action.id,
                actionStatus: "resolving",
                attempt,
                connectionId: record.endpoint.connectionId,
                credentialLease,
                endpoint: record.endpoint,
                error,
                providerAttempted: true,
                resource: failureResource,
                runtimeFence: failureRuntimeFence,
              });
              failureSettledUnderLease = true;
            } catch {
              // If ownership was reclaimed while Slack was in flight, the
              // outer recovery path reacquires the endpoint lease and settles
              // the attempt without applying stale health state.
            }
            throw error;
          }
          const threadId = slackTaskStarterThreadId(rawChannelId, starter.id);
          const [providerConfirmed] = await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            return tx
              .update(chatActions)
              .set({
                status: "provider_confirmed",
                result: {
                  attemptCount: attempt,
                  authorizedUserId: authorizationSnapshot.authorizedUserId,
                  threadId,
                  providerMessageId: starter.id,
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "resolving"),
                  sql`(${chatActions.result}->>'attemptCount')::int = ${attempt}`,
                ),
              )
              .returning();
          });
          if (!providerConfirmed) {
            throw new Error(
              "Slack task-start ownership changed after provider acceptance",
            );
          }
          // Provider transport and its durable confirmation remain fenced by
          // the credential lease. Paperclip-only task admission happens after
          // this callback returns and releases that lease: normal admission
          // stages a receipt reaction, whose independently fenced worker must
          // acquire the same lease and would otherwise self-deadlock here.
          confirmedActionId = providerConfirmed.id;
          return true;
        },
      );
      if (typeof confirmedActionId === "string") {
        await admitConfirmedSlackTaskStart(confirmedActionId, ingressOnly);
      }
      return processed;
    } catch (error) {
      if (!failureSettledUnderLease) {
        await withCredentialMutationLease(
          initialRecord.endpoint,
          async (credentialLease) => {
            await finalizeSlackTaskStartFailure({
              actionId: action.id,
              actionStatus: transportClaimed ? "resolving" : "validating",
              attempt,
              connectionId: initialRecord.endpoint.connectionId,
              credentialLease,
              endpoint: initialRecord.endpoint,
              error,
              providerAttempted: providerPostStarted,
              resource: failureResource,
              runtimeFence: failureRuntimeFence,
            });
          },
        );
      }
      throw error;
    }
  }

  async function processPendingSlackTaskStarts(limit: number) {
    const now = new Date();
    const staleAdmission = new Date(
      now.getTime() - SLACK_COMMAND_ADMISSION_STALE_MS,
    );
    const staleProviderPost = new Date(
      now.getTime() - SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS,
    );
    const staleValidation = new Date(
      now.getTime() - SLACK_COMMAND_POST_STALE_MS,
    );
    const actions = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .leftJoin(chatEndpoints, eq(chatEndpoints.id, chatActions.endpointId))
      .where(
        // Provider-confirmed rows need no provider retry and have no due
        // timestamp. Park them while an endpoint is repairable but paused
        // or in attention; otherwise an old page can starve active work
        // forever. Archived and missing endpoints remain eligible so their
        // actions can be terminalized.
        and(
          eq(chatActions.kind, "slash_task_start"),
          or(
            and(
              eq(chatActions.status, "queued"),
              sql`(${chatActions.result}->>'retryAt' is null or ${chatActions.result}->>'retryAt' <= ${now.toISOString()})`,
            ),
            and(
              eq(chatActions.status, "provider_confirmed"),
              or(
                isNull(chatEndpoints.id),
                inArray(chatEndpoints.status, [
                  "verifying",
                  "active",
                  "archived",
                ]),
              ),
            ),
            and(
              eq(chatActions.status, "admitting"),
              lte(chatActions.updatedAt, staleAdmission),
            ),
            and(
              eq(chatActions.status, "resolving"),
              lte(chatActions.updatedAt, staleProviderPost),
            ),
            and(
              eq(chatActions.status, "validating"),
              lte(chatActions.updatedAt, staleValidation),
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.createdAt))
      .limit(limit);
    let processed = 0;
    for (let offset = 0; offset < actions.length; offset += 4) {
      const results = await Promise.all(
        actions.slice(offset, offset + 4).map(async (action) => {
          try {
            return await processSlackTaskStart(action.id);
          } catch (error) {
            logger.warn(
              { actionId: action.id, error: redactError(error) },
              "Slack task start will retry or await explicit resolution",
            );
            return false;
          }
        }),
      );
      processed += results.filter(Boolean).length;
    }
    return processed;
  }

  async function handleDiscordNativeCommand(
    event: ChatSdkCallbackEvent<SlashCommandEvent>,
    runtimeContext: RuntimeContext,
  ): Promise<DiscordNativeCommandResponse> {
    const denied: DiscordNativeCommandResponse = { kind: "denied" };
    const record = await runtimeCallbackRecord(
      event.endpointId,
      runtimeContext,
      ["active"],
    );
    if (
      !record ||
      record.endpoint.provider !== "discord" ||
      record.endpoint.capabilities.slashCommands !== true ||
      event.transport !== "discord_gateway" ||
      runtimeContext.discordGatewayOwned !== true
    )
      return denied;
    const scope = {
      companyId: record.endpoint.companyId,
      endpointId: record.endpoint.id,
      applicationId: record.endpoint.botExternalId ?? "",
      guildId: record.endpoint.providerAccountId ?? "",
    };
    const invocation = parseDiscordNativeCommand(event, scope);
    if (!invocation) return denied;
    const initialRegistration = await readRegisteredDiscordCommandRegistration(
      db,
      scope,
    );
    if (
      initialRegistration?.receipt.commandId !== invocation.registeredCommandId
    )
      return denied;
    const principal = await ensurePrincipal(
      record.endpoint,
      event.event.user,
      event.event.raw,
    );
    const authorityChanged = new Error("Discord command authority changed");
    let publish = false;
    try {
      const response = await db.transaction(
        async (tx): Promise<DiscordNativeCommandResponse> => {
          const endpoint = await runtimeCallbackEndpoint(
            tx,
            scope.endpointId,
            runtimeContext,
            ["active"],
          );
          if (
            !endpoint ||
            endpoint.companyId !== scope.companyId ||
            endpoint.provider !== "discord" ||
            endpoint.botExternalId !== scope.applicationId ||
            endpoint.providerAccountId !== scope.guildId ||
            endpoint.capabilities.slashCommands !== true
          )
            return denied;
          const connection = await tx
            .select()
            .from(toolConnections)
            .where(
              and(
                eq(toolConnections.companyId, scope.companyId),
                eq(toolConnections.id, endpoint.connectionId),
              ),
            )
            .for("no key update")
            .then((rows) => rows[0] ?? null);
          if (
            !connection ||
            !connection.enabled ||
            connection.status !== "active" ||
            credentialFingerprint(connection.credentialSecretRefs) !==
              runtimeContext.credentialFingerprint
          )
            return denied;
          const registration = await readRegisteredDiscordCommandRegistration(
            tx,
            scope,
            true,
          );
          if (
            registration?.receipt.commandId !== invocation.registeredCommandId
          )
            return denied;
          const providerActionId = `discord-native-command:${invocation.interactionId}`;
          const prior = await tx
            .select()
            .from(chatActions)
            .where(
              and(
                eq(chatActions.companyId, scope.companyId),
                eq(chatActions.endpointId, scope.endpointId),
                eq(chatActions.providerActionId, providerActionId),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null);
          const receipt = prior
            ? parseDiscordNativeCommandReceipt(prior, invocation, scope)
            : null;
          if (
            prior &&
            (!receipt ||
              receipt.principalId !== principal.principal.id ||
              receipt.runtimeFence.generation !== runtimeContext.generation ||
              receipt.runtimeFence.credentialFingerprint !==
                runtimeContext.credentialFingerprint)
          )
            return denied;
          // A replay selects only its original target, including a completed
          // generation. Never reinterpret an old close as a new task's command.
          const conversation = receipt
            ? receipt.target
              ? await tx
                  .select()
                  .from(chatConversations)
                  .where(
                    and(
                      eq(chatConversations.companyId, scope.companyId),
                      eq(chatConversations.endpointId, scope.endpointId),
                      eq(chatConversations.id, receipt.target.conversationId),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null
            : invocation.sourceKind !== "guild_channel"
              ? await tx
                  .select()
                  .from(chatConversations)
                  .where(
                    and(
                      eq(chatConversations.companyId, scope.companyId),
                      eq(chatConversations.endpointId, scope.endpointId),
                      eq(
                        chatConversations.externalConversationId,
                        invocation.channelId,
                      ),
                      eq(
                        chatConversations.externalThreadId,
                        invocation.threadId,
                      ),
                    ),
                  )
                  .orderBy(desc(chatConversations.sessionGeneration))
                  .limit(1)
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
          if (
            (receipt?.target && !conversation) ||
            (conversation &&
              (conversation.externalConversationId !== invocation.channelId ||
                conversation.externalThreadId !== invocation.threadId ||
                conversation.isDirectMessage !==
                  (invocation.sourceKind === "direct_message") ||
                !["active", "waiting", "completed"].includes(
                  conversation.state,
                ) ||
                (receipt?.target &&
                  (conversation.issueId !== receipt.target.issueId ||
                    conversation.sessionGeneration !==
                      receipt.target.sessionGeneration))))
          )
            return denied;
          const resource =
            invocation.sourceKind === "direct_message"
              ? null
              : await tx
                  .select()
                  .from(chatEndpointResources)
                  .where(
                    and(
                      eq(chatEndpointResources.companyId, scope.companyId),
                      eq(chatEndpointResources.endpointId, scope.endpointId),
                      eq(
                        chatEndpointResources.providerResourceId,
                        invocation.providerResourceId,
                      ),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null);
          if (
            invocation.sourceKind === "direct_message"
              ? !endpoint.allowDirectMessages
              : !nonDirectDestinationAllowed(endpoint, resource) ||
                (conversation && conversation.resourceId !== resource?.id)
          )
            return denied;
          const authorization = await lockCurrentPrincipalAuthorization(
            tx,
            endpoint,
            principal.principal.id,
          );
          if (
            !authorization.allowed ||
            authorization.userId !== principal.userId
          )
            return denied;
          const issue = conversation
            ? await tx
                .select()
                .from(issues)
                .where(
                  and(
                    eq(issues.companyId, scope.companyId),
                    eq(issues.id, conversation.issueId),
                  ),
                )
                .for("share")
                .then((rows) => rows[0] ?? null)
            : null;
          if (conversation && !issue) return denied;
          const ownership = discordGatewayOwnerships.get(scope.endpointId);
          if (
            !ownership ||
            !discordGatewayRuntimeIsCurrent(scope.endpointId, runtimeContext)
          )
            return denied;
          const lease = await tx
            .select()
            .from(chatEndpointLeases)
            .where(
              and(
                eq(chatEndpointLeases.companyId, scope.companyId),
                eq(chatEndpointLeases.endpointId, scope.endpointId),
                eq(chatEndpointLeases.leaseKey, ownership.leaseKey),
                eq(chatEndpointLeases.token, ownership.token),
                gt(chatEndpointLeases.expiresAt, new Date()),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null);
          if (
            !lease ||
            !discordGatewayRuntimeIsCurrent(scope.endpointId, runtimeContext)
          )
            return denied;
          if (receipt)
            return { kind: "accepted", content: receipt.result.content };
          const target: DiscordNativeCommandTarget | null = conversation
            ? {
                conversationId: conversation.id,
                issueId: conversation.issueId,
                sessionGeneration: conversation.sessionGeneration,
              }
            : null;
          const active =
            conversation &&
            issue &&
            ["active", "waiting"].includes(conversation.state) &&
            (invocation.sourceKind !== "direct_message" ||
              !["done", "cancelled"].includes(issue.status));
          let content: string;
          let publicationId: string | null = null;
          if (invocation.command === "status") {
            content =
              issue && (invocation.sourceKind !== "direct_message" || active)
                ? `${issue.identifier}: ${issue.title} — ${issue.status}${conversation?.state === "completed" ? " (conversation closed)" : ""}`.slice(
                    0,
                    2000,
                  )
                : invocation.sourceKind === "guild_channel"
                  ? "Open the Discord task thread to view its Paperclip status."
                  : "No task is active in this conversation.";
          } else if (
            invocation.command === "new" &&
            invocation.sourceKind !== "direct_message"
          ) {
            content =
              "Open a new Discord thread by mentioning this agent in a new channel message. This thread stays bound to its current Paperclip task.";
          } else if (!active || !conversation || !issue) {
            content =
              invocation.sourceKind === "direct_message"
                ? "No task is active. Send a message to start a new Paperclip task."
                : "No active task is bound here. Open its Discord thread to manage it.";
          } else if ((await readChatControlChronology(
            tx,
            record.endpoint,
            { id: conversation.externalThreadId, channelId: conversation.externalConversationId },
            { receivedAt: new Date(), normalizedEvent: { message: { providerMessageId: invocation.interactionId } } },
          )) === "before_or_unproven") {
            content = "This command predates an already completed chat control. Send a new command for the current conversation.";
          } else {
            const publicText =
              invocation.command === "new"
                ? "Send your request to start a new Paperclip task."
                : invocation.sourceKind === "direct_message"
                  ? "This chat conversation is closed. Send another message to start a new task."
                  : "This chat conversation is closed. A later message here will continue the same Paperclip task.";
            const publication = await stageAuthorizedTaskControlPublication(
              tx,
              {
                companyId: scope.companyId,
                endpointId: scope.endpointId,
                conversationId: conversation.id,
                issueId: issue.id,
                principalId: principal.principal.id,
                idempotencyKey: `control:${invocation.command}:discord:${scope.endpointId}:${invocation.interactionId}`,
                payload: projectSafeChatPublication({
                  classification: "external",
                  source: "task_control",
                  text: publicText,
                }),
              },
            );
            publicationId = publication.id;
            content = `${invocation.command === "new" ? "New-task" : "Close"} request recorded. Watch this conversation for confirmation.`;
          }
          const inserted = await tx
            .insert(chatActions)
            .values({
              companyId: scope.companyId,
              endpointId: scope.endpointId,
              conversationId: target?.conversationId ?? null,
              principalId: principal.principal.id,
              kind: "discord_native_command",
              providerActionId,
              payload: {
                version: 1,
                invocation,
                runtimeFence: {
                  generation: runtimeContext.generation,
                  credentialFingerprint: runtimeContext.credentialFingerprint,
                },
                target,
              },
              status: "processed",
              result: {
                kind: "discord_native_command_recorded",
                content,
                publicationId,
              },
            })
            .onConflictDoNothing()
            .returning({ id: chatActions.id });
          if (!inserted.length) throw authorityChanged;
          await logActivity(tx as unknown as Db, {
            companyId: scope.companyId,
            actorType: authorization.userId ? "user" : "system",
            actorId: authorization.userId ?? `chat:${principal.principal.id}`,
            action: "chat.discord_command_recorded",
            entityType: "chat_endpoint",
            entityId: scope.endpointId,
            details: {
              command: invocation.command,
              interactionId: invocation.interactionId,
              conversationId: target?.conversationId ?? null,
              sessionGeneration: target?.sessionGeneration ?? null,
              publicationId,
            },
          });
          // No network work is performed under these locks. A stop while any DB
          // await was in flight rolls back the command and its staged outbox row.
          if (
            !discordGatewayRuntimeIsCurrent(scope.endpointId, runtimeContext) ||
            lease.expiresAt.getTime() <= Date.now()
          )
            throw authorityChanged;
          publish = publicationId !== null;
          return { kind: "accepted", content };
        },
      );
      if (publish)
        scheduleMessageProcessing(async () => {
          await processPendingPublications();
        });
      return response;
    } catch (error) {
      if (error === authorityChanged) return denied;
      throw error;
    }
  }

  async function handleSlashCommand(
    event: ChatSdkCallbackEvent<SlashCommandEvent>,
    runtimeContext: RuntimeContext,
  ) {
    if (event.provider === "discord")
      return handleDiscordNativeCommand(event, runtimeContext);
    const record = await runtimeCallbackRecord(
      event.endpointId,
      runtimeContext,
      ["verifying", "active"],
    );
    if (!record) return;
    const command = event.event.command.toLowerCase().split("@")[0];
    const text = event.event.text.trim();
    if (event.provider === "telegram") {
      const endpointRuntime =
        runtime.get(event.endpointId) ?? (await runtimeFor(record.endpoint));
      const thread = endpointRuntime.thread(event.event.channel.id);
      const parsedCommandMessage =
        endpointRuntime.parseTelegramCommandMessage?.(event.event.raw) ?? null;
      const synthetic = {
        id:
          telegramMessageId(event.event.raw) ??
          event.event.triggerId ??
          createHash("sha256")
            .update(
              JSON.stringify({
                command,
                raw: event.event.raw,
                userId: event.event.user.userId,
              }),
            )
            .digest("hex"),
        threadId: thread.id,
        // Telegram privacy mode does not deliver an ordinary @mention in a
        // group. /task@bot <request> is therefore the provider-native root
        // activation path; direct replies and later /task commands can
        // continue the same active group/topic task.
        text: command === "/task" && text ? text : command,
        formatted: { type: "root", children: [] },
        raw: event.event.raw,
        author: event.event.user,
        metadata: {
          // Telegram slash commands carry the original message as `raw`.
          // Preserve its whole-second provider clock so the durable drain can
          // use message_id to order a command and the next rapid DM correctly.
          dateSent: telegramMessageSentAt(event.event.raw) ?? new Date(),
          edited: false,
        },
        // Telegram routes a captioned file command through onSlashCommand
        // instead of the ordinary message callback. Preserve the provider's
        // parsed attachment descriptors so the durable delivery worker can
        // rehydrate and ingest them exactly like non-command media.
        attachments: parsedCommandMessage?.attachments ?? [],
        links: [],
        isMention: true,
      } as unknown as Message;
      await handleSdkMessage(
        {
          endpointId: event.endpointId,
          provider: event.provider,
          thread,
          message: synthetic,
          trigger: thread.isDM ? "direct_message" : "mention",
        },
        runtimeContext,
      );
      return;
    }
    const providerCommandId =
      event.event.triggerId ??
      createHash("sha256")
        .update(JSON.stringify(event.event.raw))
        .digest("hex");
    const queueSlackNotice = async (
      notice: string,
      principalId?: string | null,
    ) => {
      const noticeKey = createHash("sha256")
        .update(
          JSON.stringify([
            event.event.command,
            event.event.user.userId,
            providerCommandId,
            event.event.text,
          ]),
        )
        .digest("hex");
      const effect = await db.transaction((tx) =>
        stageProviderEffect(tx, {
          endpoint: record.endpoint,
          principalId: principalId ?? null,
          providerActionId: `provider_effect:slash_notice:${noticeKey}`,
          payload: {
            version: 1,
            effect: "ephemeral_message",
            authorizationMode: "safe_notice",
            threadId: event.event.channel.id,
            userId: event.event.user.userId,
            text: notice,
            settleDelivery: false,
          },
          runtimeContext,
        }),
      );
      if (!effect) throw new Error("Slack notice was not persisted");
      scheduleProviderEffect(effect.id, event.event.channel);
    };
    if (!["verifying", "active"].includes(record.endpoint.status)) {
      await queueSlackNotice("This Paperclip connection is not active.");
      return;
    }
    const expectedCommand =
      typeof record.endpoint.setup.command === "string"
        ? record.endpoint.setup.command
        : slackCommandForAgent(
            record.assignedAgentName,
            record.endpoint.publicId,
          );
    if (event.provider !== "slack" || command !== expectedCommand) {
      await queueSlackNotice(
        `This connection only accepts ${expectedCommand}.`,
      );
      return;
    }
    const principal = await ensurePrincipal(
      record.endpoint,
      event.event.user,
      event.event.raw,
    );
    const resource = await db
      .select()
      .from(chatEndpointResources)
      .where(
        and(
          eq(chatEndpointResources.endpointId, event.endpointId),
          eq(
            chatEndpointResources.providerResourceId,
            canonicalProviderResourceId(event.provider, {
              channelId: event.event.channel.id,
              id: event.event.channel.id,
            }),
          ),
        ),
      )
      .then((rows) => rows[0] ?? null);
    // Slack's SDK channel wrapper has reported false for isDM on real slash
    // callbacks even though the signed payload contains a D-prefixed channel
    // id. The provider id is authoritative for this routing decision.
    const rawSlackChannelId = event.event.channel.id.replace(/^slack:/, "");
    const slashIsDirectMessage = /^D[A-Z0-9]+$/i.test(rawSlackChannelId)
      ? true
      : event.event.channel.isDM;
    const destinationAllowed = slashIsDirectMessage
      ? record.endpoint.allowDirectMessages
      : nonDirectDestinationAllowed(record.endpoint, resource);
    const authorized =
      destinationAllowed &&
      !principal.linkedDenied &&
      (principal.userId !== null ||
        (record.endpoint.allowUnlinkedPeople &&
          (await sponsorAllowsGuest(record.endpoint))));
    if (!authorized) {
      await queueSlackNotice(
        "This channel or account is not allowed to start Paperclip work.",
        principal.principal.id,
      );
      return;
    }
    const slackControl = /^(status|new|close)$/i
      .exec(text)?.[1]
      ?.toLowerCase() as "status" | "new" | "close" | undefined;
    if (slackControl) {
      if (!slashIsDirectMessage) {
        // Slack slash-command payloads are channel-scoped and do not carry a
        // thread timestamp, so they cannot safely identify one of several
        // Paperclip tasks in the channel. Native @mention threads remain the
        // task-management surface there; the control vocabulary is exact only
        // in a DM, whose provider channel identity is stable.
        await queueSlackNotice(
          "Use status, new, and close in a direct message with this agent. In a channel, open the Paperclip task from its Slack thread.",
          principal.principal.id,
        );
        return;
      }
      const endpointRuntime =
        runtime.get(event.endpointId) ?? (await runtimeFor(record.endpoint));
      // A slash-command task starts a real Slack root and binds Paperclip to
      // that returned thread id. Later slash controls carry only the DM channel
      // id, so target the most recently active task instead of synthesizing an
      // unrelated base-DM thread that cannot find the binding.
      const activeThreadId = await latestSlackDmControlThreadId(
        event.endpointId,
        rawSlackChannelId,
      );
      const thread = endpointRuntime.thread(
        activeThreadId ?? `slack:${rawSlackChannelId}:`,
      );
      const synthetic = {
        id: createHash("sha256")
          .update(
            `${event.event.command}:${event.event.user.userId}:${providerCommandId}:${slackControl}`,
          )
          .digest("hex"),
        threadId: thread.id,
        text: `/${slackControl}`,
        formatted: { type: "root", children: [] },
        raw: event.event.raw,
        author: event.event.user,
        metadata: { dateSent: new Date(), edited: false },
        attachments: [],
        links: [],
        isMention: true,
      } as unknown as Message;
      await handleSdkMessage(
        {
          endpointId: event.endpointId,
          provider: event.provider,
          thread,
          message: synthetic,
          trigger: "direct_message",
        },
        runtimeContext,
        { receiptReactionSupported: false, slackSlashControl: true },
      );
      return;
    }
    if (!text) {
      await queueSlackNotice(
        `Use ${expectedCommand} followed by a task, or ${expectedCommand} status, new, or close in a direct message.`,
        principal.principal.id,
      );
      return;
    }
    const providerActionId = `slash_task:${createHash("sha256")
      .update(
        `${event.event.command}:${event.event.user.userId}:${providerCommandId}`,
      )
      .digest("hex")}`;
    const syntheticMessageId = createHash("sha256")
      .update(
        `${event.event.command}:${event.event.user.userId}:${providerCommandId}`,
      )
      .digest("hex");
    // A duplicate Slack retry must acknowledge from the already-durable row
    // without waiting for the first worker's endpoint/identity locks or Web
    // API request. Slack otherwise treats a healthy in-flight command as an
    // acknowledgement timeout and retries it again.
    const existingAction = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.endpointId, record.endpoint.id),
          eq(chatActions.providerActionId, providerActionId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    const insertedAction = existingAction
      ? null
      : await db.transaction(async (tx) => {
          if (
            !(await runtimeCallbackEndpoint(
              tx,
              event.endpointId,
              runtimeContext,
              ["verifying", "active"],
            ))
          )
            return null;
          return tx
            .insert(chatActions)
            .values({
              companyId: record.endpoint.companyId,
              endpointId: record.endpoint.id,
              principalId: principal.principal.id,
              kind: "slash_task_start",
              providerActionId,
              payload: {
                version: 1,
                channelId: event.event.channel.id,
                command,
                syntheticMessageId,
                taskText: text,
              },
              status: "queued",
            })
            .onConflictDoNothing()
            .returning()
            .then((rows) => rows[0] ?? null);
        });
    const action =
      existingAction ??
      insertedAction ??
      (await db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, record.endpoint.id),
            eq(chatActions.providerActionId, providerActionId),
          ),
        )
        .then((rows) => rows[0] ?? null));
    if (!action) throw new Error("Slack command admission was not persisted");
    // Slack has a tight acknowledgement budget. The unique action row is the
    // durable receipt; provider publication and Paperclip admission run behind
    // the acknowledgement under an atomic `received -> resolving` claim.
    // Duplicate callbacks schedule the same id and converge without waiting
    // on Slack's Web API or creating a second root.
    scheduleMessageProcessing(async () => {
      await processSlackTaskStart(
        action.id,
        options.deferWebhookProcessing === true,
      );
    });
  }

  async function applyProviderLifecycleEffect(
    endpoint: EndpointRow,
    effect: ChatProviderLifecycleEffect,
    runtimeContext?: RuntimeContext,
  ): Promise<boolean> {
    const providerEventId = `lifecycle:${effect.providerEventId}`;
    const deduplicationKey = createHash("sha256")
      .update(`${effect.provider}:${providerEventId}`)
      .digest("hex");
    const eventKind: ChatEventKind =
      effect.availability === "available" ? "installation" : "uninstallation";
    const [inserted] = await db
      .insert(chatDeliveries)
      .values({
        companyId: endpoint.companyId,
        endpointId: endpoint.id,
        providerEventId,
        deduplicationKey,
        eventKind,
        normalizedEvent: {
          providerEventId,
          kind: eventKind,
          lifecycle: effect,
          ...(runtimeContext
            ? {
                runtimeContext: {
                  credentialFingerprint: runtimeContext.credentialFingerprint,
                  generation: runtimeContext.generation,
                },
              }
            : {}),
        },
        state: "received",
      })
      .onConflictDoNothing()
      .returning();
    const candidate =
      inserted ??
      (await db
        .select()
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.endpointId, endpoint.id),
            eq(chatDeliveries.providerEventId, providerEventId),
          ),
        )
        .then((rows) => rows[0] ?? null));
    if (!candidate || candidate.state === "processed") return false;
    const staleBefore = new Date(Date.now() - DELIVERY_PROCESSING_STALE_MS);
    const [claimed] = await db
      .update(chatDeliveries)
      .set({
        state: "processing",
        attempts: candidate.attempts + 1,
        redactedError: null,
        nextAttemptAt: null,
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(chatDeliveries.id, candidate.id),
          or(
            inArray(chatDeliveries.state, ["received", "retry"]),
            and(
              eq(chatDeliveries.state, "processing"),
              lte(chatDeliveries.updatedAt, staleBefore),
            ),
          ),
        ),
      )
      .returning({ id: chatDeliveries.id });
    if (!claimed) return false;

    let refreshRuntimeAfterLifecycle = false;
    let stopRuntimeAfterFailure = false;
    let stopRuntimeAfterLifecycle = false;
    let lifecycleFailurePersisted = false;
    try {
      await withCredentialMutationLease(endpoint, async (credentialLease) => {
        const currentRecord = await endpointRecord(endpoint.id);
        if (!currentRecord) throw notFound("Chat endpoint not found");
        const currentEndpoint = currentRecord.endpoint;
        const admittedRuntimeContext = lifecycleRuntimeFence(candidate);
        const currentRuntimeContext = runtimeContextForRecord(currentRecord);
        if (
          !admittedRuntimeContext ||
          admittedRuntimeContext.generation !==
            currentRuntimeContext.generation ||
          admittedRuntimeContext.credentialFingerprint !==
            currentRuntimeContext.credentialFingerprint
        ) {
          const filteredAt = new Date();
          await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            await tx
              .update(chatDeliveries)
              .set({
                state: "filtered",
                processedAt: filteredAt,
                nextAttemptAt: null,
                redactedError:
                  "Provider lifecycle callback belonged to a superseded runtime",
                updatedAt: filteredAt,
              })
              .where(
                and(
                  eq(chatDeliveries.id, claimed.id),
                  eq(chatDeliveries.state, "processing"),
                  eq(chatDeliveries.attempts, candidate.attempts + 1),
                ),
              );
            await credentialLease.assertOwned(tx);
          });
          return;
        }

        if (currentEndpoint.provider === "github") {
          try {
            const currentCredentials =
              await resolveCredentials(currentEndpoint);
            const lifecycleInstallationId =
              effect.kind === "endpoint" &&
              typeof effect.metadata?.installationId === "string"
                ? effect.metadata.installationId
                : null;
            const removesCurrentInstallation =
              effect.kind === "endpoint" &&
              effect.availability === "revoked" &&
              lifecycleInstallationId !== null &&
              lifecycleInstallationId === currentCredentials.installationId;
            const currentInstallationRemovalReason =
              removesCurrentInstallation && effect.kind === "endpoint"
                ? effect.reason
                : null;
            if (removesCurrentInstallation) {
              // A signed deletion for the installation currently bound to
              // this endpoint is authoritative provider truth. Inventory now
              // correctly contains zero active installations, so treating its
              // empty result as a transient discovery failure would strand the
              // endpoint in attention and ask GitHub to redeliver forever.
              // Keep the App key and webhook secret so a later installation
              // event can recover this same immutable bot identity.
              const revoked = await db.transaction(async (tx) => {
                await credentialLease.assertOwned(tx);
                const current = await runtimeCallbackEndpoint(
                  tx,
                  currentEndpoint.id,
                  admittedRuntimeContext,
                  ["verifying", "active", "attention", "revoked"],
                );
                const revokedAt = new Date();
                if (!current) {
                  const [filtered] = await tx
                    .update(chatDeliveries)
                    .set({
                      state: "filtered",
                      processedAt: revokedAt,
                      nextAttemptAt: null,
                      redactedError:
                        "GitHub installation deletion belonged to a superseded runtime",
                      updatedAt: revokedAt,
                    })
                    .where(
                      and(
                        eq(chatDeliveries.id, claimed.id),
                        eq(chatDeliveries.state, "processing"),
                        eq(chatDeliveries.attempts, candidate.attempts + 1),
                      ),
                    )
                    .returning({ id: chatDeliveries.id });
                  if (!filtered) {
                    throw new Error(
                      "GitHub installation deletion ownership changed before stale settlement",
                    );
                  }
                  await credentialLease.assertOwned(tx);
                  return false;
                }
                const reason = redactSensitiveText(
                  currentInstallationRemovalReason ??
                    "GitHub App installation was removed",
                ).slice(0, MAX_ERROR_TEXT);
                await tx
                  .update(chatEndpoints)
                  .set({
                    status: "revoked",
                    healthMessage: reason,
                    lastError: reason,
                    lastEventAt: revokedAt,
                    setup: {
                      ...current.setup,
                      runtimeGeneration: runtimeGeneration(current.setup) + 1,
                    } as InternalSetupState,
                    updatedAt: revokedAt,
                  })
                  .where(eq(chatEndpoints.id, current.id));
                await tx
                  .update(toolConnections)
                  .set({
                    status: "disabled",
                    enabled: false,
                    healthStatus: "failed",
                    healthMessage: reason,
                    lastError: reason,
                    healthCheckedAt: revokedAt,
                    updatedAt: revokedAt,
                  })
                  .where(eq(toolConnections.id, current.connectionId));
                await tx
                  .update(chatEndpointResources)
                  .set({ availability: "unavailable", updatedAt: revokedAt })
                  .where(
                    and(
                      eq(chatEndpointResources.companyId, current.companyId),
                      eq(chatEndpointResources.endpointId, current.id),
                    ),
                  );
                await tx
                  .update(chatConversations)
                  .set({ state: "unavailable", updatedAt: revokedAt })
                  .where(
                    and(
                      eq(chatConversations.companyId, current.companyId),
                      eq(chatConversations.endpointId, current.id),
                      inArray(chatConversations.state, ["active", "waiting"]),
                    ),
                  );
                const [processed] = await tx
                  .update(chatDeliveries)
                  .set({
                    state: "processed",
                    processedAt: revokedAt,
                    redactedError: null,
                    nextAttemptAt: null,
                    updatedAt: revokedAt,
                  })
                  .where(
                    and(
                      eq(chatDeliveries.id, claimed.id),
                      eq(chatDeliveries.state, "processing"),
                      eq(chatDeliveries.attempts, candidate.attempts + 1),
                    ),
                  )
                  .returning({ id: chatDeliveries.id });
                if (!processed) {
                  throw new Error(
                    "GitHub installation deletion ownership changed before revocation settlement",
                  );
                }
                await credentialLease.assertOwned(tx);
                return true;
              });
              stopRuntimeAfterLifecycle = revoked;
              return;
            }
            const identity = await verifyCredentials(
              "github",
              currentCredentials,
            );
            const upgradingLegacyIdentity =
              !currentEndpoint.botExternalId &&
              legacyGitHubLabelsMatchVerifiedCredentials(
                currentEndpoint,
                identity,
              );
            if (
              !upgradingLegacyIdentity &&
              !nativeBotIdentityMatches("github", currentEndpoint, identity)
            ) {
              throw conflict(
                "The GitHub App identity changed while reconciling this connection",
                {
                  code: "chat_bot_identity_changed",
                },
              );
            }
            await assertNativeBotIdentityAvailable(currentEndpoint, identity);
            if (upgradingLegacyIdentity) {
              await db.transaction(async (tx) => {
                await credentialLease.assertOwned(tx);
                await tx
                  .update(chatEndpoints)
                  .set({
                    botExternalId: identity.botExternalId,
                    updatedAt: new Date(),
                  })
                  .where(eq(chatEndpoints.id, currentEndpoint.id));
                await credentialLease.assertOwned(tx);
              });
            }

            // GitHub lifecycle payloads are wake-up signals, not provider
            // truth. Re-read the one active App installation and its complete
            // repository inventory while the credential lease excludes secret
            // rotation and every other lifecycle callback for this endpoint.
            const prepared = await prepareProviderInventory(
              currentEndpoint,
              currentCredentials,
            );
            if (
              prepared.credentials.installationId !==
              currentCredentials.installationId
            ) {
              await persistCredentials(
                currentEndpoint,
                prepared.credentials,
                credentialLease,
              );
              refreshRuntimeAfterLifecycle = true;
            }
            if (prepared.inventory)
              await reconcileProviderResourceRows(
                currentEndpoint,
                prepared.inventory,
                credentialLease,
              );

            const canonical = await endpointRecord(currentEndpoint.id);
            if (!canonical) throw notFound("Chat endpoint not found");
            const now = new Date();
            const intentionallyUnavailable =
              canonical.endpoint.status === "paused" ||
              canonical.endpoint.status === "archived" ||
              !canonical.endpoint.setup.webhookVerifiedAt;
            const advanceRuntimeGeneration =
              refreshRuntimeAfterLifecycle ||
              !canonical.endpoint.setup.webhookVerifiedAt;
            await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              if (intentionallyUnavailable) {
                await tx
                  .update(chatEndpoints)
                  .set({
                    ...(advanceRuntimeGeneration
                      ? {
                          setup: {
                            ...canonical.endpoint.setup,
                            runtimeGeneration:
                              runtimeGeneration(canonical.endpoint.setup) + 1,
                          } as InternalSetupState,
                        }
                      : {}),
                    lastEventAt: now,
                    updatedAt: now,
                  })
                  .where(eq(chatEndpoints.id, canonical.endpoint.id));
              } else {
                const status =
                  canonical.endpoint.setup.step === "complete"
                    ? "active"
                    : "verifying";
                await tx
                  .update(chatEndpoints)
                  .set({
                    status,
                    healthMessage:
                      status === "active"
                        ? "Connected"
                        : "Waiting for a test conversation",
                    lastError: null,
                    lastEventAt: now,
                    ...(advanceRuntimeGeneration
                      ? {
                          setup: {
                            ...canonical.endpoint.setup,
                            runtimeGeneration:
                              runtimeGeneration(canonical.endpoint.setup) + 1,
                          } as InternalSetupState,
                        }
                      : {}),
                    updatedAt: now,
                  })
                  .where(eq(chatEndpoints.id, canonical.endpoint.id));
                await tx
                  .update(toolConnections)
                  .set({
                    status: "active",
                    enabled: true,
                    healthStatus: "healthy",
                    healthMessage: "Connected",
                    lastError: null,
                    healthCheckedAt: now,
                    updatedAt: now,
                  })
                  .where(
                    eq(toolConnections.id, canonical.endpoint.connectionId),
                  );
              }
              await tx
                .update(chatDeliveries)
                .set({
                  state: "processed",
                  processedAt: now,
                  redactedError: null,
                  nextAttemptAt: null,
                  updatedAt: now,
                })
                .where(
                  and(
                    eq(chatDeliveries.id, claimed.id),
                    eq(chatDeliveries.state, "processing"),
                    eq(chatDeliveries.attempts, candidate.attempts + 1),
                  ),
                );
              await credentialLease.assertOwned(tx);
            });
            if (!canonical.endpoint.setup.webhookVerifiedAt) {
              stopRuntimeAfterLifecycle = true;
            }
          } catch (error) {
            const latest = await endpointRecord(currentEndpoint.id);
            const preserveIntentionalState =
              !latest ||
              latest.endpoint.status === "paused" ||
              latest.endpoint.status === "archived" ||
              !latest.endpoint.setup.webhookVerifiedAt;
            if (!preserveIntentionalState) {
              const failedAt = new Date();
              const failure = redactError(error);
              const nextGeneration =
                runtimeGeneration(latest.endpoint.setup) + 1;
              const retryRuntimeContext: LifecycleRuntimeFence = {
                credentialFingerprint: credentialFingerprint(
                  latest.credentialSecretRefs,
                ),
                generation: nextGeneration,
              };
              const terminal = candidate.attempts + 1 >= 5;
              await db.transaction(async (tx) => {
                await credentialLease.assertOwned(tx);
                await tx
                  .update(chatEndpoints)
                  .set({
                    status: "attention",
                    healthMessage:
                      "GitHub App credentials, permissions, events, or identity need attention",
                    lastError: failure,
                    lastEventAt: failedAt,
                    setup: {
                      ...latest.endpoint.setup,
                      runtimeGeneration: nextGeneration,
                    } as InternalSetupState,
                    updatedAt: failedAt,
                  })
                  .where(eq(chatEndpoints.id, currentEndpoint.id));
                await tx
                  .update(toolConnections)
                  .set({
                    status: "disabled",
                    enabled: false,
                    healthStatus: "degraded",
                    healthMessage:
                      "GitHub App credentials, permissions, events, or identity need attention",
                    lastError: failure,
                    healthCheckedAt: failedAt,
                    updatedAt: failedAt,
                  })
                  .where(eq(toolConnections.id, currentEndpoint.connectionId));
                await tx
                  .update(chatEndpointResources)
                  .set({ availability: "unavailable", updatedAt: failedAt })
                  .where(
                    and(
                      eq(
                        chatEndpointResources.companyId,
                        currentEndpoint.companyId,
                      ),
                      eq(chatEndpointResources.endpointId, currentEndpoint.id),
                    ),
                  );
                await tx
                  .update(chatConversations)
                  .set({ state: "unavailable", updatedAt: failedAt })
                  .where(
                    and(
                      eq(
                        chatConversations.companyId,
                        currentEndpoint.companyId,
                      ),
                      eq(chatConversations.endpointId, currentEndpoint.id),
                      inArray(chatConversations.state, ["active", "waiting"]),
                    ),
                  );
                await tx
                  .update(chatDeliveries)
                  .set({
                    state: terminal ? "failed" : "retry",
                    normalizedEvent: normalizedLifecycleWithRuntimeFence(
                      candidate,
                      retryRuntimeContext,
                    ),
                    redactedError: failure,
                    nextAttemptAt: terminal ? null : failedAt,
                    updatedAt: failedAt,
                  })
                  .where(
                    and(
                      eq(chatDeliveries.id, claimed.id),
                      eq(chatDeliveries.state, "processing"),
                      eq(chatDeliveries.attempts, candidate.attempts + 1),
                    ),
                  );
                await credentialLease.assertOwned(tx);
              });
              stopRuntimeAfterFailure = true;
              lifecycleFailurePersisted = true;
            }
            throw error;
          }
          return;
        }

        const staleResourceEffect =
          effect.kind === "resource" &&
          (await hasNewerProcessedProviderLifecycleEffect(
            currentEndpoint,
            effect,
          ));

        const endpointEffectStopsRuntime =
          effect.kind === "endpoint" &&
          (effect.availability === "attention" ||
            effect.availability === "revoked");
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const now = new Date();
          if (staleResourceEffect) {
            // Persisted provider-native ordering wins over request arrival or
            // lease acquisition order. The older callback remains auditable,
            // but cannot roll a resource or conversation back.
            await tx
              .update(chatEndpoints)
              .set({ lastEventAt: now, updatedAt: now })
              .where(eq(chatEndpoints.id, currentEndpoint.id));
            await tx
              .update(chatDeliveries)
              .set({
                state: "processed",
                processedAt: now,
                redactedError: null,
                nextAttemptAt: null,
                updatedAt: now,
              })
              .where(eq(chatDeliveries.id, claimed.id));
            return;
          }
          if (effect.kind === "resource") {
            const providerResourceId =
              currentEndpoint.provider === "microsoft-teams"
                ? baseTeamsConversationId(effect.providerResourceId)
                : effect.providerResourceId;
            const previousProviderResourceId =
              currentEndpoint.provider === "telegram"
                ? effect.previousProviderResourceId
                : undefined;
            const previousResource = previousProviderResourceId
              ? await tx
                  .select()
                  .from(chatEndpointResources)
                  .where(
                    and(
                      eq(chatEndpointResources.endpointId, currentEndpoint.id),
                      eq(chatEndpointResources.type, "chat"),
                      eq(
                        chatEndpointResources.providerResourceId,
                        previousProviderResourceId,
                      ),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
            const migratedLabel =
              previousResource &&
              telegramResourceLabelIsFallback(providerResourceId, effect.label)
                ? previousResource.label
                : effect.label;
            const migratedEnabled = previousResource?.enabled === true;
            if (
              previousResource &&
              previousProviderResourceId !== providerResourceId
            ) {
              await tx
                .update(chatEndpointResources)
                .set({
                  availability: "unavailable",
                  enabled: false,
                  metadata: {
                    ...previousResource.metadata,
                    source: "chat_migration",
                    migratedTo: providerResourceId,
                  },
                  updatedAt: now,
                })
                .where(eq(chatEndpointResources.id, previousResource.id));
            }
            const preserveProviderLabel =
              (currentEndpoint.provider === "slack" &&
                slackResourceLabelIsFallback(
                  providerResourceId,
                  migratedLabel,
                )) ||
              (currentEndpoint.provider === "telegram" &&
                telegramResourceLabelIsFallback(
                  providerResourceId,
                  migratedLabel,
                ));
            const [resource] = await tx
              .insert(chatEndpointResources)
              .values({
                companyId: currentEndpoint.companyId,
                endpointId: currentEndpoint.id,
                type: effect.resourceType,
                providerResourceId,
                parentProviderResourceId:
                  effect.parentProviderResourceId ?? null,
                label: migratedLabel,
                providerUrl: effect.providerUrl ?? null,
                availability: effect.availability,
                enabled: migratedEnabled,
                metadata: effect.metadata ?? {},
              })
              .onConflictDoUpdate({
                target: [
                  chatEndpointResources.endpointId,
                  chatEndpointResources.type,
                  chatEndpointResources.providerResourceId,
                ],
                set: {
                  parentProviderResourceId:
                    effect.parentProviderResourceId ?? null,
                  ...(preserveProviderLabel ? {} : { label: migratedLabel }),
                  providerUrl: effect.providerUrl ?? null,
                  availability: effect.availability,
                  ...(previousProviderResourceId
                    ? {
                        enabled: sql<boolean>`${chatEndpointResources.enabled} or ${migratedEnabled}`,
                      }
                    : {}),
                  metadata: effect.metadata ?? {},
                  updatedAt: now,
                },
              })
              .returning({ id: chatEndpointResources.id });
            if (
              resource &&
              previousResource &&
              previousProviderResourceId !== providerResourceId
            ) {
              const previousThreadPrefix = `telegram:${previousProviderResourceId}`;
              const migratedThreadPrefix = `telegram:${providerResourceId}`;
              await tx
                .update(chatConversations)
                .set({
                  resourceId: resource.id,
                  // Telegram SDK threads use the namespaced channel id. Keep
                  // the migrated row in that canonical shape so the first
                  // reply from the replacement supergroup finds this same
                  // task instead of creating a second conversation.
                  externalConversationId: migratedThreadPrefix,
                  externalThreadId: sql<string>`case
                    when ${chatConversations.externalThreadId} = ${previousThreadPrefix} then ${migratedThreadPrefix}
                    when ${chatConversations.externalThreadId} like ${`${previousThreadPrefix}:%`}
                      then ${migratedThreadPrefix} || substring(
                        ${chatConversations.externalThreadId}
                        from char_length(${previousThreadPrefix}) + 1
                      )
                    else ${chatConversations.externalThreadId}
                  end`,
                  externalLabel: migratedLabel,
                  state: "active",
                  updatedAt: now,
                })
                .where(
                  and(
                    eq(chatConversations.companyId, currentEndpoint.companyId),
                    eq(chatConversations.endpointId, currentEndpoint.id),
                    eq(chatConversations.resourceId, previousResource.id),
                  ),
                );
            }
            if (resource) {
              await tx
                .update(chatConversations)
                .set({
                  state:
                    effect.availability === "available"
                      ? "active"
                      : "unavailable",
                  updatedAt: now,
                })
                .where(
                  and(
                    eq(chatConversations.companyId, currentEndpoint.companyId),
                    eq(chatConversations.endpointId, currentEndpoint.id),
                    eq(chatConversations.resourceId, resource.id),
                    effect.availability === "available"
                      ? eq(chatConversations.state, "unavailable")
                      : inArray(chatConversations.state, ["active", "waiting"]),
                  ),
                );
            }
            await tx
              .update(chatEndpoints)
              .set({ lastEventAt: now, updatedAt: now })
              .where(eq(chatEndpoints.id, currentEndpoint.id));
          } else {
            const reason = redactSensitiveText(effect.reason).slice(
              0,
              MAX_ERROR_TEXT,
            );
            if (effect.availability === "available") {
              if (
                currentEndpoint.status !== "paused" &&
                currentEndpoint.status !== "archived"
              ) {
                const status =
                  currentEndpoint.setup.step === "complete"
                    ? "active"
                    : currentEndpoint.status === "attention"
                      ? "verifying"
                      : currentEndpoint.status;
                await tx
                  .update(chatEndpoints)
                  .set({
                    status,
                    healthMessage:
                      status === "active"
                        ? "Connected"
                        : "Waiting for a test conversation",
                    lastError: null,
                    lastEventAt: now,
                    updatedAt: now,
                  })
                  .where(eq(chatEndpoints.id, currentEndpoint.id));
                await tx
                  .update(toolConnections)
                  .set({
                    status: "active",
                    enabled: true,
                    healthStatus: "healthy",
                    healthMessage: "Connected",
                    lastError: null,
                    healthCheckedAt: now,
                    updatedAt: now,
                  })
                  .where(eq(toolConnections.id, currentEndpoint.connectionId));
              }
            } else {
              await tx
                .update(chatEndpoints)
                .set({
                  status: effect.availability,
                  healthMessage: reason,
                  lastError: reason,
                  lastEventAt: now,
                  setup: {
                    ...currentEndpoint.setup,
                    runtimeGeneration:
                      runtimeGeneration(currentEndpoint.setup) + 1,
                  } as InternalSetupState,
                  updatedAt: now,
                })
                .where(eq(chatEndpoints.id, currentEndpoint.id));
              await tx
                .update(toolConnections)
                .set({
                  status: "disabled",
                  enabled: false,
                  healthStatus:
                    effect.availability === "revoked" ? "failed" : "degraded",
                  healthMessage: reason,
                  lastError: reason,
                  healthCheckedAt: now,
                  updatedAt: now,
                })
                .where(eq(toolConnections.id, currentEndpoint.connectionId));
              await tx
                .update(chatEndpointResources)
                .set({ availability: "unavailable", updatedAt: now })
                .where(
                  and(
                    eq(
                      chatEndpointResources.companyId,
                      currentEndpoint.companyId,
                    ),
                    eq(chatEndpointResources.endpointId, currentEndpoint.id),
                  ),
                );
              await tx
                .update(chatConversations)
                .set({ state: "unavailable", updatedAt: now })
                .where(
                  and(
                    eq(chatConversations.companyId, currentEndpoint.companyId),
                    eq(chatConversations.endpointId, currentEndpoint.id),
                    inArray(chatConversations.state, ["active", "waiting"]),
                  ),
                );
            }
          }
          await tx
            .update(chatDeliveries)
            .set({
              state: "processed",
              processedAt: now,
              redactedError: null,
              nextAttemptAt: null,
              updatedAt: now,
            })
            .where(
              and(
                eq(chatDeliveries.id, claimed.id),
                eq(chatDeliveries.state, "processing"),
                eq(chatDeliveries.attempts, candidate.attempts + 1),
              ),
            );
          await credentialLease.assertOwned(tx);
        });
        stopRuntimeAfterLifecycle = endpointEffectStopsRuntime;
      });
    } catch (error) {
      if (stopRuntimeAfterFailure) {
        await invalidateRuntime(endpoint.id).catch((runtimeError) => {
          logger.warn(
            { endpointId: endpoint.id, error: redactError(runtimeError) },
            "failed to stop GitHub endpoint after lifecycle revalidation failed",
          );
        });
      }
      if (!lifecycleFailurePersisted) {
        const terminal = candidate.attempts + 1 >= 5;
        await db
          .update(chatDeliveries)
          .set({
            state: terminal ? "failed" : "retry",
            redactedError: redactError(error),
            nextAttemptAt: terminal ? null : new Date(),
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatDeliveries.id, claimed.id),
              eq(chatDeliveries.state, "processing"),
              eq(chatDeliveries.attempts, candidate.attempts + 1),
            ),
          )
          .catch(() => undefined);
      }
      throw error;
    }

    if (refreshRuntimeAfterLifecycle) {
      // The verified reinstall may have assigned a new installation id. Drop
      // the runtime that authenticated the lifecycle webhook with the prior
      // id; the next send recreates it from the newly persisted credentials.
      await invalidateRuntime(endpoint.id).catch((error) => {
        logger.warn(
          { endpointId: endpoint.id, error: redactError(error) },
          "failed to refresh recovered GitHub chat endpoint runtime",
        );
      });
    }
    if (stopRuntimeAfterLifecycle) {
      await invalidateRuntime(endpoint.id).catch((error) => {
        logger.warn(
          { endpointId: endpoint.id, error: redactError(error) },
          "failed to stop unavailable chat endpoint runtime",
        );
      });
    }
    return true;
  }

  function lifecycleRuntimeFence(
    delivery: DeliveryRow,
  ): LifecycleRuntimeFence | null {
    const normalized = delivery.normalizedEvent;
    if (
      !normalized ||
      typeof normalized !== "object" ||
      Array.isArray(normalized)
    )
      return null;
    const value = (normalized as Record<string, unknown>).runtimeContext;
    if (!value || typeof value !== "object" || Array.isArray(value))
      return null;
    const context = value as Record<string, unknown>;
    return typeof context.generation === "number" &&
      Number.isSafeInteger(context.generation) &&
      typeof context.credentialFingerprint === "string"
      ? {
          generation: context.generation as number,
          credentialFingerprint: context.credentialFingerprint,
        }
      : null;
  }

  function normalizedLifecycleWithRuntimeFence(
    delivery: DeliveryRow,
    runtimeContext: LifecycleRuntimeFence,
  ): Record<string, unknown> {
    const normalized =
      delivery.normalizedEvent &&
      typeof delivery.normalizedEvent === "object" &&
      !Array.isArray(delivery.normalizedEvent)
        ? (delivery.normalizedEvent as Record<string, unknown>)
        : {};
    return { ...normalized, runtimeContext };
  }

  async function hasNewerProcessedProviderLifecycleEffect(
    endpoint: EndpointRow,
    effect: Extract<ChatProviderLifecycleEffect, { kind: "resource" }>,
  ): Promise<boolean> {
    const sequence = effect.providerOrder?.sequence;
    const occurredAt = effect.providerOrder?.occurredAt;
    if (!sequence && !occurredAt) return false;
    const providerResourceId =
      endpoint.provider === "microsoft-teams"
        ? baseTeamsConversationId(effect.providerResourceId)
        : effect.providerResourceId;
    const newerOrder = sequence
      ? sql`(
          ${chatDeliveries.normalizedEvent}#>>'{lifecycle,providerOrder,sequence}' ~ '^[0-9]+([.][0-9]+)?$'
          and (${chatDeliveries.normalizedEvent}#>>'{lifecycle,providerOrder,sequence}')::numeric > cast(${sequence} as numeric)
        )`
      : sql`(
          nullif(${chatDeliveries.normalizedEvent}#>>'{lifecycle,providerOrder,occurredAt}', '')::timestamptz > cast(${occurredAt!} as timestamptz)
        )`;
    const newer = await db
      .select({ id: chatDeliveries.id })
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.endpointId, endpoint.id),
          eq(chatDeliveries.state, "processed"),
          inArray(chatDeliveries.eventKind, ["installation", "uninstallation"]),
          sql`${chatDeliveries.normalizedEvent}#>>'{lifecycle,kind}' = 'resource'`,
          sql`${chatDeliveries.normalizedEvent}#>>'{lifecycle,provider}' = ${effect.provider}`,
          sql`${chatDeliveries.normalizedEvent}#>>'{lifecycle,providerResourceId}' = ${providerResourceId}`,
          newerOrder,
        ),
      )
      .limit(1);
    return newer.length > 0;
  }

  async function applyProviderLifecycleEffects(
    endpoint: EndpointRow,
    effects: ChatProviderLifecycleEffect[],
    runtimeContext: RuntimeContext,
  ) {
    for (const effect of effects) {
      if (effect.provider !== endpoint.provider) continue;
      const applied = await applyProviderLifecycleEffect(
        endpoint,
        effect,
        runtimeContext,
      );
      if (
        applied &&
        endpoint.provider === "slack" &&
        effect.kind === "resource" &&
        effect.availability === "available" &&
        slackResourceLabelIsFallback(effect.providerResourceId, effect.label)
      ) {
        const stillAvailable = await db
          .select({ id: chatEndpointResources.id })
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.endpointId, endpoint.id),
              eq(chatEndpointResources.type, "channel"),
              eq(
                chatEndpointResources.providerResourceId,
                effect.providerResourceId,
              ),
              eq(chatEndpointResources.availability, "available"),
            ),
          )
          .limit(1)
          .then((rows) => rows.length > 0);
        if (stillAvailable) {
          scheduleMessageProcessing(async () => {
            await hydrateSlackResourceLabel(
              endpoint.id,
              effect.providerResourceId,
            ).catch((error) => {
              logger.warn(
                {
                  endpointId: endpoint.id,
                  providerResourceId: effect.providerResourceId,
                  error: redactError(error),
                },
                "could not hydrate a newly available Slack channel label",
              );
            });
          });
        }
      }
    }
  }

  type GitHubIngressStageResult =
    | { kind: "invalid_signature" }
    | { kind: "ignored" }
    | { actionId: string; kind: "staged" };

  function githubSignatureIsValid(
    body: string,
    signature: string | null,
    webhookSecret: string | undefined,
  ): boolean {
    if (!signature || !webhookSecret) return false;
    const expected = `sha256=${createHmac("sha256", webhookSecret).update(body).digest("hex")}`;
    try {
      return timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
    } catch {
      return false;
    }
  }

  function githubWebhookContainsUserContent(eventType: string): boolean {
    return (
      eventType === "issue_comment" ||
      eventType === "pull_request_review_comment"
    );
  }

  function githubWebhookAddressesBot(
    payload: unknown,
    botUsername: string | null,
  ): boolean {
    if (!botUsername || !payload || typeof payload !== "object") return false;
    const comment = (payload as { comment?: unknown }).comment;
    if (!comment || typeof comment !== "object") return false;
    const body = (comment as { body?: unknown }).body;
    if (typeof body !== "string") return false;
    const identities = new Set([
      botUsername,
      botUsername.replace(/\[bot\]$/i, ""),
    ]);
    return [...identities].some((identity) => {
      if (!identity) return false;
      const escaped = identity.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      return new RegExp(`(?<!\\w)@${escaped}(?![\\w-])`, "i").test(body);
    });
  }

  function githubIngressAllowedInEndpointState(
    status: EndpointRow["status"],
    eventType: string,
  ): boolean {
    if (status === "verifying" || status === "active") return true;
    if (eventType === "ping" && (status === "draft" || status === "attention"))
      return true;
    if (
      status === "attention" &&
      [
        "github_app_authorization",
        "installation",
        "installation_repositories",
      ].includes(eventType)
    )
      return true;
    return status === "revoked" && eventType === "installation";
  }

  async function stageGitHubWebhookIngress(
    endpoint: EndpointRow,
    request: Request,
  ): Promise<GitHubIngressStageResult> {
    const body = await request.text();
    const signature = request.headers.get("x-hub-signature-256");
    const eventType = request.headers.get("x-github-event")?.trim() ?? "";
    const providerDeliveryId =
      request.headers.get("x-github-delivery")?.trim() ||
      `body:${createHash("sha256").update(body).digest("hex")}`;
    if (!SUPPORTED_GITHUB_WEBHOOK_EVENTS.has(eventType))
      return { kind: "ignored" };

    let parsedPayload: unknown = null;
    try {
      parsedPayload = JSON.parse(body) as unknown;
    } catch {
      // A valid signature is still required before a malformed body may be
      // retained. The native adapter will settle the authenticated envelope.
    }

    // Resolve from a captured ref set, then prove that exact ref set and
    // generation are still authoritative in the insertion transaction. This
    // keeps webhook authentication outside the potentially long credential
    // mutation lease without letting an obsolete secret stage new work.
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const record = await endpointRecord(endpoint.id);
      if (!record || record.endpoint.provider !== "github")
        return { kind: "ignored" };
      if (
        !githubIngressAllowedInEndpointState(record.endpoint.status, eventType)
      ) {
        return { kind: "ignored" };
      }
      const context = runtimeContextForRecord(record);
      let credentials: Record<string, string>;
      try {
        credentials = await resolveCredentialRefs(
          record.endpoint,
          record.credentialSecretRefs,
        );
      } catch (error) {
        const latest = await endpointRecord(endpoint.id);
        if (
          latest &&
          (runtimeGeneration(latest.endpoint.setup) !== context.generation ||
            credentialFingerprint(latest.credentialSecretRefs) !==
              context.credentialFingerprint)
        ) {
          continue;
        }
        throw error;
      }
      if (!githubSignatureIsValid(body, signature, credentials.webhookSecret)) {
        const latest = await endpointRecord(endpoint.id);
        if (
          latest &&
          (runtimeGeneration(latest.endpoint.setup) !== context.generation ||
            credentialFingerprint(latest.credentialSecretRefs) !==
              context.credentialFingerprint)
        ) {
          continue;
        }
        return { kind: "invalid_signature" };
      }

      const incomingInstallationId =
        parsedPayload &&
        typeof parsedPayload === "object" &&
        !Array.isArray(parsedPayload)
          ? (parsedPayload as { installation?: { id?: unknown } }).installation
              ?.id
          : undefined;
      if (
        incomingInstallationId !== undefined &&
        String(incomingInstallationId) !== credentials.installationId &&
        eventType !== "installation"
      ) {
        return { kind: "ignored" };
      }

      const bodySha256 = createHash("sha256").update(body).digest("hex");
      const staged = await db.transaction(async (tx) => {
        const currentEndpoint = await tx
          .select()
          .from(chatEndpoints)
          .where(eq(chatEndpoints.id, endpoint.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        const currentConnection = await tx
          .select({ refs: toolConnections.credentialSecretRefs })
          .from(toolConnections)
          .where(
            and(
              eq(toolConnections.companyId, record.endpoint.companyId),
              eq(toolConnections.id, record.endpoint.connectionId),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!currentEndpoint || !currentConnection) return "retry" as const;
        if (
          runtimeGeneration(currentEndpoint.setup) !== context.generation ||
          credentialFingerprint(currentConnection.refs) !==
            context.credentialFingerprint
        ) {
          return "retry" as const;
        }
        if (
          !githubIngressAllowedInEndpointState(
            currentEndpoint.status,
            eventType,
          )
        ) {
          return "ignored" as const;
        }

        // Recovery history is denial-only provenance. A genuine callback
        // queued by GitHub before pause/reconnect must not be authenticated
        // into a later generation, even if the provider signs with its current
        // secret. Include archived endpoints so reusing an App cannot move a
        // delayed callback into another endpoint/company.
        const recoveryReceipts = credentials.appId
          ? await tx
              .select({
                endpointId: chatActions.endpointId,
                payload: chatActions.payload,
                status: chatActions.status,
              })
              .from(chatActions)
              .innerJoin(
                chatEndpoints,
                eq(chatEndpoints.id, chatActions.endpointId),
              )
              .where(
                and(
                  eq(chatEndpoints.provider, "github"),
                  eq(chatEndpoints.botExternalId, credentials.appId),
                  eq(chatActions.kind, "github_webhook_recovery"),
                  eq(
                    chatActions.providerActionId,
                    `github_webhook_recovery:${providerDeliveryId}`,
                  ),
                ),
              )
          : [];
        for (const receipt of recoveryReceipts) {
          const fence = githubRecoveryWindow(receipt.payload);
          const original = (receipt.payload as GitHubRecoveryReceipt).original;
          const incoming = parsedPayload as {
            action?: unknown;
            installation?: { id?: unknown };
            repository?: { id?: unknown; full_name?: unknown };
            issue?: { id?: unknown; number?: unknown };
            pull_request?: { id?: unknown; number?: unknown };
            sender?: { id?: unknown };
            comment?: {
              id?: unknown;
              body?: unknown;
              user?: { id?: unknown };
              created_at?: unknown;
              updated_at?: unknown;
            };
          } | null;
          const comment = incoming?.comment;
          if (
            !fence ||
            receipt.status === "cancelled" ||
            receipt.endpointId !== currentEndpoint.id ||
            fence.generation !== context.generation ||
            fence.credentialFingerprint !== context.credentialFingerprint ||
            fence.webhookUrl !==
              `${webhookPublicBaseUrl}/api/chat-webhooks/${currentEndpoint.publicId}/github` ||
            !original?.payload?.comment ||
            original.event !== eventType ||
            incoming?.action !== "created" ||
            String(incoming?.installation?.id) !==
              original.payload.installationId ||
            String(incoming?.repository?.id) !==
              original.payload.repositoryId ||
            incoming?.repository?.full_name !==
              original.payload.repositoryFullName ||
            String(incoming?.sender?.id) !== original.payload.senderId ||
            (eventType === "issue_comment"
              ? String(incoming?.issue?.id) !== original.payload.issueId ||
                String(incoming?.issue?.number) !== original.payload.issueNumber
              : String(incoming?.pull_request?.id) !==
                  original.payload.pullRequestId ||
                String(incoming?.pull_request?.number) !==
                  original.payload.pullRequestNumber) ||
            String(comment?.id) !== original.payload.comment.id ||
            String(comment?.user?.id) !== original.payload.comment.userId ||
            comment?.created_at !== original.payload.comment.createdAt ||
            comment?.updated_at !== original.payload.comment.updatedAt ||
            typeof comment?.body !== "string" ||
            createHash("sha256").update(comment.body).digest("hex") !==
              original.payload.comment.bodySha256
          ) {
            return "ignored" as const;
          }
        }

        // Signed App webhooks can cover every installed repository. Do not
        // retain comment bodies for destinations the operator did not enable.
        if (githubWebhookContainsUserContent(eventType)) {
          const item = githubRepositoryInventoryItemFromPayload(parsedPayload);
          if (!item) return "ignored" as const;
          const providerRepositoryId =
            typeof item.metadata?.providerRepositoryId === "string"
              ? item.metadata.providerRepositoryId
              : null;
          const matchingResource = await tx
            .select({
              enabled: chatEndpointResources.enabled,
              id: chatEndpointResources.id,
            })
            .from(chatEndpointResources)
            .where(
              and(
                eq(chatEndpointResources.companyId, currentEndpoint.companyId),
                eq(chatEndpointResources.endpointId, currentEndpoint.id),
                eq(chatEndpointResources.type, "repository"),
                eq(chatEndpointResources.availability, "available"),
                or(
                  eq(
                    chatEndpointResources.providerResourceId,
                    item.providerResourceId,
                  ),
                  providerRepositoryId
                    ? sql`${chatEndpointResources.metadata}->>'providerRepositoryId' = ${providerRepositoryId}`
                    : undefined,
                ),
              ),
            )
            .limit(1)
            .then((rows) => rows[0] ?? null);
          if (!matchingResource) return "ignored" as const;
          if (!matchingResource.enabled) {
            const action =
              parsedPayload &&
              typeof parsedPayload === "object" &&
              !Array.isArray(parsedPayload)
                ? (parsedPayload as { action?: unknown }).action
                : null;
            const ignoreDisabledResource = async () => {
              // Record only an authenticated, content-free admission decision.
              // Do not make operators infer a working callback from silence,
              // or retain the comment/actor/thread from a disabled repository.
              const providerEventId = `github:filtered_ingress:${createHash(
                "sha256",
              )
                .update(providerDeliveryId)
                .digest("hex")}`;
              const eventKind =
                action === "edited"
                  ? "message_updated"
                  : action === "deleted"
                    ? "message_deleted"
                    : "message";
              await tx
                .insert(chatDeliveries)
                .values({
                  companyId: currentEndpoint.companyId,
                  endpointId: currentEndpoint.id,
                  providerEventId,
                  deduplicationKey: providerEventId,
                  eventKind,
                  state: "filtered",
                  processedAt: new Date(),
                  redactedError: "Destination is not enabled in Paperclip",
                  normalizedEvent: {
                    providerEventId,
                    kind: eventKind,
                    filtering: {
                      contentRetained: false,
                      reason: "destination_not_enabled",
                      resourceId: matchingResource.id,
                    },
                  },
                })
                .onConflictDoNothing();
              return "ignored" as const;
            };
            if (
              currentEndpoint.status !== "verifying" ||
              action !== "created" ||
              !githubWebhookAddressesBot(
                parsedPayload,
                currentEndpoint.botUsername,
              )
            ) {
              return ignoreDisabledResource();
            }
            const enabledResourceCount = await tx
              .select({ count: sql<number>`count(*)::int` })
              .from(chatEndpointResources)
              .where(
                and(
                  eq(chatEndpointResources.endpointId, currentEndpoint.id),
                  eq(chatEndpointResources.type, "repository"),
                  eq(chatEndpointResources.enabled, true),
                  eq(chatEndpointResources.availability, "available"),
                ),
              )
              .then((rows) => rows[0]?.count ?? 0);
            if (enabledResourceCount !== 0) return ignoreDisabledResource();
          }
        }

        const payload: GitHubWebhookIngressPayload = {
          version: 1,
          body,
          bodySha256,
          contentType:
            request.headers.get("content-type") ?? "application/json",
          deliveryId: providerDeliveryId,
          eventType,
          runtimeGeneration: context.generation,
          credentialFingerprint: context.credentialFingerprint,
        };
        const inserted = await tx
          .insert(chatActions)
          .values({
            companyId: currentEndpoint.companyId,
            endpointId: currentEndpoint.id,
            kind: "github_webhook_ingress",
            providerActionId: `github_webhook_ingress:${providerDeliveryId}`,
            payload,
            status: "received",
          })
          .onConflictDoNothing()
          .returning({ id: chatActions.id });
        if (inserted[0]?.id) {
          return { actionId: inserted[0].id, kind: "staged" } as const;
        }

        // An automatic callback is never authorization to reset the local
        // worker's terminal retry budget. The original may have arrived in the
        // interval between our remote scan and GitHub's asynchronous callback.
        if (recoveryReceipts.length > 0) return "ignored" as const;

        // GitHub preserves X-GitHub-Delivery when an operator uses Recent
        // Deliveries to retry a failed callback. Re-arm only the exact same,
        // currently authenticated body after a terminal processing failure.
        // Successful, cancelled, retryable, and in-flight receipts remain
        // immutable deduplication fences.
        const [rearmed] = await tx
          .update(chatActions)
          .set({
            payload,
            // Keep the lifetime attempt counter monotonic. Besides bounding
            // repeated manual redeliveries, this prevents a late settlement
            // from an older processing claim from matching a fresh claim
            // after re-arm (an attempts=1 ABA).
            result: sql`jsonb_build_object(
              'attempts',
              coalesce((${chatActions.result}->>'attempts')::int, 0)
            )`,
            status: "received",
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.endpointId, currentEndpoint.id),
              eq(
                chatActions.providerActionId,
                `github_webhook_ingress:${providerDeliveryId}`,
              ),
              eq(chatActions.kind, "github_webhook_ingress"),
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'false'`,
              sql`${chatActions.payload}->>'bodySha256' = ${bodySha256}`,
              sql`${chatActions.payload}->>'eventType' = ${eventType}`,
            ),
          )
          .returning({ id: chatActions.id });
        const actionId =
          rearmed?.id ??
          (await tx
            .select({ id: chatActions.id })
            .from(chatActions)
            .where(
              and(
                eq(chatActions.endpointId, currentEndpoint.id),
                eq(
                  chatActions.providerActionId,
                  `github_webhook_ingress:${providerDeliveryId}`,
                ),
              ),
            )
            .then((rows) => rows[0]?.id ?? null));
        return actionId
          ? ({ actionId, kind: "staged" } as const)
          : ("retry" as const);
      });
      if (staged === "retry") continue;
      if (staged === "ignored") return { kind: "ignored" };
      return staged;
    }
    throw conflict("GitHub credentials changed during webhook authentication", {
      code: "chat_endpoint_credentials_changed",
    });
  }

  function githubIngressAcceptedResponse() {
    return new Response("accepted", { status: 202 });
  }

  async function settleGitHubWebhookIngress(
    actionId: string,
    input: {
      attempts: number;
      payload: GitHubWebhookIngressPayload;
      response?: Response;
      error?: unknown;
      cancelledCode?: string;
    },
  ): Promise<void> {
    const terminalResponse =
      input.response !== undefined && input.response.status < 500;
    const terminalFailure = input.attempts >= 5;
    const cancelled = Boolean(input.cancelledCode);
    const processed = Boolean(input.response?.ok);
    const terminal =
      processed || terminalResponse || terminalFailure || cancelled;
    const retryAt = new Date(
      Date.now() +
        Math.min(60_000, 1_000 * 2 ** Math.max(0, input.attempts - 1)),
    );
    await db
      .update(chatActions)
      .set({
        status: cancelled ? "cancelled" : processed ? "processed" : "failed",
        payload: terminal
          ? redactedGitHubWebhookIngressPayload(input.payload)
          : input.payload,
        result: {
          attempts: input.attempts,
          ...(input.cancelledCode ? { code: input.cancelledCode } : {}),
          ...(input.response
            ? { httpStatus: input.response.status }
            : { error: redactError(input.error) }),
          retryable: !terminal,
          ...(!terminal ? { retryAt: retryAt.toISOString() } : {}),
        },
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "github_webhook_ingress"),
          eq(chatActions.status, "processing"),
          sql`(${chatActions.result}->>'attempts')::int = ${input.attempts}`,
        ),
      );
  }

  async function processGitHubWebhookIngress(
    actionId: string,
    propagateProcessingFailure = false,
  ): Promise<Response | null> {
    let action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "github_webhook_ingress"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!action) return null;
    if (["processed", "cancelled"].includes(action.status))
      return githubIngressAcceptedResponse();
    if (action.status === "failed" && action.result?.retryable !== true)
      return githubIngressAcceptedResponse();
    const payload = githubWebhookIngressPayload(action.payload);
    if (!payload) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          payload: {},
          result: {
            code: "github_webhook_ingress_payload_invalid",
            retryable: false,
          },
          updatedAt: new Date(),
        })
        .where(eq(chatActions.id, action.id));
      return githubIngressAcceptedResponse();
    }
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    if (action.status === "processing" && action.updatedAt > staleBefore) {
      return null;
    }
    if (action.status === "failed") {
      const retryAt =
        typeof action.result?.retryAt === "string"
          ? new Date(action.result.retryAt)
          : null;
      if (retryAt && retryAt > now) return null;
    } else if (action.status !== "received" && action.status !== "processing") {
      return null;
    }
    const attempts =
      (typeof action.result?.attempts === "number"
        ? action.result.attempts
        : 0) + 1;
    const previousAttempts = attempts - 1;
    const claimGuard =
      action.status === "processing"
        ? and(
            eq(chatActions.status, "processing"),
            lte(chatActions.updatedAt, staleBefore),
            sql`coalesce((${chatActions.result}->>'attempts')::int, 0) = ${previousAttempts}`,
          )
        : action.status === "failed"
          ? and(
              eq(chatActions.status, "failed"),
              sql`coalesce((${chatActions.result}->>'attempts')::int, 0) = ${previousAttempts}`,
            )
          : eq(chatActions.status, "received");
    const [claimed] = await db
      .update(chatActions)
      .set({
        status: "processing",
        result: { attempts },
        updatedAt: now,
      })
      .where(
        and(
          eq(chatActions.id, action.id),
          eq(chatActions.kind, "github_webhook_ingress"),
          claimGuard,
        ),
      )
      .returning();
    if (!claimed) return null;
    action = claimed;

    const record = await endpointRecord(action.endpointId);
    if (
      !record ||
      record.endpoint.provider !== "github" ||
      !githubIngressAllowedInEndpointState(
        record.endpoint.status,
        payload.eventType,
      ) ||
      runtimeGeneration(record.endpoint.setup) !== payload.runtimeGeneration ||
      credentialFingerprint(record.credentialSecretRefs) !==
        payload.credentialFingerprint
    ) {
      await settleGitHubWebhookIngress(action.id, {
        attempts,
        payload,
        cancelledCode: "github_webhook_ingress_runtime_superseded",
      });
      return githubIngressAcceptedResponse();
    }

    try {
      const credentials = await resolveCredentialRefs(
        record.endpoint,
        record.credentialSecretRefs,
      );
      const recovery = await db
        .select({ payload: chatActions.payload, status: chatActions.status })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, record.endpoint.id),
            eq(chatActions.kind, "github_webhook_recovery"),
            eq(
              chatActions.providerActionId,
              `github_webhook_recovery:${payload.deliveryId}`,
            ),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (
        recovery &&
        (recovery.status === "cancelled" ||
          !(await githubRecoverySourceIsCurrent(
            (recovery.payload as GitHubRecoveryReceipt).original,
            credentials,
          )))
      ) {
        await settleGitHubWebhookIngress(action.id, {
          attempts,
          payload,
          cancelledCode: "github_webhook_recovery_source_changed",
        });
        return githubIngressAcceptedResponse();
      }
      const signature = `sha256=${createHmac(
        "sha256",
        credentials.webhookSecret,
      )
        .update(payload.body)
        .digest("hex")}`;
      await options.githubWebhookReplayBarrier?.();
      const replayContext = {
        githubIngressActionId: action.id,
        githubIngressFence: {
          generation: payload.runtimeGeneration,
          credentialFingerprint: payload.credentialFingerprint,
        },
        superseded: false,
      };
      const response = await handleWebhook(
        record.endpoint.publicId,
        "github",
        new Request(
          `https://paperclip.internal/api/chat-webhooks/${record.endpoint.publicId}/github`,
          {
            method: "POST",
            headers: {
              "content-type": payload.contentType,
              "x-github-delivery": payload.deliveryId,
              "x-github-event": payload.eventType,
              "x-hub-signature-256": signature,
            },
            body: payload.body,
          },
        ),
        replayContext,
      );
      if (replayContext.superseded) {
        await settleGitHubWebhookIngress(action.id, {
          attempts,
          payload,
          cancelledCode: "github_webhook_ingress_runtime_superseded",
        });
        return githubIngressAcceptedResponse();
      }
      if (response.status === 401) {
        const latest = await endpointRecord(action.endpointId);
        if (
          !latest ||
          runtimeGeneration(latest.endpoint.setup) !==
            payload.runtimeGeneration ||
          credentialFingerprint(latest.credentialSecretRefs) !==
            payload.credentialFingerprint
        ) {
          await settleGitHubWebhookIngress(action.id, {
            attempts,
            payload,
            cancelledCode: "github_webhook_ingress_runtime_superseded",
          });
          return githubIngressAcceptedResponse();
        }
      }
      await settleGitHubWebhookIngress(action.id, {
        attempts,
        payload,
        response,
      });
      return response.status >= 500 && !propagateProcessingFailure
        ? githubIngressAcceptedResponse()
        : response;
    } catch (error) {
      await settleGitHubWebhookIngress(action.id, {
        attempts,
        payload,
        error,
      });
      logger.warn(
        {
          actionId: action.id,
          endpointId: action.endpointId,
          error: redactError(error),
        },
        "durable GitHub webhook processing deferred",
      );
      if (propagateProcessingFailure) throw error;
      return githubIngressAcceptedResponse();
    }
  }

  async function githubRecoveryResource(
    database: DbOrTransaction,
    endpoint: EndpointRow,
    repositoryId: string,
    repositoryFullName?: string | null,
  ) {
    return database
      .select({ id: chatEndpointResources.id })
      .from(chatEndpointResources)
      .where(
        and(
          eq(chatEndpointResources.companyId, endpoint.companyId),
          eq(chatEndpointResources.endpointId, endpoint.id),
          eq(chatEndpointResources.type, "repository"),
          eq(chatEndpointResources.enabled, true),
          eq(chatEndpointResources.availability, "available"),
          sql`${chatEndpointResources.metadata}->>'providerRepositoryId' = ${repositoryId}`,
          repositoryFullName
            ? eq(
                chatEndpointResources.providerResourceId,
                repositoryFullName.toLowerCase(),
              )
            : undefined,
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
  }

  async function githubRecoveryAlreadyReceived(
    database: DbOrTransaction,
    endpoint: EndpointRow,
    guid: string,
  ) {
    const action = await database
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, endpoint.companyId),
          eq(chatActions.endpointId, endpoint.id),
          eq(chatActions.providerActionId, `github_webhook_ingress:${guid}`),
        ),
      )
      .limit(1)
      .then((rows) => rows[0]);
    if (action) return true;
    // Disabled destinations intentionally retain no ingress body. Their
    // content-free filtered receipt must also remain an admission fence.
    return database
      .select({ id: chatDeliveries.id })
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.companyId, endpoint.companyId),
          eq(chatDeliveries.endpointId, endpoint.id),
          eq(
            chatDeliveries.providerEventId,
            `github:filtered_ingress:${createHash("sha256").update(guid).digest("hex")}`,
          ),
        ),
      )
      .limit(1)
      .then((rows) => rows.length > 0);
  }

  async function rememberGitHubRecoverySkip(
    endpoint: EndpointRow,
    context: LifecycleRuntimeFence,
    window: GitHubRecoveryWindow,
    original: GitHubAppWebhookDelivery,
    code: string,
  ) {
    await db.transaction(async (tx) => {
      const current = await runtimeCallbackEndpoint(tx, endpoint.id, context, [
        "active",
      ]);
      if (
        !current ||
        !original.repositoryId ||
        !(await githubRecoveryResource(tx, current, original.repositoryId))
      )
        return;
      // Only the deny tombstone is needed, not the rejected detail or source
      // contents. Remembering it lets the next bounded scan reach older valid
      // messages instead of repeatedly inspecting the same five bot callbacks.
      await tx
        .insert(chatActions)
        .values({
          companyId: current.companyId,
          endpointId: current.id,
          kind: "github_webhook_recovery",
          providerActionId: `github_webhook_recovery:${original.guid}`,
          payload: {
            ...window,
            original: { id: original.id, guid: original.guid },
          },
          status: "cancelled",
          result: { attempts: 0, code },
        })
        .onConflictDoUpdate({
          target: [chatActions.endpointId, chatActions.providerActionId],
          set: {
            status: "cancelled",
            updatedAt: new Date(),
            result: sql`coalesce(${chatActions.result}, '{}'::jsonb) || jsonb_build_object('code', ${code}::text)`,
          },
          setWhere: and(
            eq(chatActions.kind, "github_webhook_recovery"),
            sql`(${chatActions.payload}->>'generation')::int = ${context.generation}`,
            sql`${chatActions.payload}->>'credentialFingerprint' = ${context.credentialFingerprint}`,
          ),
        });
    });
  }

  async function githubRecoverySourceIsCurrent(
    detail: GitHubAppWebhookDeliveryDetail,
    credentials: Record<string, string>,
  ): Promise<boolean> {
    const comment = detail?.payload?.comment;
    if (
      !comment ||
      !detail.payload.repositoryFullName ||
      !["issue_comment", "pull_request_review_comment"].includes(detail.event)
    )
      return false;
    const current = await getGitHubRecoveryComment({
      fetch: fetchImpl,
      appToken: githubAppJwt(credentials.appId, credentials.privateKey),
      installationId: credentials.installationId,
      repositoryFullName: detail.payload.repositoryFullName,
      event: detail.event as "issue_comment" | "pull_request_review_comment",
      commentId: comment.id,
    }).catch((error) => {
      if (error?.statusCode === 404 || error?.statusCode === 410) return null;
      throw error;
    });
    if (!current) return false;
    return (
      current.id === comment.id &&
      current.userId === comment.userId &&
      current.userType === "User" &&
      current.bodySha256 === comment.bodySha256 &&
      current.createdAt === comment.createdAt &&
      current.updatedAt === comment.updatedAt &&
      (detail.event === "issue_comment"
        ? current.issueNumber === detail.payload.issueNumber
        : current.pullRequestNumber === detail.payload.pullRequestNumber)
    );
  }

  /**
   * GitHub does not retry callbacks that fail before our durable inbox. Ask
   * GitHub to redeliver a bounded recent created-comment envelope, never turn
   * delivery-history JSON into a locally signed or directly admitted request.
   * A missing/changed epoch starts at now; historical messages are not adopted
   * into a new credential/generation merely because the App can still see them.
   */
  async function processFailedGitHubWebhookDeliveries(
    limit = 5,
    onlyEndpointId?: string,
  ) {
    if (shuttingDown || !webhookPublicBaseUrl?.startsWith("https://")) return 0;
    const now = new Date();
    const rows = await db
      .select({ endpoint: chatEndpoints })
      .from(chatEndpoints)
      .innerJoin(
        toolConnections,
        and(
          eq(toolConnections.id, chatEndpoints.connectionId),
          eq(toolConnections.companyId, chatEndpoints.companyId),
        ),
      )
      .leftJoin(
        chatSdkState,
        and(
          eq(chatSdkState.endpointId, chatEndpoints.id),
          eq(chatSdkState.stateKey, GITHUB_RECOVERY_STATE_KEY),
        ),
      )
      .where(
        and(
          eq(chatEndpoints.provider, "github"),
          eq(chatEndpoints.status, "active"),
          eq(toolConnections.enabled, true),
          eq(toolConnections.status, "active"),
          onlyEndpointId ? eq(chatEndpoints.id, onlyEndpointId) : undefined,
          or(
            isNull(chatSdkState.id),
            // Backoff belongs to one runtime epoch. Reconnect or callback
            // changes must establish a fresh floor immediately, even when
            // the superseded epoch was rate limited for several hours.
            sql`${chatSdkState.value}->>'generation' is distinct from coalesce(${chatEndpoints.setup}->>'runtimeGeneration', '0')`,
            sql`${chatSdkState.value}->>'appId' is distinct from ${chatEndpoints.botExternalId}`,
            sql`${chatSdkState.value}->>'webhookUrl' is distinct from (${webhookPublicBaseUrl} || '/api/chat-webhooks/' || ${chatEndpoints.publicId} || '/github')`,
            sql`(${chatSdkState.value}->>'nextScanAt')::timestamptz <= ${now.toISOString()}::timestamptz`,
          ),
        ),
      )
      .orderBy(asc(chatSdkState.updatedAt), asc(chatEndpoints.id))
      .limit(Math.min(5, Math.max(1, limit)));
    for (const { endpoint } of rows) {
      const record = await endpointRecord(endpoint.id);
      if (!record || !record.endpoint.botExternalId) continue;
      const context = runtimeContextForRecord(record);
      const webhookUrl = `${webhookPublicBaseUrl}/api/chat-webhooks/${endpoint.publicId}/github`;
      const scope = { companyId: endpoint.companyId, endpointId: endpoint.id };
      const stored = await persistence.read(scope, GITHUB_RECOVERY_STATE_KEY);
      const previous = githubRecoveryWindow(stored?.value);
      const epochMatches =
        previous &&
        previous.generation === context.generation &&
        previous.credentialFingerprint === context.credentialFingerprint &&
        previous.webhookUrl === webhookUrl &&
        previous.appId === record.endpoint.botExternalId;
      if (epochMatches && Date.parse(previous.nextScanAt) > now.getTime())
        continue;
      const window: GitHubRecoveryWindow = {
        generation: context.generation,
        credentialFingerprint: context.credentialFingerprint,
        appId: record.endpoint.botExternalId,
        webhookUrl,
        floor: epochMatches ? previous.floor : now.toISOString(),
        nextScanAt: new Date(
          now.getTime() + GITHUB_RECOVERY_SCAN_LEASE_MS,
        ).toISOString(),
      };
      if (
        !(await persistence.compareAndSet({
          ...scope,
          key: GITHUB_RECOVERY_STATE_KEY,
          expectedVersion: stored?.version ?? null,
          value: window,
          expiresAt: null,
        }))
      )
        continue;
      const claimedVersion = (stored?.version ?? 0) + 1;
      let nextDelay = GITHUB_RECOVERY_INTERVAL_MS;
      let outcome = "scanned";
      let requested = 0;
      let inspected = 0;
      try {
        if (!epochMatches) {
          outcome = "epoch_initialized";
          continue;
        }
        const credentials = await resolveCredentialRefs(
          record.endpoint,
          record.credentialSecretRefs,
        );
        if (credentials.appId !== window.appId || !credentials.installationId)
          continue;
        const appToken = githubAppJwt(
          credentials.appId,
          credentials.privateKey,
        );
        const config = await readGitHubAppWebhookConfig({
          fetch: fetchImpl,
          appToken,
        });
        if (
          config.url !== webhookUrl ||
          config.contentType !== "json" ||
          config.insecureSsl !== "0"
        ) {
          outcome = "callback_mismatch";
          nextDelay = 5 * 60_000;
          continue;
        }
        const attempts: GitHubAppWebhookDelivery[] = [];
        const floor = Math.max(
          Date.parse(window.floor),
          now.getTime() - GITHUB_RECOVERY_WINDOW_MS,
        );
        let cursor: string | undefined;
        let truncated = false;
        let previousTimestamp = Number.POSITIVE_INFINITY;
        for (let page = 0; page < 3; page += 1) {
          const result = await listGitHubAppWebhookDeliveries({
            fetch: fetchImpl,
            appToken,
            cursor,
          });
          // GitHub's official recovery recipe uses newest-first pagination
          // and stops at the age floor. Reject observed ordering drift rather
          // than assuming unseen pages cannot contain a successful sibling.
          for (const attempt of result.deliveries) {
            const timestamp = Date.parse(attempt.deliveredAt);
            if (timestamp > previousTimestamp)
              throw new Error("GitHub recovery history ordering changed");
            previousTimestamp = timestamp;
            if (timestamp >= floor) attempts.push(attempt);
          }
          if (previousTimestamp < floor) break;
          if (!result.nextCursor) break;
          if (result.nextCursor === cursor)
            throw new Error("GitHub recovery pagination did not advance");
          cursor = result.nextCursor;
          truncated = page === 2;
        }
        // All pages in this time window are needed to rule out a successful
        // sibling; do not act on a partial window after hitting the work cap.
        if (truncated) {
          outcome = "history_limit_reached";
          nextDelay = 5 * 60_000;
          continue;
        }
        const groups = new Map<string, GitHubAppWebhookDelivery[]>();
        for (const attempt of attempts) {
          const group = groups.get(attempt.guid) ?? [];
          group.push(attempt);
          groups.set(attempt.guid, group);
        }
        for (const [guid, group] of groups) {
          if (
            inspected >= 5 ||
            shuttingDown ||
            Date.now() >= Date.parse(window.nextScanAt)
          )
            break;
          if (
            group.some(
              (item) =>
                item.statusCode !== null &&
                item.statusCode >= 200 &&
                item.statusCode < 400,
            )
          )
            continue;
          const originals = group.filter((item) => !item.redelivery);
          if (originals.length !== 1) continue;
          const original = originals[0]!;
          if (
            Date.parse(original.deliveredAt) < floor ||
            Date.parse(original.deliveredAt) > now.getTime() - 10_000 ||
            original.statusCode === null ||
            original.statusCode < 500 ||
            original.action !== "created" ||
            !["issue_comment", "pull_request_review_comment"].includes(
              original.event,
            ) ||
            original.installationId !== credentials.installationId ||
            !original.repositoryId ||
            !(await githubRecoveryResource(db, endpoint, original.repositoryId))
          )
            continue;
          const recoveryId = `github_webhook_recovery:${guid}`;
          if (await githubRecoveryAlreadyReceived(db, endpoint, guid)) continue;
          const receipt = await db
            .select()
            .from(chatActions)
            .where(
              and(
                eq(chatActions.endpointId, endpoint.id),
                eq(chatActions.providerActionId, recoveryId),
              ),
            )
            .then((items) => items[0] ?? null);
          const count =
            typeof receipt?.result?.attempts === "number"
              ? receipt.result.attempts
              : 0;
          const receiptWindow = githubRecoveryWindow(receipt?.payload);
          const latest = [...group].sort(
            (left, right) =>
              Date.parse(right.deliveredAt) - Date.parse(left.deliveredAt),
          )[0]!;
          if (
            latest.statusCode === null ||
            latest.statusCode < 500 ||
            latest.throttledAt !== null ||
            Date.parse(latest.deliveredAt) > now.getTime() - 10_000
          )
            continue;
          if (
            receipt &&
            (receipt.status === "cancelled" ||
              !receiptWindow ||
              receiptWindow.generation !== window.generation ||
              receiptWindow.credentialFingerprint !==
                window.credentialFingerprint ||
              receiptWindow.webhookUrl !== window.webhookUrl ||
              count >= 3 ||
              receipt.result?.latestAttemptId === latest.id ||
              !latest.redelivery ||
              latest.statusCode === null ||
              latest.statusCode < 500 ||
              Date.parse(latest.deliveredAt) <
                Date.parse(String(receipt.result?.requestedAt)) ||
              Date.parse(String(receipt.result?.retryAt)) > now.getTime())
          )
            continue;
          inspected += 1;
          const detail = await getGitHubAppWebhookDelivery({
            fetch: fetchImpl,
            appToken,
            deliveryId: original.id,
          });
          const comment = detail.payload.comment;
          if (
            detail.id !== original.id ||
            detail.guid !== guid ||
            detail.redelivery ||
            detail.url !== webhookUrl ||
            detail.event !== original.event ||
            detail.deliveredAt !== original.deliveredAt ||
            detail.statusCode !== original.statusCode ||
            detail.installationId !== original.installationId ||
            detail.repositoryId !== original.repositoryId ||
            detail.action !== "created" ||
            detail.payload.action !== "created" ||
            detail.payload.installationId !== credentials.installationId ||
            detail.payload.repositoryId !== original.repositoryId ||
            !comment ||
            comment.userType !== "User" ||
            detail.payload.senderId !== comment.userId ||
            Date.parse(comment.createdAt) < floor ||
            comment.createdAt !== comment.updatedAt ||
            !(await githubRecoveryResource(
              db,
              endpoint,
              original.repositoryId,
              detail.payload.repositoryFullName,
            ))
          ) {
            await rememberGitHubRecoverySkip(
              endpoint,
              context,
              window,
              original,
              "not_eligible_for_recovery",
            );
            continue;
          }
          if (!(await githubRecoverySourceIsCurrent(detail, credentials))) {
            await rememberGitHubRecoverySkip(
              endpoint,
              context,
              window,
              original,
              "source_changed_or_unavailable",
            );
            continue;
          }
          await withCredentialMutationLease(endpoint, async (lease) => {
            await lease.assertOwned();
            const currentConfig = await readGitHubAppWebhookConfig({
              fetch: fetchImpl,
              appToken,
            });
            if (
              currentConfig.url !== webhookUrl ||
              currentConfig.contentType !== "json" ||
              currentConfig.insecureSsl !== "0"
            )
              return;
            const claimed = await db.transaction(async (tx) => {
              await lease.assertOwned(tx);
              const current = await runtimeCallbackEndpoint(
                tx,
                endpoint.id,
                context,
                ["active"],
              );
              if (
                !current ||
                !(await githubRecoveryResource(
                  tx,
                  current,
                  original.repositoryId!,
                  detail.payload.repositoryFullName,
                ))
              )
                return null;
              const connection = await tx
                .select({ id: toolConnections.id })
                .from(toolConnections)
                .where(
                  and(
                    eq(toolConnections.id, current.connectionId),
                    eq(toolConnections.companyId, current.companyId),
                    eq(toolConnections.enabled, true),
                    eq(toolConnections.status, "active"),
                  ),
                )
                .then((items) => items[0]);
              const scan = await tx
                .select({ id: chatSdkState.id })
                .from(chatSdkState)
                .where(
                  and(
                    eq(chatSdkState.endpointId, endpoint.id),
                    eq(chatSdkState.stateKey, GITHUB_RECOVERY_STATE_KEY),
                    eq(chatSdkState.version, claimedVersion),
                  ),
                )
                .then((items) => items[0]);
              const local = await githubRecoveryAlreadyReceived(
                tx,
                current,
                guid,
              );
              if (
                !connection ||
                !scan ||
                local ||
                shuttingDown ||
                Date.now() >= Date.parse(window.nextScanAt)
              )
                return null;
              const result = {
                attempts: count + 1,
                latestAttemptId: latest.id,
                requestedAt: new Date().toISOString(),
                retryAt: new Date(
                  Date.now() + 60_000 * 5 ** count,
                ).toISOString(),
              };
              const payload: GitHubRecoveryReceipt = {
                ...window,
                original: detail,
              };
              const changes = receipt
                ? await tx
                    .update(chatActions)
                    .set({
                      status: "processing",
                      result,
                      updatedAt: new Date(),
                    })
                    .where(
                      and(
                        eq(chatActions.id, receipt.id),
                        eq(chatActions.updatedAt, receipt.updatedAt),
                      ),
                    )
                    .returning({ id: chatActions.id })
                : await tx
                    .insert(chatActions)
                    .values({
                      companyId: endpoint.companyId,
                      endpointId: endpoint.id,
                      kind: "github_webhook_recovery",
                      providerActionId: recoveryId,
                      payload,
                      status: "processing",
                      result,
                    })
                    .onConflictDoNothing()
                    .returning({ id: chatActions.id });
              return changes[0]?.id ?? null;
            });
            if (!claimed) return;
            requested += 1;
            // Commit the immutable denial fence before transport. Even an
            // ambiguous POST is not reattempted without a distinct failed
            // provider delivery. A stale scanner cannot overwrite a successor.
            await lease.assertOwned();
            try {
              await requestGitHubAppWebhookRedelivery({
                fetch: fetchImpl,
                appToken,
                deliveryId: original.id,
              });
              await db
                .update(chatActions)
                .set({ status: "processed", updatedAt: new Date() })
                .where(
                  and(
                    eq(chatActions.id, claimed),
                    eq(chatActions.status, "processing"),
                    sql`(${chatActions.result}->>'attempts')::int = ${count + 1}`,
                  ),
                );
            } catch (error) {
              await db
                .update(chatActions)
                .set({ status: "delivery_unknown", updatedAt: new Date() })
                .where(
                  and(
                    eq(chatActions.id, claimed),
                    eq(chatActions.status, "processing"),
                    sql`(${chatActions.result}->>'attempts')::int = ${count + 1}`,
                  ),
                );
              throw error;
            }
          });
        }
      } catch (error) {
        outcome = "scan_failed";
        nextDelay = Math.max(
          5 * 60_000,
          Math.min(
            24 * 60 * 60_000,
            Number((error as { retryAfterMs?: unknown })?.retryAfterMs) || 0,
          ),
        );
        logger.warn(
          { endpointId: endpoint.id, error: redactError(error) },
          "GitHub webhook recovery deferred",
        );
      } finally {
        await persistence.compareAndSet({
          ...scope,
          key: GITHUB_RECOVERY_STATE_KEY,
          expectedVersion: claimedVersion,
          value: {
            ...window,
            nextScanAt: new Date(Date.now() + nextDelay).toISOString(),
            outcome,
            requested,
          },
          expiresAt: null,
        });
      }
    }
    return rows.length;
  }

  async function processPendingGitHubWebhookIngress(
    limit = 25,
    onlyActionId?: string,
  ) {
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    const actions = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "github_webhook_ingress"),
          ...(onlyActionId ? [eq(chatActions.id, onlyActionId)] : []),
          or(
            eq(chatActions.status, "received"),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, staleBefore),
            ),
            and(
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'true'`,
              sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.createdAt))
      .limit(limit);
    for (const action of actions) await processGitHubWebhookIngress(action.id);
    return actions.length;
  }

  async function stageSlackSessionStop(
    endpoint: EndpointRow,
    event: SlackSessionStop,
    runtimeContext: RuntimeContext,
  ): Promise<string | null> {
    return db.transaction(async (tx) => {
      const currentEndpoint = await runtimeCallbackEndpoint(
        tx,
        endpoint.id,
        runtimeContext,
        ["active"],
      );
      if (!currentEndpoint || currentEndpoint.provider !== "slack") return null;

      const conversation = await tx
        .select()
        .from(chatConversations)
        .where(
          and(
            eq(chatConversations.companyId, currentEndpoint.companyId),
            eq(chatConversations.endpointId, currentEndpoint.id),
            eq(chatConversations.externalThreadId, event.threadId),
            inArray(chatConversations.state, ["active", "waiting"]),
          ),
        )
        .orderBy(desc(chatConversations.sessionGeneration))
        .limit(1)
        .for("update")
        .then((rows) => rows[0] ?? null);
      const principal = await tx
        .select()
        .from(chatExternalPrincipals)
        .where(
          and(
            eq(chatExternalPrincipals.companyId, currentEndpoint.companyId),
            eq(chatExternalPrincipals.provider, "slack"),
            eq(
              chatExternalPrincipals.providerAccountId,
              currentEndpoint.providerAccountId ?? "unknown",
            ),
            eq(chatExternalPrincipals.externalId, event.userId),
            eq(chatExternalPrincipals.kind, "user"),
            eq(chatExternalPrincipals.isBot, false),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const issue = conversation
        ? await tx
            .select()
            .from(issues)
            .where(
              and(
                eq(issues.companyId, currentEndpoint.companyId),
                eq(issues.id, conversation.issueId),
                eq(issues.assigneeAgentId, currentEndpoint.assignedAgentId),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;

      // Slack carries fractional event timestamps. Treat that exact instant as
      // the cancellation boundary so a run admitted even milliseconds after
      // Stop was clicked can never be mistaken for the stopped session.
      const eventCutoff = event.occurredAt;
      const futureEvent = event.occurredAt.getTime() > Date.now() + 60_000;
      let target: SlackSessionStopTarget | null = null;
      if (issue && !futureEvent && issue.executionRunId) {
        const run = await tx
          .select({
            agentId: heartbeatRuns.agentId,
            companyId: heartbeatRuns.companyId,
            contextSnapshot: heartbeatRuns.contextSnapshot,
            createdAt: heartbeatRuns.createdAt,
            id: heartbeatRuns.id,
            startedAt: heartbeatRuns.startedAt,
          })
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.id, issue.executionRunId),
              eq(heartbeatRuns.companyId, currentEndpoint.companyId),
              eq(heartbeatRuns.agentId, currentEndpoint.assignedAgentId),
              inArray(heartbeatRuns.status, [
                "queued",
                "running",
                "scheduled_retry",
              ]),
              lte(heartbeatRuns.createdAt, eventCutoff),
              or(
                isNull(heartbeatRuns.startedAt),
                lte(heartbeatRuns.startedAt, eventCutoff),
              ),
              or(
                sql`${heartbeatRuns.contextSnapshot}->>'issueId' = ${issue.id}`,
                sql`${heartbeatRuns.contextSnapshot}->>'taskId' = ${issue.id}`,
              ),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (run) target = { id: run.id, kind: "run" };
      } else if (issue && !futureEvent && !issue.executionRunId) {
        const wakeup = await tx
          .select({ id: agentWakeupRequests.id })
          .from(agentWakeupRequests)
          .where(
            and(
              eq(agentWakeupRequests.companyId, currentEndpoint.companyId),
              eq(agentWakeupRequests.agentId, currentEndpoint.assignedAgentId),
              inArray(agentWakeupRequests.status, [
                "queued",
                "deferred_issue_execution",
              ]),
              isNull(agentWakeupRequests.runId),
              lte(agentWakeupRequests.requestedAt, eventCutoff),
              or(
                sql`${agentWakeupRequests.payload}->>'issueId' = ${issue.id}`,
                sql`${agentWakeupRequests.payload}->>'taskId' = ${issue.id}`,
                sql`${agentWakeupRequests.payload}->'_paperclipWakeContext'->>'issueId' = ${issue.id}`,
                sql`${agentWakeupRequests.payload}->'_paperclipWakeContext'->>'taskId' = ${issue.id}`,
              ),
            ),
          )
          .orderBy(desc(agentWakeupRequests.requestedAt))
          .limit(1)
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (wakeup) target = { id: wakeup.id, kind: "wakeup" };
      }

      const payload: SlackSessionStopPayload = {
        version: 1,
        assignedAgentId: currentEndpoint.assignedAgentId,
        eventTimestamp: event.eventTimestamp,
        issueId: issue?.id ?? null,
        occurredAt: event.occurredAt.toISOString(),
        sessionGeneration: conversation?.sessionGeneration ?? null,
        target,
        threadId: event.threadId,
        userId: event.userId,
      };
      const [inserted] = await tx
        .insert(chatActions)
        .values({
          companyId: currentEndpoint.companyId,
          endpointId: currentEndpoint.id,
          conversationId: conversation?.id ?? null,
          principalId: principal?.id ?? null,
          kind: "slack_session_stop",
          providerActionId: `slack_session_stop:${event.providerEventId}`,
          payload,
          status: "received",
        })
        .onConflictDoNothing()
        .returning({ id: chatActions.id });
      return (
        inserted?.id ??
        (await tx
          .select({ id: chatActions.id })
          .from(chatActions)
          .where(
            and(
              eq(chatActions.endpointId, currentEndpoint.id),
              eq(
                chatActions.providerActionId,
                `slack_session_stop:${event.providerEventId}`,
              ),
              eq(chatActions.kind, "slack_session_stop"),
            ),
          )
          .then((rows) => rows[0]?.id ?? null))
      );
    });
  }

  async function processSlackSessionStop(actionId: string): Promise<void> {
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    const action = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "slack_session_stop"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!action || ["processed", "cancelled"].includes(action.status)) return;
    if (action.status === "processing" && action.updatedAt > staleBefore)
      return;
    if (action.status === "failed") {
      if (action.result?.retryable !== true) return;
      const retryAt =
        typeof action.result.retryAt === "string"
          ? new Date(action.result.retryAt)
          : null;
      if (retryAt && retryAt > now) return;
    } else if (action.status !== "received" && action.status !== "processing") {
      return;
    }
    const payload = slackSessionStopPayload(action.payload);
    const previousAttempts =
      typeof action.result?.attempts === "number" &&
      Number.isSafeInteger(action.result.attempts)
        ? Math.max(0, action.result.attempts)
        : 0;
    const attempts = previousAttempts + 1;
    if (!payload) {
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            attempts,
            code: "slack_session_stop_payload_invalid",
            retryable: false,
          },
          updatedAt: now,
        })
        .where(eq(chatActions.id, action.id));
      return;
    }

    type StopClaim =
      | { kind: "cancel_run"; runId: string; userId: string }
      | { kind: "settled" }
      | { kind: "retry" };
    const claim = await db.transaction(async (tx): Promise<StopClaim> => {
      const current = await tx
        .select()
        .from(chatActions)
        .where(eq(chatActions.id, action.id))
        .for("update")
        .then((rows) => rows[0] ?? null);
      const currentRetryAt =
        typeof current?.result?.retryAt === "string"
          ? new Date(current.result.retryAt)
          : null;
      const currentRetryIsDue =
        currentRetryAt === null ||
        (Number.isFinite(currentRetryAt.getTime()) && currentRetryAt <= now);
      const eligible =
        current?.status === "received" ||
        (current?.status === "processing" &&
          current.updatedAt <= staleBefore &&
          (current.result?.attempts ?? 0) === previousAttempts) ||
        (current?.status === "failed" &&
          current.result?.retryable === true &&
          currentRetryIsDue &&
          (current.result?.attempts ?? 0) === previousAttempts);
      if (!current || !eligible) return { kind: "settled" };

      const settle = async (
        code: string,
        actorUserId: string | null,
        targetKind: "run" | "wakeup" | "none",
      ): Promise<StopClaim> => {
        await tx
          .update(chatActions)
          .set({
            status:
              code === "slack_session_stop_cancelled"
                ? "processed"
                : "cancelled",
            result: { attempts, code, retryable: false },
            updatedAt: now,
          })
          .where(eq(chatActions.id, current.id));
        await logActivity(tx as unknown as Db, {
          companyId: current.companyId,
          actorType: actorUserId ? "user" : "system",
          actorId: actorUserId ?? "slack-session-stop",
          action:
            code === "slack_session_stop_cancelled"
              ? "chat.slack_session_stopped"
              : "chat.slack_session_stop_filtered",
          entityType: "chat_action",
          entityId: current.id,
          details: {
            endpointId: current.endpointId,
            conversationId: current.conversationId,
            eventTimestamp: payload.eventTimestamp,
            targetKind,
            resultCode: code,
          },
        });
        return { kind: "settled" };
      };

      if (
        !payload.target ||
        !payload.issueId ||
        !payload.sessionGeneration ||
        !current.conversationId ||
        !current.principalId
      ) {
        return settle("slack_session_stop_no_current_work", null, "none");
      }
      const endpoint = await tx
        .select()
        .from(chatEndpoints)
        .where(
          and(
            eq(chatEndpoints.id, current.endpointId),
            eq(chatEndpoints.companyId, current.companyId),
            eq(chatEndpoints.provider, "slack"),
            eq(chatEndpoints.status, "active"),
            eq(chatEndpoints.assignedAgentId, payload.assignedAgentId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const conversation = endpoint
        ? await tx
            .select()
            .from(chatConversations)
            .where(
              and(
                eq(chatConversations.id, current.conversationId),
                eq(chatConversations.companyId, current.companyId),
                eq(chatConversations.endpointId, current.endpointId),
                eq(chatConversations.issueId, payload.issueId),
                eq(chatConversations.externalThreadId, payload.threadId),
                eq(
                  chatConversations.sessionGeneration,
                  payload.sessionGeneration,
                ),
                inArray(chatConversations.state, ["active", "waiting"]),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;
      const resource =
        endpoint && conversation?.resourceId
          ? await tx
              .select()
              .from(chatEndpointResources)
              .where(
                and(
                  eq(chatEndpointResources.id, conversation.resourceId),
                  eq(chatEndpointResources.companyId, current.companyId),
                  eq(chatEndpointResources.endpointId, current.endpointId),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null)
          : null;
      const principal = endpoint
        ? await tx
            .select()
            .from(chatExternalPrincipals)
            .where(
              and(
                eq(chatExternalPrincipals.id, current.principalId),
                eq(chatExternalPrincipals.companyId, current.companyId),
                eq(chatExternalPrincipals.provider, "slack"),
                eq(
                  chatExternalPrincipals.providerAccountId,
                  endpoint.providerAccountId ?? "unknown",
                ),
                eq(chatExternalPrincipals.externalId, payload.userId),
                eq(chatExternalPrincipals.kind, "user"),
                eq(chatExternalPrincipals.isBot, false),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;
      const authorization =
        endpoint && principal
          ? await lockCurrentPrincipalAuthorization(tx, endpoint, principal.id)
          : null;
      const destinationAllowed =
        endpoint && conversation
          ? conversation.isDirectMessage
            ? endpoint.allowDirectMessages
            : nonDirectDestinationAllowed(endpoint, resource)
          : false;
      const issue =
        endpoint && conversation
          ? await tx
              .select()
              .from(issues)
              .where(
                and(
                  eq(issues.id, payload.issueId),
                  eq(issues.companyId, current.companyId),
                  eq(issues.assigneeAgentId, payload.assignedAgentId),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null)
          : null;
      if (
        !endpoint ||
        !conversation ||
        !principal ||
        !authorization?.allowed ||
        !authorization.userId ||
        !destinationAllowed ||
        !issue
      ) {
        return settle(
          "slack_session_stop_no_longer_authorized",
          null,
          payload.target.kind,
        );
      }

      const eventCutoff = new Date(payload.occurredAt);
      let runId: string | null = null;
      if (payload.target.kind === "run") {
        runId = payload.target.id;
      } else {
        const wakeup = await tx
          .select()
          .from(agentWakeupRequests)
          .where(
            and(
              eq(agentWakeupRequests.id, payload.target.id),
              eq(agentWakeupRequests.companyId, current.companyId),
              eq(agentWakeupRequests.agentId, payload.assignedAgentId),
              lte(agentWakeupRequests.requestedAt, eventCutoff),
              or(
                sql`${agentWakeupRequests.payload}->>'issueId' = ${issue.id}`,
                sql`${agentWakeupRequests.payload}->>'taskId' = ${issue.id}`,
                sql`${agentWakeupRequests.payload}->'_paperclipWakeContext'->>'issueId' = ${issue.id}`,
                sql`${agentWakeupRequests.payload}->'_paperclipWakeContext'->>'taskId' = ${issue.id}`,
              ),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (
          wakeup &&
          !wakeup.runId &&
          ["queued", "deferred_issue_execution"].includes(wakeup.status) &&
          !issue.executionRunId
        ) {
          await tx
            .update(agentWakeupRequests)
            .set({
              status: "cancelled",
              finishedAt: now,
              error: "Cancelled from the bound Slack agent session",
              updatedAt: now,
            })
            .where(
              and(
                eq(agentWakeupRequests.id, wakeup.id),
                inArray(agentWakeupRequests.status, [
                  "queued",
                  "deferred_issue_execution",
                ]),
                isNull(agentWakeupRequests.runId),
              ),
            );
          const agentName = await tx
            .select({ name: agents.name })
            .from(agents)
            .where(
              and(
                eq(agents.companyId, current.companyId),
                eq(agents.id, payload.assignedAgentId),
              ),
            )
            .then((rows) => rows[0]?.name ?? "Paperclip agent");
          await stageAuthorizedTaskControlPublication(tx, {
            companyId: current.companyId,
            conversationId: conversation.id,
            endpointId: current.endpointId,
            idempotencyKey: `control:stop:${current.id}`,
            issueId: issue.id,
            payload: projectSafeChatPublication({
              classification: "external",
              progressState: "failed",
              source: "safe_milestone",
              text: safeMilestoneText({
                agentName,
                errorCode: "slack_session_stopped",
                issueId: issue.id,
                milestone: "failed",
                publicBaseUrl,
              }),
            }),
            principalId: principal.id,
          });
          return settle(
            "slack_session_stop_cancelled",
            authorization.userId,
            "wakeup",
          );
        }
        runId = wakeup?.runId ?? null;
        if (!runId && wakeup?.status === "claimed") {
          await tx
            .update(chatActions)
            .set({
              status: "failed",
              result: {
                attempts,
                code: "slack_session_stop_wakeup_in_flight",
                retryable: true,
                retryAt: new Date(Date.now() + 1_000).toISOString(),
              },
              updatedAt: now,
            })
            .where(eq(chatActions.id, current.id));
          return { kind: "retry" };
        }
      }

      const run = runId
        ? await tx
            .select()
            .from(heartbeatRuns)
            .where(
              and(
                eq(heartbeatRuns.id, runId),
                eq(heartbeatRuns.companyId, current.companyId),
                eq(heartbeatRuns.agentId, payload.assignedAgentId),
                payload.target.kind === "wakeup"
                  ? eq(heartbeatRuns.wakeupRequestId, payload.target.id)
                  : and(
                      lte(heartbeatRuns.createdAt, eventCutoff),
                      or(
                        isNull(heartbeatRuns.startedAt),
                        lte(heartbeatRuns.startedAt, eventCutoff),
                      ),
                    ),
                or(
                  sql`${heartbeatRuns.contextSnapshot}->>'issueId' = ${issue.id}`,
                  sql`${heartbeatRuns.contextSnapshot}->>'taskId' = ${issue.id}`,
                ),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;
      if (!run) {
        return settle(
          "slack_session_stop_target_superseded",
          authorization.userId,
          payload.target.kind,
        );
      }
      if (run.status === "cancelled") {
        return settle(
          "slack_session_stop_cancelled",
          authorization.userId,
          "run",
        );
      }
      if (
        issue.executionRunId !== run.id ||
        !["queued", "running", "scheduled_retry"].includes(run.status)
      ) {
        return settle(
          "slack_session_stop_target_superseded",
          authorization.userId,
          "run",
        );
      }
      await tx
        .update(chatActions)
        .set({
          status: "processing",
          result: {
            attempts,
            authorizedUserId: authorization.userId,
            runId: run.id,
          },
          updatedAt: now,
        })
        .where(eq(chatActions.id, current.id));
      return {
        kind: "cancel_run",
        runId: run.id,
        userId: authorization.userId,
      };
    });
    if (claim.kind !== "cancel_run") return;

    try {
      if (!options.heartbeat.cancelRun) {
        throw new Error("Heartbeat cancellation is unavailable");
      }
      await options.heartbeat.cancelRun(
        claim.runId,
        "Stopped from the bound Slack agent session",
        {
          errorCode: "slack_session_stopped",
          eventMessage: "run cancelled from Slack",
          eventPayload: {
            endpointId: action.endpointId,
            conversationId: action.conversationId,
            provider: "slack",
          },
        },
      );
      await enqueueChatRunMilestones(db, { publicBaseUrl });
      const authoritativeRun = await db
        .select({ status: heartbeatRuns.status })
        .from(heartbeatRuns)
        .where(eq(heartbeatRuns.id, claim.runId))
        .then((rows) => rows[0] ?? null);
      const cancellationWon = authoritativeRun?.status === "cancelled";
      await db.transaction(async (tx) => {
        const [settled] = await tx
          .update(chatActions)
          .set({
            status: cancellationWon ? "processed" : "cancelled",
            result: {
              attempts,
              code: cancellationWon
                ? "slack_session_stop_cancelled"
                : "slack_session_stop_target_superseded",
              runId: claim.runId,
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, action.id),
              eq(chatActions.status, "processing"),
              sql`(${chatActions.result}->>'attempts')::int = ${attempts}`,
              sql`${chatActions.result}->>'runId' = ${claim.runId}`,
            ),
          )
          .returning({ id: chatActions.id });
        if (!settled) return;
        await logActivity(tx as unknown as Db, {
          companyId: action.companyId,
          actorType: "user",
          actorId: claim.userId,
          action: cancellationWon
            ? "chat.slack_session_stopped"
            : "chat.slack_session_stop_filtered",
          entityType: "chat_action",
          entityId: action.id,
          details: {
            endpointId: action.endpointId,
            conversationId: action.conversationId,
            eventTimestamp: payload.eventTimestamp,
            targetKind: "run",
            resultCode: cancellationWon
              ? "slack_session_stop_cancelled"
              : "slack_session_stop_target_superseded",
          },
        });
      });
    } catch (error) {
      const retryable = attempts < 5;
      await db
        .update(chatActions)
        .set({
          status: "failed",
          result: {
            attempts,
            code: "slack_session_stop_cancellation_failed",
            retryable,
            ...(retryable
              ? {
                  retryAt: new Date(
                    Date.now() + Math.min(60_000, 1_000 * 2 ** (attempts - 1)),
                  ).toISOString(),
                }
              : {}),
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, action.id),
            eq(chatActions.status, "processing"),
            sql`(${chatActions.result}->>'attempts')::int = ${attempts}`,
            sql`${chatActions.result}->>'runId' = ${claim.runId}`,
          ),
        );
      logger.warn(
        {
          actionId: action.id,
          endpointId: action.endpointId,
          attempts,
          error: redactError(error),
        },
        "Slack session stop cancellation deferred",
      );
    }
  }

  async function processPendingSlackSessionStops(
    limit = 25,
    onlyActionId?: string,
  ) {
    const now = new Date();
    const staleBefore = new Date(now.getTime() - PROVIDER_EFFECT_STALE_MS);
    const actions = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "slack_session_stop"),
          ...(onlyActionId ? [eq(chatActions.id, onlyActionId)] : []),
          or(
            eq(chatActions.status, "received"),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, staleBefore),
            ),
            and(
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'true'`,
              sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.createdAt))
      .limit(limit);
    for (const action of actions) await processSlackSessionStop(action.id);
    return actions.length;
  }

  async function handleWebhook(
    publicId: string,
    provider: ChatSdkProvider,
    request: Request,
    internalContext?: {
      githubIngressActionId: string;
      githubIngressFence: LifecycleRuntimeFence;
      superseded?: boolean;
    },
  ) {
    const serviceReceivedAtMs = Date.now();
    const replayingDurableGitHubIngress =
      provider === "github" && Boolean(internalContext?.githubIngressActionId);
    const ignoreSupersededIngress = () => {
      if (internalContext) internalContext.superseded = true;
      return new Response("ignored", { status: 200 });
    };
    const matchesGitHubIngressFence = (context: LifecycleRuntimeFence) => {
      if (!replayingDurableGitHubIngress) return true;
      const matches =
        context.generation ===
          internalContext?.githubIngressFence?.generation &&
        context.credentialFingerprint ===
          internalContext?.githubIngressFence?.credentialFingerprint;
      if (!matches && internalContext) internalContext.superseded = true;
      return matches;
    };
    const githubResponseDeadlineAt =
      provider === "github" && !replayingDurableGitHubIngress
        ? Date.now() +
          Math.max(
            1,
            Math.min(
              options.githubWebhookResponseBudgetMs ??
                GITHUB_WEBHOOK_RESPONSE_BUDGET_MS,
              9_000,
            ),
          )
        : null;
    const completeGitHubPreflightBeforeDeadline = async <T>(
      task: Promise<T>,
    ): Promise<
      { completed: true; value: T } | { completed: false; value?: never }
    > => {
      if (githubResponseDeadlineAt === null)
        return { completed: true, value: await task };
      const remaining = githubResponseDeadlineAt - Date.now();
      if (remaining <= 0) return { completed: false };
      let timeout: ReturnType<typeof setTimeout> | null = null;
      try {
        return await Promise.race([
          task.then((value) => ({ completed: true as const, value })),
          new Promise<{ completed: false; value?: never }>((resolve) => {
            timeout = setTimeout(
              () => resolve({ completed: false }),
              remaining,
            );
            timeout.unref?.();
          }),
        ]);
      } finally {
        if (timeout) clearTimeout(timeout);
      }
    };
    const endpoint = await db
      .select()
      .from(chatEndpoints)
      .where(
        and(
          eq(chatEndpoints.publicId, publicId),
          eq(chatEndpoints.provider, provider),
        ),
      )
      .then((rows) => rows[0] ?? null);
    const recoveringRevokedGitHubInstallation =
      endpoint?.status === "revoked" &&
      provider === "github" &&
      request.headers.get("x-github-event") === "installation";
    if (
      !endpoint ||
      endpoint.status === "archived" ||
      (endpoint.status === "revoked" && !recoveringRevokedGitHubInstallation)
    ) {
      if (replayingDurableGitHubIngress) return ignoreSupersededIngress();
      throw notFound("Chat endpoint not found");
    }
    recordChatWebhookStage("endpoint_resolved", endpoint.id);
    // A pause is a durable ingress fence. Providers generally retry non-2xx
    // webhooks, so acknowledge late callbacks without recreating a runtime or
    // admitting any Paperclip mutation.
    if (endpoint.status === "paused") {
      if (replayingDurableGitHubIngress) return ignoreSupersededIngress();
      return new Response("ignored", { status: 200 });
    }
    if (provider === "github" && !replayingDurableGitHubIngress) {
      await options.githubWebhookAuthenticationBarrier?.();
      let staged: GitHubIngressStageResult;
      try {
        staged = await stageGitHubWebhookIngress(endpoint, request.clone());
      } catch (error) {
        logger.warn(
          { endpointId: endpoint.id, error: redactError(error) },
          "GitHub webhook could not be durably authenticated",
        );
        return retryableGitHubWebhookResponse();
      }
      if (staged.kind === "invalid_signature")
        return new Response("Invalid signature", { status: 401 });
      if (staged.kind === "ignored")
        return new Response("ignored", { status: 200 });
      recordChatWebhookReceipt(endpoint.id, staged.actionId, "github_ingress");

      if (options.deferWebhookProcessing === true) {
        scheduleMessageProcessing(async () => {
          await processGitHubWebhookIngress(staged.actionId);
        });
        return githubIngressAcceptedResponse();
      }

      const processing = processGitHubWebhookIngress(staged.actionId, true);
      const tracked = processing.then(
        () => undefined,
        () => undefined,
      );
      backgroundMessageTasks.add(tracked);
      void tracked.finally(() => backgroundMessageTasks.delete(tracked));
      const outcome = await completeGitHubPreflightBeforeDeadline(processing);
      return outcome.completed
        ? (outcome.value ?? githubIngressAcceptedResponse())
        : githubIngressAcceptedResponse();
    }
    if (provider === "slack" && endpoint.providerAccountId) {
      const inspection = request.clone();
      const body = await inspection.text();
      const credentials = await resolveCredentials(endpoint);
      if (
        slackRequestSignatureIsValid(
          inspection,
          body,
          credentials.signingSecret,
        )
      ) {
        const incomingWorkspaceId = slackRequestWorkspaceId(
          body,
          inspection.headers.get("content-type") ?? "",
        );
        if (
          incomingWorkspaceId &&
          incomingWorkspaceId !== endpoint.providerAccountId
        ) {
          // A Slack Request URL can be copied to another app/workspace. Even a
          // correctly signed callback belongs only to the bot identity verified
          // for this endpoint, so acknowledge foreign traffic without letting
          // it reach SDK callbacks, delivery admission, principals, or lifecycle.
          return new Response("ignored", { status: 200 });
        }
      }
    }
    if (provider === "github") {
      const inspection = request.clone();
      const body = await inspection.text();
      const signature = inspection.headers.get("x-hub-signature-256");
      const eventType = inspection.headers.get("x-github-event");
      if (!replayingDurableGitHubIngress)
        await options.githubWebhookAuthenticationBarrier?.();
      // GitHub sends this signed connectivity check as soon as an App webhook
      // is saved, before the operator can generate a private key and submit
      // the App identity to Paperclip. Authenticating the ping needs only the
      // Paperclip-generated webhook secret; initializing the full provider
      // runtime here would incorrectly reject the valid setup check because
      // App API credentials are not available yet.
      if (eventType === "ping") {
        let verifiedAttempt:
          | { completed: true; value: boolean }
          | { completed: false; value?: never };
        const verification = withCredentialMutationLease(
          endpoint,
          async (credentialLease): Promise<boolean> => {
            const current = await endpointRecord(endpoint.id);
            if (
              !current ||
              current.endpoint.provider !== "github" ||
              !matchesGitHubIngressFence(runtimeContextForRecord(current)) ||
              ["archived", "paused", "revoked"].includes(
                current.endpoint.status,
              )
            )
              return false;
            const credentials = await resolveCredentials(current.endpoint);
            const expected = `sha256=${createHmac("sha256", credentials.webhookSecret).update(body).digest("hex")}`;
            let valid = false;
            try {
              valid =
                typeof signature === "string" &&
                timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
            } catch {
              valid = false;
            }
            if (!valid) return false;
            const verifiedAt = new Date();
            await db.transaction(async (tx) => {
              // Bind the verified receipt to the same lease and secret that
              // authenticated it. A reclaimed lease cannot commit a stale
              // webhook verification after secret rotation or reconnect.
              await credentialLease.assertOwned(tx);
              await tx
                .update(chatEndpoints)
                .set({
                  setup: {
                    ...current.endpoint.setup,
                    webhookVerifiedAt: verifiedAt.toISOString(),
                  },
                  healthMessage: "GitHub webhook verified",
                  updatedAt: verifiedAt,
                })
                .where(eq(chatEndpoints.id, endpoint.id));
              await logActivity(tx as unknown as Db, {
                companyId: current.endpoint.companyId,
                actorType: "system",
                actorId: "github-webhook",
                action: "chat_endpoint.webhook_verified",
                entityType: "tool_connection",
                entityId: current.endpoint.connectionId,
                details: {
                  endpointId: current.endpoint.id,
                  provider: "github",
                  providerDeliveryId:
                    inspection.headers.get("x-github-delivery") ?? null,
                },
              });
              await credentialLease.assertOwned(tx);
            });
            return true;
          },
        );
        try {
          verifiedAttempt =
            await completeGitHubPreflightBeforeDeadline(verification);
        } catch (error) {
          logger.warn(
            { endpointId: endpoint.id, error: redactError(error) },
            "GitHub ping authentication failed before durable verification",
          );
          return retryableGitHubWebhookResponse();
        }
        if (!verifiedAttempt.completed) {
          // This path is reachable only for the private durable worker. The
          // public request has already committed its authenticated receipt.
          void verification.catch((error) => {
            logger.warn(
              { endpointId: endpoint.id, error: redactError(error) },
              "timed-out GitHub ping authentication later failed",
            );
          });
          return retryableGitHubWebhookResponse();
        }
        const verified = verifiedAttempt.value;
        return verified
          ? new Response("pong", { status: 200 })
          : new Response("Invalid signature", { status: 401 });
      }
      const preflightTask = withCredentialMutationLease(
        endpoint,
        async (
          credentialLease,
        ): Promise<"accepted" | "ignored" | "invalid_signature"> => {
          // The repository upsert below is a Paperclip mutation derived from
          // the webhook credential. Re-read and authenticate while holding the
          // same lease as rotation/reconnect/removal so a callback signed with
          // an obsolete secret cannot reopen a quarantined repository in the
          // resolve-secret -> persist-resource race window.
          const current = await endpointRecord(endpoint.id);
          if (
            !current ||
            current.endpoint.provider !== "github" ||
            !matchesGitHubIngressFence(runtimeContextForRecord(current)) ||
            current.endpoint.status === "archived" ||
            current.endpoint.status === "paused" ||
            (current.endpoint.status === "revoked" &&
              eventType !== "installation")
          ) {
            return "ignored";
          }
          const credentials = await resolveCredentials(current.endpoint);
          const expected = `sha256=${createHmac("sha256", credentials.webhookSecret).update(body).digest("hex")}`;
          let signatureValid = false;
          try {
            signatureValid =
              typeof signature === "string" &&
              timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
          } catch {
            signatureValid = false;
          }
          if (!signatureValid) return "invalid_signature";

          let payload: {
            installation?: { id?: unknown };
            repository?: unknown;
          } | null = null;
          try {
            payload = JSON.parse(body) as {
              installation?: { id?: unknown };
              repository?: unknown;
            };
          } catch {
            // Let the native adapter return its normal invalid-JSON response.
          }
          if (payload) {
            const incomingInstallationId = payload.installation?.id;
            if (
              incomingInstallationId !== undefined &&
              String(incomingInstallationId) !== credentials.installationId &&
              eventType !== "installation"
            ) {
              // A dedicated endpoint represents exactly one GitHub App
              // installation. GitHub sends every installation's events to the
              // App webhook, so acknowledge foreign signed traffic without
              // admitting it to Paperclip or prompting endless redelivery.
              // Installation lifecycle events are the one exception: even when
              // their id differs, canonical App inventory under the lifecycle
              // lease must decide whether this is a valid sole-installation
              // replacement or a second active installation that quarantines
              // the endpoint.
              return "ignored";
            }
            await reconcileGitHubWebhookRepository(
              current.endpoint,
              payload,
              credentialLease,
            );
          }
          return "accepted";
        },
      );
      let preflightAttempt:
        | {
            completed: true;
            value: "accepted" | "ignored" | "invalid_signature";
          }
        | { completed: false; value?: never };
      try {
        preflightAttempt =
          await completeGitHubPreflightBeforeDeadline(preflightTask);
      } catch (error) {
        logger.warn(
          { endpointId: endpoint.id, error: redactError(error) },
          "GitHub webhook authentication failed before durable acceptance",
        );
        return retryableGitHubWebhookResponse();
      }
      if (!preflightAttempt.completed) {
        void preflightTask.catch((error) => {
          logger.warn(
            { endpointId: endpoint.id, error: redactError(error) },
            "timed-out GitHub webhook authentication later failed",
          );
        });
        return retryableGitHubWebhookResponse();
      }
      const preflight = preflightAttempt.value;
      if (preflight === "ignored") {
        return new Response("ignored", { status: 200 });
      }
      if (preflight === "invalid_signature") {
        return new Response("Invalid signature", { status: 401 });
      }
    }
    const lifecycleInspection = request.clone();
    const slackCallbackInspection =
      provider === "slack" ? request.clone() : null;
    const githubInspection = provider === "github" ? request.clone() : null;
    recordChatWebhookStage("runtime_requested");
    const runtimePromise = runtimeFor(endpoint);
    let endpointRuntime: ChatSdkEndpointRuntime;
    if (githubResponseDeadlineAt !== null) {
      let timeout: ReturnType<typeof setTimeout> | null = null;
      try {
        const outcome = await Promise.race([
          runtimePromise.then((value) => ({ completed: true as const, value })),
          new Promise<{ completed: false; value?: never }>((resolve) => {
            timeout = setTimeout(
              () => resolve({ completed: false }),
              Math.max(0, githubResponseDeadlineAt - Date.now()),
            );
            timeout.unref?.();
          }),
        ]);
        if (!outcome.completed) {
          return retryableGitHubWebhookResponse();
        }
        endpointRuntime = outcome.value;
      } catch (error) {
        logger.warn(
          { endpointId: endpoint.id, error: redactError(error) },
          "GitHub runtime initialization failed before durable webhook receipt",
        );
        return retryableGitHubWebhookResponse();
      } finally {
        if (timeout) clearTimeout(timeout);
      }
    } else {
      endpointRuntime = await runtimePromise;
    }
    recordChatWebhookStage("runtime_ready");
    const runtimeContext = runtimeContexts.get(endpointRuntime as object);
    if (!runtimeContext) {
      throw conflict("Chat endpoint runtime is not current", {
        code: "chat_endpoint_runtime_superseded",
      });
    }
    // runtimeFor can return a newer instance than the leased preflight saw.
    // Keep the exact staged epoch; callbacks on a matching instance retain
    // their normal transactional fences if a pause wins after this check.
    if (!matchesGitHubIngressFence(runtimeContext))
      return ignoreSupersededIngress();
    const response = await endpointRuntime.handleWebhook(
      request,
      undefined,
      githubResponseDeadlineAt ?? undefined,
      provider === "telegram" ? serviceReceivedAtMs : undefined,
    );
    let lifecyclePayload: unknown = null;
    if (response.ok) {
      try {
        const contentType =
          lifecycleInspection.headers.get("content-type") ?? "";
        if (contentType.includes("application/json"))
          lifecyclePayload = await lifecycleInspection.json();
      } catch {
        // The native adapter remains authoritative for non-JSON callback
        // envelopes such as Slack slash commands.
      }
    }
    if (
      response.ok &&
      lifecyclePayload &&
      endpointRuntime.acceptsProviderScope(lifecyclePayload)
    ) {
      if (endpoint.provider === "slack") {
        const stop = parseSlackSessionStop(
          lifecyclePayload,
          endpoint.providerAccountId,
        );
        if (stop) {
          const actionId = await stageSlackSessionStop(
            endpoint,
            stop,
            runtimeContext,
          );
          if (actionId) {
            if (options.deferWebhookProcessing === true) {
              scheduleMessageProcessing(() =>
                processSlackSessionStop(actionId),
              );
            } else {
              await processSlackSessionStop(actionId);
            }
          }
        }
      }
      const effects = parseChatProviderLifecycle({
        provider: endpoint.provider,
        headers: lifecycleInspection.headers,
        payload: lifecyclePayload,
        botExternalId: endpoint.botExternalId,
      });
      // Provider success is returned only after every recognized lifecycle
      // transition is durable. A persistence failure therefore becomes a
      // non-2xx webhook response and asks the provider to retry.
      await applyProviderLifecycleEffects(endpoint, effects, runtimeContext);
    }
    if (slackCallbackInspection && response.ok) {
      const callback = await inspectSlackCallback(slackCallbackInspection);
      if (callback) {
        await db.transaction(async (tx) => {
          const current = await runtimeCallbackEndpoint(
            tx,
            endpoint.id,
            runtimeContext,
            ["verifying", "active"],
          );
          if (!current) return;
          const observedAt = new Date();
          const currentSetup = current.setup as InternalSetupState;
          await tx
            .update(chatEndpoints)
            .set({
              setup: {
                ...currentSetup,
                ...(callback.isUrlVerification
                  ? { webhookVerifiedAt: observedAt.toISOString() }
                  : {}),
                slackCallbackSurfaces: {
                  ...currentSetup.slackCallbackSurfaces,
                  [callback.surface]: {
                    url: callback.url,
                    observedAt: observedAt.toISOString(),
                  },
                },
              } as InternalSetupState,
              ...(callback.isUrlVerification
                ? { healthMessage: "Slack Events Request URL verified" }
                : {}),
              updatedAt: observedAt,
            })
            .where(eq(chatEndpoints.id, endpoint.id));
        });
      }
    }
    if (githubInspection && response.ok) {
      let lifecycle: GitHubLifecycleEvent | null = null;
      try {
        lifecycle = await githubLifecycleEventFromRequest(githubInspection);
      } catch {
        // Ignore only malformed or unsupported supplemental payloads. Once an
        // event is recognized, its durable persistence failure must escape.
      }
      if (lifecycle) {
        await recordLifecycleDelivery(
          {
            endpointId: endpoint.id,
            ...lifecycle,
          },
          runtimeContext,
        );
      }
    }
    if (provider === "telegram" && response.ok && lifecyclePayload) {
      const lifecycle = telegramLifecycleEventFromPayload(lifecyclePayload);
      if (lifecycle) {
        await recordLifecycleDelivery(
          {
            endpointId: endpoint.id,
            ...lifecycle,
          },
          runtimeContext,
        );
      }
    }
    if (
      provider === "microsoft-teams" &&
      response.ok &&
      lifecyclePayload &&
      endpointRuntime.acceptsProviderScope(lifecyclePayload)
    ) {
      const lifecycle = microsoftTeamsLifecycleEventFromPayload(
        lifecyclePayload,
        endpointRuntime,
      );
      if (lifecycle) {
        await recordLifecycleDelivery(
          {
            endpointId: endpoint.id,
            ...lifecycle,
          },
          runtimeContext,
        );
      }
    }
    return response;
  }

  function normalizedPendingReaction(delivery: DeliveryRow): {
    added: boolean;
    emoji: string;
    messageId: string;
    rawEmoji: string;
    runtimeContext: LifecycleRuntimeFence;
    threadId: string;
  } | null {
    if (
      delivery.eventKind !== "reaction_added" &&
      delivery.eventKind !== "reaction_removed"
    ) {
      return null;
    }
    const normalized = delivery.normalizedEvent;
    if (
      !normalized ||
      typeof normalized !== "object" ||
      Array.isArray(normalized)
    ) {
      return null;
    }
    const value = normalized as Record<string, unknown>;
    const conversation = value.conversation;
    const message = value.message;
    const reaction = value.reaction;
    const runtimeContext = lifecycleRuntimeFence(delivery);
    if (
      !conversation ||
      typeof conversation !== "object" ||
      Array.isArray(conversation) ||
      !message ||
      typeof message !== "object" ||
      Array.isArray(message) ||
      !reaction ||
      typeof reaction !== "object" ||
      Array.isArray(reaction) ||
      !runtimeContext
    ) {
      return null;
    }
    const threadId = (conversation as Record<string, unknown>).externalThreadId;
    const messageId = (message as Record<string, unknown>).providerMessageId;
    const reactionRecord = reaction as Record<string, unknown>;
    const added = reactionRecord.added;
    const emoji = reactionRecord.emoji;
    const rawEmoji = reactionRecord.rawEmoji;
    return typeof threadId === "string" &&
      threadId.length > 0 &&
      typeof messageId === "string" &&
      messageId.length > 0 &&
      typeof added === "boolean" &&
      added === (delivery.eventKind === "reaction_added") &&
      typeof emoji === "string" &&
      emoji.length > 0 &&
      typeof rawEmoji === "string" &&
      rawEmoji.length > 0
      ? { added, emoji, messageId, rawEmoji, runtimeContext, threadId }
      : null;
  }

  async function processPendingReactionDelivery(
    candidate: DeliveryRow,
  ): Promise<void> {
    const reaction = normalizedPendingReaction(candidate);
    if (!reaction || !candidate.principalId) {
      const now = new Date();
      await db
        .update(chatDeliveries)
        .set({
          state: "failed",
          nextAttemptAt: null,
          processedAt: now,
          redactedError: "Normalized reaction delivery is incomplete",
          updatedAt: now,
        })
        .where(
          and(
            eq(chatDeliveries.id, candidate.id),
            inArray(chatDeliveries.state, ["received", "retry"]),
          ),
        );
      return;
    }
    const principalId = candidate.principalId;

    await db.transaction(async (tx) => {
      const currentEndpoint = await runtimeCallbackEndpoint(
        tx,
        candidate.endpointId,
        reaction.runtimeContext,
        ["active"],
      );
      let conversation: ConversationRow | null = null;
      let disposition:
        | { kind: "processed"; conversationId: string }
        | { kind: "retry" }
        | { kind: "filtered"; reason: string };

      if (!currentEndpoint) {
        disposition = {
          kind: "filtered",
          reason: "Reaction callback belonged to an unavailable runtime",
        };
      } else {
        await options.reactionReplayEndpointLockBarrier?.();
        conversation = await lockReactionConversationForMessage(
          tx,
          currentEndpoint,
          reaction.threadId,
          reaction.messageId,
          "outbound",
        );
        if (conversation) {
          await options.reactionReplayConversationLockBarrier?.();
        }
        if (conversation) {
          disposition = (await authorizeReactionConversation(
            tx,
            currentEndpoint,
            conversation,
            principalId,
          ))
            ? { kind: "processed", conversationId: conversation.id }
            : {
                kind: "filtered",
                reason:
                  "Reaction destination or principal is no longer authorized",
              };
        } else {
          conversation = await lockStreamingReactionConversation(
            tx,
            currentEndpoint,
            reaction.threadId,
          );
          if (conversation) {
            await options.reactionReplayConversationLockBarrier?.();
          }
          if (!conversation) {
            disposition = {
              kind: "filtered",
              reason: "Reaction target was not linked to a sent message",
            };
          } else {
            disposition = (await authorizeReactionConversation(
              tx,
              currentEndpoint,
              conversation,
              principalId,
            ))
              ? { kind: "retry" }
              : {
                  kind: "filtered",
                  reason:
                    "Reaction destination or principal is no longer authorized",
                };
          }
        }
      }

      // Endpoint, conversation, destination and identity locks are acquired
      // before the delivery row so pause/revoke and replay use one lock order.
      const locked = await tx
        .select()
        .from(chatDeliveries)
        .where(
          and(
            eq(chatDeliveries.id, candidate.id),
            inArray(chatDeliveries.state, ["received", "retry"]),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      // Authorization locks may wait behind a concurrent lifecycle mutation.
      // Sample the expiry clock only after this delivery is exclusively held.
      const decisionAt = new Date();
      if (!locked || !deliveryReady(locked, decisionAt)) return;
      const lockedReaction = normalizedPendingReaction(locked);
      if (
        !lockedReaction ||
        lockedReaction.runtimeContext.generation !==
          reaction.runtimeContext.generation ||
        lockedReaction.runtimeContext.credentialFingerprint !==
          reaction.runtimeContext.credentialFingerprint
      ) {
        disposition = {
          kind: "filtered",
          reason: "Reaction delivery identity changed before replay",
        };
      }

      const nextAttempts = locked.attempts + 1;
      const expired =
        decisionAt.getTime() - locked.receivedAt.getTime() >=
        REACTION_LINK_MAX_AGE_MS;
      if (expired || locked.attempts >= REACTION_LINK_MAX_ATTEMPTS) {
        disposition = {
          kind: "filtered",
          reason: "Reaction target did not become linked before replay expiry",
        };
      }
      if (disposition.kind === "retry" && !expired) {
        if (nextAttempts < REACTION_LINK_MAX_ATTEMPTS) {
          const delay = Math.min(
            REACTION_LINK_RETRY_DELAY_MS *
              2 ** Math.min(Math.max(locked.attempts, 0), 5),
            REACTION_LINK_MAX_DELAY_MS,
          );
          await tx
            .update(chatDeliveries)
            .set({
              state: "retry",
              attempts: nextAttempts,
              nextAttemptAt: new Date(decisionAt.getTime() + delay),
              redactedError: "Waiting for the sent message link",
              updatedAt: decisionAt,
            })
            .where(
              and(
                eq(chatDeliveries.id, locked.id),
                eq(chatDeliveries.state, locked.state),
                eq(chatDeliveries.attempts, locked.attempts),
              ),
            );
          return;
        }
        disposition = {
          kind: "filtered",
          reason: "Reaction target did not become linked before retry expiry",
        };
      } else if (disposition.kind === "retry") {
        disposition = {
          kind: "filtered",
          reason: "Reaction target did not become linked before age expiry",
        };
      }

      const processedAt = new Date();
      await tx
        .update(chatDeliveries)
        .set(
          disposition.kind === "processed"
            ? {
                conversationId: disposition.conversationId,
                state: "processed",
                attempts: nextAttempts,
                nextAttemptAt: null,
                processedAt,
                redactedError: null,
                updatedAt: processedAt,
              }
            : {
                state: "filtered",
                attempts: nextAttempts,
                nextAttemptAt: null,
                processedAt,
                redactedError: disposition.reason,
                updatedAt: processedAt,
              },
        )
        .where(
          and(
            eq(chatDeliveries.id, locked.id),
            eq(chatDeliveries.state, locked.state),
            eq(chatDeliveries.attempts, locked.attempts),
          ),
        );
    });
  }

  async function processPendingReactionDeliveries(
    limit: number,
    onlyDeliveryId?: string,
  ): Promise<number> {
    const now = new Date();
    const candidates = await db
      .select()
      .from(chatDeliveries)
      .where(
        and(
          onlyDeliveryId ? eq(chatDeliveries.id, onlyDeliveryId) : undefined,
          inArray(chatDeliveries.eventKind, [
            "reaction_added",
            "reaction_removed",
          ]),
          or(
            and(
              eq(chatDeliveries.state, "received"),
              or(
                isNull(chatDeliveries.nextAttemptAt),
                lte(chatDeliveries.nextAttemptAt, now),
              ),
            ),
            and(
              eq(chatDeliveries.state, "retry"),
              or(
                isNull(chatDeliveries.nextAttemptAt),
                lte(chatDeliveries.nextAttemptAt, now),
              ),
            ),
          ),
        ),
      )
      .orderBy(asc(chatDeliveries.receivedAt), asc(chatDeliveries.id))
      .limit(limit);
    for (const candidate of candidates) {
      try {
        await processPendingReactionDelivery(candidate);
      } catch (error) {
        logger.warn(
          {
            endpointId: candidate.endpointId,
            deliveryId: candidate.id,
            error: redactError(error),
          },
          "chat reaction-link reconciliation failed",
        );
      }
    }
    return candidates.length;
  }

  /**
   * Reconcile a verified normalized delivery whose original request was
   * interrupted. Closed, credential-free provider descriptors reconstruct
   * authenticated attachment downloads through the endpoint runtime; unsafe
   * or no-longer-available files are omitted without losing the text turn.
   */
  async function processPendingDeliveries(limit = 25, onlyDeliveryId?: string) {
    await settleRejectedInboundWakeups(onlyDeliveryId);
    // Provider-visible effects that are not backed by a task publication use
    // chat_actions as their outbox. Reconcile them before inbound deliveries
    // so a crashed processing claim is quarantined before the delivery worker
    // could otherwise replay it.
    const actionRecovery = onlyDeliveryId
      ? null
      : Promise.allSettled([
          processPendingGitHubWebhookIngress(limit),
          processPendingProviderEffects(limit),
          processPendingReceiptReactions(limit),
          processPendingSlackSessionStops(limit),
          processPendingTelegramMaintenance(limit),
          // Slack task starts are an action-backed outbox. Queued work may
          // post once; provider-confirmed rows perform Paperclip-only
          // admission; a stale in-flight post is quarantined as unknown.
          processPendingSlackTaskStarts(limit),
          processFailedChatRunRetries(limit),
        ]);
    const reactionRecovery = processPendingReactionDeliveries(
      limit,
      onlyDeliveryId,
    ).catch((error) => {
      logger.warn(
        { error: redactError(error) },
        "chat reaction-link recovery selection failed",
      );
      return 0;
    });
    let ordinaryFailed = false;
    let ordinaryError: unknown = null;
    let rows: DeliveryRow[] = [];
    try {
      const now = new Date();
      const staleBefore = new Date(
        now.getTime() - DELIVERY_PROCESSING_STALE_MS,
      );
      rows = await db
        .select()
        .from(chatDeliveries)
        .where(
          and(
            onlyDeliveryId ? eq(chatDeliveries.id, onlyDeliveryId) : undefined,
            notInArray(chatDeliveries.eventKind, [
              "reaction_added",
              "reaction_removed",
            ]),
            or(
              and(
                eq(chatDeliveries.state, "processed"),
                pendingInboundWakeupCondition(true),
              ),
              and(
                eq(chatDeliveries.state, "received"),
                or(
                  isNull(chatDeliveries.nextAttemptAt),
                  lte(chatDeliveries.nextAttemptAt, now),
                ),
              ),
              and(
                eq(chatDeliveries.state, "retry"),
                or(
                  isNull(chatDeliveries.nextAttemptAt),
                  lte(chatDeliveries.nextAttemptAt, now),
                ),
              ),
              and(
                eq(chatDeliveries.state, "processing"),
                lte(chatDeliveries.updatedAt, staleBefore),
              ),
            ),
          ),
        )
        .orderBy(asc(chatDeliveries.receivedAt))
        .limit(limit);
      const conversations = new Set<string>();
      for (const delivery of rows) {
        const lifecycleEffect = normalizedLifecycleEffect(delivery);
        if (lifecycleEffect) {
          const record = await endpointRecord(delivery.endpointId);
          if (!record || record.endpoint.status === "archived") {
            await db
              .update(chatDeliveries)
              .set({
                state: "failed",
                redactedError: "Chat endpoint is no longer available",
                updatedAt: new Date(),
              })
              .where(eq(chatDeliveries.id, delivery.id));
            continue;
          }
          try {
            await applyProviderLifecycleEffect(
              record.endpoint,
              lifecycleEffect,
            );
          } catch (error) {
            logger.warn(
              {
                endpointId: delivery.endpointId,
                deliveryId: delivery.id,
                error: redactError(error),
              },
              "chat provider lifecycle retry failed",
            );
          }
          continue;
        }
        const externalThreadId = normalizedDeliveryThreadId(delivery);
        if (!externalThreadId) {
          await db
            .update(chatDeliveries)
            .set({
              state: "failed",
              redactedError: "Normalized delivery is incomplete",
              updatedAt: new Date(),
            })
            .where(eq(chatDeliveries.id, delivery.id));
          continue;
        }
        const key = conversationDrainKey(delivery.endpointId, externalThreadId);
        if (conversations.has(key)) continue;
        conversations.add(key);
        await drainConversationDeliveries(
          delivery.endpointId,
          externalThreadId,
        );
      }
    } catch (error) {
      ordinaryFailed = true;
      ordinaryError = error;
    }
    // Provider recovery runs independently so a slow Slack Web API request
    // cannot hold unrelated verified inbound messages behind it. Callers that
    // explicitly replay one delivery skip these global sweeps entirely.
    if (actionRecovery) await actionRecovery;
    const reactionCount = await reactionRecovery;
    if (ordinaryFailed) throw ordinaryError;
    return reactionCount + rows.length;
  }

  async function listResources(endpointId: string) {
    return db
      .select()
      .from(chatEndpointResources)
      .where(
        and(
          eq(chatEndpointResources.endpointId, endpointId),
          ne(chatEndpointResources.type, "direct_message"),
        ),
      )
      .orderBy(asc(chatEndpointResources.label));
  }

  async function replaceResources(
    endpointId: string,
    updates: Array<{ id: string; enabled: boolean }>,
    actorUserId?: string | null,
  ) {
    const initial = await endpointRecord(endpointId);
    if (!initial) throw notFound("Chat endpoint not found");
    if (updates.length === 0) return listResources(endpointId);
    await withCredentialMutationLease(
      initial.endpoint,
      async (credentialLease) => {
        const ids = updates.map((entry) => entry.id);
        const publications: ActivityPublication[] = [];
        await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const [endpoint] = await tx
            .select({
              companyId: chatEndpoints.companyId,
              connectionId: chatEndpoints.connectionId,
              provider: chatEndpoints.provider,
            })
            .from(chatEndpoints)
            .where(
              and(
                eq(chatEndpoints.id, endpointId),
                eq(chatEndpoints.companyId, initial.endpoint.companyId),
              ),
            )
            .for("no key update");
          if (!endpoint) throw notFound("Chat endpoint not found");
          const rows = await tx
            .select({
              id: chatEndpointResources.id,
              availability: chatEndpointResources.availability,
              enabled: chatEndpointResources.enabled,
            })
            .from(chatEndpointResources)
            .where(
              and(
                eq(chatEndpointResources.companyId, endpoint.companyId),
                eq(chatEndpointResources.endpointId, endpointId),
                inArray(chatEndpointResources.id, ids),
              ),
            )
            .orderBy(asc(chatEndpointResources.id))
            .for("no key update");
          if (rows.length !== new Set(ids).size)
            throw unprocessable("Every resource must belong to this endpoint");
          const availabilityById = new Map(
            rows.map((row) => [row.id, row.availability]),
          );
          // Validate every submitted grant, including intermediate duplicate
          // entries. Netting below describes the audit, not new authority.
          const unavailable = updates.find(
            (entry) =>
              entry.enabled && availabilityById.get(entry.id) !== "available",
          );
          if (unavailable)
            throw conflict(
              "A destination must still be available from the provider before it can be enabled",
              { code: "chat_resource_unavailable", resourceId: unavailable.id },
            );
          const finalEnabled = new Map(
            updates.map((entry) => [entry.id, entry.enabled]),
          );
          const changes = rows
            .filter((row) => row.enabled !== finalEnabled.get(row.id))
            .map((row) => ({
              resourceId: row.id,
              before: { enabled: row.enabled },
              after: { enabled: finalEnabled.get(row.id)! },
            }));
          for (const entry of updates)
            await tx
              .update(chatEndpointResources)
              .set({ enabled: entry.enabled, updatedAt: new Date() })
              .where(
                and(
                  eq(chatEndpointResources.companyId, endpoint.companyId),
                  eq(chatEndpointResources.endpointId, endpointId),
                  eq(chatEndpointResources.id, entry.id),
                ),
              );
          if (changes.length > 0)
            await logActivity(
              tx as unknown as Db,
              {
                companyId: endpoint.companyId,
                actorType: "user",
                actorId: actorUserId ?? "board",
                action: "chat_endpoint.resources_updated",
                entityType: "tool_connection",
                entityId: endpoint.connectionId,
                details: { endpointId, provider: endpoint.provider, changes },
              },
              publications,
            );
          await credentialLease.assertOwned(tx);
        });
        // A committed reach change is factual even if the outer lease's last
        // check subsequently fails. Never publish an uncommitted activity.
        for (const publication of publications) publishActivity(publication);
      },
    );
    return listResources(endpointId);
  }

  async function listPrincipals(endpointId: string) {
    const record = await endpointRecord(endpointId);
    if (!record) throw notFound("Chat endpoint not found");
    const principals = await db
      .select()
      .from(chatExternalPrincipals)
      .where(
        and(
          eq(chatExternalPrincipals.companyId, record.endpoint.companyId),
          eq(chatExternalPrincipals.provider, record.endpoint.provider),
          eq(
            chatExternalPrincipals.providerAccountId,
            record.endpoint.providerAccountId ?? "unknown",
          ),
        ),
      )
      .orderBy(asc(chatExternalPrincipals.displayName));
    const links = await db
      .select()
      .from(chatIdentityLinks)
      .where(eq(chatIdentityLinks.endpointId, endpointId));
    const userIds = links.flatMap((link) =>
      link.paperclipUserId ? [link.paperclipUserId] : [],
    );
    const users = userIds.length
      ? await db
          .select({
            id: authUsers.id,
            name: authUsers.name,
            email: authUsers.email,
          })
          .from(authUsers)
          .where(inArray(authUsers.id, userIds))
      : [];
    const linkByPrincipal = new Map(
      links.map((link) => [link.principalId, link]),
    );
    const userById = new Map(users.map((user) => [user.id, user]));
    return principals.map((principal) => {
      const link = linkByPrincipal.get(principal.id);
      const user = link?.paperclipUserId
        ? userById.get(link.paperclipUserId)
        : null;
      return {
        id: link?.id ?? principal.id,
        principalId: principal.id,
        externalLabel:
          principal.displayName ?? principal.handle ?? principal.externalId,
        externalDetail: principal.handle
          ? `@${principal.handle.replace(/^@/, "")}`
          : principal.externalId,
        paperclipUserId: link?.paperclipUserId ?? null,
        paperclipUserLabel: user?.name ?? user?.email ?? null,
        status: link?.status ?? "pending",
      };
    });
  }

  async function createLinkIntent(
    endpointId: string,
    principalId: string,
    expiresInSeconds: number,
  ) {
    const record = await endpointRecord(endpointId);
    if (!record) throw notFound("Chat endpoint not found");
    const principal = await db
      .select()
      .from(chatExternalPrincipals)
      .where(
        and(
          eq(chatExternalPrincipals.companyId, record.endpoint.companyId),
          eq(chatExternalPrincipals.id, principalId),
          eq(chatExternalPrincipals.provider, record.endpoint.provider),
          eq(
            chatExternalPrincipals.providerAccountId,
            record.endpoint.providerAccountId ?? "",
          ),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!principal) throw notFound("External identity not found");
    if (principal.isBot || principal.kind !== "user") {
      throw unprocessable("Only a human external identity can be linked");
    }
    const token = randomBytes(32).toString("base64url");
    const tokenHash = createHash("sha256").update(token).digest("hex");
    const expiresAt = new Date(Date.now() + expiresInSeconds * 1000);
    await db.transaction(async (tx) => {
      await tx.execute(
        sql`select pg_advisory_xact_lock(hashtextextended(${`chat-identity:${record.endpoint.companyId}:${principalId}`}, 0))`,
      );
      const existingLink = await tx
        .select({ status: chatIdentityLinks.status })
        .from(chatIdentityLinks)
        .where(
          and(
            eq(chatIdentityLinks.endpointId, endpointId),
            eq(chatIdentityLinks.principalId, principalId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (existingLink?.status === "linked") {
        throw conflict("This external identity is already linked", {
          code: "chat_identity_already_linked",
        });
      }
      await tx
        .insert(chatIdentityLinks)
        .values({
          companyId: record.endpoint.companyId,
          endpointId,
          principalId,
          status: "pending",
          confirmationTokenHash: tokenHash,
          expiresAt,
        })
        .onConflictDoUpdate({
          target: [chatIdentityLinks.endpointId, chatIdentityLinks.principalId],
          set: {
            paperclipUserId: null,
            status: "pending",
            confirmationTokenHash: tokenHash,
            expiresAt,
            confirmedAt: null,
            revokedAt: null,
            updatedAt: new Date(),
          },
        });
    });
    const path = `/chat-identity/confirm?token=${encodeURIComponent(token)}`;
    return {
      confirmationUrl: publicBaseUrl ? `${publicBaseUrl}${path}` : path,
      expiresAt: expiresAt.toISOString(),
    };
  }

  async function previewIdentityLink(token: string) {
    const tokenHash = createHash("sha256").update(token).digest("hex");
    const row = await db
      .select({
        link: chatIdentityLinks,
        principal: chatExternalPrincipals,
        endpoint: chatEndpoints,
        companyName: companies.name,
        companyPrefix: companies.issuePrefix,
      })
      .from(chatIdentityLinks)
      .innerJoin(
        chatExternalPrincipals,
        and(
          eq(chatExternalPrincipals.companyId, chatIdentityLinks.companyId),
          eq(chatExternalPrincipals.id, chatIdentityLinks.principalId),
        ),
      )
      .innerJoin(
        chatEndpoints,
        and(
          eq(chatEndpoints.companyId, chatIdentityLinks.companyId),
          eq(chatEndpoints.id, chatIdentityLinks.endpointId),
        ),
      )
      .innerJoin(companies, eq(companies.id, chatIdentityLinks.companyId))
      .where(
        and(
          eq(chatIdentityLinks.confirmationTokenHash, tokenHash),
          eq(chatIdentityLinks.status, "pending"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!row || !row.link.expiresAt || row.link.expiresAt <= new Date()) {
      throw unprocessable("This identity-link request is invalid or expired");
    }
    return {
      endpointId: row.endpoint.id,
      companyId: row.endpoint.companyId,
      companyName: row.companyName,
      companyPrefix: row.companyPrefix,
      provider: row.endpoint.provider,
      providerAccountLabel: row.endpoint.providerAccountLabel,
      botLabel: row.endpoint.botDisplayName,
      externalLabel:
        row.principal.displayName ??
        row.principal.handle ??
        row.principal.externalId,
      externalDetail: row.principal.handle
        ? `@${row.principal.handle.replace(/^@/, "")}`
        : row.principal.externalId,
      expiresAt: row.link.expiresAt.toISOString(),
    };
  }

  async function confirmIdentityLink(token: string, paperclipUserId: string) {
    const tokenHash = createHash("sha256").update(token).digest("hex");
    const link = await db
      .select()
      .from(chatIdentityLinks)
      .where(
        and(
          eq(chatIdentityLinks.confirmationTokenHash, tokenHash),
          eq(chatIdentityLinks.status, "pending"),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!link || !link.expiresAt || link.expiresAt <= new Date())
      throw unprocessable("This identity-link request is invalid or expired");
    const confirmed = await db.transaction(async (tx) => {
      await tx.execute(
        sql`select pg_advisory_xact_lock(hashtextextended(${`chat-identity:${link.companyId}:${link.principalId}`}, 0))`,
      );
      const currentLink = await tx
        .select({
          id: chatIdentityLinks.id,
          companyId: chatIdentityLinks.companyId,
          endpointId: chatIdentityLinks.endpointId,
          principalId: chatIdentityLinks.principalId,
          expiresAt: chatIdentityLinks.expiresAt,
        })
        .from(chatIdentityLinks)
        .where(
          and(
            eq(chatIdentityLinks.id, link.id),
            eq(chatIdentityLinks.status, "pending"),
            eq(chatIdentityLinks.confirmationTokenHash, tokenHash),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const now = new Date();
      if (
        !currentLink ||
        !currentLink.expiresAt ||
        currentLink.expiresAt <= now
      ) {
        return null;
      }
      const membership = await tx
        .select({ status: companyMemberships.status })
        .from(companyMemberships)
        .where(
          and(
            eq(companyMemberships.companyId, currentLink.companyId),
            eq(companyMemberships.principalType, "user"),
            eq(companyMemberships.principalId, paperclipUserId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (membership?.status !== "active") {
        throw forbidden(
          "The signed-in Paperclip account is not a member of this company",
        );
      }
      const conflictingLink = await tx
        .select({
          id: chatIdentityLinks.id,
          paperclipUserId: chatIdentityLinks.paperclipUserId,
        })
        .from(chatIdentityLinks)
        .where(
          and(
            eq(chatIdentityLinks.companyId, link.companyId),
            eq(chatIdentityLinks.principalId, link.principalId),
            eq(chatIdentityLinks.status, "linked"),
            ne(chatIdentityLinks.paperclipUserId, paperclipUserId),
          ),
        )
        .limit(1)
        .then((rows) => rows[0] ?? null);
      if (conflictingLink) {
        throw conflict(
          "This provider identity is linked to a different Paperclip account",
          {
            code: "chat_identity_link_conflict",
          },
        );
      }
      return tx
        .update(chatIdentityLinks)
        .set({
          paperclipUserId,
          status: "linked",
          confirmationTokenHash: null,
          confirmedAt: now,
          updatedAt: now,
        })
        .where(
          and(
            eq(chatIdentityLinks.id, link.id),
            eq(chatIdentityLinks.status, "pending"),
            eq(chatIdentityLinks.confirmationTokenHash, tokenHash),
            gt(chatIdentityLinks.expiresAt, now),
          ),
        )
        .returning({ endpointId: chatIdentityLinks.endpointId })
        .then((rows) => rows[0] ?? null);
    });
    if (!confirmed) {
      throw conflict("This identity-link request was already used or expired", {
        code: "chat_identity_link_consumed",
      });
    }
    return { ok: true, endpointId: confirmed.endpointId };
  }

  async function revokeLink(endpointId: string, principalId: string) {
    const link = await db
      .select({ companyId: chatIdentityLinks.companyId })
      .from(chatIdentityLinks)
      .where(
        and(
          eq(chatIdentityLinks.endpointId, endpointId),
          eq(chatIdentityLinks.principalId, principalId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!link) throw notFound("Identity link not found");
    const revoked = await db.transaction(async (tx) => {
      await tx.execute(
        sql`select pg_advisory_xact_lock(hashtextextended(${`chat-identity:${link.companyId}:${principalId}`}, 0))`,
      );
      return tx
        .update(chatIdentityLinks)
        .set({
          paperclipUserId: null,
          status: "revoked",
          confirmationTokenHash: null,
          revokedAt: new Date(),
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatIdentityLinks.companyId, link.companyId),
            eq(chatIdentityLinks.endpointId, endpointId),
            eq(chatIdentityLinks.principalId, principalId),
          ),
        )
        .returning({ id: chatIdentityLinks.id })
        .then((rows) => rows[0] ?? null);
    });
    if (!revoked) throw notFound("Identity link not found");
  }

  async function listConversations(endpointId: string) {
    const record = await endpointRecord(endpointId);
    if (!record) throw notFound("Chat endpoint not found");
    const conversations = await db
      .select()
      .from(chatConversations)
      .where(eq(chatConversations.endpointId, endpointId))
      .orderBy(
        desc(chatConversations.lastActivityAt),
        desc(chatConversations.createdAt),
      );
    if (!conversations.length) return [];
    const issueRows = await db
      .select({
        id: issues.id,
        identifier: issues.identifier,
        title: issues.title,
        status: issues.status,
        updatedAt: issues.updatedAt,
      })
      .from(issues)
      .where(
        inArray(
          issues.id,
          conversations.map((row) => row.issueId),
        ),
      );
    const publications = await db
      .select()
      .from(chatPublications)
      .where(eq(chatPublications.endpointId, endpointId))
      .orderBy(desc(chatPublications.createdAt));
    const issueById = new Map(issueRows.map((row) => [row.id, row]));
    const lastPublication = new Map<
      string,
      typeof chatPublications.$inferSelect
    >();
    for (const publication of publications)
      if (!lastPublication.has(publication.conversationId))
        lastPublication.set(publication.conversationId, publication);
    return conversations.map((conversation) => {
      const issue = issueById.get(conversation.issueId);
      const externalUrl =
        record.endpoint.provider === "telegram" && conversation.isDirectMessage
          ? chatProviderConversationUrl({
              provider: "telegram",
              botUsername: record.endpoint.botUsername,
              threadId: conversation.externalThreadId,
              providerMessageId: "",
              raw: { chat: { type: "private" } },
            })
          : (conversation.providerUrl ??
            (record.endpoint.provider === "slack"
              ? chatProviderConversationUrl({
                  provider: "slack",
                  providerAccountId: record.endpoint.providerAccountId,
                  threadId: conversation.externalThreadId,
                  providerMessageId: "",
                })
              : null));
      return {
        id: conversation.id,
        companyId: conversation.companyId,
        endpointId: conversation.endpointId,
        resourceId: conversation.resourceId,
        externalLabel: conversation.externalLabel,
        externalUrl,
        externalConversationId: conversation.externalConversationId,
        externalThreadId: conversation.externalThreadId,
        sessionGeneration: conversation.sessionGeneration,
        issueId: conversation.issueId,
        issueIdentifier: issue?.identifier ?? null,
        issueTitle: issue?.title ?? null,
        isDirectMessage: conversation.isDirectMessage,
        state:
          issue?.status === "done" || issue?.status === "cancelled"
            ? "completed"
            : conversation.state,
        lastActivityAt: conversation.lastActivityAt?.toISOString() ?? null,
        createdAt: conversation.createdAt.toISOString(),
        updatedAt: (
          conversation.lastActivityAt ?? conversation.updatedAt
        ).toISOString(),
        lastPublicationStatus:
          lastPublication.get(conversation.id)?.state ?? null,
      };
    });
  }

  async function listActivity(endpointId: string) {
    const recoveryIngress = alias(chatActions, "github_recovery_ingress");
    const [
      deliveries,
      publications,
      slashActions,
      providerEffects,
      githubIngressFailures,
      slackSessionActions,
      githubRecoveries,
      githubRecoveryScans,
    ] = await Promise.all([
      db
        .select()
        .from(chatDeliveries)
        .where(eq(chatDeliveries.endpointId, endpointId))
        .orderBy(desc(chatDeliveries.createdAt))
        .limit(100),
      db
        .select()
        .from(chatPublications)
        .where(eq(chatPublications.endpointId, endpointId))
        .orderBy(desc(chatPublications.createdAt))
        .limit(100),
      db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, endpointId),
            eq(chatActions.kind, "slash_task_start"),
          ),
        )
        .orderBy(desc(chatActions.createdAt))
        .limit(100),
      db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, endpointId),
            eq(chatActions.kind, "provider_effect"),
            eq(chatActions.status, "delivery_unknown"),
          ),
        )
        .orderBy(desc(chatActions.createdAt))
        .limit(100),
      db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, endpointId),
            eq(chatActions.kind, "github_webhook_ingress"),
            eq(chatActions.status, "failed"),
            sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'false'`,
          ),
        )
        .orderBy(desc(chatActions.createdAt))
        .limit(100),
      db
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, endpointId),
            inArray(chatActions.kind, [
              "slack_session_sync",
              "slack_session_stop",
            ]),
          ),
        )
        .orderBy(desc(chatActions.updatedAt))
        .limit(100),
      db
        .select({
          action: chatActions,
          ingressStatus: recoveryIngress.status,
        })
        .from(chatActions)
        .leftJoin(
          recoveryIngress,
          and(
            eq(recoveryIngress.companyId, chatActions.companyId),
            eq(recoveryIngress.endpointId, chatActions.endpointId),
            eq(recoveryIngress.kind, "github_webhook_ingress"),
            sql`${recoveryIngress.providerActionId} = 'github_webhook_ingress:' || (${chatActions.payload}#>>'{original,guid}')`,
          ),
        )
        .where(
          and(
            eq(chatActions.endpointId, endpointId),
            eq(chatActions.kind, "github_webhook_recovery"),
          ),
        )
        .orderBy(desc(chatActions.updatedAt))
        .limit(100),
      db
        .select()
        .from(chatSdkState)
        .where(
          and(
            eq(chatSdkState.endpointId, endpointId),
            eq(chatSdkState.stateKey, GITHUB_RECOVERY_STATE_KEY),
          ),
        )
        .limit(1),
    ]);
    const ambiguousProviderEffectDeliveryIds = new Set(
      providerEffects.flatMap((action) =>
        action.deliveryId ? [action.deliveryId] : [],
      ),
    );
    const transferRows = publications.length
      ? await db
          .select(fileTransferProjectionColumns)
          .from(chatTeamsFileTransfers)
          .innerJoin(
            chatPublications,
            and(
              eq(chatPublications.id, chatTeamsFileTransfers.publicationId),
              eq(chatPublications.companyId, chatTeamsFileTransfers.companyId),
              eq(
                chatPublications.endpointId,
                chatTeamsFileTransfers.endpointId,
              ),
              eq(
                chatPublications.conversationId,
                chatTeamsFileTransfers.conversationId,
              ),
            ),
          )
          .where(
            and(
              eq(chatTeamsFileTransfers.companyId, publications[0]!.companyId),
              eq(chatTeamsFileTransfers.endpointId, endpointId),
              inArray(
                chatTeamsFileTransfers.publicationId,
                publications.map((row) => row.id),
              ),
            ),
          )
      : [];
    const transfers = new Map(
      transferRows.map((row) => [row.publicationId, row]),
    );
    const cancellableConflicts = new Map<string, number>();
    for (const transfer of transferRows) {
      if (transfer.phase !== "conflict") continue;
      const publication = publications.find(
        (row) => row.id === transfer.publicationId,
      );
      if (!publication?.conversationId) continue;
      if (
        await teamsTransferProtocol().canCancelConflict({
          companyId: publication.companyId,
          endpointId,
          conversationId: publication.conversationId,
          publicationId: publication.id,
          version: transfer.version,
        })
      )
        cancellableConflicts.set(publication.id, transfer.version);
    }
    return [
      ...deliveries.map((row) => {
        const normalized =
          row.normalizedEvent &&
          typeof row.normalizedEvent === "object" &&
          !Array.isArray(row.normalizedEvent)
            ? (row.normalizedEvent as Record<string, unknown>)
            : {};
        const deduplication =
          normalized.deduplication &&
          typeof normalized.deduplication === "object" &&
          !Array.isArray(normalized.deduplication)
            ? (normalized.deduplication as Record<string, unknown>)
            : null;
        const duplicateCount =
          typeof deduplication?.duplicateCount === "number"
            ? deduplication.duplicateCount
            : 0;
        const label = row.eventKind.replaceAll("_", " ");
        const outcome =
          row.state === "filtered"
            ? "ignored"
            : row.state === "processed"
              ? "processed"
              : row.state;
        return {
          id: row.id,
          kind: "delivery" as const,
          status: row.state,
          summary: `${label} ${outcome}${duplicateCount ? ` · ${duplicateCount} duplicate${duplicateCount === 1 ? "" : "s"} ignored` : ""}`,
          detail: row.redactedError,
          createdAt: row.createdAt.toISOString(),
          replayable:
            row.state === "failed" &&
            Boolean(row.conversationId) &&
            !ambiguousProviderEffectDeliveryIds.has(row.id),
          resolutionActions: [],
        };
      }),
      ...publications.map((row) => {
        const transfer = transfers.get(row.id);
        const projected = projectChatFileTransfer(
          publicationSummary(row),
          transfer,
        );
        const payload = row.payload as Partial<SafeChatPublicationPayload>;
        const summary = payload.progressState
          ? `${payload.progressState.replaceAll("_", " ")} update`
          : payload.interactionId
            ? "Interactive question"
            : "Response to external conversation";
        return {
          id: row.id,
          kind: "publication" as const,
          status: projected.state,
          summary,
          detail: projected.redactedError ?? null,
          createdAt: row.createdAt.toISOString(),
          replayable: !transfer && row.state === "failed",
          ...(projected.fileTransfer
            ? { fileTransfer: projected.fileTransfer }
            : {}),
          resolutionActions: transfer
            ? chatFileTransferResolutionActions(
                projected,
                cancellableConflicts.has(row.id)
                  ? {
                      publicationId: row.id,
                      version: cancellableConflicts.get(row.id)!,
                    }
                  : undefined,
              )
            : row.state === "delivery_unknown"
              ? (["mark_delivered", "retry_anyway", "cancel"] as const)
              : [],
        };
      }),
      ...slashActions.map((row) => {
        const recovery = slackSlashTaskRecoveryPayload(row.payload);
        // Keep this GET read-only while still surfacing a crashed attempt as
        // actionable. The resolution POST persists the derived quarantine
        // before it applies the operator's audited decision.
        const status = slackTaskStartActivityStatus(row);
        return {
          id: row.id,
          kind: "action" as const,
          actionType: "slash_task_start" as const,
          status,
          summary: `Slack slash-command task start ${status.replaceAll("_", " ")}`,
          detail:
            status === "delivery_unknown"
              ? recovery
                ? "Slack may have accepted the task-start message, so Paperclip will not replay it automatically. Check Slack first; an explicit retry can create a duplicate starter message and task."
                : "Slack may have accepted the task-start message. This older action lacks the context required for a safe explicit retry, so check Slack and cancel it here before submitting a new command."
              : status === "provider_confirmed"
                ? "Slack accepted the task-start message. Paperclip is completing durable task admission without sending another Slack message."
                : status === "admitting"
                  ? "Slack accepted the task-start message. A Paperclip worker is admitting the task without replaying the Slack send."
                  : status === "failed"
                    ? "Slack rejected the task-start message. Submit the command again to retry."
                    : status === "cancelled"
                      ? "An operator cancelled this unconfirmed task start."
                      : null,
          createdAt: row.createdAt.toISOString(),
          replayable: false,
          resolutionActions:
            status === "delivery_unknown"
              ? recovery
                ? (["retry_anyway", "cancel"] as const)
                : (["cancel"] as const)
              : [],
        };
      }),
      ...providerEffects.map((row) => {
        const payload = providerEffectPayload(row.payload);
        return {
          id: row.id,
          kind: "action" as const,
          actionType: "provider_effect" as const,
          status: row.status,
          summary: "Provider reply delivery unknown",
          detail: payload?.completeConversationId
            ? "The provider may have accepted this reply, but Paperclip could not confirm it or close the task conversation. Check the provider first. Marking it delivered closes the conversation; retrying can create a duplicate message."
            : "The provider may have accepted this reply, but Paperclip could not confirm it. Check the provider first. Retrying can create a duplicate message.",
          createdAt: row.createdAt.toISOString(),
          replayable: false,
          resolutionActions: [
            "mark_delivered",
            "retry_anyway",
            "cancel",
          ] as const,
        };
      }),
      ...slackSessionActions.map((row) => {
        const isSync = row.kind === "slack_session_sync";
        const retrying =
          row.status === "received" &&
          row.result?.code === "slack_session_sync_retry";
        return {
          id: row.id,
          kind: "action" as const,
          actionType: isSync
            ? ("slack_session_sync" as const)
            : ("slack_session_stop" as const),
          status: retrying ? "retry" : row.status,
          summary: isSync ? "Slack session status" : "Slack Stop request",
          detail: isSync
            ? row.result?.outcome === "unavailable"
              ? "Slack has not enabled native session status for this destination. Message delivery continues."
              : row.result?.code === "slack_session_sync_rejected"
                ? "Slack rejected the session indicator update. Check app permissions and channel access; message delivery is tracked separately."
                : retrying
                  ? "The Slack session indicator is waiting to sync. Paperclip will not resend the response."
                  : row.result?.sessionStatus === "processing"
                    ? "Working status is refreshed automatically while the run remains active."
                    : null
            : row.status === "processed"
              ? "Paperclip stopped the work authorized by this request."
              : row.status === "cancelled"
                ? "No work was stopped: this request was no longer authorized or its target was no longer current."
                : row.status === "failed"
                  ? row.result?.retryable === true
                    ? "The Stop request could not finish yet. Paperclip will retry against the original work only."
                    : "The Stop request could not be completed. Check the task's current run before trying again."
                  : "Paperclip is processing this Stop request against its original task and run.",
          createdAt: row.updatedAt.toISOString(),
          replayable: false,
          resolutionActions: [],
        };
      }),
      ...githubIngressFailures.map((row) => {
        const deliveryId =
          typeof row.payload.deliveryId === "string"
            ? row.payload.deliveryId
            : null;
        return {
          id: row.id,
          kind: "action" as const,
          actionType: "github_webhook_ingress" as const,
          status: row.status,
          summary: "GitHub webhook could not be processed",
          detail: deliveryId
            ? `GitHub delivery ${deliveryId} was authenticated, but Paperclip could not finish processing it. Fix the connection or destination, then redeliver this delivery from the GitHub App's Recent Deliveries page.`
            : "An authenticated GitHub webhook could not be processed. Fix the connection or destination, then redeliver it from the GitHub App's Recent Deliveries page.",
          createdAt: row.createdAt.toISOString(),
          replayable: false,
          resolutionActions: [],
        };
      }),
      ...githubRecoveries.map(({ action: row, ingressStatus }) => ({
        id: row.id,
        kind: "repair" as const,
        status:
          row.status === "cancelled"
            ? "cancelled"
            : ingressStatus
              ? "received"
              : "pending",
        summary:
          row.status === "cancelled"
            ? "GitHub webhook recovery skipped"
            : ingressStatus
              ? "GitHub webhook received after recovery request"
              : "GitHub webhook redelivery requested",
        detail:
          row.status === "cancelled"
            ? row.result?.code === "source_changed_or_unavailable"
              ? "The original comment changed or is no longer available. Paperclip did not replay its old contents."
              : "This callback was not an eligible current user comment. Paperclip did not replay it."
            : ingressStatus
              ? "Paperclip received this callback. Its normal access checks and processing still apply."
              : "Paperclip asked GitHub to resend a recent missed message. This does not yet confirm receipt or a reply. Automatic requests are limited; if it remains unanswered, check the App's Recent Deliveries and send your request again in the current conversation.",
        createdAt: row.updatedAt.toISOString(),
        replayable: false,
        resolutionActions: [],
      })),
      ...githubRecoveryScans.flatMap((row) => {
        const value = row.value as { outcome?: string } | null;
        const detail =
          value?.outcome === "history_limit_reached"
            ? "Recent webhook volume exceeded automatic recovery's bounded scan. No partial history was replayed. Check the App's Recent Deliveries for missed messages."
            : value?.outcome === "callback_mismatch"
              ? "The GitHub App's callback no longer matches this connection. Reconnect the App to repair it; repository access will not change."
              : value?.outcome === "scan_failed"
                ? "Paperclip could not check GitHub's failed deliveries. The check will retry with backoff; normal callbacks are still processed."
                : null;
        return detail
          ? [
              {
                id: row.id,
                kind: "health" as const,
                status: "attention",
                summary: "GitHub webhook recovery needs attention",
                detail,
                createdAt: row.updatedAt.toISOString(),
                replayable: false,
                resolutionActions: [],
              },
            ]
          : [];
      }),
    ]
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
      .slice(0, 100);
  }

  async function replayDelivery(endpointId: string, deliveryId: string) {
    const delivery = await db
      .select()
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.endpointId, endpointId),
          eq(chatDeliveries.id, deliveryId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!delivery) throw notFound("Delivery not found");
    if (!delivery.conversationId)
      throw unprocessable(
        "Only a delivery already bound to a task can be replayed safely",
      );
    const ambiguousProviderEffect = await db
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.endpointId, endpointId),
          eq(chatActions.deliveryId, delivery.id),
          eq(chatActions.kind, "provider_effect"),
          eq(chatActions.status, "delivery_unknown"),
        ),
      )
      .limit(1)
      .then((rows) => rows[0] ?? null);
    if (ambiguousProviderEffect) {
      throw conflict(
        "Resolve the unconfirmed provider reply before replaying this delivery",
        {
          code: "chat_delivery_provider_effect_resolution_required",
        },
      );
    }
    if (delivery.state !== "failed") {
      throw conflict("Only a failed delivery can be replayed", {
        code: "chat_delivery_not_failed",
      });
    }
    await db.transaction(async (tx) => {
      const claimed = await tx
        .update(chatDeliveries)
        .set({
          state: "retry",
          nextAttemptAt: new Date(),
          redactedError: null,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatDeliveries.id, delivery.id),
            eq(chatDeliveries.state, "failed"),
            eq(chatDeliveries.attempts, delivery.attempts),
          ),
        )
        .returning({ id: chatDeliveries.id });
      if (!claimed.length) {
        throw conflict("This delivery is already being replayed", {
          code: "chat_delivery_replay_conflict",
        });
      }
      // The operator requested a fresh attempt at an input that never reached
      // scheduling. Preserve its immutable scope; acceptance rechecks the
      // original external actor and current reach before any admission.
      await tx
        .update(chatActions)
        .set({ status: "preparing", result: null, updatedAt: new Date() })
        .where(
          and(
            eq(chatActions.endpointId, endpointId),
            eq(chatActions.deliveryId, delivery.id),
            eq(chatActions.kind, "inbound_wakeup"),
            eq(chatActions.status, "failed"),
            sql`not exists (select 1 from ${agentWakeupRequests} where ${agentWakeupRequests.id} = ${chatActions.id})`,
          ),
        );
    });
    await processPendingDeliveries(1, delivery.id);
    const replayed = await db
      .select({ state: chatDeliveries.state })
      .from(chatDeliveries)
      .where(eq(chatDeliveries.id, delivery.id))
      .then((rows) => rows[0] ?? null);
    if (replayed?.state !== "processed") {
      throw conflict("The delivery replay did not complete", {
        code: "chat_delivery_replay_incomplete",
        state: replayed?.state ?? "missing",
      });
    }
  }

  async function replayPublication(endpointId: string, publicationId: string) {
    const publication = await db
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.endpointId, endpointId),
          eq(chatPublications.id, publicationId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!publication) throw notFound("Publication not found");
    if (publication.state !== "failed") {
      throw conflict("Only a failed publication can be replayed", {
        code:
          publication.state === "delivery_unknown"
            ? "chat_publication_resolution_required"
            : "chat_publication_not_replayable",
      });
    }
    const interactionId = publication.payload.interactionId;
    const isInteractionPrompt =
      Boolean(interactionId) &&
      publication.idempotencyKey ===
        `interaction:${interactionId}:${publication.endpointId}`;
    if (isInteractionPrompt) {
      if (!publication.issueId || !interactionId) {
        throw conflict(
          "This interaction prompt is missing its authoritative task binding and cannot be replayed safely",
          { code: "chat_terminal_interaction_publication_not_replayable" },
        );
      }
      const interaction = await db
        .select({ status: issueThreadInteractions.status })
        .from(issueThreadInteractions)
        .where(
          and(
            eq(issueThreadInteractions.id, interactionId),
            eq(issueThreadInteractions.companyId, publication.companyId),
            eq(issueThreadInteractions.issueId, publication.issueId),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (!interaction || interaction.status !== "pending") {
        throw conflict(
          "A resolved interaction prompt cannot be replayed into the provider",
          { code: "chat_terminal_interaction_publication_not_replayable" },
        );
      }
    }
    const claimed = await db.transaction(async (tx) => {
      const current = await tx
        .select()
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, publication.companyId),
            eq(chatPublications.endpointId, endpointId),
            eq(chatPublications.id, publication.id),
          ),
        )
        .for("update")
        .then((rows) => rows[0]);
      if (
        !current ||
        current.state !== publication.state ||
        current.attempts !== publication.attempts
      )
        return [];
      // Lock the publication before checking the transfer lane: issue() takes
      // the same lock, so a concurrent consent/upload cannot slip into replay.
      const transfer = await tx
        .select({ id: chatTeamsFileTransfers.id })
        .from(chatTeamsFileTransfers)
        .where(
          and(
            eq(chatTeamsFileTransfers.companyId, current.companyId),
            eq(chatTeamsFileTransfers.publicationId, current.id),
          ),
        )
        .then((rows) => rows[0]);
      if (transfer)
        throw conflict(
          "File delivery requires a stage-specific operator resolution",
          {
            code: "chat_file_transfer_resolution_required",
          },
        );
      return tx
        .update(chatPublications)
        .set({
          state: "retry",
          nextAttemptAt: new Date(),
          redactedError: null,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatPublications.id, publication.id),
            eq(chatPublications.state, publication.state),
            eq(chatPublications.attempts, publication.attempts),
          ),
        )
        .returning({ id: chatPublications.id });
    });
    if (!claimed.length) {
      throw conflict("This publication is already being replayed", {
        code: "chat_publication_replay_conflict",
      });
    }
    await processPendingPublications(1);
  }

  async function resolvePublication(
    endpointId: string,
    publicationId: string,
    action: "mark_delivered" | "retry_anyway" | "cancel",
    userId: string,
    fileTransfer?: {
      phase: import("@paperclipai/shared").ChatFileTransferPhase;
      version: number;
    },
  ) {
    const initialRecord = await endpointRecord(endpointId);
    if (!initialRecord) throw notFound("Chat endpoint not found");
    await withCredentialMutationLease(
      initialRecord.endpoint,
      (credentialLease) =>
        db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const publication = await tx
            .select()
            .from(chatPublications)
            .where(
              and(
                eq(chatPublications.endpointId, endpointId),
                eq(chatPublications.id, publicationId),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null);
          if (!publication) throw notFound("Publication not found");
          const transfer = await tx
            .select({
              id: chatTeamsFileTransfers.id,
              endpointId: chatTeamsFileTransfers.endpointId,
              conversationId: chatTeamsFileTransfers.conversationId,
              phase: chatTeamsFileTransfers.phase,
              version: chatTeamsFileTransfers.version,
            })
            .from(chatTeamsFileTransfers)
            .where(
              and(
                eq(chatTeamsFileTransfers.companyId, publication.companyId),
                eq(chatTeamsFileTransfers.publicationId, publication.id),
              ),
            )
            .then((rows) => rows[0]);
          if (transfer || fileTransfer) {
            const resolutionRequired = () =>
              conflict(
                "File delivery requires its current stage-specific resolution",
                { code: "chat_file_transfer_resolution_required" },
              );
            if (
              !transfer ||
              !fileTransfer ||
              publication.state !== "delivery_unknown" ||
              transfer.endpointId !== publication.endpointId ||
              transfer.conversationId !== publication.conversationId ||
              transfer.phase !== fileTransfer.phase ||
              transfer.version !== fileTransfer.version ||
              ![
                "consent_unknown",
                "upload_unknown",
                "file_info_unknown",
                "conflict",
              ].includes(transfer.phase)
            )
              throw resolutionRequired();
            let result;
            try {
              result = await teamsTransferProtocol({
                credentialLease,
              }).resolveInTransaction(tx, {
                companyId: publication.companyId,
                publicationId: publication.id,
                transferId: transfer.id,
                expectedVersion: fileTransfer.version,
                expectedPhase: fileTransfer.phase as
                  | "consent_unknown"
                  | "upload_unknown"
                  | "file_info_unknown"
                  | "conflict",
                action,
              });
            } catch (error) {
              if (
                error instanceof Error &&
                error.message ===
                  "Teams file transfer authority or state changed"
              )
                throw resolutionRequired();
              throw error;
            }
            await logActivity(tx as unknown as Db, {
              companyId: publication.companyId,
              actorType: "user",
              actorId: userId,
              action: `chat.publication_${action}`,
              entityType: "chat_publication",
              entityId: publication.id,
              issueId: publication.issueId,
              details: {
                endpointId,
                conversationId: publication.conversationId,
                transferId: transfer.id,
                previousPhase: fileTransfer.phase,
                previousVersion: fileTransfer.version,
                nextPhase: result.phase,
                nextVersion: result.version,
                duplicateRiskAcknowledged: action === "retry_anyway",
              },
            });
            await credentialLease.assertOwned(tx);
            return;
          }
          if (publication.state !== "delivery_unknown") {
            throw conflict(
              "Only an unconfirmed publication needs an operator resolution",
              {
                code: "chat_publication_resolution_not_required",
              },
            );
          }

          const interactionId = publication.payload.interactionId;
          const isInteractionPrompt =
            Boolean(interactionId) &&
            publication.idempotencyKey ===
              `interaction:${interactionId}:${publication.endpointId}`;
          if (action === "retry_anyway" && isInteractionPrompt) {
            if (!publication.issueId || !interactionId) {
              throw conflict(
                "This interaction prompt is missing its authoritative task binding and cannot be retried safely",
                {
                  code: "chat_terminal_interaction_publication_not_replayable",
                },
              );
            }
            const interaction = await tx
              .select({ status: issueThreadInteractions.status })
              .from(issueThreadInteractions)
              .where(
                and(
                  eq(issueThreadInteractions.id, interactionId),
                  eq(issueThreadInteractions.companyId, publication.companyId),
                  eq(issueThreadInteractions.issueId, publication.issueId),
                ),
              )
              .then((rows) => rows[0] ?? null);
            if (!interaction || interaction.status !== "pending") {
              throw conflict(
                "A resolved interaction prompt cannot be retried with stale provider actions; mark it delivered or cancel it instead",
                {
                  code: "chat_terminal_interaction_publication_not_replayable",
                },
              );
            }
          }

          const now = new Date();
          await tx
            .update(chatPublications)
            .set(
              action === "mark_delivered"
                ? {
                    state: "published",
                    publishedAt: now,
                    nextAttemptAt: null,
                    redactedError: null,
                    updatedAt: now,
                  }
                : action === "retry_anyway"
                  ? {
                      state: "retry",
                      nextAttemptAt: now,
                      redactedError: null,
                      updatedAt: now,
                    }
                  : {
                      state: "cancelled",
                      nextAttemptAt: null,
                      redactedError:
                        "Cancelled by an operator after an unconfirmed provider delivery",
                      updatedAt: now,
                    },
            )
            .where(
              and(
                eq(chatPublications.id, publication.id),
                eq(chatPublications.state, "delivery_unknown"),
              ),
            );
          const receiptProviderActionId = `slack-file-receipt:${publication.id}:${publication.attempts}`;
          if (action === "mark_delivered") {
            await tx
              .update(chatActions)
              .set({
                result: sql`coalesce(${chatActions.result}, '{}'::jsonb) || jsonb_build_object(
                  'operatorConfirmedPublicationId', ${publication.id}::text,
                  'operatorConfirmedAttempt', ${publication.attempts}::integer,
                  'operatorConfirmedAt', ${now.toISOString()}::text
                )`,
                updatedAt: now,
              })
              .where(
                and(
                  eq(chatActions.companyId, publication.companyId),
                  eq(chatActions.endpointId, publication.endpointId),
                  eq(chatActions.conversationId, publication.conversationId),
                  eq(chatActions.kind, "slack_file_upload_receipt"),
                  eq(chatActions.providerActionId, receiptProviderActionId),
                  inArray(chatActions.status, [
                    "received",
                    "failed",
                    "processing",
                  ]),
                  sql`(${chatActions.payload}->>'publicationId')::uuid = ${publication.id}`,
                  sql`(${chatActions.payload}->>'publicationAttempt')::int = ${publication.attempts}`,
                ),
              );
          } else {
            await tx
              .update(chatActions)
              .set({
                status: "cancelled",
                result: {
                  code:
                    action === "retry_anyway"
                      ? "slack_file_upload_receipt_retry_superseded"
                      : "slack_file_upload_receipt_cancelled_by_operator",
                },
                updatedAt: now,
              })
              .where(
                and(
                  eq(chatActions.companyId, publication.companyId),
                  eq(chatActions.endpointId, publication.endpointId),
                  eq(chatActions.conversationId, publication.conversationId),
                  eq(chatActions.kind, "slack_file_upload_receipt"),
                  eq(chatActions.providerActionId, receiptProviderActionId),
                  inArray(chatActions.status, [
                    "received",
                    "failed",
                    "processing",
                  ]),
                  sql`(${chatActions.payload}->>'publicationId')::uuid = ${publication.id}`,
                  sql`(${chatActions.payload}->>'publicationAttempt')::int = ${publication.attempts}`,
                ),
              );
          }
          if (publication.idempotencyKey.startsWith("control:")) {
            await tx
              .update(chatActions)
              .set({
                status:
                  action === "mark_delivered"
                    ? "processed"
                    : action === "retry_anyway"
                      ? "issued"
                      : "cancelled",
                result: {
                  code:
                    action === "mark_delivered"
                      ? "task_control_marked_delivered_by_operator"
                      : action === "retry_anyway"
                        ? "task_control_retry_requested"
                        : "task_control_cancelled_by_operator",
                },
                updatedAt: now,
              })
              .where(
                and(
                  eq(chatActions.endpointId, publication.endpointId),
                  eq(
                    chatActions.providerActionId,
                    `task-control-authorization:${publication.id}`,
                  ),
                  inArray(chatActions.status, [
                    "issued",
                    "processing",
                    "delivery_unknown",
                  ]),
                ),
              );
          }
          if (action === "mark_delivered") {
            await tx
              .update(chatEndpoints)
              .set({ lastPublicationAt: now, updatedAt: now })
              .where(eq(chatEndpoints.id, endpointId));
            await commitTaskControlCompletion(
              tx as unknown as Db,
              publication,
              now,
            );
          }
          await logActivity(tx as unknown as Db, {
            companyId: publication.companyId,
            actorType: "user",
            actorId: userId,
            action: `chat.publication_${action}`,
            entityType: "chat_publication",
            entityId: publication.id,
            issueId: publication.issueId,
            details: {
              endpointId,
              conversationId: publication.conversationId,
              previousState: "delivery_unknown",
              nextState:
                action === "mark_delivered"
                  ? "published"
                  : action === "retry_anyway"
                    ? "retry"
                    : "cancelled",
              duplicateRiskAccepted: action === "retry_anyway",
            },
          });
          await credentialLease.assertOwned(tx);
        }),
    );
    await processPendingPublications();
  }

  async function resolveProviderEffect(
    endpointId: string,
    actionId: string,
    resolution: "mark_delivered" | "retry_anyway" | "cancel",
    userId: string,
  ) {
    const initialRecord = await endpointRecord(endpointId);
    if (!initialRecord) throw notFound("Chat endpoint not found");

    if (resolution === "retry_anyway") {
      await withCredentialMutationLease(
        initialRecord.endpoint,
        async (credentialLease) => {
          const currentRecord = await endpointRecord(endpointId);
          if (
            !currentRecord ||
            !["verifying", "active"].includes(currentRecord.endpoint.status)
          ) {
            throw conflict(
              "The chat connection must be active before retrying this provider reply",
              {
                code: "chat_action_endpoint_unavailable",
              },
            );
          }
          await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            const action = await tx
              .select()
              .from(chatActions)
              .where(
                and(
                  eq(chatActions.endpointId, endpointId),
                  eq(chatActions.id, actionId),
                  eq(chatActions.kind, "provider_effect"),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null);
            if (!action) throw notFound("Provider action not found");
            if (action.status !== "delivery_unknown") {
              throw conflict(
                "Only an unconfirmed provider action needs operator resolution",
                {
                  code: "chat_action_resolution_not_required",
                },
              );
            }
            const payload = providerEffectPayload(action.payload);
            if (!payload) {
              throw conflict("This provider action cannot be retried safely", {
                code: "chat_action_retry_context_missing",
              });
            }
            const delivery =
              payload.settleDelivery && action.deliveryId
                ? await tx
                    .select({ state: chatDeliveries.state })
                    .from(chatDeliveries)
                    .where(
                      and(
                        eq(chatDeliveries.endpointId, endpointId),
                        eq(chatDeliveries.id, action.deliveryId),
                      ),
                    )
                    .for("update")
                    .then((rows) => rows[0] ?? null)
                : null;
            if (payload.settleDelivery && action.deliveryId) {
              if (!delivery || delivery.state !== "failed") {
                throw conflict(
                  "The provider action's delivery is no longer awaiting resolution",
                  {
                    code: "chat_action_delivery_resolution_conflict",
                  },
                );
              }
              await tx
                .update(chatDeliveries)
                .set({
                  state: "processing",
                  nextAttemptAt: null,
                  redactedError: null,
                  updatedAt: new Date(),
                })
                .where(
                  and(
                    eq(chatDeliveries.id, action.deliveryId),
                    eq(chatDeliveries.state, "failed"),
                  ),
                );
            }
            const now = new Date();
            const [claimed] = await tx
              .update(chatActions)
              .set({
                status: "received",
                result: {
                  ...(action.result ?? {}),
                  code: "provider_effect_retry_requested",
                  retryable: false,
                  retryAt: null,
                },
                updatedAt: now,
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "delivery_unknown"),
                ),
              )
              .returning({ id: chatActions.id });
            if (!claimed) {
              throw conflict("This provider action is already being resolved", {
                code: "chat_action_resolution_conflict",
              });
            }
            await logActivity(tx as unknown as Db, {
              companyId: action.companyId,
              actorType: "user",
              actorId: userId,
              action: "chat.provider_effect_retry_anyway",
              entityType: "chat_action",
              entityId: action.id,
              details: {
                endpointId,
                conversationId: action.conversationId,
                deliveryId: action.deliveryId,
                previousState: "delivery_unknown",
                nextState: "received",
                duplicateRiskAccepted: true,
              },
            });
          });
        },
      );
      // The audited retry request is durable before the new transport claim.
      // Do not keep the endpoint mutation lease across provider I/O.
      await processProviderEffect(actionId);
      return;
    }

    await withCredentialMutationLease(
      initialRecord.endpoint,
      (credentialLease) =>
        db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          const action = await tx
            .select()
            .from(chatActions)
            .where(
              and(
                eq(chatActions.endpointId, endpointId),
                eq(chatActions.id, actionId),
                eq(chatActions.kind, "provider_effect"),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null);
          if (!action) throw notFound("Provider action not found");
          if (action.status !== "delivery_unknown") {
            throw conflict(
              "Only an unconfirmed provider action needs operator resolution",
              {
                code: "chat_action_resolution_not_required",
              },
            );
          }
          const payload = providerEffectPayload(action.payload);
          if (!payload) {
            throw conflict("This provider action cannot be resolved safely", {
              code: "chat_action_resolution_context_missing",
            });
          }
          const delivery =
            payload.settleDelivery && action.deliveryId
              ? await tx
                  .select({ state: chatDeliveries.state })
                  .from(chatDeliveries)
                  .where(
                    and(
                      eq(chatDeliveries.endpointId, endpointId),
                      eq(chatDeliveries.id, action.deliveryId),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
          if (
            payload.settleDelivery &&
            action.deliveryId &&
            (!delivery || delivery.state !== "failed")
          ) {
            throw conflict(
              "The provider action's delivery is no longer awaiting resolution",
              {
                code: "chat_action_delivery_resolution_conflict",
              },
            );
          }

          const now = new Date();
          const nextStatus =
            resolution === "mark_delivered" ? "processed" : "cancelled";
          const [resolved] = await tx
            .update(chatActions)
            .set({
              status: nextStatus,
              result: {
                ...(action.result ?? {}),
                code:
                  resolution === "mark_delivered"
                    ? "provider_effect_marked_delivered_by_operator"
                    : "provider_effect_cancelled_by_operator",
                retryable: false,
                retryAt: null,
              },
              updatedAt: now,
            })
            .where(
              and(
                eq(chatActions.id, action.id),
                eq(chatActions.status, "delivery_unknown"),
              ),
            )
            .returning({ id: chatActions.id });
          if (!resolved) {
            throw conflict("This provider action is already being resolved", {
              code: "chat_action_resolution_conflict",
            });
          }
          if (payload.settleDelivery && action.deliveryId) {
            await tx
              .update(chatDeliveries)
              .set(
                resolution === "mark_delivered"
                  ? {
                      state: "processed",
                      processedAt: now,
                      nextAttemptAt: null,
                      redactedError: null,
                      updatedAt: now,
                    }
                  : {
                      state: "filtered",
                      processedAt: now,
                      nextAttemptAt: null,
                      redactedError:
                        "Cancelled by an operator after an unconfirmed provider reply",
                      updatedAt: now,
                    },
              )
              .where(
                and(
                  eq(chatDeliveries.id, action.deliveryId),
                  eq(chatDeliveries.state, "failed"),
                ),
              );
          }
          if (resolution === "mark_delivered") {
            if (payload.completeConversationId) {
              await tx
                .update(chatConversations)
                .set({ state: "completed", updatedAt: now })
                .where(
                  and(
                    eq(chatConversations.id, payload.completeConversationId),
                    eq(chatConversations.endpointId, endpointId),
                  ),
                );
            }
            await tx
              .update(chatEndpoints)
              .set({ lastEventAt: now, updatedAt: now })
              .where(eq(chatEndpoints.id, endpointId));
          }
          await logActivity(tx as unknown as Db, {
            companyId: action.companyId,
            actorType: "user",
            actorId: userId,
            action: `chat.provider_effect_${resolution}`,
            entityType: "chat_action",
            entityId: action.id,
            details: {
              endpointId,
              conversationId: action.conversationId,
              deliveryId: action.deliveryId,
              completeConversationId: payload.completeConversationId ?? null,
              previousState: "delivery_unknown",
              nextState: nextStatus,
              duplicateRiskAccepted: false,
            },
          });
          await credentialLease.assertOwned(tx);
        }),
    );
  }

  async function resolveAction(
    endpointId: string,
    actionId: string,
    resolution: "mark_delivered" | "retry_anyway" | "cancel",
    userId: string,
  ) {
    const initialRecord = await endpointRecord(endpointId);
    if (!initialRecord) throw notFound("Chat endpoint not found");
    const initialAction = await db
      .select({ kind: chatActions.kind })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.endpointId, endpointId),
          eq(chatActions.id, actionId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!initialAction) throw notFound("Provider action not found");
    if (initialAction.kind === "provider_effect") {
      await resolveProviderEffect(endpointId, actionId, resolution, userId);
      return;
    }
    if (initialRecord.endpoint.provider !== "slack") {
      throw conflict("This provider action cannot be resolved here", {
        code: "chat_action_resolution_unsupported",
      });
    }
    if (resolution === "mark_delivered") {
      throw conflict("A Slack task start cannot be marked delivered here", {
        code: "chat_action_resolution_unsupported",
      });
    }

    if (resolution === "cancel") {
      await withCredentialMutationLease(
        initialRecord.endpoint,
        async (credentialLease) => {
          await db.transaction(async (tx) => {
            await credentialLease.assertOwned(tx);
            await tx
              .update(chatActions)
              .set({
                status: "delivery_unknown",
                result: { code: "slash_task_delivery_unknown" },
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatActions.endpointId, endpointId),
                  eq(chatActions.id, actionId),
                  eq(chatActions.kind, "slash_task_start"),
                  or(
                    and(
                      eq(chatActions.status, "received"),
                      lte(
                        chatActions.updatedAt,
                        new Date(Date.now() - SLACK_COMMAND_POST_STALE_MS),
                      ),
                    ),
                    and(
                      eq(chatActions.status, "resolving"),
                      lte(
                        chatActions.updatedAt,
                        new Date(
                          Date.now() - SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS,
                        ),
                      ),
                    ),
                  ),
                ),
              );
            await credentialLease.assertOwned(tx);
            const action = await tx
              .select()
              .from(chatActions)
              .where(
                and(
                  eq(chatActions.endpointId, endpointId),
                  eq(chatActions.id, actionId),
                  eq(chatActions.kind, "slash_task_start"),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null);
            if (!action) throw notFound("Provider action not found");
            if (action.status !== "delivery_unknown") {
              throw conflict(
                "Only an unconfirmed provider action needs operator resolution",
                {
                  code: "chat_action_resolution_not_required",
                },
              );
            }
            const now = new Date();
            await tx
              .update(chatActions)
              .set({
                status: "cancelled",
                result: { code: "slash_task_cancelled_by_operator" },
                updatedAt: now,
              })
              .where(
                and(
                  eq(chatActions.id, action.id),
                  eq(chatActions.status, "delivery_unknown"),
                ),
              );
            await logActivity(tx as unknown as Db, {
              companyId: action.companyId,
              actorType: "user",
              actorId: userId,
              action: "chat.slack_command_cancel",
              entityType: "chat_action",
              entityId: action.id,
              details: {
                endpointId,
                previousState: "delivery_unknown",
                nextState: "cancelled",
                duplicateRiskAccepted: false,
              },
            });
            await credentialLease.assertOwned(tx);
          });
        },
      );
      return;
    }

    let confirmedActionId: string | null = null;
    await withCredentialMutationLease(
      initialRecord.endpoint,
      async (credentialLease) => {
        const record = await endpointRecord(endpointId);
        if (!record) throw notFound("Chat endpoint not found");
        if (
          record.endpoint.provider !== "slack" ||
          !["verifying", "active"].includes(record.endpoint.status)
        ) {
          throw conflict(
            "The Slack connection must be active before retrying this action",
            {
              code: "chat_action_endpoint_unavailable",
            },
          );
        }
        const action = await db
          .select()
          .from(chatActions)
          .where(
            and(
              eq(chatActions.endpointId, endpointId),
              eq(chatActions.id, actionId),
              eq(chatActions.kind, "slash_task_start"),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (!action) throw notFound("Provider action not found");
        const staleActionCanBeNormalized =
          (action.status === "received" &&
            action.updatedAt.getTime() <=
              Date.now() - SLACK_COMMAND_POST_STALE_MS) ||
          (action.status === "resolving" &&
            action.updatedAt.getTime() <=
              Date.now() - SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS);
        if (
          action.status !== "delivery_unknown" &&
          !staleActionCanBeNormalized
        ) {
          throw conflict(
            "Only an unconfirmed provider action needs operator resolution",
            {
              code: "chat_action_resolution_not_required",
            },
          );
        }
        const recovery = slackSlashTaskRecoveryPayload(action.payload);
        if (!recovery) {
          throw conflict(
            "This action does not contain enough context for an explicit retry",
            {
              code: "chat_action_retry_context_missing",
            },
          );
        }
        if (!action.principalId) {
          throw conflict("The original Slack account is no longer available", {
            code: "chat_action_principal_missing",
          });
        }
        const principal = await db
          .select()
          .from(chatExternalPrincipals)
          .where(
            and(
              eq(chatExternalPrincipals.id, action.principalId),
              eq(chatExternalPrincipals.companyId, record.endpoint.companyId),
              eq(chatExternalPrincipals.provider, "slack"),
              eq(
                chatExternalPrincipals.providerAccountId,
                record.endpoint.providerAccountId ?? "unknown",
              ),
            ),
          )
          .then((rows) => rows[0] ?? null);
        if (!principal || principal.isBot || principal.kind !== "user") {
          throw conflict("The original Slack account is no longer available", {
            code: "chat_action_principal_missing",
          });
        }
        const link = await db
          .select({
            paperclipUserId: chatIdentityLinks.paperclipUserId,
            status: chatIdentityLinks.status,
          })
          .from(chatIdentityLinks)
          .where(
            and(
              eq(chatIdentityLinks.endpointId, endpointId),
              eq(chatIdentityLinks.principalId, principal.id),
            ),
          )
          .then((rows) => rows[0] ?? null);
        let principalAllowed = false;
        if (link?.status === "linked" && link.paperclipUserId) {
          principalAllowed = await db
            .select({ membershipRole: companyMemberships.membershipRole })
            .from(companyMemberships)
            .where(
              and(
                eq(companyMemberships.companyId, record.endpoint.companyId),
                eq(companyMemberships.principalType, "user"),
                eq(companyMemberships.principalId, link.paperclipUserId),
                eq(companyMemberships.status, "active"),
                ne(companyMemberships.membershipRole, "viewer"),
              ),
            )
            .then((rows) => rows.length > 0);
        } else if (record.endpoint.allowUnlinkedPeople) {
          principalAllowed = await sponsorAllowsGuest(record.endpoint);
        }

        const rawChannelId = recovery.channelId.replace(/^slack:/, "");
        const isDirectMessage = /^D[A-Z0-9]+$/i.test(rawChannelId);
        const resource = await db
          .select()
          .from(chatEndpointResources)
          .where(
            and(
              eq(chatEndpointResources.endpointId, endpointId),
              eq(chatEndpointResources.providerResourceId, rawChannelId),
            ),
          )
          .then((rows) => rows[0] ?? null);
        const destinationAllowed = isDirectMessage
          ? record.endpoint.allowDirectMessages
          : nonDirectDestinationAllowed(record.endpoint, resource);
        if (!principalAllowed || !destinationAllowed) {
          throw conflict(
            "The original account or destination is no longer allowed",
            {
              code: "chat_action_no_longer_authorized",
            },
          );
        }

        // Resolve and validate the runtime before claiming the action. A local
        // setup failure at this point cannot have sent anything to Slack and
        // therefore leaves the original ambiguous action untouched.
        const endpointRuntime = await runtimeFor(record.endpoint);
        const baseThread = endpointRuntime.thread(`slack:${rawChannelId}:`);
        const retryAttempt =
          (action.status === "delivery_unknown" &&
          typeof action.result?.attemptCount === "number" &&
          Number.isSafeInteger(action.result.attemptCount)
            ? Math.max(0, action.result.attemptCount)
            : 0) + 1;
        const [claimed] = await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          await tx
            .update(chatActions)
            .set({
              status: "delivery_unknown",
              result: { code: "slash_task_delivery_unknown" },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.endpointId, endpointId),
                eq(chatActions.id, actionId),
                eq(chatActions.kind, "slash_task_start"),
                or(
                  and(
                    eq(chatActions.status, "received"),
                    lte(
                      chatActions.updatedAt,
                      new Date(Date.now() - SLACK_COMMAND_POST_STALE_MS),
                    ),
                  ),
                  and(
                    eq(chatActions.status, "resolving"),
                    lte(
                      chatActions.updatedAt,
                      new Date(
                        Date.now() - SLACK_COMMAND_EXPLICIT_RETRY_STALE_MS,
                      ),
                    ),
                  ),
                ),
              ),
            );
          await credentialLease.assertOwned(tx);
          const current = await tx
            .select()
            .from(chatActions)
            .where(
              and(
                eq(chatActions.endpointId, endpointId),
                eq(chatActions.id, actionId),
                eq(chatActions.kind, "slash_task_start"),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null);
          if (!current) throw notFound("Provider action not found");
          if (current.status !== "delivery_unknown") {
            throw conflict(
              "Only an unconfirmed provider action needs operator resolution",
              {
                code: "chat_action_resolution_not_required",
              },
            );
          }
          const currentEndpoint = await runtimeCallbackEndpoint(
            tx,
            record.endpoint.id,
            runtimeContextForRecord(record),
            ["verifying", "active"],
          );
          const currentResource =
            currentEndpoint && !isDirectMessage
              ? await tx
                  .select()
                  .from(chatEndpointResources)
                  .where(
                    and(
                      eq(
                        chatEndpointResources.companyId,
                        currentEndpoint.companyId,
                      ),
                      eq(chatEndpointResources.endpointId, currentEndpoint.id),
                      eq(
                        chatEndpointResources.providerResourceId,
                        rawChannelId,
                      ),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
          const currentAuthorization = currentEndpoint
            ? await lockCurrentPrincipalAuthorization(
                tx,
                currentEndpoint,
                action.principalId!,
              )
            : null;
          const currentDestinationAllowed = currentEndpoint
            ? isDirectMessage
              ? currentEndpoint.allowDirectMessages
              : nonDirectDestinationAllowed(currentEndpoint, currentResource)
            : false;
          if (
            !currentEndpoint ||
            !currentAuthorization?.allowed ||
            !currentDestinationAllowed
          ) {
            throw conflict(
              "The original account or destination is no longer allowed",
              {
                code: "chat_action_no_longer_authorized",
              },
            );
          }
          const rows = await tx
            .update(chatActions)
            .set({
              status: "resolving",
              result: {
                code: "slash_task_retry_requested",
                attemptCount: retryAttempt,
                authorizedUserId: currentAuthorization.userId,
              },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, current.id),
                eq(chatActions.status, "delivery_unknown"),
              ),
            )
            .returning();
          await logActivity(tx as unknown as Db, {
            companyId: current.companyId,
            actorType: "user",
            actorId: userId,
            action: "chat.slack_command_retry_anyway",
            entityType: "chat_action",
            entityId: current.id,
            details: {
              endpointId,
              previousState: "delivery_unknown",
              nextState: "resolving",
              duplicateRiskAccepted: true,
            },
          });
          await credentialLease.assertOwned(tx);
          return rows;
        });
        if (!claimed) {
          throw conflict("This provider action is already being resolved", {
            code: "chat_action_resolution_conflict",
          });
        }

        let starter: { id: string; threadId: string };
        try {
          starter = await baseThread.post("Starting a task…");
        } catch (error) {
          await finalizeSlackTaskStartFailure({
            actionId: action.id,
            actionStatus: "resolving",
            attempt: retryAttempt,
            connectionId: record.endpoint.connectionId,
            credentialLease,
            endpoint: record.endpoint,
            error,
            providerAttempted: true,
            resource,
            runtimeFence: runtimeContextForRecord(record),
          });
          throw error;
        }
        const [completed] = await db.transaction(async (tx) => {
          await credentialLease.assertOwned(tx);
          return tx
            .update(chatActions)
            .set({
              // The provider send is now confirmed, but task admission is a
              // separate durable phase. Persist this fence before constructing the
              // Paperclip delivery so a crash cannot turn into another Slack post.
              status: "provider_confirmed",
              result: {
                attemptCount: retryAttempt,
                authorizedUserId: claimed.result?.authorizedUserId ?? null,
                threadId: slackTaskStarterThreadId(rawChannelId, starter.id),
                providerMessageId: starter.id,
              },
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatActions.id, action.id),
                eq(chatActions.status, "resolving"),
                sql`(${chatActions.result}->>'attemptCount')::int = ${retryAttempt}`,
              ),
            )
            .returning({ id: chatActions.id });
        });
        // A deliberately cancelled action wins over a provider response that
        // arrived only after the operator's stale-action window. Keep the Slack
        // starter as an orphan rather than creating work the operator cancelled.
        if (!completed) return;
        confirmedActionId = action.id;
      },
    );
    if (typeof confirmedActionId === "string") {
      await admitConfirmedSlackTaskStart(
        confirmedActionId,
        options.deferWebhookProcessing === true,
      );
    }
  }

  async function getPublicationBatchStatus(
    endpointId: string,
    conversationId: string,
    publicationId: string,
  ): Promise<ChatPublicationBatchStatus> {
    if (![endpointId, conversationId, publicationId].every(isUuidLike)) {
      throw badRequest(
        "Valid endpoint, conversation, and publication IDs are required",
      );
    }
    const anchor = await db
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.id, publicationId),
          eq(chatPublications.endpointId, endpointId),
          eq(chatPublications.conversationId, conversationId),
        ),
      )
      .then((rows) => rows[0]);
    if (!anchor) throw notFound("Chat publication not found");
    // An explicit Board send and every durable text/file transport part share
    // its comment. Read all parts without Activity's history limit; never
    // advance the worker or replay a provider side effect from this GET.
    // Join public receipts and private transfer facts in one database snapshot.
    // A concurrent consent or file receipt cannot produce a mixed-time batch.
    const batch = await db
      .select({
        publication: chatPublications,
        transfer: fileTransferProjectionColumns,
      })
      .from(chatPublications)
      .leftJoin(
        chatTeamsFileTransfers,
        and(
          eq(chatTeamsFileTransfers.companyId, chatPublications.companyId),
          eq(chatTeamsFileTransfers.endpointId, chatPublications.endpointId),
          eq(
            chatTeamsFileTransfers.conversationId,
            chatPublications.conversationId,
          ),
          eq(chatTeamsFileTransfers.publicationId, chatPublications.id),
        ),
      )
      .where(
        and(
          eq(chatPublications.companyId, anchor.companyId),
          eq(chatPublications.endpointId, endpointId),
          eq(chatPublications.conversationId, conversationId),
          anchor.commentId
            ? eq(chatPublications.commentId, anchor.commentId)
            : eq(chatPublications.id, anchor.id),
        ),
      )
      .orderBy(
        asc(chatPublications.createdAt),
        asc(publicationTransportOrderKey(chatPublications)),
      );
    if (!batch.length) throw notFound("Chat publication not found");
    return projectChatPublicationBatch(
      batch.map(({ publication, transfer }) =>
        projectChatFileTransfer(
          publicationSummary(publication),
          transfer?.publicationId ? transfer : undefined,
        ),
      ),
    );
  }

  async function publishComment(
    endpointId: string,
    conversationId: string,
    commentId: string,
  ) {
    const conversation = await db
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.id, conversationId),
          eq(chatConversations.endpointId, endpointId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!conversation) throw notFound("Conversation not found");
    const comment = await db
      .select()
      .from(issueComments)
      .where(
        and(
          eq(issueComments.id, commentId),
          eq(issueComments.issueId, conversation.issueId),
          isNull(issueComments.deletedAt),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!comment) throw notFound("Task comment not found");
    const [publication] = await db
      .insert(chatPublications)
      .values({
        companyId: conversation.companyId,
        endpointId,
        conversationId,
        issueId: conversation.issueId,
        commentId,
        idempotencyKey: `explicit:${commentId}:${endpointId}`,
        payload: projectSafeChatPublication({
          classification: "external",
          source: "explicit_board_send",
          text: comment.body,
        }),
        state: "pending",
      })
      .onConflictDoNothing()
      .returning();
    await processPendingPublications();
    const batch = await db
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, conversation.companyId),
          eq(chatPublications.endpointId, endpointId),
          eq(chatPublications.conversationId, conversationId),
          eq(chatPublications.commentId, commentId),
        ),
      )
      .orderBy(
        asc(chatPublications.createdAt),
        asc(publicationTransportOrderKey(chatPublications)),
      );
    return (
      batch.find((candidate) => candidate.state !== "published") ??
      batch.at(-1) ??
      publication
    );
  }

  async function publishBoardMessage(
    endpointId: string,
    conversationId: string,
    body: string,
    clientIdempotencyKey: string,
    userId: string,
    attachmentIds: string[] = [],
  ) {
    // Browser request IDs are only unique within the conversation that issued
    // them. Include that durable task boundary so a retried key from another
    // conversation can neither suppress its send nor return the first task's
    // publication.
    const idempotencyKey = `explicit-board:${endpointId}:${conversationId}:${clientIdempotencyKey}`;
    const rejectionActionId = `board-send-rejected:${conversationId}:${clientIdempotencyKey}`;
    const rejectionCode = "chat_board_send_attachments_already_bound";
    const rejectionDetails = (ids: string[]) => ({
      code: rejectionCode,
      endpointId,
      conversationId,
      idempotencyKey: clientIdempotencyKey,
      attachmentIds: ids,
    });
    const validRejectedIds = (value: unknown): value is string[] =>
      Array.isArray(value) &&
      value.length > 0 &&
      value.length <= 20 &&
      value.every((id) => typeof id === "string" && isUuidLike(id)) &&
      new Set(value).size === value.length;
    if (attachmentIds.length > 0) {
      const record = await endpointRecord(endpointId);
      if (
        record?.endpoint.provider === "microsoft-teams" &&
        record.endpoint.status === "active"
      ) {
        const [existing] = await db
          .select({ id: chatPublications.id })
          .from(chatPublications)
          .where(
            and(
              eq(chatPublications.companyId, record.endpoint.companyId),
              eq(chatPublications.endpointId, endpointId),
              eq(chatPublications.conversationId, conversationId),
              eq(chatPublications.idempotencyKey, idempotencyKey),
            ),
          )
          .limit(1);
        // A cold service must not permanently choose the task-link fallback
        // merely because runtime reconciliation has not run yet. Initialize
        // outside all Board/source locks, then recheck the full scope below.
        // A repeated send identity needs only its existing durable receipt.
        const [rejected] = existing
          ? []
          : await db
              .select({ id: chatActions.id })
              .from(chatActions)
              .where(
                and(
                  eq(chatActions.companyId, record.endpoint.companyId),
                  eq(chatActions.endpointId, endpointId),
                  eq(chatActions.providerActionId, rejectionActionId),
                ),
              )
              .limit(1);
        if (!existing && !rejected) await runtimeFor(record.endpoint);
      }
    }
    const publication = await db.transaction(async (tx) => {
      const conversation = await tx
        .select()
        .from(chatConversations)
        .where(
          and(
            eq(chatConversations.id, conversationId),
            eq(chatConversations.endpointId, endpointId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!conversation) throw notFound("Conversation not found");

      const existing = await tx
        .select()
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, conversation.companyId),
            eq(chatPublications.idempotencyKey, idempotencyKey),
          ),
        )
        .then((rows) => rows[0] ?? null);
      if (existing) {
        const batch = await tx
          .select()
          .from(chatPublications)
          .where(
            and(
              eq(chatPublications.endpointId, endpointId),
              eq(chatPublications.conversationId, conversationId),
              eq(chatPublications.commentId, existing.commentId!),
            ),
          )
          .orderBy(
            asc(chatPublications.createdAt),
            asc(publicationTransportOrderKey(chatPublications)),
          );
        return (
          batch.find((candidate) => candidate.state !== "published") ??
          batch.at(-1) ??
          existing
        );
      }

      const [rejected] = await tx
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.companyId, conversation.companyId),
            eq(chatActions.endpointId, endpointId),
            eq(chatActions.providerActionId, rejectionActionId),
          ),
        )
        .limit(1);
      if (rejected) {
        const payload = rejected.payload;
        if (
          rejected.kind !== "board_send_rejected" ||
          rejected.status !== "processed" ||
          rejected.conversationId !== conversation.id ||
          payload.schemaVersion !== 1 ||
          payload.issueId !== conversation.issueId ||
          payload.idempotencyKey !== clientIdempotencyKey ||
          rejected.result?.code !== rejectionCode ||
          !validRejectedIds(payload.attachmentIds)
        ) {
          throw conflict("Board send rejection receipt is unavailable");
        }
        // The negative receipt is immutable, including when the caller retries
        // with different content or the previous owner comment was deleted.
        return { rejection: rejectionDetails(payload.attachmentIds) };
      }

      let comment: Awaited<
        ReturnType<ReturnType<typeof issueService>["addComment"]>
      >;
      try {
        // addComment inserts before binding attachments. Roll back that insert
        // in a savepoint, then commit only the exact terminal rejection below.
        comment = await tx.transaction((inner) =>
          issueService(inner as unknown as Db).addComment(
            conversation.issueId,
            body,
            { userId },
            { authorType: "user", attachmentIds },
            inner,
          ),
        );
      } catch (error) {
        const details =
          error instanceof HttpError &&
          error.status === 409 &&
          error.details &&
          typeof error.details === "object" &&
          !Array.isArray(error.details)
            ? (error.details as Record<string, unknown>)
            : null;
        if (
          details?.code !== "issue_comment_attachments_already_bound" ||
          details.companyId !== conversation.companyId ||
          details.issueId !== conversation.issueId ||
          !validRejectedIds(details.attachmentIds) ||
          !details.attachmentIds.every((id) => attachmentIds.includes(id))
        )
          throw error;
        const invalidIds = attachmentIds.filter((id) =>
          (details.attachmentIds as string[]).includes(id),
        );
        await tx.insert(chatActions).values({
          companyId: conversation.companyId,
          endpointId,
          conversationId,
          kind: "board_send_rejected",
          providerActionId: rejectionActionId,
          payload: {
            schemaVersion: 1,
            issueId: conversation.issueId,
            requestedByUserId: userId,
            idempotencyKey: clientIdempotencyKey,
            attachmentIds: invalidIds,
          },
          status: "processed",
          result: { code: rejectionCode },
        });
        return { rejection: rejectionDetails(invalidIds) };
      }
      const attachedFiles = attachmentIds.length
        ? await tx
            .select({
              id: issueAttachments.id,
              originalFilename: assets.originalFilename,
            })
            .from(issueAttachments)
            .innerJoin(assets, eq(issueAttachments.assetId, assets.id))
            .where(
              and(
                eq(issueAttachments.companyId, conversation.companyId),
                eq(issueAttachments.issueId, conversation.issueId),
                eq(issueAttachments.issueCommentId, comment.id),
                inArray(issueAttachments.id, attachmentIds),
              ),
            )
        : [];
      const attachedFileById = new Map(
        attachedFiles.map((file) => [file.id, file]),
      );
      const orderedFiles = attachmentIds.map((attachmentId) =>
        attachedFileById.get(attachmentId)!,
      );
      const publicationCreatedAt = new Date();
      const [created] = await tx
        .insert(chatPublications)
        .values({
          companyId: conversation.companyId,
          endpointId,
          conversationId,
          issueId: conversation.issueId,
          commentId: comment.id,
          idempotencyKey,
          payload: projectSafeChatPublication({
            classification: "external",
            source: "explicit_board_send",
            text: comment.body,
          }),
          state: "pending",
          createdAt: publicationCreatedAt,
          updatedAt: publicationCreatedAt,
        })
        .returning();
      let terminalPublication = created;
      for (const [index, file] of orderedFiles.entries()) {
        const attachmentCreatedAt = new Date(
          publicationCreatedAt.getTime() + index + 1,
        );
        const [attachmentPublication] = await tx
          .insert(chatPublications)
          .values({
            companyId: conversation.companyId,
            endpointId,
            conversationId,
            issueId: conversation.issueId,
            commentId: comment.id,
            idempotencyKey: `${idempotencyKey}:attachment:${file.id}`,
            payload: projectSafeChatPublication({
              classification: "external",
              source: "explicit_board_send",
              text: `Shared ${file.originalFilename ?? "a file"}.`,
              attachmentIds: [file.id],
            }),
            state: "pending",
            createdAt: attachmentCreatedAt,
            updatedAt: attachmentCreatedAt,
          })
          .returning();
        await stageTeamsBoardFileIntent(
          tx,
          attachmentPublication,
          userId,
          conversation,
        );
        terminalPublication = attachmentPublication;
      }
      await logActivity(tx as unknown as Db, {
        companyId: conversation.companyId,
        actorType: "user",
        actorId: userId,
        action: "chat.publication_requested",
        entityType: "chat_publication",
        entityId: created.id,
        issueId: conversation.issueId,
        details: {
          endpointId,
          conversationId,
          commentId: comment.id,
          source: "explicit_board_send",
        },
      });
      return terminalPublication;
    });
    if ("rejection" in publication) {
      throw conflict(
        "Selected attachments are already bound to another comment",
        publication.rejection,
      );
    }
    await processPendingPublications();
    const batch = publication.commentId
      ? await db
          .select()
          .from(chatPublications)
          .where(
            and(
              eq(chatPublications.endpointId, endpointId),
              eq(chatPublications.conversationId, conversationId),
              eq(chatPublications.commentId, publication.commentId),
            ),
          )
          .orderBy(
            asc(chatPublications.createdAt),
            asc(publicationTransportOrderKey(chatPublications)),
          )
      : [publication];
    // A multi-part send is successful only when every ordered publication is
    // published. Surface the first blocking row so the UI points operators at
    // the actual retry/duplicate-risk resolution instead of a later pending
    // attachment that cannot advance past it.
    return (
      batch.find((candidate) => candidate.state !== "published") ??
      batch.at(-1) ??
      publication
    );
  }

  // Native Teams file consent is authority for one personal recipient and one
  // immutable file, not authority inferred from the SDK's latest route cache.
  const teamsBoardFileIntentKind = "teams_board_file_intent";
  const teamsFileProofHash = (value: unknown) =>
    createHash("sha256")
      .update(
        JSON.stringify(value, (_key, entry) =>
          entry && typeof entry === "object" && !Array.isArray(entry)
            ? Object.fromEntries(
                Object.keys(entry)
                  .sort()
                  .map((key) => [key, entry[key]]),
              )
            : entry,
        ),
      )
      .digest("hex");

  async function teamsFileCurrentScope(
    tx: DbTransaction,
    supplied: typeof chatPublications.$inferSelect,
    fence?: LifecycleRuntimeFence,
  ) {
    const [endpoint] = await tx
      .select()
      .from(chatEndpoints)
      .where(
        and(
          eq(chatEndpoints.companyId, supplied.companyId),
          eq(chatEndpoints.id, supplied.endpointId),
        ),
      )
      .for("no key update", { noWait: true });
    if (
      !endpoint ||
      endpoint.provider !== "microsoft-teams" ||
      endpoint.status !== "active" ||
      !endpoint.allowDirectMessages ||
      !isUuidLike(endpoint.providerAccountId) ||
      !isUuidLike(endpoint.botExternalId)
    )
      return null;
    const [connection] = await tx
      .select()
      .from(toolConnections)
      .where(
        and(
          eq(toolConnections.companyId, endpoint.companyId),
          eq(toolConnections.id, endpoint.connectionId),
        ),
      )
      .for("share", { noWait: true });
    if (!connection?.enabled || connection.status !== "active") return null;
    const currentFence = {
      generation: runtimeGeneration(endpoint.setup),
      credentialFingerprint: credentialFingerprint(
        connection.credentialSecretRefs,
      ),
    };
    const instance = runtime.get(endpoint.id);
    const registration = instance
      ? runtimeContexts.get(instance as object)
      : null;
    if (
      !instance ||
      !registration ||
      registration.generation !== currentFence.generation ||
      registration.credentialFingerprint !==
        currentFence.credentialFingerprint ||
      registration.localEpoch !== localRuntimeEpoch(endpoint.id) ||
      runtimeVersions.get(endpoint.id) !== registration.version ||
      (fence &&
        (fence.generation !== currentFence.generation ||
          fence.credentialFingerprint !== currentFence.credentialFingerprint))
    )
      return null;
    const [conversation] = await tx
      .select()
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, endpoint.companyId),
          eq(chatConversations.endpointId, endpoint.id),
          eq(chatConversations.id, supplied.conversationId),
          eq(chatConversations.issueId, supplied.issueId),
        ),
      )
      .for("update", { noWait: true });
    if (
      !conversation?.isDirectMessage ||
      !["active", "waiting"].includes(conversation.state)
    )
      return null;
    const [superseded] = await tx
      .select({ id: chatConversations.id })
      .from(chatConversations)
      .where(
        and(
          eq(chatConversations.companyId, endpoint.companyId),
          eq(chatConversations.endpointId, endpoint.id),
          eq(chatConversations.externalThreadId, conversation.externalThreadId),
          gt(
            chatConversations.sessionGeneration,
            conversation.sessionGeneration,
          ),
        ),
      )
      .limit(1);
    if (superseded) return null;
    const [issue] = await tx
      .select({ id: issues.id, assigneeAgentId: issues.assigneeAgentId })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, endpoint.companyId),
          eq(issues.id, conversation.issueId),
        ),
      )
      .for("share", { noWait: true });
    if (!issue || issue.assigneeAgentId !== endpoint.assignedAgentId)
      return null;
    // The conversation lock serializes rollover. The endpoint lock serializes
    // reach/credential changes; no lock here waits behind inverse Board order.
    if (conversation.resourceId)
      await tx
        .select({ id: chatEndpointResources.id })
        .from(chatEndpointResources)
        .where(
          and(
            eq(chatEndpointResources.companyId, endpoint.companyId),
            eq(chatEndpointResources.endpointId, endpoint.id),
            eq(chatEndpointResources.id, conversation.resourceId),
          ),
        )
        .for("update", { noWait: true });
    const [publication] = await tx
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, endpoint.companyId),
          eq(chatPublications.endpointId, endpoint.id),
          eq(chatPublications.conversationId, conversation.id),
          eq(chatPublications.issueId, conversation.issueId),
          eq(chatPublications.id, supplied.id),
        ),
      )
      .for("update", { noWait: true });
    const ids = publication?.payload.attachmentIds;
    if (
      !publication?.commentId ||
      !Array.isArray(ids) ||
      ids.length !== 1 ||
      !isUuidLike(ids[0]) ||
      publication.payload.progressState !== undefined ||
      publication.payload.interactionId ||
      publication.payload.card ||
      publication.idempotencyKey.startsWith("control:") ||
      publication.idempotencyKey.startsWith("wake:")
    )
      return null;
    const [comment] = await tx
      .select()
      .from(issueComments)
      .where(
        and(
          eq(issueComments.companyId, endpoint.companyId),
          eq(issueComments.issueId, conversation.issueId),
          eq(issueComments.id, publication.commentId),
          isNull(issueComments.deletedAt),
        ),
      )
      .for("share", { noWait: true });
    const [file] = await tx
      .select({ attachment: issueAttachments, asset: assets })
      .from(issueAttachments)
      .innerJoin(
        assets,
        and(
          eq(assets.id, issueAttachments.assetId),
          eq(assets.companyId, endpoint.companyId),
        ),
      )
      .where(
        and(
          eq(issueAttachments.companyId, endpoint.companyId),
          eq(issueAttachments.issueId, conversation.issueId),
          eq(issueAttachments.issueCommentId, publication.commentId),
          eq(issueAttachments.id, ids[0]),
        ),
      )
      .for("share", { noWait: true });
    const filename =
      file?.asset.originalFilename ??
      (file ? `attachment-${file.attachment.id}` : "");
    if (
      !comment ||
      comment.updatedAt.getTime() !== comment.createdAt.getTime() ||
      !file ||
      !Number.isSafeInteger(file.asset.byteSize) ||
      file.asset.byteSize <= 0 ||
      file.asset.byteSize > MAX_ATTACHMENT_BYTES ||
      file.asset.byteSize >= 60 * 1024 * 1024 ||
      !/^[a-f0-9]{64}$/.test(file.asset.sha256) ||
      !file.asset.objectKey.trim() ||
      !isAllowedContentType(file.asset.contentType) ||
      !filename ||
      filename.length > 255 ||
      filename !== filename.trim() ||
      filename.endsWith(".") ||
      /[<>:"/\\|?*\x00-\x1f\x7f]/.test(filename)
    )
      return null;
    const byteIdentity = {
      attachmentId: file.attachment.id,
      assetId: file.asset.id,
      sha256: file.asset.sha256,
      byteSize: file.asset.byteSize,
      filename,
      contentType: file.asset.contentType,
      originatingRunId: file.attachment.originatingRunId,
    };
    return {
      endpoint,
      conversation,
      publication,
      comment,
      file,
      filename,
      currentFence,
      byteIdentity,
      instance,
    };
  }

  async function teamsFilePrincipalAuthorization(
    tx: DbTransaction,
    endpoint: EndpointRow,
    principalId: string,
  ) {
    const identity = await tx.execute(
      sql`select pg_try_advisory_xact_lock(hashtextextended(${`chat-identity:${endpoint.companyId}:${principalId}`}, 0)) as locked`,
    );
    if (!identity[0]?.locked)
      throw new NativeChatReviewPresentationContentionError();
    const [link] = await tx
      .select()
      .from(chatIdentityLinks)
      .where(
        and(
          eq(chatIdentityLinks.companyId, endpoint.companyId),
          eq(chatIdentityLinks.endpointId, endpoint.id),
          eq(chatIdentityLinks.principalId, principalId),
        ),
      )
      .for("update", { noWait: true });
    const userId =
      link?.status === "linked" ? link.paperclipUserId : endpoint.sponsorUserId;
    if (userId)
      await tx
        .select()
        .from(companyMemberships)
        .where(
          and(
            eq(companyMemberships.companyId, endpoint.companyId),
            eq(companyMemberships.principalType, "user"),
            eq(companyMemberships.principalId, userId),
          ),
        )
        .for("update", { noWait: true });
    // All rows and the identity advisory key used by the common authorization
    // helper are already held; the helper cannot introduce an inverse wait.
    return lockCurrentPrincipalAuthorization(tx, endpoint, principalId);
  }

  async function teamsFileSourceBinding(
    tx: DbTransaction,
    scope: NonNullable<Awaited<ReturnType<typeof teamsFileCurrentScope>>>,
    actionId: string,
  ) {
    const { endpoint, conversation } = scope;
    const [action] = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, endpoint.companyId),
          eq(chatActions.endpointId, endpoint.id),
          eq(chatActions.conversationId, conversation.id),
          eq(chatActions.id, actionId),
          eq(chatActions.kind, "inbound_wakeup"),
          eq(chatActions.status, "processed"),
        ),
      )
      .for("update", { noWait: true });
    if (
      !action?.deliveryId ||
      !action.principalId ||
      action.payload.version !== 1 ||
      action.payload.issueId !== conversation.issueId ||
      action.payload.agentId !== endpoint.assignedAgentId ||
      action.payload.sessionGeneration !== conversation.sessionGeneration ||
      typeof action.payload.commentId !== "string" ||
      !isUuidLike(action.payload.commentId)
    )
      return null;
    const [delivery] = await tx
      .select()
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.companyId, endpoint.companyId),
          eq(chatDeliveries.endpointId, endpoint.id),
          eq(chatDeliveries.conversationId, conversation.id),
          eq(chatDeliveries.id, action.deliveryId),
          eq(chatDeliveries.principalId, action.principalId),
          eq(chatDeliveries.state, "processed"),
          inArray(chatDeliveries.eventKind, [
            "direct_message",
            "mention",
            "message",
          ]),
        ),
      )
      .for("update", { noWait: true });
    const originalFence = delivery ? lifecycleRuntimeFence(delivery) : null;
    const [principal] = await tx
      .select()
      .from(chatExternalPrincipals)
      .where(
        and(
          eq(chatExternalPrincipals.companyId, endpoint.companyId),
          eq(chatExternalPrincipals.id, action.principalId),
          eq(chatExternalPrincipals.provider, "microsoft-teams"),
          eq(
            chatExternalPrincipals.providerAccountId,
            endpoint.providerAccountId!,
          ),
          eq(chatExternalPrincipals.kind, "user"),
          eq(chatExternalPrincipals.isBot, false),
        ),
      )
      .for("share", { noWait: true });
    if (!delivery || !originalFence || !principal) return null;
    const admission = {
      companyId: endpoint.companyId,
      endpointId: endpoint.id,
      runtimeGeneration: originalFence.generation,
      credentialFingerprint: originalFence.credentialFingerprint,
      tenantId: endpoint.providerAccountId!,
      botAppId: endpoint.botExternalId!,
      providerEventId: delivery.providerEventId,
      threadId: conversation.externalThreadId,
      isDirectMessage: true,
    };
    const parsed = parseTeamsPersonalRecipient(
      delivery.normalizedEvent.teamsPersonalRecipient,
      admission,
    );
    const binding = parsed
      ? bindTeamsPersonalRecipient(parsed, {
          admission,
          deliveryId: delivery.id,
          principalId: principal.id,
          conversationId: conversation.id,
          conversationGeneration: conversation.sessionGeneration,
          externalPrincipalId: principal.externalId,
        })
      : null;
    const originalConversation = delivery.normalizedEvent.conversation as
      Record<string, unknown> | undefined;
    const originalMessage = delivery.normalizedEvent.message as
      Record<string, unknown> | undefined;
    const originalPrincipal = delivery.normalizedEvent.principal as
      Record<string, unknown> | undefined;
    if (
      !binding ||
      originalConversation?.isDirectMessage !== true ||
      typeof originalConversation.externalThreadId !== "string" ||
      canonicalTeamsThreadId(originalConversation.externalThreadId) !==
        canonicalTeamsThreadId(conversation.externalThreadId) ||
      originalMessage?.providerMessageId !==
        binding.recipient.providerActivityId ||
      originalPrincipal?.externalId !== principal.externalId
    )
      return null;
    const [source] = await tx
      .select({ comment: issueComments, link: chatMessageLinks })
      .from(chatMessageLinks)
      .innerJoin(
        issueComments,
        and(
          eq(issueComments.id, chatMessageLinks.commentId),
          eq(issueComments.companyId, endpoint.companyId),
          eq(issueComments.issueId, conversation.issueId),
        ),
      )
      .where(
        and(
          eq(chatMessageLinks.companyId, endpoint.companyId),
          eq(chatMessageLinks.endpointId, endpoint.id),
          eq(chatMessageLinks.conversationId, conversation.id),
          eq(chatMessageLinks.deliveryId, delivery.id),
          eq(chatMessageLinks.commentId, action.payload.commentId),
          eq(chatMessageLinks.direction, "inbound"),
        ),
      )
      .for("share", { noWait: true });
    const expectedUserId =
      action.payload.requestedByActorType === "user"
        ? action.payload.requestedByActorId
        : null;
    if (
      !source ||
      source.link.providerMessageId !== binding.recipient.providerActivityId ||
      source.comment.deletedAt ||
      source.comment.createdAt > scope.comment.createdAt ||
      source.comment.updatedAt.getTime() !==
        source.comment.createdAt.getTime() ||
      source.comment.authorUserId !== expectedUserId ||
      !["user", "system"].includes(
        String(action.payload.requestedByActorType),
      ) ||
      (expectedUserId === null &&
        action.payload.requestedByActorId !== principal.id)
    )
      return null;
    const [lifecycle] = await tx
      .select({ id: chatDeliveries.id })
      .from(chatDeliveries)
      .where(
        and(
          eq(chatDeliveries.companyId, endpoint.companyId),
          eq(chatDeliveries.endpointId, endpoint.id),
          or(
            isNull(chatDeliveries.conversationId),
            eq(chatDeliveries.conversationId, conversation.id),
          ),
          ne(chatDeliveries.state, "filtered"),
          inArray(chatDeliveries.eventKind, [
            "message_updated",
            "message_deleted",
            "message_restored",
          ]),
          sql`${chatDeliveries.normalizedEvent}->'runtimeContext' = ${JSON.stringify(originalFence)}::jsonb`,
          sql`${chatDeliveries.normalizedEvent}->'message'->>'targetProviderEventId' = ${delivery.providerEventId}`,
        ),
      )
      .limit(1);
    if (lifecycle) return null;
    const authorization = await teamsFilePrincipalAuthorization(
      tx,
      endpoint,
      principal.id,
    );
    if (!authorization.allowed || authorization.userId !== expectedUserId)
      return null;
    const [receipt] = await tx
      .select()
      .from(agentWakeupRequests)
      .where(
        and(
          eq(agentWakeupRequests.companyId, endpoint.companyId),
          eq(agentWakeupRequests.id, action.id),
          eq(agentWakeupRequests.agentId, endpoint.assignedAgentId),
        ),
      )
      .for("share", { noWait: true });
    if (!receipt || ["skipped", "cancelled"].includes(receipt.status))
      return null;
    try {
      assertFailedRetryReceipt(
        createDurableChatWakeupRequest({
          id: action.id,
          companyId: endpoint.companyId,
          agentId: endpoint.assignedAgentId,
          issueId: conversation.issueId,
          commentId: source.comment.id,
          requestedByActorType: action.payload.requestedByActorType as
            "user" | "system",
          requestedByActorId: String(action.payload.requestedByActorId),
          requestedAt: action.createdAt,
          authorize: async () => {},
        }),
        receipt,
      );
    } catch (error) {
      if (
        error instanceof HttpError &&
        (error.details as { code?: string } | undefined)?.code ===
          "chat_failed_run_retry_not_authorized"
      )
        return null;
      throw error;
    }
    return {
      binding,
      authorization,
      action,
      sourceFacts: {
        actionId: action.id,
        deliveryId: delivery.id,
        commentId: source.comment.id,
        principalId: principal.id,
        scope: inboundWakeScope(action),
        originalFence,
        bodySha256: createHash("sha256")
          .update(source.comment.body)
          .digest("hex"),
        receiptId: receipt.id,
        recipientBindingSha256: teamsFileProofHash(binding),
      },
    };
  }

  async function teamsBoardOriginBinding(
    tx: DbTransaction,
    scope: NonNullable<Awaited<ReturnType<typeof teamsFileCurrentScope>>>,
  ) {
    // Pick the task's first admitted source, never the latest DM actor. If the
    // durable task contains different recipient principals, consent is ambiguous.
    const principals = await tx
      .selectDistinct({ id: chatActions.principalId })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, scope.endpoint.companyId),
          eq(chatActions.endpointId, scope.endpoint.id),
          eq(chatActions.conversationId, scope.conversation.id),
          eq(chatActions.kind, "inbound_wakeup"),
          eq(chatActions.status, "processed"),
          sql`${chatActions.payload}->>'sessionGeneration' = ${String(scope.conversation.sessionGeneration)}`,
        ),
      )
      .limit(2);
    if (principals.length !== 1 || !principals[0]?.id) return null;
    const [origin] = await tx
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, scope.endpoint.companyId),
          eq(chatActions.endpointId, scope.endpoint.id),
          eq(chatActions.conversationId, scope.conversation.id),
          eq(chatActions.kind, "inbound_wakeup"),
          eq(chatActions.status, "processed"),
          sql`${chatActions.payload}->>'sessionGeneration' = ${String(scope.conversation.sessionGeneration)}`,
        ),
      )
      .orderBy(asc(chatActions.createdAt), asc(chatActions.id))
      .limit(1);
    return origin ? teamsFileSourceBinding(tx, scope, origin.id) : null;
  }

  async function teamsBoardAuthorIsCurrent(
    tx: DbTransaction,
    companyId: string,
    userId: string,
  ) {
    const [membership] = await tx
      .select()
      .from(companyMemberships)
      .where(
        and(
          eq(companyMemberships.companyId, companyId),
          eq(companyMemberships.principalType, "user"),
          eq(companyMemberships.principalId, userId),
        ),
      )
      .for("share", { noWait: true });
    return (
      membership?.status === "active" && membership.membershipRole !== "viewer"
    );
  }

  function teamsBoardFileIntentPayload(
    scope: NonNullable<Awaited<ReturnType<typeof teamsFileCurrentScope>>>,
    source: NonNullable<Awaited<ReturnType<typeof teamsFileSourceBinding>>>,
    userId: string,
  ) {
    return {
      schema: "paperclip.teams.board-file-intent.v1",
      publicationId: scope.publication.id,
      issueId: scope.conversation.issueId,
      commentId: scope.comment.id,
      attachmentId: scope.file.attachment.id,
      userId,
      conversationGeneration: scope.conversation.sessionGeneration,
      sourceActionId: source.action.id,
      sourceScopeSha256: teamsFileProofHash(source.sourceFacts),
      recipientBindingSha256: teamsFileProofHash(source.binding),
      byteIdentitySha256: teamsFileProofHash(scope.byteIdentity),
      commentBodySha256: createHash("sha256")
        .update(scope.comment.body)
        .digest("hex"),
    };
  }

  function teamsFileRuntimeStillCurrent(
    scope: NonNullable<Awaited<ReturnType<typeof teamsFileCurrentScope>>>,
  ) {
    const registration = runtimeContexts.get(scope.instance as object);
    return (
      runtime.get(scope.endpoint.id) === scope.instance &&
      registration?.generation === scope.currentFence.generation &&
      registration.credentialFingerprint ===
        scope.currentFence.credentialFingerprint &&
      registration.localEpoch === localRuntimeEpoch(scope.endpoint.id) &&
      runtimeVersions.get(scope.endpoint.id) === registration.version
    );
  }

  async function stageTeamsBoardFileIntent(
    tx: DbTransaction,
    publication: typeof chatPublications.$inferSelect,
    userId: string,
    conversation: ConversationRow,
  ): Promise<void> {
    if (
      !publication.idempotencyKey.startsWith("explicit-board:") ||
      !conversation.isDirectMessage
    )
      return;
    const scope = await teamsFileCurrentScope(tx, publication);
    if (
      !scope ||
      scope.conversation.id !== conversation.id ||
      scope.conversation.sessionGeneration !== conversation.sessionGeneration ||
      scope.comment.authorUserId !== userId ||
      scope.comment.authorAgentId ||
      scope.comment.createdByRunId ||
      !(await teamsBoardAuthorIsCurrent(tx, scope.endpoint.companyId, userId))
    )
      return;
    const source = await teamsBoardOriginBinding(tx, scope);
    if (!source || !teamsFileRuntimeStillCurrent(scope)) return;
    const key = `${teamsBoardFileIntentKind}:${publication.id}`;
    const payload = teamsBoardFileIntentPayload(scope, source, userId);
    const [existing] = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, scope.endpoint.companyId),
          eq(chatActions.endpointId, scope.endpoint.id),
          eq(chatActions.providerActionId, key),
        ),
      )
      .for("update", { noWait: true });
    if (existing) {
      if (
        existing.kind !== teamsBoardFileIntentKind ||
        existing.status !== "processed" ||
        existing.deliveryId !== source.binding.deliveryId ||
        existing.principalId !== source.binding.principalId ||
        existing.conversationId !== scope.conversation.id ||
        teamsFileProofHash(existing.payload) !== teamsFileProofHash(payload)
      )
        throw conflict("The Teams file recipient intent has changed", {
          code: "chat_file_transfer_authority_changed",
        });
      return;
    }
    await tx.insert(chatActions).values({
      companyId: scope.endpoint.companyId,
      endpointId: scope.endpoint.id,
      conversationId: scope.conversation.id,
      deliveryId: source.binding.deliveryId,
      principalId: source.binding.principalId,
      kind: teamsBoardFileIntentKind,
      providerActionId: key,
      status: "processed",
      payload,
    });
  }

  async function deriveTeamsFileTransferAuthority(
    tx: DbTransaction,
    publication: typeof chatPublications.$inferSelect,
    fence: LifecycleRuntimeFence,
    continuingTeamsFileTransfer?: NonNullable<
      NonNullable<
        Parameters<typeof failedChatRetrySource>[1]["committedResponse"]
      >["continuingTeamsFileTransfer"]
    >,
  ): Promise<TeamsFileTransferAuthority | null> {
    const scope = await teamsFileCurrentScope(tx, publication, fence);
    if (!scope) return null;
    let source: NonNullable<Awaited<ReturnType<typeof teamsFileSourceBinding>>>;
    let causal: Record<string, unknown>;
    if (isExplicitOperatorPublication(scope.publication)) {
      if (
        !scope.publication.idempotencyKey.startsWith("explicit-board:") ||
        !scope.comment.authorUserId ||
        scope.comment.authorAgentId ||
        scope.comment.createdByRunId ||
        !(await teamsBoardAuthorIsCurrent(
          tx,
          scope.endpoint.companyId,
          scope.comment.authorUserId,
        ))
      )
        return null;
      const [intent] = await tx
        .select()
        .from(chatActions)
        .where(
          and(
            eq(chatActions.companyId, scope.endpoint.companyId),
            eq(chatActions.endpointId, scope.endpoint.id),
            eq(chatActions.conversationId, scope.conversation.id),
            eq(chatActions.kind, teamsBoardFileIntentKind),
            eq(
              chatActions.providerActionId,
              `${teamsBoardFileIntentKind}:${scope.publication.id}`,
            ),
            eq(chatActions.status, "processed"),
          ),
        )
        .for("share", { noWait: true });
      if (
        !intent ||
        typeof intent.payload.sourceActionId !== "string" ||
        !isUuidLike(intent.payload.sourceActionId)
      )
        return null;
      const bound = await teamsBoardOriginBinding(tx, scope);
      if (
        !bound ||
        bound.action.id !== intent.payload.sourceActionId ||
        intent.deliveryId !== bound.binding.deliveryId ||
        intent.principalId !== bound.binding.principalId
      )
        return null;
      const currentPayload = teamsBoardFileIntentPayload(
        scope,
        bound,
        scope.comment.authorUserId,
      );
      if (
        teamsFileProofHash(intent.payload) !==
        teamsFileProofHash(currentPayload)
      )
        return null;
      source = bound;
      causal = {
        kind: "explicit_board_send",
        intentId: intent.id,
        ...currentPayload,
      };
    } else {
      const runId = scope.comment.createdByRunId;
      if (
        !runId ||
        scope.comment.authorAgentId !== scope.endpoint.assignedAgentId ||
        scope.file.attachment.originatingRunId !== runId
      )
        return null;
      const [run] = await tx
        .select()
        .from(heartbeatRuns)
        .where(
          and(
            eq(heartbeatRuns.companyId, scope.endpoint.companyId),
            eq(heartbeatRuns.id, runId),
            eq(heartbeatRuns.agentId, scope.endpoint.assignedAgentId),
            eq(heartbeatRuns.nativeIssueId, scope.conversation.issueId),
            eq(heartbeatRuns.runtimeMode, "native"),
            eq(heartbeatRuns.status, "succeeded"),
            isNotNull(heartbeatRuns.finishedAt),
          ),
        )
        .for("share", { noWait: true });
      const marker = run?.resultJson?.nativeCommittedChatResponse as
        Record<string, unknown> | undefined;
      if (
        !run ||
        !marker ||
        marker.schema !== "paperclip.native_committed_chat_response.v1" ||
        typeof marker.resultId !== "string" ||
        !isUuidLike(marker.resultId) ||
        typeof marker.decisionId !== "string" ||
        !isUuidLike(marker.decisionId) ||
        typeof marker.canonicalSha256 !== "string" ||
        !/^(?:sha256:)?[a-f0-9]{64}$/.test(marker.canonicalSha256)
      )
        return null;
      // Pre-lock the exact causal source and actor rows before the existing
      // complete native publication proof invokes its common authorization.
      const originActions = await tx
        .select({ id: chatActions.id })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.companyId, scope.endpoint.companyId),
            eq(chatActions.conversationId, scope.conversation.id),
            eq(chatActions.kind, "inbound_wakeup"),
            inArray(
              sql<string>`${chatActions.payload}->>'commentId'`,
              retryCommentIds(run.contextSnapshot ?? {}),
            ),
          ),
        );
      const bindings: Array<
        NonNullable<Awaited<ReturnType<typeof teamsFileSourceBinding>>>
      > = [];
      for (const action of originActions) {
        const binding = await teamsFileSourceBinding(tx, scope, action.id);
        if (!binding) return null;
        bindings.push(binding);
      }
      let proved: FailedChatRetrySource;
      try {
        proved = await failedChatRetrySource(tx, {
          companyId: scope.endpoint.companyId,
          issueId: scope.conversation.issueId,
          agentId: run.agentId,
          failedRunId: run.id,
          publication: true,
          committedResponse: {
            resultId: marker.resultId,
            canonicalSha256: marker.canonicalSha256,
            decisionId: marker.decisionId,
            continuingTeamsFileTransfer,
          },
        });
      } catch (error) {
        if (
          error instanceof HttpError &&
          (error.details as { code?: string } | undefined)?.code ===
            "chat_failed_run_retry_not_authorized"
        )
          return null;
        throw error;
      }
      if (
        proved.provider !== "microsoft-teams" ||
        proved.endpointId !== scope.endpoint.id ||
        proved.conversationId !== scope.conversation.id ||
        proved.sessionGeneration !== scope.conversation.sessionGeneration ||
        bindings.length !== proved.sources.length
      )
        return null;
      const ordered = proved.sources.map((entry) =>
        bindings.find((binding) => binding.action.id === entry.actionId),
      );
      const first = ordered[0];
      if (
        !first ||
        ordered.some(
          (entry) =>
            !entry ||
            entry.binding.principalId !== proved.principalId ||
            entry.binding.recipient.providerConversationId !==
              first.binding.recipient.providerConversationId ||
            entry.binding.recipient.providerUserId !==
              first.binding.recipient.providerUserId ||
            entry.binding.recipient.aadObjectId !==
              first.binding.recipient.aadObjectId,
        )
      )
        return null;
      if (
        run.resultJson?.finalizationReasonCode ===
          "governed_response_waiting" &&
        !(await authorizeNativeChatReviewPresentation(
          tx as unknown as Db,
          {
            companyId: scope.endpoint.companyId,
            issueId: scope.conversation.issueId,
            runId: run.id,
            resultJson: run.resultJson,
            destination: {
              endpointId: scope.endpoint.id,
              conversationId: scope.conversation.id,
            },
          },
          "nonblocking",
        ))
      )
        return null;
      source = first;
      causal = {
        kind: "native_committed_response",
        runId: run.id,
        resultId: marker.resultId,
        canonicalSha256: marker.canonicalSha256,
        decisionId: marker.decisionId,
        sourceScopeSha256: proved.sourceScopeSha256,
        sources: ordered.map((entry) => entry!.sourceFacts),
      };
    }
    // No mutable stage, attempt, receipt, route URL or provider token enters
    // this digest. The next authorization derives these facts afresh.
    const sourceDigest = teamsFileProofHash({
      schema: "paperclip.teams.file-source.v1",
      companyId: scope.endpoint.companyId,
      endpointId: scope.endpoint.id,
      conversationId: scope.conversation.id,
      conversationGeneration: scope.conversation.sessionGeneration,
      issueId: scope.conversation.issueId,
      publicationId: scope.publication.id,
      commentId: scope.comment.id,
      causal,
      byteIdentity: scope.byteIdentity,
    });
    if (!teamsFileRuntimeStillCurrent(scope)) return null;
    return {
      companyId: scope.endpoint.companyId,
      endpointId: scope.endpoint.id,
      conversationId: scope.conversation.id,
      issueId: scope.conversation.issueId,
      publicationId: scope.publication.id,
      commentId: scope.comment.id,
      attachmentId: scope.file.attachment.id,
      principalId: source.binding.principalId,
      authorizedUserId: source.authorization.userId,
      runtimeGeneration: scope.currentFence.generation,
      credentialFingerprint: scope.currentFence.credentialFingerprint,
      conversationGeneration: scope.conversation.sessionGeneration,
      sourceDigest,
      tenantId: source.binding.recipient.tenantId,
      botAppId: source.binding.recipient.botAppId,
      aadObjectId: source.binding.recipient.aadObjectId,
      providerConversationId: source.binding.recipient.providerConversationId,
      providerUserId: source.binding.recipient.providerUserId,
      sha256: scope.file.asset.sha256,
      byteSize: scope.file.asset.byteSize,
      filename: scope.filename,
    };
  }

  function teamsTransferProtocol(
    input: {
      credentialLease?: CredentialMutationLeaseGuard;
      callbackContext?: RuntimeContext;
    } = {},
  ) {
    const denied = () =>
      conflict("Teams file delivery authority changed", {
        code: "chat_file_transfer_authority_changed",
      });
    const currentRuntime = async (authority: TeamsFileTransferAuthority) => {
      if (!input.credentialLease) throw denied();
      await input.credentialLease.assertOwned();
      const record = await endpointRecord(authority.endpointId);
      if (
        !record ||
        record.endpoint.companyId !== authority.companyId ||
        record.endpoint.provider !== "microsoft-teams" ||
        record.endpoint.status !== "active"
      )
        throw denied();
      const context = runtimeContextForRecord(record);
      if (
        context.generation !== authority.runtimeGeneration ||
        context.credentialFingerprint !== authority.credentialFingerprint
      )
        throw denied();
      const instance = await runtimeFor(record.endpoint);
      const registered = runtimeContexts.get(instance as object);
      if (
        !registered ||
        registered.version !== context.version ||
        registered.localEpoch !== localRuntimeEpoch(authority.endpointId) ||
        runtime.get(authority.endpointId) !== instance
      )
        throw denied();
      await input.credentialLease.assertOwned();
      return instance;
    };
    const personalThread = (authority: TeamsFileTransferAuthority) =>
      `teams:${Buffer.from(authority.providerConversationId).toString("base64url")}:personal`;
    return teamsFileTransferService(db, {
      project: projectTeamsFilePublication,
      authorize: async (tx, expected, stage) => {
        await input.credentialLease?.assertOwned(tx);
        if (
          input.callbackContext &&
          (input.callbackContext.generation !== expected.runtimeGeneration ||
            input.callbackContext.credentialFingerprint !==
              expected.credentialFingerprint ||
            input.callbackContext.localEpoch !==
              localRuntimeEpoch(expected.endpointId) ||
            input.callbackContext.endpointRuntime !==
              runtime.get(expected.endpointId))
        )
          throw denied();
        const [publication] = await tx
          .select()
          .from(chatPublications)
          .where(
            and(
              eq(chatPublications.companyId, expected.companyId),
              eq(chatPublications.endpointId, expected.endpointId),
              eq(chatPublications.id, expected.publicationId),
            ),
          )
          .for("update");
        // This selector is derived only inside the staged protocol's locked
        // authority check, never from a retry request or a model instruction.
        const [continuing] =
          publication?.state === "delivery_unknown" &&
          (stage === "response" || stage === "file_info")
            ? await tx
                .select({
                  transferId: chatTeamsFileTransfers.id,
                  publicationId: chatTeamsFileTransfers.publicationId,
                  version: chatTeamsFileTransfers.version,
                  phase: chatTeamsFileTransfers.phase,
                })
                .from(chatTeamsFileTransfers)
                .where(
                  and(
                    eq(chatTeamsFileTransfers.companyId, expected.companyId),
                    eq(chatTeamsFileTransfers.endpointId, expected.endpointId),
                    eq(
                      chatTeamsFileTransfers.conversationId,
                      expected.conversationId,
                    ),
                    eq(
                      chatTeamsFileTransfers.publicationId,
                      expected.publicationId,
                    ),
                    eq(
                      chatTeamsFileTransfers.phase,
                      stage === "response"
                        ? "consent_unknown"
                        : "file_info_unknown",
                    ),
                  ),
                )
                .for("update")
            : [];
        const current =
          publication &&
          (await deriveTeamsFileTransferAuthority(
            tx,
            publication,
            {
              generation: expected.runtimeGeneration,
              credentialFingerprint: expected.credentialFingerprint,
            },
            continuing && {
              ...continuing,
              phase: continuing.phase as
                "consent_unknown" | "file_info_unknown",
            },
          ));
        if (!current) throw denied();
        await input.credentialLease?.assertOwned(tx);
        return current;
      },
      loadBytes: async (authority) => {
        const [publication] = await db
          .select()
          .from(chatPublications)
          .where(
            and(
              eq(chatPublications.companyId, authority.companyId),
              eq(chatPublications.endpointId, authority.endpointId),
              eq(chatPublications.id, authority.publicationId),
            ),
          );
        if (!publication) throw denied();
        const files = await publicationFiles(publication, publication.payload);
        if (files.length !== 1 || !Buffer.isBuffer(files[0]?.data))
          throw denied();
        return files[0].data;
      },
      postConsent: async ({ authority, card, signal }) => {
        const instance = await currentRuntime(authority);
        signal.throwIfAborted();
        return instance.sendTeamsFileConsentCard(
          personalThread(authority),
          card,
        );
      },
      postFileInfo: async ({ authority, card, signal }) => {
        const instance = await currentRuntime(authority);
        signal.throwIfAborted();
        return instance.sendTeamsUploadedFileCard(
          personalThread(authority),
          card,
        );
      },
      uploadRequest: options.teamsFileUploadRequest,
    });
  }

  async function handleTeamsFileConsent(
    callback: ChatSdkCallbackEvent<TeamsFileConsentEvent>,
    context: RuntimeContext,
  ): Promise<"recorded" | "ignored" | "denied"> {
    if (
      callback.provider !== "microsoft-teams" ||
      callback.endpointId !== callback.event.endpointId ||
      context.endpointRuntime !== runtime.get(callback.endpointId) ||
      context.localEpoch !== localRuntimeEpoch(callback.endpointId)
    )
      return "denied";
    // Do not wait for the sender's credential lease: an authentic acceptance
    // can arrive while its consent-card POST is still awaiting the receipt.
    let result: "recorded" | "ignored" | "denied";
    try {
      result = await teamsTransferProtocol({
        callbackContext: context,
      }).recordConsent(callback.event);
    } catch (error) {
      // A known current-policy denial is not a temporary provider outage.
      // Contention and unproven persistence still propagate as retryable 503.
      if (
        error instanceof HttpError &&
        (error.details as { code?: string } | undefined)?.code ===
          "chat_file_transfer_authority_changed"
      )
        return "denied";
      throw error;
    }
    if (result === "recorded")
      scheduleMessageProcessing(async () => {
        await processPendingPublications();
      });
    return result;
  }

  async function tryProcessTeamsFilePublication(
    selected: typeof chatPublications.$inferSelect,
  ): Promise<boolean> {
    const [existing] = await db
      .select({
        id: chatTeamsFileTransfers.id,
        endpointId: chatTeamsFileTransfers.endpointId,
        conversationId: chatTeamsFileTransfers.conversationId,
      })
      .from(chatTeamsFileTransfers)
      .where(
        and(
          eq(chatTeamsFileTransfers.companyId, selected.companyId),
          eq(chatTeamsFileTransfers.publicationId, selected.id),
        ),
      );
    if (!existing && !selected.payload.attachmentIds?.length) return false;
    const record = await endpointRecord(selected.endpointId);
    if (!record || record.endpoint.provider !== "microsoft-teams")
      return Boolean(existing);
    if (
      existing &&
      (existing.endpointId !== selected.endpointId ||
        existing.conversationId !== selected.conversationId)
    )
      return true;
    if (record.endpoint.status !== "active") return Boolean(existing);
    try {
      return await withCredentialMutationLease(
        record.endpoint,
        async (credentialLease) => {
          await runtimeFor(record.endpoint);
          const protocol = teamsTransferProtocol({ credentialLease });
          let transferId = existing?.id;
          if (!transferId) {
            const authority = await db.transaction(async (tx) => {
              await credentialLease.assertOwned(tx);
              const [current] = await tx
                .select()
                .from(chatPublications)
                .where(
                  and(
                    eq(chatPublications.companyId, selected.companyId),
                    eq(chatPublications.id, selected.id),
                  ),
                )
                .for("update");
              if (
                !current ||
                !["pending", "retry"].includes(current.state) ||
                (current.nextAttemptAt && current.nextAttemptAt > new Date())
              )
                return null;
              return deriveTeamsFileTransferAuthority(
                tx,
                current,
                runtimeContextForRecord(record),
              );
            });
            // Missing personal-recipient proof is not permission to guess a DM.
            // The ordinary path sends the truthful task-link fallback instead.
            if (!authority) return false;
            transferId = (
              await protocol.issue(
                authority,
                new Date(Date.now() + 60 * 60 * 1000),
              )
            ).id;
          }
          // A successful consent/upload transition can immediately progress to
          // its next effect, but no user wait, unknown outcome or backoff spins.
          for (let stage = 0; stage < 3; stage++) {
            const [current] = await db
              .select({ nextAttemptAt: chatPublications.nextAttemptAt })
              .from(chatPublications)
              .where(
                and(
                  eq(chatPublications.companyId, selected.companyId),
                  eq(chatPublications.id, selected.id),
                ),
              );
            if (
              !current ||
              (current.nextAttemptAt && current.nextAttemptAt > new Date())
            )
              break;
            const result = await protocol.process(
              selected.companyId,
              transferId,
            );
            if (
              ![
                "consent_pending",
                "upload_pending",
                "file_info_pending",
              ].includes(result.phase)
            )
              break;
          }
          teamsFileRetryAfter.delete(selected.id);
          return true;
        },
      );
    } catch {
      // A failed authorization/lock/receipt write must never fall through to a
      // generic resend. Preserve exact durable evidence; this cooldown grants
      // no authority and safely resets when the server restarts.
      if (teamsFileRetryAfter.size >= 1000)
        teamsFileRetryAfter.delete(teamsFileRetryAfter.keys().next().value!);
      teamsFileRetryAfter.set(selected.id, Date.now() + 30_000);
      return true;
    }
  }

  let teamsMaintenancePending = false;
  let teamsMaintenanceAfter = 0;
  function scheduleTeamsFileMaintenance() {
    if (
      teamsMaintenancePending ||
      Date.now() < teamsMaintenanceAfter ||
      shuttingDown
    )
      return;
    teamsMaintenancePending = true;
    teamsMaintenanceAfter = Date.now() + 30_000;
    scheduleMessageProcessing(async () => {
      try {
        const scopes = await db
          .selectDistinct({ companyId: chatTeamsFileTransfers.companyId })
          .from(chatTeamsFileTransfers)
          .where(
            or(
              and(
                inArray(chatTeamsFileTransfers.phase, [
                  "consent_pending",
                  "awaiting_consent",
                  "upload_pending",
                ]),
                lte(chatTeamsFileTransfers.expiresAt, new Date()),
              ),
              and(
                inArray(chatTeamsFileTransfers.phase, [
                  "consent_sending",
                  "uploading",
                  "file_info_sending",
                  "conflict",
                ]),
                lte(chatTeamsFileTransfers.attemptExpiresAt, new Date()),
              ),
            ),
          );
        const protocol = teamsTransferProtocol();
        // Separate from the ordinary message queue. Each company sweep bounds
        // its row count and lock waits and performs no provider I/O.
        for (const scope of scopes) {
          if (shuttingDown) break;
          await protocol.expireAndRecover(scope.companyId, 100);
        }
      } catch {
        // Selection errors are closed here too; private transfer envelopes and
        // SQL parameters must not escape through the generic background logger.
        logger.warn(
          "Teams file maintenance will retry after a temporary failure",
        );
      } finally {
        teamsMaintenancePending = false;
      }
    });
  }

  async function publicationFiles(
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
    preparation: { teamsInlineImagesOnly?: boolean } = {},
  ): Promise<FileUpload[]> {
    if (!payload.attachmentIds?.length) return [];
    try {
      const rows = await db
        .select({
          id: issueAttachments.id,
          issueId: issueAttachments.issueId,
          issueCommentId: issueAttachments.issueCommentId,
          objectKey: assets.objectKey,
          contentType: assets.contentType,
          byteSize: assets.byteSize,
          sha256: assets.sha256,
          originalFilename: assets.originalFilename,
        })
        .from(issueAttachments)
        .innerJoin(assets, eq(issueAttachments.assetId, assets.id))
        .where(
          and(
            eq(issueAttachments.companyId, publication.companyId),
            eq(issueAttachments.issueId, publication.issueId),
            inArray(issueAttachments.id, payload.attachmentIds),
          ),
        );
      const byId = new Map(rows.map((row) => [row.id, row]));
      const orderedRows = payload.attachmentIds.map((attachmentId) => {
        const row = byId.get(attachmentId);
        if (
          !row ||
          (publication.commentId &&
            row.issueCommentId !== publication.commentId) ||
          row.byteSize <= 0 ||
          row.byteSize > MAX_ATTACHMENT_BYTES ||
          !row.objectKey.trim() ||
          !/^[0-9a-f]{64}$/iu.test(row.sha256) ||
          !isAllowedContentType(row.contentType)
        )
          throw new OutboundAttachmentValidationError(
            "Chat publication attachment is invalid or outside its authorized task comment",
          );
        return row;
      });
      // Picture messages have a different Teams contract from arbitrary files.
      // Preserve the normal scope/metadata checks above, but never hydrate a
      // document or oversized image just to discover it needs a task link.
      if (
        preparation.teamsInlineImagesOnly &&
        orderedRows.some(
          (row) =>
            row.byteSize > TEAMS_INLINE_IMAGE_MAX_BYTES ||
            !isTeamsInlineImageContentType(row.contentType),
        )
      ) {
        return [];
      }
      // Authorization and persisted metadata must fail definitively even when
      // storage is unavailable; do not mask an invalid file as a transient outage.
      if (!options.storage)
        throw new OutboundAttachmentHydrationError(
          "Attachment storage is unavailable for chat publication",
        );
      const files: FileUpload[] = [];
      for (const row of orderedRows) {
        files.push(
          await hydrateOutboundAttachment({
            storage: options.storage,
            companyId: publication.companyId,
            objectKey: row.objectKey,
            byteSize: row.byteSize,
            sha256: row.sha256,
            filename: row.originalFilename ?? `attachment-${row.id}`,
            mimeType: row.contentType,
          }),
        );
      }
      return files;
    } catch (error) {
      if (
        isOutboundAttachmentHydrationError(error) ||
        isOutboundAttachmentValidationError(error)
      ) {
        throw error;
      }
      throw new OutboundAttachmentHydrationError(
        "Chat publication attachment preparation failed",
        error,
      );
    }
  }

  function discordMarkdownAttachment(text: string): FileUpload {
    return {
      data: Buffer.from(text, "utf8"),
      filename: "paperclip-response.md",
      mimeType: "text/markdown; charset=utf-8",
    };
  }

  function telegramMarkdownAttachment(text: string): Attachment {
    const data = Buffer.from(text, "utf8");
    return {
      data,
      mimeType: "text/markdown; charset=utf-8",
      name: "paperclip-response.md",
      size: data.byteLength,
      type: "file",
    };
  }

  async function recordSlackFileUploadReceipt(input: {
    credentialLease: CredentialMutationLeaseGuard;
    conversation: ConversationRow;
    endpoint: EndpointRow;
    publication: typeof chatPublications.$inferSelect;
    receipt: SlackFileUploadAcceptedReceipt;
    runtimeContext: LifecycleRuntimeFence;
  }): Promise<string> {
    const publicationAttempt = input.publication.attempts + 1;
    const botExternalId = input.endpoint.botExternalId;
    const expectedThreadId = `slack:${input.receipt.channelId}:${input.receipt.threadTs ?? ""}`;
    if (
      input.endpoint.provider !== "slack" ||
      !botExternalId ||
      input.receipt.version !== 1 ||
      expectedThreadId !== input.conversation.externalThreadId ||
      input.receipt.fileIds.length !==
        (input.publication.payload.attachmentIds?.length ?? 0)
    ) {
      throw new Error(
        "Slack file upload receipt did not match its publication",
      );
    }
    const payload: SlackFileUploadReceiptPayload = {
      version: 1,
      publicationId: input.publication.id,
      publicationAttempt,
      threadId: expectedThreadId,
      fileIds: [...input.receipt.fileIds],
      botExternalId,
      runtimeGeneration: input.runtimeContext.generation,
      credentialFingerprint: input.runtimeContext.credentialFingerprint,
    };
    if (!slackFileUploadReceiptPayload(payload)) {
      throw new Error("Slack file upload receipt was malformed");
    }
    const providerActionId = `slack-file-receipt:${input.publication.id}:${publicationAttempt}`;
    const recordedAt = new Date();
    return db.transaction(async (tx) => {
      await input.credentialLease.assertOwned(tx);
      const publication = await tx
        .select({ id: chatPublications.id })
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.id, input.publication.id),
            eq(chatPublications.companyId, input.publication.companyId),
            eq(chatPublications.endpointId, input.publication.endpointId),
            eq(
              chatPublications.conversationId,
              input.publication.conversationId,
            ),
            eq(chatPublications.state, "streaming"),
            eq(chatPublications.attempts, publicationAttempt),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const endpoint = publication
        ? await runtimeCallbackEndpoint(
            tx,
            input.endpoint.id,
            input.runtimeContext,
            ["verifying", "active"],
          )
        : null;
      const conversation = endpoint
        ? await tx
            .select({
              externalThreadId: chatConversations.externalThreadId,
              id: chatConversations.id,
            })
            .from(chatConversations)
            .where(
              and(
                eq(chatConversations.id, input.conversation.id),
                eq(chatConversations.companyId, input.publication.companyId),
                eq(chatConversations.endpointId, input.endpoint.id),
                inArray(chatConversations.state, [
                  "active",
                  "waiting",
                  "completed",
                ]),
              ),
            )
            .for("no key update")
            .then((rows) => rows[0] ?? null)
        : null;
      if (
        !publication ||
        endpoint?.provider !== "slack" ||
        endpoint.botExternalId !== botExternalId ||
        conversation?.externalThreadId !== expectedThreadId
      ) {
        throw new Error(
          "Slack file upload ownership changed before receipt persistence",
        );
      }
      const inserted = await tx
        .insert(chatActions)
        .values({
          companyId: input.publication.companyId,
          endpointId: input.publication.endpointId,
          conversationId: input.publication.conversationId,
          kind: "slack_file_upload_receipt",
          providerActionId,
          payload,
          status: "received",
          result: { code: "slack_file_upload_identity_pending", attempts: 0 },
          createdAt: recordedAt,
          updatedAt: recordedAt,
        })
        .onConflictDoNothing()
        .returning({ id: chatActions.id });
      if (inserted[0]) {
        await input.credentialLease.assertOwned(tx);
        return inserted[0].id;
      }
      const existing = await tx
        .select({ id: chatActions.id })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, input.publication.endpointId),
            eq(chatActions.providerActionId, providerActionId),
            eq(chatActions.kind, "slack_file_upload_receipt"),
            sql`${chatActions.payload} = ${JSON.stringify(payload)}::jsonb`,
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!existing) {
        throw new Error(
          "Slack file upload receipt conflicted with durable state",
        );
      }
      await input.credentialLease.assertOwned(tx);
      return existing.id;
    });
  }

  async function recordExactOutboundPublicationLink(
    tx: DbOrTransaction,
    input: {
      publication: typeof chatPublications.$inferSelect;
      providerMessageId: string;
    },
  ): Promise<boolean> {
    const inserted = await tx
      .insert(chatMessageLinks)
      .values({
        companyId: input.publication.companyId,
        endpointId: input.publication.endpointId,
        conversationId: input.publication.conversationId,
        publicationId: input.publication.id,
        commentId: input.publication.commentId,
        providerMessageId: input.providerMessageId,
        direction: "outbound",
      })
      .onConflictDoNothing()
      .returning({ id: chatMessageLinks.id });
    if (inserted.length) return true;
    return tx
      .select({ id: chatMessageLinks.id })
      .from(chatMessageLinks)
      .where(
        and(
          eq(chatMessageLinks.companyId, input.publication.companyId),
          eq(chatMessageLinks.endpointId, input.publication.endpointId),
          eq(chatMessageLinks.conversationId, input.publication.conversationId),
          eq(chatMessageLinks.publicationId, input.publication.id),
          input.publication.commentId
            ? eq(chatMessageLinks.commentId, input.publication.commentId)
            : isNull(chatMessageLinks.commentId),
          eq(chatMessageLinks.providerMessageId, input.providerMessageId),
          eq(chatMessageLinks.direction, "outbound"),
        ),
      )
      .limit(1)
      .then((rows) => rows.length > 0);
  }

  async function stageSlackFilePublicationSuccess(
    tx: DbTransaction,
    input: {
      committedAt: Date;
      endpoint: EndpointRow;
      publication: typeof chatPublications.$inferSelect;
      providerMessageId: string;
      runtimeContext: LifecycleRuntimeFence;
      stageSessionSync: boolean;
    },
  ): Promise<void> {
    if (
      !(await recordExactOutboundPublicationLink(tx, {
        publication: input.publication,
        providerMessageId: input.providerMessageId,
      }))
    ) {
      throw new Error(
        "Slack file upload message identity conflicts with another publication",
      );
    }
    await tx
      .update(chatEndpoints)
      .set({
        lastPublicationAt: input.committedAt,
        updatedAt: input.committedAt,
      })
      .where(
        and(
          eq(chatEndpoints.id, input.endpoint.id),
          inArray(chatEndpoints.status, ["verifying", "active"]),
          sql`coalesce((${chatEndpoints.setup}->>'runtimeGeneration')::integer, 0) = ${input.runtimeContext.generation}`,
        ),
      );
    if (input.stageSessionSync) {
      await stageSlackSessionSync(tx, {
        companyId: input.publication.companyId,
        endpointId: input.publication.endpointId,
        conversationId: input.publication.conversationId,
        runtimeGeneration: input.runtimeContext.generation,
        credentialFingerprint: input.runtimeContext.credentialFingerprint,
      });
    }
  }

  function telegramStopSubscriptionScope(
    endpoint: EndpointRow,
    context: LifecycleRuntimeFence,
  ) {
    if (
      endpoint.provider !== "telegram" ||
      !endpoint.botExternalId ||
      !webhookPublicBaseUrl
    )
      return null;
    const webhookUrlSha256 = createHash("sha256")
      .update(
        `${webhookPublicBaseUrl}/api/chat-webhooks/${endpoint.publicId}/telegram`,
      )
      .digest("hex");
    return {
      version: 1,
      botUserId: endpoint.botExternalId,
      runtimeGeneration: context.generation,
      credentialFingerprint: context.credentialFingerprint,
      webhookUrlSha256,
    };
  }

  async function hasTelegramStopSubscription(
    endpoint: EndpointRow,
    context: LifecycleRuntimeFence,
  ): Promise<boolean> {
    const scope = telegramStopSubscriptionScope(endpoint, context);
    if (!scope) return false;
    const [receipt] = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, endpoint.companyId),
          eq(chatActions.endpointId, endpoint.id),
          eq(chatActions.kind, "telegram_stop_subscription"),
          eq(
            chatActions.providerActionId,
            `telegram-stop-subscription:${scope.runtimeGeneration}:${scope.credentialFingerprint}:${scope.webhookUrlSha256}`,
          ),
          eq(chatActions.status, "processed"),
        ),
      )
      .limit(1);
    return (
      !!receipt &&
      receipt.result?.code === "telegram_stop_subscription_confirmed" &&
      Object.keys(receipt.payload).length === Object.keys(scope).length &&
      Object.entries(scope).every(
        ([key, value]) => receipt.payload[key] === value,
      )
    );
  }

  async function recordTelegramStopSubscription(
    endpoint: EndpointRow,
    context: LifecycleRuntimeFence,
    lease: CredentialMutationLeaseGuard,
  ): Promise<void> {
    const scope = telegramStopSubscriptionScope(endpoint, context);
    if (!scope)
      throw new Error("Telegram Stop subscription scope is unavailable");
    await db.transaction(async (tx) => {
      await lease.assertOwned(tx);
      const current = await runtimeCallbackEndpoint(tx, endpoint.id, context, [
        "verifying",
        "active",
      ]);
      if (
        !current ||
        current.botExternalId !== scope.botUserId ||
        current.publicId !== endpoint.publicId
      )
        throw new Error("Telegram Stop subscription ownership changed");
      const [connection] = await tx
        .select()
        .from(toolConnections)
        .where(
          and(
            eq(toolConnections.id, current.connectionId),
            eq(toolConnections.companyId, current.companyId),
          ),
        )
        .for("share");
      if (
        !connection?.enabled ||
        connection.status !== "active" ||
        credentialFingerprint(connection.credentialSecretRefs) !==
          context.credentialFingerprint
      )
        throw new Error(
          "Telegram Stop subscription credential ownership changed",
        );
      await tx
        .insert(chatActions)
        .values({
          companyId: endpoint.companyId,
          endpointId: endpoint.id,
          kind: "telegram_stop_subscription",
          providerActionId: `telegram-stop-subscription:${scope.runtimeGeneration}:${scope.credentialFingerprint}:${scope.webhookUrlSha256}`,
          payload: scope,
          status: "processed",
          result: { code: "telegram_stop_subscription_confirmed" },
        })
        .onConflictDoUpdate({
          target: [chatActions.endpointId, chatActions.providerActionId],
          set: {
            payload: scope,
            status: "processed",
            result: { code: "telegram_stop_subscription_confirmed" },
            updatedAt: new Date(),
          },
        });
      await lease.assertOwned(tx);
    });
  }

  async function repairTelegramStopSubscription(
    endpoint: EndpointRow,
    payload: TelegramMaintenancePayload,
    lease: CredentialMutationLeaseGuard,
  ): Promise<void> {
    const plainObject = (value: unknown): Record<string, unknown> =>
      value !== null && typeof value === "object" && !Array.isArray(value)
        ? (value as Record<string, unknown>)
        : {};
    const context = {
      generation: payload.runtimeGeneration,
      credentialFingerprint: payload.credentialFingerprint,
    };
    const scope = telegramStopSubscriptionScope(endpoint, context);
    const reject = () =>
      Object.assign(
        new Error(
          "Telegram subscription cannot be safely upgraded under current ownership",
        ),
        {
          code: "CHAT_PROVIDER_PRETRANSPORT_REJECTED",
        },
      );
    if (
      !scope ||
      scope.webhookUrlSha256 !== payload.webhookUrlSha256 ||
      scope.botUserId !== payload.botUserId
    )
      throw reject();
    const assertCurrent = async () =>
      db.transaction(async (tx) => {
        await lease.assertOwned(tx);
        const current = await runtimeCallbackEndpoint(
          tx,
          endpoint.id,
          context,
          ["active"],
        );
        if (
          !current ||
          current.companyId !== endpoint.companyId ||
          current.botExternalId !== scope.botUserId ||
          current.publicId !== endpoint.publicId
        )
          throw reject();
        const [connection] = await tx
          .select()
          .from(toolConnections)
          .where(
            and(
              eq(toolConnections.id, current.connectionId),
              eq(toolConnections.companyId, current.companyId),
            ),
          )
          .for("share");
        if (
          !connection?.enabled ||
          connection.status !== "active" ||
          credentialFingerprint(connection.credentialSecretRefs) !==
            context.credentialFingerprint
        )
          throw reject();
        await lease.assertOwned(tx);
      });
    await assertCurrent();
    // A recovered providerConfirmed flag is not a subscription capability.
    // Only the separately committed exact current receipt can avoid fresh I/O.
    if (await hasTelegramStopSubscription(endpoint, context)) return;
    const credentials = await resolveCredentials(endpoint);
    if (
      !credentials.botToken ||
      typeof credentials.webhookSecret !== "string" ||
      !/^[A-Za-z0-9_-]{1,256}$/.test(credentials.webhookSecret)
    )
      throw reject();
    const request = async (
      method: "getMe" | "getWebhookInfo" | "setWebhook",
      body: Record<string, unknown> = {},
    ) => {
      await assertCurrent();
      let response: Response;
      try {
        response = await fetchImpl(
          `https://api.telegram.org/bot${encodeURIComponent(credentials.botToken!)}/${method}`,
          {
            method: "POST",
            redirect: "error",
            signal: AbortSignal.timeout(PROVIDER_CREDENTIAL_CHECK_TIMEOUT_MS),
            headers: { "content-type": "application/json" },
            body: JSON.stringify(body),
          },
        );
      } catch {
        // Network errors can embed a token-bearing URL. Keep maintenance
        // diagnostics closed rather than forwarding provider/transport prose.
        throw new Error(
          "Telegram subscription transport did not confirm completion",
        );
      }
      let value: unknown;
      try {
        value = await response.json();
      } catch {
        throw new Error("Telegram subscription returned an invalid response");
      }
      const result = plainObject(value);
      if (!response.ok || result.ok !== true) {
        const retryAfter = plainObject(result.parameters).retry_after;
        throw Object.assign(
          new Error("Telegram subscription request was not confirmed"),
          response.status === 429
            ? {
                adapter: "telegram",
                code: "RATE_LIMITED",
                name: "AdapterRateLimitError",
                retryAfter:
                  typeof retryAfter === "number" && Number.isFinite(retryAfter)
                    ? retryAfter
                    : undefined,
                response: {
                  status: response.status,
                  headers: response.headers,
                },
              }
            : {
                adapter: "telegram",
                status: response.status,
                response: {
                  status: response.status,
                  headers: response.headers,
                },
              },
        );
      }
      return result.result;
    };
    const identity = plainObject(await request("getMe"));
    if (
      identity.is_bot !== true ||
      !Number.isSafeInteger(identity.id) ||
      String(identity.id) !== scope.botUserId
    )
      throw reject();
    const url = `${webhookPublicBaseUrl}/api/chat-webhooks/${endpoint.publicId}/telegram`;
    const plan = telegramStopSubscriptionPlan(
      await request("getWebhookInfo"),
      url,
    );
    if (!plan) throw reject();
    // No URL repoint, credential rotation, certificate guess, IP pin, or queue
    // dropping. A successful SET proves the stored secret; GET cannot do so.
    if (
      (await request("setWebhook", {
        url,
        secret_token: credentials.webhookSecret,
        ...plan,
        drop_pending_updates: false,
      })) !== true
    )
      throw new Error("Telegram subscription mutation was not confirmed");
    if (
      !telegramStopSubscriptionConfirmed(
        await request("getWebhookInfo"),
        url,
        plan,
      )
    )
      throw new Error("Telegram subscription verification changed");
    await assertCurrent();
    await recordTelegramStopSubscription(endpoint, context, lease);
  }

  async function handleTelegramGenerationStopped(
    callback: ChatSdkCallbackEvent<TelegramGenerationStoppedProof>,
    context: RuntimeContext,
  ): Promise<void> {
    const receipt = telegramGenerationStoppedReceipt(callback.event);
    if (callback.provider !== "telegram" || !receipt) return;
    const record = await runtimeCallbackRecord(callback.endpointId, context, [
      "verifying",
      "active",
    ]);
    if (
      record?.endpoint.provider !== "telegram" ||
      record.endpoint.botExternalId !== receipt.botUserId
    )
      return;
    const candidates = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, record.endpoint.companyId),
          eq(chatActions.endpointId, callback.endpointId),
          eq(chatActions.kind, TELEGRAM_DRAFT_ACTION_KIND),
          sql`${chatActions.payload}->>'botUserId' = ${receipt.botUserId}`,
          sql`${chatActions.payload}->>'draftId' = ${String(receipt.draftId)}`,
        ),
      )
      .limit(2);
    if (candidates.length !== 1) return;
    const candidate = candidates[0]!;
    const binding = parseTelegramDraftBinding(candidate.payload);
    if (
      !binding ||
      binding.chatId !== receipt.chatId ||
      binding.messageThreadId !== receipt.messageThreadId ||
      binding.runtimeGeneration !== context.generation ||
      binding.credentialFingerprint !== context.credentialFingerprint
    )
      return;
    await db.transaction(async (tx) => {
      // The sender holds a renewable credential lease during draft HTTP. Do
      // not acquire that lease here: a Stop can arrive inside the first RPC.
      // Both Stop and final-send use the publication→endpoint→draft lock order.
      const publication = await tx
        .select()
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, record.endpoint.companyId),
            eq(chatPublications.endpointId, callback.endpointId),
            eq(chatPublications.conversationId, binding.conversationId),
            eq(chatPublications.id, binding.publicationId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      const endpoint = await runtimeCallbackEndpoint(
        tx,
        callback.endpointId,
        context,
        ["verifying", "active"],
      );
      if (
        !publication ||
        !endpoint ||
        endpoint.provider !== "telegram" ||
        endpoint.botExternalId !== receipt.botUserId ||
        runtime.get(endpoint.id) !== context.endpointRuntime ||
        publication.attempts !== binding.publicationAttempt ||
        telegramDraftTextSha256(
          renderPublicationTransportText(publication.payload),
        ) !== binding.textSha256
      )
        return;
      const connection = await tx
        .select()
        .from(toolConnections)
        .where(
          and(
            eq(toolConnections.companyId, endpoint.companyId),
            eq(toolConnections.id, endpoint.connectionId),
          ),
        )
        .for("share")
        .then((rows) => rows[0] ?? null);
      if (
        !connection?.enabled ||
        connection.status !== "active" ||
        credentialFingerprint(connection.credentialSecretRefs) !==
          binding.credentialFingerprint
      )
        return;
      const conversation = await tx
        .select()
        .from(chatConversations)
        .where(
          and(
            eq(chatConversations.companyId, endpoint.companyId),
            eq(chatConversations.endpointId, endpoint.id),
            eq(chatConversations.id, binding.conversationId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (
        !conversation ||
        !conversation.isDirectMessage ||
        conversation.sessionGeneration !== binding.sessionGeneration ||
        conversation.externalThreadId !==
          `telegram:${binding.chatId}${binding.messageThreadId === null ? "" : `:${binding.messageThreadId}`}`
      )
        return;
      const action = await tx
        .select()
        .from(chatActions)
        .where(eq(chatActions.id, candidate.id))
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (
        !action ||
        JSON.stringify(action.payload) !== JSON.stringify(candidate.payload)
      )
        return;
      // final_sending is an irreversible local I/O claim, not a delivery
      // receipt. A late Stop must not claim that an in-flight final was undone.
      if (
        action.result?.phase !== "drafting" ||
        action.status !== "processing" ||
        !["streaming", "delivery_unknown"].includes(publication.state)
      )
        return;
      const stoppedAt = new Date();
      await tx
        .update(chatActions)
        .set({
          status: "cancelled",
          result: {
            phase: "stopped",
            updateId: receipt.updateId,
            stoppedAt: stoppedAt.toISOString(),
          },
          updatedAt: stoppedAt,
        })
        .where(eq(chatActions.id, action.id));
      await tx
        .update(chatPublications)
        .set({
          state: "cancelled",
          nextAttemptAt: null,
          redactedError: TELEGRAM_DRAFT_STOPPED_REASON,
          updatedAt: stoppedAt,
        })
        .where(eq(chatPublications.id, publication.id));
      await tx
        .update(chatActions)
        .set({
          status: "cancelled",
          result: {
            code: "telegram_draft_presentation_stopped",
            attempts: publication.attempts,
          },
          updatedAt: stoppedAt,
        })
        .where(
          and(
            eq(chatActions.companyId, publication.companyId),
            eq(chatActions.endpointId, publication.endpointId),
            eq(
              chatActions.providerActionId,
              `task-control-authorization:${publication.id}`,
            ),
            eq(chatActions.status, "processing"),
            sql`${chatActions.result}->>'attempts' = ${String(publication.attempts)}`,
          ),
        );
    });
  }

  async function reserveTelegramPublicationDraft(input: {
    endpoint: EndpointRow;
    conversation: ConversationRow;
    publication: typeof chatPublications.$inferSelect;
    text: string;
    credentialLease: CredentialMutationLeaseGuard;
    runtimeContext: RuntimeContext;
  }): Promise<{ actionId: string; control: TelegramDraftControl }> {
    const endpointRuntime = await runtimeFor(input.endpoint);
    const registeredContext = runtimeContexts.get(endpointRuntime as object);
    if (
      !registeredContext ||
      registeredContext.generation !== input.runtimeContext.generation ||
      registeredContext.credentialFingerprint !==
        input.runtimeContext.credentialFingerprint ||
      registeredContext.version !== input.runtimeContext.version
    )
      throw new Error("Telegram draft runtime authority changed");
    const draftRuntimeContext = { ...input.runtimeContext, endpointRuntime };
    const destination = telegramPrivateDraftDestination(
      input.conversation.externalThreadId,
    );
    if (
      !destination ||
      !input.conversation.isDirectMessage ||
      !input.endpoint.botExternalId
    )
      throw new Error("Telegram private draft destination is invalid");
    const bindingBase = {
      version: 1 as const,
      publicationId: input.publication.id,
      publicationAttempt: input.publication.attempts + 1,
      conversationId: input.conversation.id,
      sessionGeneration: input.conversation.sessionGeneration,
      runtimeGeneration: input.runtimeContext.generation,
      credentialFingerprint: input.runtimeContext.credentialFingerprint,
      botUserId: input.endpoint.botExternalId,
      ...destination,
      textSha256: telegramDraftTextSha256(input.text),
    };
    const reserved = await db.transaction(async (tx) => {
      await input.credentialLease.assertOwned(tx);
      const publication = await tx
        .select()
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.id, input.publication.id),
            eq(chatPublications.state, "streaming"),
            eq(chatPublications.attempts, bindingBase.publicationAttempt),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!publication)
        throw new Error("Telegram draft publication ownership changed");
      const providerActionId = `telegram-draft-publication:${publication.id}:${publication.attempts}`;
      const existing = await tx
        .select({ id: chatActions.id })
        .from(chatActions)
        .where(
          and(
            eq(chatActions.endpointId, input.endpoint.id),
            eq(chatActions.providerActionId, providerActionId),
          ),
        )
        .limit(1);
      // A second invocation of the same attempt cannot create another draft or
      // replay an uncertain final. A new explicit publication attempt gets a
      // fresh, never-before-used bot-global ID.
      if (existing.length)
        throw new Error("Telegram draft attempt already exists");
      // NO CYCLE and no company/endpoint ownership: rollback, endpoint deletion
      // and bot re-binding cannot recycle a provider-visible draft identity.
      // Exhaustion is a refusal, never a fallback to a process-local/random ID.
      const allocated = await tx.execute(
        sql`select nextval('chat_telegram_draft_ids')::integer as "draftId"`,
      );
      const binding = parseTelegramDraftBinding({
        ...bindingBase,
        draftId: allocated[0]?.draftId,
      });
      if (!binding)
        throw new Error("Telegram draft identity allocation was invalid");
      const [action] = await tx
        .insert(chatActions)
        .values({
          companyId: input.endpoint.companyId,
          endpointId: input.endpoint.id,
          conversationId: input.conversation.id,
          kind: TELEGRAM_DRAFT_ACTION_KIND,
          providerActionId,
          payload: binding,
          status: "issued",
          result: { phase: "reserved" },
        })
        .returning();
      return { action: action!, binding };
    });
    const before = (final: boolean): Promise<boolean> =>
      db.transaction(async (tx) => {
        await input.credentialLease.assertOwned(tx);
        const publication = await tx
          .select()
          .from(chatPublications)
          .where(
            and(
              eq(chatPublications.companyId, input.endpoint.companyId),
              eq(chatPublications.id, input.publication.id),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        const endpoint = await runtimeCallbackEndpoint(
          tx,
          input.endpoint.id,
          draftRuntimeContext,
          ["verifying", "active"],
        );
        if (
          !endpoint ||
          endpoint.provider !== "telegram" ||
          !endpoint.allowDirectMessages ||
          endpoint.botExternalId !== reserved.binding.botUserId ||
          runtime.get(endpoint.id) !== endpointRuntime
        )
          throw new Error("Telegram draft endpoint authority changed");
        const connection = await tx
          .select()
          .from(toolConnections)
          .where(
            and(
              eq(toolConnections.companyId, endpoint.companyId),
              eq(toolConnections.id, endpoint.connectionId),
            ),
          )
          .for("share")
          .then((rows) => rows[0] ?? null);
        if (
          !connection?.enabled ||
          connection.status !== "active" ||
          credentialFingerprint(connection.credentialSecretRefs) !==
            reserved.binding.credentialFingerprint
        )
          throw new Error("Telegram draft credential authority changed");
        const conversation = await tx
          .select()
          .from(chatConversations)
          .where(
            and(
              eq(chatConversations.companyId, endpoint.companyId),
              eq(chatConversations.endpointId, endpoint.id),
              eq(chatConversations.id, input.conversation.id),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null);
        const action = await tx
          .select()
          .from(chatActions)
          .where(eq(chatActions.id, reserved.action.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (
          !action ||
          JSON.stringify(action.payload) !==
            JSON.stringify(reserved.action.payload) ||
          !publication ||
          publication.attempts !== reserved.binding.publicationAttempt
        )
          throw new Error("Telegram draft attempt authority changed");
        if (
          action.status === "cancelled" &&
          action.result?.phase === "stopped" &&
          publication.state === "cancelled"
        )
          return false;
        if (
          publication.state !== "streaming" ||
          !conversation ||
          telegramDraftTextSha256(
            renderPublicationTransportText(publication.payload),
          ) !== reserved.binding.textSha256 ||
          conversation.sessionGeneration !==
            reserved.binding.sessionGeneration ||
          conversation.externalThreadId !==
            input.conversation.externalThreadId ||
          !["active", "waiting", "completed"].includes(conversation.state) ||
          !["reserved", "drafting"].includes(String(action.result?.phase)) ||
          !["issued", "processing"].includes(action.status) ||
          !(await authorizeRetainedChatSourcePublication(tx, publication))
        )
          throw new Error("Telegram draft source authority changed");
        await tx
          .update(chatActions)
          .set({
            status: "processing",
            result: {
              phase: final ? "final_sending" : "drafting",
            },
            updatedAt: new Date(),
          })
          .where(eq(chatActions.id, action.id));
        await input.credentialLease.assertOwned(tx);
        return true;
      });
    return {
      actionId: reserved.action.id,
      control: {
        version: 1,
        draftId: reserved.binding.draftId,
        beforeDraft: () => before(false),
        beforeFinal: () => before(true),
      },
    };
  }

  async function postSafePublication(input: {
    endpoint: EndpointRow;
    conversation: ConversationRow;
    publication: typeof chatPublications.$inferSelect;
    payload: SafeChatPublicationPayload;
    replaceProviderMessageId?: string | null;
    telegramDraftControl?: TelegramDraftControl;
    onSlackFileUploadAccepted?: (
      receipt: SlackFileUploadAcceptedReceipt,
    ) => Promise<void>;
  }) {
    const endpointRuntime = await runtimeFor(input.endpoint);
    const thread = endpointRuntime.thread(input.conversation.externalThreadId);
    const card = safeCardForPublication(input.payload, input.endpoint.provider);
    let attachments: Attachment[] = [];
    let files: FileUpload[] = [];
    let text = renderPublicationTransportText(input.payload);
    if (input.payload.attachmentIds?.length) {
      if (
        input.endpoint.provider === "microsoft-teams" &&
        !input.conversation.isDirectMessage
      ) {
        // The staged personal-file lane remains authoritative for consent.
        // Channel/group pictures need no OneDrive upload or public asset URL:
        // send only verified original picture bytes through the native adapter.
        const candidates = await publicationFiles(
          input.publication,
          input.payload,
          { teamsInlineImagesOnly: true },
        );
        const pictures = await Promise.all(
          candidates.map(prepareTeamsInlineImage),
        );
        if (pictures.length && pictures.every((picture) => picture !== null)) {
          files = pictures;
        }
      }
      const nativeFileSurface =
        CAPABILITIES[input.endpoint.provider].files &&
        input.endpoint.provider !== "microsoft-teams";
      if (nativeFileSurface) {
        const uploads = await publicationFiles(
          input.publication,
          input.payload,
        );
        if (input.endpoint.provider === "telegram") {
          attachments = await Promise.all(
            uploads.map(telegramAttachmentForUpload),
          );
        } else {
          files = uploads;
        }
      } else if (files.length === 0) {
        const taskUrl = safeChatTaskUrl(
          options.publicBaseUrl,
          input.publication.issueId,
        );
        if (
          input.endpoint.provider === "github" ||
          input.endpoint.provider === "microsoft-teams"
        ) {
          // GitHub lacks a bot upload contract. Teams reaches this fallback
          // only without an admissible personal-consent destination. Replace
          // our generated caption, preserving any future custom text.
          const generatedFileLabel = /^Shared (.+)\.$/s.exec(text)?.[1] ?? null;
          const limitation =
            input.endpoint.provider === "github"
              ? "This GitHub App connection cannot upload file bytes into comments."
              : "Direct file delivery isn't available for this Teams conversation.";
          if (generatedFileLabel) {
            const saved = taskUrl
              ? `File saved on the Paperclip task: ${generatedFileLabel}.`
              : `File saved on the private Paperclip task: ${generatedFileLabel}.`;
            text = taskUrl
              ? `${saved} ${limitation} Download it: ${taskUrl}`
              : `${saved} ${limitation}`;
          } else {
            const handoff = taskUrl
              ? `Open the file on its Paperclip task: ${taskUrl}`
              : "The file remains available only on the private Paperclip task.";
            text = `${text}\n\n${limitation} ${handoff}`;
          }
        } else {
          const attachmentFallback = taskUrl
            ? `Open the task in Paperclip: ${taskUrl}`
            : "Open the task in Paperclip to download the attachment.";
          text = `${text}\n\n${attachmentFallback}`;
        }
      }
    }
    if (
      input.endpoint.provider === "discord" &&
      input.payload.transportPart?.mode === "discord_markdown_attachment"
    ) {
      files.push(discordMarkdownAttachment(text));
      text =
        input.payload.transportPart.count > 1
          ? "Complete response attached."
          : "Paperclip attached the complete response because it exceeds Discord’s message limit.";
    }
    if (
      input.endpoint.provider === "telegram" &&
      input.payload.transportPart?.mode === "telegram_markdown_attachment"
    ) {
      attachments.push(telegramMarkdownAttachment(text));
      text =
        input.payload.transportPart.count > 1
          ? "Complete response attached."
          : "Paperclip attached the complete response to preserve its Markdown formatting.";
    }
    if (card && CAPABILITIES[input.endpoint.provider].cards) {
      return await attemptProviderPublication(async () =>
        input.replaceProviderMessageId
          ? await editOrPostProviderPublication(
              () =>
                thread.adapter.editMessage(
                  thread.id,
                  input.replaceProviderMessageId!,
                  {
                    card,
                    fallbackText: text,
                    ...(files.length ? { files } : {}),
                  },
                ),
              () =>
                thread.post({
                  card,
                  fallbackText: text,
                  ...(files.length ? { files } : {}),
                }),
            )
          : await thread.post({
              card,
              fallbackText: text,
              ...(files.length ? { files } : {}),
            }),
      );
    }
    if (attachments.length) {
      const attachmentMessage: AdapterPostableMessage = {
        attachments,
        markdown: text,
      };
      return await attemptProviderPublication(async () =>
        input.replaceProviderMessageId
          ? await editOrPostProviderPublication(
              () =>
                thread.adapter.editMessage(
                  thread.id,
                  input.replaceProviderMessageId!,
                  attachmentMessage,
                ),
              () => thread.post(attachmentMessage),
            )
          : await thread.post(attachmentMessage),
      );
    }
    if (files.length) {
      // The pinned Slack adapter performs file upload and text publication as
      // two provider calls when both fields are present. A rate limit or
      // network failure on the second call would make an automatic retry
      // duplicate the already-shared file. File publications have their own
      // ordered outbox row, so Slack receives a single native upload here.
      const fileMessage: AdapterPostableMessage = {
        // Empty Slack markdown keeps the SDK call type-safe while its pinned
        // adapter treats this as a file-only upload and skips chat.postMessage.
        markdown: input.endpoint.provider === "slack" ? "" : text,
        files,
      };
      if (
        input.endpoint.provider === "slack" &&
        !input.replaceProviderMessageId &&
        !input.payload.card &&
        !input.payload.interactionId &&
        !input.publication.idempotencyKey.startsWith("control:") &&
        input.payload.attachmentIds?.length &&
        input.onSlackFileUploadAccepted
      ) {
        return await attemptProviderPublication(
          async () =>
            await endpointRuntime.postSlackFilePublication(
              thread.id,
              fileMessage,
              input.onSlackFileUploadAccepted!,
            ),
        );
      }
      return await attemptProviderPublication(async () =>
        input.replaceProviderMessageId
          ? await editOrPostProviderPublication(
              () =>
                thread.adapter.editMessage(
                  thread.id,
                  input.replaceProviderMessageId!,
                  fileMessage,
                ),
              () => thread.post(fileMessage),
            )
          : await thread.post(fileMessage),
      );
    }
    if (
      !input.replaceProviderMessageId &&
      !input.payload.transportPart &&
      CAPABILITIES[input.endpoint.provider].nativeStreaming &&
      (input.endpoint.provider !== "telegram" ||
        !input.conversation.isDirectMessage ||
        input.telegramDraftControl !== undefined) &&
      shouldStreamSafePublicationText(text)
    ) {
      return await attemptProviderPublication(async () =>
        input.telegramDraftControl
          ? endpointRuntime.streamTelegramDraft(
              input.conversation.externalThreadId,
              streamSafePublicationText(text),
              input.telegramDraftControl,
            )
          : thread.post(streamSafePublicationText(text)),
      );
    }
    return await attemptProviderPublication(async () =>
      input.replaceProviderMessageId
        ? await editOrPostProviderPublication(
            () =>
              thread.adapter.editMessage(
                thread.id,
                input.replaceProviderMessageId!,
                { markdown: text },
              ),
            () => thread.post({ markdown: text }),
          )
        : await thread.post({ markdown: text }),
    );
  }

  /** Add navigation only from the exact accepted native input batch. The
   * omission text/model response is not authority, nor is an older task file. */
  async function githubCurrentOmissionPreparedText(
    tx: DbOrTransaction,
    publication: typeof chatPublications.$inferSelect,
    endpoint: EndpointRow,
  ): Promise<string | null | false> {
    if (endpoint.provider !== "github") return null;
    const preparationKey = `github-omission-navigation:${publication.id}`;
    const [prepared] = await tx
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.companyId, publication.companyId),
          eq(chatActions.endpointId, publication.endpointId),
          eq(chatActions.conversationId, publication.conversationId),
          eq(chatActions.providerActionId, preparationKey),
        ),
      )
      .limit(1);
    // A prepared final cannot become a different kind of publication while
    // retaining the decorated body. Check its receipt before these exclusions.
    if (
      !publication.commentId ||
      publication.payload.progressState !== undefined ||
      publication.payload.interactionId ||
      publication.payload.card ||
      publication.payload.attachmentIds?.length ||
      publication.payload.transportPart ||
      publication.idempotencyKey.startsWith("control:") ||
      isExplicitOperatorPublication(publication)
    )
      return prepared ? false : null;
    const taskUrl = prepared
      ? typeof prepared.payload.taskUrl === "string"
        ? safeChatTaskUrl(prepared.payload.taskUrl, publication.issueId)
        : null
      : safeChatTaskUrl(options.publicBaseUrl, publication.issueId);
    if (
      prepared &&
      (prepared.kind !== "github_omission_navigation" ||
        prepared.status !== "processed" ||
        prepared.payload.version !== 1 ||
        prepared.payload.publicationId !== publication.id ||
        taskUrl !== prepared.payload.taskUrl ||
        prepared.payload.preparedTextSha256 !==
          createHash("sha256").update(publication.payload.text).digest("hex"))
    )
      return false;
    if (!taskUrl) return prepared ? false : null;
    const [origin] = await tx
      .select({ run: heartbeatRuns, resultId: nativeRunFinalizations.resultId })
      .from(issueComments)
      .innerJoin(
        heartbeatRuns,
        and(
          eq(heartbeatRuns.id, issueComments.createdByRunId),
          eq(heartbeatRuns.companyId, publication.companyId),
          eq(heartbeatRuns.nativeIssueId, publication.issueId),
          eq(heartbeatRuns.agentId, endpoint.assignedAgentId),
          eq(heartbeatRuns.runtimeMode, "native"),
          eq(heartbeatRuns.status, "succeeded"),
          isNotNull(heartbeatRuns.finishedAt),
        ),
      )
      .innerJoin(
        nativeRunFinalizations,
        and(
          eq(nativeRunFinalizations.companyId, publication.companyId),
          eq(nativeRunFinalizations.issueId, publication.issueId),
          eq(nativeRunFinalizations.runId, heartbeatRuns.id),
          eq(nativeRunFinalizations.phase, "committed"),
        ),
      )
      .where(
        and(
          eq(issueComments.id, publication.commentId),
          eq(issueComments.companyId, publication.companyId),
          eq(issueComments.issueId, publication.issueId),
          eq(issueComments.authorAgentId, endpoint.assignedAgentId),
          isNull(issueComments.deletedAt),
        ),
      )
      .limit(1);
    const presentation = origin?.run.resultJson?.presentationDecision as
      Record<string, unknown> | undefined;
    if (!origin?.resultId || presentation?.commentId !== publication.commentId)
      return prepared ? false : null;
    if (
      prepared &&
      (prepared.payload.runId !== origin.run.id ||
        prepared.payload.resultId !== origin.resultId)
    )
      return false;
    try {
      // This existing publication proof includes the accepted response_wake
      // result, immutable owner/coalesced receipts, every current source,
      // runtime/generation, source edits/deletes and current principal access.
      const source = await failedChatRetrySource(tx, {
        companyId: publication.companyId,
        issueId: publication.issueId,
        agentId: origin.run.agentId,
        failedRunId: origin.run.id,
        publication: true,
        committedResponse: { resultId: origin.resultId },
      });
      if (
        source.endpointId !== endpoint.id ||
        source.conversationId !== publication.conversationId
      )
        return prepared ? false : null;
      const omitted = source.sources.some((entry) => {
        const count = (
          entry.omissionReasons as Record<string, unknown> | undefined
        )?.download_unavailable;
        return (
          typeof count === "number" && Number.isSafeInteger(count) && count > 0
        );
      });
      if (!omitted) return prepared ? false : null;
      if (prepared) return publication.payload.text;
      const text = publication.payload.text.includes(taskUrl)
        ? publication.payload.text
        : `${publication.payload.text}\n\n[Open this Paperclip task](${taskUrl})`;
      await tx.insert(chatActions).values({
        companyId: publication.companyId,
        endpointId: publication.endpointId,
        conversationId: publication.conversationId,
        kind: "github_omission_navigation",
        providerActionId: preparationKey,
        status: "processed",
        payload: {
          version: 1,
          publicationId: publication.id,
          runId: origin.run.id,
          resultId: origin.resultId,
          taskUrl,
          preparedTextSha256: createHash("sha256").update(text).digest("hex"),
        },
      });
      return text;
    } catch (error) {
      if (
        isExternalChatWaitAuthorizationContention(error) ||
        error instanceof NativeChatReviewPresentationContentionError
      )
        throw new NativeChatReviewPresentationContentionError();
      if (
        isExternalActionAuthorizationChange(error) ||
        (error &&
          typeof error === "object" &&
          "details" in error &&
          error.details &&
          typeof error.details === "object" &&
          "code" in error.details &&
          error.details.code === "chat_failed_run_retry_not_authorized")
      )
        return prepared ? false : null;
      throw new FailedChatRetryPublicationReadError();
    }
  }

  async function claimPublicationTransportAuthorization(input: {
    credentialLease: CredentialMutationLeaseGuard;
    endpoint: EndpointRow;
    publication: typeof chatPublications.$inferSelect;
    runtimeContext: LifecycleRuntimeFence;
  }): Promise<{
    authorizationActionId: string | null;
    conversation: ConversationRow;
    endpoint: EndpointRow;
    preparedText: string | null;
  } | null> {
    return db.transaction(async (tx) => {
      await input.credentialLease.assertOwned(tx);
      const currentPublication = await tx
        .select({ id: chatPublications.id })
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.id, input.publication.id),
            eq(chatPublications.state, "streaming"),
            eq(chatPublications.attempts, input.publication.attempts + 1),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!currentPublication) return null;
      try {
        if (
          !(await authorizeRetainedChatSourcePublication(tx, input.publication))
        )
          return null;
      } catch (error) {
        if (error instanceof NativeChatReviewPresentationContentionError)
          throw error;
        throw new FailedChatRetryPublicationReadError();
      }
      const attachmentFailureFence = attachmentFailureNoticeFence(
        input.publication.idempotencyKey,
      );
      if (
        attachmentFailureFence &&
        (attachmentFailureFence.generation !==
          input.runtimeContext.generation ||
          attachmentFailureFence.credentialFingerprint !==
            input.runtimeContext.credentialFingerprint)
      ) {
        return null;
      }
      const endpoint = await runtimeCallbackEndpoint(
        tx,
        input.publication.endpointId,
        input.runtimeContext,
        ["verifying", "active"],
      );
      const conversation = endpoint
        ? await tx
            .select()
            .from(chatConversations)
            .where(
              and(
                eq(chatConversations.companyId, endpoint.companyId),
                eq(chatConversations.endpointId, endpoint.id),
                eq(chatConversations.id, input.publication.conversationId),
                inArray(chatConversations.state, [
                  "active",
                  "waiting",
                  "completed",
                ]),
              ),
            )
            .for("update")
            .then((rows) => rows[0] ?? null)
        : null;
      const resource =
        endpoint && conversation?.resourceId && !conversation.isDirectMessage
          ? await tx
              .select()
              .from(chatEndpointResources)
              .where(
                and(
                  eq(chatEndpointResources.companyId, endpoint.companyId),
                  eq(chatEndpointResources.endpointId, endpoint.id),
                  eq(chatEndpointResources.id, conversation.resourceId),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null)
          : null;
      const attachmentFailureNoticeSuperseded =
        attachmentFailureFence && conversation
          ? await tx
              .select({ id: chatConversations.id })
              .from(chatConversations)
              .where(
                and(
                  eq(chatConversations.companyId, conversation.companyId),
                  eq(chatConversations.endpointId, conversation.endpointId),
                  eq(
                    chatConversations.externalThreadId,
                    conversation.externalThreadId,
                  ),
                  gt(
                    chatConversations.sessionGeneration,
                    conversation.sessionGeneration,
                  ),
                ),
              )
              .limit(1)
              .then((rows) => rows.length > 0)
          : false;
      const isTaskControl =
        input.publication.idempotencyKey.startsWith("control:");
      const providerVisibleCompletion =
        conversation?.state === "completed" &&
        !isExplicitOperatorPublication(input.publication) &&
        (await hasCommittedTaskControlCompletion(conversation.id, tx));
      const authorizationAction =
        endpoint && isTaskControl
          ? await tx
              .select()
              .from(chatActions)
              .where(
                and(
                  eq(chatActions.companyId, endpoint.companyId),
                  eq(chatActions.endpointId, endpoint.id),
                  eq(chatActions.conversationId, conversation?.id ?? ""),
                  eq(chatActions.kind, "task_control_authorization"),
                  eq(
                    chatActions.providerActionId,
                    `task-control-authorization:${input.publication.id}`,
                  ),
                  eq(chatActions.status, "issued"),
                ),
              )
              .for("update")
              .then((rows) => rows[0] ?? null)
          : null;
      const destinationAllowed =
        endpoint !== null &&
        conversation !== null &&
        (conversation.isDirectMessage
          ? endpoint.allowDirectMessages
          : nonDirectDestinationAllowed(endpoint, resource));
      if (
        !endpoint ||
        !conversation ||
        (attachmentFailureFence &&
          ((conversation.state !== "active" &&
            conversation.state !== "waiting") ||
            attachmentFailureNoticeSuperseded)) ||
        providerVisibleCompletion ||
        (isTaskControl && !authorizationAction?.principalId) ||
        !destinationAllowed
      ) {
        return null;
      }
      let authorizationActionId: string | null = null;
      if (
        input.publication.idempotencyKey.startsWith("wake:") &&
        !(await authorizeInboundWakePublication(tx, input.publication))
      )
        return null;
      // A native response alongside an older completion review has its own
      // narrow authorization. Recheck that exact proof, review and original
      // requester at the transport claim, including file publications whose
      // comment is the run's earlier internal attachment-selection comment.
      if (
        input.publication.commentId &&
        !isExplicitOperatorPublication(input.publication)
      ) {
        const [origin] = await tx
          .select({
            runId: heartbeatRuns.id,
            resultJson: heartbeatRuns.resultJson,
          })
          .from(issueComments)
          .innerJoin(
            heartbeatRuns,
            and(
              eq(heartbeatRuns.id, issueComments.createdByRunId),
              eq(heartbeatRuns.companyId, issueComments.companyId),
            ),
          )
          .where(
            and(
              eq(issueComments.id, input.publication.commentId),
              eq(issueComments.companyId, endpoint.companyId),
              eq(issueComments.issueId, input.publication.issueId),
            ),
          )
          .limit(1);
        if (
          origin?.resultJson?.finalizationReasonCode ===
          "governed_response_waiting"
        ) {
          try {
            if (
              !(await authorizeNativeChatReviewPresentation(
                tx as unknown as Db,
                {
                  companyId: endpoint.companyId,
                  issueId: input.publication.issueId,
                  runId: origin.runId,
                  resultJson: origin.resultJson,
                  destination: {
                    endpointId: endpoint.id,
                    conversationId: conversation.id,
                  },
                },
                "nonblocking",
              ))
            )
              return null;
          } catch (error) {
            if (isExternalChatWaitAuthorizationContention(error))
              throw new NativeChatReviewPresentationContentionError();
            throw error;
          }
        }
      }
      const preparedText = await githubCurrentOmissionPreparedText(
        tx,
        input.publication,
        endpoint,
      );
      if (preparedText === false) return null;
      if (authorizationAction?.principalId) {
        const authorization = await lockCurrentPrincipalAuthorization(
          tx,
          endpoint,
          authorizationAction.principalId,
        );
        if (!authorization.allowed) return null;
        const [claimedAuthorization] = await tx
          .update(chatActions)
          .set({
            status: "processing",
            result: {
              attempts: input.publication.attempts + 1,
              authorizedUserId: authorization.userId,
              credentialFingerprint: input.runtimeContext.credentialFingerprint,
              runtimeGeneration: input.runtimeContext.generation,
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, authorizationAction.id),
              eq(chatActions.status, "issued"),
            ),
          )
          .returning({ id: chatActions.id });
        if (!claimedAuthorization) return null;
        authorizationActionId = claimedAuthorization.id;
      }
      if (preparedText !== null) {
        // Persist the exact provider text before I/O. A retry must reuse this
        // body, not accumulate links or regenerate it from changed settings.
        await tx
          .update(chatPublications)
          .set({
            payload: { ...input.publication.payload, text: preparedText },
          })
          .where(eq(chatPublications.id, input.publication.id));
      }
      await input.credentialLease.assertOwned(tx);
      // The publication's streaming row plus the optional authorization action
      // are the durable transport claim. Their database locks are released
      // before provider I/O. The renewable credential lease intentionally
      // remains held so reconnect and reach mutations linearize after this
      // committed authorization snapshot and transport attempt.
      return {
        authorizationActionId,
        conversation,
        endpoint,
        preparedText,
      };
    });
  }

  function runIdFromMilestonePublication(
    publication: typeof chatPublications.$inferSelect,
  ): string | null {
    if (!publication.payload.progressState) return null;
    const match =
      /^run:([^:]+):(?:queued|working|waiting_for_input|completed|failed):/.exec(
        publication.idempotencyKey,
      );
    const runId = match?.[1] ?? null;
    // This identifier is also compared against a UUID column below. Old or
    // manually repaired rows must not be allowed to turn the global
    // publication sweep into a PostgreSQL cast error.
    return isUuidLike(runId) ? runId : null;
  }

  async function runOwnershipMilestoneSupersessionReason(
    publication: typeof chatPublications.$inferSelect,
  ): Promise<string | null> {
    const progress = publication.payload.progressState;
    if (
      !progress ||
      !["queued", "working", "waiting_for_input"].includes(progress)
    ) {
      return null;
    }
    const runId = runIdFromMilestonePublication(publication);
    if (!runId) return null;
    const run = await db.transaction(async (tx) => {
      // Use native finalization's issue -> run lock order. If terminalization
      // won, the current status suppresses this obsolete provider update. If
      // this short authorization snapshot wins, the progress was still true
      // at its durable send boundary and the later final remains authoritative.
      const currentIssue = await tx
        .select({ id: issues.id })
        .from(issues)
        .where(
          and(
            eq(issues.id, publication.issueId),
            eq(issues.companyId, publication.companyId),
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!currentIssue) return null;
      return tx
        .select({
          status: heartbeatRuns.status,
          errorCode: heartbeatRuns.errorCode,
        })
        .from(heartbeatRuns)
        .where(
          and(
            eq(heartbeatRuns.id, runId),
            eq(heartbeatRuns.companyId, publication.companyId),
            sql`${heartbeatRuns.contextSnapshot} ->> 'issueId' = ${publication.issueId}`,
          ),
        )
        .for("update")
        .then((rows) => rows[0] ?? null);
    });
    const baseProgressKey = `run:${runId}:${progress}:${publication.endpointId}`;
    const nativeProgressPrefix = `run:${runId}:working:${publication.endpointId}:native:`;
    const isTerminalizableProgress =
      (progress === "queued" || progress === "working") &&
      (publication.idempotencyKey === baseProgressKey ||
        publication.idempotencyKey.startsWith(nativeProgressPrefix));
    if (
      isTerminalizableProgress &&
      run &&
      ["succeeded", "interrupted", "failed", "cancelled", "timed_out"].includes(
        run.status,
      )
    ) {
      return "Run reached a terminal state before progress delivery";
    }
    // Match only the closed ownership-attention projection. Historical progress
    // without an extant run retains its existing delivery semantics.
    const ownershipBlocked =
      run?.status === "running" &&
      [
        "native_execution_ownership_unverified",
        "native_adopted_runner_authentication_timeout",
      ].includes(run.errorCode ?? "");
    if (progress === "waiting_for_input") {
      return ownershipBlocked
        ? null
        : "Run ownership attention no longer applies to the bound task";
    }
    return ownershipBlocked
      ? "Run progress was superseded by ownership recovery attention"
      : null;
  }

  async function providerProgressLaneConsumed(
    publication: typeof chatPublications.$inferSelect,
    providerMessageId: string,
  ): Promise<boolean> {
    // Published progress rows retain their old provider ID after an edit.
    // Consult that exact message's current outbound link, not the conversation
    // tail: an authored answer or failure has consumed the lane, while an
    // interleaved task-status update may still be replaced normally.
    const [consumed] = await db
      .select({ id: chatPublications.id })
      .from(chatMessageLinks)
      .innerJoin(
        chatPublications,
        and(
          eq(chatPublications.id, chatMessageLinks.publicationId),
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.issueId, publication.issueId),
          eq(chatPublications.providerMessageId, providerMessageId),
          eq(chatPublications.state, "published"),
        ),
      )
      .where(
        and(
          eq(chatMessageLinks.companyId, publication.companyId),
          eq(chatMessageLinks.endpointId, publication.endpointId),
          eq(chatMessageLinks.conversationId, publication.conversationId),
          eq(chatMessageLinks.direction, "outbound"),
          eq(chatMessageLinks.providerMessageId, providerMessageId),
          or(
            and(
              isNotNull(chatPublications.commentId),
              sql`${chatPublications.payload}->>'progressState' is null`,
            ),
            sql`${chatPublications.payload}->>'progressState' = 'failed'`,
          ),
        ),
      )
      .limit(1);
    return Boolean(consumed);
  }

  async function committedResponseMayReplaceFailure(
    publication: typeof chatPublications.$inferSelect,
    runId: string,
    providerMessageId: string,
  ): Promise<boolean> {
    if (
      !publication.commentId ||
      publication.payload.progressState !== undefined
    )
      return false;
    return db
      .transaction(async (tx) => {
        const [run] = await tx
          .select()
          .from(heartbeatRuns)
          .where(
            and(
              eq(heartbeatRuns.id, runId),
              eq(heartbeatRuns.companyId, publication.companyId),
              eq(heartbeatRuns.nativeIssueId, publication.issueId),
              eq(heartbeatRuns.runtimeMode, "native"),
              eq(heartbeatRuns.status, "succeeded"),
              isNotNull(heartbeatRuns.finishedAt),
            ),
          )
          .for("share", { noWait: true });
        const presentation = run?.resultJson?.presentationDecision as
          Record<string, unknown> | undefined;
        if (
          !run?.resultJson?.nativeCommittedChatResponse ||
          presentation?.commentId !== publication.commentId
        )
          return false;
        const [comment] = await tx
          .select({ id: issueComments.id })
          .from(issueComments)
          .where(
            and(
              eq(issueComments.id, publication.commentId!),
              eq(issueComments.companyId, publication.companyId),
              eq(issueComments.issueId, publication.issueId),
              eq(issueComments.createdByRunId, runId),
              eq(issueComments.authorAgentId, run.agentId),
              isNull(issueComments.deletedAt),
            ),
          )
          .for("share", { noWait: true });
        if (!comment) return false;
        const [priorAnswer] = await tx
          .select({ id: chatPublications.id })
          .from(chatPublications)
          .innerJoin(
            issueComments,
            and(
              eq(issueComments.id, chatPublications.commentId),
              eq(issueComments.companyId, publication.companyId),
              eq(issueComments.createdByRunId, runId),
            ),
          )
          .where(
            and(
              eq(chatPublications.companyId, publication.companyId),
              eq(chatPublications.endpointId, publication.endpointId),
              eq(chatPublications.conversationId, publication.conversationId),
              eq(chatPublications.issueId, publication.issueId),
              ne(chatPublications.id, publication.id),
              inArray(chatPublications.state, [
                "published",
                "streaming",
                "delivery_unknown",
              ]),
              sql`${chatPublications.payload}->>'progressState' is null`,
            ),
          )
          .limit(1);
        if (priorAnswer) return false;
        // A historical progress row can retain this ID after a later edit.
        // Only its CURRENT outbound link may grant this narrow exception; an
        // authored answer or another run's failure must remain consumed.
        const [failure] = await tx
          .select({ id: chatPublications.id })
          .from(chatMessageLinks)
          .innerJoin(
            chatPublications,
            and(
              eq(chatPublications.id, chatMessageLinks.publicationId),
              eq(chatPublications.companyId, publication.companyId),
              eq(chatPublications.endpointId, publication.endpointId),
              eq(chatPublications.conversationId, publication.conversationId),
              eq(chatPublications.issueId, publication.issueId),
              eq(chatPublications.providerMessageId, providerMessageId),
              eq(
                chatPublications.idempotencyKey,
                `run:${runId}:failed:${publication.endpointId}`,
              ),
              eq(chatPublications.state, "published"),
              isNull(chatPublications.commentId),
              sql`${chatPublications.payload}->>'progressState' = 'failed'`,
            ),
          )
          .where(
            and(
              eq(chatMessageLinks.companyId, publication.companyId),
              eq(chatMessageLinks.endpointId, publication.endpointId),
              eq(chatMessageLinks.conversationId, publication.conversationId),
              eq(chatMessageLinks.providerMessageId, providerMessageId),
              eq(chatMessageLinks.direction, "outbound"),
            ),
          );
        if (!failure) return false;
        // The marker is read from the authoritative run, never the publication
        // payload. Recheck accepted result/decision plus the complete current
        // source batch, actor, access and epoch before borrowing its failure lane.
        // The transport claim repeats those checks at the I/O boundary.
        return authorizeRetainedChatSourcePublication(tx, publication);
      })
      .catch((error: unknown) => {
        if (isExternalChatWaitAuthorizationContention(error))
          throw new NativeChatReviewPresentationContentionError();
        throw error;
      });
  }

  async function runPublicationToReplace(
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
  ): Promise<string | null> {
    if (payload.attachmentIds?.length) return null;
    const currentRunId =
      runIdFromMilestonePublication(publication) ??
      (publication.commentId
        ? await db
            .select({ runId: issueComments.createdByRunId })
            .from(issueComments)
            .where(eq(issueComments.id, publication.commentId))
            .then((rows) => rows[0]?.runId ?? null)
        : null);
    if (!currentRunId) return null;
    return db
      .select({
        id: chatPublications.id,
        commentId: chatPublications.commentId,
        providerMessageId: chatPublications.providerMessageId,
        payload: chatPublications.payload,
      })
      .from(chatPublications)
      .leftJoin(issueComments, eq(issueComments.id, chatPublications.commentId))
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.state, "published"),
          isNotNull(chatPublications.providerMessageId),
          or(
            like(chatPublications.idempotencyKey, `run:${currentRunId}:%`),
            eq(issueComments.createdByRunId, currentRunId),
          ),
        ),
      )
      .orderBy(desc(chatPublications.createdAt), desc(chatPublications.id))
      .then(async (rows) => {
        // Progress updates are one replaceable provider-message lane per run.
        // The first durable agent comment may turn that placeholder into the
        // terminal response, but later comments from the same run are distinct
        // user-visible outputs and must be posted separately. Re-editing the
        // placeholder for each comment silently erases the earlier replies.
        if (
          publication.commentId &&
          rows.some(
            (row) =>
              row.commentId !== null && row.payload.progressState === undefined,
          )
        )
          return null;
        const replacement = rows.find(
          (row) =>
            Boolean(row.providerMessageId) &&
            row.payload.progressState !== undefined,
        );
        if (!replacement?.providerMessageId) return null;
        if (
          (await providerProgressLaneConsumed(
            publication,
            replacement.providerMessageId,
          )) &&
          !(await committedResponseMayReplaceFailure(
            publication,
            currentRunId,
            replacement.providerMessageId,
          ))
        )
          return null;
        // Replacement identity belongs to the run, not to the provider-visible
        // tail. A status/control reply may legitimately interleave while the run
        // is active; making the tail the edit candidate would strand this run's
        // working placeholder forever. The query is bounded by endpoint,
        // conversation (the task generation), and run id, so an interleaved
        // control or another run can never donate its provider message here.
        return replacement.providerMessageId;
      });
  }

  async function receiptReactionCompletionRunId(
    tx: Db,
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
  ): Promise<string | null> {
    if (
      payload.progressState === "completed" ||
      payload.progressState === "failed"
    ) {
      return runIdFromMilestonePublication(publication);
    }
    if (publication.commentId) {
      const runId = await tx
        .select({ runId: issueComments.createdByRunId })
        .from(issueComments)
        .where(
          and(
            eq(issueComments.id, publication.commentId),
            eq(issueComments.companyId, publication.companyId),
          ),
        )
        .then((rows) => rows[0]?.runId ?? null);
      return isUuidLike(runId) ? runId : null;
    }
    if (
      payload.interactionId &&
      publication.idempotencyKey ===
        `interaction:${payload.interactionId}:${publication.endpointId}`
    ) {
      const runId = await tx
        .select({ runId: issueThreadInteractions.sourceRunId })
        .from(issueThreadInteractions)
        .where(
          and(
            eq(issueThreadInteractions.id, payload.interactionId),
            eq(issueThreadInteractions.companyId, publication.companyId),
            eq(issueThreadInteractions.issueId, publication.issueId),
          ),
        )
        .then((rows) => rows[0]?.runId ?? null);
      return isUuidLike(runId) ? runId : null;
    }
    return null;
  }

  async function inboundWakePublicationToReplace(
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
  ): Promise<string | null> {
    if (payload.attachmentIds?.length) return null;
    const notice = parseInboundWakePublicationKey(publication.idempotencyKey);
    let wakeId: string | null =
      notice && notice.state !== "queued" ? notice.wakeId : null;
    let runId = runIdFromMilestonePublication(publication);
    if (
      !notice &&
      !runId &&
      payload.interactionId &&
      publication.idempotencyKey ===
        `interaction:${payload.interactionId}:${publication.endpointId}`
    ) {
      const [interaction] = await db
        .select({ runId: issueThreadInteractions.sourceRunId })
        .from(issueThreadInteractions)
        .where(
          and(
            eq(issueThreadInteractions.id, payload.interactionId),
            eq(issueThreadInteractions.companyId, publication.companyId),
            eq(issueThreadInteractions.issueId, publication.issueId),
            inArray(issueThreadInteractions.kind, [
              "ask_user_questions",
              "request_confirmation",
            ]),
          ),
        );
      runId = interaction?.runId ?? null;
    }
    if (!notice && !runId && publication.commentId) {
      const [comment] = await db
        .select({ runId: issueComments.createdByRunId })
        .from(issueComments)
        .where(
          and(
            eq(issueComments.id, publication.commentId),
            eq(issueComments.companyId, publication.companyId),
            eq(issueComments.issueId, publication.issueId),
          ),
        );
      runId = comment?.runId ?? null;
    }
    let runContext: Record<string, unknown> | null = null;
    if (runId) {
      if (publication.commentId) {
        const [priorAnswer] = await db
          .select({ id: chatPublications.id })
          .from(chatPublications)
          .innerJoin(
            issueComments,
            eq(issueComments.id, chatPublications.commentId),
          )
          .where(
            and(
              eq(chatPublications.companyId, publication.companyId),
              eq(chatPublications.endpointId, publication.endpointId),
              eq(chatPublications.conversationId, publication.conversationId),
              eq(chatPublications.state, "published"),
              eq(issueComments.createdByRunId, runId),
              sql`${chatPublications.payload}->>'progressState' is null`,
            ),
          )
          .limit(1);
        if (priorAnswer) return null;
      }
      const [run] = await db
        .select({
          wakeId: heartbeatRuns.wakeupRequestId,
          context: heartbeatRuns.contextSnapshot,
        })
        .from(heartbeatRuns)
        .innerJoin(
          agentWakeupRequests,
          and(
            eq(agentWakeupRequests.id, heartbeatRuns.wakeupRequestId),
            eq(agentWakeupRequests.runId, heartbeatRuns.id),
            eq(agentWakeupRequests.companyId, heartbeatRuns.companyId),
            eq(agentWakeupRequests.agentId, heartbeatRuns.agentId),
            // Failed/cancelled is the admitted run's outcome, not loss of
            // its original admission. Its terminal milestone still owns
            // this exact lane even if no working update was sent first.
            ne(agentWakeupRequests.status, "skipped"),
          ),
        )
        .where(
          and(
            eq(heartbeatRuns.id, runId),
            eq(heartbeatRuns.companyId, publication.companyId),
            sql`${heartbeatRuns.contextSnapshot}->>'issueId' = ${publication.issueId}`,
          ),
        );
      wakeId = run?.wakeId ?? null;
      runContext = run?.context ?? null;
    }
    if (!wakeId) return null;
    const [queued] = await db
      .select({
        commentId: chatPublications.commentId,
        providerMessageId: chatPublications.providerMessageId,
      })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.issueId, publication.issueId),
          eq(chatPublications.state, "published"),
          isNotNull(chatPublications.providerMessageId),
          eq(
            chatPublications.idempotencyKey,
            inboundWakePublicationKey(
              wakeId,
              "queued",
              publication.endpointId,
              publication.conversationId,
            ),
          ),
        ),
      );
    if (!queued?.commentId || !queued.providerMessageId) return null;
    // The run helper may have rejected this same provider ID because its
    // queued/working placeholder is already an answer or terminal failure.
    // Falling back to the older wake row must not erase that newer output.
    if (
      await providerProgressLaneConsumed(publication, queued.providerMessageId)
    )
      return null;
    if (notice && notice.state !== "queued")
      return queued.commentId === publication.commentId
        ? queued.providerMessageId
        : null;
    // A deferred owner can be a Board wake into which the exact external
    // comment coalesced. The run must actually contain that source comment;
    // wake ID alone cannot authorize a different successor's edit lane.
    return runContext &&
      (runContext.wakeCommentId === queued.commentId ||
        runContext.commentId === queued.commentId ||
        (Array.isArray(runContext.wakeCommentIds) &&
          runContext.wakeCommentIds.includes(queued.commentId)))
      ? queued.providerMessageId
      : null;
  }

  async function stageTerminalReceiptReactionRemovals(
    tx: Db,
    input: {
      endpoint: EndpointRow;
      publication: typeof chatPublications.$inferSelect;
      payload: SafeChatPublicationPayload;
      runtimeContext: RuntimeContext;
      closedProgressRunId?: string;
    },
  ): Promise<string[]> {
    if (
      !["discord", "slack", "telegram", "github"].includes(
        input.endpoint.provider,
      )
    )
      return [];
    const runId =
      input.closedProgressRunId ??
      (await receiptReactionCompletionRunId(
        tx,
        input.publication,
        input.payload,
      ));
    if (!runId) return [];

    const receipts = await tx
      .select({
        actionId: chatActions.id,
        deliveryId: chatMessageLinks.deliveryId,
        payload: chatActions.payload,
        result: chatActions.result,
        status: chatActions.status,
        normalizedEvent: chatDeliveries.normalizedEvent,
      })
      .from(heartbeatRuns)
      .innerJoin(
        chatMessageLinks,
        and(
          eq(chatMessageLinks.companyId, heartbeatRuns.companyId),
          eq(chatMessageLinks.endpointId, input.publication.endpointId),
          eq(chatMessageLinks.conversationId, input.publication.conversationId),
          eq(chatMessageLinks.direction, "inbound"),
          or(
            sql`${chatMessageLinks.commentId}::text = ${heartbeatRuns.contextSnapshot} ->> 'wakeCommentId'`,
            sql`${chatMessageLinks.commentId}::text = ${heartbeatRuns.contextSnapshot} ->> 'commentId'`,
            sql`coalesce(${heartbeatRuns.contextSnapshot} -> 'wakeCommentIds', '[]'::jsonb) ? ${chatMessageLinks.commentId}::text`,
          ),
        ),
      )
      .leftJoin(
        chatDeliveries,
        and(
          eq(chatDeliveries.id, chatMessageLinks.deliveryId),
          eq(chatDeliveries.companyId, chatMessageLinks.companyId),
          eq(chatDeliveries.endpointId, chatMessageLinks.endpointId),
          eq(chatDeliveries.conversationId, chatMessageLinks.conversationId),
          ["slack", "telegram", "github"].includes(input.endpoint.provider)
            ? eq(chatDeliveries.state, "processed")
            : undefined,
        ),
      )
      .leftJoin(
        chatActions,
        and(
          eq(chatActions.endpointId, chatMessageLinks.endpointId),
          eq(chatActions.deliveryId, chatMessageLinks.deliveryId),
          eq(chatActions.kind, "receipt_reaction"),
          sql`${chatActions.providerActionId} = 'receipt_reaction:' || ${chatMessageLinks.deliveryId}::text`,
        ),
      )
      .where(
        and(
          eq(heartbeatRuns.id, runId),
          eq(heartbeatRuns.companyId, input.publication.companyId),
          eq(
            sql<string>`${heartbeatRuns.contextSnapshot} ->> 'issueId'`,
            input.publication.issueId,
          ),
        ),
      );
    const removals = receipts.flatMap((receipt) => {
      if (!receipt.deliveryId) return [];
      let payload = receipt.payload
        ? receiptReactionPayload(receipt.payload)
        : null;
      if (
        input.endpoint.provider === "github" &&
        payload &&
        (payload.runtimeGeneration !== input.runtimeContext.generation ||
          payload.credentialFingerprint !==
            input.runtimeContext.credentialFingerprint)
      )
        return [];
      if (["slack", "telegram", "github"].includes(input.endpoint.provider)) {
        // Eyes acknowledge this admitted message, not each model/retry run.
        // A fast final can win before addReceiptReaction inserts its row.
        // Persist the one-shot marker from the original admitted source now;
        // the late add will observe it under the same credential fence.
        const normalized = receipt.normalizedEvent;
        if (!normalized) return [];
        if (input.endpoint.provider === "github") {
          const originalFence = normalized.runtimeContext as
            Record<string, unknown> | undefined;
          if (
            originalFence?.generation !== input.runtimeContext.generation ||
            originalFence.credentialFingerprint !==
              input.runtimeContext.credentialFingerprint
          )
            return [];
        }
        const acknowledgement = normalized.acknowledgement as
          Record<string, unknown> | undefined;
        const message = normalized.message as Record<string, unknown> | undefined;
        const conversation = normalized.conversation as
          Record<string, unknown> | undefined;
        const source = receiptReactionPayload({
          version: 1,
          operation: "add",
          reaction: "eyes",
          threadId: conversation?.externalThreadId,
          messageId: message?.providerMessageId,
          runtimeGeneration: input.runtimeContext.generation,
          credentialFingerprint: input.runtimeContext.credentialFingerprint,
        });
        if (
          acknowledgement?.receiptReactionSupported !== true ||
          !source ||
          (payload &&
            (payload.threadId !== source.threadId ||
              payload.messageId !== source.messageId))
        )
          return [];
        payload = source;
      }
      if (!payload || payload.operation !== "add") return [];
      return [
        {
          companyId: input.publication.companyId,
          endpointId: input.publication.endpointId,
          conversationId: input.publication.conversationId,
          deliveryId: receipt.deliveryId,
          kind: "receipt_reaction",
          providerActionId: `receipt_reaction_remove:${receipt.deliveryId}`,
          payload: {
            ...payload,
            ...(input.endpoint.provider === "github" &&
            parseGitHubReceiptIdentity(receipt.result?.githubReceipt)
              ? {
                  githubReceipt: parseGitHubReceiptIdentity(
                    receipt.result?.githubReceipt,
                  )!,
                }
              : {}),
            operation: "remove" as const,
            runtimeGeneration: input.runtimeContext.generation,
            credentialFingerprint: input.runtimeContext.credentialFingerprint,
          } satisfies ReceiptReactionPayload,
          status: "received",
        },
      ];
    });
    if (removals.length === 0) return [];
    const removalDeliveryIds = new Set(
      removals.map((removal) => removal.deliveryId),
    );
    for (const receipt of receipts) {
      if (
        !receipt.deliveryId ||
        !removalDeliveryIds.has(receipt.deliveryId) ||
        !receipt.actionId ||
        !receipt.status ||
        !["received", "failed", "processing"].includes(receipt.status)
      ) {
        continue;
      }
      await tx
        .update(chatActions)
        .set({
          status: "cancelled",
          result: {
            ...(typeof receipt.result?.attempts === "number"
              ? { attempts: receipt.result.attempts }
              : {}),
            code: "receipt_reaction_superseded_by_terminal_publication",
          },
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatActions.id, receipt.actionId),
            eq(chatActions.status, receipt.status),
          ),
        );
    }
    await tx.insert(chatActions).values(removals).onConflictDoNothing();
    return tx
      .select({ id: chatActions.id })
      .from(chatActions)
      .where(
        and(
          eq(chatActions.endpointId, input.publication.endpointId),
          inArray(
            chatActions.providerActionId,
            removals.map((removal) => removal.providerActionId),
          ),
        ),
      )
      .then((rows) => rows.map((row) => row.id));
  }

  async function interactionResolutionPublicationToReplace(
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
  ): Promise<string | null> {
    if (
      !publication.idempotencyKey.startsWith("interaction-resolution:") ||
      !payload.interactionId
    )
      return null;
    return db
      .select({ providerMessageId: chatPublications.providerMessageId })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.issueId, publication.issueId),
          eq(
            chatPublications.idempotencyKey,
            `interaction:${payload.interactionId}:${publication.endpointId}`,
          ),
          eq(chatPublications.state, "published"),
          isNotNull(chatPublications.providerMessageId),
        ),
      )
      .then((rows) => rows[0]?.providerMessageId ?? null);
  }

  async function interactionPromptPublicationToReplace(
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
  ): Promise<string | null> {
    if (
      !payload.interactionId ||
      publication.idempotencyKey !==
        `interaction:${payload.interactionId}:${publication.endpointId}`
    ) {
      return null;
    }
    const interaction = await db
      .select({
        kind: issueThreadInteractions.kind,
        sourceRunId: issueThreadInteractions.sourceRunId,
      })
      .from(issueThreadInteractions)
      .where(
        and(
          eq(issueThreadInteractions.id, payload.interactionId),
          eq(issueThreadInteractions.companyId, publication.companyId),
          eq(issueThreadInteractions.issueId, publication.issueId),
          inArray(issueThreadInteractions.kind, [
            "ask_user_questions",
            "request_confirmation",
          ]),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!interaction?.sourceRunId) return null;

    // A provider-visible interaction is this run's response, not an additional
    // message beside its progress indicator. Move the durable interaction
    // publication onto the exact source run's provider-message lane. This
    // retires both the normal working placeholder and the queued placeholder
    // when a very fast run asks before the working update is published.
    for (const progressState of ["working", "queued"] as const) {
      const providerMessageId = await db
        .select({ providerMessageId: chatPublications.providerMessageId })
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, publication.companyId),
            eq(chatPublications.endpointId, publication.endpointId),
            eq(chatPublications.conversationId, publication.conversationId),
            eq(chatPublications.issueId, publication.issueId),
            eq(
              chatPublications.idempotencyKey,
              `run:${interaction.sourceRunId}:${progressState}:${publication.endpointId}`,
            ),
            eq(chatPublications.state, "published"),
            isNotNull(chatPublications.providerMessageId),
          ),
        )
        .then((rows) => rows[0]?.providerMessageId ?? null);
      if (providerMessageId) return providerMessageId;
    }
    return null;
  }

  async function runProgressSupersededByPublishedInteraction(
    publication: typeof chatPublications.$inferSelect,
  ): Promise<boolean> {
    if (
      !["queued", "working"].includes(publication.payload.progressState ?? "")
    ) {
      return false;
    }
    const sourceRunId = runIdFromMilestonePublication(publication);
    if (!sourceRunId) return false;
    const interactionIds = await db
      .select({ id: issueThreadInteractions.id })
      .from(issueThreadInteractions)
      .where(
        and(
          eq(issueThreadInteractions.companyId, publication.companyId),
          eq(issueThreadInteractions.issueId, publication.issueId),
          eq(issueThreadInteractions.sourceRunId, sourceRunId),
          inArray(issueThreadInteractions.kind, [
            "ask_user_questions",
            "request_confirmation",
          ]),
        ),
      )
      .then((rows) => rows.map((row) => row.id));
    if (interactionIds.length === 0) return false;
    return db
      .select({ id: chatPublications.id })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.issueId, publication.issueId),
          eq(chatPublications.state, "published"),
          inArray(
            chatPublications.idempotencyKey,
            interactionIds.map(
              (interactionId) =>
                `interaction:${interactionId}:${publication.endpointId}`,
            ),
          ),
        ),
      )
      .limit(1)
      .then((rows) => rows.length > 0);
  }

  async function taskStatusPublicationToReplace(
    publication: typeof chatPublications.$inferSelect,
    payload: SafeChatPublicationPayload,
  ): Promise<string | null> {
    if (
      !publication.idempotencyKey.startsWith("control:status:") ||
      payload.attachmentIds?.length
    )
      return null;
    const rows = await db
      .select({
        commentId: chatPublications.commentId,
        commentRunId: issueComments.createdByRunId,
        idempotencyKey: chatPublications.idempotencyKey,
        payload: chatPublications.payload,
        providerMessageId: chatPublications.providerMessageId,
      })
      .from(chatPublications)
      .leftJoin(issueComments, eq(issueComments.id, chatPublications.commentId))
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.state, "published"),
          isNotNull(chatPublications.providerMessageId),
        ),
      )
      .orderBy(desc(chatPublications.createdAt), desc(chatPublications.id));
    const rowRunId = (row: (typeof rows)[number]) => {
      const milestoneMatch =
        /^run:([^:]+):(?:queued|working|waiting_for_input|completed|failed):/.exec(
          row.idempotencyKey,
        );
      return milestoneMatch?.[1] ?? row.commentRunId ?? null;
    };
    for (const candidate of rows) {
      if (
        !candidate.providerMessageId ||
        !["queued", "working"].includes(candidate.payload.progressState ?? "")
      ) {
        continue;
      }
      const runId = rowRunId(candidate);
      if (!runId) continue;
      const laneClosed = rows.some((row) => {
        if (rowRunId(row) !== runId) return false;
        return (
          ["waiting_for_input", "completed", "failed"].includes(
            row.payload.progressState ?? "",
          ) ||
          (row.commentId !== null && row.payload.progressState === undefined)
        );
      });
      if (!laneClosed) return candidate.providerMessageId;
    }
    return null;
  }

  async function closeProgressToReplace(
    publication: typeof chatPublications.$inferSelect,
    endpoint: EndpointRow,
  ): Promise<{ providerMessageId: string; runId: string } | null> {
    if (
      !["telegram", "slack", "discord", "microsoft-teams"].includes(
        endpoint.provider,
      ) ||
      !publication.idempotencyKey.startsWith("control:close:")
    )
      return null;
    const current = alias(chatPublications, "close_current_progress");
    const plainText = (table: typeof chatPublications | typeof current) =>
      and(
        sql`jsonb_typeof(${table.payload}->'text') = 'string'`,
        sql`${table.payload}->'card' is null`,
        sql`${table.payload}->'interactionId' is null`,
        sql`${table.payload}->'transportPart' is null`,
        sql`(${table.payload}->'attachmentIds' is null or ${table.payload}->'attachmentIds' = '[]'::jsonb)`,
      );
    const ownedMilestone = (table: typeof chatPublications | typeof current) =>
      or(
        sql`${table.idempotencyKey} = 'run:' || ${heartbeatRuns.id}::text || ':queued:' || ${endpoint.id}`,
        sql`${table.idempotencyKey} = 'run:' || ${heartbeatRuns.id}::text || ':working:' || ${endpoint.id}`,
        sql`${table.idempotencyKey} like 'run:' || ${heartbeatRuns.id}::text || ':working:' || ${endpoint.id} || ':native:%'`,
      );
    // A historical progress row alone is not edit authority: its exact current
    // outbound link must still belong to that run's progress (or an interleaved
    // status control). Read under the same credential lease as final delivery.
    const lanes = await db
      .selectDistinct({
        providerMessageId: chatMessageLinks.providerMessageId,
        runId: heartbeatRuns.id,
      })
      .from(chatPublications)
      .innerJoin(
        heartbeatRuns,
        and(
          eq(heartbeatRuns.companyId, publication.companyId),
          eq(heartbeatRuns.agentId, endpoint.assignedAgentId),
          sql`${heartbeatRuns.contextSnapshot}->>'issueId' = ${publication.issueId}`,
          sql`split_part(${chatPublications.idempotencyKey}, ':', 2) = ${heartbeatRuns.id}::text`,
        ),
      )
      .innerJoin(
        chatMessageLinks,
        and(
          eq(chatMessageLinks.companyId, publication.companyId),
          eq(chatMessageLinks.endpointId, publication.endpointId),
          eq(chatMessageLinks.conversationId, publication.conversationId),
          eq(chatMessageLinks.direction, "outbound"),
          eq(
            chatMessageLinks.providerMessageId,
            chatPublications.providerMessageId,
          ),
        ),
      )
      .innerJoin(
        current,
        and(
          eq(current.id, chatMessageLinks.publicationId),
          eq(current.companyId, publication.companyId),
          eq(current.endpointId, publication.endpointId),
          eq(current.conversationId, publication.conversationId),
          eq(current.issueId, publication.issueId),
          eq(current.state, "published"),
          eq(current.providerMessageId, chatMessageLinks.providerMessageId),
          isNull(current.commentId),
          plainText(current),
          or(
            and(
              sql`${current.payload}->>'progressState' in ('queued', 'working')`,
              ownedMilestone(current),
            ),
            like(current.idempotencyKey, "control:status:%"),
          ),
        ),
      )
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.issueId, publication.issueId),
          eq(chatPublications.state, "published"),
          isNull(chatPublications.commentId),
          plainText(chatPublications),
          sql`${chatPublications.payload}->>'progressState' in ('queued', 'working')`,
          ownedMilestone(chatPublications),
        ),
      )
      .limit(2);
    // One close receipt owns one edit. Multiple independent lanes require a
    // separate durable multi-effect protocol, never an arbitrary latest guess.
    if (lanes.length !== 1) return null;
    const lane = lanes[0]!;
    const [possiblyConsumed] = await db
      .select({ id: chatPublications.id })
      .from(chatPublications)
      .leftJoin(
        issueComments,
        and(
          eq(issueComments.id, chatPublications.commentId),
          eq(issueComments.companyId, publication.companyId),
          eq(issueComments.issueId, publication.issueId),
        ),
      )
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          eq(chatPublications.issueId, publication.issueId),
          or(
            inArray(chatPublications.state, [
              "pending",
              "retry",
              "streaming",
              "delivery_unknown",
              "published",
            ]),
            // Stopping retries (including an operator's unknown-delivery
            // cancellation) does not prove an attempted edit never arrived.
            and(
              inArray(chatPublications.state, ["cancelled", "failed"]),
              gt(chatPublications.attempts, 0),
            ),
          ),
          or(
            eq(issueComments.createdByRunId, lane.runId),
            // Question/confirmation prompts consume this same run's progress
            // ID through interactionPromptPublicationToReplace, but have no
            // commentId. A stale working link is not proof that their edit
            // never reached the provider (including an unconfirmed receipt).
            sql`exists (
              select 1 from issue_thread_interactions consuming_interaction
              where consuming_interaction.company_id = ${publication.companyId}::uuid
                and consuming_interaction.issue_id = ${publication.issueId}::uuid
                and consuming_interaction.source_run_id = ${lane.runId}::uuid
                and consuming_interaction.kind in ('ask_user_questions', 'request_confirmation')
                and ${chatPublications.payload}->>'interactionId' = consuming_interaction.id::text
                and ${chatPublications.idempotencyKey} = 'interaction:' || consuming_interaction.id::text || ':' || ${publication.endpointId}
            )`,
            eq(
              chatPublications.idempotencyKey,
              `run:${lane.runId}:completed:${endpoint.id}`,
            ),
            eq(
              chatPublications.idempotencyKey,
              `run:${lane.runId}:failed:${endpoint.id}`,
            ),
          ),
        ),
      )
      .limit(1);
    // A final may have reached the provider before its database receipt. Even an
    // unchanged working link cannot disprove that ambiguous provider effect.
    return possiblyConsumed ? null : lane;
  }

  async function currentTaskControlPayload(
    publication: typeof chatPublications.$inferSelect,
  ): Promise<SafeChatPublicationPayload> {
    const persisted = publication.payload as SafeChatPublicationPayload;
    if (!publication.idempotencyKey.startsWith("control:status:")) {
      return persisted;
    }
    const issue = await db
      .select({
        identifier: issues.identifier,
        status: issues.status,
        title: issues.title,
      })
      .from(issues)
      .where(
        and(
          eq(issues.companyId, publication.companyId),
          eq(issues.id, publication.issueId),
        ),
      )
      .then((rows) => rows[0] ?? null);
    if (!issue) return persisted;
    return projectSafeChatPublication({
      classification: "external",
      source: "task_control",
      text: `${issue.identifier}: ${issue.title} — ${issue.status}`,
    });
  }

  function taskControlCompletesConversation(
    publication: Pick<typeof chatPublications.$inferSelect, "idempotencyKey">,
  ): boolean {
    return /^control:(?:new|close):/.test(publication.idempotencyKey);
  }

  function isExplicitOperatorPublication(
    publication: Pick<typeof chatPublications.$inferSelect, "idempotencyKey">,
  ): boolean {
    return /^(?:explicit:|explicit-board:)/.test(publication.idempotencyKey);
  }

  async function hasCommittedTaskControlCompletion(
    conversationId: string,
    database: DbOrTransaction = db,
  ): Promise<boolean> {
    return database
      .select({ id: chatPublications.id })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.conversationId, conversationId),
          eq(chatPublications.state, "published"),
          or(
            like(chatPublications.idempotencyKey, "control:new:%"),
            like(chatPublications.idempotencyKey, "control:close:%"),
          ),
        ),
      )
      .limit(1)
      .then((rows) => rows.length > 0);
  }

  async function commitTaskControlCompletion(
    tx: Db,
    publication: Pick<
      typeof chatPublications.$inferSelect,
      | "companyId"
      | "conversationId"
      | "createdAt"
      | "endpointId"
      | "id"
      | "idempotencyKey"
      | "payload"
    >,
    committedAt: Date,
  ): Promise<void> {
    if (!taskControlCompletesConversation(publication)) return;
    await tx
      .update(chatConversations)
      .set({ state: "completed", updatedAt: committedAt })
      .where(
        and(
          eq(chatConversations.companyId, publication.companyId),
          eq(chatConversations.endpointId, publication.endpointId),
          eq(chatConversations.id, publication.conversationId),
          inArray(chatConversations.state, ["active", "waiting"]),
        ),
      );
    // The provider-visible completion is the external boundary. Anything
    // enqueued later for this old generation stays internal even if its run
    // finishes after /new or /close. A racing insert that commits after this
    // transaction is rejected by the completed-conversation send guard.
    await tx
      .update(chatPublications)
      .set({
        state: "cancelled",
        nextAttemptAt: null,
        redactedError:
          "Conversation was completed by a task control before delivery",
        updatedAt: committedAt,
      })
      .where(
        and(
          eq(chatPublications.companyId, publication.companyId),
          eq(chatPublications.endpointId, publication.endpointId),
          eq(chatPublications.conversationId, publication.conversationId),
          or(
            gt(chatPublications.createdAt, publication.createdAt),
            and(
              eq(chatPublications.createdAt, publication.createdAt),
              gt(
                publicationTransportOrderKey(chatPublications),
                publication.payload.transportPart?.orderKey ?? publication.id,
              ),
            ),
          ),
          inArray(chatPublications.state, ["pending", "retry", "streaming"]),
          sql`not (${chatPublications.idempotencyKey} like 'explicit:%' or ${chatPublications.idempotencyKey} like 'explicit-board:%')`,
        ),
      );
  }

  async function finalizePublicationFailure(
    publication: typeof chatPublications.$inferSelect,
    error: unknown,
    providerAccepted = false,
    runtimeContext?: LifecycleRuntimeFence | null,
    credentialLease?: CredentialMutationLeaseGuard,
  ): Promise<boolean> {
    const attempts = publication.attempts + 1;
    const disposition = providerAccepted
      ? {
          kind: "delivery_unknown" as const,
          reason:
            "Provider accepted the publication, but Paperclip could not confirm its durable result",
        }
      : error instanceof NativeChatReviewPresentationContentionError
        ? { kind: "retry" as const, retryAfterMs: 250, reason: error.message }
        : error instanceof FailedChatRetryPublicationReadError
          ? {
              kind: "retry" as const,
              retryAfterMs: 1_000,
              reason: error.message,
            }
          : isOutboundAttachmentValidationError(error)
            ? {
                kind: "failed" as const,
                reason: error.message,
              }
            : isOutboundAttachmentHydrationError(error)
              ? {
                  kind: "retry" as const,
                  retryAfterMs: Math.min(
                    60_000,
                    2 ** Math.max(0, attempts) * 1_000,
                  ),
                  reason: error.message,
                }
              : classifyChatPublicationError(error, attempts);
    const failure = redactSensitiveText(disposition.reason).slice(
      0,
      MAX_ERROR_TEXT,
    );
    // Provider-directed rate limits are not delivery failures. Keep the
    // durable publication retryable for the provider's full interval instead
    // of exhausting the five-attempt transport budget while flood control is
    // still active.
    const terminalRetry =
      disposition.kind === "retry" &&
      disposition.providerRateLimit !== true &&
      attempts >= 5;
    const attachmentFailure = attachmentFailureKind(publication.payload);
    const attachmentFailureRuntimeContext =
      !providerAccepted &&
      disposition.kind === "failed" &&
      runtimeContext &&
      attachmentFailure &&
      definiteAttachmentProviderRejection(error)
        ? runtimeContext
        : null;
    let invalidateCurrentRuntime = false;
    const finalized = await db.transaction(async (tx) => {
      await credentialLease?.assertOwned(tx);
      const state =
        disposition.kind === "retry" && !terminalRetry
          ? "retry"
          : disposition.kind === "delivery_unknown"
            ? "delivery_unknown"
            : disposition.kind === "resource_unavailable"
              ? "cancelled"
              : "failed";
      const [ownedPublication] = await tx
        .update(chatPublications)
        .set({
          state,
          nextAttemptAt:
            disposition.kind === "retry" && !terminalRetry
              ? new Date(Date.now() + disposition.retryAfterMs)
              : null,
          redactedError: failure,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatPublications.id, publication.id),
            eq(chatPublications.state, "streaming"),
            eq(chatPublications.attempts, attempts),
          ),
        )
        .returning({ id: chatPublications.id });
      if (!ownedPublication) return false;

      if (publication.idempotencyKey.startsWith("control:")) {
        await tx
          .update(chatActions)
          .set({
            status:
              state === "delivery_unknown"
                ? "delivery_unknown"
                : state === "cancelled"
                  ? "cancelled"
                  : "issued",
            result: {
              code:
                state === "delivery_unknown"
                  ? "task_control_delivery_unknown"
                  : state === "cancelled"
                    ? "task_control_destination_unavailable"
                    : "task_control_transport_failed",
              attempts,
              retryable: state === "retry",
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.endpointId, publication.endpointId),
              eq(
                chatActions.providerActionId,
                `task-control-authorization:${publication.id}`,
              ),
              eq(chatActions.status, "processing"),
              sql`(${chatActions.result}->>'attempts')::int = ${attempts}`,
            ),
          );
      }

      const currentEndpoint =
        runtimeContext &&
        (disposition.kind === "endpoint_attention" ||
          disposition.kind === "resource_unavailable")
          ? await runtimeCallbackEndpoint(
              tx,
              publication.endpointId,
              runtimeContext,
              ["verifying", "active"],
            )
          : null;

      if (disposition.kind === "endpoint_attention" && currentEndpoint) {
        await tx
          .update(chatEndpoints)
          .set({
            status: "attention",
            healthMessage: "Provider credentials or permissions need attention",
            lastError: failure,
            updatedAt: new Date(),
          })
          .where(eq(chatEndpoints.id, currentEndpoint.id));
        await tx
          .update(toolConnections)
          .set({
            status: "disabled",
            enabled: false,
            healthStatus: "degraded",
            healthMessage: "Provider credentials or permissions need attention",
            lastError: failure,
            healthCheckedAt: new Date(),
            updatedAt: new Date(),
          })
          .where(eq(toolConnections.id, currentEndpoint.connectionId));
        invalidateCurrentRuntime = true;
      } else if (
        disposition.kind === "resource_unavailable" &&
        currentEndpoint
      ) {
        const binding = await tx
          .select({ resourceId: chatConversations.resourceId })
          .from(chatConversations)
          .where(eq(chatConversations.id, publication.conversationId))
          .then((result) => result[0] ?? null);
        await tx
          .update(chatConversations)
          .set({ state: "unavailable", updatedAt: new Date() })
          .where(
            and(
              eq(chatConversations.id, publication.conversationId),
              eq(chatConversations.endpointId, currentEndpoint.id),
            ),
          );
        if (binding?.resourceId) {
          await tx
            .update(chatEndpointResources)
            .set({ availability: "unavailable", updatedAt: new Date() })
            .where(
              and(
                eq(chatEndpointResources.id, binding.resourceId),
                eq(chatEndpointResources.endpointId, currentEndpoint.id),
              ),
            );
        }
      }

      if (attachmentFailureRuntimeContext && attachmentFailure) {
        const noticeEndpoint = await runtimeCallbackEndpoint(
          tx,
          publication.endpointId,
          attachmentFailureRuntimeContext,
          ["verifying", "active"],
        );
        const noticeConversation = noticeEndpoint
          ? await tx
              .select({
                id: chatConversations.id,
                state: chatConversations.state,
              })
              .from(chatConversations)
              .where(
                and(
                  eq(chatConversations.companyId, publication.companyId),
                  eq(chatConversations.endpointId, publication.endpointId),
                  eq(chatConversations.id, publication.conversationId),
                  inArray(chatConversations.state, ["active", "waiting"]),
                ),
              )
              .for("no key update")
              .then((rows) => rows[0] ?? null)
          : null;
        const providerCanSendTextNotice =
          noticeEndpoint &&
          ["slack", "discord", "telegram"].includes(noticeEndpoint.provider) &&
          (attachmentFailure.provider === null ||
            noticeEndpoint.provider === attachmentFailure.provider);
        if (providerCanSendTextNotice && noticeConversation) {
          const taskUrl = safeChatTaskUrl(
            options.publicBaseUrl,
            publication.issueId,
          );
          const noticeText =
            attachmentFailure.kind === "generated_response"
              ? "Paperclip could not send the response attachment. The complete response remains on its Paperclip task for an operator to retry."
              : "Paperclip could not send an attachment. The file remains on its Paperclip task for an operator to retry.";
          const idempotencyKey = `${ATTACHMENT_FAILURE_NOTICE_PREFIX}${publication.id}:${attachmentFailureRuntimeContext.generation}:${attachmentFailureRuntimeContext.credentialFingerprint}`;
          await tx
            .insert(chatPublications)
            .values({
              companyId: publication.companyId,
              endpointId: publication.endpointId,
              conversationId: publication.conversationId,
              issueId: publication.issueId,
              commentId: null,
              idempotencyKey,
              payload: projectSafeChatPublication({
                classification: "external",
                source: "safe_milestone",
                text: taskUrl
                  ? `${noticeText} Open task: ${taskUrl}`
                  : noticeText,
              }),
              state: "pending",
            })
            .onConflictDoNothing();
        }
      }

      await credentialLease?.assertOwned(tx);
      return true;
    });
    if (finalized && invalidateCurrentRuntime) {
      await credentialLease?.assertOwned();
      await invalidateRuntime(publication.endpointId).catch(() => undefined);
    }
    if (finalized) {
      logger.warn(
        {
          endpointId: publication.endpointId,
          publicationId: publication.id,
          error: failure,
          disposition: disposition.kind,
        },
        "chat publication failed",
      );
    }
    return finalized;
  }

  async function ensureDurablePublicationTransport(
    publication: typeof chatPublications.$inferSelect,
  ): Promise<typeof chatPublications.$inferSelect> {
    const persisted = publication.payload as SafeChatPublicationPayload;
    if (
      !persisted ||
      typeof persisted !== "object" ||
      typeof persisted.text !== "string"
    ) {
      throw Object.assign(
        new Error("Durable chat publication payload is malformed"),
        { code: "VALIDATION_ERROR", name: "ValidationError" },
      );
    }
    // Validate closed persisted wrappers even on retries that are already split.
    renderPublicationTransportText(persisted);
    await options.publicationTransportPreparationBarrier?.({
      publicationId: publication.id,
    });
    const provider = await db
      .select({ provider: chatEndpoints.provider })
      .from(chatEndpoints)
      .where(eq(chatEndpoints.id, publication.endpointId))
      .then((rows) => rows[0]?.provider ?? null);
    if (
      provider === "slack" ||
      provider === "github" ||
      provider === "microsoft-teams"
    ) {
      if (
        persisted.transportPart ||
        persisted.card ||
        persisted.interactionId ||
        persisted.attachmentIds?.length
      )
        return publication;
      const parts = splitNativePublicationText(provider, persisted.text);
      if (parts.length === 1) return publication;
      return db.transaction(async (tx) => {
        const current = await tx
          .select()
          .from(chatPublications)
          .where(eq(chatPublications.id, publication.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current) return publication;
        const currentPayload = current.payload as SafeChatPublicationPayload;
        renderPublicationTransportText(currentPayload);
        if (
          currentPayload.transportPart ||
          currentPayload.card ||
          currentPayload.interactionId ||
          currentPayload.attachmentIds?.length ||
          !["pending", "retry"].includes(current.state)
        )
          return current;
        const currentParts =
          currentPayload.text === persisted.text
            ? parts
            : splitNativePublicationText(provider, currentPayload.text);
        if (currentParts.length === 1) return current;
        const batchId = current.id;
        const updatedAt = new Date();
        const payloadFor = (index: number): SafeChatPublicationPayload => {
          const part = currentParts[index]!;
          const payload = {
            ...currentPayload,
            text: part.text,
            transportPart: {
              batchId,
              index,
              count: currentParts.length,
              mode: "inline" as const,
              orderKey: `${batchId}:${String(index).padStart(4, "0")}`,
              ...(part.prefix ? { prefix: part.prefix } : {}),
              ...(part.suffix ? { suffix: part.suffix } : {}),
            },
          };
          if (index > 0) delete payload.progressState;
          return payload;
        };
        const rootPayload = payloadFor(0);
        await tx
          .update(chatPublications)
          .set({ payload: rootPayload, updatedAt })
          .where(eq(chatPublications.id, current.id));
        await tx.insert(chatPublications).values(
          currentParts.slice(1).map((_part, offset) => ({
            companyId: current.companyId,
            endpointId: current.endpointId,
            conversationId: current.conversationId,
            issueId: current.issueId,
            commentId: current.commentId,
            idempotencyKey: `${current.idempotencyKey}:${provider}-part:${offset + 1}`,
            payload: payloadFor(offset + 1),
            state: "pending" as const,
            createdAt: sql`(select ${chatPublications.createdAt} from ${chatPublications} where ${chatPublications.id} = ${current.id})`,
            updatedAt,
          })),
        );
        return { ...current, payload: rootPayload, updatedAt };
      });
    }
    if (provider === "discord") {
      if (
        persisted.transportPart ||
        persisted.card ||
        persisted.interactionId ||
        !discordMarkdownRequiresAttachment(persisted.text)
      ) {
        return publication;
      }

      // A normal response can replace its run's working placeholder. Discord's
      // adapter cannot add a file while editing, so first turn that placeholder
      // into a durable hand-off and then publish the complete Markdown as its
      // own ordered attachment row. Publications without a replacement lane
      // remain one provider call: a short caption and the lossless file.
      const replacesProgressMessage = Boolean(
        await runPublicationToReplace(publication, persisted),
      );
      return db.transaction(async (tx) => {
        const current = await tx
          .select()
          .from(chatPublications)
          .where(eq(chatPublications.id, publication.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current) return publication;
        const currentPayload = current.payload as SafeChatPublicationPayload;
        if (
          currentPayload.transportPart ||
          currentPayload.card ||
          currentPayload.interactionId ||
          !["pending", "retry"].includes(current.state) ||
          !discordMarkdownRequiresAttachment(currentPayload.text)
        ) {
          return current;
        }

        const batchId = current.id;
        const updatedAt = new Date();
        const transportPart = (
          index: number,
          count: number,
          mode: "inline" | "discord_markdown_attachment",
        ) => ({
          batchId,
          count,
          index,
          mode,
          orderKey: `${batchId}:${String(index).padStart(4, "0")}`,
        });
        if (!replacesProgressMessage) {
          const attachmentPayload: SafeChatPublicationPayload = {
            ...currentPayload,
            transportPart: transportPart(0, 1, "discord_markdown_attachment"),
          };
          await tx
            .update(chatPublications)
            .set({ payload: attachmentPayload, updatedAt })
            .where(eq(chatPublications.id, current.id));
          return { ...current, payload: attachmentPayload, updatedAt };
        }

        const handoffPayload: SafeChatPublicationPayload = {
          ...currentPayload,
          text: "This response needs a separate attachment because it exceeds the message limit.",
          transportPart: transportPart(0, 2, "inline"),
        };
        delete handoffPayload.attachmentIds;
        await tx
          .update(chatPublications)
          .set({ payload: handoffPayload, updatedAt })
          .where(eq(chatPublications.id, current.id));

        const attachmentPayload: SafeChatPublicationPayload = {
          ...currentPayload,
          transportPart: transportPart(1, 2, "discord_markdown_attachment"),
        };
        delete attachmentPayload.progressState;
        await tx.insert(chatPublications).values({
          companyId: current.companyId,
          endpointId: current.endpointId,
          conversationId: current.conversationId,
          issueId: current.issueId,
          commentId: current.commentId,
          idempotencyKey: `discord-markdown-attachment:${current.id}`,
          payload: attachmentPayload,
          state: "pending",
          createdAt: sql`(select ${chatPublications.createdAt} from ${chatPublications} where ${chatPublications.id} = ${current.id})`,
          updatedAt,
        });
        return { ...current, payload: handoffPayload, updatedAt };
      });
    }

    if (provider !== "telegram") return publication;
    if (
      persisted.transportPart ||
      persisted.card ||
      persisted.interactionId ||
      persisted.attachmentIds?.length
    ) {
      return publication;
    }
    if (telegramMarkdownRequiresAttachment(persisted.text)) {
      // Telegram parses each message independently. A fixed-size split can
      // turn the second half of a code fence, link, or list into unrelated
      // plain text even though concatenating the source parts is lossless.
      // Preserve structured long Markdown as one document. When this is a run
      // final, first complete its existing progress placeholder, then send the
      // file through a separate ordered outbox row because Telegram cannot add
      // an attachment while editing that placeholder.
      const replacesProgressMessage = Boolean(
        await runPublicationToReplace(publication, persisted),
      );
      return db.transaction(async (tx) => {
        const current = await tx
          .select()
          .from(chatPublications)
          .where(eq(chatPublications.id, publication.id))
          .for("update")
          .then((rows) => rows[0] ?? null);
        if (!current) return publication;
        const currentPayload = current.payload as SafeChatPublicationPayload;
        if (
          currentPayload.transportPart ||
          currentPayload.card ||
          currentPayload.interactionId ||
          currentPayload.attachmentIds?.length ||
          !["pending", "retry"].includes(current.state) ||
          !telegramMarkdownRequiresAttachment(currentPayload.text)
        ) {
          return current;
        }

        const batchId = current.id;
        const updatedAt = new Date();
        const transportPart = (
          index: number,
          count: number,
          mode: "inline" | "telegram_markdown_attachment",
        ) => ({
          batchId,
          count,
          index,
          mode,
          orderKey: `${batchId}:${String(index).padStart(4, "0")}`,
        });
        if (!replacesProgressMessage) {
          const attachmentPayload: SafeChatPublicationPayload = {
            ...currentPayload,
            transportPart: transportPart(0, 1, "telegram_markdown_attachment"),
          };
          await tx
            .update(chatPublications)
            .set({ payload: attachmentPayload, updatedAt })
            .where(eq(chatPublications.id, current.id));
          return { ...current, payload: attachmentPayload, updatedAt };
        }

        const handoffPayload: SafeChatPublicationPayload = {
          ...currentPayload,
          text: "This response needs a separate attachment because it exceeds the message limit.",
          transportPart: transportPart(0, 2, "inline"),
        };
        delete handoffPayload.attachmentIds;
        await tx
          .update(chatPublications)
          .set({ payload: handoffPayload, updatedAt })
          .where(eq(chatPublications.id, current.id));

        const attachmentPayload: SafeChatPublicationPayload = {
          ...currentPayload,
          transportPart: transportPart(1, 2, "telegram_markdown_attachment"),
        };
        delete attachmentPayload.progressState;
        await tx.insert(chatPublications).values({
          companyId: current.companyId,
          endpointId: current.endpointId,
          conversationId: current.conversationId,
          issueId: current.issueId,
          commentId: current.commentId,
          idempotencyKey: `telegram-markdown-attachment:${current.id}`,
          payload: attachmentPayload,
          state: "pending",
          createdAt: sql`(select ${chatPublications.createdAt} from ${chatPublications} where ${chatPublications.id} = ${current.id})`,
          updatedAt,
        });
        return { ...current, payload: handoffPayload, updatedAt };
      });
    }
    const parts = splitTelegramPublicationText(persisted.text);
    if (parts.length === 1) return publication;

    return db.transaction(async (tx) => {
      const current = await tx
        .select()
        .from(chatPublications)
        .where(eq(chatPublications.id, publication.id))
        .for("update")
        .then((rows) => rows[0] ?? null);
      if (!current) return publication;
      const currentPayload = current.payload as SafeChatPublicationPayload;
      if (
        currentPayload.transportPart ||
        currentPayload.card ||
        currentPayload.interactionId ||
        currentPayload.attachmentIds?.length ||
        !["pending", "retry"].includes(current.state)
      ) {
        return current;
      }
      const currentParts = splitTelegramPublicationText(currentPayload.text);
      if (currentParts.length === 1) return current;

      const batchId = current.id;
      const updatedAt = new Date();
      const transportPart = (index: number) => ({
        batchId,
        count: currentParts.length,
        index,
        orderKey: `${batchId}:${String(index).padStart(4, "0")}`,
      });
      const rootPayload: SafeChatPublicationPayload = {
        ...currentPayload,
        text: currentParts[0]!,
        transportPart: transportPart(0),
      };
      await tx
        .update(chatPublications)
        .set({ payload: rootPayload, updatedAt })
        .where(eq(chatPublications.id, current.id));

      const { progressState: _progressState, ...nonProgressPayload } =
        currentPayload;
      await tx.insert(chatPublications).values(
        currentParts.slice(1).map((text, offset) => {
          const index = offset + 1;
          return {
            companyId: current.companyId,
            endpointId: current.endpointId,
            conversationId: current.conversationId,
            issueId: current.issueId,
            commentId: current.commentId,
            idempotencyKey: `${current.idempotencyKey}:telegram-part:${index}`,
            payload: {
              ...nonProgressPayload,
              text,
              transportPart: transportPart(index),
            },
            state: "pending" as const,
            createdAt: sql`(select ${chatPublications.createdAt} from ${chatPublications} where ${chatPublications.id} = ${current.id})`,
            updatedAt,
          };
        }),
      );
      return { ...current, payload: rootPayload, updatedAt };
    });
  }

  async function settlePublicationPreparationFailure(
    publication: typeof chatPublications.$inferSelect,
    error: unknown,
  ): Promise<boolean> {
    const attempts = publication.attempts + 1;
    const classified = classifyChatPublicationError(error, attempts);
    // No provider I/O has started at this boundary. Unknown transport or
    // database failures are therefore safe to retry; only a definite local
    // validation rejection (or repeated exhaustion) is terminal.
    const terminal = classified.kind === "failed" || attempts >= 5;
    const retryAfterMs =
      classified.kind === "retry"
        ? classified.retryAfterMs
        : Math.min(60_000, 2 ** Math.max(0, attempts) * 1_000);
    const result = await db.transaction(async (tx) => {
      const [settled] = await tx
        .update(chatPublications)
        .set({
          state: terminal ? "failed" : "retry",
          attempts,
          nextAttemptAt: terminal ? null : new Date(Date.now() + retryAfterMs),
          redactedError: terminal
            ? "Publication payload could not be prepared for provider delivery"
            : "Publication preparation failed before provider delivery",
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(chatPublications.id, publication.id),
            eq(chatPublications.state, publication.state),
            eq(chatPublications.attempts, publication.attempts),
          ),
        )
        .returning({ id: chatPublications.id });
      if (!settled) return false;
      if (terminal && publication.idempotencyKey.startsWith("control:")) {
        await tx
          .update(chatActions)
          .set({
            status: "cancelled",
            result: {
              code: "task_control_publication_invalid",
              attempts,
              retryable: false,
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.endpointId, publication.endpointId),
              eq(
                chatActions.providerActionId,
                `task-control-authorization:${publication.id}`,
              ),
              eq(chatActions.status, "issued"),
            ),
          );
      }
      return true;
    });
    if (result) {
      logger.warn(
        {
          endpointId: publication.endpointId,
          publicationId: publication.id,
          error: redactError(error),
          terminal,
        },
        "chat publication preparation failed",
      );
    }
    return result;
  }

  async function lockSlackFileReceiptAuthorization(
    tx: DbTransaction,
    input: {
      actionId: string;
      payload: SlackFileUploadReceiptPayload;
    },
  ): Promise<
    | {
        action: typeof chatActions.$inferSelect;
        conversation: ConversationRow;
        endpoint: EndpointRow;
        mode: "delivery_unknown" | "operator_confirmed";
        publication: typeof chatPublications.$inferSelect;
      }
    | { action: typeof chatActions.$inferSelect; mode: "defer" | "settled" }
    | null
  > {
    const publication = await tx
      .select()
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.id, input.payload.publicationId),
          eq(chatPublications.attempts, input.payload.publicationAttempt),
        ),
      )
      .for("update")
      .then((rows) => rows[0] ?? null);
    const action = publication
      ? await tx
          .select()
          .from(chatActions)
          .where(
            and(
              eq(chatActions.id, input.actionId),
              eq(chatActions.companyId, publication.companyId),
              eq(chatActions.endpointId, publication.endpointId),
              eq(chatActions.conversationId, publication.conversationId),
              eq(chatActions.kind, "slack_file_upload_receipt"),
              eq(
                chatActions.providerActionId,
                `slack-file-receipt:${publication.id}:${publication.attempts}`,
              ),
            ),
          )
          .for("update")
          .then((rows) => rows[0] ?? null)
      : null;
    const currentPayload = action
      ? slackFileUploadReceiptPayload(action.payload)
      : null;
    if (
      !publication ||
      !action ||
      !publication.payload.attachmentIds?.length ||
      publication.payload.card ||
      publication.payload.interactionId ||
      publication.idempotencyKey.startsWith("control:") ||
      !currentPayload ||
      !sameSlackFileUploadReceipt(currentPayload, input.payload)
    ) {
      return null;
    }
    if (publication.state === "streaming") {
      return { action, mode: "defer" };
    }
    if (publication.state === "published" && publication.providerMessageId) {
      const exactLink = await tx
        .select({ id: chatMessageLinks.id })
        .from(chatMessageLinks)
        .where(
          and(
            eq(chatMessageLinks.companyId, publication.companyId),
            eq(chatMessageLinks.endpointId, publication.endpointId),
            eq(chatMessageLinks.conversationId, publication.conversationId),
            eq(chatMessageLinks.publicationId, publication.id),
            publication.commentId
              ? eq(chatMessageLinks.commentId, publication.commentId)
              : isNull(chatMessageLinks.commentId),
            eq(
              chatMessageLinks.providerMessageId,
              publication.providerMessageId,
            ),
            eq(chatMessageLinks.direction, "outbound"),
          ),
        )
        .limit(1)
        .then((rows) => rows[0] ?? null);
      return exactLink ? { action, mode: "settled" } : null;
    }
    const mode =
      publication.state === "delivery_unknown"
        ? "delivery_unknown"
        : publication.state === "published" &&
            !publication.providerMessageId &&
            operatorConfirmedSlackFileReceipt(action.result, input.payload)
          ? "operator_confirmed"
          : null;
    if (!mode) return null;
    const endpoint = await runtimeCallbackEndpoint(
      tx,
      publication.endpointId,
      {
        generation: input.payload.runtimeGeneration,
        credentialFingerprint: input.payload.credentialFingerprint,
      },
      ["verifying", "active"],
    );
    const conversation = endpoint
      ? await tx
          .select()
          .from(chatConversations)
          .where(
            and(
              eq(chatConversations.id, publication.conversationId),
              eq(chatConversations.companyId, publication.companyId),
              eq(chatConversations.endpointId, publication.endpointId),
              eq(chatConversations.externalThreadId, input.payload.threadId),
              inArray(chatConversations.state, [
                "active",
                "waiting",
                "completed",
              ]),
            ),
          )
          .for("no key update")
          .then((rows) => rows[0] ?? null)
      : null;
    const resource =
      endpoint && conversation?.resourceId && !conversation.isDirectMessage
        ? await tx
            .select()
            .from(chatEndpointResources)
            .where(
              and(
                eq(chatEndpointResources.id, conversation.resourceId),
                eq(chatEndpointResources.companyId, endpoint.companyId),
                eq(chatEndpointResources.endpointId, endpoint.id),
              ),
            )
            .for("no key update")
            .then((rows) => rows[0] ?? null)
        : null;
    if (
      endpoint?.provider !== "slack" ||
      endpoint.botExternalId !== input.payload.botExternalId ||
      !conversation ||
      !(conversation.isDirectMessage
        ? endpoint.allowDirectMessages
        : nonDirectDestinationAllowed(endpoint, resource))
    ) {
      return null;
    }
    return { action, conversation, endpoint, mode, publication };
  }

  async function processPendingSlackFileUploadReceipts(limit = 25) {
    const selectedAt = new Date();
    const actions = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "slack_file_upload_receipt"),
          notExists(
            db
              .select({ id: chatEndpoints.id })
              .from(chatEndpoints)
              .where(
                and(
                  eq(chatEndpoints.id, chatActions.endpointId),
                  inArray(chatEndpoints.status, ["paused", "attention"]),
                ),
              ),
          ),
          // The normal publication owner is still polling Slack. Receipt
          // recovery must neither contend with it nor let its not-yet-due
          // action occupy the bounded recovery page.
          notExists(
            db
              .select({ id: chatPublications.id })
              .from(chatPublications)
              .where(
                and(
                  sql`${chatPublications.id}::text = ${chatActions.payload}->>'publicationId'`,
                  sql`${chatPublications.attempts}::text = ${chatActions.payload}->>'publicationAttempt'`,
                  eq(chatPublications.state, "streaming"),
                ),
              ),
          ),
          or(
            eq(chatActions.status, "received"),
            and(
              eq(chatActions.status, "failed"),
              sql`coalesce(${chatActions.result}->>'retryable', 'false') = 'true'`,
              sql`(${chatActions.result}->>'retryAt')::timestamptz <= ${selectedAt.toISOString()}::timestamptz`,
            ),
            and(
              eq(chatActions.status, "processing"),
              lte(
                chatActions.updatedAt,
                new Date(selectedAt.getTime() - SLACK_FILE_RECEIPT_STALE_MS),
              ),
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.updatedAt), asc(chatActions.id))
      .limit(limit);
    let processed = 0;
    for (const selected of actions) {
      const payload = slackFileUploadReceiptPayload(selected.payload);
      if (!payload) {
        await db
          .update(chatActions)
          .set({
            status: "failed",
            result: {
              code: "slack_file_upload_receipt_payload_invalid",
              retryable: false,
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, selected.id),
              eq(chatActions.kind, selected.kind),
              eq(chatActions.status, selected.status),
              sql`${chatActions.payload} = ${JSON.stringify(selected.payload)}::jsonb`,
              selected.result === null
                ? isNull(chatActions.result)
                : sql`${chatActions.result} = ${JSON.stringify(selected.result)}::jsonb`,
            ),
          );
        continue;
      }
      const record = await endpointRecord(selected.endpointId);
      if (!record) {
        await db
          .update(chatActions)
          .set({
            status: "cancelled",
            result: { code: "slack_file_upload_receipt_endpoint_removed" },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, selected.id),
              eq(chatActions.kind, selected.kind),
              eq(chatActions.status, selected.status),
              sql`${chatActions.payload} = ${JSON.stringify(selected.payload)}::jsonb`,
              selected.result === null
                ? isNull(chatActions.result)
                : sql`${chatActions.result} = ${JSON.stringify(selected.result)}::jsonb`,
            ),
          );
        continue;
      }
      if (["paused", "attention"].includes(record.endpoint.status)) continue;
      const ownerToken = randomUUID();
      let attempt = 1;
      try {
        await withCredentialMutationLease(record.endpoint, async (lease) => {
          const claim = await db.transaction(async (tx) => {
            await lease.assertOwned(tx);
            const locked = await lockSlackFileReceiptAuthorization(tx, {
              actionId: selected.id,
              payload,
            });
            const decisionAt = new Date();
            const priorAttempts =
              typeof locked?.action.result?.attempts === "number" &&
              Number.isSafeInteger(locked.action.result.attempts)
                ? locked.action.result.attempts
                : 0;
            attempt = priorAttempts + 1;
            const retryAt =
              typeof locked?.action.result?.retryAt === "string"
                ? Date.parse(locked.action.result.retryAt)
                : Number.NaN;
            const eligible = locked
              ? locked.action.status === "received" ||
                (locked.action.status === "failed" &&
                  locked.action.result?.retryable === true &&
                  Number.isFinite(retryAt) &&
                  retryAt <= decisionAt.getTime()) ||
                (locked.action.status === "processing" &&
                  locked.action.updatedAt.getTime() <=
                    decisionAt.getTime() - SLACK_FILE_RECEIPT_STALE_MS)
              : false;
            if (locked && !eligible) return null;
            if (locked?.mode === "defer") {
              if (locked.action.status === "processing") {
                await tx
                  .update(chatActions)
                  .set({
                    status: "received",
                    result: {
                      code: "slack_file_upload_identity_pending",
                      attempts: priorAttempts,
                    },
                    updatedAt: new Date(),
                  })
                  .where(eq(chatActions.id, locked.action.id));
              }
              return null;
            }
            if (locked?.mode === "settled") {
              await tx
                .update(chatActions)
                .set({
                  status: "processed",
                  result: {
                    code: "slack_file_upload_identity_confirmed",
                    attempts: priorAttempts,
                  },
                  updatedAt: new Date(),
                })
                .where(eq(chatActions.id, locked.action.id));
              return null;
            }
            if (
              !locked ||
              decisionAt.getTime() -
                (locked?.action.createdAt ?? selected.createdAt).getTime() >
                SLACK_FILE_RECEIPT_MAX_AGE_MS ||
              attempt > SLACK_FILE_RECEIPT_MAX_ATTEMPTS
            ) {
              await tx
                .update(chatActions)
                .set({
                  status: "cancelled",
                  result: {
                    code: locked
                      ? "slack_file_upload_receipt_expired"
                      : "slack_file_upload_receipt_authorization_changed",
                    attempts: priorAttempts,
                  },
                  updatedAt: decisionAt,
                })
                .where(
                  and(
                    eq(chatActions.id, selected.id),
                    inArray(chatActions.status, [
                      "received",
                      "failed",
                      "processing",
                    ]),
                  ),
                );
              return null;
            }
            if (
              !["received", "failed", "processing"].includes(
                locked.action.status,
              )
            ) {
              return null;
            }
            const [claimed] = await tx
              .update(chatActions)
              .set({
                status: "processing",
                result: {
                  attempts: attempt,
                  ownerToken,
                  ...(locked.mode === "operator_confirmed"
                    ? {
                        operatorConfirmedPublicationId:
                          locked.action.result?.operatorConfirmedPublicationId,
                        operatorConfirmedAttempt:
                          locked.action.result?.operatorConfirmedAttempt,
                        operatorConfirmedAt:
                          locked.action.result?.operatorConfirmedAt,
                      }
                    : {}),
                },
                updatedAt: decisionAt,
              })
              .where(
                and(
                  eq(chatActions.id, locked.action.id),
                  eq(chatActions.status, locked.action.status),
                ),
              )
              .returning({ id: chatActions.id });
            await lease.assertOwned(tx);
            return claimed ? locked : null;
          });
          if (!claim || !("endpoint" in claim)) return;
          processed += 1;
          const endpointRuntime = await runtimeFor(claim.endpoint);
          await lease.assertOwned();
          const providerMessageId =
            await endpointRuntime.resolveSlackFileUploadReceipt(
              payload.threadId,
              payload.fileIds,
            );
          if (!providerMessageId) {
            await db.transaction(async (tx) => {
              await lease.assertOwned(tx);
              await tx
                .update(chatActions)
                .set({
                  status: "failed",
                  result: sql`coalesce(${chatActions.result}, '{}'::jsonb) || ${JSON.stringify(
                    {
                      attempts: attempt,
                      code: "slack_file_upload_identity_pending",
                      retryable: true,
                      retryAt: new Date(
                        Date.now() + Math.min(60_000, 1_000 * 2 ** attempt),
                      ).toISOString(),
                    },
                  )}::jsonb`,
                  updatedAt: new Date(),
                })
                .where(
                  and(
                    eq(chatActions.id, selected.id),
                    eq(chatActions.status, "processing"),
                    sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                  ),
                );
            });
            return;
          }
          await db.transaction(async (tx) => {
            await lease.assertOwned(tx);
            const locked = await lockSlackFileReceiptAuthorization(tx, {
              actionId: selected.id,
              payload,
            });
            if (
              !locked ||
              locked.mode === "defer" ||
              locked.mode === "settled" ||
              !("publication" in locked) ||
              locked.action.status !== "processing" ||
              locked.action.result?.ownerToken !== ownerToken
            ) {
              if (!locked) {
                await tx
                  .update(chatActions)
                  .set({
                    status: "cancelled",
                    result: {
                      attempts: attempt,
                      code: "slack_file_upload_receipt_authorization_changed",
                    },
                    updatedAt: new Date(),
                  })
                  .where(
                    and(
                      eq(chatActions.id, selected.id),
                      eq(chatActions.status, "processing"),
                      sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                    ),
                  );
              } else if (locked.mode === "defer") {
                await tx
                  .update(chatActions)
                  .set({
                    status: "received",
                    result: {
                      attempts: attempt,
                      code: "slack_file_upload_identity_pending",
                    },
                    updatedAt: new Date(),
                  })
                  .where(
                    and(
                      eq(chatActions.id, selected.id),
                      eq(chatActions.status, "processing"),
                      sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                    ),
                  );
              } else {
                await tx
                  .update(chatActions)
                  .set({
                    status:
                      locked.mode === "settled" ? "processed" : "cancelled",
                    result: {
                      attempts: attempt,
                      code:
                        locked.mode === "settled"
                          ? "slack_file_upload_identity_confirmed"
                          : "slack_file_upload_receipt_superseded",
                    },
                    updatedAt: new Date(),
                  })
                  .where(
                    and(
                      eq(chatActions.id, selected.id),
                      eq(chatActions.status, "processing"),
                      sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                    ),
                  );
              }
              return;
            }
            const committedAt = new Date();
            if (
              !(await recordExactOutboundPublicationLink(tx, {
                publication: locked.publication,
                providerMessageId,
              }))
            ) {
              await tx
                .update(chatActions)
                .set({
                  status: "failed",
                  result: {
                    attempts: attempt,
                    code: "slack_file_upload_receipt_message_conflict",
                    retryable: false,
                  },
                  updatedAt: committedAt,
                })
                .where(eq(chatActions.id, selected.id));
              return;
            }
            if (locked.mode === "delivery_unknown") {
              const [settled] = await tx
                .update(chatPublications)
                .set({
                  state: "published",
                  providerMessageId,
                  publishedAt: committedAt,
                  nextAttemptAt: null,
                  redactedError: null,
                  updatedAt: committedAt,
                })
                .where(
                  and(
                    eq(chatPublications.id, locked.publication.id),
                    eq(chatPublications.state, "delivery_unknown"),
                    eq(chatPublications.attempts, payload.publicationAttempt),
                  ),
                )
                .returning({ id: chatPublications.id });
              if (!settled) {
                throw new Error(
                  "Slack file upload publication changed before receipt commit",
                );
              }
              await stageSlackFilePublicationSuccess(tx, {
                committedAt,
                endpoint: locked.endpoint,
                publication: locked.publication,
                providerMessageId,
                runtimeContext: {
                  generation: payload.runtimeGeneration,
                  credentialFingerprint: payload.credentialFingerprint,
                },
                stageSessionSync:
                  !isExplicitOperatorPublication(locked.publication) &&
                  !locked.publication.idempotencyKey.startsWith(
                    "control:status:",
                  ),
              });
            } else {
              const [enriched] = await tx
                .update(chatPublications)
                .set({ providerMessageId })
                .where(
                  and(
                    eq(chatPublications.id, locked.publication.id),
                    eq(chatPublications.state, "published"),
                    eq(chatPublications.attempts, payload.publicationAttempt),
                    isNull(chatPublications.providerMessageId),
                  ),
                )
                .returning({ id: chatPublications.id });
              if (!enriched) {
                throw new Error(
                  "Slack file upload publication changed before identity enrichment",
                );
              }
            }
            await tx
              .update(chatActions)
              .set({
                status: "processed",
                result: {
                  attempts: attempt,
                  code: "slack_file_upload_identity_confirmed",
                },
                updatedAt: committedAt,
              })
              .where(
                and(
                  eq(chatActions.id, selected.id),
                  eq(chatActions.status, "processing"),
                  sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                ),
              );
            await lease.assertOwned(tx);
          });
        });
      } catch (error) {
        const disposition = classifyChatPublicationError(error, attempt);
        const retryable =
          disposition.kind === "retry" ||
          disposition.kind === "delivery_unknown";
        const retryMs =
          disposition.kind === "retry"
            ? disposition.retryAfterMs
            : Math.min(60_000, 1_000 * 2 ** Math.min(attempt, 8));
        await db
          .update(chatActions)
          .set({
            status: retryable ? "failed" : "cancelled",
            result: sql`coalesce(${chatActions.result}, '{}'::jsonb) || ${JSON.stringify(
              {
                attempts: attempt,
                code: retryable
                  ? "slack_file_upload_receipt_lookup_retry"
                  : "slack_file_upload_receipt_lookup_rejected",
                retryable,
                ...(retryable
                  ? { retryAt: new Date(Date.now() + retryMs).toISOString() }
                  : {}),
              },
            )}::jsonb`,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, selected.id),
              eq(chatActions.status, "processing"),
              sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
            ),
          );
      }
    }
    return processed;
  }

  async function processPendingSlackSessionSyncs(
    limit = 25,
    onlyActionId?: string,
  ) {
    const now = new Date();
    const actions = await db
      .select()
      .from(chatActions)
      .where(
        and(
          eq(chatActions.kind, "slack_session_sync"),
          ...(onlyActionId ? [eq(chatActions.id, onlyActionId)] : []),
          or(
            and(
              eq(chatActions.status, "received"),
              sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${now.toISOString()}::timestamptz)`,
            ),
            and(
              eq(chatActions.status, "processing"),
              lte(chatActions.updatedAt, new Date(now.getTime() - 60_000)),
            ),
          ),
        ),
      )
      .orderBy(asc(chatActions.updatedAt))
      .limit(limit);
    await options.slackSessionSyncSelectionBarrier?.();
    for (const action of actions) {
      const payload = slackSessionSyncPayload(action.payload);
      if (!payload || !action.conversationId) {
        await db
          .update(chatActions)
          .set({
            status: "failed",
            result: { code: "slack_session_payload_invalid" },
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(chatActions.id, action.id),
              eq(chatActions.updatedAt, action.updatedAt),
            ),
          );
        continue;
      }
      const revisionWhere = and(
        eq(chatActions.id, action.id),
        sql`(${chatActions.payload}->>'revision')::bigint = ${payload.revision}`,
      );
      const selectedSnapshotWhere = and(
        revisionWhere,
        eq(chatActions.status, action.status),
        eq(chatActions.updatedAt, action.updatedAt),
      );
      const record = await endpointRecord(action.endpointId);
      if (record && ["paused", "attention"].includes(record.endpoint.status)) {
        await db
          .update(chatActions)
          .set({
            status: "received",
            result: { retryAt: new Date(Date.now() + 30_000).toISOString() },
            updatedAt: new Date(),
          })
          .where(selectedSnapshotWhere);
        continue;
      }
      if (!record || record.endpoint.provider !== "slack") {
        await db
          .update(chatActions)
          .set({
            status: "cancelled",
            result: { code: "slack_session_endpoint_unavailable" },
            updatedAt: new Date(),
          })
          .where(selectedSnapshotWhere);
        continue;
      }
      const attempts =
        (typeof action.result?.attempts === "number"
          ? action.result.attempts
          : 0) + 1;
      const ownerToken = randomUUID();
      let ownsAttempt = false;
      try {
        await withCredentialMutationLease(record.endpoint, async (lease) => {
          const claim = await db.transaction(async (tx) => {
            await lease.assertOwned(tx);
            const endpoint = await runtimeCallbackEndpoint(
              tx,
              action.endpointId,
              {
                generation: payload.runtimeGeneration,
                credentialFingerprint: payload.credentialFingerprint,
              },
              ["active", "verifying"],
            );
            const conversation = endpoint
              ? await tx
                  .select()
                  .from(chatConversations)
                  .where(
                    and(
                      eq(chatConversations.id, action.conversationId!),
                      eq(chatConversations.endpointId, endpoint.id),
                      eq(chatConversations.companyId, endpoint.companyId),
                      inArray(chatConversations.state, [
                        "active",
                        "waiting",
                        "completed",
                      ]),
                    ),
                  )
                  .for("update")
                  .then((rows) => rows[0] ?? null)
              : null;
            const resource =
              endpoint && conversation?.resourceId
                ? await tx
                    .select()
                    .from(chatEndpointResources)
                    .where(
                      and(
                        eq(chatEndpointResources.id, conversation.resourceId),
                        eq(chatEndpointResources.companyId, endpoint.companyId),
                        eq(chatEndpointResources.endpointId, endpoint.id),
                      ),
                    )
                    .for("update")
                    .then((rows) => rows[0] ?? null)
                : null;
            const superseded = conversation
              ? await tx
                  .select({ id: chatConversations.id })
                  .from(chatConversations)
                  .where(
                    and(
                      eq(chatConversations.companyId, conversation.companyId),
                      eq(chatConversations.endpointId, conversation.endpointId),
                      eq(
                        chatConversations.externalThreadId,
                        conversation.externalThreadId,
                      ),
                      gt(
                        chatConversations.sessionGeneration,
                        conversation.sessionGeneration,
                      ),
                    ),
                  )
                  .limit(1)
                  .then((rows) => rows.length > 0)
              : false;
            if (
              !endpoint ||
              !conversation ||
              superseded ||
              !(conversation.isDirectMessage
                ? endpoint.allowDirectMessages
                : nonDirectDestinationAllowed(endpoint, resource))
            ) {
              await tx
                .update(chatActions)
                .set({
                  status: "cancelled",
                  result: { code: "slack_session_destination_changed" },
                  updatedAt: new Date(),
                })
                .where(selectedSnapshotWhere);
              return null;
            }
            // Recompute at dispatch: a delayed processing retry must not
            // overwrite a newer final response or a later question card.
            const publication = await tx
              .select()
              .from(chatPublications)
              .where(
                and(
                  eq(chatPublications.companyId, endpoint.companyId),
                  eq(chatPublications.endpointId, endpoint.id),
                  eq(chatPublications.conversationId, conversation.id),
                  eq(chatPublications.state, "published"),
                  sql`${chatPublications.idempotencyKey} not like 'explicit%'`,
                  sql`${chatPublications.idempotencyKey} not like 'control:status:%'`,
                  sql`${chatPublications.idempotencyKey} not like 'wake:%'`,
                ),
              )
              .orderBy(
                desc(chatPublications.publishedAt),
                desc(chatPublications.createdAt),
                desc(chatPublications.id),
              )
              .limit(1)
              .then((rows) => rows[0] ?? null);
            if (!publication) {
              await tx
                .update(chatActions)
                .set({
                  status: "cancelled",
                  result: { code: "slack_session_no_published_state" },
                  updatedAt: new Date(),
                })
                .where(selectedSnapshotWhere);
              return null;
            }
            let status = slackSessionStatusForPublication(
              publication.payload,
              conversation.state === "completed",
            );
            const runId = runIdFromMilestonePublication(publication);
            if (status === "processing" && runId) {
              const run = await tx
                .select({ status: heartbeatRuns.status })
                .from(heartbeatRuns)
                .where(
                  and(
                    eq(heartbeatRuns.id, runId),
                    eq(heartbeatRuns.companyId, endpoint.companyId),
                    eq(heartbeatRuns.agentId, endpoint.assignedAgentId),
                  ),
                )
                .then((rows) => rows[0] ?? null);
              // Stop may finish before its confirmation publication. Never
              // resurrect processing from that run's earlier working receipt.
              if (!run || !["queued", "running"].includes(run.status))
                status = "active";
            }
            const claimed = await tx
              .update(chatActions)
              .set({
                status: "processing",
                result: { attempts, ownerToken },
                updatedAt: new Date(),
              })
              .where(
                and(
                  selectedSnapshotWhere,
                  or(
                    and(
                      eq(chatActions.status, "received"),
                      sql`(${chatActions.result}->>'retryAt' is null or (${chatActions.result}->>'retryAt')::timestamptz <= ${new Date().toISOString()}::timestamptz)`,
                    ),
                    and(
                      eq(chatActions.status, "processing"),
                      lte(chatActions.updatedAt, new Date(Date.now() - 60_000)),
                    ),
                  ),
                ),
              )
              .returning({ id: chatActions.id });
            await lease.assertOwned(tx);
            return claimed.length ? { endpoint, conversation, status } : null;
          });
          if (!claim) return;
          ownsAttempt = true;
          const credentials = await resolveCredentials(claim.endpoint);
          await lease.assertOwned();
          const outcome = await setSlackSessionStatus({
            botToken: credentials.botToken,
            threadId: claim.conversation.externalThreadId,
            status: claim.status,
            fetch: fetchImpl,
          });
          await db.transaction(async (tx) => {
            await lease.assertOwned(tx);
            // Refresh long work before Slack's one-hour processing timeout.
            // Unsupported sessions settle until a new publication restages
            // them; completed threads must not create perpetual polling work.
            const retryMs =
              outcome === "updated" && claim.status === "processing"
                ? 30 * 60_000
                : null;
            await tx
              .update(chatActions)
              .set({
                status: retryMs === null ? "processed" : "received",
                result: {
                  attempts,
                  outcome,
                  sessionStatus: claim.status,
                  ...(retryMs === null
                    ? {}
                    : {
                        retryAt: new Date(Date.now() + retryMs).toISOString(),
                      }),
                },
                updatedAt: new Date(),
              })
              .where(
                and(
                  revisionWhere,
                  eq(chatActions.status, "processing"),
                  sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                ),
              );
          });
        });
      } catch (error) {
        const disposition = classifyChatPublicationError(error, attempts);
        // Unlike posting a message, repeating setStatus cannot duplicate any
        // content. Ambiguous transport/receipt failures remain retryable, but
        // a definite scope/auth/destination rejection waits for new activity.
        const retryable =
          disposition.kind === "retry" ||
          disposition.kind === "delivery_unknown";
        const retryMs =
          disposition.kind === "retry"
            ? disposition.retryAfterMs
            : Math.min(5 * 60_000, 1_000 * 2 ** Math.min(attempts, 8));
        await db
          .update(chatActions)
          .set({
            status: retryable ? "received" : "failed",
            result: {
              attempts,
              code: retryable
                ? "slack_session_sync_retry"
                : "slack_session_sync_rejected",
              ...(retryable
                ? { retryAt: new Date(Date.now() + retryMs).toISOString() }
                : {}),
            },
            updatedAt: new Date(),
          })
          .where(
            and(
              revisionWhere,
              ownsAttempt
                ? and(
                    eq(chatActions.status, "processing"),
                    sql`${chatActions.result}->>'ownerToken' = ${ownerToken}`,
                  )
                : and(
                    eq(chatActions.status, "received"),
                    eq(chatActions.updatedAt, action.updatedAt),
                  ),
            ),
          );
        logger.warn(
          {
            endpointId: action.endpointId,
            actionId: action.id,
            retryable,
            error: redactError(error),
          },
          "Slack session status update did not complete; message delivery is unchanged",
        );
      }
    }
    return actions.length;
  }

  async function withPublicationAttemptLease(
    publication: typeof chatPublications.$inferSelect,
    operation: (lease: CredentialMutationLeaseGuard) => Promise<void>,
  ): Promise<void> {
    // A scheduled sweep may overlap a slow provider call (also on a standby
    // server). Claim and exact-attempt ownership must become visible together:
    // endpoint-wide activity is not evidence that this publication is alive.
    const token = randomUUID();
    const leaseKey = `publication:${publication.id}:${publication.attempts + 1}`;
    const now = new Date();
    const owned = and(
      eq(chatEndpointLeases.companyId, publication.companyId),
      eq(chatEndpointLeases.endpointId, publication.endpointId),
      eq(chatEndpointLeases.leaseKey, leaseKey),
      eq(chatEndpointLeases.token, token),
    );
    const claimed = await db.transaction(async (tx) => {
      // Transfer issuance locks this same publication. Check after acquiring
      // that lock, not through a pre-lock snapshot that could miss a new lane.
      const current = await tx
        .select({ id: chatPublications.id })
        .from(chatPublications)
        .where(
          and(
            eq(chatPublications.companyId, publication.companyId),
            eq(chatPublications.id, publication.id),
            eq(chatPublications.state, publication.state),
            eq(chatPublications.attempts, publication.attempts),
          ),
        )
        .for("update")
        .then((rows) => rows[0]);
      if (!current) return false;
      const transfer = await tx
        .select({ id: chatTeamsFileTransfers.id })
        .from(chatTeamsFileTransfers)
        .where(
          and(
            eq(chatTeamsFileTransfers.companyId, publication.companyId),
            eq(chatTeamsFileTransfers.publicationId, current.id),
          ),
        )
        .then((rows) => rows[0]);
      if (transfer) return false;
      const [row] = await tx
        .update(chatPublications)
        .set({
          state: "streaming",
          attempts: publication.attempts + 1,
          updatedAt: now,
        })
        .where(
          and(
            eq(chatPublications.id, publication.id),
            eq(chatPublications.state, publication.state),
            eq(chatPublications.attempts, publication.attempts),
          ),
        )
        .returning({ id: chatPublications.id });
      if (!row) return false;
      await tx.insert(chatEndpointLeases).values({
        companyId: publication.companyId,
        endpointId: publication.endpointId,
        leaseKey,
        token,
        expiresAt: new Date(now.getTime() + CREDENTIAL_MUTATION_LEASE_TTL_MS),
      });
      return true;
    });
    if (!claimed) return;
    let leaseLoss: Error | null = null;
    const assertOwned: CredentialMutationLeaseGuard["assertOwned"] = async (
      database = db,
    ) => {
      if (leaseLoss) throw leaseLoss;
      try {
        // Use a savepoint when the caller already owns a transaction. The
        // decision clock is sampled only after the lease row lock resolves;
        // an UPDATE predicate using a pre-lock clock can revive expired work.
        await database.transaction(async (tx) => {
          const current = await tx
            .select({ expiresAt: chatEndpointLeases.expiresAt })
            .from(chatEndpointLeases)
            .where(owned)
            .for("update")
            .then((rows) => rows[0] ?? null);
          const checkedAt = new Date();
          if (
            leaseLoss ||
            !current ||
            current.expiresAt.getTime() <= checkedAt.getTime()
          ) {
            throw new Error("Publication attempt lease is no longer owned");
          }
          await tx
            .update(chatEndpointLeases)
            .set({
              expiresAt: new Date(
                checkedAt.getTime() + CREDENTIAL_MUTATION_LEASE_TTL_MS,
              ),
              updatedAt: checkedAt,
            })
            .where(owned);
        });
      } catch (error) {
        leaseLoss = Object.assign(
          new Error(
            "Chat publication attempt ownership was lost before completion",
            { cause: error },
          ),
          { code: "CHAT_PUBLICATION_LEASE_LOST" },
        );
        throw leaseLoss;
      }
    };
    let renewal: Promise<void> | null = null;
    const timer = setInterval(() => {
      if (renewal || leaseLoss) return;
      renewal = assertOwned()
        .catch(() => undefined)
        .finally(() => {
          renewal = null;
        });
    }, CREDENTIAL_MUTATION_LEASE_TTL_MS / 3);
    timer.unref?.();
    try {
      await operation({ assertOwned });
    } finally {
      clearInterval(timer);
      await renewal;
      await db.delete(chatEndpointLeases).where(owned);
    }
  }

  async function processSelectedPublication(
    selectedPublication: typeof chatPublications.$inferSelect,
  ): Promise<void> {
    let publication: typeof chatPublications.$inferSelect;
    try {
      publication =
        await ensureDurablePublicationTransport(selectedPublication);
    } catch (error) {
      try {
        await settlePublicationPreparationFailure(selectedPublication, error);
      } catch (settlementError) {
        logger.error(
          {
            endpointId: selectedPublication.endpointId,
            publicationId: selectedPublication.id,
            error: redactError(settlementError),
          },
          "could not durably settle chat publication preparation failure",
        );
      }
      return;
    }
    const earlierOpenPublication = await db
      .select({ id: chatPublications.id })
      .from(chatPublications)
      .where(
        and(
          eq(chatPublications.conversationId, publication.conversationId),
          or(
            lt(chatPublications.createdAt, publication.createdAt),
            and(
              eq(chatPublications.createdAt, publication.createdAt),
              lt(
                publicationTransportOrderKey(chatPublications),
                publication.payload.transportPart?.orderKey ?? publication.id,
              ),
            ),
          ),
          inArray(chatPublications.state, [
            "pending",
            "retry",
            "streaming",
            "delivery_unknown",
          ]),
        ),
      )
      .limit(1)
      .then((result) => result[0] ?? null);
    if (earlierOpenPublication) return;
    if (await tryProcessTeamsFilePublication(publication)) return;
    await withPublicationAttemptLease(publication, async (publicationLease) => {
      let providerAccepted = false;
      let publicationRuntimeContext: RuntimeContext | null = null;
      let failureHandledWithinCredentialLease = false;
      let slackFileReceiptActionId: string | null = null;
      const settlePublicationFailure = async (
        error: unknown,
        credentialLease?: CredentialMutationLeaseGuard,
      ) => {
        try {
          await finalizePublicationFailure(
            publication,
            error,
            providerAccepted,
            publicationRuntimeContext,
            credentialLease ?? publicationLease,
          );
        } catch (finalizationError) {
          // If the provider accepted the message, a failed receipt write
          // must remain streaming until the stale scan quarantines it. A
          // later lifecycle mutation must not turn this into an implicit
          // replay or allow a stale failure to overwrite the new runtime.
          logger.error(
            {
              endpointId: publication.endpointId,
              publicationId: publication.id,
              error: redactError(finalizationError),
            },
            "could not durably finalize chat publication failure",
          );
        }
      };
      try {
        const recordForLease = await endpointRecord(publication.endpointId);
        if (!recordForLease)
          throw new Error("Chat publication binding is unavailable");
        const currentPublicationRuntimeContext =
          runtimeContextForRecord(recordForLease);
        publicationRuntimeContext = currentPublicationRuntimeContext;
        const [endpoint, conversation] = await Promise.all([
          db
            .select()
            .from(chatEndpoints)
            .where(eq(chatEndpoints.id, publication.endpointId))
            .then((result) => result[0] ?? null),
          db
            .select()
            .from(chatConversations)
            .where(eq(chatConversations.id, publication.conversationId))
            .then((result) => result[0] ?? null),
        ]);
        if (!endpoint || !conversation)
          throw new Error("Chat publication binding is unavailable");
        const providerVisibleCompletion =
          conversation.state === "completed" &&
          !isExplicitOperatorPublication(publication) &&
          (await hasCommittedTaskControlCompletion(conversation.id));
        if (endpoint.status === "paused" || endpoint.status === "attention") {
          await publicationLease.assertOwned();
          await db
            .update(chatPublications)
            .set({
              state: "pending",
              attempts: publication.attempts,
              // Pause can race the eligibility read. The query excludes
              // inactive endpoints on the next pass, so retain only the
              // original provider deadline rather than delaying Resume.
              nextAttemptAt: publication.nextAttemptAt,
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatPublications.id, publication.id),
                eq(chatPublications.state, "streaming"),
                eq(chatPublications.attempts, publication.attempts + 1),
              ),
            );
          return;
        }
        // The setup conversation is a real end-to-end test: once provider
        // credentials are verified, its safe agent response must be able to
        // reach the provider before the operator confirms the final wizard
        // step. Draft, paused, revoked, and archived endpoints remain closed.
        if (
          !["active", "verifying"].includes(endpoint.status) ||
          ["unavailable", "endpoint_removed"].includes(conversation.state) ||
          providerVisibleCompletion
        ) {
          await publicationLease.assertOwned();
          await db
            .update(chatPublications)
            .set({
              state: "cancelled",
              redactedError: providerVisibleCompletion
                ? "Conversation was completed before delivery"
                : "External destination is no longer active",
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatPublications.id, publication.id),
                eq(chatPublications.state, "streaming"),
                eq(chatPublications.attempts, publication.attempts + 1),
              ),
            );
          return;
        }
        if (conversation.isDirectMessage) {
          if (!endpoint.allowDirectMessages) {
            await publicationLease.assertOwned();
            await db
              .update(chatPublications)
              .set({
                state: "cancelled",
                redactedError: "Direct messages are disabled in Paperclip",
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatPublications.id, publication.id),
                  eq(chatPublications.state, "streaming"),
                  eq(chatPublications.attempts, publication.attempts + 1),
                ),
              );
            return;
          }
        } else {
          const resource = conversation.resourceId
            ? await db
                .select()
                .from(chatEndpointResources)
                .where(
                  and(
                    eq(chatEndpointResources.id, conversation.resourceId),
                    eq(chatEndpointResources.endpointId, endpoint.id),
                    eq(chatEndpointResources.companyId, endpoint.companyId),
                  ),
                )
                .then((result) => result[0] ?? null)
            : null;
          if (!nonDirectDestinationAllowed(endpoint, resource)) {
            await publicationLease.assertOwned();
            await db
              .update(chatPublications)
              .set({
                state: "cancelled",
                redactedError: "Destination is disabled in Paperclip",
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatPublications.id, publication.id),
                  eq(chatPublications.state, "streaming"),
                  eq(chatPublications.attempts, publication.attempts + 1),
                ),
              );
            return;
          }
        }
        const interactionId = publication.payload.interactionId;
        const isInteractionPrompt =
          Boolean(interactionId) &&
          publication.idempotencyKey ===
            `interaction:${interactionId}:${publication.endpointId}`;
        if (isInteractionPrompt && publication.issueId) {
          const currentInteraction = await db
            .select({ status: issueThreadInteractions.status })
            .from(issueThreadInteractions)
            .where(
              and(
                eq(issueThreadInteractions.id, interactionId!),
                eq(issueThreadInteractions.companyId, publication.companyId),
                eq(issueThreadInteractions.issueId, publication.issueId),
              ),
            )
            .then((result) => result[0] ?? null);
          if (!currentInteraction || currentInteraction.status !== "pending") {
            await publicationLease.assertOwned();
            await db
              .update(chatPublications)
              .set({
                state: "cancelled",
                attempts: publication.attempts,
                nextAttemptAt: null,
                redactedError: "Interaction resolved before provider delivery",
                updatedAt: new Date(),
              })
              .where(
                and(
                  eq(chatPublications.id, publication.id),
                  eq(chatPublications.state, "streaming"),
                  eq(chatPublications.attempts, publication.attempts + 1),
                ),
              );
            return;
          }
        }
        // Milestone selection and insertion can overlap across sweeps. An old
        // snapshot inserted after newer attention must not overwrite it simply
        // because it now occupies the next FIFO slot.
        const progressSupersessionReason =
          (await runOwnershipMilestoneSupersessionReason(publication)) ??
          ((await runProgressSupersededByPublishedInteraction(publication))
            ? "Run progress was superseded by its provider interaction"
            : null);
        if (progressSupersessionReason) {
          await publicationLease.assertOwned();
          await db
            .update(chatPublications)
            .set({
              state: "cancelled",
              attempts: publication.attempts,
              nextAttemptAt: null,
              redactedError: progressSupersessionReason,
              updatedAt: new Date(),
            })
            .where(
              and(
                eq(chatPublications.id, publication.id),
                eq(chatPublications.state, "streaming"),
                eq(chatPublications.attempts, publication.attempts + 1),
              ),
            );
          return;
        }
        // Status is sampled when it reaches the head of the provider lane,
        // not when the command was admitted. If an already-streaming final
        // publication won the race, this reply reflects Paperclip's latest
        // authoritative task state after that earlier send commits.
        let payload = await currentTaskControlPayload(publication);
        await withCredentialMutationLease(
          recordForLease.endpoint,
          async (credentialGuard) => {
            const credentialLease: CredentialMutationLeaseGuard = {
              assertOwned: async (database = db) => {
                await credentialGuard.assertOwned(database);
                await publicationLease.assertOwned(database);
              },
            };
            try {
              // A prior failure's provider ID may have been reused while this
              // worker waited for the endpoint lane. Select against current
              // outbound links only after owning that lane, before the final
              // source authorization claim and provider I/O.
              const closedProgress = await closeProgressToReplace(
                publication,
                endpoint,
              );
              const replaceProviderMessageId = CAPABILITIES[endpoint.provider]
                .messageEdits
                ? (closedProgress?.providerMessageId ??
                  (await interactionResolutionPublicationToReplace(
                    publication,
                    payload,
                  )) ??
                  (await interactionPromptPublicationToReplace(
                    publication,
                    payload,
                  )) ??
                  (await runPublicationToReplace(publication, payload)) ??
                  (await inboundWakePublicationToReplace(
                    publication,
                    payload,
                  )) ??
                  (await taskStatusPublicationToReplace(publication, payload)))
                : null;
              const authorizationClaim =
                await claimPublicationTransportAuthorization({
                  credentialLease,
                  endpoint: recordForLease.endpoint,
                  publication,
                  runtimeContext: currentPublicationRuntimeContext,
                });
              if (!authorizationClaim) {
                await db.transaction(async (tx) => {
                  await credentialLease.assertOwned(tx);
                  await tx
                    .update(chatPublications)
                    .set({
                      state: "cancelled",
                      nextAttemptAt: null,
                      redactedError:
                        "Task control requester or destination is no longer authorized",
                      updatedAt: new Date(),
                    })
                    .where(
                      and(
                        eq(chatPublications.id, publication.id),
                        eq(chatPublications.state, "streaming"),
                        eq(chatPublications.attempts, publication.attempts + 1),
                      ),
                    );
                  await tx
                    .update(chatActions)
                    .set({
                      status: "cancelled",
                      result: {
                        code: "task_control_authorization_changed",
                      },
                      updatedAt: new Date(),
                    })
                    .where(
                      and(
                        eq(chatActions.endpointId, publication.endpointId),
                        eq(
                          chatActions.providerActionId,
                          `task-control-authorization:${publication.id}`,
                        ),
                        eq(chatActions.status, "issued"),
                      ),
                    );
                  await credentialLease.assertOwned(tx);
                });
                return;
              }
              // The durable claim above is the authorization linearization
              // point. Provider I/O runs without a database transaction or
              // row lock. The renewable lease preserves credential/runtime
              // identity until conditional settlement.
              if (authorizationClaim.preparedText !== null)
                payload = { ...payload, text: authorizationClaim.preparedText };
              const telegramDraft =
                authorizationClaim.endpoint.provider === "telegram" &&
                authorizationClaim.conversation.isDirectMessage &&
                !replaceProviderMessageId &&
                !payload.transportPart &&
                !payload.card &&
                !payload.attachmentIds?.length &&
                shouldStreamSafePublicationText(
                  renderPublicationTransportText(payload),
                ) &&
                (await hasTelegramStopSubscription(
                  authorizationClaim.endpoint,
                  currentPublicationRuntimeContext,
                ))
                  ? await reserveTelegramPublicationDraft({
                      endpoint: authorizationClaim.endpoint,
                      conversation: authorizationClaim.conversation,
                      publication,
                      text: renderPublicationTransportText(payload),
                      credentialLease,
                      runtimeContext: currentPublicationRuntimeContext,
                    })
                  : null;
              const sent = await postSafePublication({
                endpoint: authorizationClaim.endpoint,
                conversation: authorizationClaim.conversation,
                publication,
                payload,
                replaceProviderMessageId,
                telegramDraftControl: telegramDraft?.control,
                onSlackFileUploadAccepted: async (receipt) => {
                  // uploadV2 has completed at this point. Mark acceptance
                  // before the durable callback so a local write failure is
                  // still quarantined and can never trigger an implicit upload.
                  providerAccepted = true;
                  slackFileReceiptActionId = await recordSlackFileUploadReceipt(
                    {
                      credentialLease,
                      endpoint: authorizationClaim.endpoint,
                      conversation: authorizationClaim.conversation,
                      publication,
                      receipt,
                      runtimeContext: currentPublicationRuntimeContext,
                    },
                  );
                },
              });
              if (isTelegramDraftStopped(sent)) {
                // Only the durable stop transaction can produce this outcome.
                // It settled this exact publication; never fabricate a provider
                // receipt, complete its task, or enqueue a retry from this path.
                if (!telegramDraft)
                  throw new Error("Unexpected Telegram draft stop result");
                const stopped = await db
                  .select({ id: chatActions.id })
                  .from(chatActions)
                  .innerJoin(
                    chatPublications,
                    and(
                      eq(chatPublications.id, publication.id),
                      eq(chatPublications.state, "cancelled"),
                      eq(chatPublications.attempts, publication.attempts + 1),
                    ),
                  )
                  .where(
                    and(
                      eq(chatActions.id, telegramDraft.actionId),
                      eq(chatActions.status, "cancelled"),
                      sql`${chatActions.result}->>'phase' = 'stopped'`,
                    ),
                  );
                if (stopped.length !== 1)
                  throw new Error(
                    "Telegram draft stop was not durably committed",
                  );
                return;
              }
              providerAccepted = true;
              // A resolved SDK call is not a usable delivery receipt. Teams,
              // for example, returns an empty ID for an empty HTTP success
              // body. Preserve uncertainty instead of publishing a broken
              // message link or automatically sending the content again.
              if (
                typeof sent?.id !== "string" ||
                !sent.id ||
                sent.id.length > 2048 ||
                sent.id.trim() !== sent.id ||
                /[\u0000-\u001f\u007f]/.test(sent.id)
              ) {
                throw new Error(
                  "Provider did not return a usable message receipt",
                );
              }
              const { authorizationActionId } = authorizationClaim;
              const receiptRemovalActionIds: string[] = [];
              await db.transaction(async (tx) => {
                await credentialLease.assertOwned(tx);
                const committedAt = new Date();
                const [completedPublication] = await tx
                  .update(chatPublications)
                  .set({
                    state: "published",
                    payload,
                    providerMessageId: sent.id,
                    publishedAt: committedAt,
                    redactedError: null,
                    updatedAt: committedAt,
                  })
                  .where(
                    and(
                      eq(chatPublications.id, publication.id),
                      eq(chatPublications.state, "streaming"),
                      eq(chatPublications.attempts, publication.attempts + 1),
                    ),
                  )
                  .returning({ id: chatPublications.id });
                if (!completedPublication) {
                  throw new Error(
                    "Chat publication ownership changed before commit",
                  );
                }
                if (telegramDraft) {
                  const completedDraft = await tx
                    .update(chatActions)
                    .set({
                      status: "processed",
                      result: {
                        phase: "published",
                        providerMessageId: sent.id,
                      },
                      updatedAt: committedAt,
                    })
                    .where(
                      and(
                        eq(chatActions.id, telegramDraft.actionId),
                        eq(chatActions.status, "processing"),
                        sql`${chatActions.result}->>'phase' = 'final_sending'`,
                      ),
                    )
                    .returning({ id: chatActions.id });
                  if (completedDraft.length !== 1)
                    throw new Error(
                      "Telegram final draft ownership changed before commit",
                    );
                }
                if (slackFileReceiptActionId) {
                  const [completedReceipt] = await tx
                    .update(chatActions)
                    .set({
                      status: "processed",
                      result: {
                        code: "slack_file_upload_identity_confirmed",
                        attempts: 1,
                      },
                      updatedAt: committedAt,
                    })
                    .where(
                      and(
                        eq(chatActions.id, slackFileReceiptActionId),
                        eq(chatActions.kind, "slack_file_upload_receipt"),
                        eq(chatActions.status, "received"),
                        sql`(${chatActions.payload}->>'publicationId')::uuid = ${publication.id}`,
                        sql`(${chatActions.payload}->>'publicationAttempt')::int = ${publication.attempts + 1}`,
                      ),
                    )
                    .returning({ id: chatActions.id });
                  if (!completedReceipt) {
                    throw new Error(
                      "Slack file upload receipt ownership changed before commit",
                    );
                  }
                }
                if (slackFileReceiptActionId) {
                  await stageSlackFilePublicationSuccess(tx, {
                    committedAt,
                    endpoint: authorizationClaim.endpoint,
                    publication,
                    providerMessageId: sent.id,
                    runtimeContext: currentPublicationRuntimeContext,
                    stageSessionSync:
                      !isExplicitOperatorPublication(publication) &&
                      !publication.idempotencyKey.startsWith("control:status:"),
                  });
                } else {
                  // A queue notice references its causal inbound comment for
                  // authorization, but is not an authored copy of that comment.
                  // Reactions/readers must not attribute bot status to the user.
                  const linkedCommentId = parseInboundWakePublicationKey(
                    publication.idempotencyKey,
                  )
                    ? null
                    : publication.commentId;
                  const messageLinkInsert = tx.insert(chatMessageLinks).values({
                    companyId: publication.companyId,
                    endpointId: publication.endpointId,
                    conversationId: publication.conversationId,
                    publicationId: publication.id,
                    commentId: linkedCommentId,
                    providerMessageId: sent.id,
                    direction: "outbound",
                  });
                  if (replaceProviderMessageId) {
                    await messageLinkInsert.onConflictDoUpdate({
                      target: [
                        chatMessageLinks.endpointId,
                        chatMessageLinks.conversationId,
                        chatMessageLinks.providerMessageId,
                      ],
                      set: {
                        publicationId: publication.id,
                        commentId: linkedCommentId,
                      },
                    });
                  } else {
                    await messageLinkInsert.onConflictDoNothing();
                  }
                  await tx
                    .update(chatEndpoints)
                    .set({
                      lastPublicationAt: committedAt,
                      updatedAt: committedAt,
                    })
                    .where(
                      and(
                        eq(chatEndpoints.id, authorizationClaim.endpoint.id),
                        inArray(chatEndpoints.status, ["verifying", "active"]),
                        sql`coalesce((${chatEndpoints.setup}->>'runtimeGeneration')::integer, 0) = ${currentPublicationRuntimeContext.generation}`,
                      ),
                    );
                }
                if (authorizationActionId) {
                  const processedAuthorization = await tx
                    .update(chatActions)
                    .set({
                      status: "processed",
                      result: { code: "task_control_authorized_and_sent" },
                      updatedAt: committedAt,
                    })
                    .where(
                      and(
                        eq(chatActions.id, authorizationActionId),
                        eq(chatActions.status, "processing"),
                        sql`(${chatActions.result}->>'attempts')::int = ${publication.attempts + 1}`,
                      ),
                    )
                    .returning({ id: chatActions.id });
                  if (!processedAuthorization.length) {
                    throw new Error(
                      "Task-control authorization ownership changed before commit",
                    );
                  }
                }
                await commitTaskControlCompletion(
                  tx as unknown as Db,
                  publication,
                  committedAt,
                );
                if (
                  !slackFileReceiptActionId &&
                  authorizationClaim.endpoint.provider === "slack" &&
                  !isExplicitOperatorPublication(publication) &&
                  !parseInboundWakePublicationKey(publication.idempotencyKey) &&
                  !publication.idempotencyKey.startsWith("control:status:")
                ) {
                  await stageSlackSessionSync(tx, {
                    companyId: publication.companyId,
                    endpointId: publication.endpointId,
                    conversationId: publication.conversationId,
                    runtimeGeneration:
                      currentPublicationRuntimeContext.generation,
                    credentialFingerprint:
                      currentPublicationRuntimeContext.credentialFingerprint,
                  });
                }
                receiptRemovalActionIds.push(
                  ...(await stageTerminalReceiptReactionRemovals(
                    tx as unknown as Db,
                    {
                      endpoint: authorizationClaim.endpoint,
                      publication,
                      payload,
                      runtimeContext: currentPublicationRuntimeContext,
                      closedProgressRunId: closedProgress?.runId,
                    },
                  )),
                );
                await credentialLease.assertOwned(tx);
              });
              // Receipt cleanup is non-critical provider I/O. Dispatch it
              // after the terminal reply and durable action commit so a
              // slow reaction endpoint cannot hold the publication lane.
              // If this process stops first, the action outbox resumes the
              // idempotent removal on a later reconciliation sweep.
              for (const actionId of receiptRemovalActionIds) {
                scheduleMessageProcessing(() =>
                  processReceiptReaction(actionId),
                );
              }
            } catch (error) {
              // Authentication, membership, and destination failures mutate
              // endpoint/runtime state. Settle them before releasing the
              // credential lease so a concurrent reconnect or provider
              // recovery cannot be overwritten by this stale attempt.
              failureHandledWithinCredentialLease = true;
              // If ownership was already lost, leave the publication in its
              // conservative streaming state for quarantine. Mutating health
              // from this obsolete runtime would overwrite the new owner.
              await settlePublicationFailure(error, credentialLease);
            }
          },
        );
      } catch (error) {
        if (!failureHandledWithinCredentialLease)
          await settlePublicationFailure(error);
      }
    });
  }

  async function processPendingPublications(
    limit = 25,
    { waitForCompletion = true }: { waitForCompletion?: boolean } = {},
  ) {
    if (shuttingDown) return 0;
    await enqueueInboundWakeupPublications();
    await reconcileTerminalConfirmationActions(limit);
    const now = new Date();
    const staleBefore = new Date(now.getTime() - 60_000);
    // A process that disappears after the provider accepted a post but before
    // Paperclip persisted its message id leaves an ambiguous delivery. Never
    // resend it automatically; an operator can explicitly replay after
    // checking the provider conversation.
    const quarantinedPublications = await db
      .update(chatPublications)
      .set({
        state: "delivery_unknown",
        nextAttemptAt: null,
        redactedError:
          "Provider delivery could not be confirmed after the worker stopped. Check the external conversation before replaying.",
        updatedAt: now,
      })
      .where(
        and(
          eq(chatPublications.state, "streaming"),
          lte(chatPublications.updatedAt, staleBefore),
          // Teams owns separate staged I/O intents and a longer attempt lease.
          // Only that protocol may recover/quarantine its in-flight stages.
          notExists(
            db
              .select({ id: chatTeamsFileTransfers.id })
              .from(chatTeamsFileTransfers)
              .where(
                and(
                  eq(
                    chatTeamsFileTransfers.companyId,
                    chatPublications.companyId,
                  ),
                  eq(chatTeamsFileTransfers.publicationId, chatPublications.id),
                ),
              ),
          ),
          notExists(
            db
              .select({ id: chatEndpointLeases.id })
              .from(chatEndpointLeases)
              .where(
                and(
                  eq(chatEndpointLeases.companyId, chatPublications.companyId),
                  eq(
                    chatEndpointLeases.endpointId,
                    chatPublications.endpointId,
                  ),
                  sql`${chatEndpointLeases.leaseKey} = 'publication:' || ${chatPublications.id}::text || ':' || ${chatPublications.attempts}::text`,
                  gt(chatEndpointLeases.expiresAt, now),
                ),
              ),
          ),
        ),
      )
      .returning({ id: chatPublications.id });
    if (quarantinedPublications.length > 0) {
      await db
        .update(chatActions)
        .set({
          status: "delivery_unknown",
          result: {
            code: "task_control_delivery_unknown",
            retryable: false,
          },
          updatedAt: now,
        })
        .where(
          and(
            eq(chatActions.kind, "task_control_authorization"),
            eq(chatActions.status, "processing"),
            inArray(
              chatActions.providerActionId,
              quarantinedPublications.map(
                (publication) => `task-control-authorization:${publication.id}`,
              ),
            ),
          ),
        );
    }
    const earlierPublication = alias(
      chatPublications,
      "earlier_chat_publications",
    );
    const attemptedIds: string[] = [];
    const ownedTasks = new Set<Promise<void>>();
    let failed = false;
    let firstError: unknown;
    try {
      while (attemptedIds.length < limit && !failed && !shuttingDown) {
        if (publicationEndpointTasks.size >= PUBLICATION_ENDPOINT_CONCURRENCY) {
          if (!waitForCompletion) break;
          await Promise.race(publicationEndpointTasks.values());
          continue;
        }
        const busyEndpointIds = [...publicationEndpointTasks.keys()];
        for (const [id, retryAfter] of teamsFileRetryAfter)
          if (retryAfter <= Date.now()) teamsFileRetryAfter.delete(id);
        const coolingTeamsPublicationIds = [...teamsFileRetryAfter.keys()];
        // Select only each conversation's current head before applying the
        // global limit. Re-query after every batch so one invocation can still
        // drain a conversation's newly unblocked milestones in FIFO order.
        const rows = await db
          .select()
          .from(chatPublications)
          .where(
            and(
              or(
                and(
                  inArray(chatPublications.state, ["pending", "retry"]),
                  notExists(
                    db
                      .select({ id: chatTeamsFileTransfers.id })
                      .from(chatTeamsFileTransfers)
                      .where(
                        and(
                          eq(
                            chatTeamsFileTransfers.companyId,
                            chatPublications.companyId,
                          ),
                          eq(
                            chatTeamsFileTransfers.publicationId,
                            chatPublications.id,
                          ),
                        ),
                      ),
                  ),
                ),
                // Dedicated protocol work shares the endpoint concurrency cap,
                // never the ordinary publication claim or resend implementation.
                sql`exists (${db
                  .select({ id: chatTeamsFileTransfers.id })
                  .from(chatTeamsFileTransfers)
                  .where(
                    and(
                      eq(
                        chatTeamsFileTransfers.companyId,
                        chatPublications.companyId,
                      ),
                      eq(
                        chatTeamsFileTransfers.endpointId,
                        chatPublications.endpointId,
                      ),
                      eq(
                        chatTeamsFileTransfers.conversationId,
                        chatPublications.conversationId,
                      ),
                      eq(
                        chatTeamsFileTransfers.publicationId,
                        chatPublications.id,
                      ),
                      sql`exists (${db
                        .select({ id: chatEndpoints.id })
                        .from(chatEndpoints)
                        .where(
                          and(
                            eq(chatEndpoints.id, chatPublications.endpointId),
                            eq(
                              chatEndpoints.companyId,
                              chatPublications.companyId,
                            ),
                            eq(chatEndpoints.provider, "microsoft-teams"),
                            eq(chatEndpoints.status, "active"),
                          ),
                        )})`,
                      or(
                        inArray(chatTeamsFileTransfers.phase, [
                          "consent_pending",
                          "upload_pending",
                          "file_info_pending",
                        ]),
                        and(
                          eq(chatTeamsFileTransfers.phase, "consent_unknown"),
                          isNotNull(chatTeamsFileTransfers.responseActivityId),
                          sql`${chatTeamsFileTransfers.privateState}->'response' is not null`,
                        ),
                      ),
                    ),
                  )})`,
              ),
              busyEndpointIds.length > 0
                ? notInArray(chatPublications.endpointId, busyEndpointIds)
                : undefined,
              coolingTeamsPublicationIds.length > 0
                ? notInArray(chatPublications.id, coolingTeamsPublicationIds)
                : undefined,
              // Inactive endpoints must not consume the eligibility page or
              // acquire an artificial retry deadline. When an operator resumes
              // them, due work is immediately eligible; genuine provider retry
              // deadlines below remain unchanged.
              notExists(
                db
                  .select({ id: chatEndpoints.id })
                  .from(chatEndpoints)
                  .where(
                    and(
                      eq(chatEndpoints.id, chatPublications.endpointId),
                      inArray(chatEndpoints.status, ["paused", "attention"]),
                    ),
                  ),
              ),
              or(
                isNull(chatPublications.nextAttemptAt),
                lte(chatPublications.nextAttemptAt, now),
              ),
              attemptedIds.length > 0
                ? notInArray(chatPublications.id, attemptedIds)
                : undefined,
              notExists(
                db
                  .select({ id: earlierPublication.id })
                  .from(earlierPublication)
                  .where(
                    and(
                      eq(
                        earlierPublication.conversationId,
                        chatPublications.conversationId,
                      ),
                      publicationPrecedes(earlierPublication, chatPublications),
                      inArray(earlierPublication.state, [
                        "pending",
                        "retry",
                        "streaming",
                        "delivery_unknown",
                      ]),
                    ),
                  ),
              ),
            ),
          )
          .orderBy(
            asc(chatPublications.createdAt),
            asc(publicationTransportOrderKey(chatPublications)),
          )
          .limit(limit - attemptedIds.length);
        if (rows.length === 0) {
          // The query excluded the busy-endpoint snapshot above. A worker
          // may have completed while PostgreSQL selected this empty page,
          // exposing a new head that must be queried before declaring idle.
          if (busyEndpointIds.some((id) => !publicationEndpointTasks.has(id)))
            continue;
          if (!waitForCompletion || publicationEndpointTasks.size === 0) break;
          await Promise.race(publicationEndpointTasks.values());
          continue;
        }
        let started = false;
        for (const selectedPublication of rows) {
          if (
            publicationEndpointTasks.size >= PUBLICATION_ENDPOINT_CONCURRENCY ||
            attemptedIds.length >= limit ||
            failed ||
            shuttingDown
          )
            break;
          if (publicationEndpointTasks.has(selectedPublication.endpointId))
            continue;
          attemptedIds.push(selectedPublication.id);
          started = true;
          // Reserve synchronously before provider work; overlapping drains share
          // this cap. Different conversations for one bot keep the existing
          // endpoint-exclusive credential fence instead of timing out behind it.
          const task = Promise.resolve()
            .then(() => processSelectedPublication(selectedPublication))
            .catch((error: unknown) => {
              if (!failed) {
                failed = true;
                firstError = error;
              }
              if (!waitForCompletion) {
                logger.error(
                  {
                    endpointId: selectedPublication.endpointId,
                    publicationId: selectedPublication.id,
                    error: redactError(error),
                  },
                  "scheduled chat publication worker failed",
                );
              }
            })
            .finally(() => {
              if (
                publicationEndpointTasks.get(selectedPublication.endpointId) ===
                task
              ) {
                publicationEndpointTasks.delete(selectedPublication.endpointId);
              }
              ownedTasks.delete(task);
            });
          publicationEndpointTasks.set(selectedPublication.endpointId, task);
          ownedTasks.add(task);
        }
        // Re-query while slots remain: one busy endpoint must not fill the
        // candidate page and hide later eligible endpoints behind its backlog.
        if (!started && publicationEndpointTasks.size > 0) {
          if (!waitForCompletion) break;
          await Promise.race(publicationEndpointTasks.values());
        }
      }
    } catch (error) {
      if (!failed) {
        failed = true;
        firstError = error;
      }
    } finally {
      // Observe rejection immediately above and join every started worker
      // before this invocation returns or propagates its original failure.
      if (waitForCompletion) await Promise.all(ownedTasks);
    }
    if (failed) throw firstError;
    await processPendingInteractionWakeups(limit);
    return attemptedIds.length;
  }

  // Cron refills free endpoint slots from the durable outbox each second.
  // Work remains tracked by this service and is joined before runtime shutdown.
  async function schedulePendingPublications(limit = 25) {
    scheduleTeamsFileMaintenance();
    return processPendingPublications(limit, { waitForCompletion: false });
  }

  async function getIssueBinding(
    issueId: string,
  ): Promise<ExternalChannelBindingSummary | null> {
    const companyId = await db
      .select({ companyId: issues.companyId })
      .from(issues)
      .where(eq(issues.id, issueId))
      .then((rows) => rows[0]?.companyId ?? null);
    return companyId
      ? getExternalChannelBindingSummary(db, companyId, issueId)
      : null;
  }

  return {
    runtime,
    list,
    get,
    create,
    update,
    generateSetupSecret,
    configure,
    test,
    handleWebhook,
    listResources,
    replaceResources,
    listPrincipals,
    createLinkIntent,
    previewIdentityLink,
    confirmIdentityLink,
    revokeLink,
    listConversations,
    listActivity,
    replayDelivery,
    replayPublication,
    resolveAction,
    resolvePublication,
    publishComment,
    getPublicationBatchStatus,
    publishBoardMessage,
    reconcileProviderRuntimes,
    processPendingPublications,
    enqueueInboundWakeupPublications,
    schedulePendingPublications,
    processPendingDeliveries,
    prepareFailedChatRunRetry,
    authorizeFailedChatRunRetry,
    processFailedChatRunRetry,
    processFailedChatRunRetries,
    processPendingGitHubWebhookIngress,
    processFailedGitHubWebhookDeliveries,
    processPendingProviderEffects,
    processPendingReceiptReactions,
    processPendingSlackFileUploadReceipts,
    processPendingSlackSessionStops,
    processPendingSlackSessionSyncs,
    getIssueBinding,
    shutdown: async () => {
      shuttingDown = true;
      await Promise.allSettled([...failedRetryTasks.values()]);
      unregisterFailedRetryAuthority();
      unregisterCommittedResponseAuthority();
      await Promise.allSettled([...publicationEndpointTasks.values()]);
      await Promise.allSettled([...backgroundMessageTasks]);
      scheduledConversationDrains.clear();
      liveInboundMessages.clear();
      const ownedDiscordGateways = [...discordGatewayOwnerships.values()];
      for (const ownership of ownedDiscordGateways) {
        ownership.stopping = true;
        if (ownership.renewTimer) {
          clearInterval(ownership.renewTimer);
          ownership.renewTimer = null;
        }
      }
      discordGatewayOwnerships.clear();
      await Promise.allSettled(
        ownedDiscordGateways
          .map((ownership) => ownership.renewal)
          .filter((renewal): renewal is Promise<void> => renewal !== null),
      );
      await Promise.allSettled([...discordGatewayStopTasks]);
      // Stop every provider runtime before releasing leader rows. This gives a
      // standby an immediate takeover path without overlapping Gateway sockets.
      await runtime.shutdown();
      await Promise.all(
        ownedDiscordGateways.map((ownership) =>
          releaseDiscordGatewayLeaseRow(ownership),
        ),
      );
    },
  };
}

export type ChatChannelService = ReturnType<typeof chatChannelService>;
